function send(res, data = {}) {
  res.json({ ok: true, ...data });
}

function normalizeBaseUrl(value, fallback) {
  const raw = String(value || fallback || '').trim().replace(/\/+$/, '');
  return raw || fallback;
}

function envNonNegativeInteger(value, fallback = 0, max = Number.MAX_SAFE_INTEGER) {
  const number = Math.floor(Number(value));
  if (!Number.isFinite(number) || number < 0) return fallback;
  return Math.min(number, max);
}

function envFlagEnabled(value, fallback = false) {
  const text = String(value ?? '').trim().toLowerCase();
  if (!text) return fallback;
  return ['1', 'true', 'yes', 'on', 'enabled'].includes(text);
}

function isLocalServiceUrl(value) {
  try {
    const parsed = new URL(value);
    const host = parsed.hostname.toLowerCase();
    return host === 'localhost' || host === '127.0.0.1' || host === '::1';
  } catch {
    return false;
  }
}

function fail(res, status, error) {
  res.status(status).json({ ok: false, error });
}

function sqliteDirectWriteUnavailableError(label, cause) {
  return Object.assign(new Error(`${label}暂不可用，请稍后重试`), {
    status: 503,
    code: 'sqlite_direct_write_unavailable',
    skipApiErrorLog: true,
    cause
  });
}

function memberStoreReadUnavailableError(store = {}, label = '成员数据读取') {
  const message = store.memberReadError
    ? `${label}暂不可用，请稍后重试：${store.memberReadError}`
    : `${label}暂不可用，请稍后重试`;
  return Object.assign(new Error(message), {
    status: 503,
    code: 'member_store_read_unavailable',
    skipApiErrorLog: true
  });
}

function requireOperationRun(operationRun, label = '操作记录') {
  if (operationRun?.id) return operationRun;
  throw Object.assign(new Error(`${label}暂时无法写入，请稍后重试`), {
    status: 503,
    errorKey: 'operation_run_unavailable',
    skipApiErrorLog: true
  });
}

function operationRunUnavailable(error = null) {
  return error?.errorKey === 'operation_run_unavailable';
}

function usernameIsValid(username) {
  return /^[a-zA-Z0-9_.-]{2,32}$/.test(username);
}

function isRootUser(user) {
  return user?.id === 'user_root' || user?.username === 'root';
}

function isReadonlyViewer(user) {
  return isViewer(user);
}

function canViewOperationalData(user, store = null) {
  if (canViewAllData(user) || isMember(user)) return true;
  if (!store || !user) return false;
  return ['squads', 'server', 'kda', 'history'].some((moduleId) => canViewModuleInStore(store, user, moduleId));
}

function readonlyViewerCanWrite(req) {
  const method = String(req.method || '').toUpperCase();
  if (method === 'GET' || method === 'HEAD' || method === 'OPTIONS') return true;
  const path = String(req.path || '');
  return path === '/auth/logout' ||
    path === '/profile/password' ||
    path === '/query' ||
    path === '/query/export-image' ||
    path === '/integrations/public-query' ||
    path === '/integrations/rustplus/relay';
}

function blockReadonlyViewerWrites(req, res, next) {
  if (isReadonlyViewer(req.user) && !readonlyViewerCanWrite(req)) {
    fail(res, 403, '只读账号只能查看和查询');
    return;
  }
  next();
}

function permissionRolesForStore(store) {
  return normalizePermissionRoles(store?.permissionRoles || []);
}

function publicPermissionModules() {
  return PERMISSION_MODULES.map((module) => ({ ...module }));
}

function permissionRoleUsage(store, code) {
  return (store.users || []).filter((user) => user.role === code).length;
}

function publicPermissionRole(store, role) {
  const customRoles = permissionRolesForStore(store);
  const code = role.code;
  const builtIn = BUILTIN_ROLE_IDS.includes(code);
  const storedRole = customRoles.find((item) => item.code === code);
  const sourceRole = storedRole || role;
  const normalizedRole = builtIn
    ? normalizePermissionRole({
        ...sourceRole,
        code,
        permissions: sourceRole.permissions || rolePermissions(code, customRoles)
      }, {}, nowIso(), { allowBuiltIn: true })
    : normalizePermissionRole(sourceRole, {}, nowIso());
  return {
    ...normalizedRole,
    builtIn,
    system: builtIn,
    locked: false,
    permissions: normalizePermissionMatrix(normalizedRole?.permissions || {}),
    userCount: permissionRoleUsage(store, code),
    canDelete: !builtIn && permissionRoleUsage(store, code) === 0
  };
}

function permissionRolesPayload(store) {
  const customRoles = permissionRolesForStore(store);
  const customRoleCodes = new Set(BUILTIN_ROLE_IDS);
  return [
    ...BUILTIN_ROLE_IDS.map((code) => publicPermissionRole(store, { code })),
    ...customRoles.filter((role) => !customRoleCodes.has(role.code)).map((role) => publicPermissionRole(store, role))
  ];
}

function effectivePermissionsForUser(store, user) {
  if (!user) return normalizePermissionMatrix({});
  return rolePermissions(user.role, permissionRolesForStore(store));
}

function roleDisplayName(store, roleCode) {
  const code = normalizePermissionRoleCode(roleCode) || normalizeText(roleCode, 40);
  const customRole = permissionRolesForStore(store).find((role) => role.code === code);
  return customRole?.name || code;
}

function publicUserWithPermissions(store, user) {
  const base = publicUser(user);
  if (!base) return null;
  return {
    ...base,
    roleLabel: roleDisplayName(store, user.role),
    isRoot: isRootUser(user),
    permissions: effectivePermissionsForUser(store, user)
  };
}

function canViewModuleInStore(store, user, moduleId) {
  return userCanWithStore(store, user, moduleId, 'view');
}

function canEditModuleInStore(store, user, moduleId) {
  return userCanWithStore(store, user, moduleId, 'edit');
}

function userCanWithStore(store, user, moduleId, action = 'view') {
  if (!user) return false;
  if (isRootUser(user)) return true;
  return roleCan(user.role, permissionRolesForStore(store), moduleId, action);
}

function requireModuleView(moduleId) {
  return async (req, res, next) => {
    try {
      if (!req.user) {
        fail(res, 401, '请先登录');
        return;
      }
      if (isRootUser(req.user)) {
        next();
        return;
      }
      const store = await readPermissionCheckStore();
      if (!canViewModuleInStore(store, req.user, moduleId)) {
        fail(res, 403, '无权查看该模块');
        return;
      }
      next();
    } catch (error) {
      next(error);
    }
  };
}

