function roleAssignmentCheck(store, actor, roleCode, targetUser = null) {
  const customRoles = permissionRolesForStore(store);
  const role = normalizeRole(roleCode, customRoles);
  if (!roleExists(role, customRoles)) return { ok: false, error: '角色不存在' };
  if (isAdmin(actor)) return { ok: true, role };
  if (!canEditModuleInStore(store, actor, 'users')) return { ok: false, error: '无权修改账号' };
  if (targetUser?.id && actor?.id === targetUser.id && role !== actor.role) {
    return { ok: false, error: '不能修改自己的角色' };
  }
  if (role === 'admin') return { ok: false, error: '只有管理员可以分配管理员角色' };
  if (roleCan(role, customRoles, 'permissions', 'edit')) {
    return { ok: false, error: '不能分配可修改权限管理的角色' };
  }
  const actorPermissions = effectivePermissionsForUser(store, actor);
  const nextPermissions = rolePermissions(role, customRoles);
  for (const module of PERMISSION_MODULES) {
    const nextCanEdit = permissionAllows(nextPermissions, module.id, 'edit');
    const nextCanView = permissionAllows(nextPermissions, module.id, 'view');
    if (nextCanEdit && !permissionAllows(actorPermissions, module.id, 'edit')) {
      return { ok: false, error: '不能分配高于自身权限的角色' };
    }
    if (nextCanView && !permissionAllows(actorPermissions, module.id, 'view')) {
      return { ok: false, error: '不能分配高于自身权限的角色' };
    }
  }
  return { ok: true, role };
}

function accountManagementCheck(store, actor, targetUser) {
  if (!targetUser) return { ok: false, status: 404, error: '账号不存在' };
  if (isAdmin(actor)) return { ok: true };
  if (targetUser.id === actor?.id) return { ok: false, status: 403, error: '不能通过账号管理修改自己' };
  if (isRootUser(targetUser) || targetUser.role === 'admin') {
    return { ok: false, status: 403, error: '不能管理管理员账号' };
  }
  if (roleCan(targetUser.role, permissionRolesForStore(store), 'permissions', 'edit')) {
    return { ok: false, status: 403, error: '不能管理可修改权限的账号' };
  }
  return { ok: true };
}

function rolePermissionChangeCheck(store, actor, permissions = {}) {
  if (isAdmin(actor)) return { ok: true };
  const actorPermissions = effectivePermissionsForUser(store, actor);
  const nextPermissions = normalizePermissionMatrix(permissions);
  for (const module of PERMISSION_MODULES) {
    const nextCanEdit = permissionAllows(nextPermissions, module.id, 'edit');
    const nextCanView = permissionAllows(nextPermissions, module.id, 'view');
    if (nextCanEdit && !permissionAllows(actorPermissions, module.id, 'edit')) {
      return { ok: false, error: '不能创建或修改高于自身权限的角色' };
    }
    if (nextCanView && !permissionAllows(actorPermissions, module.id, 'view')) {
      return { ok: false, error: '不能创建或修改高于自身权限的角色' };
    }
  }
  return { ok: true };
}

function passwordIsValid(password) {
  return typeof password === 'string' && password.length >= 8 && password.length <= 128;
}

function requestOrigin(req) {
  const configured = normalizeBaseUrl(process.env.NB_PUBLIC_BASE_URL, '');
  if (configured) return configured;
  const proto = normalizeText(req.headers['x-forwarded-proto'], 20) || req.protocol || 'http';
  const host = normalizeText(req.get('host'), 200) || '127.0.0.1:8787';
  return `${proto}://${host}`;
}

function steamOpenIdReturnUrl(req) {
  const params = new URLSearchParams();
  const language = authLanguageFromRequest(req);
  if (language) params.set('lang', language);
  const suffix = params.toString();
  return `${requestOrigin(req)}/api/auth/steam/callback${suffix ? `?${suffix}` : ''}`;
}

const THIRD_PARTY_AUTH_LANGUAGES = ['zh', 'en', 'ru', 'tr', 'th', 'ko'];
const THIRD_PARTY_AUTH_STATE_TTL_MS = 10 * 60 * 1000;

function authLanguageFromValue(value = '') {
  const normalized = normalizeText(value, 40).toLowerCase().replace('_', '-');
  if (!normalized) return '';
  if (normalized.startsWith('zh')) return 'zh';
  const base = normalized.split('-')[0];
  return THIRD_PARTY_AUTH_LANGUAGES.includes(base) ? base : '';
}

function authLanguageFromRequest(req) {
  const queryLanguage = authLanguageFromValue(req.query?.lang || req.query?.authLang || '');
  if (queryLanguage) return queryLanguage;
  const accepted = String(req.headers['accept-language'] || '')
    .split(',')
    .map((part) => part.split(';')[0])
    .map(authLanguageFromValue)
    .find(Boolean);
  return accepted || 'en';
}

function authErrorRedirectUrl(req, errorKey, language = authLanguageFromRequest(req)) {
  const params = new URLSearchParams({
    login: '1',
    authError: errorKey,
    authLang: language || 'en'
  });
  return `${requestOrigin(req)}/?${params}`;
}

function redirectAuthError(req, res, errorKey, language = authLanguageFromRequest(req)) {
  res.redirect(authErrorRedirectUrl(req, errorKey, language));
}

async function signThirdPartyAuthState(payload = {}) {
  const body = Buffer.from(JSON.stringify({
    ...payload,
    exp: Date.now() + THIRD_PARTY_AUTH_STATE_TTL_MS,
    nonce: crypto.randomBytes(12).toString('base64url')
  })).toString('base64url');
  const secret = await getSessionSecret();
  const signature = crypto.createHmac('sha256', secret).update(body).digest('base64url');
  return `${body}.${signature}`;
}

async function verifyThirdPartyAuthState(value = '') {
  const [body, signature] = String(value || '').split('.');
  if (!body || !signature) return null;
  const secret = await getSessionSecret();
  const expected = crypto.createHmac('sha256', secret).update(body).digest('base64url');
  if (signature.length !== expected.length) return null;
  if (!crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) return null;
  try {
    const payload = JSON.parse(Buffer.from(body, 'base64url').toString('utf8'));
    if (!payload?.exp || Number(payload.exp) < Date.now()) return null;
    return payload;
  } catch {
    return null;
  }
}

function discordOAuthClientId(store = null) {
  return normalizeText(
    process.env.NB_DISCORD_OAUTH_CLIENT_ID ||
      process.env.DISCORD_CLIENT_ID ||
      store?.settings?.discord?.applicationId ||
      '',
    80
  );
}

function discordOAuthClientSecret() {
  return normalizeText(process.env.NB_DISCORD_OAUTH_CLIENT_SECRET || process.env.DISCORD_CLIENT_SECRET || '', 240);
}

function discordOAuthRedirectUri(req) {
  return normalizeText(process.env.NB_DISCORD_OAUTH_REDIRECT_URI || process.env.DISCORD_REDIRECT_URI || '', 300) ||
    `${requestOrigin(req)}/api/auth/discord/callback`;
}

function discordOAuthConfigured(store = null) {
  return Boolean(discordOAuthClientId(store) && discordOAuthClientSecret());
}

function publicThirdPartyLoginSettings(store, actor = null) {
  const settings = store.settings?.thirdPartyLogin || {};
  const steam = settings.steam || {};
  const discordConfigured = discordOAuthConfigured(store);
  return {
    steam: {
      enabled: steam.enabled !== false,
      startUrl: '/api/auth/steam/start',
      callbackUrl: '/api/auth/steam/callback',
      updatedAt: steam.updatedAt || ''
    },
    discord: {
      enabled: Boolean(settings.discord?.enabled) && discordConfigured,
      configured: discordConfigured,
      status: discordConfigured ? 'active' : 'not_configured',
      startUrl: '/api/auth/discord/start',
      callbackUrl: '/api/auth/discord/callback',
      updatedAt: settings.discord?.updatedAt || ''
    },
    kook: {
      defaultRole: settings.kook?.defaultRole || 'member',
      ...(actor ? { roleOptions: permissionRolesPayload(store).filter((role) => roleAssignmentCheck(store, actor, role.code).ok).map(({ code, name }) => ({ code, name })) } : {}),
      enabled: kookOAuthEnabled(store) && kookOAuthConfigured(),
      configured: kookOAuthConfigured(),
      startUrl: '/api/auth/kook/start',
      callbackUrl: '/api/auth/kook/callback',
      updatedAt: settings.kook?.updatedAt || ''
    },
    wechat: {
      enabled: Boolean(settings.wechat?.enabled),
      status: 'planned',
      updatedAt: settings.wechat?.updatedAt || ''
    }
  };
}

function normalizeThirdPartyLoginSettingsInput(body = {}, existing = {}, store = {}, actor = null) {
  const defaultRole = body?.kook?.defaultRole ?? existing?.kook?.defaultRole ?? 'member';
  if (defaultRole !== (existing?.kook?.defaultRole || 'member')) {
    if (typeof defaultRole !== 'string' || !permissionRolesPayload(store).some((role) => role.code === defaultRole)) {
      throw Object.assign(new Error('角色不存在'), { status: 400 });
    }
    const check = roleAssignmentCheck(store, actor, defaultRole);
    if (!check.ok) throw Object.assign(new Error(check.error), { status: 403 });
  }
  const now = nowIso();
  return {
    steam: {
      enabled: body?.steam?.enabled ?? existing?.steam?.enabled ?? true,
      updatedAt: now
    },
    discord: {
      enabled: Boolean(body?.discord?.enabled ?? existing?.discord?.enabled),
      updatedAt: now
    },
    kook: {
      defaultRole,
      enabled: Boolean(body?.kook?.enabled ?? existing?.kook?.enabled ?? (process.env.NB_KOOK_OAUTH_ENABLED === '1')),
      updatedAt: now
    },
    wechat: {
      enabled: Boolean(body?.wechat?.enabled ?? existing?.wechat?.enabled),
      updatedAt: existing?.wechat?.updatedAt || ''
    }
  };
}

function steamIdFromOpenIdClaimedId(value = '') {
  const match = String(value || '').match(/^https?:\/\/steamcommunity\.com\/openid\/id\/(\d{17})\/?$/);
  return match?.[1] || '';
}

async function verifySteamOpenIdCallback(req) {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(req.query || {})) {
    if (!key.startsWith('openid.')) continue;
    params.set(key, String(value || ''));
  }
  params.set('openid.mode', 'check_authentication');
  const response = await nodeFetch(STEAM_OPENID_PROVIDER_URL, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: params.toString()
  });
  const text = await response.text();
  return /is_valid\s*:\s*true/i.test(text);
}

function steamLoginUsernameForId(steamId, store) {
  const suffix = steamId.slice(-8);
  const base = `steam_${suffix}`;
  if (!store.users.some((user) => user.username.toLowerCase() === base.toLowerCase())) return base;
  for (let index = 2; index < 1000; index += 1) {
    const username = `${base}_${index}`;
    if (!store.users.some((user) => user.username.toLowerCase() === username.toLowerCase())) return username;
  }
  return `steam_${suffix}_${crypto.randomBytes(3).toString('hex')}`;
}

function thirdPartyLoginUsernameForId(provider, id, store) {
  if (provider === 'steam') return steamLoginUsernameForId(id, store);
  const suffix = String(id || '').slice(-8) || crypto.randomBytes(4).toString('hex');
  const base = `${provider}_${suffix}`;
  if (!store.users.some((user) => user.username.toLowerCase() === base.toLowerCase())) return base;
  for (let index = 2; index < 1000; index += 1) {
    const username = `${base}_${index}`;
    if (!store.users.some((user) => user.username.toLowerCase() === username.toLowerCase())) return username;
  }
  return `${base}_${crypto.randomBytes(3).toString('hex')}`;
}

function thirdPartyLoginRoleRank(user = {}) {
  if (isAdmin(user)) return 500;
  if (user.role === 'member_manager') return 400;
  if (isLeader(user)) return 300;
  if (isMember(user)) return 100;
  if (isViewer(user)) return 0;
  return 250;
}

function thirdPartyLoginUserRank(user = {}, provider = '') {
  let rank = thirdPartyLoginRoleRank(user);
  if (user.loginProviders?.[provider]) rank += 20;
  if (user.createdBy === `${provider}_login`) rank += 10;
  return rank;
}

function existingLoginUserForMember(store, member, provider) {
  const steamId = normalizeText(member?.steamId, 80);
  if (!steamId) return null;
  const candidates = (store.users || []).filter((user) => normalizeText(user.boundSteamId, 80) === steamId);
  return candidates
    .toSorted((left, right) => {
      const rankDelta = thirdPartyLoginUserRank(right, provider) - thirdPartyLoginUserRank(left, provider);
      if (rankDelta) return rankDelta;
      return timestampForSort(right.updatedAt || right.createdAt) - timestampForSort(left.updatedAt || left.createdAt);
    })[0] || null;
}

function upsertThirdPartyMemberLogin(store, req, { provider, member, identity = {}, profile = {}, passwordHash = '' }) {
  if (member?.roleAccessLock) {
    throw Object.assign(new Error('你已离队，请联系管理获取语音频道角色'), { status: 403, errorKey: 'memberDeparted' });
  }
  const now = nowIso();
  let user = existingLoginUserForMember(store, member, provider);
  if (user?.roleAccessLock) {
    throw Object.assign(new Error('你已离队，请联系管理获取语音频道角色'), { status: 403, errorKey: 'memberDeparted' });
  }
  if (!user) {
    if (!passwordHash) {
      throw Object.assign(new Error('登录账号初始化失败'), { status: 500, errorKey: 'thirdPartyLoginVerifyFailed' });
    }
    user = {
      id: createId('user'),
      username: thirdPartyLoginUsernameForId(provider, identity.id || member.steamId, store),
      role: provider === 'kook' && roleExists(store.settings?.thirdPartyLogin?.kook?.defaultRole, permissionRolesForStore(store))
        ? store.settings.thirdPartyLogin.kook.defaultRole : 'member',
      passwordHash,
      boundSteamId: member.steamId,
      steamNickname: member.steamNickname || '',
      steamAvatar: member.avatar || '',
      loginProviders: {},
      createdAt: now,
      updatedAt: now,
      createdBy: `${provider}_login`
    };
    store.users.push(user);
    appendLog(store, req, `${provider}_login_user_create`, `${provider} 登录创建成员账号 ${user.username}`, {
      targetId: user.id,
      steamId: member.steamId,
      metadata: { memberId: member.id }
    });
  }

  user.loginProviders ||= {};
  user.loginProviders[provider] = {
    ...(user.loginProviders[provider] || {}),
    ...identity,
    linkedAt: user.loginProviders[provider]?.linkedAt || now,
    lastLoginAt: now
  };
  if (provider === 'steam') {
    user.steamNickname = profile.nickname || user.steamNickname || member.steamNickname || '';
    user.steamAvatar = profile.avatar || user.steamAvatar || member.avatar || '';
    member.steamNickname = profile.nickname || member.steamNickname || '';
    member.avatar = profile.avatar || member.avatar || '';
  }
  if (provider === 'discord') {
    member.discordName = profile.username || member.discordName || '';
    member.discordAvatarHash = profile.avatarHash || member.discordAvatarHash || '';
    member.discordAvatarUrl = profile.avatarUrl || member.discordAvatarUrl || '';
  }
  user.updatedAt = now;
  member.updatedAt = now;
  ensureAccountMember(store, user, {
    ensureSquad: false,
    rawInput: member.rawInput || member.steamId,
    avatar: member.avatar || user.steamAvatar || ''
  });
  appendLog(store, req, `${provider}_login`, `${provider} 登录 ${user.username}`, {
    targetId: user.id,
    steamId: member.steamId,
    metadata: { memberId: member.id, providerUserId: identity.id || '' }
  });
  return user;
}

function blockMemberRoleManagement(req, res) {
  if (!isMember(req.user)) return false;
  fail(res, 403, '成员角色只能修改自己的信息');
  return true;
}

