function wechatApplicationStatus(record = {}) {
  const explicitStatus = normalizeText(record?.status, 40);
  if (explicitStatus) return explicitStatus;
  if (record?.reviewedAt || record?.reviewedByUserId || record?.reviewNote || record?.adminNote) return 'closed';
  return 'pending';
}

function isWechatApplicationActive(record = {}) {
  return WECHAT_APPLICATION_ACTIVE_STATUSES.has(wechatApplicationStatus(record));
}

