async function exchangeDiscordOAuthCode(req, store, code, redirectUri) {
  const clientId = discordOAuthClientId(store);
  const clientSecret = discordOAuthClientSecret();
  if (!clientId || !clientSecret) {
    throw Object.assign(new Error('Discord OAuth 未配置'), { status: 500, errorKey: 'discordLoginNotConfigured' });
  }
  const body = new URLSearchParams({
    client_id: clientId,
    client_secret: clientSecret,
    grant_type: 'authorization_code',
    code,
    redirect_uri: redirectUri
  });
  const result = await discordApiRequest('/oauth2/token', {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    rawBody: body.toString(),
    scope: 'oauth_token',
    retry: false
  });
  const { response, payload } = result;
  if (!result.ok || !payload?.access_token) {
    throw Object.assign(new Error(payload?.error_description || payload?.error || 'Discord OAuth 验证失败'), {
      status: response.status || 502,
      errorKey: 'thirdPartyLoginVerifyFailed'
    });
  }
  return payload;
}

async function fetchDiscordOAuthUser(accessToken) {
  const result = await discordApiRequest('/users/@me', {
    bearerToken: accessToken,
    scope: 'oauth_user',
    retry: false
  });
  const { response, payload } = result;
  if (!result.ok || !payload?.id) {
    throw Object.assign(new Error(payload?.message || 'Discord 用户信息读取失败'), {
      status: response.status || 502,
      errorKey: 'thirdPartyLoginVerifyFailed'
    });
  }
  return payload;
}

function discordOAuthUserProfile(user = {}) {
  const id = normalizeText(user.id, DISCORD_ID_MAX_LENGTH);
  const avatarHash = normalizeText(user.avatar, 160);
  const username = normalizeText(user.global_name || user.username, 120);
  return {
    id,
    username,
    avatarHash,
    avatarUrl: avatarHash ? discordUserAvatarUrl(id, avatarHash) : discordDefaultAvatarUrl(id)
  };
}
