const WIPE_SERVER_PRESETS = [...VITAL_RUST_2X_SERVERS, ...ATLAS_2X_SERVER_PRESETS];

function wipeServerPresetById(serverPresetId = '') {
  const normalizedId = normalizeText(serverPresetId, 80);
  return WIPE_SERVER_PRESETS.find((server) => server.id === normalizedId) || null;
}

function wipeServerPresetFromInput(source = {}) {
  return wipeServerPresetById(source?.serverPresetId) ||
    wipeServerPresetById(source?.vitalServerId) ||
    VITAL_RUST_2X_SERVERS.find((server) => server.vitalServerId === normalizeText(source?.vitalServerId, 80)) ||
    null;
}

const VITAL_SERVER_STATUSES = new Set(['active', 'maintenance', 'hidden']);
const VITAL_SERVER_STATUS_LABELS = {
  active: '正常',
  maintenance: '维护',
  hidden: '隐藏'
};

function normalizeVitalServerStatus(value) {
  const normalized = normalizeText(value, 40).toLowerCase();
  return VITAL_SERVER_STATUSES.has(normalized) ? normalized : '';
}

function vitalServerStatusLabel(status) {
  const normalized = normalizeVitalServerStatus(status) || 'active';
  return VITAL_SERVER_STATUS_LABELS[normalized] || normalized;
}

function normalizeVitalServerOverride(raw = {}) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const vitalServerId = normalizeText(source.vitalServerId || source.id, 80);
  if (!vitalServerId) return null;
  const override = { vitalServerId };
  if (Object.hasOwn(source, 'name')) override.name = normalizeText(source.name, 120);
  if (Object.hasOwn(source, 'directConnect')) override.directConnect = normalizeText(source.directConnect, 240);
  if (Object.hasOwn(source, 'vipUrl')) override.vipUrl = normalizeText(source.vipUrl, 500);
  if (Object.hasOwn(source, 'mapLink')) override.mapLink = normalizeText(source.mapLink, 500);
  if (Object.hasOwn(source, 'rustMapsLink')) override.rustMapsLink = normalizeText(source.rustMapsLink, 500);
  if (Object.hasOwn(source, 'notes')) override.notes = normalizeText(source.notes, 1000);
  if (Object.hasOwn(source, 'status')) {
    override.status = normalizeVitalServerStatus(source.status) || 'active';
  }
  if (Object.hasOwn(source, 'updatedAt')) override.updatedAt = normalizeText(source.updatedAt, 80);
  return override;
}

function vitalServerSettings(store) {
  store.settings ||= {};
  store.settings.vitalServers ||= {};
  const validIds = new Set(VITAL_RUST_2X_SERVERS.map((server) => server.vitalServerId));
  const rawOverrides = Array.isArray(store.settings.vitalServers.overrides)
    ? store.settings.vitalServers.overrides
    : [];
  const overrides = [];
  const seen = new Set();
  for (const raw of rawOverrides) {
    const override = normalizeVitalServerOverride(raw);
    if (!override || !validIds.has(override.vitalServerId) || seen.has(override.vitalServerId)) continue;
    seen.add(override.vitalServerId);
    overrides.push(override);
  }
  store.settings.vitalServers.overrides = overrides;
  return store.settings.vitalServers;
}

function vitalServerOverridesById(store) {
  return new Map(vitalServerSettings(store).overrides.map((override) => [override.vitalServerId, override]));
}

function applyVitalServerOverride(server, override = null) {
  const status = normalizeVitalServerStatus(override?.status) || normalizeVitalServerStatus(server.status) || 'active';
  return {
    ...server,
    baseName: server.name,
    name: override && Object.hasOwn(override, 'name') && override.name ? override.name : server.name,
    directConnect: override && Object.hasOwn(override, 'directConnect') ? override.directConnect : (server.directConnect || ''),
    vipUrl: override && Object.hasOwn(override, 'vipUrl') ? override.vipUrl : (server.vipUrl || ''),
    mapLink: override && Object.hasOwn(override, 'mapLink') ? override.mapLink : (server.mapLink || ''),
    rustMapsLink: override && Object.hasOwn(override, 'rustMapsLink') ? override.rustMapsLink : (server.rustMapsLink || ''),
    status,
    statusLabel: vitalServerStatusLabel(status),
    notes: override && Object.hasOwn(override, 'notes') ? override.notes : '',
    overrideUpdatedAt: override?.updatedAt || ''
  };
}

function vitalServerFromCatalog(server, catalog = []) {
  const official = (Array.isArray(catalog) ? catalog : [])
    .find((entry) => entry.id === server.vitalServerId);
  if (!official?.connectionHost || !official.connectionPort) return server;
  return {
    ...server,
    directConnect: `client.connect ${official.connectionHost}:${official.connectionPort}`
  };
}

function vitalServersForStore(store, catalog = []) {
  const overridesById = vitalServerOverridesById(store);
  return VITAL_RUST_2X_SERVERS.map((server) => (
    applyVitalServerOverride(
      vitalServerFromCatalog(server, catalog),
      overridesById.get(server.vitalServerId) || null
    )
  ));
}

function wipeServerPresetsForStore(store, vitalCatalog = []) {
  return [
    ...vitalServersForStore(store, vitalCatalog).filter((server) => server.status !== 'hidden'),
    ...ATLAS_2X_SERVER_PRESETS
  ];
}

function normalizeParticipantStatus(status) {
  const normalized = (normalizeText(status, 40) || 'on_time').toLowerCase();
  const canonical = LEGACY_PARTICIPANT_STATUS[normalized] || normalized;
  return PARTICIPANT_STATUSES.has(canonical) ? canonical : canonical;
}

function isParticipantAvailable(status) {
  return PARTICIPANT_AVAILABLE_STATUSES.has(normalizeParticipantStatus(status));
}

function normalizeDiscordAttendanceAction(action) {
  const normalized = normalizeText(action, 40).toLowerCase();
  if (!normalized) return '';
  const canonical = DISCORD_ATTENDANCE_ACTION_ALIASES[normalized] || normalizeParticipantStatus(normalized);
  return PARTICIPANT_STATUSES.has(canonical) ? canonical : '';
}

function legacyWechatAttendanceStatus(status) {
  const normalized = normalizeParticipantStatus(status);
  if (normalized === 'join_8h' || normalized === 'join_16h') return 'late';
  if (normalized === 'not_attending') return 'skip';
  return 'on_time';
}

function wechatAttendanceModelFromRequest(req = {}) {
  const headerValue = normalizeText(req.get?.(WECHAT_WIPE_ATTENDANCE_MODEL_HEADER), 20).toLowerCase();
  const queryValue = normalizeText(req.query?.attendanceModel, 20).toLowerCase();
  const bodyValue = normalizeText(req.body?.attendanceModel, 20).toLowerCase();
  return [headerValue, queryValue, bodyValue].includes(WECHAT_WIPE_ATTENDANCE_MODEL_V2) ? 'v2' : 'legacy';
}

function publicWechatAttendanceStatus(status, attendanceModel = 'v2') {
  const canonical = normalizeParticipantStatus(status);
  return attendanceModel === 'legacy' ? legacyWechatAttendanceStatus(canonical) : canonical;
}

function attendanceStatusText(status, { language = 'zh', context = 'wechat' } = {}) {
  const normalized = normalizeParticipantStatus(status);
  if (context === 'discord') {
    if (normalized === 'join_8h') return 'Join in 8h';
    if (normalized === 'join_16h') return 'Join in 16h';
    if (normalized === 'not_attending') return 'Not Attending';
    return 'Attending';
  }
  if (language === 'en') {
    if (normalized === 'join_8h') return 'Join in 8h';
    if (normalized === 'join_16h') return 'Join in 16h';
    if (normalized === 'not_attending') return 'Not Attending';
    return 'Attending';
  }
  if (normalized === 'join_8h') return '早上来';
  if (normalized === 'join_16h') return '晚上来';
  if (normalized === 'not_attending') return '有事不来';
  return '准时开荒';
}

function normalizeWechatWipeSignupStatus(status) {
  const raw = normalizeText(status, 40);
  if (!raw) return '';
  const normalized = normalizeParticipantStatus(raw);
  return WECHAT_WIPE_SIGNUP_STATUSES.has(normalized) ? normalized : '';
}

function normalizeMemberSpecialty(value) {
  return normalizeSharedMemberSpecialties([normalizeText(value, 40)])[0] || '';
}

function normalizeMemberSpecialties(value) {
  return normalizeSharedMemberSpecialties(value);
}

function memberSpecialtyOptionsPayload() {
  return [...MEMBER_SPECIALTIES].map((value) => ({
    value,
    label: MEMBER_SPECIALTY_LABELS_ZH[value] || value
  }));
}

function buildKdaUrl(vitalServerId, vitalWipeId) {
  const normalizedServerId = normalizeText(vitalServerId, 80);
  const normalizedWipeId = normalizeText(vitalWipeId, 120);
  if (!normalizedServerId || !normalizedWipeId) return '';
  const externalParams = new URLSearchParams({
    tab: 'vital',
    vitalServerId: normalizedServerId,
    vitalWipeId: normalizedWipeId
  });
  if (RUST_KDA_PUBLIC_BASE_URL) return `${RUST_KDA_PUBLIC_BASE_URL}/?${externalParams}`;
  const internalParams = new URLSearchParams({
    view: 'dataLookup',
    tab: 'vital',
    vitalServerId: normalizedServerId,
    vitalWipeId: normalizedWipeId
  });
  const publicBaseUrl = normalizeBaseUrl(process.env.NB_PUBLIC_BASE_URL, '');
  return `${publicBaseUrl}/?${internalParams}`;
}

const KDA_PROVIDERS = new Set(['vital', 'manual', 'none']);

function wipeKdaProvider(wipe = {}) {
  const explicit = normalizeText(wipe?.kdaProvider, 40).toLowerCase();
  if (KDA_PROVIDERS.has(explicit)) return explicit;
  if (normalizeText(wipe?.vitalServerId, 80)) return 'vital';
  return 'manual';
}

function wipeKdaCapability(wipe = {}) {
  const kdaProvider = wipeKdaProvider(wipe);
  const vitalServerId = normalizeText(wipe?.vitalServerId, 80);
  const vitalWipeId = normalizeText(wipe?.vitalWipeId, 120);
  let kdaSyncUnavailableReason = '';
  let kdaSyncMessage = '';

  if (kdaProvider === 'none') {
    kdaSyncUnavailableReason = 'kda_disabled';
    kdaSyncMessage = '该档期未启用 KDA 数据源，可在后台手动导入 KDA 数据。';
  } else if (kdaProvider === 'manual') {
    kdaSyncUnavailableReason = 'manual_provider';
    kdaSyncMessage = '该服务器暂不支持自动 KDA，可在后台手动导入 KDA 数据。';
  } else if (!vitalServerId) {
    kdaSyncUnavailableReason = 'missing_vital_server_id';
    kdaSyncMessage = '该档期缺少 Vital Server ID，无法自动同步 KDA，可补充 Vital 信息或手动导入 KDA 数据。';
  } else if (!vitalWipeId) {
    kdaSyncUnavailableReason = 'missing_vital_wipe_id';
    kdaSyncMessage = '等待 Vital 生成 Wipe ID，暂时无法自动同步 KDA，可稍后重试或手动导入 KDA 数据。';
  }

  return {
    kdaProvider,
    kdaSyncAvailable: kdaProvider === 'vital' && !kdaSyncUnavailableReason,
    kdaSyncUnavailableReason,
    kdaSyncMessage
  };
}

function kdaSyncUnavailableCounts(wipe, requested = 0, source = 'manual') {
  const capability = wipeKdaCapability(wipe);
  const reason = capability.kdaSyncUnavailableReason || 'kda_sync_unavailable';
  const message = capability.kdaSyncMessage || '当前档期暂不支持自动 KDA，可手动导入 KDA 数据。';
  return {
    imported: 0,
    ignored: 0,
    requested,
    completed: requested,
    failed: 0,
    source,
    kdaSyncSkipped: true,
    ...capability,
    kdaSyncUnavailableReason: reason,
    kdaSyncMessage: message,
    details: {
      kdaSync: {
        skipped: true,
        reason,
        message,
        provider: capability.kdaProvider
      }
    }
  };
}

function publicWipeKdaCapability(wipe = {}) {
  return wipeKdaCapability(wipe);
}

function expandVitalRustName(value) {
  return String(value || '').replace(/\bVT\b/g, 'Vital Rust');
}

async function fetchVitalWipesResult(vitalServerId, options = {}) {
  if (process.env.NB_DISABLE_EXTERNAL_VITAL === '1') return { ok: false, rows: [], disabled: true };
  const scope = `server:${normalizeText(vitalServerId, 40) || 'unknown'}`;
  try {
    assertExternalProviderAvailable('vital_wipes', scope);
    const wipes = await fetchVitalServerWipes(vitalServerId, options);
    recordExternalProviderSuccess('vital_wipes', scope);
    return { ok: true, rows: wipes, fetchedAt: nowIso() };
  } catch (error) {
    if (!error?.circuitOpen) recordExternalProviderFailure('vital_wipes', error, scope);
    return { ok: false, rows: [], error, fetchedAt: nowIso() };
  }
}

async function fetchVitalWipes(vitalServerId, options = {}) {
  return (await fetchVitalWipesResult(vitalServerId, options)).rows;
}

