function vitalWipeOption(server, wipe, type, fallbackStartedAt = '') {
  if (type === 'all') {
    return {
      id: 'all',
      label: 'All Wipes',
      type,
      startedAt: '',
      endedAt: '',
      vitalServerId: server.vitalServerId,
      vitalWipeId: '',
      kdaUrl: '',
      mapLink: '',
      rustMapsLink: '',
      mapSize: '',
      protocol: ''
    };
  }
  if (!wipe && !fallbackStartedAt) return null;
  const startedAt = wipe?.startTime || fallbackStartedAt;
  const endedAt = wipe?.endTime || '';
  const vitalWipeId = wipe?.id || '';
  const labelPrefix = type === 'next' ? 'Next' : (type === 'current' ? 'Current' : 'Wipe');
  const labelStart = startedAt ? startedAt.slice(0, 10) : '';
  const labelEnd = endedAt ? endedAt.slice(0, 10) : '';
  const labelRange = [labelStart, labelEnd].filter(Boolean).join(' - ');
  return {
    id: wipe?.id || type,
    label: `${labelPrefix}${labelRange ? ` · ${labelRange}` : ''}`,
    type,
    startedAt,
    endedAt,
    vitalServerId: server.vitalServerId,
    vitalWipeId,
    kdaUrl: buildKdaUrl(server.vitalServerId, vitalWipeId),
    mapLink: wipe?.mapUrl || (type === 'current' ? server.mapLink || '' : ''),
    rustMapsLink: type === 'current' ? server.rustMapsLink || '' : '',
    mapSize: wipe?.mapSize || '',
    protocol: wipe?.protocol || ''
  };
}

const SCHEDULED_WIPE_ACTIVATION_TOLERANCE_MS = 30 * 60 * 1000;

function activeVitalWipeRepresentsScheduledCurrent(activeWipe, scheduledCurrentAt) {
  const remoteStartMs = Date.parse(activeWipe?.startTime || '');
  const scheduledStartMs = Date.parse(scheduledCurrentAt || '');
  return Number.isFinite(remoteStartMs) && Number.isFinite(scheduledStartMs)
    && remoteStartMs + SCHEDULED_WIPE_ACTIVATION_TOLERANCE_MS >= scheduledStartMs;
}

function normalizeVitalWipes(wipes = [], { serverId = '', now = new Date() } = {}) {
  const nowMs = now instanceof Date ? now.getTime() : Date.parse(now);
  if (!Number.isFinite(nowMs)) throw new TypeError('Invalid Vital Wipe normalization time');
  const normalizedServerId = normalizeText(serverId, 80);
  const validRows = [];
  for (const source of Array.isArray(wipes) ? wipes : []) {
    const id = normalizeText(source?.id, 120);
    const startMs = Date.parse(source?.startTime || '');
    const hasEnd = Boolean(source?.endTime);
    const endMs = hasEnd ? Date.parse(source.endTime) : null;
    const rowServerId = normalizeText(source?.gameServerId, 80);
    if (!id || !Number.isFinite(startMs) || startMs > nowMs) continue;
    if (normalizedServerId && rowServerId && rowServerId !== normalizedServerId) continue;
    if (hasEnd && (!Number.isFinite(endMs) || endMs < startMs || endMs > nowMs)) continue;
    validRows.push({ source, id, startMs, hasEnd });
  }
  validRows.sort((left, right) => right.startMs - left.startMs);

  const seenIds = new Set();
  let activeAccepted = false;
  const normalized = [];
  for (const row of validRows) {
    if (seenIds.has(row.id)) continue;
    seenIds.add(row.id);
    if (!row.hasEnd) {
      if (activeAccepted) continue;
      activeAccepted = true;
    }
    normalized.push(row.source);
  }
  return normalized;
}

function publicVitalServer(server, wipes = [], now = new Date()) {
  const times = computedWipeTimes(server, now);
  const remoteWipes = normalizeVitalWipes(wipes, { serverId: server.vitalServerId, now });
  const activeWipe = remoteWipes.find((wipe) => !wipe.endTime) || null;
  const allOption = vitalWipeOption(server, null, 'all');
  const remoteOptions = remoteWipes.map((wipe) => (
    vitalWipeOption(server, wipe, wipe.endTime ? 'archived' : 'current', times.currentStart)
  ));
  const currentWipeAt = activeVitalWipeRepresentsScheduledCurrent(activeWipe, times.currentStart)
    ? activeWipe.startTime
    : times.currentStart;
  return {
    id: server.id,
    serverPresetId: server.id,
    name: expandVitalRustName(server.name),
    provider: 'vital',
    serverVipProvider: 'vital',
    kdaProvider: 'vital',
    vitalServerId: server.vitalServerId,
    battlemetricsId: server.battlemetricsId,
    baseName: server.baseName || server.name,
    status: normalizeVitalServerStatus(server.status) || 'active',
    statusLabel: vitalServerStatusLabel(server.status),
    directConnect: server.directConnect || '',
    vipUrl: server.vipUrl || '',
    mapLink: server.mapLink || '',
    rustMapsLink: server.rustMapsLink || '',
    notes: server.notes || '',
    overrideUpdatedAt: server.overrideUpdatedAt || '',
    nextWipeAt: times.nextStart,
    currentWipeAt,
    remoteAvailable: remoteWipes.length > 0,
    wipes: remoteOptions,
    wipeOptions: [allOption, ...remoteOptions].filter(Boolean)
  };
}

function publicConfiguredWipeServer(server, now = new Date(), officialServer = null) {
  const times = computedWipeTimes(server, now);
  const officialNextMs = Date.parse(officialServer?.nextWipeAt || '');
  const currentMs = now instanceof Date ? now.getTime() : Date.parse(now);
  const officialNextWipeAt = Number.isFinite(officialNextMs) && officialNextMs > currentMs
    ? new Date(officialNextMs).toISOString()
    : '';
  const nextWipeAt = officialNextWipeAt || times.nextStart;
  const officialCurrentMs = Date.parse(officialServer?.currentWipeAt || '');
  const scheduledCurrentMs = Date.parse(times.currentStart || '');
  const officialCurrentWipeAt = Number.isFinite(officialCurrentMs)
    && officialCurrentMs <= currentMs
    && officialCurrentMs >= currentMs - 180 * 24 * 60 * 60 * 1000
    && (!Number.isFinite(scheduledCurrentMs)
      || officialCurrentMs + SCHEDULED_WIPE_ACTIVATION_TOLERANCE_MS >= scheduledCurrentMs)
    ? new Date(officialCurrentMs).toISOString()
    : '';
  const currentWipeAt = officialCurrentWipeAt || times.currentStart;
  const currentOption = {
    id: 'current',
    label: `Current${currentWipeAt ? ` · ${currentWipeAt.slice(0, 10)}` : ''}`,
    type: 'current',
    startedAt: currentWipeAt,
    endedAt: '',
    vitalServerId: '',
    vitalWipeId: '',
    kdaUrl: '',
    mapLink: server.mapLink || '',
    rustMapsLink: server.rustMapsLink || '',
    mapSize: '',
    protocol: ''
  };
  const nextOption = vitalWipeOption(server, null, 'next', nextWipeAt);
  return {
    id: server.id,
    serverPresetId: server.id,
    name: server.name,
    provider: server.provider || '',
    serverVipProvider: server.serverVipProvider || server.provider || '',
    kdaProvider: server.kdaProvider || 'manual',
    vitalServerId: '',
    battlemetricsId: server.battlemetricsId || '',
    baseName: server.name,
    status: 'active',
    statusLabel: vitalServerStatusLabel('active'),
    directConnect: server.directConnect || '',
    vipUrl: server.vipUrl || '',
    mapLink: server.mapLink || '',
    rustMapsLink: server.rustMapsLink || '',
    notes: '',
    overrideUpdatedAt: '',
    nextWipeAt,
    nextWipeSource: officialNextWipeAt ? 'atlas_official' : 'schedule_fallback',
    scheduleNextWipeAt: times.nextStart,
    currentWipeAt,
    currentWipeSource: officialCurrentWipeAt ? 'atlas_a2s' : 'schedule_fallback',
    currentWipeObservedAt: officialCurrentWipeAt ? officialServer?.observedAt || '' : '',
    scheduleCurrentWipeAt: times.currentStart,
    remoteAvailable: false,
    wipes: [currentOption],
    wipeOptions: [currentOption, nextOption].filter(Boolean)
  };
}

function publicWipeServerPreset(server, wipes = [], now = new Date(), officialServer = null) {
  if (server?.provider === 'atlas') {
    return {
      ...publicConfiguredWipeServer(server, now, officialServer),
      defaultWipeMode: 'next'
    };
  }
  const payload = publicVitalServer(server, wipes, now);
  const scheduledCurrentAt = computedWipeTimes(server, now).currentStart;
  const activeRemoteOption = payload.wipes.find((option) => option.type === 'current') || null;
  const currentOption = activeVitalWipeRepresentsScheduledCurrent(
    activeRemoteOption ? { startTime: activeRemoteOption.startedAt } : null,
    scheduledCurrentAt
  )
    ? { ...activeRemoteOption, startedAt: scheduledCurrentAt }
    : vitalWipeOption(server, null, 'current', scheduledCurrentAt);
  const nextOption = vitalWipeOption(server, null, 'next', payload.nextWipeAt);
  return {
    ...payload,
    defaultWipeMode: 'next',
    wipeOptions: [currentOption, nextOption].filter(Boolean)
  };
}

async function publicWipeServerOptionsForStore(store, now = new Date()) {
  const atlasCatalogPromise = fetchAtlasServers();
  const vitalCatalogPromise = fetchVitalServers();
  const baselineServers = wipeServerPresetsForStore(store);
  const atlasCurrentWipesById = new Map(baselineServers
    .filter((server) => server.provider === 'atlas')
    .map((server) => [server.id, fetchAtlasCurrentWipe(server)]));
  const vitalWipesById = new Map(baselineServers
    .filter((server) => server.provider !== 'atlas')
    .map((server) => [server.vitalServerId, fetchVitalWipes(server.vitalServerId)]));
  const [atlasCatalog, vitalCatalog] = await Promise.all([atlasCatalogPromise, vitalCatalogPromise]);
  return Promise.all(wipeServerPresetsForStore(store, vitalCatalog).map(async (server) => (
    server.provider === 'atlas'
      ? publicWipeServerPreset(
        server,
        [],
        now,
        {
          ...(atlasServerForPreset(server, atlasCatalog) || {}),
          ...(await atlasCurrentWipesById.get(server.id) || {})
        }
      )
      : publicWipeServerPreset(server, await vitalWipesById.get(server.vitalServerId), now)
  )));
}

function userDisplayName(user) {
  if (!user) return '未知';
  if (user.boundSteamId) return user.steamNickname || user.username;
  return user.username;
}

function attachIntegrationEventResponseRecorder(res, eventResult, metadata = {}) {
  const event = eventResult?.event;
  if (!event?.id) return;
  res.once('finish', () => {
    const statusCode = Number(res.statusCode || 0);
    const responseFailure = eventResult.responseFailure || null;
    const terminalStatus = event.status === 'duplicate'
      ? 'duplicate'
      : (statusCode >= 400 || responseFailure ? 'failed' : 'processed');
    updateIntegrationEvent(event.id, {
      status: terminalStatus,
      processedAt: nowIso(),
      errorSummary: responseFailure?.errorSummary || (statusCode >= 400 ? `HTTP ${statusCode}` : ''),
      metadata: {
        ...metadata,
        duplicate: Boolean(eventResult.duplicate),
        httpStatus: statusCode,
        ...(responseFailure?.stage ? { stage: responseFailure.stage } : {})
      }
    }).catch(() => {});
  });
}

function discordIntegrationEventInput(payload = {}, req = {}) {
  const eventType = payload.type === 1
    ? 'ping'
    : (payload.type === 2 ? 'application_command' : (payload.type === 3 ? 'message_component' : (payload.type === 5 ? 'modal_submit' : `type_${payload.type || 'unknown'}`)));
  const customId = normalizeText(payload?.data?.custom_id || payload?.data?.name, 160);
  const sourceId = normalizeText(payload.id || payload.interaction_id || payload.token, 160);
  const rawBody = Buffer.isBuffer(req.body) ? req.body : Buffer.from(String(req.body || ''));
  const bodyHash = crypto.createHash('sha1').update(rawBody).digest('hex').slice(0, 24);
  return {
    platform: 'discord',
    eventType,
    dedupeKey: `discord:interaction:${sourceId || bodyHash}`,
    sourceId: sourceId || bodyHash,
    status: 'received',
    metadata: {
      interactionType: payload.type,
      customId,
      commandName: normalizeText(payload?.data?.name, 120),
      guildId: normalizeText(payload.guild_id, DISCORD_ID_MAX_LENGTH),
      channelId: normalizeText(payload.channel_id, DISCORD_ID_MAX_LENGTH),
      userId: discordUserIdFromInteraction(payload),
      locale: normalizeText(payload.locale, 20),
      bodyBytes: rawBody.length
    }
  };
}

function kookIntegrationEventInput(payload = {}, body = {}, claim = null) {
  const data = kookEventData(payload);
  const buttonValue = kookButtonEventValue(body);
  const eventType = data.channel_type === 'WEBHOOK_CHALLENGE'
    ? 'webhook_challenge'
    : (buttonValue ? 'message_button_click' : normalizeText(data.type || data.channel_type || data.event_type || payload.s || 'event', 120));
  const dedupeKey = claim?.key || kookWebhookEventDedupeKey(payload, body);
  return {
    platform: 'kook',
    eventType,
    dedupeKey: `kook:event:${dedupeKey}`,
    sourceId: normalizeText(data.msg_id || data.msgId || data.event_id || data.eventId || data.message_id || data.messageId || payload.sn || payload.s, 160),
    status: claim?.claimed === false ? 'duplicate' : (buttonValue ? 'queued' : 'processed'),
    metadata: {
      channelType: normalizeText(data.channel_type, 80),
      buttonValue,
      targetId: kookButtonEventTargetId(payload, body),
      messageId: kookButtonEventMessageId(payload, body),
      userId: normalizeText(data.author_id || data.authorId || data.user_id || data.userId, KOOK_ID_MAX_LENGTH),
      memoryDedupeClaimed: claim ? Boolean(claim.claimed) : undefined,
      memoryDedupeReason: claim?.reason || ''
    }
  };
}

async function checkpointSqliteSafe(mode = 'PASSIVE') {
  if (!sqliteEnabled()) return null;
  try {
    return await checkpointSqlite(mode);
  } catch (error) {
    console.warn('[nb-clan] sqlite checkpoint failed:', error?.message || error);
    return null;
  }
}

function newerTimestamp(left, right) {
  return timestampForSort(left?.syncedAt || left?.capturedAt || left?.updatedAt || left?.createdAt) -
    timestampForSort(right?.syncedAt || right?.capturedAt || right?.updatedAt || right?.createdAt);
}

function setLatestIndexValue(map, key, value) {
  if (!key || !value) return;
  const current = map.get(key);
  if (!current || newerTimestamp(value, current) > 0) map.set(key, value);
}

function setLatestWipeIndexValue(map, key, wipe) {
  if (!key || !wipe) return;
  const current = map.get(key);
  const nextTime = timestampForSort(wipe.closedAt || wipe.updatedAt || wipe.startedAt || wipe.createdAt);
  const currentTime = timestampForSort(current?.closedAt || current?.updatedAt || current?.startedAt || current?.createdAt);
  if (!current || nextTime > currentTime) map.set(key, wipe);
}

function compactOfficialKdaSignals(kda = null) {
  if (!kda) return null;
  return {
    kills: Number(kda.kills || 0),
    deaths: Number(kda.deaths || 0),
    assists: Number(kda.assists || 0),
    kda: Number(kda.kda || 0),
    headshots: Number(kda.headshots || 0),
    hits: Number(kda.hits || 0),
    playerHits: Number(kda.playerHits || kda.hits || 0),
    totalHits: Number(kda.totalHits || kda.hits || 0),
    buildingHits: Number(kda.buildingHits || 0),
    signHits: Number(kda.signHits || 0),
    animalHits: Number(kda.animalHits || 0),
    deadPlayerHits: Number(kda.deadPlayerHits || 0),
    otherHits: Number(kda.otherHits || 0),
    bulletsFired: Number(kda.bulletsFired || 0),
    accuracy: Number(kda.accuracy || 0),
    headshotRate: Number(kda.headshotRate || 0),
    rockets: Number(kda.rockets || 0),
    sulfur: Number(kda.sulfur || 0),
    metalOre: Number(kda.metalOre || 0),
    wood: Number(kda.wood || 0),
    stone: Number(kda.stone || 0),
    playTimeMinutes: Number(kda.playTimeMinutes || 0),
    achievementsCount: Number(kda.achievementsCount || 0)
  };
}

function getStoreIndexes(store) {
  const indexes = {
    usersById: new Map((store.users || []).map((user) => [user.id, user])),
    squadsById: new Map((store.squads || []).map((squad) => [squad.id, squad])),
    squadByMemberId: new Map((store.squadMembers || []).map((item) => [item.memberId, item])),
    memberProfileByMemberId: new Map((store.memberProfiles || []).map((profile) => [profile.memberId, profile])),
    wipesById: new Map((store.wipes || []).map((wipe) => [wipe.id, wipe])),
    latestWipeByBattlemetricsServerId: new Map(),
    availableParticipantsByMemberId: new Map(),
    latestKdaByMemberId: new Map(),
    latestKdaByWipeMemberKey: new Map()
  };
  for (const wipe of store.wipes || []) {
    const serverId = battlemetricsServerIdForWipe(wipe);
    if (serverId) setLatestWipeIndexValue(indexes.latestWipeByBattlemetricsServerId, serverId, wipe);
  }
  for (const participant of store.wipeParticipants || []) {
    if (!isParticipantAvailable(participant.status)) continue;
    if (!indexes.availableParticipantsByMemberId.has(participant.memberId)) {
      indexes.availableParticipantsByMemberId.set(participant.memberId, []);
    }
    indexes.availableParticipantsByMemberId.get(participant.memberId).push(participant);
  }
  for (const row of store.kdaRows || []) {
    setLatestIndexValue(indexes.latestKdaByMemberId, row.memberId, row);
    setLatestIndexValue(indexes.latestKdaByWipeMemberKey, `${row.wipeId}:member:${row.memberId}`, row);
    setLatestIndexValue(indexes.latestKdaByWipeMemberKey, `${row.wipeId}:steam:${row.steamId}`, row);
  }
  return indexes;
}

function discordReviewInviterNameForMember(store, member) {
  const invitedByUserId = normalizeText(member?.invitedByUserId, 120);
  if (!invitedByUserId.startsWith('discord:')) return '未知';
  const application = (store.discordMemberApplications || []).find((item) => (
    (member.id && item.memberId === member.id) ||
    (member.steamId && item.steamId === member.steamId && item.reviewedByUserId === invitedByUserId)
  ));
  const applicationReviewer = normalizeText(
    application?.reviewedByName ||
    application?.reviewedByUsername ||
    application?.reviewedByDisplayName,
    120
  );
  if (applicationReviewer) return applicationReviewer;
  const log = (store.logs || []).find((item) => (
    item.actorUserId === invitedByUserId &&
    ['member_add', 'member_edit', 'discord_member_application_approve'].includes(item.type) &&
    (
      item.targetId === member.id ||
      item.metadata?.memberId === member.id ||
      (application?.id && item.targetId === application.id)
    ) &&
    normalizeText(item.actorUsername, 120)
  ));
  return normalizeText(log?.actorUsername, 120) || '未知';
}

function enrichMember(store, member, viewer = null, indexes = getStoreIndexes(store)) {
  const { usersById, squadsById, squadByMemberId } = indexes;
  const inviter = usersById.get(member.invitedByUserId);
  const inviterName = normalizeText(member.invitedByName || member.inviterName, 120) ||
    (inviter ? userDisplayName(inviter) : discordReviewInviterNameForMember(store, member));
  const squadMember = squadByMemberId.get(member.id);
  const squad = squadMember ? squadsById.get(squadMember.squadId) : null;
  const rawOnlineSummary = memberOnlineSummary(store, member, indexes);
  const onlineSummary = memberDisplayOnlineSummary(store, member, viewer, indexes);
  const profileStats = memberProfilePayload(store, member, indexes, { useKdaFallback: false });
  const onlineTimeMinutes = onlineMinutesFromSummary(onlineSummary);
  const onlineTimeKnown = Boolean(!onlineSummary.error && (onlineSummary.syncedAt || onlineSummary.lastOnlineAt || onlineTimeMinutes > 0));
  return {
    ...member,
    displayName: memberDisplayName(member),
    inviterName,
    invitedAt: member.createdAt,
    squadId: squad?.id || '',
    squadName: squad?.name || '',
    specialty: normalizeMemberSpecialties(member.specialty),
    ...normalizeMemberVipInput(member, member),
    vitalVip: publicVitalVip(member),
    vitalVipText: vitalVipSummaryText(member),
    rustinityVip: publicRustinityVip(member),
    rustinityVipText: rustinityVipSummaryText(member),
    atlasVip: publicAtlasVip(member),
    atlasVipText: atlasVipSummaryText(member),
    battlemetricsId: member.battlemetricsId || rawOnlineSummary.battlemetricsPlayerId || onlineSummary.battlemetricsPlayerId || '',
    avatar: member.avatar || '',
    canManage: canManageMemberInStore(store, viewer, member, indexes),
    onlineSummary,
    accountSignals: {
      playTimeMinutes: Number(profileStats.playTimeMinutes || 0),
      playTimeKnown: Boolean(profileStats.playTimeKnown),
      playTimeVisibility: profileStats.playTimeVisibility || '',
      inventoryValue: profileStats.inventoryValue,
      inventoryCurrency: profileStats.inventoryCurrency || 'USD',
      inventoryPublic: Boolean(profileStats.inventoryPublic),
      inventoryVisibility: profileStats.inventoryVisibility || '',
      profilePublic: Boolean(profileStats.profilePublic),
      accountRestricted: Boolean(profileStats.accountRestricted),
      accountRestrictionStatus: profileStats.accountRestrictionStatus || '',
      accountRestrictionCheckedAt: profileStats.accountRestrictionCheckedAt || '',
      accountRestrictionError: profileStats.accountRestrictionError || '',
      vacBanned: Boolean(profileStats.vacBanned),
      numberOfVacBans: Number(profileStats.numberOfVacBans || 0),
      numberOfGameBans: Number(profileStats.numberOfGameBans || 0),
      daysSinceLastBan: Number(profileStats.daysSinceLastBan || 0),
      communityBanned: Boolean(profileStats.communityBanned),
      economyBan: profileStats.economyBan || 'none',
      economyRestricted: Boolean(profileStats.economyRestricted),
      steamBanCheckedAt: profileStats.steamBanCheckedAt || '',
      steamBanError: profileStats.steamBanError || '',
      fetchedAt: profileStats.fetchedAt || '',
      lastOnlineAt: onlineSummary.lastOnlineAt || '',
      lastOfflineAt: onlineSummary.lastOfflineAt || '',
      onlineSyncedAt: onlineSummary.syncedAt || '',
      onlineTimeKnown,
      onlineTimeMinutes,
      battlemetricsPlayerId: onlineSummary.battlemetricsPlayerId || '',
      battlemetricsServerId: onlineSummary.battlemetricsServerId || '',
      battlemetricsWipeId: onlineSummary.wipeId || '',
      battlemetricsServerPlayTimeMinutes: Number(onlineSummary.serverPlayTimeMinutes || 0),
      battlemetricsTotalPlayTimeMinutes: Number(onlineSummary.totalPlayTimeMinutes || 0),
      battlemetricsWeeklyPlayTimeMinutes: Number(onlineSummary.weeklyPlayTimeMinutes || 0),
      officialKda: compactOfficialKdaSignals(profileStats.officialKda)
    },
    profileUrl: `https://steamcommunity.com/profiles/${member.steamId}`
  };
}

function enrichMembers(store, viewer = null, sourceMembers = store.members, indexes = getStoreIndexes(store)) {
  return sourceMembers.map((member) => enrichMember(store, member, viewer, indexes));
}

function memberListQueryParams(query = {}) {
  const hasLimit = Object.hasOwn(query, 'limit');
  const rawLimit = Math.floor(Number(query.limit));
  const rawOffset = Math.floor(Number(query.offset));
  const specialty = normalizeMemberSpecialties(query.specialty)[0] || '';
  const rawVitalVipType = normalizeText(query.vitalVipType, 40);
  const vitalVipType = ['none', 'priority', 'queue_skip'].includes(rawVitalVipType) ? rawVitalVipType : '';
  return {
    hasLimit,
    limit: hasLimit ? Math.max(1, Math.min(100, Number.isFinite(rawLimit) ? rawLimit : 5)) : 0,
    offset: Math.max(0, Number.isFinite(rawOffset) ? rawOffset : 0),
    q: normalizeText(query.q, 120).toLowerCase(),
    squadId: normalizeText(query.squadId, 100),
    specialty,
    vitalVipType
  };
}

function memberMatchesListQuery(store, member, params, indexes) {
  const squadMember = indexes.squadByMemberId.get(member.id);
  const squad = squadMember ? indexes.squadsById.get(squadMember.squadId) : null;
  const memberSquadId = squad?.id || '';
  if ((params.squadId === '__unassigned' || params.squadId === '__none__') && memberSquadId) return false;
  if (params.squadId && params.squadId !== '__unassigned' && params.squadId !== '__none__' && memberSquadId !== params.squadId) return false;
  if (params.specialty && !normalizeMemberSpecialties(member.specialty).includes(params.specialty)) return false;
  if (params.vitalVipType && normalizeVitalVipType(member.vitalVipType) !== params.vitalVipType) return false;
  if (!params.q) return true;
  return [
    memberDisplayName(member),
    member.customName,
    member.steamNickname,
    member.steamId,
    member.discordId,
    member.discordName,
    member.wechatId,
    member.notes,
    squad?.name
  ].some((value) => normalizeText(value, 240).toLowerCase().includes(params.q));
}

function memberListPayload(store, viewer, query = {}) {
  const params = memberListQueryParams(query);
  const indexes = getStoreIndexes(store);
  const filteredMembers = store.members.filter((member) => memberMatchesListQuery(store, member, params, indexes));
  const total = filteredMembers.length;
  const pageMembers = params.hasLimit ? filteredMembers.slice(params.offset, params.offset + params.limit) : filteredMembers;
  const limit = params.hasLimit ? params.limit : total;
  return {
    members: enrichMembers(store, viewer, pageMembers, indexes),
    total,
    offset: params.hasLimit ? params.offset : 0,
    limit,
    hasMore: params.hasLimit && params.offset + pageMembers.length < total
  };
}

function canUsePagedMemberListStore(params = {}) {
  return Boolean(params.hasLimit && !params.q && !params.squadId && !params.specialty && !params.vitalVipType);
}

function canUsePagedSquadMemberListStore(params = {}) {
  return Boolean(
    params.hasLimit &&
    params.squadId &&
    params.squadId !== '__none__' &&
    params.squadId !== '__unassigned' &&
    !params.q &&
    !params.specialty &&
    !params.vitalVipType
  );
}

function canUsePagedUnassignedMemberListStore(params = {}) {
  return Boolean(
    params.hasLimit &&
    (params.squadId === '__none__' || params.squadId === '__unassigned') &&
    !params.q &&
    !params.specialty &&
    !params.vitalVipType
  );
}

function canUsePagedSearchMemberListStore(params = {}) {
  return Boolean(
    params.hasLimit &&
    params.q &&
    !params.squadId &&
    !params.specialty &&
    !params.vitalVipType
  );
}

function canUsePagedCandidateFilteredMemberListStore(params = {}) {
  const filterCount = [
    params.q,
    params.squadId,
    params.specialty,
    params.vitalVipType
  ].filter(Boolean).length;
  if (!params.hasLimit || filterCount < 2) return false;
  if (params.squadId || params.specialty || params.vitalVipType) return true;
  return false;
}

function canUsePagedVitalVipMemberListStore(params = {}) {
  return Boolean(
    params.hasLimit &&
    !params.q &&
    !params.squadId &&
    !params.specialty &&
    ['priority', 'queue_skip'].includes(params.vitalVipType)
  );
}

function canUsePagedVitalVipNoneMemberListStore(params = {}) {
  return Boolean(
    params.hasLimit &&
    !params.q &&
    !params.squadId &&
    !params.specialty &&
    params.vitalVipType === 'none'
  );
}

function canUsePagedSpecialtyMemberListStore(params = {}) {
  return Boolean(
    params.hasLimit &&
    !params.q &&
    !params.squadId &&
    params.specialty &&
    !params.vitalVipType
  );
}

function memberSpecialtyQueryValues(specialty) {
  const normalized = normalizeMemberSpecialty(specialty);
  return normalized ? [...new Set([...sharedMemberSpecialtyQueryValues(normalized), normalized.toUpperCase()])] : [];
}

async function readCandidateFilteredMemberListStore(params, options = {}) {
  if (params.squadId && params.squadId !== '__none__' && params.squadId !== '__unassigned') {
    return readMemberListSquadCandidateRuntimeStore(params.squadId, options);
  }
  if (params.squadId === '__none__' || params.squadId === '__unassigned') {
    return readMemberListUnassignedCandidateRuntimeStore(options);
  }
  if (params.specialty) {
    return readMemberListSpecialtyCandidateRuntimeStore(memberSpecialtyQueryValues(params.specialty), options);
  }
  if (params.vitalVipType) {
    return readMemberListVitalVipCandidateRuntimeStore(params.vitalVipType, options);
  }
  return null;
}

async function writeWechatAdminMemberDirect(req, memberId, mutator, reason = 'wechat_admin_member_update', options = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedMemberId = normalizeText(memberId, 120);
      const store = await readMemberDetailRuntimeStore(normalizedMemberId, options);
      const member = (store.members || []).find((item) => item.id === normalizedMemberId);
      if (!member) throw Object.assign(new Error('成员不存在'), { status: 404 });
      const linkedWechatUserId = normalizeText(member.wechatUserId || (isWechatSystemId(member.wechatId) ? member.wechatId : ''), 160);
      if (linkedWechatUserId && !(store.wechatUsers || []).some((item) => item.id === linkedWechatUserId)) {
        const linkedWechatUser = await getSqliteRecord('wechatUsers', linkedWechatUserId);
        if (linkedWechatUser) {
          store.wechatUsers ||= [];
          store.wechatUsers.push(linkedWechatUser);
        }
      }
      const result = await mutator(store, member);
      const updatedMember = { ...member };
      const upserts = { members: [updatedMember], ...(result?.upserts || {}) };
      let log = result?.log || null;
      if (log) upserts.logs = [...(upserts.logs || []), log];
      const patchResult = await writeSqliteStorePatch({
        reason,
        upserts,
        deletes: result?.deletes || {},
        replaces: result?.replaces || {},
        scalars: result?.scalars || {},
        trims: log ? logTrimPatch() : {}
      });
      await patchStoreCache((cachedStore) => {
        cachedStore.members ||= [];
        replaceCachedRecord(cachedStore.members, updatedMember);
        if (log) applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
        if (typeof result?.patchCache === 'function') {
          result.patchCache(cachedStore);
        }
      });
      return { store, member: updatedMember, result };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite wechat admin member update failed:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('微信管理成员写入', error);
  }
}

async function deleteWebMembersDirect(req, memberIds = [], options = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedMemberIds = [...new Set((Array.isArray(memberIds) ? memberIds : [memberIds])
        .map((id) => normalizeText(id, 120))
        .filter(Boolean))];
      const members = await readSqliteRecordsByIds('members', normalizedMemberIds);
      const membersById = new Map(members.map((member) => [member.id, member]));
      const missingId = normalizedMemberIds.find((id) => !membersById.has(id));
      if (missingId) throw Object.assign(new Error('成员不存在'), { status: 404 });
      const targetMembers = normalizedMemberIds.map((id) => membersById.get(id)).filter(Boolean);
      const store = await readMemberDeleteRuntimeStore(targetMembers);
      const blockedMember = targetMembers.find((member) => !canManageMemberInStore(store, req.user, member));
      if (blockedMember) {
        throw Object.assign(new Error('无权管理该成员'), { status: 403 });
      }
      const before = {
        squadMembers: [...(store.squadMembers || [])],
        wipeParticipants: [...(store.wipeParticipants || [])],
        kdaRows: [...(store.kdaRows || [])],
        kdaSnapshots: [...(store.kdaSnapshots || [])],
        memberProfiles: [...(store.memberProfiles || [])],
        accountAlertDismissals: [...(store.accountAlertDismissals || [])],
        users: [...(store.users || [])],
        sessions: [...(store.sessions || [])]
      };
      const deleteIds = new Set(targetMembers.map((member) => member.id));
      store.members = [];
      removeMemberRuntimeRecords(store, targetMembers);
      const bulk = Boolean(options.bulk);
      const log = bulk
        ? createLogEntry(req, 'member_bulk_delete', `批量删除成员 ${deleteIds.size} 人`, {
          metadata: {
            deleted: deleteIds.size,
            memberIds: [...deleteIds],
            names: targetMembers.map((member) => memberDisplayName(member))
          }
        })
        : createLogEntry(req, 'member_delete', `删除成员 ${memberDisplayName(targetMembers[0])}`, {
          steamId: targetMembers[0]?.steamId || '',
          targetId: targetMembers[0]?.id || ''
        });
      const deletes = {
        members: [...deleteIds],
        squadMembers: collectionDeletePatch(before.squadMembers, store.squadMembers),
        wipeParticipants: collectionDeletePatch(before.wipeParticipants, store.wipeParticipants),
        kdaRows: collectionDeletePatch(before.kdaRows, store.kdaRows),
        kdaSnapshots: collectionDeletePatch(before.kdaSnapshots, store.kdaSnapshots),
        memberProfiles: collectionDeletePatch(before.memberProfiles, store.memberProfiles),
        accountAlertDismissals: collectionDeletePatch(before.accountAlertDismissals, store.accountAlertDismissals),
        users: collectionDeletePatch(before.users, store.users),
        sessions: collectionDeletePatch(before.sessions, store.sessions)
      };
      const patchResult = await writeSqliteStorePatch({
        reason: bulk ? 'member_bulk_delete' : 'member_delete',
        upserts: { logs: [log] },
        deletes,
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        const deleteFromCollection = (collection, ids = []) => {
          if (!ids.length) return;
          const idSet = new Set(ids);
          cachedStore[collection] = (cachedStore[collection] || []).filter((item) => !idSet.has(item.id || item.key));
        };
        for (const [collection, ids] of Object.entries(deletes)) {
          deleteFromCollection(collection, ids);
        }
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return {
        deleted: deleteIds.size,
        deletedMemberIds: [...deleteIds],
        deletedMember: targetMembers[0] || null
      };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite member delete failed:', error?.message || error);
    throw sqliteDirectWriteUnavailableError(options.bulk ? '成员批量删除写入' : '成员删除写入', error);
  }
}

async function writeWebMemberCreateDirect(req, member) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const steamId = normalizeText(member?.steamId, 80);
      if (!steamId) throw Object.assign(new Error('Steam ID 必填'), { status: 400 });
      const existing = await findSqliteRecordByJsonField('members', 'steamId', steamId);
      if (existing) throw Object.assign(new Error('该 SteamID 已经是成员'), { status: 409 });
      const requestedSquadId = Object.hasOwn(req.body || {}, 'squadId') ? normalizeText(req.body.squadId, 80) : '';
      const permissionRoles = await getSqliteCollection('permissionRoles', { limit: 0 });
      const squads = await readMemberAssignmentSquadsForUser(req.user, permissionRoles, [requestedSquadId]);
      const store = memberRuntimeStoreShell({
        members: [],
        squads,
        squadMembers: [],
        permissionRoles
      });
      const nextMember = { ...member };
      store.members.unshift(nextMember);
      if (requestedSquadId) {
        setMemberSquad(store, nextMember, requestedSquadId, req.user);
      }
      const log = createLogEntry(req, 'member_add', `添加成员 ${memberDisplayName(nextMember)}`, {
        steamId: nextMember.steamId,
        targetId: nextMember.id,
        metadata: { rawInput: nextMember.rawInput }
      });
      const patchResult = await writeSqliteStorePatch({
        reason: 'member_add',
        upserts: {
          members: [nextMember],
          ...(store.squadMembers.length ? { squadMembers: store.squadMembers } : {}),
          logs: [log]
        },
        positions: {
          members: { [nextMember.id]: 0 },
          logs: { [log.id]: 0 }
        },
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        cachedStore.members ||= [];
        cachedStore.members = cachedStore.members.filter((item) => item.id !== nextMember.id);
        cachedStore.members.unshift(nextMember);
        if (store.squadMembers.length) {
          applyStoreCollectionCachePatch(cachedStore, ['squadMembers'], { squadMembers: store.squadMembers }, {});
        }
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return {
        memberId: nextMember.id,
        squadId: store.squadMembers.find((item) => item.memberId === nextMember.id)?.squadId || ''
      };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite member create failed:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('成员创建写入', error);
  }
}

async function writeWebMemberBulkCreateDirect(req, preparedMembers = [], options = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const items = (preparedMembers || []).filter((item) => item?.member?.steamId);
      const steamIds = uniqueNormalizedTexts(items.map((item) => item.member.steamId), 80);
      const [existingMembers, permissionRoles] = await Promise.all([
        steamIds.length ? getSqliteRecordsByJsonField('members', 'steamId', steamIds, { limit: 0 }) : Promise.resolve([]),
        getSqliteCollection('permissionRoles', { limit: 0 })
      ]);
      const squadId = normalizeText(options.squadId, 80);
      const squads = await readMemberAssignmentSquadsForUser(req.user, permissionRoles, [squadId]);
      const existingSteamIds = new Set((existingMembers || []).map((member) => normalizeText(member.steamId, 80)).filter(Boolean));
      const store = memberRuntimeStoreShell({
        members: [],
        squads,
        squadMembers: [],
        permissionRoles
      });
      const results = [...(options.results || [])];
      const failed = Number(options.failed || 0);
      let skipped = Number(options.skipped || 0);
      let imported = 0;
      const importedMemberIds = [];
      for (const item of items) {
        const steamId = normalizeText(item.member.steamId, 80);
        if (existingSteamIds.has(steamId)) {
          skipped += 1;
          results.push({ input: item.input, steamId, status: 'skipped', message: '该 SteamID 已经是成员' });
          continue;
        }
        const member = { ...item.member };
        store.members.unshift(member);
        existingSteamIds.add(steamId);
        if (squadId) {
          setMemberSquad(store, member, squadId, req.user);
        }
        imported += 1;
        importedMemberIds.push(member.id);
        results.push({ input: item.input, steamId: member.steamId, status: 'imported', message: memberDisplayName(member) });
      }
      let log = null;
      if (imported > 0) {
        log = createLogEntry(req, 'member_bulk_add', `批量导入成员 ${imported} 人`, {
          metadata: { imported, skipped, failed, squadId }
        });
        const patchResult = await writeSqliteStorePatch({
          reason: 'member_bulk_add',
          upserts: {
            members: store.members,
            ...(store.squadMembers.length ? { squadMembers: store.squadMembers } : {}),
            logs: [log]
          },
          positions: {
            members: Object.fromEntries(store.members.map((member) => [member.id, 0])),
            logs: { [log.id]: 0 }
          },
          trims: logTrimPatch()
        });
        await patchStoreCache((cachedStore) => {
          cachedStore.members ||= [];
          const importedIdSet = new Set(importedMemberIds);
          cachedStore.members = cachedStore.members.filter((member) => !importedIdSet.has(member.id));
          cachedStore.members.unshift(...store.members);
          if (store.squadMembers.length) {
            applyStoreCollectionCachePatch(cachedStore, ['squadMembers'], { squadMembers: store.squadMembers }, {});
          }
          applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
        });
      }
      return { imported, skipped, failed, results, importedMemberIds };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite member bulk create failed:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('成员批量创建写入', error);
  }
}

async function deleteWechatAdminMemberDirect(req, memberId) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedMemberId = normalizeText(memberId, 120);
      const member = normalizedMemberId ? await getSqliteRecord('members', normalizedMemberId) : null;
      if (!member) throw Object.assign(new Error('成员不存在'), { status: 404 });
      const deletedMember = { ...member };
      const store = await readWechatAdminMemberDeleteRuntimeStore(member);
      const linkedWechatUsers = (store.wechatUsers || []).filter((item) => (
        item.memberId === member.id ||
        item.id === member.wechatUserId ||
        (isWechatSystemId(member.wechatId) && item.id === member.wechatId)
      ));
      const updatedAt = nowIso();
      for (const wechatUser of linkedWechatUsers) {
        wechatUser.memberId = '';
        if (wechatUser.status !== 'blocked') wechatUser.status = 'guest';
        wechatUser.updatedAt = updatedAt;
      }
      const affectedWechatUsers = linkedWechatUsers.map((item) => ({ ...item }));
      const before = {
        squadMembers: [...(store.squadMembers || [])],
        wipeParticipants: [...(store.wipeParticipants || [])],
        kdaRows: [...(store.kdaRows || [])],
        kdaSnapshots: [...(store.kdaSnapshots || [])],
        memberProfiles: [...(store.memberProfiles || [])],
        accountAlertDismissals: [...(store.accountAlertDismissals || [])],
        users: [...(store.users || [])],
        sessions: [...(store.sessions || [])]
      };
      store.members = [];
      removeMemberRuntimeRecords(store, [member]);
      const log = createLogEntry(req, 'wechat_admin_member_delete', `微信管理删除成员 ${memberDisplayName(member)}`, {
        steamId: member.steamId,
        targetId: member.id,
        actorUserId: reviewActorId(req),
        actorUsername: requestActorUsername(req, 'wechat_admin')
      });
      const deletes = {
        members: [member.id],
        squadMembers: collectionDeletePatch(before.squadMembers, store.squadMembers),
        wipeParticipants: collectionDeletePatch(before.wipeParticipants, store.wipeParticipants),
        kdaRows: collectionDeletePatch(before.kdaRows, store.kdaRows),
        kdaSnapshots: collectionDeletePatch(before.kdaSnapshots, store.kdaSnapshots),
        memberProfiles: collectionDeletePatch(before.memberProfiles, store.memberProfiles),
        accountAlertDismissals: collectionDeletePatch(before.accountAlertDismissals, store.accountAlertDismissals),
        users: collectionDeletePatch(before.users, store.users),
        sessions: collectionDeletePatch(before.sessions, store.sessions)
      };
      const patchResult = await writeSqliteStorePatch({
        reason: 'wechat_admin_member_delete',
        upserts: {
          logs: [log],
          ...(affectedWechatUsers.length ? { wechatUsers: affectedWechatUsers } : {})
        },
        deletes,
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        const deleteFromCollection = (collection, ids = []) => {
          if (!ids.length) return;
          const idSet = new Set(ids);
          cachedStore[collection] = (cachedStore[collection] || []).filter((item) => !idSet.has(item.id || item.key));
        };
        for (const [collection, ids] of Object.entries(deletes)) {
          deleteFromCollection(collection, ids);
        }
        cachedStore.wechatUsers ||= [];
        for (const wechatUser of affectedWechatUsers) replaceCachedRecord(cachedStore.wechatUsers, wechatUser);
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return { deletedMember, affectedWechatUsers };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite wechat admin member delete failed:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('微信管理成员删除写入', error);
  }
}

async function memberListPayloadForViewer(viewer, query = {}) {
  if (!sqlitePrimaryMode()) {
    const store = await readStore();
    return memberListPayload(store, viewer, query);
  }
  const params = memberListQueryParams(query);
  const viewerRole = normalizeRole(viewer?.role);
  const includePermissionRoles = Boolean(viewerRole && !BUILTIN_ROLE_IDS.includes(viewerRole));
  if (canUsePagedCandidateFilteredMemberListStore(params)) {
    const candidateStore = await readCandidateFilteredMemberListStore(params, {
      includePermissionRoles
    });
    if (candidateStore) {
      await hydrateMemberListFilterContextRuntimeStore(candidateStore, candidateStore.members);
      const baseIndexes = getStoreIndexes(candidateStore);
      const filteredMembers = candidateStore.members.filter((member) => memberMatchesListQuery(candidateStore, member, params, baseIndexes));
      const total = filteredMembers.length;
      const pageMembers = filteredMembers.slice(params.offset, params.offset + params.limit);
      candidateStore.members = pageMembers;
      await hydrateMemberListPageRuntimeStore(candidateStore, pageMembers);
      const pageIndexes = getStoreIndexes(candidateStore);
      return {
        members: enrichMembers(candidateStore, viewer, pageMembers, pageIndexes),
        total,
        offset: params.offset,
        limit: params.limit,
        hasMore: params.offset + pageMembers.length < total
      };
    }
  }
  if (canUsePagedVitalVipNoneMemberListStore(params)) {
    const vipNoneStore = await readMemberListVitalVipNoneCandidateRuntimeStore({
      includePermissionRoles
    });
    if (vipNoneStore) {
      const baseIndexes = getStoreIndexes(vipNoneStore);
      const filteredMembers = vipNoneStore.members.filter((member) => memberMatchesListQuery(vipNoneStore, member, params, baseIndexes));
      const total = filteredMembers.length;
      const pageMembers = filteredMembers.slice(params.offset, params.offset + params.limit);
      vipNoneStore.members = pageMembers;
      await hydrateMemberListPageRuntimeStore(vipNoneStore, pageMembers);
      const pageIndexes = getStoreIndexes(vipNoneStore);
      return {
        members: enrichMembers(vipNoneStore, viewer, pageMembers, pageIndexes),
        total,
        offset: params.offset,
        limit: params.limit,
        hasMore: params.offset + pageMembers.length < total
      };
    }
  }
  if (canUsePagedSpecialtyMemberListStore(params)) {
    const specialtyStore = await readMemberListSpecialtyCandidateRuntimeStore(memberSpecialtyQueryValues(params.specialty), {
      includePermissionRoles
    });
    if (specialtyStore) {
      const baseIndexes = getStoreIndexes(specialtyStore);
      const filteredMembers = specialtyStore.members.filter((member) => memberMatchesListQuery(specialtyStore, member, params, baseIndexes));
      const total = filteredMembers.length;
      const pageMembers = filteredMembers.slice(params.offset, params.offset + params.limit);
      specialtyStore.members = pageMembers;
      await hydrateMemberListPageRuntimeStore(specialtyStore, pageMembers);
      const pageIndexes = getStoreIndexes(specialtyStore);
      return {
        members: enrichMembers(specialtyStore, viewer, pageMembers, pageIndexes),
        total,
        offset: params.offset,
        limit: params.limit,
        hasMore: params.offset + pageMembers.length < total
      };
    }
  }
  if (canUsePagedUnassignedMemberListStore(params)) {
    const pageResult = await readMemberListUnassignedPageRuntimeStore({
      limit: params.limit,
      offset: params.offset,
      includePermissionRoles
    });
    if (pageResult) {
      const indexes = getStoreIndexes(pageResult.store);
      return {
        members: enrichMembers(pageResult.store, viewer, pageResult.store.members, indexes),
        total: pageResult.total,
        offset: pageResult.offset,
        limit: pageResult.limit,
        hasMore: pageResult.offset + pageResult.store.members.length < pageResult.total
      };
    }
  }
  if (canUsePagedSearchMemberListStore(params)) {
    const pageResult = await readMemberListSearchPageRuntimeStore(params.q, {
      limit: params.limit,
      offset: params.offset,
      includePermissionRoles
    });
    if (pageResult) {
      const indexes = getStoreIndexes(pageResult.store);
      return {
        members: enrichMembers(pageResult.store, viewer, pageResult.store.members, indexes),
        total: pageResult.total,
        offset: pageResult.offset,
        limit: pageResult.limit,
        hasMore: pageResult.offset + pageResult.store.members.length < pageResult.total
      };
    }
  }
  if (canUsePagedVitalVipMemberListStore(params)) {
    const pageResult = await readMemberListVitalVipPageRuntimeStore(params.vitalVipType, {
      limit: params.limit,
      offset: params.offset,
      includePermissionRoles
    });
    if (pageResult) {
      const indexes = getStoreIndexes(pageResult.store);
      return {
        members: enrichMembers(pageResult.store, viewer, pageResult.store.members, indexes),
        total: pageResult.total,
        offset: pageResult.offset,
        limit: pageResult.limit,
        hasMore: pageResult.offset + pageResult.store.members.length < pageResult.total
      };
    }
  }
  if (canUsePagedSquadMemberListStore(params)) {
    const pageResult = await readMemberListSquadPageRuntimeStore(params.squadId, {
      limit: params.limit,
      offset: params.offset,
      includePermissionRoles
    });
    if (pageResult) {
      const indexes = getStoreIndexes(pageResult.store);
      return {
        members: enrichMembers(pageResult.store, viewer, pageResult.store.members, indexes),
        total: pageResult.total,
        offset: pageResult.offset,
        limit: pageResult.limit,
        hasMore: pageResult.offset + pageResult.store.members.length < pageResult.total
      };
    }
  }
  if (canUsePagedMemberListStore(params)) {
    const pageResult = await readMemberListPageRuntimeStore({
      limit: params.limit,
      offset: params.offset,
      includePermissionRoles
    });
    if (pageResult) {
      const indexes = getStoreIndexes(pageResult.store);
      return {
        members: enrichMembers(pageResult.store, viewer, pageResult.store.members, indexes),
        total: pageResult.total,
        offset: pageResult.offset,
        limit: pageResult.limit,
        hasMore: pageResult.offset + pageResult.store.members.length < pageResult.total
      };
    }
  }
  const store = await readMemberListRuntimeStore({
    includePermissionRoles
  });
  if (store.memberPartial) throw memberStoreReadUnavailableError(store, '成员列表读取');
  if (!sqlitePrimaryMode()) return memberListPayload(store, viewer, query);
  const baseIndexes = getStoreIndexes(store);
  const filteredMembers = store.members.filter((member) => memberMatchesListQuery(store, member, params, baseIndexes));
  const total = filteredMembers.length;
  const pageMembers = params.hasLimit ? filteredMembers.slice(params.offset, params.offset + params.limit) : filteredMembers;
  const limit = params.hasLimit ? params.limit : total;
  await hydrateMemberListPageRuntimeStore(store, pageMembers);
  const pageIndexes = getStoreIndexes(store);
  return {
    members: enrichMembers(store, viewer, pageMembers, pageIndexes),
    total,
    offset: params.hasLimit ? params.offset : 0,
    limit,
    hasMore: params.hasLimit && params.offset + pageMembers.length < total
  };
}

function discordMembershipAuditConfiguration(store = {}) {
  const settings = discordSettings(store);
  const guildId = normalizeText(settings.guildId, DISCORD_ID_MAX_LENGTH);
  const roleIds = discordMembershipAuditRoleIds(settings);
  const tokenConfigured = Boolean(discordBotToken(settings));
  return {
    configured: Boolean(tokenConfigured && guildId && roleIds.length),
    tokenConfigured,
    guildId,
    roleIds
  };
}

function discordMembershipAuditStatus(member = {}) {
  return normalizeText(member.discordMembershipStatus, 40);
}

function discordMembershipAuditIsCandidate(member = {}) {
  return DISCORD_MEMBERSHIP_CANDIDATE_STATUSES.has(discordMembershipAuditStatus(member));
}

function discordMembershipRoleNamesForIds(roleIds = [], roleNameById = new Map()) {
  return (Array.isArray(roleIds) ? roleIds : []).map((roleId) => {
    const id = normalizeText(roleId, DISCORD_ID_MAX_LENGTH);
    const name = roleNameById instanceof Map ? normalizeText(roleNameById.get(id), 100) : '';
    return name || id;
  });
}

function publicDiscordMembershipRoles(roleIds = [], roleNames = []) {
  const names = Array.isArray(roleNames) ? roleNames : [];
  return (Array.isArray(roleIds) ? roleIds : [])
    .map((roleId, index) => {
      const id = normalizeText(roleId, DISCORD_ID_MAX_LENGTH);
      if (!id) return null;
      return {
        id,
        name: normalizeText(names[index], 100) || id
      };
    })
    .filter(Boolean);
}

function publicDiscordMembershipAudit(member = {}) {
  const expectedRoleIds = Array.isArray(member.discordMembershipExpectedRoleIds) ? member.discordMembershipExpectedRoleIds : [];
  const actualRoleIds = Array.isArray(member.discordMembershipActualRoleIds) ? member.discordMembershipActualRoleIds : [];
  return {
    status: discordMembershipAuditStatus(member),
    checkedAt: member.discordMembershipCheckedAt || '',
    missingSince: member.discordMembershipMissingSince || '',
    lastOkAt: member.discordMembershipLastOkAt || '',
    lastFailureAt: member.discordMembershipLastFailureAt || '',
    error: member.discordMembershipError || '',
    guildId: member.discordMembershipGuildId || '',
    expectedRoleIds,
    actualRoleIds,
    expectedRoles: publicDiscordMembershipRoles(expectedRoleIds, member.discordMembershipExpectedRoleNames),
    actualRoles: publicDiscordMembershipRoles(actualRoleIds, member.discordMembershipActualRoleNames)
  };
}

function discordMembershipAuditSummary(store = {}) {
  const settings = discordSettings(store);
  const audit = settings.memberAudit || {};
  const candidates = (store.members || []).filter(discordMembershipAuditIsCandidate);
  const notInGuild = candidates.filter((member) => discordMembershipAuditStatus(member) === DISCORD_MEMBERSHIP_NOT_IN_GUILD_STATUS).length;
  const missingRole = candidates.filter((member) => discordMembershipAuditStatus(member) === DISCORD_MEMBERSHIP_MISSING_ROLE_STATUS).length;
  return {
    lastRunAt: audit.lastRunAt || '',
    lastRunError: audit.lastRunError || '',
    checked: Number(audit.checked || 0),
    valid: Number(audit.valid || 0),
    flagged: Number(audit.flagged || 0),
    failed: Number(audit.failed || 0),
    skipped: Number(audit.skipped || 0),
    notInGuild,
    missingRole,
    currentFlagged: candidates.length
  };
}

function discordMembershipAuditPayload(store = {}, viewer = null) {
  const indexes = getStoreIndexes(store);
  const candidates = (store.members || [])
    .filter((member) => normalizeMemberStatus(member.memberStatus) === 'active')
    .filter(discordMembershipAuditIsCandidate)
    .map((member) => ({
      member: enrichMember(store, member, viewer, indexes),
      audit: publicDiscordMembershipAudit(member)
    }))
    .sort((left, right) => timestampForSort(left.audit.missingSince || left.audit.checkedAt) - timestampForSort(right.audit.missingSince || right.audit.checkedAt));
  return {
    configuration: discordMembershipAuditConfiguration(store),
    summary: discordMembershipAuditSummary(store),
    candidates
  };
}

function discordGuildMemberDisplayName(payload = {}, fallback = '') {
  return normalizeText(
    payload?.nick || payload?.user?.global_name || payload?.user?.username || fallback,
    120
  );
}

async function checkDiscordMembershipForMember(store = {}, member = {}, settings = {}, indexes = getStoreIndexes(store), roleNameById = new Map(), roleNamesResolved = true) {
  const discordUserId = validDiscordUserId(member.discordId);
  const expectedRoleIds = expectedDiscordRoleIdsForMember(store, member, settings, indexes);
  const expectedRoleNames = discordMembershipRoleNamesForIds(expectedRoleIds, roleNameById);
  const guildId = normalizeText(settings.guildId, DISCORD_ID_MAX_LENGTH);
  if (!discordUserId) {
    return {
      memberId: member.id,
      status: 'skipped',
      reason: 'missing_discord_id',
      expectedRoleIds,
      expectedRoleNames,
      actualRoleIds: [],
      actualRoleNames: [],
      roleNamesResolved,
      guildId
    };
  }
  const fetched = await fetchDiscordGuildMember(settings, discordUserId);
  if (!fetched.found) {
    return {
      memberId: member.id,
      discordUserId,
      status: DISCORD_MEMBERSHIP_NOT_IN_GUILD_STATUS,
      expectedRoleIds,
      expectedRoleNames,
      actualRoleIds: [],
      actualRoleNames: [],
      roleNamesResolved,
      guildId
    };
  }
  const actualRoleIds = [...new Set((Array.isArray(fetched.payload?.roles) ? fetched.payload.roles : [])
    .map((roleId) => normalizeText(roleId, DISCORD_ID_MAX_LENGTH))
    .filter(Boolean))];
  const actualRoleNames = discordMembershipRoleNamesForIds(actualRoleIds, roleNameById);
  const actualRoleSet = new Set(actualRoleIds);
  const hasExpectedRole = expectedRoleIds.length > 0 && expectedRoleIds.some((roleId) => actualRoleSet.has(roleId));
  return {
    memberId: member.id,
    discordUserId,
    status: hasExpectedRole ? DISCORD_MEMBERSHIP_VALID_STATUS : DISCORD_MEMBERSHIP_MISSING_ROLE_STATUS,
    expectedRoleIds,
    expectedRoleNames,
    actualRoleIds,
    actualRoleNames,
    roleNamesResolved,
    discordName: discordGuildMemberDisplayName(fetched.payload, member.discordName),
    guildId
  };
}

function applyDiscordMembershipAuditResultToMember(member, result = {}, checkedAt = nowIso()) {
  const currentStatus = discordMembershipAuditStatus(member);
  const nextStatus = normalizeText(result.status, 40);
  const previousExpectedRoleNameById = new Map(publicDiscordMembershipRoles(
    member.discordMembershipExpectedRoleIds,
    member.discordMembershipExpectedRoleNames
  ).map((role) => [role.id, role.name]));
  const previousActualRoleNameById = new Map(publicDiscordMembershipRoles(
    member.discordMembershipActualRoleIds,
    member.discordMembershipActualRoleNames
  ).map((role) => [role.id, role.name]));
  member.discordMembershipCheckedAt = checkedAt;
  member.discordMembershipGuildId = result.guildId || member.discordMembershipGuildId || '';
  member.discordMembershipExpectedRoleIds = Array.isArray(result.expectedRoleIds) ? result.expectedRoleIds : [];
  member.discordMembershipActualRoleIds = Array.isArray(result.actualRoleIds) ? result.actualRoleIds : [];
  if (result.roleNamesResolved !== false) {
    member.discordMembershipExpectedRoleNames = publicDiscordMembershipRoles(
      member.discordMembershipExpectedRoleIds,
      result.expectedRoleNames
    ).map((role) => role.name);
    member.discordMembershipActualRoleNames = publicDiscordMembershipRoles(
      member.discordMembershipActualRoleIds,
      result.actualRoleNames
    ).map((role) => role.name);
  } else {
    member.discordMembershipExpectedRoleNames = member.discordMembershipExpectedRoleIds
      .map((roleId) => previousExpectedRoleNameById.get(roleId) || roleId);
    member.discordMembershipActualRoleNames = member.discordMembershipActualRoleIds
      .map((roleId) => previousActualRoleNameById.get(roleId) || roleId);
  }
  if (result.discordName) member.discordName = normalizeText(result.discordName, 120);

  if (nextStatus === DISCORD_MEMBERSHIP_VALID_STATUS) {
    member.discordMembershipStatus = DISCORD_MEMBERSHIP_VALID_STATUS;
    member.discordMembershipMissingSince = '';
    member.discordMembershipLastOkAt = checkedAt;
    member.discordMembershipError = '';
  } else if (DISCORD_MEMBERSHIP_CANDIDATE_STATUSES.has(nextStatus)) {
    member.discordMembershipStatus = nextStatus;
    if (!DISCORD_MEMBERSHIP_CANDIDATE_STATUSES.has(currentStatus) || !member.discordMembershipMissingSince) {
      member.discordMembershipMissingSince = checkedAt;
    }
    member.discordMembershipError = '';
  } else if (nextStatus === DISCORD_MEMBERSHIP_CHECK_FAILED_STATUS) {
    if (!DISCORD_MEMBERSHIP_CANDIDATE_STATUSES.has(currentStatus)) {
      member.discordMembershipStatus = DISCORD_MEMBERSHIP_CHECK_FAILED_STATUS;
    }
    member.discordMembershipLastFailureAt = checkedAt;
    member.discordMembershipError = result.error || '';
  }

  member.updatedAt = checkedAt;
}

function discordMembershipAuditLogSummary(summary = {}) {
  return `Discord 成员角色检查：检查 ${summary.checked || 0} 人，标记 ${summary.flagged || 0} 人，失败 ${summary.failed || 0} 人`;
}

function applyDiscordMembershipAuditWrite(store, results = [], summary = {}, checkedAt = nowIso()) {
  const resultByMemberId = new Map(results.map((result) => [result.memberId, result]));
  for (const member of store.members || []) {
    const result = resultByMemberId.get(member.id);
    if (!result) continue;
    applyDiscordMembershipAuditResultToMember(member, result, checkedAt);
  }
  const nextSettings = discordSettings(store);
  nextSettings.memberAudit = {
    ...nextSettings.memberAudit,
    lastRunAt: checkedAt,
    lastRunError: '',
    checked: summary.checked,
    valid: summary.valid,
    flagged: summary.flagged,
    notInGuild: summary.notInGuild,
    missingRole: summary.missingRole,
    failed: summary.failed,
    skipped: summary.skipped
  };
}

async function writeDiscordMembershipAuditDirect(req, results = [], summary = {}, checkedAt = nowIso()) {
  if (!sqlitePrimaryMode()) return false;
  try {
    await runStoreWriteTask(async () => {
      const store = await readDiscordMembershipAuditStore();
      const before = snapshotStoreCollections(store, ['members']);
      applyDiscordMembershipAuditWrite(store, results, summary, checkedAt);
      const { upserts, deletes } = diffStoreCollections(before, store, ['members']);
      const log = createLogEntry(req, 'discord_member_audit', discordMembershipAuditLogSummary(summary), {
        actorUserId: req.user?.id || 'system',
        actorUsername: req.user?.username || 'system',
        metadata: summary
      });
      const patchResult = await writeSqliteStorePatch({
        reason: 'discord_member_audit',
        upserts: {
          ...upserts,
          logs: [log]
        },
        deletes,
        scalars: {
          settings: store.settings || {}
        },
        positions: {
          logs: { [log.id]: 0 }
        },
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        applyStoreCollectionCachePatch(cachedStore, ['members'], upserts, deletes);
        cachedStore.settings = store.settings || {};
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
    });
    return true;
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite discord membership audit fallback:', error?.message || error);
    return false;
  }
}

async function runDiscordMembershipAudit(req) {
  const snapshot = await readDiscordMembershipAuditStore();
  const settings = discordSettings(snapshot);
  const configuration = discordMembershipAuditConfiguration(snapshot);
  if (!configuration.tokenConfigured) {
    throw Object.assign(new Error('Discord Bot Token 尚未配置'), { status: 400 });
  }
  if (!configuration.guildId) {
    throw Object.assign(new Error('Discord Guild ID 尚未配置'), { status: 400 });
  }
  if (!configuration.roleIds.length) {
    throw Object.assign(new Error('Discord 成员角色规则尚未配置'), { status: 400 });
  }

  let roleNameById = new Map();
  let roleNamesResolved = false;
  try {
    roleNameById = await fetchDiscordGuildRoleNames(settings);
    roleNamesResolved = true;
  } catch (error) {
    console.warn('[nb-clan] Discord member audit role dictionary unavailable; falling back to role IDs:', error?.message || error);
  }

  const indexes = getStoreIndexes(snapshot);
  const targetMembers = (snapshot.members || [])
    .filter((member) => normalizeMemberStatus(member.memberStatus) === 'active')
    .filter((member) => validDiscordUserId(member.discordId));
  const checkedAt = nowIso();
  const results = [];
  for (const member of targetMembers) {
    try {
      results.push(await checkDiscordMembershipForMember(snapshot, member, settings, indexes, roleNameById, roleNamesResolved));
    } catch (error) {
      const expectedRoleIds = expectedDiscordRoleIdsForMember(snapshot, member, settings, indexes);
      results.push({
        memberId: member.id,
        discordUserId: validDiscordUserId(member.discordId),
        status: DISCORD_MEMBERSHIP_CHECK_FAILED_STATUS,
        expectedRoleIds,
        expectedRoleNames: discordMembershipRoleNamesForIds(expectedRoleIds, roleNameById),
        actualRoleIds: [],
        actualRoleNames: [],
        roleNamesResolved,
        guildId: configuration.guildId,
        error: normalizeText(error?.message || 'Discord member check failed', 240)
      });
    }
  }

  const summary = {
    checked: results.length,
    valid: results.filter((result) => result.status === DISCORD_MEMBERSHIP_VALID_STATUS).length,
    notInGuild: results.filter((result) => result.status === DISCORD_MEMBERSHIP_NOT_IN_GUILD_STATUS).length,
    missingRole: results.filter((result) => result.status === DISCORD_MEMBERSHIP_MISSING_ROLE_STATUS).length,
    failed: results.filter((result) => result.status === DISCORD_MEMBERSHIP_CHECK_FAILED_STATUS).length,
    skipped: (snapshot.members || []).filter((member) => normalizeMemberStatus(member.memberStatus) === 'active' && !validDiscordUserId(member.discordId)).length
  };
  summary.flagged = summary.notInGuild + summary.missingRole;

  const directWritten = await writeDiscordMembershipAuditDirect(req, results, summary, checkedAt);
  if (!directWritten) {
    await updateStore((store) => {
      applyDiscordMembershipAuditWrite(store, results, summary, checkedAt);
      appendLog(store, req, 'discord_member_audit', discordMembershipAuditLogSummary(summary), {
        actorUserId: req.user?.id || 'system',
        actorUsername: req.user?.username || 'system',
        metadata: summary
      });
    });
  }

  return { checkedAt, summary, results };
}

