async function writeMemberSteamProfileRefreshDirect(req, stats) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const store = await readMemberProfileRefreshWriteStore(req.params.id);
      const member = (store.members || []).find((item) => item.id === req.params.id);
      if (!member) throw Object.assign(new Error('成员不存在'), { status: 404 });
      if (!canManageMemberInStore(store, req.user, member)) {
        throw Object.assign(new Error('无权管理该成员'), { status: 403 });
      }

      const before = snapshotStoreCollections(store, ['members', 'memberProfiles']);
      const previousNickname = member.steamNickname || '';
      const previousAvatar = member.avatar || '';
      upsertMemberProfileCache(store, member, stats);
      member.updatedAt = nowIso();
      const log = createLogEntry(req, 'member_edit', `更新 Steam 数据 ${memberDisplayName(member)}`, {
        steamId: member.steamId,
        targetId: member.id,
        metadata: {
          previousNickname,
          steamNickname: member.steamNickname || '',
          avatarChanged: Boolean(member.avatar && member.avatar !== previousAvatar)
        }
      });
      const { upserts, deletes } = diffStoreCollections(before, store, ['members', 'memberProfiles']);
      const patchResult = await writeSqliteStorePatch({
        reason: 'member_steam_profile_refresh',
        upserts: { ...upserts, logs: [log] },
        deletes,
        trims: logTrimPatch()
      });
      const deletedLogIds = trimmedLogIds(patchResult);
      await patchStoreCache((cachedStore) => {
        applyStoreCollectionCachePatch(
          cachedStore,
          ['members', 'memberProfiles', 'logs'],
          { ...upserts, logs: [log] },
          { ...deletes, ...(deletedLogIds.length ? { logs: deletedLogIds } : {}) }
        );
      });
      return { memberId: member.id };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite member steam profile refresh fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('Steam 资料刷新写入', error);
  }
}

async function writeWechatProfileRefreshDirect(req, member, profileStats, {
  realtimeResult = null,
  profileOk = false,
  auditLog = true,
  reason = 'wechat_profile_refresh'
} = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const store = await readMemberProfileRefreshWriteStore(member?.id, { includeManagementContext: false });
      const current = (store.members || []).find((item) => item.id === member?.id && item.steamId === member?.steamId);
      if (!current) throw Object.assign(new Error('成员不存在'), { status: 404 });

      const collectionNames = ['members', 'memberProfiles'];
      const before = snapshotStoreCollections(store, collectionNames);
      const previousNickname = current.steamNickname || '';
      const previousAvatar = current.avatar || '';
      upsertMemberProfileCache(store, current, profileStats);
      const refreshedNickname = normalizeText(profileStats.steamDisplayName, 120);
      if (refreshedNickname) current.steamNickname = refreshedNickname;
      if (profileStats.avatar) current.avatar = profileStats.avatar;
      current.updatedAt = nowIso();
      const log = auditLog
        ? createLogEntry(req, 'wechat_profile_refresh', `微信刷新成员资料 ${memberDisplayName(current)}`, {
          steamId: current.steamId,
          targetId: current.id,
          actorUserId: `wechat:${req.wechatUser?.id || ''}`,
          actorUsername: requestActorUsername(req),
          metadata: {
            previousNickname,
            steamNickname: current.steamNickname || '',
            avatarChanged: Boolean(current.avatar && current.avatar !== previousAvatar),
            profileOk,
            profileError: profileStats.error || '',
            kdaSource: wechatProfileRefreshKdaSource(realtimeResult)
          }
        })
        : null;
      const { upserts, deletes } = diffStoreCollections(before, store, collectionNames);
      const patchUpserts = { ...upserts, ...(log ? { logs: [log] } : {}) };
      const patchResult = await writeSqliteStorePatch({
        reason,
        upserts: patchUpserts,
        deletes,
        trims: log ? logTrimPatch() : {}
      });
      const deletedLogIds = trimmedLogIds(patchResult);
      await patchStoreCache((cachedStore) => {
        applyStoreCollectionCachePatch(
          cachedStore,
          [...collectionNames, ...(log ? ['logs'] : [])],
          patchUpserts,
          { ...deletes, ...(deletedLogIds.length ? { logs: deletedLogIds } : {}) }
        );
      });
      return { memberId: current.id };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite wechat profile refresh fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('微信资料刷新写入', error);
  }
}

