async function writeWebSquadDirect(req, action, input = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedAction = action === 'edit' ? 'edit' : 'create';
      const body = input.body || req.body || {};
      const now = nowIso();
      const targetSquadId = normalizeText(input.squadId || req.params?.id, 120);
      const [targetSquads, permissionRoles] = await Promise.all([
        normalizedAction === 'edit' && targetSquadId
          ? readSqliteRecordsByIds('squads', [targetSquadId])
          : Promise.resolve([]),
        getSqliteCollection('permissionRoles', { limit: 0 })
      ]);
      const current = normalizedAction === 'edit'
        ? targetSquads.find((squad) => squad.id === targetSquadId && !squad.archivedAt)
        : null;
      if (normalizedAction === 'edit' && !current) {
        throw Object.assign(new Error('队伍不存在'), { status: 404 });
      }
      const permissionStore = memberRuntimeStoreShell({
        squads: current ? [current] : [],
        permissionRoles
      });
      if (normalizedAction === 'edit' && !canManageSquadInStore(permissionStore, req.user, current)) {
        throw Object.assign(new Error('无权管理该队伍'), { status: 403 });
      }

      let assignedLeaders = [];
      let members = [];
      let squadMembers = [];
      let leaderUserIds = [];
      if (normalizedAction === 'create') {
        leaderUserIds = input.leaderUserIds || requestedSquadLeaderIds(body);
        if (!leaderUserIds.length) throw Object.assign(new Error('请选择有效队长'), { status: 400 });
      } else if (
        canEditModuleInStore(permissionStore, req.user, 'squads') &&
        (Object.hasOwn(body || {}, 'leaderUserIds') || Object.hasOwn(body || {}, 'leaderUserId'))
      ) {
        leaderUserIds = requestedSquadLeaderIds(body);
        if (!leaderUserIds.length) throw Object.assign(new Error('请选择有效队长'), { status: 400 });
      }
      if (leaderUserIds.length) {
        const leaderUsers = await readSqliteRecordsByIds('users', leaderUserIds);
        ({ leaders: assignedLeaders, members, squadMembers } = await readSquadLeaderWriteContext(leaderUsers, leaderUserIds));
      }

      const store = memberRuntimeStoreShell({
        users: assignedLeaders,
        members,
        squads: current ? [current] : [],
        squadMembers,
        permissionRoles
      });
      const collectionNames = ['squads', 'members', 'squadMembers'];
      const before = snapshotStoreCollections(store, collectionNames);
      let targetSquad;
      if (normalizedAction === 'create') {
        const name = normalizeText(input.name || body?.name, 80);
        if (!name) throw Object.assign(new Error('队伍名称必填'), { status: 400 });
        targetSquad = {
          id: createId('squad'),
          name,
          leaderUserId: leaderUserIds[0],
          leaderUserIds,
          notes: normalizeText(body?.notes, 500),
          createdBy: req.user.id,
          createdAt: now,
          updatedAt: now,
          archivedAt: ''
        };
        store.squads.unshift(targetSquad);
      } else {
        const index = store.squads.findIndex((squad) => squad.id === current.id && !squad.archivedAt);
        const nextFields = {
          name: normalizeText(body?.name, 80) || current.name,
          notes: normalizeText(body?.notes, 500),
          updatedAt: now
        };
        if (assignedLeaders.length) {
          nextFields.leaderUserId = leaderUserIds[0];
          nextFields.leaderUserIds = leaderUserIds;
        }
        targetSquad = { ...current, ...nextFields };
        store.squads[index] = targetSquad;
      }
      assignedLeaders.forEach((leader) => ensureAccountMember(store, leader, { ensureSquad: false }));
      const logType = normalizedAction === 'edit' ? 'squad_edit' : 'squad_add';
      const log = createLogEntry(req, logType, `${normalizedAction === 'edit' ? '编辑队伍' : '创建队伍'} ${targetSquad.name}`, {
        targetId: targetSquad.id
      });
      const { upserts, deletes } = diffStoreCollections(before, store, collectionNames);
      await writeSqliteStorePatch({
        reason: logType,
        upserts: { ...upserts, logs: [log] },
        deletes
      });
      await patchStoreCache((cachedStore) => {
        applyStoreCollectionCachePatch(cachedStore, [...collectionNames, 'logs'], { ...upserts, logs: [log] }, deletes);
      });
      return { squadId: targetSquad.id };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite web squad write failed:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('队伍写入', error);
  }
}

async function writeWechatAdminSquadDirect(req, action, input = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedAction = action === 'delete' ? 'delete' : (action === 'edit' ? 'edit' : 'create');
      const squadId = normalizeText(input.squadId || req.params?.id, 120);
      const now = nowIso();

      if (normalizedAction === 'delete') {
        const [squadRecords, removedSquadMembers, activeWipes, plannedWipes, missingStatusWipes] = await Promise.all([
          squadId ? readSqliteRecordsByIds('squads', [squadId]) : Promise.resolve([]),
          squadId ? getSqliteRecordsByJsonField('squadMembers', 'squadId', [squadId], { limit: 0 }) : Promise.resolve([]),
          getSqliteRecordsByJsonField('wipes', 'status', ['active'], { limit: 0 }),
          getSqliteRecordsByJsonField('wipes', 'status', ['planned'], { limit: 0 }),
          getSqliteRecordsWhereJsonFieldMissing('wipes', 'status', { limit: 0 })
        ]);
        const squad = squadRecords.find((item) => item.id === squadId && !item.archivedAt);
        if (!squad) throw Object.assign(new Error('队伍不存在'), { status: 404 });
        const removedMemberIds = uniqueNormalizedTexts(removedSquadMembers.map((item) => item.memberId), 120);
        const removedMembersById = removedMemberIds.length ? await readSqliteRecordsByIds('members', removedMemberIds) : [];
        const membersById = new Map(removedMembersById.map((member) => [member.id, member]));
        const removedMembers = removedMemberIds.map((memberId) => membersById.get(memberId) || { id: memberId }).filter(Boolean);
        const deleteScope = liveMemberDeleteScope(removedMembers);
        const [wipeParticipantsByMember, wipeParticipantsBySteam, kdaRowsByMember, kdaRowsBySteam, kdaSnapshotsByMember, kdaSnapshotsBySteam] = await Promise.all([
          removedMemberIds.length ? getSqliteRecordsByJsonField('wipeParticipants', 'memberId', removedMemberIds, { limit: 0 }) : Promise.resolve([]),
          deleteScope.steamIds.size ? getSqliteRecordsByJsonField('wipeParticipants', 'steamId', [...deleteScope.steamIds], { limit: 0 }) : Promise.resolve([]),
          removedMemberIds.length ? getSqliteRecordsByJsonField('kdaRows', 'memberId', removedMemberIds, { limit: 0 }) : Promise.resolve([]),
          deleteScope.steamIds.size ? getSqliteRecordsByJsonField('kdaRows', 'steamId', [...deleteScope.steamIds], { limit: 0 }) : Promise.resolve([]),
          removedMemberIds.length ? getSqliteRecordsByJsonField('kdaSnapshots', 'memberId', removedMemberIds, { limit: 0 }) : Promise.resolve([]),
          deleteScope.steamIds.size ? getSqliteRecordsByJsonField('kdaSnapshots', 'steamId', [...deleteScope.steamIds], { limit: 0 }) : Promise.resolve([])
        ]);
        const store = {
          squads: [{ ...squad, archivedAt: now, updatedAt: now }],
          squadMembers: [],
          wipes: mergeRecordsById(activeWipes, plannedWipes, missingStatusWipes),
          wipeParticipants: mergeRecordsById(wipeParticipantsByMember, wipeParticipantsBySteam),
          kdaRows: mergeRecordsById(kdaRowsByMember, kdaRowsBySteam),
          kdaSnapshots: mergeRecordsById(kdaSnapshotsByMember, kdaSnapshotsBySteam)
        };
        const collectionNames = ['squads', 'squadMembers', 'wipeParticipants', 'kdaRows', 'kdaSnapshots'];
        const before = snapshotStoreCollections({
          squads: [squad],
          squadMembers: removedSquadMembers,
          wipeParticipants: store.wipeParticipants,
          kdaRows: store.kdaRows,
          kdaSnapshots: store.kdaSnapshots
        }, collectionNames);
        removeLiveMemberWipeRecords(store, removedMembers);
        const log = createLogEntry(req, 'wechat_admin_squad_delete', `微信管理删除队伍 ${squad.name}`, {
          targetId: squad.id,
          actorUserId: reviewActorId(req),
          actorUsername: requestActorUsername(req, 'wechat_admin')
        });
        const { upserts, deletes } = diffStoreCollections(before, store, collectionNames);
        await writeSqliteStorePatch({
          reason: 'wechat_admin_squad_delete',
          upserts: { ...upserts, logs: [log] },
          deletes
        });
        await patchStoreCache((cachedStore) => {
          applyStoreCollectionCachePatch(cachedStore, [...collectionNames, 'logs'], { ...upserts, logs: [log] }, deletes);
        });
        return { squadId: squad.id };
      }

      const targetSquads = normalizedAction === 'edit' && squadId
        ? await readSqliteRecordsByIds('squads', [squadId])
        : [];
      const current = normalizedAction === 'edit'
        ? targetSquads.find((squad) => squad.id === squadId && !squad.archivedAt)
        : null;
      if (normalizedAction === 'edit' && !current) {
        throw Object.assign(new Error('队伍不存在'), { status: 404 });
      }

      const leaderUserIds = normalizedAction === 'edit' && !Object.hasOwn(input.body || {}, 'leaderUserIds') && !Object.hasOwn(input.body || {}, 'leaderUserId')
        ? squadLeaderIds(current)
        : uniqueNormalizedTexts(input.leaderUserIds || requestedSquadLeaderIds(input.body || req.body || {}), 120);
      if (!leaderUserIds.length) throw Object.assign(new Error('请选择有效队长'), { status: 400 });
      const leaderUsers = await readSqliteRecordsByIds('users', leaderUserIds);
      const { leaders, members, squadMembers } = await readSquadLeaderWriteContext(leaderUsers, leaderUserIds);
      const store = memberRuntimeStoreShell({
        users: leaders,
        members,
        squads: current ? [current] : [],
        squadMembers,
        wipes: []
      });
      const collectionNames = ['squads', 'members', 'squadMembers'];
      const before = snapshotStoreCollections(store, collectionNames);

      let nextSquad;
      if (normalizedAction === 'create') {
        const name = normalizeText(input.name || input.body?.name, 80);
        if (!name) throw Object.assign(new Error('队伍名称必填'), { status: 400 });
        nextSquad = {
          id: createId('squad'),
          name,
          leaderUserId: leaderUserIds[0],
          leaderUserIds,
          color: normalizeText(input.body?.color, 40),
          iconUrl: normalizeText(input.body?.iconUrl || input.body?.icon, 500),
          notes: normalizeText(input.body?.notes, 500),
          createdBy: reviewActorId(req),
          createdAt: now,
          updatedAt: now,
          archivedAt: ''
        };
        store.squads.unshift(nextSquad);
      } else {
        const index = store.squads.findIndex((squad) => squad.id === current.id && !squad.archivedAt);
        nextSquad = {
          ...current,
          name: normalizeText(input.body?.name, 80) || current.name,
          leaderUserId: leaderUserIds[0],
          leaderUserIds,
          color: Object.hasOwn(input.body || {}, 'color') ? normalizeText(input.body?.color, 40) : (current.color || ''),
          iconUrl: Object.hasOwn(input.body || {}, 'iconUrl') || Object.hasOwn(input.body || {}, 'icon')
            ? normalizeText(input.body?.iconUrl || input.body?.icon, 500)
            : (current.iconUrl || current.icon || ''),
          notes: Object.hasOwn(input.body || {}, 'notes') ? normalizeText(input.body?.notes, 500) : (current.notes || ''),
          updatedAt: now
        };
        store.squads[index] = nextSquad;
      }
      leaders.forEach((leader) => ensureAccountMember(store, leader, { ensureSquad: false }));
      const logType = normalizedAction === 'edit' ? 'wechat_admin_squad_edit' : 'wechat_admin_squad_add';
      const log = createLogEntry(req, logType, `${normalizedAction === 'edit' ? '微信管理编辑队伍' : '微信管理创建队伍'} ${nextSquad.name}`, {
        targetId: nextSquad.id,
        actorUserId: reviewActorId(req),
        actorUsername: requestActorUsername(req, 'wechat_admin'),
        metadata: { leaderUserIds }
      });
      const { upserts, deletes } = diffStoreCollections(before, store, collectionNames);
      await writeSqliteStorePatch({
        reason: logType,
        upserts: { ...upserts, logs: [log] },
        deletes
      });
      await patchStoreCache((cachedStore) => {
        applyStoreCollectionCachePatch(cachedStore, [...collectionNames, 'logs'], { ...upserts, logs: [log] }, deletes);
      });
      return { squadId: nextSquad.id };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite wechat admin squad write failed:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('微信管理队伍写入', error);
  }
}

async function squadListPayloadForViewer(viewer) {
  await syncLeaderMembersForViewer(viewer);
  const store = await readSquadRuntimeStore({ includeMembers: false, activeOnlyWipes: true });
  if (!canUseSquadsInStore(store, viewer)) {
    return { forbidden: true, store, squads: [] };
  }
  return {
    forbidden: false,
    store,
    squads: visibleSquads(store, viewer).map((squad) => enrichSquad(store, squad, viewer))
  };
}

async function squadMemberPayloadForViewer(squadId, viewer, query = {}) {
  await syncLeaderMembersForViewer(viewer, { squadIds: [squadId], includeRoleLeaders: false });
  const viewerRole = normalizeRole(viewer?.role);
  const store = await readSquadMemberRuntimeStore(squadId, query, {
    viewer,
    includePermissionRoles: Boolean(viewerRole && !BUILTIN_ROLE_IDS.includes(viewerRole))
  });
  const squad = store.squads.find((item) => item.id === squadId && !item.archivedAt);
  if (!squad) return { status: 404, error: '队伍不存在' };
  if (!canViewSquadInStore(store, viewer, squad)) return { status: 403, error: '无权查看该队伍' };
  const squadPayload = enrichSquad(store, squad, viewer);
  const params = memberListQueryParams(query);
  const memberIds = new Set(store.squadMembers.filter((item) => item.squadId === squad.id).map((item) => item.memberId));
  const squadMembers = store.members.filter((member) => memberIds.has(member.id));
  const pageMembers = params.hasLimit ? squadMembers.slice(params.offset, params.offset + params.limit) : squadMembers;
  await hydrateMemberScopedRuntimeStore(store, pageMembers.map((member) => member.id));
  const payload = squadMemberListPayload(store, squad.id, viewer, query);
  return { status: 200, store, squad, squadPayload, ...payload };
}

async function candidateMembersPayloadForViewer(squadId, viewer) {
  await syncLeaderMembersForViewer(viewer);
  const viewerRole = normalizeRole(viewer?.role);
  const store = await readSquadCandidateRuntimeStore(squadId, {
    includePermissionRoles: Boolean(viewerRole && !BUILTIN_ROLE_IDS.includes(viewerRole))
  });
  const squad = store.squads.find((item) => item.id === squadId && !item.archivedAt);
  if (!squad) return { status: 404, error: '队伍不存在' };
  if (!canManageSquadInStore(store, viewer, squad)) return { status: 403, error: '无权管理该队伍' };
  return { status: 200, members: candidateMembersForSquad(store, viewer, squad) };
}

function liveMemberDeleteScope(targets = []) {
  if (targets?.memberIds instanceof Set || targets?.steamIds instanceof Set) {
    return {
      memberIds: new Set([...(targets.memberIds || [])].map((id) => normalizeText(id, 120)).filter(Boolean)),
      steamIds: new Set([...(targets.steamIds || [])].map((id) => normalizeText(id, 32)).filter(Boolean))
    };
  }
  const memberIds = new Set();
  const steamIds = new Set();
  const items = targets instanceof Set ? [...targets] : (Array.isArray(targets) ? targets : [targets]);
  for (const item of items) {
    if (!item) continue;
    if (typeof item === 'object') {
      const memberId = normalizeText(item.id || item.memberId || item.member?.id, 120);
      const steamId = normalizeText(item.steamId || item.member?.steamId, 32);
      if (memberId) memberIds.add(memberId);
      if (steamId) steamIds.add(steamId);
      continue;
    }
    const memberId = normalizeText(item, 120);
    if (memberId) memberIds.add(memberId);
  }
  return { memberIds, steamIds };
}

function liveMemberRecordMatchesDeleteScope(record = {}, scope = {}) {
  const memberId = normalizeText(record.memberId || record.member?.id, 120);
  const steamId = normalizeText(record.steamId || record.member?.steamId, 32);
  return Boolean(
    (memberId && scope.memberIds?.has(memberId)) ||
    (steamId && scope.steamIds?.has(steamId))
  );
}

function scopedLiveMemberRecordDeletes(records = [], targets = [], liveWipeIds = new Set()) {
  const deleteScope = liveMemberDeleteScope(targets);
  if ((!deleteScope.memberIds.size && !deleteScope.steamIds.size) || !liveWipeIds.size) return [];
  return records
    .filter((item) => liveWipeIds.has(item.wipeId) && liveMemberRecordMatchesDeleteScope(item, deleteScope))
    .map((item) => item.id)
    .filter(Boolean);
}

async function deleteSquadDirect(req, squadId) {
  if (!sqlitePrimaryMode()) {
    await updateStore((store) => {
      const index = store.squads.findIndex((squad) => squad.id === squadId && !squad.archivedAt);
      if (index === -1) throw Object.assign(new Error('队伍不存在'), { status: 404 });
      const squad = store.squads[index];
      const removedMemberIds = store.squadMembers
        .filter((item) => item.squadId === squad.id)
        .map((item) => item.memberId);
      const membersById = new Map((store.members || []).map((member) => [member.id, member]));
      const removedMembers = removedMemberIds.map((memberId) => membersById.get(memberId) || { id: memberId }).filter(Boolean);
      store.squads[index] = { ...squad, archivedAt: nowIso(), updatedAt: nowIso() };
      store.squadMembers = store.squadMembers.filter((item) => item.squadId !== squad.id);
      removeLiveMemberWipeRecords(store, removedMembers);
      appendLog(store, req, 'squad_delete', `删除队伍 ${squad.name}`, { targetId: squad.id });
    });
    return;
  }
  await runStoreWriteTask(async () => {
    const [squad, squadMembers, activeWipes, plannedWipes, missingStatusWipes] = await Promise.all([
      getSqliteRecord('squads', squadId),
      getSqliteRecordsByJsonField('squadMembers', 'squadId', [squadId], { limit: 0 }),
      getSqliteRecordsByJsonField('wipes', 'status', ['active'], { limit: 0 }),
      getSqliteRecordsByJsonField('wipes', 'status', ['planned'], { limit: 0 }),
      getSqliteRecordsWhereJsonFieldMissing('wipes', 'status', { limit: 0 })
    ]);
    if (!squad || squad.archivedAt) throw Object.assign(new Error('队伍不存在'), { status: 404 });
    const archivedSquad = { ...squad, archivedAt: nowIso(), updatedAt: nowIso() };
    const removedSquadMembers = squadMembers.filter((item) => item.squadId === squad.id);
    const removedMemberIds = [...new Set(removedSquadMembers.map((item) => item.memberId).filter(Boolean))];
    const members = removedMemberIds.length ? await readSqliteRecordsByIds('members', removedMemberIds) : [];
    const membersById = new Map(members.map((member) => [member.id, member]));
    const removedMembers = removedMemberIds.map((memberId) => membersById.get(memberId) || { id: memberId }).filter(Boolean);
    const deleteScope = liveMemberDeleteScope(removedMembers);
    const liveWipeIds = liveWipeIdSet({ wipes: mergeRecordsById(activeWipes, plannedWipes, missingStatusWipes) });
    const [wipeParticipants, kdaRows, kdaSnapshots] = removedMemberIds.length
      ? await Promise.all([
        getSqliteRecordsByJsonField('wipeParticipants', 'memberId', removedMemberIds, { limit: 0 }),
        Promise.all([
          getSqliteRecordsByJsonField('kdaRows', 'memberId', removedMemberIds, { limit: 0 }),
          deleteScope.steamIds.size ? getSqliteRecordsByJsonField('kdaRows', 'steamId', [...deleteScope.steamIds], { limit: 0 }) : Promise.resolve([])
        ]).then((groups) => [...new Map(groups.flat().map((item) => [item.id, item])).values()]),
        Promise.all([
          getSqliteRecordsByJsonField('kdaSnapshots', 'memberId', removedMemberIds, { limit: 0 }),
          deleteScope.steamIds.size ? getSqliteRecordsByJsonField('kdaSnapshots', 'steamId', [...deleteScope.steamIds], { limit: 0 }) : Promise.resolve([])
        ]).then((groups) => [...new Map(groups.flat().map((item) => [item.id, item])).values()])
      ])
      : [[], [], []];
    const log = createLogEntry(req, 'squad_delete', `删除队伍 ${squad.name}`, { targetId: squad.id });
    const patchResult = await writeSqliteStorePatch({
      reason: 'squad_delete',
      upserts: {
        squads: [archivedSquad],
        logs: [log]
      },
      deletes: {
        squadMembers: removedSquadMembers.map((item) => item.id).filter(Boolean),
        wipeParticipants: scopedLiveMemberRecordDeletes(wipeParticipants, deleteScope, liveWipeIds),
        kdaRows: scopedLiveMemberRecordDeletes(kdaRows, deleteScope, liveWipeIds),
        kdaSnapshots: scopedLiveMemberRecordDeletes(kdaSnapshots, deleteScope, liveWipeIds)
      },
      trims: logTrimPatch()
    });
    await patchStoreCache((store) => {
      store.squads ||= [];
      replaceCachedRecord(store.squads, archivedSquad);
      const removedSquadMemberIds = new Set(removedSquadMembers.map((item) => item.id));
      store.squadMembers = (store.squadMembers || []).filter((item) => !removedSquadMemberIds.has(item.id));
      const deleteFromCollection = (collection, ids) => {
        if (!ids?.length) return;
        const idSet = new Set(ids);
        store[collection] = (store[collection] || []).filter((item) => !idSet.has(item.id));
      };
      deleteFromCollection('wipeParticipants', scopedLiveMemberRecordDeletes(wipeParticipants, deleteScope, liveWipeIds));
      deleteFromCollection('kdaRows', scopedLiveMemberRecordDeletes(kdaRows, deleteScope, liveWipeIds));
      deleteFromCollection('kdaSnapshots', scopedLiveMemberRecordDeletes(kdaSnapshots, deleteScope, liveWipeIds));
      applyCachedLogPatch(store, [log], trimmedLogIds(patchResult));
    });
  });
}

async function writeSquadMembersDirect(req, squadId, input = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const action = input.action === 'remove' ? 'remove' : 'add';
      const memberIds = action === 'remove'
        ? [normalizeText(input.memberId, 120)].filter(Boolean)
        : [...new Set((Array.isArray(input.memberIds) ? input.memberIds : [])
          .map((id) => normalizeText(id, 120))
          .filter(Boolean))];
      const { store, squad } = action === 'remove'
        ? await readSquadMemberRemoveWriteRuntimeStore(squadId, memberIds[0])
        : await readSquadMemberAddWriteRuntimeStore(squadId, memberIds);
      if (!squad) throw Object.assign(new Error('队伍不存在'), { status: 404 });
      if (!canManageSquadInStore(store, req.user, squad)) {
        throw Object.assign(new Error('无权管理该队伍'), { status: 403 });
      }

      const before = {
        squadMembers: [...(store.squadMembers || [])],
        wipeParticipants: [...(store.wipeParticipants || [])],
        kdaRows: [...(store.kdaRows || [])],
        kdaSnapshots: [...(store.kdaSnapshots || [])]
      };

      let log;
      if (action === 'remove') {
        const memberId = memberIds[0] || '';
        const member = (store.members || []).find((item) => item.id === memberId) || { id: memberId };
        store.squadMembers = (store.squadMembers || []).filter((item) => !(item.squadId === squad.id && item.memberId === memberId));
        removeLiveMemberWipeRecords(store, [member]);
        log = createLogEntry(req, 'squad_member_remove', `队伍 ${squad.name} 移除成员`, { targetId: squad.id });
      } else {
        const membersById = new Map((store.members || []).map((member) => [member.id, member]));
        const currentSquadByMemberId = new Map((store.squadMembers || []).map((item) => [item.memberId, item]));
        const canAssignAnyMember = isAdmin(req.user) || canEditModuleInStore(store, req.user, 'squads');
        for (const memberId of memberIds) {
          const member = membersById.get(memberId);
          const currentSquadMember = currentSquadByMemberId.get(memberId);
          const alreadyInTargetSquad = currentSquadMember?.squadId === squad.id;
          const assignedToOtherSquad = currentSquadMember && currentSquadMember.squadId !== squad.id;
          const canAssignMember = Boolean(
            member &&
            !alreadyInTargetSquad &&
            (
              canAssignAnyMember ||
              (!assignedToOtherSquad && canManageMemberInStore(store, req.user, member))
            )
          );
          if (!canAssignMember) throw Object.assign(new Error('存在无权添加的成员'), { status: 403 });
          store.squadMembers = (store.squadMembers || []).filter((item) => item.memberId !== memberId);
          store.squadMembers.push({
            id: createId('squad_member'),
            squadId: squad.id,
            memberId,
            addedByUserId: req.user.id,
            createdAt: nowIso()
          });
          syncLiveMemberWipeSquadRecords(store, [memberId], squad.id);
        }
        log = createLogEntry(req, 'squad_member_add', `队伍 ${squad.name} 添加成员 ${memberIds.length} 人`, { targetId: squad.id });
      }

      const squadMemberPatch = recordPatchById(before.squadMembers, store.squadMembers);
      const wipeParticipantPatch = recordPatchById(before.wipeParticipants, store.wipeParticipants);
      const kdaRowPatch = recordPatchById(before.kdaRows, store.kdaRows);
      const kdaSnapshotPatch = recordPatchById(before.kdaSnapshots, store.kdaSnapshots);
      const patchResult = await writeSqliteStorePatch({
        reason: action === 'remove' ? 'squad_member_remove' : 'squad_member_add',
        upserts: {
          logs: [log],
          ...(squadMemberPatch.upserts.length ? { squadMembers: squadMemberPatch.upserts } : {}),
          ...(wipeParticipantPatch.upserts.length ? { wipeParticipants: wipeParticipantPatch.upserts } : {}),
          ...(kdaRowPatch.upserts.length ? { kdaRows: kdaRowPatch.upserts } : {}),
          ...(kdaSnapshotPatch.upserts.length ? { kdaSnapshots: kdaSnapshotPatch.upserts } : {})
        },
        deletes: {
          ...(squadMemberPatch.deletes.length ? { squadMembers: squadMemberPatch.deletes } : {}),
          ...(wipeParticipantPatch.deletes.length ? { wipeParticipants: wipeParticipantPatch.deletes } : {}),
          ...(kdaRowPatch.deletes.length ? { kdaRows: kdaRowPatch.deletes } : {}),
          ...(kdaSnapshotPatch.deletes.length ? { kdaSnapshots: kdaSnapshotPatch.deletes } : {})
        },
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        patchCachedScopedRecords(cachedStore, 'squadMembers', before.squadMembers, store.squadMembers);
        patchCachedScopedRecords(cachedStore, 'wipeParticipants', before.wipeParticipants, store.wipeParticipants);
        patchCachedScopedRecords(cachedStore, 'kdaRows', before.kdaRows, store.kdaRows);
        patchCachedScopedRecords(cachedStore, 'kdaSnapshots', before.kdaSnapshots, store.kdaSnapshots);
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return { squadId: squad.id, memberIds };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite squad members failed:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('队伍成员写入', error);
  }
}

function editedMemberRecordFromInput(before, { memberSelfEdit = false, editBody = {}, resolved = {}, nextProfile = {} } = {}) {
  return {
    ...before,
    steamId: memberSelfEdit ? before.steamId : resolved.steamId,
    rawInput: memberSelfEdit ? (before.rawInput || before.steamId) : (resolved.rawInput || before.rawInput),
    customName: normalizeText(editBody?.customName, 80),
    steamNickname: memberSelfEdit ? (before.steamNickname || '') : nextProfile.nickname,
    avatar: memberSelfEdit ? (before.avatar || '') : nextProfile.avatar,
    discordId: memberSelfEdit ? (before.discordId || '') : normalizeText(editBody?.discordId, 80),
    discordName: memberSelfEdit ? (before.discordName || '') : normalizeText(editBody?.discordName, 120),
    wechatId: memberSelfEdit ? (before.wechatId || '') : normalizeText(editBody?.wechatId, 80),
    wechatUserId: before.wechatUserId || '',
    phone: normalizeText(editBody?.phone, 80),
    notes: normalizeText(editBody?.notes, 240),
    specialty: normalizeMemberSpecialties(editBody?.specialty),
    ...normalizeMemberVipInput(editBody || {}, before),
    battlemetricsId: !memberSelfEdit && Object.hasOwn(editBody || {}, 'battlemetricsId') ? normalizeText(editBody?.battlemetricsId, 80) : before.battlemetricsId || '',
    updatedAt: nowIso()
  };
}

async function readMemberAssignmentSquadsForUser(user, permissionRoles = [], squadIds = []) {
  const permissionStore = memberRuntimeStoreShell({ permissionRoles, squads: [], squadMembers: [] });
  const needsLeaderSquadContext = isLeader(user) &&
    !canEditModuleInStore(permissionStore, user, 'members') &&
    !canEditModuleInStore(permissionStore, user, 'squads');
  if (needsLeaderSquadContext) return getSqliteCollection('squads', { limit: 0 });
  return readSqliteRecordsByIds('squads', uniqueNormalizedTexts(squadIds, 120));
}

async function updateMemberDirect(req, { editBody, memberSelfEdit, resolved, nextProfile } = {}) {
  if (!sqlitePrimaryMode()) {
    let updatedMemberId = req.params.id;
    const members = await updateStore((nextStore) => {
      const index = nextStore.members.findIndex((member) => member.id === req.params.id);
      if (index === -1) throw Object.assign(new Error('成员不存在'), { status: 404 });
      if (!canManageMemberInStore(nextStore, req.user, nextStore.members[index])) {
        throw Object.assign(new Error('无权管理该成员'), { status: 403 });
      }
      if (nextStore.members.some((member) => member.id !== req.params.id && member.steamId === resolved.steamId)) {
        throw Object.assign(new Error('该 SteamID 已经是成员'), { status: 409 });
      }
      const before = nextStore.members[index];
      const updated = editedMemberRecordFromInput(before, { memberSelfEdit, editBody, resolved, nextProfile });
      updatedMemberId = updated.id;
      nextStore.members[index] = updated;
      if (!memberSelfEdit && Object.hasOwn(editBody || {}, 'squadId')) {
        setMemberSquad(nextStore, updated, editBody.squadId, req.user);
      }
      appendLog(nextStore, req, 'member_edit', `编辑成员 ${memberDisplayName(updated)}`, {
        steamId: updated.steamId,
        targetId: updated.id,
        metadata: { beforeSteamId: before.steamId }
      });
      return enrichMembers(nextStore, req.user);
    });
    return { updatedMemberId, members };
  }
  return runStoreWriteTask(async () => {
    const targetMember = await getSqliteRecord('members', req.params.id);
    if (!targetMember) throw Object.assign(new Error('成员不存在'), { status: 404 });
    const normalizedSteamId = normalizeText(resolved?.steamId, 80);
    const requestedSquadId = !memberSelfEdit && Object.hasOwn(editBody || {}, 'squadId')
      ? normalizeText(editBody?.squadId, 80)
      : '';
    const [
      duplicateMembers,
      squadMembers,
      activeWipes,
      plannedWipes,
      missingStatusWipes,
      permissionRoles,
      wipeParticipants,
      kdaRows,
      kdaSnapshots
    ] = await Promise.all([
      normalizedSteamId ? getSqliteRecordsByJsonField('members', 'steamId', [normalizedSteamId], { limit: 0 }) : Promise.resolve([]),
      getSqliteRecordsByJsonField('squadMembers', 'memberId', [targetMember.id], { limit: 0 }),
      getSqliteRecordsByJsonField('wipes', 'status', ['active'], { limit: 0 }),
      getSqliteRecordsByJsonField('wipes', 'status', ['planned'], { limit: 0 }),
      getSqliteRecordsWhereJsonFieldMissing('wipes', 'status', { limit: 0 }),
      getSqliteCollection('permissionRoles', { limit: 0 }),
      getSqliteRecordsByJsonField('wipeParticipants', 'memberId', [req.params.id], { limit: 0 }),
      getSqliteRecordsByJsonField('kdaRows', 'memberId', [req.params.id], { limit: 0 }),
      getSqliteRecordsByJsonField('kdaSnapshots', 'memberId', [req.params.id], { limit: 0 })
    ]);
    const squadIds = uniqueNormalizedTexts([
      targetMember.squadId,
      requestedSquadId,
      ...(squadMembers || []).map((item) => item.squadId)
    ], 120);
    const squads = await readMemberAssignmentSquadsForUser(req.user, permissionRoles, squadIds);
    const members = mergeRecordsById([targetMember], duplicateMembers);
    const store = {
      users: [],
      members,
      squads,
      squadMembers,
      wipes: mergeRecordsById(activeWipes, plannedWipes, missingStatusWipes),
      permissionRoles,
      wipeParticipants: [...wipeParticipants],
      kdaRows: [...kdaRows],
      kdaSnapshots: [...kdaSnapshots],
      memberProfiles: [],
      settings: {},
      syncState: {}
    };
    const index = store.members.findIndex((member) => member.id === req.params.id);
    if (index === -1) throw Object.assign(new Error('成员不存在'), { status: 404 });
    if (!canManageMemberInStore(store, req.user, store.members[index])) {
      throw Object.assign(new Error('无权管理该成员'), { status: 403 });
    }
    if (store.members.some((member) => member.id !== req.params.id && member.steamId === resolved.steamId)) {
      throw Object.assign(new Error('该 SteamID 已经是成员'), { status: 409 });
    }
    const before = store.members[index];
    const updated = editedMemberRecordFromInput(before, { memberSelfEdit, editBody, resolved, nextProfile });
    store.members[index] = updated;
    const beforeSquadMembers = [...store.squadMembers];
    const beforeWipeParticipants = [...store.wipeParticipants];
    const beforeKdaRows = [...store.kdaRows];
    const beforeKdaSnapshots = [...store.kdaSnapshots];
    const shouldPatchSquad = !memberSelfEdit && Object.hasOwn(editBody || {}, 'squadId');
    if (shouldPatchSquad) {
      setMemberSquad(store, updated, editBody.squadId, req.user);
    }
    const squadMemberPatch = recordPatchById(beforeSquadMembers, store.squadMembers);
    const wipeParticipantPatch = recordPatchById(beforeWipeParticipants, store.wipeParticipants);
    const kdaRowPatch = recordPatchById(beforeKdaRows, store.kdaRows);
    const kdaSnapshotPatch = recordPatchById(beforeKdaSnapshots, store.kdaSnapshots);
    const log = createLogEntry(req, 'member_edit', `编辑成员 ${memberDisplayName(updated)}`, {
      steamId: updated.steamId,
      targetId: updated.id,
      metadata: { beforeSteamId: before.steamId }
    });
    const patchResult = await writeSqliteStorePatch({
      reason: 'member_edit',
      upserts: {
        members: [updated],
        logs: [log],
        ...(squadMemberPatch.upserts.length ? { squadMembers: squadMemberPatch.upserts } : {}),
        ...(wipeParticipantPatch.upserts.length ? { wipeParticipants: wipeParticipantPatch.upserts } : {}),
        ...(kdaRowPatch.upserts.length ? { kdaRows: kdaRowPatch.upserts } : {}),
        ...(kdaSnapshotPatch.upserts.length ? { kdaSnapshots: kdaSnapshotPatch.upserts } : {})
      },
      deletes: {
        ...(squadMemberPatch.deletes.length ? { squadMembers: squadMemberPatch.deletes } : {}),
        ...(wipeParticipantPatch.deletes.length ? { wipeParticipants: wipeParticipantPatch.deletes } : {}),
        ...(kdaRowPatch.deletes.length ? { kdaRows: kdaRowPatch.deletes } : {}),
        ...(kdaSnapshotPatch.deletes.length ? { kdaSnapshots: kdaSnapshotPatch.deletes } : {})
      },
      trims: logTrimPatch()
    });
    await patchStoreCache((cachedStore) => {
      cachedStore.members ||= [];
      replaceCachedRecord(cachedStore.members, updated);
      patchCachedScopedRecords(cachedStore, 'squadMembers', beforeSquadMembers, store.squadMembers);
      patchCachedScopedRecords(cachedStore, 'wipeParticipants', beforeWipeParticipants, store.wipeParticipants);
      patchCachedScopedRecords(cachedStore, 'kdaRows', beforeKdaRows, store.kdaRows);
      patchCachedScopedRecords(cachedStore, 'kdaSnapshots', beforeKdaSnapshots, store.kdaSnapshots);
      applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
    });
    return { updatedMemberId: updated.id, members: null };
  });
}

async function writeDiscordWipeSignupDirect(req, { wipeId, discordUserId, status, statusText, language } = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedWipeId = normalizeText(wipeId, 120);
      const normalizedDiscordUserId = normalizeText(discordUserId, DISCORD_ID_MAX_LENGTH);
      const normalizedStatus = normalizeParticipantStatus(status);
      const store = await readDiscordWipeSignupWriteStore(normalizedWipeId, normalizedDiscordUserId);
      const wipe = store.wipes.find((item) => item.id === normalizedWipeId);
      assertWipeMutable(wipe);
      const before = {
        wipes: cloneRecordsForPatch(store.wipes),
        members: cloneRecordsForPatch(store.members),
        wipeParticipants: cloneRecordsForPatch(store.wipeParticipants),
        kdaRows: cloneRecordsForPatch(store.kdaRows),
        kdaSnapshots: cloneRecordsForPatch(store.kdaSnapshots),
        discordAttendanceResponses: cloneRecordsForPatch(store.discordAttendanceResponses)
      };
      let addedMemberId = '';
      const member = store.members.find((item) => normalizeText(item.discordId, DISCORD_ID_MAX_LENGTH) === normalizedDiscordUserId);
      if (!member) {
        throw Object.assign(new Error(discordText(language, 'noBoundDiscordMember')), { status: 404 });
      }
      const squadsByMember = memberSquadMap(store);
      const squadId = squadsByMember.get(member.id)?.squadId || '';
      const now = nowIso();
      const index = store.wipeParticipants.findIndex((item) => item.wipeId === wipe.id && item.memberId === member.id);
      if (index === -1) {
        store.wipeParticipants.push({
          id: createId('wipe_participant'),
          wipeId: wipe.id,
          memberId: member.id,
          squadId,
          status: normalizedStatus,
          source: 'discord',
          sourceUserId: normalizedDiscordUserId,
          note: '',
          addedByUserId: `discord:${normalizedDiscordUserId}`,
          createdAt: now,
          updatedAt: now
        });
        addedMemberId = member.id;
        if (normalizedStatus === 'not_attending') {
          recordMemberNotAttending(store, { memberId: member.id, wipeId: wipe.id, source: 'discord', at: now });
        }
      } else {
        const participant = store.wipeParticipants[index];
        const previousStatus = normalizeParticipantStatus(participant.status);
        store.wipeParticipants[index] = {
          ...participant,
          squadId: participant.squadId || squadId,
          status: normalizedStatus,
          source: 'discord',
          sourceUserId: normalizedDiscordUserId,
          note: '',
          addedByUserId: participant.addedByUserId || `discord:${normalizedDiscordUserId}`,
          updatedAt: now
        };
        if (normalizedStatus === 'not_attending' && previousStatus !== 'not_attending') {
          recordMemberNotAttending(store, { memberId: member.id, wipeId: wipe.id, source: 'discord', at: now });
        }
      }
      upsertDiscordAttendanceResponse(store, {
        wipeId: wipe.id,
        discordUserId: normalizedDiscordUserId,
        displayName: memberDisplayName(member),
        status: normalizedStatus
      });
      if (isWipeStartedServer(wipe)) syncKdaRows(store, wipe);
      const log = createLogEntry(req, 'discord_wipe_signup', `Discord attendance ${memberDisplayName(member)} ${statusText}`, {
        targetId: wipe.id,
        steamId: member.steamId,
        metadata: { discordUserId: normalizedDiscordUserId, status: normalizedStatus }
      });

      const wipesPatch = collectionFullPatchFromBeforeAfter(before.wipes, store.wipes);
      const membersPatch = collectionFullPatchFromBeforeAfter(before.members, store.members);
      const wipeParticipantPatch = collectionFullPatchFromBeforeAfter(before.wipeParticipants, store.wipeParticipants);
      const kdaRowPatch = collectionFullPatchFromBeforeAfter(before.kdaRows, store.kdaRows);
      const kdaSnapshotPatch = collectionFullPatchFromBeforeAfter(before.kdaSnapshots, store.kdaSnapshots);
      const discordAttendancePatch = collectionFullPatchFromBeforeAfter(before.discordAttendanceResponses, store.discordAttendanceResponses);
      const patchResult = await writeSqliteStorePatch({
        reason: 'discord_wipe_signup',
        upserts: {
          ...(wipesPatch.upserts.length ? { wipes: wipesPatch.upserts } : {}),
          ...(membersPatch.upserts.length ? { members: membersPatch.upserts } : {}),
          ...(wipeParticipantPatch.upserts.length ? { wipeParticipants: wipeParticipantPatch.upserts } : {}),
          ...(kdaRowPatch.upserts.length ? { kdaRows: kdaRowPatch.upserts } : {}),
          ...(kdaSnapshotPatch.upserts.length ? { kdaSnapshots: kdaSnapshotPatch.upserts } : {}),
          ...(discordAttendancePatch.upserts.length ? { discordAttendanceResponses: discordAttendancePatch.upserts } : {}),
          logs: [log]
        },
        deletes: {
          ...(wipeParticipantPatch.deletes.length ? { wipeParticipants: wipeParticipantPatch.deletes } : {}),
          ...(kdaRowPatch.deletes.length ? { kdaRows: kdaRowPatch.deletes } : {}),
          ...(kdaSnapshotPatch.deletes.length ? { kdaSnapshots: kdaSnapshotPatch.deletes } : {}),
          ...(discordAttendancePatch.deletes.length ? { discordAttendanceResponses: discordAttendancePatch.deletes } : {})
        },
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        patchCachedScopedRecords(cachedStore, 'wipes', before.wipes, store.wipes);
        patchCachedScopedRecords(cachedStore, 'members', before.members, store.members);
        patchCachedScopedRecords(cachedStore, 'wipeParticipants', before.wipeParticipants, store.wipeParticipants);
        patchCachedScopedRecords(cachedStore, 'kdaRows', before.kdaRows, store.kdaRows);
        patchCachedScopedRecords(cachedStore, 'kdaSnapshots', before.kdaSnapshots, store.kdaSnapshots);
        patchCachedScopedRecords(cachedStore, 'discordAttendanceResponses', before.discordAttendanceResponses, store.discordAttendanceResponses);
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return { addedMemberId, updatedWipeId: wipe.id };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite discord wipe signup fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('Discord 报名写入', error);
  }
}

async function writeWebWipeParticipantsDirect(req, action, input = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const store = await readWebWipeParticipantWriteStore(req.params.id, action, input, req);
      const wipe = store.wipes.find((item) => item.id === req.params.id);
      assertWipeMutable(wipe);
      const before = {
        members: cloneRecordsForPatch(store.members),
        wipeParticipants: cloneRecordsForPatch(store.wipeParticipants),
        kdaRows: cloneRecordsForPatch(store.kdaRows),
        kdaSnapshots: cloneRecordsForPatch(store.kdaSnapshots)
      };
      const addedMemberIds = [];
      const updatedWipeId = wipe.id;
      let localGeneratedKdaSynced = false;
      let log = null;

      if (action === 'self_signup') {
        const status = normalizeWechatWipeSignupStatus(input.status);
        const result = upsertWebMemberWipeSignup(store, { wipe, user: req.user, status });
        if (result.added) addedMemberIds.push(result.member.id);
        if (isWipeStartedServer(wipe)) {
          syncKdaRows(store, wipe);
          localGeneratedKdaSynced = process.env.NB_DISABLE_EXTERNAL_VITAL === '1';
        }
        const statusText = attendanceStatusText(status, { language: 'zh', context: 'wechat' });
        log = createLogEntry(req, 'wipe_member_signup', `Web 自助报名 ${memberDisplayName(result.member)} ${statusText}`, {
          targetId: wipe.id,
          steamId: result.member.steamId,
          actorUserId: req.user.id,
          actorUsername: req.user.username,
          metadata: { memberId: result.member.id, status, source: 'web' }
        });
      } else if (action === 'add') {
        const memberIds = [...new Set((Array.isArray(input.memberIds) ? input.memberIds : [])
          .map((id) => normalizeText(id, 80))
          .filter(Boolean))];
        const status = normalizeParticipantStatus(input.status);
        const note = normalizeText(input.note, 500);
        const candidates = new Map(participantCandidates(store, wipe, req.user).map((member) => [member.id, member]));
        const squadsByMember = memberSquadMap(store);
        const captainSquads = leaderSquads(store, req.user);
        for (const memberId of memberIds) {
          const member = candidates.get(memberId);
          if (!member) throw Object.assign(new Error('存在无权添加的参与人员'), { status: 403 });
          if (store.wipeParticipants.some((item) => item.wipeId === wipe.id && item.memberId === memberId)) continue;
          const memberSquadId = squadsByMember.get(memberId)?.squadId || '';
          const squadId = memberSquadId || captainSquads[0]?.id || '';
          const now = nowIso();
          store.wipeParticipants.push({
            id: createId('wipe_participant'),
            wipeId: wipe.id,
            memberId,
            squadId,
            status,
            source: 'admin',
            sourceUserId: req.user.id,
            note,
            addedByUserId: req.user.id,
            createdAt: now,
            updatedAt: now
          });
          if (status === 'not_attending') {
            recordMemberNotAttending(store, { memberId, wipeId: wipe.id, source: 'admin', at: now });
          }
          addedMemberIds.push(memberId);
        }
        log = createLogEntry(req, 'wipe_participant_add', `当前档添加参与人员 ${memberIds.length} 人`, { targetId: wipe.id });
      } else if (action === 'edit') {
        const status = normalizeParticipantStatus(input.status);
        const memberId = normalizeText(input.memberId, 120);
        const index = store.wipeParticipants.findIndex((item) => item.wipeId === wipe.id && item.memberId === memberId);
        if (index === -1) throw Object.assign(new Error('参与人员不存在'), { status: 404 });
        const participant = store.wipeParticipants[index];
        const member = store.members.find((item) => item.id === participant.memberId);
        const captainSquads = leaderSquads(store, req.user);
        const memberSquad = memberSquadMap(store).get(member?.id);
        const leaderSquad = memberSquad
          ? captainSquads.find((squad) => squad.id === memberSquad.squadId) || null
          : captainSquads[0] || null;
        if (!canManageWipeParticipant(req.user, member, memberSquad, leaderSquad)) {
          throw Object.assign(new Error('无权管理该参与人员'), { status: 403 });
        }
        let squadId = participant.squadId;
        if (isAdmin(req.user) && Object.hasOwn(req.body || {}, 'squadId')) {
          const requestedSquadId = normalizeText(req.body.squadId, 80);
          if (requestedSquadId && !activeSquads(store).some((squad) => squad.id === requestedSquadId)) {
            throw Object.assign(new Error('队伍不存在'), { status: 404 });
          }
          squadId = requestedSquadId;
        } else if (leaderSquad) {
          squadId = leaderSquad.id;
        }
        const previousStatus = normalizeParticipantStatus(participant.status);
        const now = nowIso();
        store.wipeParticipants[index] = {
          ...participant,
          status,
          squadId,
          source: 'admin',
          sourceUserId: req.user.id,
          updatedAt: now
        };
        if (status === 'not_attending' && previousStatus !== 'not_attending') {
          recordMemberNotAttending(store, { memberId: member.id, wipeId: wipe.id, source: 'admin', at: now });
        }
        log = createLogEntry(req, 'wipe_participant_edit', '当前档修改参与人员', { targetId: wipe.id });
      } else if (action === 'remove') {
        const memberId = normalizeText(input.memberId, 120);
        const participant = store.wipeParticipants.find((item) => item.wipeId === wipe.id && item.memberId === memberId);
        if (!participant) throw Object.assign(new Error('参与人员不存在'), { status: 404 });
        const member = store.members.find((item) => item.id === participant.memberId);
        const captainSquads = leaderSquads(store, req.user);
        const memberSquad = memberSquadMap(store).get(member?.id);
        const leaderSquad = memberSquad
          ? captainSquads.find((squad) => squad.id === memberSquad.squadId) || null
          : captainSquads[0] || null;
        if (!canManageWipeParticipant(req.user, member, memberSquad, leaderSquad)) {
          throw Object.assign(new Error('无权管理该参与人员'), { status: 403 });
        }
        store.wipeParticipants = store.wipeParticipants.filter((item) => !(item.wipeId === wipe.id && item.memberId === memberId));
        log = createLogEntry(req, 'wipe_participant_remove', '当前档移除参与人员', { targetId: wipe.id });
      } else {
        throw Object.assign(new Error('未知参与人操作'), { status: 400 });
      }

      const membersPatch = collectionFullPatchFromBeforeAfter(before.members, store.members);
      const wipeParticipantPatch = collectionFullPatchFromBeforeAfter(before.wipeParticipants, store.wipeParticipants);
      const kdaRowPatch = collectionFullPatchFromBeforeAfter(before.kdaRows, store.kdaRows);
      const kdaSnapshotPatch = collectionFullPatchFromBeforeAfter(before.kdaSnapshots, store.kdaSnapshots);
      const patchResult = await writeSqliteStorePatch({
        reason: `web_wipe_participant_${action}`,
        upserts: {
          ...(membersPatch.upserts.length ? { members: membersPatch.upserts } : {}),
          ...(wipeParticipantPatch.upserts.length ? { wipeParticipants: wipeParticipantPatch.upserts } : {}),
          ...(kdaRowPatch.upserts.length ? { kdaRows: kdaRowPatch.upserts } : {}),
          ...(kdaSnapshotPatch.upserts.length ? { kdaSnapshots: kdaSnapshotPatch.upserts } : {}),
          ...(log ? { logs: [log] } : {})
        },
        deletes: {
          ...(wipeParticipantPatch.deletes.length ? { wipeParticipants: wipeParticipantPatch.deletes } : {}),
          ...(kdaRowPatch.deletes.length ? { kdaRows: kdaRowPatch.deletes } : {}),
          ...(kdaSnapshotPatch.deletes.length ? { kdaSnapshots: kdaSnapshotPatch.deletes } : {})
        },
        trims: log ? logTrimPatch() : {}
      });
      await patchStoreCache((cachedStore) => {
        patchCachedScopedRecords(cachedStore, 'members', before.members, store.members);
        patchCachedScopedRecords(cachedStore, 'wipeParticipants', before.wipeParticipants, store.wipeParticipants);
        patchCachedScopedRecords(cachedStore, 'kdaRows', before.kdaRows, store.kdaRows);
        patchCachedScopedRecords(cachedStore, 'kdaSnapshots', before.kdaSnapshots, store.kdaSnapshots);
        if (log) applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return { addedMemberIds, updatedWipeId, localGeneratedKdaSynced };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite web wipe participant fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('Web 当前档参与人员写入', error);
  }
}

function buildWebWipeCreateDraft(req, createdAt = nowIso()) {
  const serverPreset = wipeServerPresetFromInput(req.body);
  const serverPresetId = normalizeText(req.body?.serverPresetId, 80) || serverPreset?.id || '';
  const serverName = normalizeText(req.body?.serverName, 120) || serverPreset?.name || '';
  const vitalServerId = normalizeText(req.body?.vitalServerId, 80);
  const vitalWipeId = normalizeText(req.body?.vitalWipeId, 120);
  const vitalServer = VITAL_RUST_2X_SERVERS.find((server) => server.vitalServerId === vitalServerId);
  const battlemetricsId = normalizeText(req.body?.battlemetricsId, 80) || serverPreset?.battlemetricsId || vitalServer?.battlemetricsId || '';
  const clientTimeZone = normalizeClientTimeZone(req.body);
  const startedAt = normalizeWipeDateTimeInput(req.body?.startedAt) || createdAt;
  const nextWipeAt = normalizeWipeDateTimeInput(req.body?.nextWipeAt);
  const wipeLabel = normalizeText(req.body?.wipeLabel, 120) || (vitalWipeId ? 'Current' : 'Planned');
  const requestedKdaProvider = normalizeText(req.body?.kdaProvider, 40).toLowerCase();
  return {
    id: createId('wipe'),
    name: normalizeText(req.body?.name, 120) || `${serverName} ${startedAt.slice(0, 10)}`,
    status: 'active',
    serverName,
    startedAt,
    startedAtTimeZone: clientTimeZone,
    closedAt: '',
    wipeLabel,
    wipeMode: normalizeText(req.body?.wipeMode, 40),
    nextWipeAt,
    nextWipeAtTimeZone: nextWipeAt ? clientTimeZone : '',
    directConnect: normalizeText(req.body?.directConnect, 240) || serverPreset?.directConnect || '',
    vipUrl: normalizeText(req.body?.vipUrl, 240) || serverPreset?.vipUrl || '',
    mapLink: normalizeText(req.body?.mapLink, 500),
    rustMapsLink: normalizeText(req.body?.rustMapsLink, 500),
    notes: normalizeText(req.body?.notes, 1000),
    serverPresetId,
    serverVipProvider: normalizeServerVipProvider(req.body?.serverVipProvider) || serverPreset?.serverVipProvider || '',
    kdaProvider: KDA_PROVIDERS.has(requestedKdaProvider)
      ? requestedKdaProvider
      : (serverPreset?.kdaProvider || (vitalServerId ? 'vital' : 'manual')),
    vitalServerId,
    vitalWipeId,
    battlemetricsId,
    kdaUrl: normalizeText(req.body?.kdaUrl, 500) || buildKdaUrl(vitalServerId, vitalWipeId),
    createdBy: req.user.id,
    createdAt,
    updatedAt: createdAt
  };
}

function buildWebWipeEditDraft(req, wipe) {
  const hasServerPresetId = Object.hasOwn(req.body || {}, 'serverPresetId');
  const requestedServerPresetId = normalizeText(req.body?.serverPresetId, 80);
  const serverPresetId = hasServerPresetId ? requestedServerPresetId : (wipe.serverPresetId || '');
  const vitalServerId = normalizeText(req.body?.vitalServerId, 80);
  const vitalWipeId = normalizeText(req.body?.vitalWipeId, 120);
  const vitalServer = VITAL_RUST_2X_SERVERS.find((server) => server.vitalServerId === vitalServerId);
  const serverPreset = wipeServerPresetById(serverPresetId) || vitalServer;
  const battlemetricsId = Object.hasOwn(req.body || {}, 'battlemetricsId')
    ? (normalizeText(req.body?.battlemetricsId, 80) || serverPreset?.battlemetricsId || '')
    : (serverPreset?.battlemetricsId || wipe.battlemetricsId || '');
  const serverName = normalizeText(req.body?.serverName, 120) || serverPreset?.name || wipe.serverName;
  const clientTimeZone = normalizeClientTimeZone(req.body);
  const startedAt = normalizeWipeDateTimeInput(req.body?.startedAt) || wipe.startedAt;
  const nextWipeAt = normalizeWipeDateTimeInput(req.body?.nextWipeAt);
  const rustMapsLink = normalizeText(req.body?.rustMapsLink, 500);
  const rustMapsLinkChanged = normalizeRustMapsMapUrl(rustMapsLink) !== normalizeRustMapsMapUrl(wipe.rustMapsLink);
  const requestedKdaProvider = normalizeText(req.body?.kdaProvider, 40).toLowerCase();
  const kdaProvider = Object.hasOwn(req.body || {}, 'kdaProvider')
    ? (KDA_PROVIDERS.has(requestedKdaProvider) ? requestedKdaProvider : (serverPreset?.kdaProvider || (vitalServerId ? 'vital' : 'manual')))
    : (wipe.kdaProvider || serverPreset?.kdaProvider || (vitalServerId ? 'vital' : 'manual'));
  return {
    ...wipe,
    name: normalizeText(req.body?.name, 120) || `${serverName} ${startedAt.slice(0, 10)}`,
    serverName,
    startedAt,
    startedAtTimeZone: clientTimeZone || wipe.startedAtTimeZone || '',
    wipeLabel: normalizeText(req.body?.wipeLabel, 120) || wipe.wipeLabel || '',
    wipeMode: normalizeText(req.body?.wipeMode, 40) || wipe.wipeMode || '',
    nextWipeAt,
    nextWipeAtTimeZone: nextWipeAt ? (clientTimeZone || wipe.nextWipeAtTimeZone || '') : '',
    directConnect: normalizeText(req.body?.directConnect, 240),
    vipUrl: normalizeText(req.body?.vipUrl, 240),
    mapLink: normalizeText(req.body?.mapLink, 500),
    rustMapsLink,
    ...(rustMapsLinkChanged ? {
      rustMapsImageUrl: '',
      rustMapsImageSourceUrl: '',
      rustMapsImageUpdatedAt: '',
      rustMapsImageError: '',
      rustMapsImageErrorAt: ''
    } : {}),
    notes: normalizeText(req.body?.notes, 1000),
    serverPresetId,
    serverVipProvider: Object.hasOwn(req.body || {}, 'serverVipProvider')
      ? (normalizeServerVipProvider(req.body?.serverVipProvider) || serverPreset?.serverVipProvider || '')
      : (wipe.serverVipProvider || serverPreset?.serverVipProvider || ''),
    kdaProvider,
    vitalServerId,
    vitalWipeId,
    battlemetricsId,
    kdaUrl: normalizeText(req.body?.kdaUrl, 500) || buildKdaUrl(vitalServerId, vitalWipeId),
    updatedAt: nowIso()
  };
}

async function createWebWipeDirect(req) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const wipes = await getSqliteRecordsByJsonField('wipes', 'status', ['active'], { limit: 0 });
      if (currentWipe({ wipes })) throw Object.assign(new Error('已经存在进行中的档期'), { status: 409 });
      const wipe = buildWebWipeCreateDraft(req);
      const log = createLogEntry(req, 'wipe_create', `创建当前档 ${wipe.name}`, { targetId: wipe.id });
      const patchResult = await writeSqliteStorePatch({
        reason: 'wipe_create',
        upserts: {
          wipes: [wipe],
          logs: [log]
        },
        positions: {
          wipes: { [wipe.id]: 0 },
          logs: { [log.id]: 0 }
        },
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        cachedStore.wipes ||= [];
        cachedStore.wipes = cachedStore.wipes.filter((item) => item.id !== wipe.id);
        cachedStore.wipes.unshift(wipe);
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return wipe.id;
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite web wipe create fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('档期创建写入', error);
  }
}

async function updateWebWipeDirect(req) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const wipe = await getSqliteRecord('wipes', req.params.id);
      assertWipeMutable(wipe);
      const nextWipe = buildWebWipeEditDraft(req, wipe);
      const log = createLogEntry(req, 'wipe_edit', `编辑当前档 ${nextWipe.name}`, { targetId: wipe.id });
      const patchResult = await writeSqliteStorePatch({
        reason: 'wipe_edit',
        upserts: {
          wipes: [nextWipe],
          logs: [log]
        },
        positions: {
          logs: { [log.id]: 0 }
        },
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        cachedStore.wipes ||= [];
        replaceCachedRecord(cachedStore.wipes, nextWipe);
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return nextWipe.id;
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite web wipe edit fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('档期编辑写入', error);
  }
}

async function deleteWebWipeDirect(req) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedWipeId = normalizeText(req.params.id, 120);
      const [
        wipe,
        wipeParticipants,
        kdaRows,
        kdaSnapshots,
        wipeSettlements,
        uploads
      ] = await Promise.all([
        getSqliteRecord('wipes', normalizedWipeId),
        getSqliteRecordsByJsonField('wipeParticipants', 'wipeId', [normalizedWipeId], { limit: 0 }),
        getSqliteRecordsByJsonField('kdaRows', 'wipeId', [normalizedWipeId], { limit: 0 }),
        getSqliteRecordsByJsonField('kdaSnapshots', 'wipeId', [normalizedWipeId], { limit: 0 }),
        getSqliteRecordsByJsonField('wipeSettlements', 'wipeId', [normalizedWipeId], { limit: 0 }),
        getSqliteRecordsByJsonField('uploads', 'ownerId', [normalizedWipeId], { limit: 0 })
      ]);
      if (!wipe) throw Object.assign(new Error('档期不存在'), { status: 404 });
      if (wipe.status !== 'closed') throw Object.assign(new Error('进行中的档期请先结档'), { status: 409 });
      const uploadsToDelete = (uploads || []).filter((upload) => upload.ownerType === 'wipe' && upload.ownerId === wipe.id);
      const log = createLogEntry(req, 'wipe_delete', `删除档案 ${wipe.name}`, { targetId: wipe.id });
      const patchResult = await writeSqliteStorePatch({
        reason: 'wipe_delete',
        upserts: { logs: [log] },
        deletes: {
          wipes: [wipe.id],
          ...(wipeParticipants.length ? { wipeParticipants: wipeParticipants.map((item) => item.id) } : {}),
          ...(kdaRows.length ? { kdaRows: kdaRows.map((item) => item.id) } : {}),
          ...(kdaSnapshots.length ? { kdaSnapshots: kdaSnapshots.map((item) => item.id) } : {}),
          ...(wipeSettlements.length ? { wipeSettlements: wipeSettlements.map((item) => item.id) } : {}),
          ...(uploadsToDelete.length ? { uploads: uploadsToDelete.map((item) => item.id) } : {})
        },
        positions: {
          logs: { [log.id]: 0 }
        },
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        cachedStore.wipes = (cachedStore.wipes || []).filter((item) => item.id !== wipe.id);
        cachedStore.wipeParticipants = (cachedStore.wipeParticipants || []).filter((item) => item.wipeId !== wipe.id);
        cachedStore.kdaRows = (cachedStore.kdaRows || []).filter((item) => item.wipeId !== wipe.id);
        cachedStore.kdaSnapshots = (cachedStore.kdaSnapshots || []).filter((item) => item.wipeId !== wipe.id);
        cachedStore.wipeSettlements = (cachedStore.wipeSettlements || []).filter((item) => item.wipeId !== wipe.id);
        cachedStore.uploads = (cachedStore.uploads || []).filter((item) => !(item.ownerType === 'wipe' && item.ownerId === wipe.id));
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return { wipe, uploads: uploadsToDelete };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite web wipe delete fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('档期删除写入', error);
  }
}

async function writeWipeUploadDirect(req, upload, { logType, logMessage } = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const wipe = await getSqliteRecord('wipes', req.params.id);
      assertWipeMutable(wipe);
      const nextUpload = { ...upload, ownerType: 'wipe', ownerId: wipe.id };
      const summary = typeof logMessage === 'function' ? logMessage(nextUpload, wipe) : logMessage;
      const log = createLogEntry(req, logType || 'wipe_upload', summary || '更新档期附件', { targetId: wipe.id });
      const patchResult = await writeSqliteStorePatch({
        reason: logType || 'wipe_upload',
        upserts: {
          uploads: [nextUpload],
          logs: [log]
        },
        positions: {
          uploads: { [nextUpload.id]: 0 },
          logs: { [log.id]: 0 }
        },
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        cachedStore.uploads ||= [];
        cachedStore.uploads = cachedStore.uploads.filter((item) => item.id !== nextUpload.id);
        cachedStore.uploads.unshift(nextUpload);
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return nextUpload;
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite wipe upload fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('档期附件写入', error);
  }
}

async function deleteWipeUploadDirect(req, { allowedKinds = [], notFoundMessage = '上传不存在', logType, logMessage } = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const [wipe, upload] = await Promise.all([
        getSqliteRecord('wipes', req.params.id),
        getSqliteRecord('uploads', req.params.uploadId)
      ]);
      assertWipeMutable(wipe);
      const kindSet = new Set((allowedKinds || []).map((kind) => normalizeText(kind, 80)).filter(Boolean));
      if (!upload || upload.ownerType !== 'wipe' || upload.ownerId !== wipe.id || (kindSet.size && !kindSet.has(upload.kind))) {
        throw Object.assign(new Error(notFoundMessage), { status: 404 });
      }
      const summary = typeof logMessage === 'function' ? logMessage(upload, wipe) : logMessage;
      const log = createLogEntry(req, logType || 'wipe_upload_delete', summary || '删除档期附件', { targetId: wipe.id });
      const patchResult = await writeSqliteStorePatch({
        reason: logType || 'wipe_upload_delete',
        upserts: { logs: [log] },
        deletes: { uploads: [upload.id] },
        positions: { logs: { [log.id]: 0 } },
        trims: logTrimPatch()
      });
      await patchStoreCache((cachedStore) => {
        cachedStore.uploads = (cachedStore.uploads || []).filter((item) => item.id !== upload.id);
        applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return upload;
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite wipe upload delete fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('档期附件删除写入', error);
  }
}

async function writeWechatAdminWipeParticipantsDirect(req, action, input = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const requestedWipeId = normalizeText(input.requestedWipeId, 120);
      const requestedMemberId = normalizeText(input.memberId, 120);
      const requestedStatus = normalizeWechatWipeSignupStatus(input.status);
      const store = await readWechatAdminWipeParticipantWriteStore(requestedWipeId, action, input, req);
      const viewer = wechatManagementActor(store, req);
      const wipe = requestedWipeId === 'current'
        ? currentWipe(store)
        : store.wipes.find((item) => item.id === requestedWipeId);
      assertWipeMutable(wipe);
      const before = {
        wipes: cloneRecordsForPatch(store.wipes),
        members: cloneRecordsForPatch(store.members),
        wipeParticipants: cloneRecordsForPatch(store.wipeParticipants),
        kdaRows: cloneRecordsForPatch(store.kdaRows),
        kdaSnapshots: cloneRecordsForPatch(store.kdaSnapshots)
      };
      const addedMemberIds = [];
      let log = null;

      if (action === 'add') {
        const memberIds = [...new Set((Array.isArray(input.memberIds) ? input.memberIds : [])
          .map((id) => normalizeText(id, 120))
          .filter(Boolean))];
        const candidates = new Map(participantCandidates(store, wipe, viewer).map((member) => [member.id, member]));
        const squadsByMember = memberSquadMap(store);
        const note = normalizeText(input.note, 500);
        for (const memberId of memberIds) {
          const candidate = candidates.get(memberId);
          if (!candidate) throw Object.assign(new Error('存在不可添加或已报名的成员'), { status: 403 });
          const member = store.members.find((item) => item.id === memberId);
          if (!member) throw Object.assign(new Error('成员不存在'), { status: 404 });
          const squadId = squadsByMember.get(memberId)?.squadId || '';
          const now = nowIso();
          store.wipeParticipants.push({
            id: createId('wipe_participant'),
            wipeId: wipe.id,
            memberId,
            squadId,
            status: requestedStatus,
            source: 'admin',
            sourceUserId: reviewActorId(req),
            note,
            addedByUserId: reviewActorId(req),
            createdAt: now,
            updatedAt: now
          });
          if (requestedStatus === 'not_attending') {
            recordMemberNotAttending(store, { memberId, wipeId: wipe.id, source: 'admin', at: now });
          }
          addedMemberIds.push(memberId);
        }
        log = createLogEntry(req, 'wechat_admin_wipe_signup_add', `微信管理添加报名 ${addedMemberIds.length} 人`, {
          targetId: wipe.id,
          actorUserId: reviewActorId(req),
          actorUsername: requestActorUsername(req),
          metadata: { memberIds: addedMemberIds, status: requestedStatus }
        });
      } else if (action === 'edit') {
        const index = store.wipeParticipants.findIndex((item) => item.wipeId === wipe.id && item.memberId === requestedMemberId);
        if (index === -1) throw Object.assign(new Error('报名记录不存在'), { status: 404 });
        const participant = store.wipeParticipants[index];
        const member = store.members.find((item) => item.id === requestedMemberId);
        if (!member) throw Object.assign(new Error('成员不存在'), { status: 404 });
        const squadsByMember = memberSquadMap(store);
        const memberSquad = participant.squadId ? { squadId: participant.squadId } : (squadsByMember.get(member.id) || null);
        const captainSquads = leaderSquads(store, viewer);
        const leaderSquad = memberSquad
          ? captainSquads.find((squad) => squad.id === memberSquad.squadId) || null
          : captainSquads[0] || null;
        if (!canManageWipeParticipant(viewer, member, memberSquad, leaderSquad)) {
          throw Object.assign(new Error('无权修改该报名'), { status: 403 });
        }
        const previousStatus = normalizeParticipantStatus(participant.status);
        const now = nowIso();
        store.wipeParticipants[index] = {
          ...participant,
          status: requestedStatus,
          source: 'admin',
          sourceUserId: reviewActorId(req),
          note: input.hasNote ? normalizeText(input.note, 500) : (participant.note || ''),
          updatedAt: now
        };
        if (requestedStatus === 'not_attending' && previousStatus !== 'not_attending') {
          recordMemberNotAttending(store, { memberId: member.id, wipeId: wipe.id, source: 'admin', at: now });
        }
        log = createLogEntry(req, 'wechat_admin_wipe_signup_edit', `微信管理修改报名 ${memberDisplayName(member)} ${requestedStatus}`, {
          targetId: wipe.id,
          steamId: member.steamId,
          actorUserId: reviewActorId(req),
          actorUsername: requestActorUsername(req),
          metadata: { memberId: member.id, status: requestedStatus }
        });
      } else if (action === 'remove') {
        const participant = store.wipeParticipants.find((item) => item.wipeId === wipe.id && item.memberId === requestedMemberId);
        if (!participant) throw Object.assign(new Error('报名记录不存在'), { status: 404 });
        const member = store.members.find((item) => item.id === requestedMemberId);
        if (member) {
          const squadsByMember = memberSquadMap(store);
          const memberSquad = participant.squadId ? { squadId: participant.squadId } : (squadsByMember.get(member.id) || null);
          const captainSquads = leaderSquads(store, viewer);
          const leaderSquad = memberSquad
            ? captainSquads.find((squad) => squad.id === memberSquad.squadId) || null
            : captainSquads[0] || null;
          if (!canManageWipeParticipant(viewer, member, memberSquad, leaderSquad)) {
            throw Object.assign(new Error('无权移除该报名'), { status: 403 });
          }
        }
        store.wipeParticipants = store.wipeParticipants.filter((item) => !(item.wipeId === wipe.id && item.memberId === requestedMemberId));
        log = createLogEntry(req, 'wechat_admin_wipe_signup_remove', `微信管理移除报名 ${member ? memberDisplayName(member) : requestedMemberId}`, {
          targetId: wipe.id,
          steamId: member?.steamId || '',
          actorUserId: reviewActorId(req),
          actorUsername: requestActorUsername(req),
          metadata: { memberId: requestedMemberId }
        });
      } else {
        throw Object.assign(new Error('未知参与人操作'), { status: 400 });
      }

      if (isWipeStartedServer(wipe)) syncKdaRows(store, wipe);

      const wipesPatch = collectionFullPatchFromBeforeAfter(before.wipes, store.wipes);
      const membersPatch = collectionFullPatchFromBeforeAfter(before.members, store.members);
      const wipeParticipantPatch = collectionFullPatchFromBeforeAfter(before.wipeParticipants, store.wipeParticipants);
      const kdaRowPatch = collectionFullPatchFromBeforeAfter(before.kdaRows, store.kdaRows);
      const kdaSnapshotPatch = collectionFullPatchFromBeforeAfter(before.kdaSnapshots, store.kdaSnapshots);
      const patchResult = await writeSqliteStorePatch({
        reason: `wechat_admin_wipe_participant_${action}`,
        upserts: {
          ...(wipesPatch.upserts.length ? { wipes: wipesPatch.upserts } : {}),
          ...(membersPatch.upserts.length ? { members: membersPatch.upserts } : {}),
          ...(wipeParticipantPatch.upserts.length ? { wipeParticipants: wipeParticipantPatch.upserts } : {}),
          ...(kdaRowPatch.upserts.length ? { kdaRows: kdaRowPatch.upserts } : {}),
          ...(kdaSnapshotPatch.upserts.length ? { kdaSnapshots: kdaSnapshotPatch.upserts } : {}),
          ...(log ? { logs: [log] } : {})
        },
        deletes: {
          ...(wipeParticipantPatch.deletes.length ? { wipeParticipants: wipeParticipantPatch.deletes } : {}),
          ...(kdaRowPatch.deletes.length ? { kdaRows: kdaRowPatch.deletes } : {}),
          ...(kdaSnapshotPatch.deletes.length ? { kdaSnapshots: kdaSnapshotPatch.deletes } : {})
        },
        trims: log ? logTrimPatch() : {}
      });
      await patchStoreCache((cachedStore) => {
        patchCachedScopedRecords(cachedStore, 'wipes', before.wipes, store.wipes);
        patchCachedScopedRecords(cachedStore, 'members', before.members, store.members);
        patchCachedScopedRecords(cachedStore, 'wipeParticipants', before.wipeParticipants, store.wipeParticipants);
        patchCachedScopedRecords(cachedStore, 'kdaRows', before.kdaRows, store.kdaRows);
        patchCachedScopedRecords(cachedStore, 'kdaSnapshots', before.kdaSnapshots, store.kdaSnapshots);
        if (log) applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return { addedMemberIds, updatedWipeId: wipe.id };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite wechat admin wipe participant fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('微信管理报名写入', error);
  }
}

async function writeWechatAdminWipeLifecycleDirect(req, action, input = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedAction = normalizeText(action, 40);
      const includeNotificationContext = normalizedAction === 'publish' ||
        normalizedAction === 'open-signup' ||
        (normalizedAction === 'create' && normalizeText(input.body?.signupStatus, 40) !== 'closed');
      const store = await readWechatAdminWipeLifecycleWriteStore({
        includeNotificationContext,
        requestedWipeId: input.requestedWipeId
      });
      const collectionNames = ['wipes', 'wechatNotifications', 'operationRuns'];
      const before = snapshotStoreCollections(store, collectionNames);
      const requestedWipeId = normalizeText(input.requestedWipeId, 120);
      const body = input.body || {};
      let updatedWipeId = '';
      let notificationMessages = [];

      if (normalizedAction === 'create') {
        if (currentWipe(store)) throw Object.assign(new Error('已经存在进行中的档期'), { status: 409 });
        const fields = wechatWipeFieldsFromBody(store, body);
        if (!fields.serverName) throw Object.assign(new Error('服务器名称必填'), { status: 400 });
        const createdAt = nowIso();
        const signupStatus = normalizeText(body?.signupStatus, 40) === 'closed' ? 'closed' : 'open';
        const wipe = {
          id: createId('wipe'),
          status: 'active',
          closedAt: '',
          ...fields,
          signupStatus,
          signupOpenedAt: signupStatus === 'open' ? createdAt : '',
          signupClosedAt: signupStatus === 'closed' ? createdAt : '',
          createdBy: reviewActorId(req),
          createdAt,
          updatedAt: createdAt
        };
        store.wipes.unshift(wipe);
        updatedWipeId = wipe.id;
        if (signupStatus === 'open') {
          notificationMessages = collectWechatWipeOpenNotifications(store, wipe);
        }
        appendLog(store, req, 'wechat_admin_wipe_create', `微信管理创建开荒 ${wipe.name}`, {
          targetId: wipe.id,
          actorUserId: reviewActorId(req),
          actorUsername: requestActorUsername(req),
          metadata: { vitalServerId: wipe.vitalServerId, signupStatus }
        });
      } else {
        const wipe = requestedWipeId === 'current'
          ? currentWipe(store)
          : store.wipes.find((item) => item.id === requestedWipeId);
        assertWipeMutable(wipe);
        const index = store.wipes.findIndex((item) => item.id === wipe.id);
        if (index === -1) throw Object.assign(new Error('档期不存在'), { status: 404 });
        const now = nowIso();

        if (normalizedAction === 'edit') {
          const fields = wechatWipeFieldsFromBody(store, body, wipe);
          if (!fields.serverName) throw Object.assign(new Error('服务器名称必填'), { status: 400 });
          store.wipes[index] = {
            ...wipe,
            ...fields,
            updatedAt: now
          };
          updatedWipeId = wipe.id;
          appendLog(store, req, 'wechat_admin_wipe_edit', `微信管理编辑开荒 ${fields.name}`, {
            targetId: wipe.id,
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req),
            metadata: { vitalServerId: fields.vitalServerId }
          });
        } else if (normalizedAction === 'publish' || normalizedAction === 'open-signup') {
          const nextWipe = {
            ...wipe,
            signupStatus: 'open',
            signupOpenedAt: now,
            signupClosedAt: '',
            signupCloseAt: '',
            updatedAt: now
          };
          store.wipes[index] = nextWipe;
          updatedWipeId = nextWipe.id;
          notificationMessages = collectWechatWipeOpenNotifications(store, nextWipe);
          appendLog(
            store,
            req,
            normalizedAction === 'publish' ? 'wechat_admin_wipe_publish' : 'wechat_admin_wipe_signup_open',
            `${normalizedAction === 'publish' ? '微信管理发布报名' : '微信管理开放报名'} ${nextWipe.name}`,
            {
              targetId: nextWipe.id,
              actorUserId: reviewActorId(req),
              actorUsername: requestActorUsername(req)
            }
          );
        } else if (normalizedAction === 'close-signup') {
          const nextWipe = {
            ...wipe,
            signupStatus: 'closed',
            signupClosedAt: now,
            signupCloseAt: now,
            updatedAt: now
          };
          store.wipes[index] = nextWipe;
          updatedWipeId = nextWipe.id;
          appendLog(store, req, 'wechat_admin_wipe_signup_close', `微信管理关闭报名 ${nextWipe.name}`, {
            targetId: nextWipe.id,
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req)
          });
        } else {
          throw Object.assign(new Error('未知档期操作'), { status: 400 });
        }
      }

      const { upserts, deletes } = diffStoreCollections(before, store, collectionNames);
      const createdLogs = (store.logs || []).filter((log) => log?.id);
      const patchResult = await writeSqliteStorePatch({
        reason: `wechat_admin_wipe_${normalizedAction.replaceAll('-', '_')}`,
        upserts: {
          ...upserts,
          ...(createdLogs.length ? { logs: createdLogs } : {})
        },
        deletes,
        trims: createdLogs.length ? logTrimPatch() : {}
      });
      await patchStoreCache((cachedStore) => {
        applyStoreCollectionCachePatch(cachedStore, collectionNames, upserts, deletes);
        if (createdLogs.length) applyCachedLogPatch(cachedStore, createdLogs, trimmedLogIds(patchResult));
        cachedStore.wechatNotifications ||= [];
        cachedStore.wechatNotifications = cachedStore.wechatNotifications
          .toSorted((left, right) => timestampForSort(right.createdAt) - timestampForSort(left.createdAt))
          .slice(0, 2000);
        ensureOperationRuns(cachedStore);
      });
      return { updatedWipeId, notificationMessages };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite wechat admin wipe lifecycle write failed:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('微信管理档期写入', error);
  }
}

async function writeWechatWipeSignupDirect(req, input = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const requestedWipeId = normalizeText(input.requestedWipeId, 120);
      const requestedStatus = normalizeWechatWipeSignupStatus(input.status);
      const store = await readWechatWipeSignupWriteStore(req.wechatUser?.id, requestedWipeId);
      const wechatUser = (store.wechatUsers || []).find((item) => item.id === req.wechatUser.id);
      const member = wechatUser?.memberId ? store.members.find((item) => item.id === wechatUser.memberId) : null;
      if (!wechatUser) throw Object.assign(new Error('微信用户不存在'), { status: 404 });
      if (!member) throw Object.assign(new Error('微信账号未绑定有效成员'), { status: 403 });
      const wipe = requestedWipeId === 'current'
        ? currentWipe(store)
        : store.wipes.find((item) => item.id === requestedWipeId);
      assertWechatWipeSignupOpen(wipe);

      const before = {
        wipes: cloneRecordsForPatch(store.wipes),
        members: cloneRecordsForPatch(store.members),
        wipeParticipants: cloneRecordsForPatch(store.wipeParticipants),
        kdaRows: cloneRecordsForPatch(store.kdaRows),
        kdaSnapshots: cloneRecordsForPatch(store.kdaSnapshots),
        wechatNotifications: cloneRecordsForPatch(store.wechatNotifications),
        operationRuns: cloneRecordsForPatch(store.operationRuns)
      };
      let addedMemberId = '';
      let notificationMessages = [];
      let log = null;

      if (input.cancelRequested) {
        const result = cancelWechatWipeParticipant(store, { wipe, member, wechatUser });
        if (result.removed && isWipeStartedServer(wipe)) syncKdaRows(store, wipe);
        log = createLogEntry(req, 'wechat_wipe_signup_cancel', `微信取消报名 ${memberDisplayName(member)}`, {
          targetId: wipe.id,
          steamId: member.steamId,
          actorUserId: `wechat:${wechatUser.id}`,
          actorUsername: wechatUser.nickname || wechatUser.id,
          metadata: {
            wechatUserId: wechatUser.id,
            memberId: member.id,
            status: 'cancel',
            source: 'wechat',
            removed: result.removed
          }
        });
      } else {
        const result = upsertWechatWipeParticipant(store, {
          wipe,
          member,
          wechatUser,
          status: requestedStatus,
          note: input.note
        });
        if (result.added) addedMemberId = member.id;
        notificationMessages = collectWechatWipeSignupStatusNotification(store, {
          wipe,
          wechatUser,
          status: requestedStatus
        });
        if (isWipeStartedServer(wipe)) syncKdaRows(store, wipe);
        const statusText = attendanceStatusText(requestedStatus, { language: 'zh', context: 'wechat' });
        log = createLogEntry(req, 'wechat_wipe_signup', `微信报名 ${memberDisplayName(member)} ${statusText}`, {
          targetId: wipe.id,
          steamId: member.steamId,
          actorUserId: `wechat:${wechatUser.id}`,
          actorUsername: wechatUser.nickname || wechatUser.id,
          metadata: {
            wechatUserId: wechatUser.id,
            memberId: member.id,
            status: requestedStatus,
            source: 'wechat'
          }
        });
      }

      const wipesPatch = collectionFullPatchFromBeforeAfter(before.wipes, store.wipes);
      const membersPatch = collectionFullPatchFromBeforeAfter(before.members, store.members);
      const wipeParticipantPatch = collectionFullPatchFromBeforeAfter(before.wipeParticipants, store.wipeParticipants);
      const kdaRowPatch = collectionFullPatchFromBeforeAfter(before.kdaRows, store.kdaRows);
      const kdaSnapshotPatch = collectionFullPatchFromBeforeAfter(before.kdaSnapshots, store.kdaSnapshots);
      const wechatNotificationPatch = collectionFullPatchFromBeforeAfter(before.wechatNotifications, store.wechatNotifications);
      const operationRunPatch = collectionFullPatchFromBeforeAfter(before.operationRuns, store.operationRuns);
      const patchResult = await writeSqliteStorePatch({
        reason: input.cancelRequested ? 'wechat_wipe_signup_cancel' : 'wechat_wipe_signup',
        upserts: {
          ...(wipesPatch.upserts.length ? { wipes: wipesPatch.upserts } : {}),
          ...(membersPatch.upserts.length ? { members: membersPatch.upserts } : {}),
          ...(wipeParticipantPatch.upserts.length ? { wipeParticipants: wipeParticipantPatch.upserts } : {}),
          ...(kdaRowPatch.upserts.length ? { kdaRows: kdaRowPatch.upserts } : {}),
          ...(kdaSnapshotPatch.upserts.length ? { kdaSnapshots: kdaSnapshotPatch.upserts } : {}),
          ...(wechatNotificationPatch.upserts.length ? { wechatNotifications: wechatNotificationPatch.upserts } : {}),
          ...(operationRunPatch.upserts.length ? { operationRuns: operationRunPatch.upserts } : {}),
          ...(log ? { logs: [log] } : {})
        },
        deletes: {
          ...(wipeParticipantPatch.deletes.length ? { wipeParticipants: wipeParticipantPatch.deletes } : {}),
          ...(kdaRowPatch.deletes.length ? { kdaRows: kdaRowPatch.deletes } : {}),
          ...(kdaSnapshotPatch.deletes.length ? { kdaSnapshots: kdaSnapshotPatch.deletes } : {}),
          ...(wechatNotificationPatch.deletes.length ? { wechatNotifications: wechatNotificationPatch.deletes } : {}),
          ...(operationRunPatch.deletes.length ? { operationRuns: operationRunPatch.deletes } : {})
        },
        trims: log ? logTrimPatch() : {}
      });
      await patchStoreCache((cachedStore) => {
        patchCachedScopedRecords(cachedStore, 'wipes', before.wipes, store.wipes);
        patchCachedScopedRecords(cachedStore, 'members', before.members, store.members);
        patchCachedScopedRecords(cachedStore, 'wipeParticipants', before.wipeParticipants, store.wipeParticipants);
        patchCachedScopedRecords(cachedStore, 'kdaRows', before.kdaRows, store.kdaRows);
        patchCachedScopedRecords(cachedStore, 'kdaSnapshots', before.kdaSnapshots, store.kdaSnapshots);
        patchCachedScopedRecords(cachedStore, 'wechatNotifications', before.wechatNotifications, store.wechatNotifications);
        patchCachedScopedRecords(cachedStore, 'operationRuns', before.operationRuns, store.operationRuns);
        if (log) applyCachedLogPatch(cachedStore, [log], trimmedLogIds(patchResult));
      });
      return { addedMemberId, updatedWipeId: wipe.id, notificationMessages };
    });
  } catch (error) {
    if (error?.status) throw error;
    console.warn('[nb-clan] sqlite wechat wipe signup fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('微信报名写入', error);
  }
}

async function resolveMemberEditSteamInput(input, current) {
  const rawInput = normalizeText(input, 500);
  if (!rawInput) {
    return { ok: true, steamId: current.steamId, rawInput: current.rawInput || current.steamId };
  }
  const parsed = parseSteamInput(rawInput);
  if (parsed.ok && parsed.steamId === current.steamId) {
    return { ...parsed, rawInput: current.rawInput || parsed.rawInput || current.steamId };
  }
  if (rawInput === current.steamId || rawInput === current.rawInput) {
    return { ok: true, steamId: current.steamId, rawInput: current.rawInput || current.steamId };
  }
  return resolveSteamInput(rawInput);
}

function defaultAccountRiskRules() {
  return [
    {
      id: 'account-restricted',
      name: 'Steam 受限账号',
      type: 'account_restricted',
      operator: 'is',
      threshold: 0,
      squadFilter: '',
      enabled: true
    },
    {
      id: 'steam-ban-or-restriction',
      name: 'Steam 封禁或限制',
      type: 'steam_ban_or_restriction',
      operator: 'is',
      threshold: 0,
      squadFilter: '',
      enabled: true
    },
    {
      id: 'low-game-hours',
      name: '游戏时长低于 500h',
      type: 'playtime_hours',
      operator: 'lt',
      threshold: 500,
      squadFilter: '',
      enabled: true
    },
    {
      id: 'low-inventory',
      name: '库存价值低于 $50',
      type: 'inventory_value',
      operator: 'lt',
      threshold: 50,
      squadFilter: '',
      enabled: true
    },
    {
      id: 'no-online-14d',
      name: '14 天无在线记录',
      type: 'no_online_days',
      operator: 'gte',
      threshold: 14,
      squadFilter: '',
      enabled: true
    },
    {
      id: 'unassigned-squad',
      name: '未分配队伍',
      type: 'unassigned_squad',
      operator: 'is',
      threshold: 0,
      squadFilter: '',
      enabled: false
    }
  ];
}

function requiredDefaultAccountRiskRules() {
  return defaultAccountRiskRules().filter((rule) => (
    rule.type === 'account_restricted' || rule.type === 'steam_ban_or_restriction'
  ));
}

function normalizeAccountRiskSquadFilter(value) {
  const filter = normalizeText(value, 100);
  if (!filter || filter === '__unassigned') return filter;
  return filter;
}

function publicAccountRiskRule(item = {}) {
  const type = ACCOUNT_RISK_RULE_TYPES.has(item.type) ? item.type : 'private_inventory';
  return {
    id: normalizeText(item.id, 100),
    name: normalizeText(item.name, 100),
    type,
    operator: ACCOUNT_RISK_RULE_OPERATORS.has(item.operator) ? item.operator : defaultOperatorForAccountRiskRuleType(type),
    threshold: Number.isFinite(Number(item.threshold)) ? Number(item.threshold) : 0,
    squadFilter: normalizeAccountRiskSquadFilter(item.squadFilter),
    enabled: item.enabled !== false,
    createdAt: item.createdAt || '',
    updatedAt: item.updatedAt || ''
  };
}

function accountRiskRulesForStore(store) {
  const settings = store.settings?.accountRisk || {};
  const configured = settings.configured === true;
  const rules = configured ? (settings.rules || []) : defaultAccountRiskRules();
  const publicRules = rules.map(publicAccountRiskRule).filter((rule) => rule.id && rule.name);
  for (const requiredRule of [...requiredDefaultAccountRiskRules()].reverse()) {
    if (!publicRules.some((rule) => rule.id === requiredRule.id || rule.type === requiredRule.type)) {
      publicRules.unshift(publicAccountRiskRule(requiredRule));
    }
  }
  return publicRules;
}

function publicAccountRiskSettings(store) {
  const settings = store.settings?.accountRisk || {};
  return {
    squadFilter: normalizeAccountRiskSquadFilter(settings.squadFilter),
    rules: accountRiskRulesForStore(store),
    configured: settings.configured === true
  };
}

function defaultOperatorForAccountRiskRuleType(type) {
  if (type === 'private_inventory' || type === 'private_playtime') return 'unavailable';
  if (type === 'account_restricted' || type === 'steam_ban_or_restriction' || type === 'unassigned_squad') return 'is';
  if (type === 'playtime_hours' || type === 'inventory_value') return 'lt';
  if (type === 'no_online_days') return 'gte';
  return 'gt';
}

function normalizeAccountRiskRuleInput(item = {}, existing = null) {
  const type = normalizeText(item.type, 40);
  if (!ACCOUNT_RISK_RULE_TYPES.has(type)) return null;
  const operator = normalizeText(item.operator, 20);
  const normalizedOperator = ACCOUNT_RISK_RULE_OPERATORS.has(operator)
    ? operator
    : defaultOperatorForAccountRiskRuleType(type);
  const rawThreshold = Number(item.threshold);
  const threshold = Number.isFinite(rawThreshold) ? Math.max(0, rawThreshold) : 0;
  const now = nowIso();
  return {
    id: normalizeText(item.id, 100) || createId('risk_rule'),
    name: normalizeText(item.name, 100) || normalizeText(existing?.name, 100) || type,
    type,
    operator: normalizedOperator,
    threshold,
    squadFilter: normalizeAccountRiskSquadFilter(item.squadFilter),
    enabled: item.enabled !== false,
    createdAt: existing?.createdAt || now,
    updatedAt: now
  };
}

