function battlemetricsSettings(store) {
  store.settings ||= {};
  store.settings.battlemetrics ||= {};
  store.settings.battlemetrics.apiKey ||= '';
  store.settings.battlemetrics.apiKeys ||= [];
  store.settings.battlemetrics.apiKeyUpdatedAt ||= '';
  store.settings.battlemetrics.lastSyncAt ||= '';
  store.settings.battlemetrics.lastSyncError ||= '';
  normalizeBattlemetricsApiKeys(store.settings.battlemetrics);
  return store.settings.battlemetrics;
}

function normalizeBattlemetricsApiKeys(settings) {
  const now = nowIso();
  const seen = new Set();
  const legacyKey = normalizeText(settings.apiKey, BATTLEMETRICS_API_KEY_MAX_LENGTH);
  const rawKeys = Array.isArray(settings.apiKeys) ? settings.apiKeys : [];
  const keys = [];

  for (const item of rawKeys) {
    const apiKey = normalizeText(item?.apiKey, BATTLEMETRICS_API_KEY_MAX_LENGTH);
    if (!apiKey || seen.has(apiKey)) continue;
    seen.add(apiKey);
    keys.push({
      id: normalizeText(item?.id, 80) || createId('bm_key'),
      label: normalizeText(item?.label, 80),
      apiKey,
      createdAt: normalizeText(item?.createdAt, 40) || settings.apiKeyUpdatedAt || now,
      updatedAt: normalizeText(item?.updatedAt, 40) || settings.apiKeyUpdatedAt || now
    });
  }

  if (legacyKey && !seen.has(legacyKey)) {
    keys.unshift({
      id: 'bm_key_legacy',
      label: '',
      apiKey: legacyKey,
      createdAt: settings.apiKeyUpdatedAt || now,
      updatedAt: settings.apiKeyUpdatedAt || now
    });
  }

  settings.apiKeys = keys;
  settings.apiKey = keys[0]?.apiKey || '';
  if (keys.length && !settings.apiKeyUpdatedAt) {
    settings.apiKeyUpdatedAt = keys[0].updatedAt || now;
  }
  return keys;
}

function battlemetricsApiKey(store) {
  const settings = battlemetricsSettings(store);
  return String(process.env.NB_BATTLEMETRICS_API_KEY || process.env.BATTLEMETRICS_TOKEN || settings.apiKeys?.[0]?.apiKey || settings.apiKey || '').trim();
}

function publicBattlemetricsApiKeys(settings) {
  return (settings.apiKeys || []).map((item, index) => ({
    id: item.id,
    label: item.label || `Token ${index + 1}`,
    masked: '********',
    updatedAt: item.updatedAt || item.createdAt || ''
  }));
}

function battlemetricsSettingsPayload(store) {
  const settings = battlemetricsSettings(store);
  const envConfigured = Boolean(process.env.NB_BATTLEMETRICS_API_KEY || process.env.BATTLEMETRICS_TOKEN);
  const keys = publicBattlemetricsApiKeys(settings);
  return {
    enabled: Boolean(envConfigured || keys.length),
    source: envConfigured ? 'env' : (keys.length ? 'store' : ''),
    envConfigured,
    keyCount: keys.length,
    keys,
    apiKeyUpdatedAt: envConfigured ? '' : (settings.apiKeyUpdatedAt || ''),
    lastSyncAt: settings.lastSyncAt || '',
    lastSyncError: settings.lastSyncError || ''
  };
}

