function deriveDiscordEnabledCommandIds(target = {}) {
  const ids = [];
  if (target.channelId) ids.push('wipe');
  if (target.kdaQueryChannelId) ids.push('kda');
  if (target.memberRegisterChannelId || target.memberReviewChannelId || target.memberManageRoleId || normalizeDiscordMemberRegisterRoleSquadRules(target.memberRegisterRoleSquadRules).length) {
    ids.push('member');
  }
  if (target.memberRankingChannelId) ids.push('ranking');
  if (target.mapChannelId) ids.push('map');
  return ids;
}

function isBotCommandDefinitionId(value) {
  return /^[A-Za-z0-9_:-]{1,80}$/.test(String(value || '').trim());
}

function normalizeDiscordEnabledCommandIds(values, target = {}) {
  if (!Array.isArray(values)) return deriveDiscordEnabledCommandIds(target);
  const allowed = new Set(DISCORD_BOT_COMMAND_IDS);
  const used = new Set();
  return values
    .map((value) => normalizeText(value, 40))
    .filter((value) => {
      if ((!allowed.has(value) && !isBotCommandDefinitionId(value)) || used.has(value)) return false;
      used.add(value);
      return true;
    });
}

