    discordMetadataSyncedAt: settings.discordMetadataSyncedAt || '',
    discordMetadataSyncError: settings.discordMetadataSyncError || '',
    lastPushAt: settings.lastPushAt || '',
    lastPushError: settings.lastPushError || '',
