function discordPublicUrl(req, value = '') {
  const raw = normalizeText(value, 500);
  if (!raw) return '';
  try {
    const parsed = raw.startsWith('/') ? new URL(raw, requestOrigin(req)) : new URL(raw);
    return ['http:', 'https:'].includes(parsed.protocol) ? parsed.toString() : '';
  } catch {
    return '';
  }
}

function discordMapUploads(store, wipe, kind) {
  return (store?.uploads || []).filter((upload) => (
    upload.ownerType === 'wipe' &&
    upload.ownerId === wipe?.id &&
    upload.kind === kind
  ));
}

function discordMapImageUpload(store, wipe) {
  const images = discordMapUploads(store, wipe, 'map_image');
  if (!images.length) return null;
  return images.find((upload) => upload.url && upload.url === wipe?.rustMapsImageUrl) ||
    images.find((upload) => upload.source === 'rustmaps' || upload.originalName === 'RustMaps full map & icons.png') ||
    images[0];
}

async function discordMapCardData(store, req) {
  const wipe = currentWipe(store);
  if (!wipe) {
    throw Object.assign(new Error('当前没有进行中的服务器档期'), { status: 404 });
  }
  const mapFile = discordMapUploads(store, wipe, 'map_file')[0] || null;
  const mapUrl = discordPublicUrl(req, wipe.rustMapsLink) ||
    discordPublicUrl(req, wipe.mapLink) ||
    discordPublicUrl(req, mapFile?.url);
  if (!mapUrl) {
    throw Object.assign(new Error('当前服务器没有地图链接'), { status: 400 });
  }
  const imageUpload = discordMapImageUpload(store, wipe);
  let imageUrl = discordPublicUrl(req, wipe.rustMapsImageUrl) ||
    discordPublicUrl(req, imageUpload?.url) ||
    discordPublicUrl(req, wipe.rustMapsImageSourceUrl);
  if (!imageUrl && normalizeRustMapsMapUrl(mapUrl)) {
    imageUrl = await resolveRustMapsImageUrl(mapUrl).catch(() => '');
  }
  if (!imageUrl) {
    throw Object.assign(new Error('当前服务器没有地图预览图'), { status: 400 });
  }
  return {
    wipe,
    serverName: expandVitalRustName(wipe.serverName || wipe.name || '当前服务器'),
    mapUrl,
    imageUrl
  };
}

async function buildDiscordMapMessage(store, req, options = {}) {
  const language = discordTextLanguage(options.language || DISCORD_PUBLIC_MESSAGE_LANGUAGE);
  const data = await discordMapCardData(store, req);
  return {
    embeds: [
      {
        title: `🗺️ Map ${data.serverName}`.slice(0, 256),
        url: data.mapUrl,
        description: [
          `${discordText(language, 'server')}: ${data.serverName}`,
          `${discordText(language, 'mapLink')}: ${data.mapUrl}`
        ].join('\n').slice(0, 4096),
        image: { url: data.imageUrl },
        color: 0x22c55e,
        footer: { text: discordText(language, 'footerMemberSystem') },
        timestamp: nowIso()
      }
    ]
  };
}

function buildDiscordAttendanceRegistrationRequiredMessage(settings = {}, language = DISCORD_PUBLIC_MESSAGE_LANGUAGE) {
  const registrationMessage = buildDiscordMemberRegistrationMessage(settings, language);
  return discordPublicInteractionMessage({
    content: discordText(language, 'attendanceNeedRegistration'),
    embeds: registrationMessage.embeds,
    components: registrationMessage.components,
    flags: 64
  });
}

function normalizeDiscordVipProvider(value = '') {
  const raw = normalizeText(value, 40).toLowerCase();
  if (raw === 'rustintiy') return 'rustinity';
  return ['vital', 'rustinity', 'atlas'].includes(raw) ? raw : '';
}

function discordVipProviderConfig(provider = 'vital') {
  const normalizedProvider = normalizeDiscordVipProvider(provider) || 'vital';
  if (normalizedProvider === 'rustinity') {
    return {
      provider: 'rustinity',
      label: 'Rustinity VIP',
      typeField: 'rustinityVipType',
      purchasedAtField: 'rustinityVipPurchasedAt',
      expiresAtField: 'rustinityVipExpiresAt',
      supportsPriority: false,
      normalizeType: normalizeRustinityVipType,
      normalizeInput: normalizeRustinityVipInput,
      publicVip: publicRustinityVip,
      logType: 'discord_rustinity_vip_update'
    };
  }
  if (normalizedProvider === 'atlas') {
    return {
      provider: 'atlas',
      label: 'Atlas VIP',
      typeField: 'atlasVipType',
      purchasedAtField: 'atlasVipPurchasedAt',
      expiresAtField: 'atlasVipExpiresAt',
      supportsPriority: true,
      normalizeType: normalizeAtlasVipType,
      normalizeInput: normalizeAtlasVipInput,
      publicVip: publicAtlasVip,
      logType: 'discord_atlas_vip_update'
    };
  }
  return {
    provider: 'vital',
    label: 'Vital VIP',
    typeField: 'vitalVipType',
    purchasedAtField: 'vitalVipPurchasedAt',
    expiresAtField: 'vitalVipExpiresAt',
    supportsPriority: true,
    normalizeType: normalizeVitalVipType,
    normalizeInput: normalizeVitalVipInput,
    publicVip: publicVitalVip,
    logType: 'discord_vital_vip_update'
  };
}

function discordVipProviderFromCustomId(customId = '', fallback = 'vital') {
  const [, action, firstValue] = normalizeText(customId, 120).split(':');
  if (action === 'type') return normalizeDiscordVipProvider(firstValue) || fallback;
  if (action === 'submit') {
    const normalizedProvider = normalizeDiscordVipProvider(firstValue);
    return normalizedProvider || fallback;
  }
  return fallback;
}

function discordVipTypeFromSubmitCustomId(customId = '') {
  const parts = normalizeText(customId, 120).split(':');
  if (parts[1] !== 'submit') return '';
  if (normalizeDiscordVipProvider(parts[2])) return parts[3] || '';
  return parts[2] || '';
}

function normalizeDiscordVipType(provider, value) {
  const config = discordVipProviderConfig(provider);
  const raw = normalizeText(value, 40).toLowerCase();
  if (raw === 'none') return 'none';
  if (['免排队', '免', 'queue skip', 'queueskip', 'skip queue', 'skip'].includes(raw)) return 'queue_skip';
  if (config.supportsPriority && ['优先队列', '优先', 'priority queue', 'priority', 'vip'].includes(raw)) return 'priority';
  return config.normalizeType(raw);
}

function discordVitalVipTypeText(type, language = DISCORD_DEFAULT_LANGUAGE, provider = 'vital') {
  const normalized = normalizeDiscordVipType(provider, type);
  if (normalized === 'priority') return discordVitalVipText(language, 'typePriority');
  if (normalized === 'queue_skip') return discordVitalVipText(language, 'typeQueueSkip');
  return discordVitalVipText(language, 'typeNone');
}

function discordVitalVipSelectOption(label, value, selected = false) {
  return {
    label: normalizeText(label, 100),
    value: normalizeText(value, 100),
    ...(selected ? { default: true } : {})
  };
}

function discordModalLabel(label, component, options = {}) {
  return {
    type: DISCORD_COMPONENT_LABEL,
    label: normalizeText(label, 45),
    ...(options.description ? { description: normalizeText(options.description, 100) } : {}),
    component
  };
}

function discordVitalVipLabel(language, labelKey, component, vars = {}) {
  return discordModalLabel(discordVitalVipText(language, labelKey, vars), component);
}

function discordVitalVipDateParts(value) {
  const normalized = normalizeVitalVipDate(value) || nowIso().slice(0, 10);
  const [year, month, day] = normalized.split('-').map((part) => Number(part));
  return { year, month, day };
}

function discordVitalVipMonthOptions(selectedMonth) {
  return Array.from({ length: 12 }, (_item, index) => {
    const month = index + 1;
    const label = String(month).padStart(2, '0');
    return discordVitalVipSelectOption(label, label, selectedMonth === month);
  });
}

function discordVipTypeOptions(provider = 'vital', language = DISCORD_DEFAULT_LANGUAGE, selectedType = 'none') {
  const config = discordVipProviderConfig(provider);
  const normalizedType = normalizeDiscordVipType(config.provider, selectedType);
  const options = [
    discordVitalVipSelectOption(discordVitalVipText(language, 'typeNone'), 'none', normalizedType === 'none'),
    discordVitalVipSelectOption(discordVitalVipText(language, 'typeQueueSkip'), 'queue_skip', normalizedType === 'queue_skip')
  ];
  if (config.supportsPriority) {
    options.push(discordVitalVipSelectOption(discordVitalVipText(language, 'typePriority'), 'priority', normalizedType === 'priority'));
  }
  return options;
}

function discordVitalVipTypeOptions(language = DISCORD_DEFAULT_LANGUAGE, selectedType = 'none') {
  return discordVipTypeOptions('vital', language, selectedType);
}

export function discordVipSummaryLine(provider, member = {}, language = DISCORD_DEFAULT_LANGUAGE) {
  const config = discordVipProviderConfig(provider);
  const vip = config.publicVip(member);
  const label = discordVitalVipTypeText(vip.type, language, config.provider);
  if (!vip.active) return `${config.label}: ${label}`;
  return `${config.label}: ${label} · ${discordVitalVipText(language, 'purchaseLabel')} ${vitalVipDisplayDate(vip.purchasedAt) || '-'} · ${discordVitalVipText(language, 'expiryLabel')} ${discordExpiryTimestamp(vip.expiresAt) || '-'}`;
}

function discordVipProviderOptions(language = DISCORD_DEFAULT_LANGUAGE, member = {}) {
  return ['vital', 'rustinity', 'atlas'].map((provider) => {
    const config = discordVipProviderConfig(provider);
    const vip = config.publicVip(member);
    return {
      label: config.label,
      value: config.provider,
      description: normalizeText(discordVitalVipTypeText(vip.type, language, config.provider), 100)
    };
  });
}

function discordVipProviderMessage(member = {}, payload = {}) {
  const language = discordInteractionLanguage(payload);
  return {
    type: 4,
    data: {
      content: [
        discordVitalVipText(language, 'updateProviderContent'),
        discordVipSummaryLine('vital', member, language),
        discordVipSummaryLine('rustinity', member, language),
        discordVipSummaryLine('atlas', member, language)
      ].join('\n'),
      flags: 64,
      components: [
        {
          type: 1,
          components: [
            {
              type: DISCORD_COMPONENT_STRING_SELECT,
              custom_id: `${DISCORD_VITAL_VIP_PREFIX}:provider`,
              placeholder: discordVitalVipText(language, 'updateProviderPlaceholder'),
              min_values: 1,
              max_values: 1,
              options: discordVipProviderOptions(language, member)
            }
          ]
        }
      ]
    }
  };
}

function discordVipTypeMessage(member = {}, payload = {}, provider = 'vital') {
  const language = discordInteractionLanguage(payload);
  const config = discordVipProviderConfig(provider);
  return {
    type: 4,
    data: {
      content: discordVitalVipText(language, 'updateVipTypeContent', { provider: config.label }),
      flags: 64,
      components: [
        {
          type: 1,
          components: [
            {
              type: DISCORD_COMPONENT_STRING_SELECT,
              custom_id: `${DISCORD_VITAL_VIP_PREFIX}:type:${config.provider}`,
              placeholder: discordVitalVipText(language, 'updateVipTypePlaceholder', { provider: config.label }),
              min_values: 1,
              max_values: 1,
              options: discordVipTypeOptions(config.provider, language, member[config.typeField])
            }
          ]
        }
      ]
    }
  };
}

function discordVitalVipTypeMessage(member = {}, payload = {}) {
  return discordVipProviderMessage(member, payload);
}

function discordVitalVipDateComponents(language, selectedDate) {
  const { month, day } = discordVitalVipDateParts(selectedDate);
  return [
    discordVitalVipLabel(language, 'monthLabel', {
      type: DISCORD_COMPONENT_STRING_SELECT,
      custom_id: 'date_month',
      options: discordVitalVipMonthOptions(month),
      min_values: 1,
      max_values: 1,
      required: true
    }),
    discordVitalVipLabel(language, 'dayLabel', {
      type: 4,
      custom_id: 'date_day',
      style: 1,
      placeholder: discordVitalVipText(language, 'dayPlaceholder'),
      value: String(day),
      min_length: 1,
      max_length: 2,
      required: true
    })
  ];
}

function discordVitalVipDateModal(member, payload = {}, vipType = 'none', provider = 'vital') {
  const language = discordInteractionLanguage(payload);
  const config = discordVipProviderConfig(provider);
  const type = normalizeDiscordVipType(config.provider, vipType);
  const purchasedAt = normalizeVitalVipDate(member[config.purchasedAtField]);
  const selectedDate = purchasedAt || nowIso().slice(0, 10);
  return {
    type: 9,
    data: {
      custom_id: `${DISCORD_VITAL_VIP_PREFIX}:submit:${config.provider}:${type}`,
      title: discordVitalVipText(language, 'modalTitle', { provider: config.label }),
      components: discordVitalVipDateComponents(language, selectedDate)
    }
  };
}

function normalizeDiscordVitalVipType(value) {
  const raw = normalizeText(value, 40).toLowerCase();
  if (['none', 'queue_skip', 'priority'].includes(raw)) return raw;
  if (['免排队', '免', 'queue skip', 'queueskip', 'skip queue', 'skip'].includes(raw)) return 'queue_skip';
  if (['优先队列', '优先', 'priority queue', 'priority', 'vip'].includes(raw)) return 'priority';
  return normalizeVitalVipType(raw);
}

function discordVitalVipStrictDate(year, month, day) {
  const numericYear = Number(year);
  const numericMonth = Number(month);
  const numericDay = Number(day);
  if (!Number.isInteger(numericYear) || !Number.isInteger(numericMonth) || !Number.isInteger(numericDay)) return '';
  if (numericYear < 2020 || numericYear > 2100 || numericMonth < 1 || numericMonth > 12 || numericDay < 1 || numericDay > 31) return '';
  const date = new Date(Date.UTC(numericYear, numericMonth - 1, numericDay));
  if (
    date.getUTCFullYear() !== numericYear ||
    date.getUTCMonth() !== numericMonth - 1 ||
    date.getUTCDate() !== numericDay
  ) return '';
  return `${String(numericYear).padStart(4, '0')}-${String(numericMonth).padStart(2, '0')}-${String(numericDay).padStart(2, '0')}`;
}

function discordVitalVipDateSelection(payload) {
  const year = nowIso().slice(0, 4);
  const month = discordModalValue(payload, 'date_month');
  const day = normalizeText(discordModalValue(payload, 'date_day'), 2);
  if (!/^\d{1,2}$/.test(day)) return { date: '' };
  return { date: discordVitalVipStrictDate(year, month, day) };
}

export function discordVitalVipUpdatedInteraction(updatedVip = {}, language = DISCORD_DEFAULT_LANGUAGE, provider = 'vital') {
  const config = discordVipProviderConfig(provider);
  return discordInteractionMessage(discordVitalVipText(language, 'updated', {
    provider: config.label,
    label: discordVitalVipTypeText(updatedVip.type, language, config.provider),
    purchasedAt: vitalVipDisplayDate(updatedVip.purchasedAt) || '-',
    expiresAt: discordExpiryTimestamp(updatedVip.expiresAt) || '-'
  }));
}

async function saveDiscordVitalVipUpdate(req, payload, discordUserId, updateInput, language = DISCORD_DEFAULT_LANGUAGE, provider = 'vital') {
  const config = discordVipProviderConfig(provider);
  const normalizedDiscordId = normalizeText(discordUserId, DISCORD_ID_MAX_LENGTH);
  if (sqlitePrimaryMode()) {
    try {
      return await runStoreWriteTask(async () => {
        const members = await getSqliteRecordsByJsonField('members', 'discordId', [normalizedDiscordId], { limit: 0 });
        const member = members.find((item) => normalizeText(item.discordId, DISCORD_ID_MAX_LENGTH) === normalizedDiscordId) || null;
        if (!member) throw Object.assign(new Error(discordVitalVipText(language, 'needRegistration')), { status: 404 });
        const vip = config.normalizeInput(updateInput, member);
        const updated = {
          ...member,
          ...vip,
          updatedAt: nowIso()
        };
        const updatedVip = config.publicVip(updated);
        const log = createLogEntry(req, config.logType, `Discord 更新 ${config.label} ${memberDisplayName(updated)} ${updatedVip.label}`, {
          targetId: updated.id,
          steamId: updated.steamId,
          actorUserId: `discord:${normalizedDiscordId}`,
          actorUsername: discordInteractionDisplayName(payload, normalizedDiscordId),
          metadata: { discordUserId: normalizedDiscordId, provider: config.provider, vip: updatedVip }
        });
        const patchResult = await writeSqliteStorePatch({
          reason: 'discord_vip_update',
          upserts: {
            members: [updated],
            logs: [log]
          },
          trims: logTrimPatch()
        });
        await patchStoreCache((store) => {
          store.members ||= [];
          replaceCachedRecord(store.members, updated);
          applyCachedLogPatch(store, [log], trimmedLogIds(patchResult));
        });
        return updatedVip;
      });
    } catch (error) {
      if (error?.status === 404) throw error;
      console.warn('[nb-clan] sqlite discord vip update failed:', error?.message || error);
      throw sqliteDirectWriteUnavailableError(`Discord ${config.label} 写入`, error);
    }
  }
  let updatedVip = null;
  await updateStore((store) => {
    const member = discordMemberForUserId(store, normalizedDiscordId);
    if (!member) throw Object.assign(new Error(discordVitalVipText(language, 'needRegistration')), { status: 404 });
    const vip = config.normalizeInput(updateInput, member);
    Object.assign(member, vip, { updatedAt: nowIso() });
    updatedVip = config.publicVip(member);
    appendLog(store, req, config.logType, `Discord 更新 ${config.label} ${memberDisplayName(member)} ${updatedVip.label}`, {
      targetId: member.id,
      steamId: member.steamId,
      actorUserId: `discord:${normalizedDiscordId}`,
      actorUsername: discordInteractionDisplayName(payload, normalizedDiscordId),
      metadata: { discordUserId: normalizedDiscordId, provider: config.provider, vip: updatedVip }
    });
  });
  return updatedVip;
}

async function applyDiscordVipProviderSelection(req, payload) {
  const language = discordInteractionLanguage(payload);
  const discordUserId = discordUserIdFromInteraction(payload);
  if (!discordUserId) return discordInteractionMessage(discordVitalVipText(language, 'noDiscordUser'));
  const provider = normalizeDiscordVipProvider(Array.isArray(payload?.data?.values) ? payload.data.values[0] : '');
  if (!provider) return discordInteractionMessage(discordVitalVipText(language, 'invalidProvider'));
  const member = await readDiscordMemberForUserId(discordUserId);
  if (!member) return discordInteractionMessage(discordVitalVipText(language, 'needRegistration'));
  return discordVipTypeMessage(member, payload, provider);
}

async function applyDiscordVitalVipTypeSelection(req, payload) {
  const language = discordInteractionLanguage(payload);
  const discordUserId = discordUserIdFromInteraction(payload);
  if (!discordUserId) return discordInteractionMessage(discordVitalVipText(language, 'noDiscordUser'));
  const provider = discordVipProviderFromCustomId(payload?.data?.custom_id, 'vital');
  const config = discordVipProviderConfig(provider);
  const type = normalizeDiscordVipType(config.provider, Array.isArray(payload?.data?.values) ? payload.data.values[0] : '');
  if (!['none', 'queue_skip', 'priority'].includes(type) || (type === 'priority' && !config.supportsPriority)) {
    return discordInteractionMessage(discordVitalVipText(language, 'invalidType'));
  }
  if (type === 'none') {
    const updatedVip = await saveDiscordVitalVipUpdate(req, payload, discordUserId, { [config.typeField]: 'none' }, language, config.provider);
    return discordVitalVipUpdatedInteraction(updatedVip, language, config.provider);
  }
  const member = await readDiscordMemberForUserId(discordUserId);
  if (!member) return discordInteractionMessage(discordVitalVipText(language, 'needRegistration'));
  return discordVitalVipDateModal(member, payload, type, config.provider);
}

async function applyDiscordVitalVipUpdate(req, payload) {
  const language = discordInteractionLanguage(payload);
  const discordUserId = discordUserIdFromInteraction(payload);
  if (!discordUserId) return discordInteractionMessage(discordVitalVipText(language, 'noDiscordUser'));
  const customId = normalizeText(payload?.data?.custom_id, 120);
  const provider = discordVipProviderFromCustomId(customId, 'vital');
  const config = discordVipProviderConfig(provider);
  const typeFromCustomId = discordVipTypeFromSubmitCustomId(customId);
  const type = normalizeDiscordVipType(config.provider, discordModalValue(payload, 'vip_type') || typeFromCustomId);
  const updateInput = { [config.typeField]: type };
  if (!['none', 'queue_skip', 'priority'].includes(type) || (type === 'priority' && !config.supportsPriority)) {
    return discordInteractionMessage(discordVitalVipText(language, 'invalidType'));
  }
  if (type !== 'none') {
    const dateSelection = discordVitalVipDateSelection(payload);
    if (!dateSelection.date) {
      return discordInteractionMessage(discordVitalVipText(language, 'invalidDate'));
    }
    updateInput[config.purchasedAtField] = dateSelection.date;
  }
  const updatedVip = await saveDiscordVitalVipUpdate(req, payload, discordUserId, updateInput, language, config.provider);
  return discordVitalVipUpdatedInteraction(updatedVip, language, config.provider);
}

function discordRankingMemberName(row = {}) {
  return row.displayName ||
    row.member?.displayName ||
    (row.member ? memberDisplayName(row.member) : '') ||
    row.steamId ||
    '-';
}

function discordRankingMemberTeamName(row = {}, language = DISCORD_PUBLIC_MESSAGE_LANGUAGE) {
  return normalizeText(row.squadName || row.member?.squadName, 80) || discordText(language, 'unassignedSquad');
}

function discordRankingMetric(metric = DISCORD_MEMBER_RANKING_DEFAULT_METRIC) {
  return DISCORD_MEMBER_RANKING_METRICS.find((item) => item.metric === metric) || DISCORD_MEMBER_RANKING_METRICS[0];
}

function discordRankingMetricLabel(metric = DISCORD_MEMBER_RANKING_DEFAULT_METRIC, language = DISCORD_PUBLIC_MESSAGE_LANGUAGE) {
  const item = discordRankingMetric(metric);
  return item.labelKey ? discordText(language, item.labelKey) : item.label;
}

function discordRankingMetricValueText(row = {}, metric = DISCORD_MEMBER_RANKING_DEFAULT_METRIC, language = DISCORD_PUBLIC_MESSAGE_LANGUAGE) {
  const item = discordRankingMetric(metric);
  const value = wechatRankingMetricValue(row, item.metric);
  if (item.metric === 'online_minutes') return formatDiscordHours(value, language) || '-';
  if (item.metric === 'sulfur' || item.metric === 'metalOre') return formatExportCompactResource(value, language);
  return formatDiscordNumber(value, item.maximumFractionDigits, language);
}

function discordRankingAvatarUrl(store, row = {}) {
  const member = row.member || {};
  const steamAvatar = normalizeText(row.avatar || member.avatar, 500);
  if (steamAvatar) {
    try {
      const parsed = new URL(steamAvatar);
      if (parsed.protocol === 'https:') return parsed.toString();
    } catch {}
  }
  return memberDiscordAvatarUrl(store, member);
}

function discordRankingRankLabel(index = 0) {
  const rank = `#${index + 1}`;
  const medal = ['🥇', '🥈', '🥉'][index];
  return medal ? `${medal} ${rank}` : rank;
}

function discordRankingRowField(row = {}, index = 0, metric = DISCORD_MEMBER_RANKING_DEFAULT_METRIC, language = DISCORD_PUBLIC_MESSAGE_LANGUAGE) {
  const primary = discordRankingMetric(metric);
  const rankLabel = discordRankingRankLabel(index);
  const secondaryMetrics = [
    'kda',
    'kills',
    't3Kills',
    'deaths',
    'online_minutes'
  ].filter((item) => item !== primary.metric).slice(0, 3);
  const secondaryText = secondaryMetrics
    .map((item) => `${discordRankingMetricLabel(item, language)} ${discordRankingMetricValueText(row, item, language)}`)
    .join(' · ');
  return {
    name: `${rankLabel} ${discordRankingMemberName(row)} · ${discordRankingMemberTeamName(row, language)}`,
    value: [
      `**${discordRankingMetricLabel(primary.metric, language)}: ${discordRankingMetricValueText(row, primary.metric, language)}**`,
      secondaryText
    ].filter(Boolean).join('\n'),
    inline: false
  };
}

function discordRankingRows(store, metric = DISCORD_MEMBER_RANKING_DEFAULT_METRIC) {
  const rankingMetric = discordRankingMetric(metric).metric;
  const wipe = queryReferenceWipe(store);
  if (!wipe) return { wipe: null, rows: [] };
  const viewer = { id: 'discord_member_ranking', username: 'Discord Member Ranking', role: 'admin' };
  const indexes = getStoreIndexes(store);
  const rows = kdaRowsForWipe(store, wipe, viewer, { scope: 'all', sort: 'kda', order: 'desc' })
    .map((row) => {
      const member = row.member || store.members.find((item) => item.id === row.memberId || item.steamId === row.steamId) || null;
      const squadMember = member ? indexes.squadByMemberId.get(member.id) : null;
      const squad = squadMember ? indexes.squadsById.get(squadMember.squadId) : null;
      return member ? { ...row, member, avatar: row.avatar || member.avatar || '', squadName: squad?.name || row.squadName || '' } : row;
    })
    .sort((left, right) => {
      const diff = wechatRankingMetricValue(right, rankingMetric) - wechatRankingMetricValue(left, rankingMetric);
      if (diff !== 0) return diff;
      return String(left.displayName || left.steamId).localeCompare(String(right.displayName || right.steamId));
    });
  return { wipe, rows };
}

function buildDiscordMemberRankingComponents(selectedMetric = DISCORD_MEMBER_RANKING_DEFAULT_METRIC, language = DISCORD_PUBLIC_MESSAGE_LANGUAGE) {
  const metricButtons = DISCORD_MEMBER_RANKING_METRICS.map((item) => ({
    type: 2,
    custom_id: `${DISCORD_MEMBER_RANKING_PREFIX}:metric:${item.metric}`,
    label: normalizeText(discordRankingMetricLabel(item.metric, language), 80),
    style: item.metric === selectedMetric ? 1 : 2,
    emoji: item.emoji ? { name: item.emoji } : undefined
  }));
  const mineButton = {
    type: 2,
    custom_id: `${DISCORD_MEMBER_RANKING_PREFIX}:mine`,
    label: normalizeText(discordText(language, 'myRanking'), 80),
    style: 3,
    emoji: { name: '📊' }
  };
  const buttons = [...metricButtons, mineButton];
  const rows = [];
  for (let index = 0; index < buttons.length; index += 5) {
    rows.push({ type: 1, components: buttons.slice(index, index + 5) });
  }
  return rows;
}

export function buildDiscordMemberRankingMessage(store, options = {}) {
  const language = discordTextLanguage(options.language || DISCORD_PUBLIC_MESSAGE_LANGUAGE);
  const metric = discordRankingMetric(options.metric || DISCORD_MEMBER_RANKING_DEFAULT_METRIC).metric;
  const temporary = Boolean(options.temporary);
  const { wipe, rows } = discordRankingRows(store, metric);
  const topRows = rows.slice(0, DISCORD_MEMBER_RANKING_LIMIT);
  const updatedAt = kdaDataFreshness(rows).syncedAt || nowIso();
  const metricLabel = discordRankingMetricLabel(metric, language);
  const serverName = expandVitalRustName(wipe?.serverName || wipe?.name || '-');
  const deleteAt = temporary ? new Date(Date.now() + DISCORD_MEMBER_RANKING_DELETE_DELAY_MS).toISOString() : '';
  const header = [
    `${discordText(language, 'server')}: ${serverName}`,
    `${discordText(language, 'synced')}: ${discordTimestamp(updatedAt) || '-'}`,
    temporary ? discordText(language, 'rankingAutoDeleteCountdown', { time: discordTimestamp(deleteAt, 'R') || '' }) : ''
  ].filter(Boolean).join('\n');
  const topAvatarUrl = topRows.length ? discordRankingAvatarUrl(store, topRows[0]) : '';
  const embeds = [{
      title: discordText(language, 'memberRankingTitle', {
        metric: metricLabel,
        limit: DISCORD_MEMBER_RANKING_LIMIT
      }),
      description: topRows.length
        ? header
        : `${header}\n\n${discordText(language, 'noRankingData')}`.slice(0, 4096),
      ...(topAvatarUrl ? { thumbnail: { url: topAvatarUrl } } : {}),
      fields: topRows.map((row, index) => discordRankingRowField(row, index, metric, language)),
      color: 0x2563eb,
      footer: { text: discordText(language, 'memberRankingFooter') },
      timestamp: nowIso()
    }];
  return {
    embeds,
    components: buildDiscordMemberRankingComponents(metric, language)
  };
}

async function rememberDiscordMemberRankingMetric(settings = {}, metric = DISCORD_MEMBER_RANKING_DEFAULT_METRIC) {
  const selectedMetric = discordRankingMetric(metric).metric;
  const targetId = normalizeText(settings.targetId, DISCORD_TARGET_ID_MAX_LENGTH);
  await updateSettingsStore((store) => {
    const nextSettings = discordSettings(store);
    updateDiscordTargetStatus(nextSettings, targetId, {
      lastMemberRankingMetric: selectedMetric,
      lastMemberRankingRefreshAt: nowIso(),
      lastMemberRankingRefreshError: ''
    });
  }, 'discord_member_ranking_button');
}

async function buildDiscordMemberRankingMetricInteraction(store, metric, settings = {}) {
  const selectedMetric = discordRankingMetric(metric).metric;
  const language = discordCardLanguage(settings.lastMemberRankingLanguage || DISCORD_PUBLIC_MESSAGE_LANGUAGE);
  await rememberDiscordMemberRankingMetric(settings, selectedMetric);
  return discordInteractionUpdateMessage(buildDiscordMemberRankingMessage(store, {
    metric: selectedMetric,
    language
  }));
}

function buildDiscordMemberRankingMineMessage(store, member, language = DISCORD_DEFAULT_LANGUAGE) {
  const metrics = DISCORD_MEMBER_RANKING_METRICS.map((item) => item.metric);
  const { wipe, rows } = discordRankingRows(store, DISCORD_MEMBER_RANKING_DEFAULT_METRIC);
  const row = rows.find((item) => item.memberId === member.id || item.steamId === member.steamId);
  if (!row) return discordInteractionMessage(discordText(language, 'noMyRankingData'));
  const teamName = discordRankingMemberTeamName(row, language);
  const rankLines = metrics.map((metric) => {
    const sorted = [...rows].sort((left, right) => wechatRankingMetricValue(right, metric) - wechatRankingMetricValue(left, metric));
    const rank = sorted.findIndex((item) => item.memberId === member.id || item.steamId === member.steamId) + 1;
    const value = discordRankingMetricValueText(row, metric, language);
    return `${discordRankingMetricLabel(metric, language)}: ${value} · #${rank || '-'}`;
  });
  const deleteAt = new Date(Date.now() + DISCORD_MEMBER_RANKING_DELETE_DELAY_MS).toISOString();
  return {
    type: 4,
    data: {
      flags: 64,
      allowed_mentions: { parse: [] },
      embeds: [
        {
          title: discordText(language, 'myRankingTitle', { name: `${memberDisplayName(member)} · ${teamName}` }),
          description: [
            `${discordText(language, 'server')}: ${expandVitalRustName(wipe?.serverName || wipe?.name || '-')}`,
            `${discordText(language, 'squad')}：${teamName}`,
            `SteamID：${member.steamId}`,
            '',
            rankLines.join('\n'),
            '',
            discordText(language, 'rankingAutoDeleteCountdown', { time: discordTimestamp(deleteAt, 'R') || '' })
          ].join('\n').slice(0, 4096),
          color: 0x0f9f6e,
          timestamp: nowIso()
        }
      ]
    }
  };
}

function kookCardPlainText(content, limit = 2000) {
  return { type: 'plain-text', content: normalizeText(content, limit) };
}

function kookCardKmarkdown(content, limit = 5000) {
  return { type: 'kmarkdown', content: normalizeText(content, limit) };
}

function kookRankingButtonElement(item, selectedMetric, language) {
  const label = [item.emoji, discordRankingMetricLabel(item.metric, language)].filter(Boolean).join(' ');
  return {
    type: 'button',
    theme: item.metric === selectedMetric ? 'primary' : 'secondary',
    value: `${KOOK_MEMBER_RANKING_PREFIX}:metric:${item.metric}`,
    click: 'return-val',
    text: kookCardPlainText(label, 80)
  };
}

function kookRankingMemberName(row = {}) {
  return discordRankingMemberName(row).replace(/dictator/gi, (match) => `${match.slice(0, 1)}***${match.slice(-4)}`);
}

function buildKookMemberRankingButtonGroups(selectedMetric = DISCORD_MEMBER_RANKING_DEFAULT_METRIC, language = DISCORD_PUBLIC_MESSAGE_LANGUAGE) {
  const buttons = [
    ...DISCORD_MEMBER_RANKING_METRICS.map((item) => kookRankingButtonElement(item, selectedMetric, language)),
    {
      type: 'button',
      theme: 'secondary',
      value: `${KOOK_MEMBER_RANKING_PREFIX}:mine_disabled`,
      text: kookCardPlainText(`📊 ${discordText(language, 'myRankingUnavailable')}`, 80)
    }
  ];
  const groups = [];
  for (let index = 0; index < buttons.length; index += 4) {
    groups.push({ type: 'action-group', elements: buttons.slice(index, index + 4) });
  }
  return groups;
}

function kookRankingRowModule(store, row = {}, index = 0, metric = DISCORD_MEMBER_RANKING_DEFAULT_METRIC, language = DISCORD_PUBLIC_MESSAGE_LANGUAGE) {
  const primary = discordRankingMetric(metric);
  const rankLabel = discordRankingRankLabel(index);
  const secondaryMetrics = [
    'kda',
    'kills',
    't3Kills',
    'deaths',
    'online_minutes'
  ].filter((item) => item !== primary.metric).slice(0, 3);
  const secondaryText = secondaryMetrics
    .map((item) => `${discordRankingMetricLabel(item, language)} ${discordRankingMetricValueText(row, item, language)}`)
    .join(' · ');
  const lines = [
    `**${rankLabel} ${kookRankingMemberName(row)} · ${discordRankingMemberTeamName(row, language)}**`,
    `${discordRankingMetricLabel(primary.metric, language)}: **${discordRankingMetricValueText(row, primary.metric, language)}**`,
    secondaryText
  ].filter(Boolean);
  return {
    type: 'section',
    text: kookCardKmarkdown(lines.join('\n'), 1000)
  };
}

function buildKookMemberRankingCard(store, options = {}) {
  const language = discordTextLanguage(options.language || DISCORD_PUBLIC_MESSAGE_LANGUAGE);
  const metric = discordRankingMetric(options.metric || DISCORD_MEMBER_RANKING_DEFAULT_METRIC).metric;
  const { wipe, rows } = discordRankingRows(store, metric);
  const topRows = rows.slice(0, DISCORD_MEMBER_RANKING_LIMIT);
  const updatedAt = kdaDataFreshness(rows).syncedAt || nowIso();
  const metricLabel = discordRankingMetricLabel(metric, language);
  const serverName = expandVitalRustName(wipe?.serverName || wipe?.name || '-');
  const modules = [
    {
      type: 'header',
      text: kookCardPlainText(discordText(language, 'memberRankingTitle', {
        metric: metricLabel,
        limit: DISCORD_MEMBER_RANKING_LIMIT
      }), 100)
    },
    {
      type: 'section',
      text: kookCardKmarkdown([
        `**${discordText(language, 'server')}**: ${serverName}`,
        `**${discordText(language, 'synced')}**: ${formatDiscordDateTime(updatedAt, language) || '-'}`
      ].join('\n'), 1000)
    },
    { type: 'divider' },
    ...(topRows.length
      ? topRows.map((row, index) => kookRankingRowModule(store, row, index, metric, language))
      : [{ type: 'section', text: kookCardKmarkdown(discordText(language, 'noRankingData'), 1000) }]),
    { type: 'divider' },
    ...buildKookMemberRankingButtonGroups(metric, language),
    {
      type: 'context',
      elements: [kookCardPlainText(discordText(language, 'memberRankingFooter'), 200)]
    }
  ];
  const cards = [{
    type: 'card',
    theme: 'info',
    color: '#2563eb',
    size: 'lg',
    modules
  }];
  return {
    type: 10,
    cards,
    content: JSON.stringify(cards)
  };
}

function buildKookMemberRankingMineContent(store, member, language = DISCORD_DEFAULT_LANGUAGE) {
  const metrics = DISCORD_MEMBER_RANKING_METRICS.map((item) => item.metric);
  const { wipe, rows } = discordRankingRows(store, DISCORD_MEMBER_RANKING_DEFAULT_METRIC);
  const row = rows.find((item) => item.memberId === member.id || item.steamId === member.steamId);
  if (!row) return discordText(language, 'noMyRankingData');
  const teamName = discordRankingMemberTeamName(row, language);
  const rankLines = metrics.map((metric) => {
    const sorted = [...rows].sort((left, right) => wechatRankingMetricValue(right, metric) - wechatRankingMetricValue(left, metric));
    const rank = sorted.findIndex((item) => item.memberId === member.id || item.steamId === member.steamId) + 1;
    return `${discordRankingMetricLabel(metric, language)}: ${discordRankingMetricValueText(row, metric, language)} · #${rank || '-'}`;
  });
  return [
    `**${discordText(language, 'myRankingTitle', { name: `${memberDisplayName(member)} · ${teamName}` })}**`,
    `${discordText(language, 'server')}: ${expandVitalRustName(wipe?.serverName || wipe?.name || '-')}`,
    `${discordText(language, 'squad')}: ${teamName}`,
    `SteamID: ${member.steamId}`,
    '',
    rankLines.join('\n')
  ].join('\n');
}

function kookMemberForUserId(store, kookUserId) {
  const normalizedKookId = normalizeText(kookUserId, KOOK_ID_MAX_LENGTH);
  if (!normalizedKookId) return null;
  return (store.members || []).find((member) => [
    member.kookId,
    member.kookUserId,
    member.kookAccountId
  ].some((value) => normalizeText(value, KOOK_ID_MAX_LENGTH) === normalizedKookId)) || null;
}

async function refreshDiscordMemberRankingCard(options = {}) {
  const snapshot = await readMemberRankingRuntimeStore({ reference: 'query', scopeMembersToRows: true });
  const baseSettings = discordSettings(snapshot);
  const targetSettings = options.targetId
    ? [discordSettingsForTarget(baseSettings, options.targetId)]
    : discordTargets(baseSettings).map((target) => discordTargetSettings(baseSettings, target));
  const results = [];
  for (const settings of targetSettings) {
    const channelId = normalizeText(settings.memberRankingChannelId, DISCORD_ID_MAX_LENGTH);
    const messageId = normalizeText(settings.lastMemberRankingMessageId, 80);
    if (!discordBotToken(settings) || !channelId || !messageId) {
      results.push({ targetId: settings.targetId, skipped: true, reason: 'not_configured' });
      continue;
    }
    const operationRun = await createOperationRun({
      type: 'discord_member_ranking_card_update',
      platform: 'discord',
      source: options.source || (options.silent ? 'auto' : 'manual'),
      status: 'running',
      targetType: 'member_ranking_card',
      targetId: settings.targetId || channelId,
      messageId,
      channelId,
      dedupeKey: `discord:member-ranking-card:update:${channelId}:${messageId}`,
      createdBy: options.createdBy || 'system',
      metadata: {
        targetId: settings.targetId || '',
        targetName: settings.targetName || ''
      }
    }).catch(() => null);
    if (!operationRun?.id) {
      results.push({ targetId: settings.targetId, skipped: true, reason: 'operation_run_unavailable' });
      if (!options.silent) requireOperationRun(operationRun);
      continue;
    }
    try {
      const language = discordCardLanguage(settings.lastMemberRankingLanguage);
      const message = buildDiscordMemberRankingMessage(snapshot, { language });
      const discordMessage = await editDiscordChannelMessage(settings, channelId, messageId, message);
      const refreshedAt = nowIso();
      const refreshedMessageId = normalizeText(discordMessage?.id || messageId, 80);
      let trackingWriteError = null;
      try {
        await updateSettingsLogStore((store) => {
          const nextSettings = discordSettings(store);
          updateDiscordTargetStatus(nextSettings, settings.targetId, {
            lastMemberRankingRefreshAt: refreshedAt,
            lastMemberRankingRefreshError: ''
          });
          return {
            upserts: discordCardMessageRefUpserts(
              DISCORD_MEMBER_RANKING_MESSAGE_REF_KIND,
              DISCORD_TARGET_MESSAGE_REF_TARGET_TYPE,
              settings.targetId || channelId,
              channelId,
              { ...discordMessage, id: refreshedMessageId },
              settings,
              {
                store,
                source: 'discord_member_ranking_card_refresh',
                action: 'refresh',
                metadata: { targetId: settings.targetId || '', targetName: settings.targetName || '', language }
              }
            )
          };
        }, 'discord_member_ranking_refresh');
      } catch (error) {
        trackingWriteError = error;
      }
      if (trackingWriteError) {
        let recoveredMessageRefCount = 0;
        let messageRefWriteError = null;
        const recoveryRefUpserts = discordCardMessageRefUpserts(
          DISCORD_MEMBER_RANKING_MESSAGE_REF_KIND,
          DISCORD_TARGET_MESSAGE_REF_TARGET_TYPE,
          settings.targetId || channelId,
          channelId,
          { ...discordMessage, id: refreshedMessageId },
          settings,
          {
            source: 'discord_member_ranking_card_refresh_recovery',
            action: 'refresh',
            metadata: {
              targetId: settings.targetId || '',
              targetName: settings.targetName || '',
              language,
              trackingWriteFailed: true
            }
          }
        );
        try {
          recoveredMessageRefCount = await persistIntegrationMessageRefs(
            recoveryRefUpserts.integrationMessageRefs || [],
            'discord_member_ranking_refresh_message_ref_recovery'
          );
        } catch (refError) {
          messageRefWriteError = refError;
        }
        const trackingError = sqliteDirectWriteUnavailableError('Discord 排行卡状态记录', trackingWriteError);
        await finishOperationRun(operationRun, {
          status: 'failed',
          messageId: refreshedMessageId,
          channelId: normalizeText(discordMessage?.channel_id || channelId, DISCORD_ID_MAX_LENGTH),
          errorSummary: normalizeText(trackingWriteError.message || trackingWriteError, 500),
          retryable: true,
          metadata: {
            targetId: settings.targetId || '',
            targetName: settings.targetName || '',
            channelId,
            language,
            externalActionSucceeded: true,
            trackingWriteFailed: true,
            trackingWriteError: normalizeText(trackingWriteError.message || trackingWriteError, 240),
            messageRefRecovered: recoveredMessageRefCount > 0,
            messageRefWriteFailed: Boolean(messageRefWriteError),
            messageRefWriteError: normalizeText(messageRefWriteError?.message || '', 240)
          }
        });
        trackingError.discordMemberRankingTrackingWriteFailed = true;
        trackingError.discordMessageId = refreshedMessageId;
        throw trackingError;
      }
      await finishOperationRun(operationRun, {
        status: 'succeeded',
        messageId: refreshedMessageId,
        channelId: normalizeText(discordMessage?.channel_id || channelId, DISCORD_ID_MAX_LENGTH),
        metadata: { targetId: settings.targetId || '', targetName: settings.targetName || '' }
      });
      results.push({ targetId: settings.targetId, skipped: false, message: discordMessage });
    } catch (error) {
      if (error?.discordMemberRankingTrackingWriteFailed) {
        results.push({
          targetId: settings.targetId,
          skipped: true,
          reason: 'tracking_write_failed',
          error,
          messageId: normalizeText(error.discordMessageId, 80)
        });
        if (!options.silent) throw error;
        continue;
      }
      const errorMessage = normalizeText(error.message || 'Discord ranking refresh failed', 240);
      await updateSettingsStore((store) => {
        const nextSettings = discordSettings(store);
        updateDiscordTargetStatus(nextSettings, settings.targetId, {
          lastMemberRankingRefreshError: errorMessage
        });
      }, 'discord_member_ranking_refresh_failed');
      await finishOperationRun(operationRun, {
        status: 'failed',
        errorSummary: errorMessage,
        retryable: true,
        metadata: { targetId: settings.targetId || '', targetName: settings.targetName || '', channelId, messageId }
      });
      results.push({ targetId: settings.targetId, skipped: true, reason: 'failed', error });
      if (!options.silent) throw error;
    }
  }
  return {
    skipped: results.every((result) => result.skipped),
    results
  };
}

function publicMemberRankingRefreshResult(result = {}) {
  if (Array.isArray(result.results)) {
    return {
      skipped: Boolean(result.skipped),
      results: result.results.map((item) => ({
        targetId: item.targetId || '',
        skipped: Boolean(item.skipped),
        reason: item.reason || '',
        messageId: normalizeText(item.messageId || item.message?.id || item.message?.messageId || item.message?.msg_id, 120),
        error: normalizeText(item.error?.message || item.error, 240)
      }))
    };
  }
  return {
    skipped: Boolean(result.skipped),
    reason: result.reason || '',
    action: result.action || '',
    messageId: normalizeText(result.messageId || result.message?.id || result.message?.messageId || result.message?.msg_id, 120),
    error: normalizeText(result.error?.message || result.error, 240)
  };
}

function queueDiscordMemberRankingCardRefresh(reason = 'sync') {
  if (process.env.NB_DISABLE_BACKGROUND_JOBS === '1') return;
  queueBackgroundTask(`discord-member-ranking-card-refresh:${reason}`, () => (
    refreshDiscordMemberRankingCard({ silent: true })
  ), 0).catch(() => {});
}

async function refreshKookMemberRankingCard(options = {}) {
  const snapshot = await readMemberRankingRuntimeStore({ reference: 'query', scopeMembersToRows: true });
  const settings = kookSettings(snapshot);
  const channelId = normalizeText(settings.memberRankingChannelId, KOOK_ID_MAX_LENGTH);
  const messageId = normalizeText(settings.lastMemberRankingMessageId, 120);
  if (!kookBotToken(settings) || !channelId || !messageId) {
    return { skipped: true, reason: 'not_configured' };
  }
  const operationRun = await createOperationRun({
    type: 'kook_member_ranking_card_refresh',
    platform: 'kook',
    source: options.source || (options.silent ? 'auto' : 'manual'),
    status: 'running',
    targetType: 'member_ranking_card',
    targetId: channelId,
    messageId,
    channelId,
    dedupeKey: `kook:member-ranking-card:refresh:${channelId}:${messageId}`,
    createdBy: options.createdBy || 'system',
    metadata: { channelId }
  }).catch(() => null);
  if (!operationRun?.id) {
    if (!options.silent) requireOperationRun(operationRun);
    return { skipped: true, reason: 'operation_run_unavailable' };
  }
	  try {
	    const language = discordCardLanguage(settings.lastMemberRankingLanguage);
	    const metric = discordRankingMetric(settings.lastMemberRankingMetric || DISCORD_MEMBER_RANKING_DEFAULT_METRIC).metric;
	    const message = buildKookMemberRankingCard(snapshot, { language, metric });
	    const result = await upsertKookCardMessage(settings, channelId, message.cards, {
	      messageId,
	      fallbackToCreate: true,
	      cleanupSource: options.source || (options.silent ? 'auto' : 'manual'),
	      createdBy: options.createdBy || 'system'
	    });
	    const refreshedAt = nowIso();
	    const refreshedMessageId = result.messageId || messageId;
	    let trackingWriteError = null;
	    try {
	      await updateSettingsLogStore((store) => {
	        const nextSettings = kookSettings(store);
	        nextSettings.lastMemberRankingMessageId = refreshedMessageId;
	        nextSettings.lastMemberRankingRefreshAt = refreshedAt;
	        nextSettings.lastMemberRankingRefreshError = '';
	        return {
	          upserts: kookCardMessageRefUpserts(
	            KOOK_MEMBER_RANKING_MESSAGE_REF_KIND,
	            KOOK_TARGET_MESSAGE_REF_TARGET_TYPE,
	            channelId,
	            channelId,
	            { ...result, messageId: refreshedMessageId },
	            settings,
	            {
	              store,
	              source: 'kook_member_ranking_card_refresh',
	              action: result.action || 'refresh',
	              metadata: { channelId, metric, language }
	            }
	          )
	        };
	      }, 'kook_member_ranking_refresh');
	    } catch (error) {
	      trackingWriteError = error;
	    }
	    if (trackingWriteError) {
	      let recoveredMessageRefCount = 0;
	      let messageRefWriteError = null;
	      const recoveryRefUpserts = kookCardMessageRefUpserts(
	        KOOK_MEMBER_RANKING_MESSAGE_REF_KIND,
	        KOOK_TARGET_MESSAGE_REF_TARGET_TYPE,
	        channelId,
	        channelId,
	        { ...result, messageId: refreshedMessageId },
	        settings,
	        {
	          source: 'kook_member_ranking_card_refresh_recovery',
	          action: result.action || 'refresh',
	          metadata: {
	            channelId,
	            metric,
	            language,
	            trackingWriteFailed: true
	          }
	        }
	      );
	      try {
	        recoveredMessageRefCount = await persistIntegrationMessageRefs(
	          recoveryRefUpserts.integrationMessageRefs || [],
	          'kook_member_ranking_refresh_message_ref_recovery'
	        );
	      } catch (refError) {
	        messageRefWriteError = refError;
	      }
	      const trackingError = sqliteDirectWriteUnavailableError('KOOK 排行卡状态记录', trackingWriteError);
	      await finishOperationRun(operationRun, {
	        status: 'failed',
	        messageId: normalizeText(refreshedMessageId, 120),
	        channelId,
	        errorSummary: normalizeText(trackingWriteError.message || trackingWriteError, 500),
	        retryable: true,
	        metadata: {
	          channelId,
	          action: result.action || '',
	          metric,
	          language,
	          cleanupDeletedCount: result.cleanup?.deleted || 0,
	          cleanupFailedCount: result.cleanup?.failed || 0,
	          cleanupMissingCount: result.cleanup?.missing || 0,
	          externalActionSucceeded: true,
	          trackingWriteFailed: true,
	          trackingWriteError: normalizeText(trackingWriteError.message || trackingWriteError, 240),
	          messageRefRecovered: recoveredMessageRefCount > 0,
	          messageRefWriteFailed: Boolean(messageRefWriteError),
	          messageRefWriteError: normalizeText(messageRefWriteError?.message || '', 240)
	        }
	      });
	      trackingError.kookMemberRankingTrackingWriteFailed = true;
	      trackingError.kookMessageId = refreshedMessageId;
	      trackingError.kookAction = result.action || '';
	      throw trackingError;
	    }
	    await finishOperationRun(operationRun, {
	      status: 'succeeded',
	      messageId: normalizeText(refreshedMessageId, 120),
	      channelId,
	      metadata: {
	        channelId,
	        action: result.action || '',
	        metric,
	        language,
	        cleanupDeletedCount: result.cleanup?.deleted || 0,
	        cleanupFailedCount: result.cleanup?.failed || 0,
	        cleanupMissingCount: result.cleanup?.missing || 0
	      }
	    });
	    return { skipped: false, messageId: refreshedMessageId, message: result.message, action: result.action };
	  } catch (error) {
	    if (error?.kookMemberRankingTrackingWriteFailed) {
	      if (!options.silent) throw error;
	      return {
	        skipped: true,
	        reason: 'tracking_write_failed',
	        error,
	        messageId: normalizeText(error.kookMessageId, 120),
	        action: normalizeText(error.kookAction, 40)
	      };
	    }
	    const errorMessage = normalizeText(error.message || 'KOOK ranking refresh failed', 240);
    await updateSettingsStore((store) => {
      const nextSettings = kookSettings(store);
      nextSettings.lastMemberRankingRefreshError = errorMessage;
    }, 'kook_member_ranking_refresh_failed');
    await finishOperationRun(operationRun, {
      status: 'failed',
      errorSummary: errorMessage,
      retryable: true,
      metadata: { channelId, messageId }
    });
    if (!options.silent) throw error;
    return { skipped: true, reason: 'failed', error };
  }
}

function queueKookMemberRankingCardRefresh(reason = 'sync') {
  if (process.env.NB_DISABLE_BACKGROUND_JOBS === '1') return;
  queueBackgroundTask(`kook-member-ranking-card-refresh:${reason}`, () => (
    refreshKookMemberRankingCard({ silent: true })
  ), 0).catch(() => {});
}

function queueMemberRankingCardRefresh(reason = 'sync') {
  queueDiscordMemberRankingCardRefresh(reason);
  queueKookMemberRankingCardRefresh(reason);
}

function kookEventData(payload = {}) {
  return payload?.d && typeof payload.d === 'object' ? payload.d : {};
}

function parseJsonObject(text = '') {
  const trimmed = String(text || '').trim();
  if (!trimmed) return null;
  try {
    const parsed = JSON.parse(trimmed);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

function parseKookWebhookJsonBuffer(buffer) {
  const body = Buffer.isBuffer(buffer) ? buffer : Buffer.from(String(buffer || ''));
  const candidates = [body];
  for (const inflate of [zlib.inflateSync, zlib.inflateRawSync]) {
    try {
      candidates.push(inflate(body));
    } catch {}
  }
  for (const candidate of candidates) {
    const parsed = parseJsonObject(candidate.toString('utf8'));
    if (parsed) return parsed;
  }
  throw Object.assign(new Error('KOOK webhook payload is not valid JSON.'), { status: 400 });
}

function decryptKookWebhookPayload(encryptedText = '', encryptKey = '') {
  const keyText = normalizeText(encryptKey, KOOK_ENCRYPT_KEY_MAX_LENGTH);
  if (!keyText) {
    throw Object.assign(new Error('KOOK Encrypt Key is required for encrypted webhook payloads.'), { status: 400 });
  }
  try {
    const decoded = Buffer.from(String(encryptedText || ''), 'base64');
    const iv = decoded.subarray(0, 16);
    const encryptedBody = Buffer.from(decoded.subarray(16).toString('utf8'), 'base64');
    const key = Buffer.alloc(32);
    Buffer.from(keyText).copy(key, 0, 0, Math.min(Buffer.byteLength(keyText), 32));
    const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv);
    return Buffer.concat([decipher.update(encryptedBody), decipher.final()]).toString('utf8');
  } catch (error) {
    throw Object.assign(new Error(`KOOK webhook decrypt failed: ${error.message || 'invalid payload'}`), { status: 400 });
  }
}

function parseKookWebhookPayload(buffer, settings = {}) {
  const parsed = parseKookWebhookJsonBuffer(buffer);
  if (!parsed?.encrypt) return parsed;
  const decryptedText = decryptKookWebhookPayload(parsed.encrypt, settings.encryptKey);
  const decrypted = parseJsonObject(decryptedText);
  if (!decrypted) throw Object.assign(new Error('KOOK encrypted webhook payload is not valid JSON.'), { status: 400 });
  return decrypted;
}

function kookEventVerifyToken(payload = {}) {
  const data = kookEventData(payload);
  return normalizeText(data.verify_token || data.verifyToken, KOOK_VERIFY_TOKEN_MAX_LENGTH);
}

function kookButtonEventBody(payload = {}) {
  const data = kookEventData(payload);
  const extra = data.extra && typeof data.extra === 'object' ? data.extra : {};
  if (extra.type !== 'message_btn_click') return null;
  return extra.body && typeof extra.body === 'object' ? extra.body : {};
}

function kookButtonEventValue(body = {}) {
  return normalizeText(body?.value, 160);
}

function kookButtonEventTargetId(payload = {}, body = {}) {
  const data = kookEventData(payload);
  return normalizeText(
    body?.target_id || body?.targetId || body?.channel_id || body?.channelId || data.target_id || data.targetId,
    KOOK_ID_MAX_LENGTH
  );
}

function kookButtonEventUserId(payload = {}, body = {}) {
  const data = kookEventData(payload);
  return normalizeText(
    body?.user_id || body?.userId || data.author_id || data.authorId || data.user_id || data.userId,
    KOOK_ID_MAX_LENGTH
  );
}

function kookButtonEventMessageId(payload = {}, body = {}, settings = {}) {
  const explicitMessageId = normalizeText(body?.msg_id || body?.msgId || body?.message_id || body?.messageId, 120);
  if (explicitMessageId) return explicitMessageId;
  const targetId = kookButtonEventTargetId(payload, body);
  const expectedChannelId = normalizeText(settings.memberRankingChannelId, KOOK_ID_MAX_LENGTH);
  if (targetId && expectedChannelId && targetId !== expectedChannelId) return '';
  return normalizeText(settings.lastMemberRankingMessageId, 120);
}

function kookMemberRankingButtonEventMatchesStoredCard(settings = {}, payload = {}, body = {}) {
  const value = kookButtonEventValue(body);
  if (!value.startsWith(KOOK_MEMBER_RANKING_PREFIX)) return false;
  const targetId = kookButtonEventTargetId(payload, body);
  const expectedChannelId = normalizeText(settings.memberRankingChannelId, KOOK_ID_MAX_LENGTH);
  if (targetId && expectedChannelId && targetId !== expectedChannelId) return false;
  const messageId = kookButtonEventMessageId(payload, body, settings);
  const expectedMessageId = normalizeText(settings.lastMemberRankingMessageId, 120);
  if (expectedMessageId && messageId && messageId !== expectedMessageId) return false;
  return Boolean(expectedMessageId || messageId);
}

function sendKookChallengeResponse(res, challenge) {
  const body = JSON.stringify({ challenge: normalizeText(challenge, 500) });
  res.statusCode = 200;
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Content-Length', String(Buffer.byteLength(body)));
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('Connection', 'close');
  res.end(body);
}

function cleanupKookWebhookDedupe(now = Date.now()) {
  for (const [key, expiresAt] of kookWebhookRecentEvents.entries()) {
    if (expiresAt > now) break;
    kookWebhookRecentEvents.delete(key);
  }
  while (kookWebhookRecentEvents.size > KOOK_WEBHOOK_DEDUPE_MAX) {
    const oldestKey = kookWebhookRecentEvents.keys().next().value;
    if (!oldestKey) break;
    kookWebhookRecentEvents.delete(oldestKey);
  }
}

function kookWebhookEventDedupeKey(payload = {}, body = {}) {
  const data = kookEventData(payload);
  const stableParts = [
    data.msg_id,
    data.msgId,
    data.event_id,
    data.eventId,
    data.message_id,
    data.messageId,
    data.target_id,
    data.targetId,
    data.channel_id,
    data.channelId,
    data.author_id,
    data.authorId,
    data.user_id,
    data.userId,
    kookButtonEventValue(body)
  ].map((item) => normalizeText(item, 160)).filter(Boolean);
  if (stableParts.length) return stableParts.join(':');
  const fallbackParts = [payload.s, payload.sn, payload.t].map((item) => normalizeText(item, 160)).filter(Boolean);
  if (fallbackParts.length) return fallbackParts.join(':');
  return crypto.createHash('sha1').update(JSON.stringify(payload || {})).digest('hex');
}

function claimKookWebhookEvent(payload = {}, body = {}) {
  const now = Date.now();
  cleanupKookWebhookDedupe(now);
  const key = kookWebhookEventDedupeKey(payload, body);
  const expiresAt = kookWebhookRecentEvents.get(key) || 0;
  if (expiresAt > now) return { claimed: false, key };
  kookWebhookRecentEvents.set(key, now + KOOK_WEBHOOK_DEDUPE_TTL_MS);
  cleanupKookWebhookDedupe(now);
  return { claimed: true, key };
}

function queueKookWebhookButtonEvent(payload = {}, existingClaim = null, options = {}) {
  const body = kookButtonEventBody(payload);
  const claim = existingClaim || claimKookWebhookEvent(payload, body);
  if (!claim.claimed) return { queued: false, reason: 'duplicate', key: claim.key };
  const integrationEventId = normalizeText(options.integrationEventId, 120);
  queueInteractionTask(
    `kook-webhook-button:${claim.key}`,
    () => handleKookMemberRankingButtonEvent(payload, { integrationEventId }),
    0
  )
    .catch((error) => {
      console.error('[nb-clan] KOOK webhook button task failed:', error);
    });
  return { queued: true, key: claim.key };
}

function kookButtonEventLanguage(settings = {}, _body = {}) {
  return discordCardLanguage(settings.lastMemberRankingLanguage || DISCORD_PUBLIC_MESSAGE_LANGUAGE);
}

async function recordKookButtonIntegrationEventStatus(integrationEventId, patch = {}) {
  const id = normalizeText(integrationEventId, 120);
  if (!id) return null;
  return updateIntegrationEvent(id, {
    ...patch,
    metadata: {
      handler: 'kook_member_ranking_button',
      ...(patch.metadata || {})
    }
  }).catch((error) => {
    console.warn('[nb-clan] KOOK webhook button integration event update failed:', error?.message || error);
    return null;
  });
}

async function handleKookMemberRankingButtonEvent(payload = {}, options = {}) {
  const integrationEventId = normalizeText(options.integrationEventId, 120);
  const body = kookButtonEventBody(payload);
  if (!body) {
    await recordKookButtonIntegrationEventStatus(integrationEventId, {
      status: 'skipped',
      processedAt: nowIso(),
      errorSummary: '',
      metadata: { skipped: true, reason: 'not_button_event' }
    });
    return { skipped: true, reason: 'not_button_event' };
  }
  const value = kookButtonEventValue(body);
  if (!value.startsWith(KOOK_MEMBER_RANKING_PREFIX)) {
    await recordKookButtonIntegrationEventStatus(integrationEventId, {
      status: 'skipped',
      processedAt: nowIso(),
      errorSummary: '',
      metadata: { skipped: true, reason: 'unknown_button', buttonValue: value }
    });
    return { skipped: true, reason: 'unknown_button' };
  }
  try {
    await recordKookButtonIntegrationEventStatus(integrationEventId, {
      status: 'processing',
      metadata: { buttonValue: value }
    });
    const snapshot = await readMemberRankingRuntimeStore({ reference: 'query', scopeMembersToRows: true });
    const settings = kookSettings(snapshot);
    const language = kookButtonEventLanguage(settings, body);
    if (value.startsWith(`${KOOK_MEMBER_RANKING_PREFIX}:metric:`)) {
      const metric = discordRankingMetric(value.split(':')[2] || DISCORD_MEMBER_RANKING_DEFAULT_METRIC).metric;
      const targetId = kookButtonEventTargetId(payload, body);
      const channelId = normalizeText(settings.memberRankingChannelId, KOOK_ID_MAX_LENGTH);
      if (targetId && channelId && targetId !== channelId) {
        throw Object.assign(new Error('KOOK ranking button channel mismatch.'), { status: 400 });
      }
      const messageId = kookButtonEventMessageId(payload, body, settings);
      if (!messageId) throw Object.assign(new Error('KOOK ranking message id is missing.'), { status: 400 });
      const message = buildKookMemberRankingCard(snapshot, { language, metric });
	      const result = await upsertKookCardMessage(settings, channelId, message.cards, {
	        messageId,
	        fallbackToCreate: true,
	        cleanupSource: 'interaction',
	        createdBy: kookButtonEventUserId(payload, body)
	      });
	      const nextMessageId = result.messageId || messageId;
	      const refreshedAt = nowIso();
	      let trackingWriteError = null;
	      try {
	        await updateSettingsLogStore((store) => {
	          const nextSettings = kookSettings(store);
	          nextSettings.lastMemberRankingMessageId = nextMessageId;
	          nextSettings.lastMemberRankingMetric = metric;
	          nextSettings.lastMemberRankingRefreshAt = refreshedAt;
	          nextSettings.lastMemberRankingRefreshError = '';
	          return {
	            upserts: kookCardMessageRefUpserts(
	              KOOK_MEMBER_RANKING_MESSAGE_REF_KIND,
	              KOOK_TARGET_MESSAGE_REF_TARGET_TYPE,
	              channelId,
	              channelId,
	              { ...result, messageId: nextMessageId },
	              settings,
	              {
	                store,
	                source: 'kook_member_ranking_button',
	                action: result.action || 'button',
	                metadata: { channelId, metric, language }
	              }
	            )
	          };
	        }, 'kook_member_ranking_button');
	      } catch (error) {
	        trackingWriteError = error;
	      }
	      if (trackingWriteError) {
	        let recoveredMessageRefCount = 0;
	        let messageRefWriteError = null;
	        const recoveryRefUpserts = kookCardMessageRefUpserts(
	          KOOK_MEMBER_RANKING_MESSAGE_REF_KIND,
	          KOOK_TARGET_MESSAGE_REF_TARGET_TYPE,
	          channelId,
	          channelId,
	          { ...result, messageId: nextMessageId },
	          settings,
	          {
	            source: 'kook_member_ranking_button_recovery',
	            action: result.action || 'button',
	            metadata: {
	              channelId,
	              metric,
	              language,
	              trackingWriteFailed: true
	            }
	          }
	        );
	        try {
	          recoveredMessageRefCount = await persistIntegrationMessageRefs(
	            recoveryRefUpserts.integrationMessageRefs || [],
	            'kook_member_ranking_button_message_ref_recovery'
	          );
	        } catch (refError) {
	          messageRefWriteError = refError;
	        }
	        const trackingErrorText = normalizeText(trackingWriteError.message || trackingWriteError, 240);
	        await recordKookButtonIntegrationEventStatus(integrationEventId, {
	          status: 'failed',
	          processedAt: nowIso(),
	          errorSummary: trackingErrorText,
	          metadata: {
	            action: 'metric',
	            metric,
	            language,
	            channelId,
	            messageId: nextMessageId,
	            buttonValue: value,
	            externalActionSucceeded: true,
	            trackingWriteFailed: true,
	            trackingWriteError: trackingErrorText,
	            messageRefRecovered: recoveredMessageRefCount > 0,
	            messageRefWriteFailed: Boolean(messageRefWriteError),
	            messageRefWriteError: normalizeText(messageRefWriteError?.message || '', 240)
	          }
	        });
	        return {
	          skipped: true,
	          reason: 'tracking_write_failed',
	          action: 'metric',
	          message: result.message,
	          messageId: nextMessageId
	        };
	      }
	      await recordKookButtonIntegrationEventStatus(integrationEventId, {
	        status: 'processed',
	        processedAt: nowIso(),
        errorSummary: '',
        metadata: {
          action: 'metric',
          metric,
          language,
          channelId,
          messageId: nextMessageId,
          buttonValue: value
        }
      });
      return { skipped: false, action: 'metric', message: result.message };
    }
    if (value === `${KOOK_MEMBER_RANKING_PREFIX}:mine` || value === `${KOOK_MEMBER_RANKING_PREFIX}:mine_disabled`) {
      await recordKookButtonIntegrationEventStatus(integrationEventId, {
        status: 'skipped',
        processedAt: nowIso(),
        errorSummary: '',
        metadata: { skipped: true, reason: 'my_ranking_disabled', buttonValue: value }
      });
      return { skipped: true, reason: 'my_ranking_disabled' };
    }
    await recordKookButtonIntegrationEventStatus(integrationEventId, {
      status: 'skipped',
      processedAt: nowIso(),
      errorSummary: '',
      metadata: { skipped: true, reason: 'unknown_ranking_button', buttonValue: value }
    });
    return { skipped: true, reason: 'unknown_ranking_button' };
  } catch (error) {
    const errorMessage = normalizeText(error.message || 'KOOK ranking button failed', 240);
    await updateSettingsStore((store) => {
      const nextSettings = kookSettings(store);
      nextSettings.lastMemberRankingRefreshError = errorMessage;
    }, 'kook_member_ranking_button_failed');
    await recordKookButtonIntegrationEventStatus(integrationEventId, {
      status: 'failed',
      processedAt: nowIso(),
      errorSummary: errorMessage,
      metadata: {
        buttonValue: value,
        targetId: kookButtonEventTargetId(payload, body),
        messageId: kookButtonEventMessageId(payload, body)
      }
    });
    throw error;
  }
}

function enqueueDiscordSend(task) {
  const run = discordSendQueue.catch(() => {}).then(async () => {
    const waitMs = Math.max(0, discordNextSendAt - Date.now());
    if (waitMs) await sleep(waitMs);
    try {
      return await task();
    } finally {
      discordNextSendAt = Date.now() + DISCORD_SEND_INTERVAL_MS;
    }
  });
  discordSendQueue = run.catch(() => {});
  return run;
}

function discordRetryAfterMs(response, payload = {}, attempt = 1) {
  const values = [
    payload?.retry_after,
    response.headers.get('retry-after'),
    response.headers.get('x-ratelimit-reset-after')
  ].map((value) => Number(value)).filter((value) => Number.isFinite(value) && value >= 0);
  const ms = values.length
    ? Math.ceil(values[0] * 1000)
    : Math.min(DISCORD_RETRY_MAX_DELAY_MS, attempt * 1000);
  return Math.max(0, Math.min(ms, DISCORD_RETRY_MAX_DELAY_MS));
}

function discordApiUrl(pathname, query = {}) {
  const url = new URL(String(pathname || '').replace(/^\//, ''), `${DISCORD_API_BASE_URL}/`);
  for (const [key, value] of Object.entries(query || {})) {
    if (value === null || value === undefined || value === '') continue;
    url.searchParams.set(key, String(value));
  }
  return url;
}

function discordProviderScope(pathname = '', scope = '') {
  const explicitScope = normalizeText(scope, 120);
  if (explicitScope) return explicitScope;
  return normalizeText(String(pathname || '').replace(/\d{6,}/g, ':id'), 120) || 'request';
}

function discordHttpStatus(status) {
  if (Number(status) === 429) return 429;
  if (Number(status) >= 500) return 502;
  return Number(status) || 400;
}

function discordTimeoutError(timeoutMs = DISCORD_API_REQUEST_TIMEOUT_MS) {
  return Object.assign(new Error(`Discord API timeout after ${timeoutMs}ms`), { status: 504 });
}

function recordDiscordProviderFailure(error, scope) {
  if (!error?.circuitOpen) recordExternalProviderFailure(DISCORD_PROVIDER, error, scope);
}

async function discordResponsePayload(response) {
  if (response.status === 204) return null;
  return response.json().catch(async () => ({ message: await response.text().catch(() => '') }));
}

async function discordApiRequest(pathname, options = {}, attempt = 1) {
  const providerScope = discordProviderScope(pathname, options.scope);
  const timeoutMs = Math.max(1000, Number(options.timeoutMs || DISCORD_API_REQUEST_TIMEOUT_MS));
  const method = String(options.method || 'GET').toUpperCase();
  const retryAllowed = options.retry !== false && (
    ['GET', 'HEAD', 'PUT', 'DELETE', 'OPTIONS'].includes(method) ||
    options.retryUnsafe === true
  );
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    assertExternalProviderAvailable(DISCORD_PROVIDER, providerScope);
    const headers = { ...(options.headers || {}) };
    if (options.botToken && !headers.authorization) headers.authorization = `Bot ${options.botToken}`;
    if (options.bearerToken && !headers.authorization) headers.authorization = `Bearer ${options.bearerToken}`;
    let body = options.rawBody;
    if (body === undefined && options.body !== undefined) {
      body = JSON.stringify(options.body);
      headers['content-type'] ||= 'application/json';
    }
    const response = await nodeFetch(discordApiUrl(pathname, options.query), {
      method,
      headers,
      body,
      signal: controller.signal
    });
    const payload = await discordResponsePayload(response);
    const okStatuses = new Set(options.okStatuses || []);
    const ok = response.ok || okStatuses.has(response.status);
    if (ok) {
      recordExternalProviderSuccess(DISCORD_PROVIDER, providerScope);
      return { ok: true, response, payload };
    }
    const maxAttempts = Math.max(1, Number(options.maxAttempts || DISCORD_MESSAGE_MAX_ATTEMPTS));
    const shouldRetry = retryAllowed && (response.status === 429 || response.status >= 500) && attempt < maxAttempts;
    if (shouldRetry) {
      clearTimeout(timeout);
      await sleep(discordRetryAfterMs(response, payload || {}, attempt));
      return discordApiRequest(pathname, options, attempt + 1);
    }
    const error = Object.assign(new Error(`Discord HTTP ${response.status}`), {
      status: discordHttpStatus(response.status),
      discordCode: payload?.code
    });
    recordDiscordProviderFailure(error, providerScope);
    return { ok: false, response, payload, error };
  } catch (error) {
    const normalizedError = error?.name === 'AbortError' ? discordTimeoutError(timeoutMs) : error;
    const retryableNetworkError = !normalizedError?.status || normalizedError.status === 504;
    if (retryAllowed && retryableNetworkError && attempt < Math.max(1, Number(options.maxAttempts || DISCORD_MESSAGE_MAX_ATTEMPTS))) {
      clearTimeout(timeout);
      await sleep(Math.min(DISCORD_RETRY_MAX_DELAY_MS, attempt * 1000));
      return discordApiRequest(pathname, options, attempt + 1);
    }
    recordDiscordProviderFailure(normalizedError, providerScope);
    throw normalizedError;
  } finally {
    clearTimeout(timeout);
  }
}

async function postDiscordChannelMessage(token, targetChannelId, message, attempt = 1) {
  const nonce = normalizeText(message?.nonce, 25) || `${Date.now().toString(36)}${crypto.randomBytes(6).toString('hex')}`.slice(0, 25);
  const result = await discordApiRequest(`/channels/${encodeURIComponent(targetChannelId)}/messages`, {
    method: 'POST',
    botToken: token,
    body: {
      ...(message || {}),
      nonce,
      enforce_nonce: true
    },
    scope: 'channel_message_create',
    retryUnsafe: true,
    maxAttempts: DISCORD_MESSAGE_MAX_ATTEMPTS - attempt + 1
  });
  if (result.ok) return result.payload;
  const { response, payload, error } = result;
  const detail = normalizeText(payload?.message || payload?.error || `Discord HTTP ${response.status}`, 240);
  const status = error?.status || discordHttpStatus(response.status);
  throw Object.assign(new Error(`Discord push failed: ${detail}`), { status });
}

async function sendDiscordChannelMessage(settings, message, channelId = settings.channelId) {
  const token = discordBotToken(settings);
  const targetChannelId = normalizeText(channelId, DISCORD_ID_MAX_LENGTH);
  if (!token || !targetChannelId) {
    throw Object.assign(new Error('Discord Bot Token or Channel ID is not configured.'), { status: 400 });
  }
  return enqueueDiscordSend(() => postDiscordChannelMessage(token, targetChannelId, message));
}

export const __discordProviderHealthForTests = {
  postDiscordChannelMessage
};

async function fetchDiscordGuildMember(settings, discordUserId, attempt = 1) {
  const token = discordBotToken(settings);
  const guildId = normalizeText(settings?.guildId, DISCORD_ID_MAX_LENGTH);
  const userId = normalizeText(discordUserId, DISCORD_ID_MAX_LENGTH);
  if (!token || !guildId || !userId) {
    throw Object.assign(new Error('Discord Bot Token, Guild ID, or User ID is not configured.'), { status: 400 });
  }
  const result = await discordApiRequest(`/guilds/${encodeURIComponent(guildId)}/members/${encodeURIComponent(userId)}`, {
    botToken: token,
    scope: 'guild_member_get',
    okStatuses: [404],
    maxAttempts: DISCORD_MESSAGE_MAX_ATTEMPTS - attempt + 1
  });
  const { response, payload, error } = result;
  if (response.status === 404) {
    return { found: false, status: response.status, payload };
  }
  if (result.ok) {
    return { found: true, status: response.status, payload };
  }
  const detail = normalizeText(payload?.message || payload?.error || `Discord HTTP ${response.status}`, 240);
  throw Object.assign(new Error(`Discord member fetch failed: ${detail}`), { status: error?.status || discordHttpStatus(response.status) });
}

