const DISCORD_TARGET_CHANNEL_METADATA_FIELDS = [
  ['channelId', 'channelName'],
  ['memberRankingChannelId', 'memberRankingChannelName'],
  ['mapChannelId', 'mapChannelName']
];

async function resolveDiscordTargetMetadata(settings = {}) {
  const targets = discordTargets(settings).map((target) => ({ ...target }));
  const tokenConfigured = Boolean(discordBotToken(settings));
  const resolvedAt = nowIso();
  const guildRequests = new Map();

  for (const target of targets) {
    const guildId = normalizeText(target.guildId, DISCORD_ID_MAX_LENGTH);
    if (!guildId || guildRequests.has(guildId)) continue;
    const guildTargets = targets.filter((item) => item.guildId === guildId);
    const needsRoles = guildTargets.some((item) => normalizeDiscordMemberRegisterRoleSquadRules(item.memberRegisterRoleSquadRules).length > 0);
    const needsChannels = guildTargets.some((item) => DISCORD_TARGET_CHANNEL_METADATA_FIELDS.some(([idField]) => item[idField]));
    const targetSettings = { ...settings, guildId };
    guildRequests.set(guildId, Promise.all([
      needsRoles && tokenConfigured
        ? fetchDiscordGuildRoleNames(targetSettings, { retry: false, maxAttempts: 1, timeoutMs: 5_000 })
          .then((value) => ({ ok: true, value }))
          .catch((error) => ({ ok: false, error }))
        : Promise.resolve({ ok: !needsRoles, value: new Map(), error: needsRoles ? new Error('Discord Bot Token is not configured.') : null }),
      needsChannels && tokenConfigured
        ? fetchDiscordGuildChannelNames(targetSettings, { retry: false, maxAttempts: 1, timeoutMs: 5_000 })
          .then((value) => ({ ok: true, value }))
          .catch((error) => ({ ok: false, error }))
        : Promise.resolve({ ok: !needsChannels, value: new Map(), error: needsChannels ? new Error('Discord Bot Token is not configured.') : null })
    ]).then(([roles, channels]) => ({ roles, channels })));
  }

  const guildMetadata = new Map();
  await Promise.all([...guildRequests.entries()].map(async ([guildId, request]) => {
    guildMetadata.set(guildId, await request);
  }));

  return {
    resolvedAt,
    targets: targets.map((target) => {
      const guildId = normalizeText(target.guildId, DISCORD_ID_MAX_LENGTH);
      const configuredChannelIds = Object.fromEntries(DISCORD_TARGET_CHANNEL_METADATA_FIELDS.map(([idField]) => [idField, target[idField] || '']));
      const roleIds = normalizeDiscordMemberRegisterRoleSquadRules(target.memberRegisterRoleSquadRules).map((rule) => rule.roleId);
      const metadata = guildMetadata.get(guildId);
      const errors = [];
      if ((roleIds.length || Object.values(configuredChannelIds).some(Boolean)) && !guildId) {
        errors.push('Discord Guild ID is not configured.');
      }
      if (metadata?.roles?.error) errors.push(metadata.roles.error.message || String(metadata.roles.error));
      if (metadata?.channels?.error) errors.push(metadata.channels.error.message || String(metadata.channels.error));
      return {
        targetId: target.id,
        guildId,
        resolvedAt,
        roleIds,
        rolesResolved: Boolean(metadata?.roles?.ok),
        roleNames: metadata?.roles?.ok ? Object.fromEntries(metadata.roles.value) : {},
        configuredChannelIds,
        channelsResolved: Boolean(metadata?.channels?.ok),
        channelNames: metadata?.channels?.ok ? Object.fromEntries(metadata.channels.value) : {},
        error: normalizeText([...new Set(errors)].join(' '), 500)
      };
    })
  };
}

function applyDiscordTargetMetadata(settings = {}, metadata = {}) {
  const targets = discordTargets(settings);
  for (const patch of Array.isArray(metadata?.targets) ? metadata.targets : []) {
    const target = targets.find((item) => item.id === patch.targetId && item.guildId === patch.guildId);
    if (!target) continue;
    if (patch.channelsResolved) {
      for (const [idField, nameField] of DISCORD_TARGET_CHANNEL_METADATA_FIELDS) {
        const configuredId = normalizeText(patch.configuredChannelIds?.[idField], DISCORD_ID_MAX_LENGTH);
        if (target[idField] !== configuredId) continue;
        target[nameField] = configuredId ? normalizeText(patch.channelNames?.[configuredId], 100) : '';
      }
    }
    if (patch.rolesResolved) {
      const resolvedRoleIds = new Set(Array.isArray(patch.roleIds) ? patch.roleIds : []);
      target.memberRegisterRoleSquadRules = normalizeDiscordMemberRegisterRoleSquadRules(target.memberRegisterRoleSquadRules)
        .map((rule) => ({
          ...rule,
          roleName: resolvedRoleIds.has(rule.roleId) ? normalizeText(patch.roleNames?.[rule.roleId], 100) : rule.roleName
        }));
    }
    target.discordMetadataSyncedAt = normalizeText(patch.resolvedAt || metadata.resolvedAt, 80);
    target.discordMetadataSyncError = normalizeText(patch.error, 500);
  }
  syncDiscordLegacyFields(settings, targets[0]);
  return settings;
}

async function fetchDiscordChannelMessages(settings, channelId, afterMessageId = '') {
  const token = discordBotToken(settings);
  const targetChannelId = normalizeText(channelId, DISCORD_ID_MAX_LENGTH);
  if (!token || !targetChannelId) {
    throw Object.assign(new Error('Discord Bot Token or Channel ID is not configured.'), { status: 400 });
  }
  const url = new URL(`${DISCORD_API_BASE_URL}/channels/${encodeURIComponent(targetChannelId)}/messages`);
  url.searchParams.set('limit', String(DISCORD_KOOK_BRIDGE_BATCH_LIMIT));
  const after = normalizeText(afterMessageId, 80);
  if (after) url.searchParams.set('after', after);
  const result = await discordApiRequest(`/channels/${encodeURIComponent(targetChannelId)}/messages`, {
    botToken: token,
    query: Object.fromEntries(url.searchParams.entries()),
    scope: 'channel_messages_list'
  });
  const { response, payload, error } = result;
  if (!result.ok) {
    const detail = normalizeText(payload?.message || payload?.error || `Discord HTTP ${response.status}`, 240);
    throw Object.assign(new Error(`Discord message fetch failed: ${detail}`), { status: error?.status || discordHttpStatus(response.status) });
  }
  const messages = (Array.isArray(payload) ? payload : [])
    .filter((message) => message?.id)
    .sort((left, right) => {
      const leftTime = timestampForSort(left.timestamp);
      const rightTime = timestampForSort(right.timestamp);
      if (leftTime || rightTime) return leftTime - rightTime;
      try {
        const leftId = BigInt(left.id);
        const rightId = BigInt(right.id);
        return leftId === rightId ? 0 : (leftId < rightId ? -1 : 1);
      } catch {
        return String(left.id).localeCompare(String(right.id));
      }
    });
  return uniqueBridgeMessagesById(messages, (message) => normalizeText(message.id, 80));
}

