function bridgeTranslationContextText(message = {}, platform = 'discord') {
  return platform === 'kook'
    ? kookBridgeTranslationText(message)
    : discordBridgeTranslationText(message);
}

function bridgeTranslationContextAuthor(message = {}, platform = 'discord') {
  return platform === 'kook'
    ? kookMessageAuthorName(message)
    : discordMessageAuthorName(message);
}

function bridgeTranslationContextEntries(messages = [], currentMessage = null, platform = 'discord', route = {}) {
  const index = messages.indexOf(currentMessage);
  if (index < 0) return [];
  const start = Math.max(0, index - DISCORD_KOOK_BRIDGE_TRANSLATION_CONTEXT_RADIUS);
  const end = Math.min(messages.length - 1, index + DISCORD_KOOK_BRIDGE_TRANSLATION_CONTEXT_RADIUS);
  const entries = [];
  for (let cursor = start; cursor <= end; cursor += 1) {
    if (cursor === index) continue;
    const message = messages[cursor];
    if (platform === 'kook') {
      if (kookBridgeMessageShouldSkip(route, message)) continue;
    } else if (discordMessageContentUnavailable(message) || discordBridgeMessageShouldSkip(route, message)) {
      continue;
    }
    const text = normalizeText(bridgeTranslationContextText(message, platform), DISCORD_KOOK_BRIDGE_TRANSLATION_CONTEXT_LINE_MAX_LENGTH);
    if (!text) continue;
    entries.push({
      offset: cursor - index,
      author: normalizeText(bridgeTranslationContextAuthor(message, platform), 80) || (platform === 'kook' ? 'KOOK' : 'Discord'),
      text
    });
  }
  return entries;
}

function formatBridgeTranslationContext(contextEntries = []) {
  const entries = Array.isArray(contextEntries) ? contextEntries : [];
  const previous = entries.filter((entry) => Number(entry.offset) < 0);
  const next = entries.filter((entry) => Number(entry.offset) > 0);
  if (!previous.length && !next.length) return '';
  const lines = ['Context messages for meaning only; do not translate or output these lines.'];
  if (previous.length) {
    lines.push('Previous messages:');
    for (const entry of previous) {
      lines.push(`[${entry.offset}] ${entry.author}: ${entry.text}`);
    }
  }
  if (next.length) {
    lines.push('Next messages:');
    for (const entry of next) {
      lines.push(`[+${entry.offset}] ${entry.author}: ${entry.text}`);
    }
  }
  return normalizeText(lines.join('\n'), DISCORD_KOOK_BRIDGE_TRANSLATION_CONTEXT_MAX_LENGTH);
}

function bridgeTranslationIntentHints(text = '') {
  const source = normalizeText(text, DISCORD_KOOK_BRIDGE_TEXT_MAX_LENGTH);
  if (!source) return '';
  const hasRosterContext = /\b(?:wipe|play(?:ing)?|clan|team|roster|lineup|squad|group|raid|roam(?:ing)?|react|people|players|members|with\s+us)\b/i.test(source);
  const asksRosterDepth = /\bhow\s+deep\s+(?:(?:we|you|they)\s+(?:are|will\s+be)|(?:our|the)\s+team\s+(?:is|will\s+be))\b/i.test(source) ||
    /\bhow\s+deep\s+(?:are|will)\s+(?:we|you|they)\b/i.test(source);
  const statesRosterDepth = /\b(?:(?:we|you|they)(?:'re|\s+are)|(?:our|the)\s+team(?:'s|\s+is)|rolling|running|roaming|playing|coming)\s+\d{1,3}\s+deep\b/i.test(source);
  if (!(statesRosterDepth || (hasRosterContext && asksRosterDepth))) return '';
  return 'Detected Rust roster idiom: "deep" means player headcount or team size here, not physical depth. Translate it naturally as 有多少人/阵容多大/几人队 in Simplified Chinese, or the equivalent team-size wording in the requested language.';
}

function bridgeTranslationUserPrompt(targetLanguage = '', text = '', contextEntries = []) {
  const context = formatBridgeTranslationContext(contextEntries);
  const intentHints = bridgeTranslationIntentHints(text);
  return [
    `Target language: ${targetLanguage}`,
    intentHints,
    context,
    'Message to translate:',
    text
  ].filter(Boolean).join('\n\n');
}

async function translateBridgeMessage(content = '', store = {}, targetLanguageOverride = '', options = {}) {
  const text = normalizeText(content, DISCORD_KOOK_BRIDGE_TEXT_MAX_LENGTH);
  if (!text) return '';
  const apiKey = discordKookBridgeTranslationApiKey(store);
  if (!apiKey) {
    throw Object.assign(new Error('AI translation API key is not configured.'), { status: 400 });
  }
  const targetLanguage = normalizeText(targetLanguageOverride, 80) || bridgeTranslationTargetsForContent(text)[0]?.target || 'English';
  const translationBaseUrl = assertDiscordKookBridgeTranslationBaseUrl(discordKookBridgeTranslationBaseUrl(store));
  const url = new URL('chat/completions', `${translationBaseUrl}/`);
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), DISCORD_KOOK_BRIDGE_TRANSLATION_TIMEOUT_MS);
  try {
    const response = await nodeFetch(url, {
      method: 'POST',
      headers: {
        authorization: `Bearer ${apiKey}`,
        'content-type': 'application/json'
      },
      body: JSON.stringify({
        model: discordKookBridgeTranslationModel(store),
        temperature: 0,
        messages: [
          {
            role: 'system',
            content: DISCORD_KOOK_BRIDGE_TRANSLATION_PROMPT
          },
          {
            role: 'user',
            content: bridgeTranslationUserPrompt(targetLanguage, text, options.contextEntries)
          }
        ]
      }),
      signal: controller.signal
    });
    const payload = await response.json().catch(async () => ({ error: { message: await response.text().catch(() => '') } }));
    if (!response.ok) {
      const detail = normalizeText(payload?.error?.message || payload?.message || `AI HTTP ${response.status}`, 240);
      throw Object.assign(new Error(`AI translation failed: ${detail}`), { status: response.status >= 500 ? 502 : response.status });
    }
    return normalizeText(payload?.choices?.[0]?.message?.content || payload?.output_text || '', DISCORD_KOOK_BRIDGE_TEXT_MAX_LENGTH);
  } catch (error) {
    if (error?.name === 'AbortError') {
      throw Object.assign(new Error(`AI translation timeout after ${DISCORD_KOOK_BRIDGE_TRANSLATION_TIMEOUT_MS}ms`), { status: 504 });
    }
    throw error;
  } finally {
    clearTimeout(timeout);
  }
}

export const __discordKookBridgeTranslationForTests = {
  bridgeTranslationIntentHints,
  bridgeTranslationUserPrompt,
  systemPrompt: DISCORD_KOOK_BRIDGE_TRANSLATION_PROMPT,
  translateBridgeMessage
};

async function translateBridgeMessagePair(content = '', store = {}, languageIds = [], options = {}) {
  const text = normalizeText(content, DISCORD_KOOK_BRIDGE_TEXT_MAX_LENGTH);
  if (!text) return { primary: '', turkish: '', entries: [], sourceLanguage: '' };
  const sourceLanguage = bridgeMessageSourceLanguage(text);
  const targets = bridgeTranslationTargetsForContent(text, languageIds);
  const translations = await Promise.all(
    targets.map((target) => translateBridgeMessage(text, store, target.target, options))
  );
  const entries = targets.map((target, index) => ({
    languageId: target.id,
    label: target.label,
    text: translations[index] || ''
  })).filter((entry) => entry.text);
  return {
    primary: entries[0]?.text || '',
    turkish: entries.find((entry) => entry.languageId === 'tr')?.text || '',
    entries,
    sourceLanguage
  };
}

const BRIDGE_MESSAGE_SOURCE_MARKER = '\u2063\u200C\u200D\u2060\u200B\u2063';
const BRIDGE_MESSAGE_VISUAL_SPACER = '\u200B';

function bridgeMessageWithoutLeadingMention(content = '') {
  return normalizeText(content, DISCORD_KOOK_BRIDGE_TEXT_MAX_LENGTH)
    .replaceAll(BRIDGE_MESSAGE_SOURCE_MARKER, '')
    .replace(/\u200B/g, '')
    .trimStart()
    .replace(/^(?:@everyone|@here|\(met\)\s*(?:all|here)\s*\(met\))\s*/i, '')
    .trimStart();
}

function bridgeMessageLooksForwarded(content = '') {
  const raw = normalizeText(content, DISCORD_KOOK_BRIDGE_TEXT_MAX_LENGTH);
  if (!raw) return false;
  if (raw.includes(BRIDGE_MESSAGE_SOURCE_MARKER)) return true;
  const text = bridgeMessageWithoutLeadingMention(raw);
  return /^(?:Discord|KOOK)\s*·\s*[^\n]{1,100}\n{1,3}[^:\n]{1,100}:\s/.test(text);
}

function bridgeMessageLines(sourceName, authorName, original, translation, turkishTranslation = '', options = {}) {
  const author = normalizeText(authorName, 80) || '-';
  const lines = [
    sourceName
  ].filter((line) => String(line || '').trim());
  if (String(original || '').trim()) {
    lines.push(`${author}: ${original}`);
  } else if (options.showEmptyOriginal) {
    lines.push(`${author}:`);
  }
  if (translation) {
    lines.push(`${author}: ${translation}`);
  }
  if (turkishTranslation) {
    lines.push(`${author}: ${turkishTranslation}`);
  }
  for (const entry of Array.isArray(options.translationEntries) ? options.translationEntries : []) {
    const label = normalizeText(entry?.label, 40);
    const text = normalizeText(entry?.text, DISCORD_KOOK_BRIDGE_TEXT_MAX_LENGTH);
    if (!label || !text) continue;
    lines.push(`${label}: ${text}`);
  }
  return `${lines.join('\n\n')}\n\n${BRIDGE_MESSAGE_SOURCE_MARKER}${BRIDGE_MESSAGE_VISUAL_SPACER}`;
}

function bridgeDisplayTranslationEntries(entries = [], escapeFn = (value) => value, languageIds = []) {
  const allowedLanguageIds = new Set((Array.isArray(languageIds) ? languageIds : [])
    .map((item) => normalizeText(item, 20))
    .filter(Boolean));
  return (Array.isArray(entries) ? entries : [])
    .map((entry) => ({
      languageId: normalizeText(entry?.languageId, 20),
      label: escapeFn(entry?.label || ''),
      text: escapeFn(entry?.text || '')
    }))
    .filter((entry) => entry.label && entry.text)
    .filter((entry) => !allowedLanguageIds.size || allowedLanguageIds.has(entry.languageId));
}

function bridgeRouteSourceName(platform, route = {}) {
  const routeName = normalizeText(route.name, 80);
  return routeName ? `${platform} · ${routeName}` : platform;
}

function bridgeImageUnavailableText(count = 0) {
  const total = Math.max(0, Math.trunc(Number(count || 0)));
  if (!total) return '';
  return total === 1 ? 'image unavailable' : `${total} images unavailable`;
}

function formatDiscordToKookMessage(message = {}, translation = '', route = {}, options = {}) {
  const originalText = escapeKookKMarkdownText(discordBridgeMessageText(message));
  const messageImageUrls = discordMessageImageUrls(message);
  const imageUrls = options.includeImages === false ? [] : messageImageUrls;
  const failedImageText = escapeKookKMarkdownText(bridgeImageUnavailableText(options.failedImageCount));
  const originalBody = [originalText, failedImageText].filter(Boolean).join('\n');
  const original = bridgeOriginalWithImages(originalBody, imageUrls, 'kook');
  const mentionAll = discordMessageMentionsEveryone(message);
  const hasStructuredTranslations = Array.isArray(options.translationEntries);
  const translationEntries = bridgeDisplayTranslationEntries(options.translationEntries, escapeKookKMarkdownText, ['zh']);
  const content = bridgeMessageLines(
    bridgeRouteSourceName('Discord', route),
    escapeKookKMarkdownText(discordMessageAuthorName(message)),
    original,
    translationEntries.length || hasStructuredTranslations ? '' : escapeKookKMarkdownText(translation),
    '',
    {
      showEmptyOriginal: Boolean(messageImageUrls.length && !failedImageText),
      translationEntries
    }
  );
  return `${mentionAll ? '(met)all(met)\n\n' : ''}${content}`.slice(0, 8000);
}

function buildDiscordToKookBridgeCard(message = {}, translation = '', route = {}, imageUrls = [], options = {}) {
  const content = formatDiscordToKookMessage(message, translation, route, {
    includeImages: false,
    turkishTranslation: options.turkishTranslation,
    translationEntries: options.translationEntries
  });
  const cardImages = uniqueBridgeImageUrls(imageUrls)
    .map(kookBridgeImageElement)
    .filter(Boolean);
  return {
    type: 10,
    content: JSON.stringify([{
      type: 'card',
      theme: 'info',
      color: '#2563eb',
      size: 'lg',
      modules: [
        { type: 'section', text: kookCardKmarkdown(content, 4000) },
        ...cardImages.map((image) => ({ type: 'container', elements: [image] }))
      ]
    }])
  };
}

async function buildDiscordToKookPipeBody(kook = {}, message = {}, translation = '', route = {}, options = {}) {
  const imageUrls = discordMessageImageUrls(message);
  if (imageUrls.length) {
    const { assetUrls, failedUrls } = await prepareKookAssetImageUrls(kook, imageUrls);
    if (assetUrls.length) {
      return buildDiscordToKookBridgeCard(message, translation, route, assetUrls, options);
    }
    if (!discordBridgeMessageText(message)) {
      return { skipped: true, reason: 'image_unavailable' };
    }
    return { content: formatDiscordToKookMessage(message, translation, route, {
      includeImages: false,
      failedImageCount: failedUrls.length || imageUrls.length,
      turkishTranslation: options.turkishTranslation,
      translationEntries: options.translationEntries
    }) };
  }
  return { content: formatDiscordToKookMessage(message, translation, route, {
    turkishTranslation: options.turkishTranslation,
    translationEntries: options.translationEntries
  }) };
}

function formatKookToDiscordMessage(message = {}, translation = '', route = {}, options = {}) {
  const messageImageUrls = kookMessageImageUrls(message);
  const imageUrls = options.includeImages === false ? [] : messageImageUrls;
  const original = bridgeOriginalWithImages(kookBridgeMessageText(message), imageUrls, 'discord');
  const mentionAll = kookMessageMentionsEveryone(message);
  const hasStructuredTranslations = Array.isArray(options.translationEntries);
  const translationEntries = bridgeDisplayTranslationEntries(options.translationEntries, (value) => value, ['en', 'ru', 'tr']);
  const content = bridgeMessageLines(
    bridgeRouteSourceName('KOOK', route),
    kookMessageAuthorName(message),
    original,
    translationEntries.length || hasStructuredTranslations ? '' : translation,
    translationEntries.length || hasStructuredTranslations ? '' : options.turkishTranslation,
    {
      showEmptyOriginal: Boolean(messageImageUrls.length),
      translationEntries
    }
  );
  return `${mentionAll ? '@everyone\n\n' : ''}${content}`.slice(0, 2000);
}

function discordImageEmbed(url = '') {
  const imageUrl = bridgeImageUrl(url);
  if (!imageUrl) return null;
  return {
    color: 0x2563eb,
    image: { url: imageUrl }
  };
}

function buildKookToDiscordBridgePayload(message = {}, translation = '', route = {}, options = {}) {
  const embeds = uniqueBridgeImageUrls(kookMessageImageUrls(message))
    .map(discordImageEmbed)
    .filter(Boolean);
  return {
    content: formatKookToDiscordMessage(message, translation, route, {
      includeImages: false,
      turkishTranslation: options.turkishTranslation,
      translationEntries: options.translationEntries
    }),
    allowed_mentions: kookMessageMentionsEveryone(message) ? { parse: ['everyone'] } : { parse: [] },
    ...(embeds.length ? { embeds } : {})
  };
}

function discordBridgeMessageShouldSkip(bridge = {}, message = {}) {
  return Boolean(
    !message?.id ||
      message.author?.bot ||
      bridgeMessageLooksForwarded(message.content || '') ||
      discordMessageHasOnlyUnsupportedNonTextPayload(message) ||
      bridgeHasRecentMessage(bridge, 'discord', message.id)
  );
}

function discordMessageHasSticker(message = {}) {
  return Boolean(
    (Array.isArray(message.sticker_items) && message.sticker_items.length) ||
      (Array.isArray(message.stickers) && message.stickers.length)
  );
}

const DISCORD_MESSAGE_FLAG_HAS_SNAPSHOT = 16384;

function discordMessageHasSnapshotPayload(message = {}) {
  return Boolean(
    discordMessageSnapshotMessages(message).length ||
      (Number(message.flags || 0) & DISCORD_MESSAGE_FLAG_HAS_SNAPSHOT)
  );
}

function discordMessageHasOnlyUnsupportedNonTextPayload(message = {}) {
  const hasBridgePayload = Boolean(discordBridgeMessageText(message) || discordMessageImageUrls(message).length);
  return Boolean(
    (discordMessageHasSticker(message) || discordMessageHasSnapshotPayload(message)) &&
      !hasBridgePayload
  );
}

function discordMessageContentUnavailable(message = {}) {
  return Boolean(
    message?.id &&
      !message.author?.bot &&
      !discordBridgeMessageText(message) &&
      !discordMessageImageUrls(message).length &&
      !discordMessageHasOnlyUnsupportedNonTextPayload(message)
  );
}

function kookBridgeMessageShouldSkip(bridge = {}, message = {}) {
  const author = kookMessageAuthor(message);
  const hasText = Boolean(kookBridgeMessageText(message));
  const hasImages = Boolean(kookMessageImageUrls(message).length);
  return Boolean(
    !kookMessageId(message) ||
      author.bot ||
      message.author_id === '1' ||
      bridgeMessageLooksForwarded(message.content || '') ||
      bridgeMessageLooksForwarded(plainKookContent(message.content || '')) ||
      bridgeHasRecentMessage(bridge, 'kook', kookMessageId(message)) ||
      (!hasText && !hasImages) ||
      ![1, 2, 9, 10, '1', '2', '9', '10'].includes(message.type ?? 9)
  );
}

async function updateDiscordKookBridgeStore(patch = {}) {
  await updateSettingsStore((store) => {
    const bridge = discordKookBridgeSettings(store);
    Object.assign(bridge, patch);
  }, 'discord_kook_bridge_state');
}

async function updateDiscordKookBridgeRouteStore(routeId, patch = {}, recent = []) {
  const normalizedRouteId = normalizeText(routeId, DISCORD_KOOK_BRIDGE_ROUTE_ID_MAX_LENGTH);
  if (!normalizedRouteId) return;
  await updateSettingsStore((store) => {
    const bridge = discordKookBridgeSettings(store);
    const route = bridge.routes.find((item) => item.id === normalizedRouteId);
    if (!route) return;
    Object.assign(route, patch);
    for (const item of recent) {
      rememberBridgeMessage(route, item.platform, item.messageId);
    }
  }, 'discord_kook_bridge_route_state');
}

function discordKookBridgeMessageRefRecord(platform, route = {}, channelId = '', messageId = '', options = {}) {
  const normalizedRouteId = normalizeText(route.id, DISCORD_KOOK_BRIDGE_ROUTE_ID_MAX_LENGTH);
  if (!normalizedRouteId) return null;
  return platformCardMessageRefRecord(
    platform,
    DISCORD_KOOK_BRIDGE_MESSAGE_REF_KIND,
    DISCORD_KOOK_BRIDGE_MESSAGE_REF_TARGET_TYPE,
    normalizedRouteId,
    channelId,
    messageId,
    'active',
    {
      source: 'discord_kook_bridge_sync',
      action: 'forward',
      targetId: normalizedRouteId,
      targetName: normalizeText(route.name, 120),
      metadata: {
        routeId: normalizedRouteId,
        routeName: normalizeText(route.name, 120),
        direction: normalizeText(options.direction, 40),
        sourcePlatform: normalizeText(options.sourcePlatform, 40),
        sourceChannelId: normalizeText(options.sourceChannelId, 120),
        sourceMessageId: normalizeText(options.sourceMessageId, 120)
      }
    }
  );
}

async function persistDiscordKookBridgeMessageRef(ref) {
  if (!ref?.id) return 0;
  return persistIntegrationMessageRefs([ref], 'discord_kook_bridge_message_ref');
}

function discordKookBridgeMessageRefIsActive(ref = {}) {
  return normalizeText(ref.status, 40) === INTEGRATION_MESSAGE_REF_ACTIVE_STATUS;
}

function discordKookBridgeSourceMessageRefMatches(ref = {}, route = {}, direction = '', sourcePlatform = '', sourceMessageId = '') {
  const metadata = ref.metadata && typeof ref.metadata === 'object' ? ref.metadata : {};
  return Boolean(
    ref.kind === DISCORD_KOOK_BRIDGE_MESSAGE_REF_KIND &&
      ref.targetType === DISCORD_KOOK_BRIDGE_MESSAGE_REF_TARGET_TYPE &&
      ref.targetId === normalizeText(route.id, DISCORD_KOOK_BRIDGE_ROUTE_ID_MAX_LENGTH) &&
      discordKookBridgeMessageRefIsActive(ref) &&
      normalizeText(metadata.direction, 40) === normalizeText(direction, 40) &&
      normalizeText(metadata.sourcePlatform, 40) === normalizeText(sourcePlatform, 40) &&
      normalizeText(metadata.sourceMessageId, 120) === normalizeText(sourceMessageId, 120)
  );
}

function discordKookBridgeSourceMessageRefExists(snapshot = {}, route = {}, direction = '', sourcePlatform = '', sourceMessageId = '') {
  if (!sourceMessageId) return false;
  return (snapshot.integrationMessageRefs || []).some((ref) => (
    discordKookBridgeSourceMessageRefMatches(ref, route, direction, sourcePlatform, sourceMessageId)
  ));
}

async function readDiscordKookBridgeRouteMessageRefs(snapshot = {}, routes = []) {
  const routeIds = [...new Set(routes
    .map((route) => normalizeText(route.id, DISCORD_KOOK_BRIDGE_ROUTE_ID_MAX_LENGTH))
    .filter(Boolean))];
  if (!routeIds.length) return [];
  if (!sqliteEnabled()) {
    const routeIdSet = new Set(routeIds);
    return (snapshot.integrationMessageRefs || []).filter((ref) => (
      ref.kind === DISCORD_KOOK_BRIDGE_MESSAGE_REF_KIND &&
        ref.targetType === DISCORD_KOOK_BRIDGE_MESSAGE_REF_TARGET_TYPE &&
        routeIdSet.has(normalizeText(ref.targetId, DISCORD_KOOK_BRIDGE_ROUTE_ID_MAX_LENGTH))
    ));
  }
  try {
    return (await getSqliteRecordsByJsonField('integrationMessageRefs', 'targetId', routeIds, { limit: 0 }))
      .filter((ref) => (
        ref.kind === DISCORD_KOOK_BRIDGE_MESSAGE_REF_KIND &&
          ref.targetType === DISCORD_KOOK_BRIDGE_MESSAGE_REF_TARGET_TYPE
      ));
  } catch (error) {
    console.warn('[nb-clan] discord-kook bridge message refs partial fallback:', error?.message || error);
    return [];
  }
}

function appendDiscordKookBridgeTrackingFailure(target = {}, error, options = {}) {
  const errorMessage = normalizeText(error?.message || error || 'Discord-KOOK bridge tracking write failed', 240);
  target.trackingWriteFailed = true;
  target.trackingWriteError = [target.trackingWriteError, errorMessage]
    .map((item) => normalizeText(item, 240))
    .filter(Boolean)
    .filter((item, index, items) => items.indexOf(item) === index)
    .join('；')
    .slice(0, 240);
  target.externalActionSucceeded = Boolean(target.externalActionSucceeded || options.externalActionSucceeded);
  target.messageRefPersisted = Boolean(target.messageRefPersisted || options.messageRefPersisted);
  target.messageRefWriteFailed = Boolean(target.messageRefWriteFailed || options.messageRefWriteFailed);
  if (options.recovered) target.trackingRecovered = true;
  return errorMessage;
}

function discordKookBridgeRouteIsRunnable(route = {}) {
  return Boolean(discordKookBridgeRouteCanDiscordToKook(route) || discordKookBridgeRouteCanKookToDiscord(route));
}

async function processDiscordKookBridgeDirection(snapshot, route, direction, messages = []) {
  const discord = discordSettings(snapshot);
  const kook = kookSettings(snapshot);
  const result = { fetched: messages.length, forwarded: 0, skipped: 0 };
  for (const message of messages) {
    if (direction === 'discord_to_kook') {
      const messageId = normalizeText(message.id, 80);
      if (discordMessageContentUnavailable(message)) {
        result.skipped += 1;
        route.lastDiscordMessageId = messageId;
        await updateDiscordKookBridgeRouteStore(route.id, { lastDiscordMessageId: messageId });
        continue;
      }
      if (discordBridgeMessageShouldSkip(route, message)) {
        result.skipped += 1;
        route.lastDiscordMessageId = messageId;
        await updateDiscordKookBridgeRouteStore(route.id, { lastDiscordMessageId: messageId });
        continue;
      }
      if (discordKookBridgeSourceMessageRefExists(snapshot, route, direction, 'discord', messageId)) {
        result.skipped += 1;
        result.duplicateSourceMessageRefSkipped = (result.duplicateSourceMessageRefSkipped || 0) + 1;
        route.lastDiscordMessageId = messageId;
        try {
          await updateDiscordKookBridgeRouteStore(route.id, { lastDiscordMessageId: messageId });
        } catch (error) {
          appendDiscordKookBridgeTrackingFailure(result, error, { messageRefPersisted: true });
        }
        continue;
      }
      const translation = await translateBridgeMessagePair(discordBridgeTranslationText(message), snapshot, ['zh'], {
        contextEntries: bridgeTranslationContextEntries(messages, message, 'discord', route)
      });
      const kookPipeBody = await buildDiscordToKookPipeBody(kook, message, translation.primary, route, {
        turkishTranslation: translation.turkish,
        translationEntries: translation.entries
      });
      if (kookPipeBody?.skipped) {
        result.skipped += 1;
        route.lastDiscordMessageId = messageId;
        await updateDiscordKookBridgeRouteStore(route.id, { lastDiscordMessageId: messageId });
        continue;
      }
      let kookMessage;
      try {
        kookMessage = await sendKookPipeMessage(route, kookPipeBody);
      } catch (error) {
        if (!kookPipeContentRejected(error)) throw error;
        result.skipped += 1;
        route.lastDiscordMessageId = messageId;
        await updateDiscordKookBridgeRouteStore(route.id, { lastDiscordMessageId: messageId });
        continue;
      }
      const sentMessageId = normalizeText(kookMessage?.msg_id || kookMessage?.id, 120);
      const now = nowIso();
      result.forwarded += 1;
      route.lastDiscordMessageId = messageId;
      route.lastForwardedAt = now;
      route.lastForwardedKookMessageId = sentMessageId;
	      const messageRef = discordKookBridgeMessageRefRecord('kook', route, route.kookChannelId, sentMessageId, {
	        direction,
	        sourcePlatform: 'discord',
	        sourceChannelId: message.channel_id,
	        sourceMessageId: messageId
	      });
	      let messageRefPersisted = false;
	      try {
	        await persistDiscordKookBridgeMessageRef(messageRef);
	        messageRefPersisted = Boolean(messageRef?.id);
	      } catch (error) {
	        appendDiscordKookBridgeTrackingFailure(result, error, {
	          externalActionSucceeded: true,
	          messageRefPersisted: false,
	          messageRefWriteFailed: true
	        });
	      }
	      try {
	        await updateDiscordKookBridgeRouteStore(route.id, {
	          lastDiscordMessageId: messageId,
	          lastForwardedAt: now,
	          lastForwardedKookMessageId: sentMessageId
	        }, [{ platform: 'kook', messageId: sentMessageId }]);
	      } catch (error) {
	        appendDiscordKookBridgeTrackingFailure(result, error, {
	          externalActionSucceeded: true,
	          messageRefPersisted
	        });
	      }
      continue;
    }

    const messageId = kookMessageId(message);
    const messageAt = kookMessageTimestamp(message);
    if (kookBridgeMessageShouldSkip(route, message)) {
      result.skipped += 1;
      route.lastKookMessageId = messageId;
      route.lastKookMessageAt = messageAt ? String(messageAt) : route.lastKookMessageAt;
      await updateDiscordKookBridgeRouteStore(route.id, {
        lastKookMessageId: messageId,
        lastKookMessageAt: route.lastKookMessageAt || ''
      });
      continue;
    }
    if (discordKookBridgeSourceMessageRefExists(snapshot, route, direction, 'kook', messageId)) {
      result.skipped += 1;
      result.duplicateSourceMessageRefSkipped = (result.duplicateSourceMessageRefSkipped || 0) + 1;
      route.lastKookMessageId = messageId;
      route.lastKookMessageAt = messageAt ? String(messageAt) : route.lastKookMessageAt;
      try {
        await updateDiscordKookBridgeRouteStore(route.id, {
          lastKookMessageId: messageId,
          lastKookMessageAt: route.lastKookMessageAt || ''
        });
      } catch (error) {
        appendDiscordKookBridgeTrackingFailure(result, error, { messageRefPersisted: true });
      }
      continue;
    }
    const translation = await translateBridgeMessagePair(kookBridgeTranslationText(message), snapshot, ['en', 'ru', 'tr'], {
      contextEntries: bridgeTranslationContextEntries(messages, message, 'kook', route)
    });
    const discordMessage = await sendDiscordChannelMessage(discord, buildKookToDiscordBridgePayload(message, translation.primary, route, {
      turkishTranslation: translation.turkish,
      translationEntries: translation.entries
    }), route.discordChannelId);
    const sentMessageId = normalizeText(discordMessage?.id, 80);
    const now = nowIso();
    result.forwarded += 1;
    route.lastKookMessageId = messageId;
    route.lastKookMessageAt = messageAt ? String(messageAt) : route.lastKookMessageAt;
    route.lastForwardedAt = now;
    route.lastForwardedDiscordMessageId = sentMessageId;
	    const messageRef = discordKookBridgeMessageRefRecord('discord', route, route.discordChannelId, sentMessageId, {
	      direction,
	      sourcePlatform: 'kook',
	      sourceChannelId: route.kookChannelId,
	      sourceMessageId: messageId
	    });
	    let messageRefPersisted = false;
	    try {
	      await persistDiscordKookBridgeMessageRef(messageRef);
	      messageRefPersisted = Boolean(messageRef?.id);
	    } catch (error) {
	      appendDiscordKookBridgeTrackingFailure(result, error, {
	        externalActionSucceeded: true,
	        messageRefPersisted: false,
	        messageRefWriteFailed: true
	      });
	    }
	    try {
	      await updateDiscordKookBridgeRouteStore(route.id, {
	        lastKookMessageId: messageId,
	        lastKookMessageAt: route.lastKookMessageAt || '',
        lastForwardedAt: now,
        lastForwardedDiscordMessageId: sentMessageId
      }, [{ platform: 'discord', messageId: sentMessageId }]);
	    } catch (error) {
	      appendDiscordKookBridgeTrackingFailure(result, error, {
	        externalActionSucceeded: true,
	        messageRefPersisted
	      });
	    }
  }
  return result;
}

async function runDiscordKookBridgeRouteSync(snapshot, route, options = {}) {
  const routeStateBefore = {
    lastDiscordMessageId: route.lastDiscordMessageId || '',
    lastKookMessageId: route.lastKookMessageId || '',
    lastKookMessageAt: route.lastKookMessageAt || '',
    lastSyncAt: route.lastSyncAt || '',
    lastSyncError: route.lastSyncError || ''
  };
  const discord = discordSettings(snapshot);
  const kook = kookSettings(snapshot);
  const canDiscordToKook = discordKookBridgeRouteCanDiscordToKook(route);
  const canKookToDiscord = discordKookBridgeRouteCanKookToDiscord(route);
  const [discordFetch, kookFetch] = await Promise.allSettled([
    canDiscordToKook ? fetchDiscordChannelMessages(discord, route.discordChannelId, route.lastDiscordMessageId) : Promise.resolve([]),
    canKookToDiscord ? fetchKookChannelMessages(kook, route.kookChannelId, route.lastKookMessageId, route.lastKookMessageAt) : Promise.resolve([])
  ]);
  const discordMessages = discordFetch.status === 'fulfilled' ? discordFetch.value : [];
  const kookMessages = kookFetch.status === 'fulfilled' ? kookFetch.value : [];
  const result = {
    routeId: route.id,
    routeName: route.name || '',
    skipped: false,
    initialized: false,
    errors: 0,
    error: '',
    discordToKook: { fetched: discordMessages.length, forwarded: 0, skipped: 0 },
    kookToDiscord: { fetched: kookMessages.length, forwarded: 0, skipped: 0 }
  };
  const errors = [];

  if (!canDiscordToKook) {
    result.discordToKook.disabled = true;
    result.discordToKook.disabledReason = discordKookBridgeRouteHasBaseTargets(route) ? 'missing_kook_access_token' : 'not_configured';
  }
  if (!canKookToDiscord) {
    result.kookToDiscord.disabled = true;
    result.kookToDiscord.disabledReason = 'not_configured';
  }

  if (!canDiscordToKook) {
    result.discordToKook.fetched = 0;
  } else if (discordFetch.status === 'rejected') {
    const errorMessage = normalizeText(discordFetch.reason?.message || 'Discord message fetch failed', 240);
    result.discordToKook.error = errorMessage;
    errors.push(`Discord→KOOK: ${errorMessage}`);
  } else {
    try {
      if (!route.lastDiscordMessageId) {
        const latestDiscord = discordMessages.at(-1);
        const latestDiscordId = normalizeText(latestDiscord?.id, 80);
        if (latestDiscordId) route.lastDiscordMessageId = latestDiscordId;
        result.initialized = Boolean(latestDiscordId) || result.initialized;
      } else {
        result.discordToKook = await processDiscordKookBridgeDirection(snapshot, route, 'discord_to_kook', discordMessages);
        if (result.discordToKook.trackingWriteFailed) {
          errors.push(`Discord→KOOK tracking: ${result.discordToKook.trackingWriteError || 'tracking write failed'}`);
        }
      }
    } catch (error) {
      const errorMessage = normalizeText(error.message || 'Discord to KOOK sync failed', 240);
      result.discordToKook.error = errorMessage;
      errors.push(`Discord→KOOK: ${errorMessage}`);
    }
  }

  if (!canKookToDiscord) {
    result.kookToDiscord.fetched = 0;
  } else if (kookFetch.status === 'rejected') {
    const errorMessage = normalizeText(kookFetch.reason?.message || 'KOOK message fetch failed', 240);
    result.kookToDiscord.error = errorMessage;
    errors.push(`KOOK→Discord: ${errorMessage}`);
  } else {
    try {
      if (!route.lastKookMessageId) {
        const latestKook = kookMessages.at(-1);
        const latestKookId = kookMessageId(latestKook);
        const latestKookAt = kookMessageTimestamp(latestKook);
        if (latestKookId) route.lastKookMessageId = latestKookId;
        if (latestKookAt) route.lastKookMessageAt = String(latestKookAt);
        result.initialized = Boolean(latestKookId) || result.initialized;
      } else {
        result.kookToDiscord = await processDiscordKookBridgeDirection(snapshot, route, 'kook_to_discord', kookMessages);
        if (result.kookToDiscord.trackingWriteFailed) {
          errors.push(`KOOK→Discord tracking: ${result.kookToDiscord.trackingWriteError || 'tracking write failed'}`);
        }
      }
    } catch (error) {
      const errorMessage = normalizeText(error.message || 'KOOK to Discord sync failed', 240);
      result.kookToDiscord.error = errorMessage;
      errors.push(`KOOK→Discord: ${errorMessage}`);
    }
  }

  const syncedAt = nowIso();
  const errorSummary = normalizeText(errors.join('；'), 240);
  const lastPersistedSyncAt = timestampForSort(routeStateBefore.lastSyncAt);
  const heartbeatDue = Boolean(options.forceHeartbeat) ||
    !lastPersistedSyncAt ||
    Date.now() - lastPersistedSyncAt >= DISCORD_KOOK_BRIDGE_TRACE_HEARTBEAT_MS;
  const cursorChanged = routeStateBefore.lastDiscordMessageId !== (route.lastDiscordMessageId || '') ||
    routeStateBefore.lastKookMessageId !== (route.lastKookMessageId || '') ||
    routeStateBefore.lastKookMessageAt !== (route.lastKookMessageAt || '');
  const shouldPersistRouteState = Boolean(
    heartbeatDue ||
    result.initialized ||
    cursorChanged ||
    errors.length ||
    routeStateBefore.lastSyncError !== errorSummary
  );
  try {
	  if (shouldPersistRouteState) {
	    await updateDiscordKookBridgeRouteStore(route.id, {
	      lastDiscordMessageId: route.lastDiscordMessageId || '',
	      lastKookMessageId: route.lastKookMessageId || '',
	      lastKookMessageAt: route.lastKookMessageAt || '',
	      lastSyncAt: syncedAt,
	      lastSyncError: errorSummary
	    });
	  }
	    if (result.discordToKook.trackingWriteFailed && !result.discordToKook.messageRefWriteFailed) {
	      result.discordToKook.trackingRecovered = true;
	    }
	    if (result.kookToDiscord.trackingWriteFailed && !result.kookToDiscord.messageRefWriteFailed) {
	      result.kookToDiscord.trackingRecovered = true;
	    }
  } catch (error) {
    const finalTrackingError = appendDiscordKookBridgeTrackingFailure(result, error, {
      externalActionSucceeded: Boolean(result.discordToKook.forwarded || result.kookToDiscord.forwarded)
    });
    errors.push(`route tracking: ${finalTrackingError}`);
  }
	  result.trackingWriteFailed = Boolean(
	    result.trackingWriteFailed ||
	      result.discordToKook.trackingWriteFailed ||
	      result.kookToDiscord.trackingWriteFailed
	  );
	  result.messageRefWriteFailed = Boolean(
	    result.messageRefWriteFailed ||
	      result.discordToKook.messageRefWriteFailed ||
	      result.kookToDiscord.messageRefWriteFailed
	  );
	  result.messageRefPersisted = Boolean(
	    result.messageRefPersisted ||
	      result.discordToKook.messageRefPersisted ||
	      result.kookToDiscord.messageRefPersisted
	  );
	  result.externalActionSucceeded = Boolean(
	    result.externalActionSucceeded ||
	      result.discordToKook.externalActionSucceeded ||
      result.kookToDiscord.externalActionSucceeded
  );
  result.trackingWriteError = normalizeText(
    result.trackingWriteError ||
      result.discordToKook.trackingWriteError ||
      result.kookToDiscord.trackingWriteError,
    240
  );
  result.errors = errors.length;
  result.error = normalizeText(errors.join('；'), 240);
  return { ...result, syncedAt };
}

async function runDiscordKookBridgeSync(options = {}) {
  const traceHeartbeatDue = Boolean(options.manual) ||
    !discordKookBridgeLastTraceAt ||
    Date.now() - discordKookBridgeLastTraceAt >= DISCORD_KOOK_BRIDGE_TRACE_HEARTBEAT_MS;
  const operationRun = traceHeartbeatDue ? await createOperationRun({
    type: 'discord_kook_bridge_sync',
    platform: 'system',
    source: options.manual ? 'manual' : 'auto',
    status: 'running',
    targetType: 'discord_kook_bridge',
    targetId: normalizeText(options.routeId, DISCORD_KOOK_BRIDGE_ROUTE_ID_MAX_LENGTH) || 'all_routes',
    dedupeKey: `discord-kook-bridge:${options.manual ? 'manual' : 'scheduled'}:${normalizeText(options.routeId, DISCORD_KOOK_BRIDGE_ROUTE_ID_MAX_LENGTH) || 'all'}:${Date.now()}`,
    createdBy: options.createdBy || (options.manual ? 'manual' : 'system'),
    metadata: {
      manual: Boolean(options.manual),
      routeId: normalizeText(options.routeId, DISCORD_KOOK_BRIDGE_ROUTE_ID_MAX_LENGTH)
    }
  }).catch(() => null) : null;
  if (operationRun && !options.manual) discordKookBridgeLastTraceAt = Date.now();
  if (options.manual) requireOperationRun(operationRun, 'Discord-KOOK 同步操作记录');
  const finishBridgeOperationRun = async (result = {}, error = null) => {
    const failed = Boolean(error || Number(result.errors || 0) > 0);
    return finishOperationRun(operationRun, {
      status: error ? 'failed' : (result.skipped ? 'skipped' : (failed ? 'failed' : 'succeeded')),
      errorSummary: error
        ? normalizeText(error.message || error, 240)
        : (failed ? normalizeText(result.error || `${result.errors || 0} route(s) failed`, 240) : ''),
      retryable: Boolean(error || failed),
      metadata: {
        manual: Boolean(options.manual),
        routeId: normalizeText(options.routeId, DISCORD_KOOK_BRIDGE_ROUTE_ID_MAX_LENGTH),
        skipped: Boolean(result.skipped),
        reason: result.reason || '',
        routeCount: result.routeCount || 0,
        errors: result.errors || 0,
	        externalActionSucceeded: Boolean(result.externalActionSucceeded),
	        trackingWriteFailed: Boolean(result.trackingWriteFailed),
	        messageRefWriteFailed: Boolean(result.messageRefWriteFailed),
	        messageRefPersisted: Boolean(result.messageRefPersisted),
	        trackingWriteError: normalizeText(result.trackingWriteError, 240),
	        discordToKook: result.discordToKook || {},
	        kookToDiscord: result.kookToDiscord || {}
      }
    });
  };
  const withBridgeOperationRun = (result = {}, run = null) => (
    run ? { ...result, operationRun: publicOperationRun(run) } : result
  );
  if (discordKookBridgeRunning) {
    const result = { skipped: true, reason: 'running' };
    const run = await finishBridgeOperationRun(result);
    return withBridgeOperationRun(result, run);
  }
  discordKookBridgeRunning = true;
  try {
    const snapshot = options.snapshot || await readSettingsRuntimeStore();
    const bridge = discordKookBridgeSettings(snapshot);
    if (!bridge.enabled) {
      const result = { skipped: true, reason: 'disabled' };
      const run = await finishBridgeOperationRun(result);
      return withBridgeOperationRun(result, run);
    }
    const routeId = normalizeText(options.routeId, DISCORD_KOOK_BRIDGE_ROUTE_ID_MAX_LENGTH);
    const candidateRoutes = bridge.routes.filter((route) => (!routeId || route.id === routeId) && route.enabled);
    if (routeId && !bridge.routes.some((route) => route.id === routeId)) {
      throw Object.assign(new Error('Discord-KOOK sync route not found.'), { status: 404 });
    }
    if (!candidateRoutes.length) {
      const result = { skipped: true, reason: routeId ? 'route_disabled' : 'no_enabled_routes' };
      const run = await finishBridgeOperationRun(result);
      return withBridgeOperationRun(result, run);
    }

    const discord = discordSettings(snapshot);
    const kook = kookSettings(snapshot);
    if (!discordBotToken(discord) || !kookBotToken(kook) || !discordKookBridgeTranslationApiKey(snapshot)) {
      throw Object.assign(new Error('Discord-KOOK sync is not fully configured.'), { status: 400 });
    }

    const routes = candidateRoutes.filter(discordKookBridgeRouteIsRunnable);
    if (!routes.length) {
      const result = { skipped: true, reason: 'no_configured_routes' };
      const run = await finishBridgeOperationRun(result);
      return withBridgeOperationRun(result, run);
    }
    snapshot.integrationMessageRefs = await readDiscordKookBridgeRouteMessageRefs(snapshot, routes);
    const result = {
      skipped: false,
      initialized: false,
      routeCount: routes.length,
      errors: 0,
      routes: [],
      discordToKook: { fetched: 0, forwarded: 0, skipped: 0 },
      kookToDiscord: { fetched: 0, forwarded: 0, skipped: 0 }
    };

    for (const route of routes) {
      try {
        const routeResult = await runDiscordKookBridgeRouteSync(
          snapshot,
          { ...route, recentMessageIds: [...(route.recentMessageIds || [])] },
          { forceHeartbeat: traceHeartbeatDue }
        );
        result.initialized = Boolean(routeResult.initialized) || result.initialized;
        result.discordToKook.fetched += routeResult.discordToKook.fetched;
        result.discordToKook.forwarded += routeResult.discordToKook.forwarded;
        result.discordToKook.skipped += routeResult.discordToKook.skipped;
        result.kookToDiscord.fetched += routeResult.kookToDiscord.fetched;
        result.kookToDiscord.forwarded += routeResult.kookToDiscord.forwarded;
        result.kookToDiscord.skipped += routeResult.kookToDiscord.skipped;
        if (routeResult.errors) {
          result.errors += 1;
          result.error ||= routeResult.error || '';
        }
	        if (routeResult.trackingWriteFailed) {
	          result.trackingWriteFailed = true;
	          result.externalActionSucceeded = Boolean(result.externalActionSucceeded || routeResult.externalActionSucceeded);
	          result.messageRefWriteFailed = Boolean(result.messageRefWriteFailed || routeResult.messageRefWriteFailed);
	          result.messageRefPersisted = Boolean(result.messageRefPersisted || routeResult.messageRefPersisted);
	          result.trackingWriteError = result.trackingWriteError || routeResult.trackingWriteError || '';
	        }
        result.routes.push(routeResult);
      } catch (error) {
        const errorMessage = normalizeText(error.message || 'Discord-KOOK route sync failed', 240);
        result.errors += 1;
        result.routes.push({
          routeId: route.id,
          routeName: route.name || '',
          skipped: false,
          error: errorMessage
        });
        await updateDiscordKookBridgeRouteStore(route.id, {
          lastSyncAt: nowIso(),
          lastSyncError: errorMessage
        }).catch(() => {});
      }
    }

    const syncedAt = nowIso();
    const hadActivity = Boolean(
      result.initialized ||
      result.errors ||
      result.discordToKook.fetched ||
      result.discordToKook.forwarded ||
      result.discordToKook.skipped ||
      result.kookToDiscord.fetched ||
      result.kookToDiscord.forwarded ||
      result.kookToDiscord.skipped
    );
    if (options.manual || traceHeartbeatDue || hadActivity) {
      await updateDiscordKookBridgeStore({
        lastSyncAt: syncedAt,
        lastSyncError: result.errors ? `${result.errors}/${routes.length} route(s) failed` : ''
      });
    }
    const finalResult = {
      ...result,
      manual: Boolean(options.manual),
      routeId: routeId || '',
      syncedAt
    };
    const run = await finishBridgeOperationRun(finalResult);
    return withBridgeOperationRun(finalResult, run);
  } catch (error) {
    await updateDiscordKookBridgeStore({
      lastSyncAt: nowIso(),
      lastSyncError: normalizeText(error.message || 'Discord-KOOK sync failed', 240)
    }).catch(() => {});
    await finishBridgeOperationRun({}, error);
    throw error;
  } finally {
    discordKookBridgeRunning = false;
  }
}

async function runDiscordKookBridgeScheduledSync() {
  const now = Date.now();
  if (discordKookBridgeNextAutoSyncAt && now < discordKookBridgeNextAutoSyncAt) {
    return { skipped: true, reason: 'interval' };
  }

  let snapshot = null;
  if (!discordKookBridgeScheduleCacheUpdatedAt || now - discordKookBridgeScheduleCacheUpdatedAt >= DISCORD_KOOK_BRIDGE_SCHEDULE_REFRESH_MS || !discordKookBridgeScheduleCache.enabled) {
    snapshot = await readSettingsRuntimeStore();
    const bridge = discordKookBridgeSettings(snapshot);
    refreshDiscordKookBridgeScheduleCache(bridge, now);
    if (!bridge.enabled) return { skipped: true, reason: 'disabled' };
  }

  const intervalMs = discordKookBridgeScheduleCache.pollIntervalMs;
  if (discordKookBridgeLastAutoSyncAt && now - discordKookBridgeLastAutoSyncAt < intervalMs) {
    discordKookBridgeNextAutoSyncAt = discordKookBridgeLastAutoSyncAt + intervalMs;
    return { skipped: true, reason: 'interval' };
  }
  discordKookBridgeLastAutoSyncAt = now;
  discordKookBridgeNextAutoSyncAt = now + intervalMs;
  return runDiscordKookBridgeSync({ silent: true, snapshot });
}

function rustplusRelayDiscordTargetOptions(store) {
  return discordTargets(discordSettings(store)).map(publicDiscordTargetPayload);
}

function rustplusRelayMemberOnlineSummaryFromServerOnline(member = {}, serverOnline = {}) {
  const onlineTimeMinutes = Number(serverOnline.onlineTimeMinutes || 0);
  return {
    ...(member.onlineSummary && typeof member.onlineSummary === 'object' ? member.onlineSummary : {}),
    wipeId: serverOnline.wipeId || '',
    wipeName: serverOnline.wipeName || '',
    wipeStatus: serverOnline.wipeStatus || '',
    serverName: serverOnline.serverName || '',
    battlemetricsServerId: serverOnline.battlemetricsServerId || '',
    lastOnlineAt: serverOnline.lastOnlineAt || '',
    lastOfflineAt: serverOnline.lastOfflineAt || '',
    onlineTimeSeconds: Number(serverOnline.onlineTimeSeconds || 0),
    onlineTimeMinutes: Number.isFinite(onlineTimeMinutes) ? onlineTimeMinutes : 0,
    serverPlayTimeSeconds: Number(serverOnline.onlineTimeSeconds || 0),
    serverPlayTimeMinutes: Number.isFinite(onlineTimeMinutes) ? onlineTimeMinutes : 0,
    weeklyPlayTimeSeconds: Number(serverOnline.weeklyPlayTimeSeconds || 0),
    weeklyPlayTimeMinutes: Number(serverOnline.weeklyPlayTimeMinutes || 0),
    syncedAt: serverOnline.syncedAt || '',
    error: serverOnline.error || ''
  };
}

function isRustplusRelayBattlemetricsFallbackSummary(summary = {}) {
  const confidence = normalizeText(summary.matchConfidence || summary.battlemetricsMatchConfidence || '', 80).toLowerCase();
  const notes = normalizeText(summary.matchNotes || summary.battlemetricsMatchNotes || '', 240).toLowerCase();
  if (confidence !== 'rustplus_relay_bmid' && !notes.includes('rust+ relay online fallback')) return false;
  return !battlemetricsSummaryHasDirectSessionEvidence(summary);
}

function battlemetricsSummaryHasDirectSessionEvidence(summary = {}) {
  const playerId = normalizeText(summary.battlemetricsPlayerId || '', 80);
  const serverId = normalizeText(summary.battlemetricsServerId || '', 80);
  const fetchedPages = Number(summary.sessionFetchedPages ?? summary.battlemetricsSessionFetchedPages ?? 0);
  const rangeStopAt = normalizeText(summary.rangeStopAt || summary.battlemetricsRangeStopAt, 80);
  return Boolean(playerId && serverId && (fetchedPages > 0 || rangeStopAt));
}

function canUseBattlemetricsOnlineForWipe(wipe, nowMs = Date.now()) {
  if (!wipe) return false;
  return wipe.status === 'closed' || isWipeStartedServer(wipe, nowMs);
}

function battlemetricsOnlineSummaryTimestampMs(summary = {}) {
  const candidates = [
    summary.rangeStopAt,
    summary.battlemetricsRangeStopAt,
    summary.syncedAt,
    summary.battlemetricsSyncedAt,
    summary.lastOnlineAt,
    summary.battlemetricsLastOnlineAt,
    summary.lastOfflineAt,
    summary.battlemetricsLastOfflineAt,
    summary.matchLastSeenAt,
    summary.battlemetricsMatchLastSeenAt
  ];
  for (const value of candidates) {
    const time = timestampForSort(value);
    if (time) return time;
  }
  return 0;
}

export function battlemetricsOnlineSummaryTrustedForWipe(summary = {}, wipe = null, nowMs = Date.now()) {
  if (!summary || typeof summary !== 'object') return false;
  if (isRustplusRelayBattlemetricsFallbackSummary(summary)) return false;
  if (normalizeText(summary.error || summary.battlemetricsError, 240)) return false;
  if (!wipe) return true;
  if (!canUseBattlemetricsOnlineForWipe(wipe, nowMs)) return false;

  const summaryWipeId = normalizeText(summary.wipeId || summary.battlemetricsWipeId, 120);
  const wipeId = normalizeText(wipe.id, 120);
  if (summaryWipeId && wipeId && summaryWipeId !== wipeId) return false;

  const summaryServerId = normalizeText(summary.battlemetricsServerId, 80);
  const wipeServerId = battlemetricsServerIdForWipe(wipe);
  if (summaryServerId && wipeServerId && summaryServerId !== wipeServerId) return false;
  if (!summaryWipeId && wipeId && !summaryServerId) return false;

  const startedAtMs = wipeStartTimeMs(wipe);
  if (startedAtMs && effectiveWipeStatus(wipe, nowMs) !== 'closed') {
    const summaryTimeMs = battlemetricsOnlineSummaryTimestampMs(summary);
    if (!summaryTimeMs || summaryTimeMs < startedAtMs) return false;
  }

  return true;
}

function kdaRowTimestampMs(row = {}) {
  return timestampForSort(row?.syncedAt || row?.capturedAt || row?.updatedAt || row?.createdAt);
}

function kdaRowTimeTrustedForWipe(row = {}, wipe = null, nowMs = Date.now()) {
  if (!row || !wipe) return false;
  const rowWipeId = normalizeText(row.wipeId, 120);
  const wipeId = normalizeText(wipe.id, 120);
  if (rowWipeId && wipeId && rowWipeId !== wipeId) return false;
  if (!canUseBattlemetricsOnlineForWipe(wipe, nowMs)) return false;
  const startedAtMs = wipeStartTimeMs(wipe);
  if (startedAtMs && effectiveWipeStatus(wipe, nowMs) !== 'closed') {
    const rowTimeMs = kdaRowTimestampMs(row);
    if (!rowTimeMs || rowTimeMs < startedAtMs) return false;
  }
  return true;
}

function kdaRowOnlineSummaryTrustedForWipe(row = {}, wipe = null, nowMs = Date.now()) {
  const summary = row?.onlineSummary || null;
  if (battlemetricsOnlineSummaryTrustedForWipe(summary, wipe, nowMs)) return true;
  if (!summary || typeof summary !== 'object') return false;
  if (isRustplusRelayBattlemetricsFallbackSummary(summary)) return false;
  const hasExplicitScope = Boolean(summary.wipeId || summary.battlemetricsWipeId || summary.battlemetricsServerId);
  if (hasExplicitScope || battlemetricsOnlineSummaryTimestampMs(summary)) return false;
  return kdaRowTimeTrustedForWipe(row, wipe, nowMs) && onlineMinutesFromSummary(summary) > 0;
}

function kdaRowScopedOnlineMinutes(row = {}, wipe = null) {
  const rowMinutes = Number(row?.onlineTimeMinutes || 0);
  if (!Number.isFinite(rowMinutes) || rowMinutes <= 0 || row?.onlineSummary) return 0;
  const rowWipeId = normalizeText(row?.wipeId, 120);
  const wipeId = normalizeText(wipe?.id, 120);
  return rowWipeId && wipeId && rowWipeId === wipeId ? rowMinutes : 0;
}

function kdaRowOnlineMinutesForWipe(row = {}, onlineSummary = {}, wipe = null) {
  const rowMinutes = Number(row?.onlineTimeMinutes || 0);
  const rowSummaryTrusted = kdaRowOnlineSummaryTrustedForWipe(row, wipe);
  if (!battlemetricsOnlineSummaryTrustedForWipe(onlineSummary, wipe) && !rowSummaryTrusted) {
    const scopedRowMinutes = kdaRowScopedOnlineMinutes(row, wipe);
    if (scopedRowMinutes) return scopedRowMinutes;
    if (!row?.onlineSummary && kdaRowTimeTrustedForWipe(row, wipe) && Number.isFinite(rowMinutes) && rowMinutes > 0) return rowMinutes;
    if (wipe?.status === 'closed' && !row?.onlineSummary && Number.isFinite(rowMinutes) && rowMinutes > 0) return rowMinutes;
    return 0;
  }
  if (rowSummaryTrusted && Number.isFinite(rowMinutes) && rowMinutes > 0) return rowMinutes;
  const summaryMinutes = onlineMinutesFromSummary(onlineSummary);
  return summaryMinutes || kdaRowScopedOnlineMinutes(row, wipe);
}

function rustplusRelayServerOnlineHasDisplayValue(serverOnline = {}) {
  return Boolean(
    serverOnline?.lastOnlineAt ||
      serverOnline?.lastOfflineAt ||
      Number(serverOnline?.onlineTimeMinutes || 0) > 0 ||
      Number(serverOnline?.onlineTimeSeconds || 0) > 0
  );
}

function rustplusRelayMemberServerNames(member = {}) {
  return [
    member.serverName,
    ...(Array.isArray(member.serverNames) ? member.serverNames : [])
  ].map((value) => normalizeText(value, 180)).filter(Boolean);
}

function rustplusRelayServerNameTokens(value = '') {
  return new Set(
    expandVitalRustName(value)
      .toLowerCase()
      .match(/[a-z0-9]+/g) || []
  );
}

function rustplusRelayServerNameMatchesBattlemetrics(candidateName = '', vitalName = '') {
  const candidateTokens = rustplusRelayServerNameTokens(candidateName);
  const vitalTokens = [...rustplusRelayServerNameTokens(vitalName)];
  return vitalTokens.length > 0 && vitalTokens.every((token) => candidateTokens.has(token));
}

function rustplusRelayServerNamesEquivalent(leftName = '', rightName = '') {
  const leftTokens = [...rustplusRelayServerNameTokens(leftName)];
  const rightTokens = [...rustplusRelayServerNameTokens(rightName)];
  if (!leftTokens.length || !rightTokens.length) return false;
  if (leftTokens.length === 1 || rightTokens.length === 1) {
    return leftTokens.length === rightTokens.length && leftTokens[0] === rightTokens[0];
  }
  const rightSet = new Set(rightTokens);
  const commonCount = leftTokens.filter((token) => rightSet.has(token)).length;
  return commonCount >= 2 && (commonCount === leftTokens.length || commonCount === rightTokens.length);
}

function rustplusRelayServerNameMatchesAny(names = [], expectedNames = []) {
  const normalizedNames = names.map((value) => normalizeText(value, 180)).filter(Boolean);
  const normalizedExpectedNames = expectedNames.map((value) => normalizeText(value, 180)).filter(Boolean);
  if (!normalizedNames.length || !normalizedExpectedNames.length) return false;
  return normalizedNames.some((name) => normalizedExpectedNames.some((expectedName) => (
    rustplusRelayServerNamesEquivalent(name, expectedName) ||
      rustplusRelayServerNameMatchesBattlemetrics(name, expectedName) ||
      rustplusRelayServerNameMatchesBattlemetrics(expectedName, name)
  )));
}

function rustplusRelayServerOnlineMatchesTarget(serverOnline = {}, target = {}, relayMember = {}) {
  const targetWipe = target?.wipe || null;
  if (!targetWipe || !serverOnline?.wipeId || serverOnline.wipeId !== targetWipe.id) return false;
  const targetServerId = normalizeText(target.serverId || battlemetricsServerIdForWipe(targetWipe), 80);
  const serverOnlineServerId = normalizeText(serverOnline.battlemetricsServerId, 80);
  if (!targetServerId || !serverOnlineServerId || targetServerId !== serverOnlineServerId) return false;
  return rustplusRelayServerNameMatchesAny(
    rustplusRelayMemberServerNames(relayMember),
    [serverOnline.serverName, target.serverName, targetWipe.serverName, targetWipe.name]
  );
}

function rustplusRelayBattlemetricsTargetForMember(store, relayMember = {}) {
  const relayServerNames = rustplusRelayMemberServerNames(relayMember);
  const vitalServer = VITAL_RUST_2X_SERVERS.find((server) => (
    relayServerNames.some((name) => rustplusRelayServerNameMatchesBattlemetrics(name, server.name))
  )) || null;
  const active = currentWipe(store);
  if (!vitalServer && active && battlemetricsServerIdForWipe(active)) {
    const activeNames = [active.serverName, active.name].map((value) => normalizeText(value, 180)).filter(Boolean);
    if (relayServerNames.some((relayName) => activeNames.some((activeName) => rustplusRelayServerNamesEquivalent(relayName, activeName)))) {
      return {
        serverId: battlemetricsServerIdForWipe(active),
        serverName: expandVitalRustName(active.serverName || active.name || relayServerNames[0] || ''),
        wipe: active
      };
    }
  }
  const serverId = vitalServer?.battlemetricsId || '';
  if (!serverId) return { serverId: '', serverName: relayServerNames[0] || '', wipe: null };
  if (active && battlemetricsServerIdForWipe(active) === serverId) {
    return { serverId, serverName: expandVitalRustName(vitalServer.name), wipe: active };
  }
  const matchingWipes = (store.wipes || [])
    .filter((wipe) => battlemetricsServerIdForWipe(wipe) === serverId)
    .toSorted((left, right) => {
      if (left.status !== right.status) {
        if (left.status !== 'closed') return -1;
        if (right.status !== 'closed') return 1;
      }
      const rightTime = timestampForSort(right.startedAt || right.updatedAt || right.closedAt || right.createdAt);
      const leftTime = timestampForSort(left.startedAt || left.updatedAt || left.closedAt || left.createdAt);
      return rightTime - leftTime;
    });
  return {
    serverId,
    serverName: expandVitalRustName(vitalServer.name),
    wipe: matchingWipes[0] || null
  };
}

function rustplusRelayBattlemetricsServerOnlinePayload(store, systemMember, target = {}, indexes = getStoreIndexes(store)) {
  if (!target?.serverId) return null;
  if (target.wipe) return memberServerOnlinePayload(store, systemMember, target.wipe, indexes);
  const summary = memberOnlineSummary(store, systemMember, indexes);
  if (isRustplusRelayBattlemetricsFallbackSummary(summary)) return null;
  const summaryServerId = normalizeText(summary.battlemetricsServerId, 80);
  if (!summaryServerId || summaryServerId !== target.serverId) return null;
  const onlineTimeSeconds = Number(summary.serverPlayTimeSeconds || summary.weeklyPlayTimeSeconds || 0);
  return {
    wipeId: '',
    wipeName: '',
    wipeStatus: '',
    serverName: target.serverName || summary.serverName || '',
    startedAt: '',
    battlemetricsServerId: target.serverId,
    lastOnlineAt: summary.lastOnlineAt || '',
    lastOfflineAt: summary.lastOfflineAt || '',
    onlineTimeSeconds,
    onlineTimeMinutes: Math.round(onlineTimeSeconds / 60),
    weeklyPlayTimeSeconds: Number(summary.weeklyPlayTimeSeconds || 0),
    weeklyPlayTimeMinutes: Number(summary.weeklyPlayTimeMinutes || 0),
    syncedAt: summary.syncedAt || '',
    error: summary.error || ''
  };
}

function queueRustplusRelayBattlemetricsOnlineFallback(store, systemMember, relayMember = {}, target = {}, serverOnline = {}) {
  // Rust+ relay is only a live relay source; member profile and KDA online time must come from direct BM sync.
}

function enrichRustplusRelayStateWithMemberOnline(store, state = {}) {
  const indexes = getStoreIndexes(store);
  const membersBySteamId = new Map((store.members || []).map((member) => [member.steamId, member]));
  const enrichRelayMember = (member = {}) => {
    const steamId = normalizeText(member.steamId, 32);
    const systemMember = steamId ? membersBySteamId.get(steamId) : null;
    if (!systemMember) return member;
    const target = rustplusRelayBattlemetricsTargetForMember(store, member);
    const serverOnline = rustplusRelayBattlemetricsServerOnlinePayload(store, systemMember, target, indexes);
    if (!serverOnline || !rustplusRelayServerOnlineMatchesTarget(serverOnline, target, member)) return member;
    const webLastOnlineAt = serverOnline.lastOnlineAt || '';
    const webLastOfflineAt = serverOnline.lastOfflineAt || '';
    const webOnlineTimeMinutes = Number(serverOnline.onlineTimeMinutes || 0);
    const relayOnlineTimeMinutes = Number(member.onlineTimeMinutes || 0);
    const hasServerOnlineValue = rustplusRelayServerOnlineHasDisplayValue(serverOnline);
    return {
      ...member,
      lastOnlineAt: webLastOnlineAt || member.lastOnlineAt || '',
      lastOnlineAtSource: webLastOnlineAt ? 'battlemetrics' : member.lastOnlineAtSource,
      lastOfflineAt: webLastOfflineAt || member.lastOfflineAt || '',
      ...(hasServerOnlineValue ? {
        serverOnline,
        onlineSummary: rustplusRelayMemberOnlineSummaryFromServerOnline(member, serverOnline)
      } : {}),
      onlineTimeMinutes: Number.isFinite(webOnlineTimeMinutes) && webOnlineTimeMinutes > 0
        ? webOnlineTimeMinutes
        : (Number.isFinite(relayOnlineTimeMinutes) ? relayOnlineTimeMinutes : 0)
    };
  };
  const members = Array.isArray(state.members) ? state.members.map(enrichRelayMember) : [];
  const server = state.server && Array.isArray(state.server.members)
    ? { ...state.server, members: state.server.members.map(enrichRelayMember) }
    : state.server;
  return {
    ...state,
    server,
    members
  };
}

function scopedRustplusRelayState(state = {}, scope = 'all') {
  if (scope === 'info') {
    return {
      ...state,
      discordTargets: [],
      settings: state.settings ? {
        ...state.settings,
        discordForwarding: {
          enabled: false,
          routes: [],
          updatedAt: '',
          lastForwardedAt: '',
          lastForwardError: '',
          lastForwardMessageId: ''
        }
      } : state.settings,
      chatMessages: [],
      chatPage: {
        offset: 0,
        limit: 0,
        count: 0,
        total: 0,
        hasMore: false,
        nextOffset: 0
      },
      summary: {
        ...(state.summary || {}),
        chatCount: 0
      }
    };
  }
  if (scope === 'chat') {
    return {
      ...state,
      discordTargets: [],
      server: state.server ? { ...state.server, members: [], invites: [], inviteRecords: [] } : null,
      members: [],
      invites: [],
      inviteRecords: [],
      clan: state.clan ? { ...state.clan, memberLimit: 0, announcement: '' } : state.clan,
      summary: {
        ...(state.summary || {}),
        memberCount: 0,
        onlineCount: 0,
        offlineCount: 0,
        inviteCount: 0,
        inviteRecordCount: 0
      }
    };
  }
  return state;
}

function publicRustplusRelayApiState(store, filters = {}, options = {}) {
  const scope = options.scope || 'all';
  const state = {
    ...publicRustplusRelayState(store, filters),
    discordTargets: rustplusRelayDiscordTargetOptions(store)
  };
  const enriched = enrichRustplusRelayStateWithMemberOnline(store, state);
  queueRustplusRelaySteamProfileBackfill(enriched);
  return scopedRustplusRelayState(enriched, scope);
}

function publicRustplusRelayApiPart(state = {}, part = 'summary') {
  const serverSummary = state.server ? {
    ...state.server,
    members: undefined,
    invites: undefined,
    inviteRecords: undefined
  } : null;
  const base = {
    settings: state.settings,
    clients: state.clients || [],
    servers: state.servers || [],
    selected: state.selected || {},
    server: serverSummary,
    clan: state.clan || null,
    summary: state.summary || {}
  };
  if (part === 'members') {
    return {
      ...base,
      members: state.members || []
    };
  }
  if (part === 'chats') {
    return {
      selected: state.selected || {},
      server: serverSummary,
      chatMessages: state.chatMessages || [],
      chatPage: state.chatPage || {},
      summary: state.summary || {}
    };
  }
  if (part === 'invites') {
    return {
      ...base,
      invites: state.invites || [],
      inviteRecords: state.inviteRecords || [],
      inviteRecordsIncluded: Boolean(state.inviteRecordsIncluded)
    };
  }
  return {
    ...base,
    discordTargets: state.discordTargets || []
  };
}

function rustplusRelayScopeAccess(store, user, requestedScope = '') {
  const requested = normalizeText(requestedScope, 20);
  const canViewInfo = canViewModuleInStore(store, user, 'rustClanInfo') || canViewModuleInStore(store, user, 'rustTools');
  const canViewChat = canViewModuleInStore(store, user, 'rustClanChat') || canViewModuleInStore(store, user, 'rustTools');
  if (requested === 'info') return canViewInfo ? 'info' : '';
  if (requested === 'chat') return canViewChat ? 'chat' : '';
  if (requested === 'all') return canViewInfo && canViewChat ? 'all' : '';
  if (canViewInfo && canViewChat) return 'all';
  if (canViewInfo) return 'info';
  if (canViewChat) return 'chat';
  return '';
}

function rustplusRelayDiscordForwardingRoutes(config = {}, event = {}) {
  if (!config.enabled) return [];
  const routes = Array.isArray(config.routes) && config.routes.length ? config.routes : [config];
  return routes.filter((route) => {
    if (!route || route.enabled === false) return false;
    if (route.clientId && route.clientId !== event.clientId) return false;
    if (route.serverKey && route.serverKey !== event.serverKey) return false;
    if (route.platform === 'kook') {
      return Boolean(route.serverKey || route.kookChannelId || route.kookAccessToken || route.kookTemplateId);
    }
    return Boolean(route.serverKey || route.channelId || route.targetId);
  });
}

function normalizedDiscordMentionKey(value = '') {
  return normalizeText(value, 120)
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[’'`"]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function compactDiscordMentionKey(value = '') {
  return normalizedDiscordMentionKey(value).replace(/[^\p{L}\p{N}]+/gu, '');
}

function discordMentionKeysForName(value = '') {
  const normalized = normalizedDiscordMentionKey(value);
  if (!normalized || normalized === 'everyone' || normalized === 'here') return [];
  const keys = new Set([normalized]);
  const compact = compactDiscordMentionKey(normalized);
  if (compact && compact !== normalized) keys.add(compact);
  for (const part of normalized.split(/\s*-\s*/)) {
    const key = normalizedDiscordMentionKey(part);
    if (key && key !== 'everyone' && key !== 'here') {
      keys.add(key);
      const compactKey = compactDiscordMentionKey(key);
      if (compactKey && compactKey !== key) keys.add(compactKey);
    }
  }
  return [...keys];
}

function validDiscordUserId(value = '') {
  const id = normalizeText(value, DISCORD_ID_MAX_LENGTH);
  return /^\d{17,20}$/.test(id) ? id : '';
}

function rustplusRelayDiscordMentionLookup(store = {}) {
  const byKey = new Map();
  for (const member of store.members || []) {
    const discordId = validDiscordUserId(member.discordId);
    if (!discordId) continue;
    const names = [
      member.discordName,
      member.customName,
      member.steamNickname,
      member.displayName,
      member.steamId
    ];
    for (const name of names) {
      for (const key of discordMentionKeysForName(name)) {
        if (!byKey.has(key)) byKey.set(key, new Set());
        byKey.get(key).add(discordId);
      }
    }
  }
  return byKey;
}

function uniqueDiscordMentionId(ids = new Set()) {
  return ids.size === 1 ? [...ids][0] : '';
}

function discordMentionIdForCandidate(candidate = '', lookup = new Map()) {
  const exact = lookup.get(normalizedDiscordMentionKey(candidate));
  const exactId = exact ? uniqueDiscordMentionId(exact) : '';
  if (exactId) return exactId;
  const ids = new Set();
  for (const key of discordMentionKeysForName(candidate)) {
    for (const id of lookup.get(key) || []) ids.add(id);
  }
  return uniqueDiscordMentionId(ids);
}

function discordMentionCandidatePrefixes(value = '') {
  const raw = normalizeText(value, 120).trimEnd();
  if (!raw) return [];
  const prefixes = new Set([raw]);
  const words = raw.split(/\s+/).filter(Boolean);
  for (let count = Math.min(words.length, 5); count >= 1; count -= 1) {
    prefixes.add(words.slice(0, count).join(' '));
  }
  return [...prefixes].sort((left, right) => right.length - left.length);
}

function discordMentionMatchForRawCandidate(rawCandidate = '', lookup = new Map()) {
  for (const candidate of discordMentionCandidatePrefixes(rawCandidate)) {
    const normalizedName = normalizedDiscordMentionKey(candidate);
    if (!normalizedName || normalizedName === 'everyone' || normalizedName === 'here') continue;
    const discordId = discordMentionIdForCandidate(candidate, lookup);
    if (discordId) return { discordId, matchedText: candidate };
  }
  return null;
}

function rustplusRelayChatSenderCanMentionEveryone(store = {}, message = {}) {
  const steamId = normalizeText(message.steamId, 80);
  if (!steamId) return false;
  return (store.users || [])
    .filter((user) => normalizeText(user.boundSteamId, 80) === steamId)
    .some((user) => (
      userCan(user, store.permissionRoles || [], 'rustClanChat', 'edit') ||
        userCan(user, store.permissionRoles || [], 'rustTools', 'edit') ||
        userCan(user, store.permissionRoles || [], 'discordBot', 'edit')
    ));
}

function applyRustplusRelayDiscordPersonMentions(text = '', lookup = new Map()) {
  const mentionedUserIds = new Set();
  const content = normalizeText(text, 2000).replace(/@(?!everyone\b|here\b)([^\n@<>/，,。！？!?；;:：()[\]{}]{1,120})/giu, (match, rawCandidate) => {
    const resolved = discordMentionMatchForRawCandidate(rawCandidate, lookup);
    if (!resolved) return match;
    const rest = rawCandidate.slice(resolved.matchedText.length);
    const discordId = resolved.discordId;
    mentionedUserIds.add(discordId);
    return `<@${discordId}>${rest}`;
  });
  return { content, mentionedUserIds };
}

function applyRustplusRelayDiscordEveryoneMentions(text = '', canMentionEveryone = false) {
  let hasAllowedEveryoneMention = false;
  const content = normalizeText(text, 2000).replace(/(^|[^\p{L}\p{N}_])@(everyone|here)\b/giu, (match, prefix, mentionType) => {
    if (canMentionEveryone) {
      hasAllowedEveryoneMention = true;
      return `${prefix}@${mentionType.toLowerCase()}`;
    }
    return `${prefix}\uff20${mentionType.toLowerCase()}`;
  });
  return { content, hasAllowedEveryoneMention };
}

function rustplusRelayDiscordAllowedMentions(userIds = new Set(), allowEveryone = false) {
  const allowed = {
    parse: allowEveryone ? ['everyone'] : []
  };
  const users = [...userIds].slice(0, 100);
  if (users.length) allowed.users = users;
  return allowed;
}

function rustplusRelayDiscordMentionMessage(store = {}, message = {}) {
  const sourceField = message.translatedMessage ? 'translatedMessage' : 'message';
  const sourceText = message[sourceField] || '';
  const personResult = applyRustplusRelayDiscordPersonMentions(sourceText, rustplusRelayDiscordMentionLookup(store));
  const everyoneResult = applyRustplusRelayDiscordEveryoneMentions(
    personResult.content,
    rustplusRelayChatSenderCanMentionEveryone(store, message)
  );
  return {
    message: {
      ...message,
      [sourceField]: everyoneResult.content
    },
    allowedMentions: rustplusRelayDiscordAllowedMentions(personResult.mentionedUserIds, everyoneResult.hasAllowedEveryoneMention)
  };
}

function rustplusRelayChatForwardRouteKey(route = {}, event = {}, channelId = '') {
  return normalizeText(
    route.id ||
      route.routeId ||
      route.targetId ||
      route.serverKey ||
      event.serverKey ||
      channelId,
    160
  );
}

function rustplusRelayChatForwardTargetName(route = {}, settings = {}) {
  return normalizeText(route.targetName || route.name || settings.targetName, 120);
}

function rustplusRelayChatForwardRunMetadata(route = {}, event = {}, chatMessage = {}, options = {}) {
  return {
    platform: normalizeText(options.platform || route.platform || 'discord', 40),
    routeId: rustplusRelayChatForwardRouteKey(route, event, options.channelId),
    targetId: normalizeText(options.targetId || route.targetId || '', 120),
    targetName: rustplusRelayChatForwardTargetName(route, options.settings || {}),
    channelId: normalizeText(options.channelId, 120),
    clientId: normalizeText(route.clientId || event.clientId, 120),
    serverKey: normalizeText(route.serverKey || event.serverKey, 160),
    serverId: normalizeText(event.serverId || chatMessage.serverId, 120),
    serverName: normalizeText(event.serverName || chatMessage.serverName, 120),
    chatMessageId: normalizeText(event.chatMessageId || chatMessage.id, 160),
    steamId: normalizeText(chatMessage.steamId || event.steamId, 80),
    displayName: normalizeText(chatMessage.displayName || event.displayName, 120),
    messageLength: normalizeText(chatMessage.message || '', 2000).length,
    translatedMessageLength: normalizeText(chatMessage.translatedMessage || '', 2000).length,
    ...(options.extra && typeof options.extra === 'object' ? options.extra : {})
  };
}

function rustplusRelayChatForwardRunInput(route = {}, event = {}, chatMessage = {}, channelId = '', options = {}) {
  const platform = options.platform || route.platform || 'discord';
  const chatMessageId = normalizeText(event.chatMessageId || chatMessage.id, 160);
  const routeKey = rustplusRelayChatForwardRouteKey(route, event, channelId);
  return {
    type: 'rustplus_relay_chat_forward',
    platform,
    source: 'auto',
    status: 'running',
    targetType: RUSTPLUS_RELAY_CHAT_FORWARD_MESSAGE_REF_TARGET_TYPE,
    targetId: chatMessageId,
    channelId,
    dedupeKey: `rustplus:relay-chat-forward:${platform}:${routeKey}:${chatMessageId}`,
    createdBy: 'system',
    metadata: rustplusRelayChatForwardRunMetadata(route, event, chatMessage, {
      ...options,
      platform,
      channelId
    })
  };
}

function rustplusRelayChatForwardMessageId(platform = '', result = {}) {
  if (platform === 'kook') return kookMessageRefIdFromResult(result);
  return normalizeText(
    result?.id ||
      result?.messageId ||
      result?.message?.id ||
      result?.message?.messageId,
    120
  );
}

function rustplusRelayChatForwardMessageRef(platform = '', route = {}, event = {}, chatMessage = {}, channelId = '', result = {}, options = {}) {
  const messageId = rustplusRelayChatForwardMessageId(platform, result);
  if (!messageId) return null;
  const targetId = normalizeText(event.chatMessageId || chatMessage.id, 160);
  const targetName = rustplusRelayChatForwardTargetName(route, options.settings || {});
  return platformCardMessageRefRecord(
    platform,
    RUSTPLUS_RELAY_CHAT_FORWARD_MESSAGE_REF_KIND,
    RUSTPLUS_RELAY_CHAT_FORWARD_MESSAGE_REF_TARGET_TYPE,
    targetId,
    channelId,
    messageId,
    'active',
    {
      source: 'rustplus_relay_chat_forward',
      action: 'forward',
      targetId: normalizeText(options.targetId || route.targetId || channelId, 120),
      targetName,
      metadata: rustplusRelayChatForwardRunMetadata(route, event, chatMessage, {
        platform,
        channelId,
        settings: options.settings || {},
        targetId: options.targetId || route.targetId || '',
        extra: {
          operationRunId: normalizeText(options.operationRunId, 120)
        }
      })
    }
  );
}

async function recordRustplusRelayChatForwardSuccess(req, context = {}) {
  const {
    operationRun,
    platform = '',
    route = {},
    settings = {},
    event = {},
    chatMessage = {},
    channelId = '',
    result = {}
  } = context;
  const messageId = rustplusRelayChatForwardMessageId(platform, result);
  const resultChannelId = normalizeText(result?.channel_id || result?.channelId || channelId, 120);
  const ref = rustplusRelayChatForwardMessageRef(platform, route, event, chatMessage, resultChannelId || channelId, result, {
    settings,
    targetId: settings.targetId || route.targetId || '',
    operationRunId: operationRun?.id || ''
  });
  let messageRefPersisted = false;
  let trackingWriteError = null;
  if (ref) {
    try {
      messageRefPersisted = await persistIntegrationMessageRefs([ref], 'rustplus_relay_chat_forward_message_ref') > 0;
    } catch (error) {
      trackingWriteError = error;
    }
  }
  const baseMetadata = rustplusRelayChatForwardRunMetadata(route, event, chatMessage, {
    platform,
    channelId: resultChannelId || channelId,
    settings,
    targetId: settings.targetId || route.targetId || '',
    extra: {
      externalActionSucceeded: true,
      messageRefPersisted,
      messageRefSkippedReason: ref ? '' : 'missing_message_id'
    }
  });
  if (trackingWriteError) {
    await finishOperationRun(operationRun, {
      status: 'failed',
      messageId,
      channelId: resultChannelId || channelId,
      errorKey: 'message_ref_write_failed',
      errorSummary: normalizeText(trackingWriteError.message || trackingWriteError, 500),
      retryable: true,
      metadata: {
        ...baseMetadata,
        trackingWriteFailed: true,
        trackingWriteError: normalizeText(trackingWriteError.message || trackingWriteError, 240),
        messageRefWriteFailed: true
      }
    });
    await appendLogDirect(
      req,
      platform === 'kook' ? 'rustplus_relay_chat_kook_tracking_failed' : 'rustplus_relay_chat_discord_tracking_failed',
      trackingWriteError.message || 'Rust+ clan chat third-party tracking write failed',
      {
        metadata: {
          platform,
          channelId: resultChannelId || channelId,
          routeId: rustplusRelayChatForwardRouteKey(route, event, channelId),
          chatMessageId: event.chatMessageId || '',
          operationRunId: operationRun?.id || '',
          externalActionSucceeded: true,
          trackingWriteFailed: true
        }
      }
    ).catch(() => {});
    return { ok: false, messageId, messageRefPersisted: false, trackingWriteFailed: true };
  }
  await finishOperationRun(operationRun, {
    status: 'succeeded',
    messageId,
    channelId: resultChannelId || channelId,
    metadata: baseMetadata
  });
  return { ok: true, messageId, messageRefPersisted };
}

export async function forwardRustplusRelayChatToThirdParty(req, relayPayload = {}) {
  const event = relayPayload.event || {};
  if (event.type !== 'clan_chat_message' || !event.inserted || !event.chatMessageId) return;
  const snapshot = await readRustplusRelayRuntimeStore();
  const relaySettings = rustplusRelaySettings(snapshot);
  const forwarding = relaySettings.discordForwarding || {};
  const routes = rustplusRelayDiscordForwardingRoutes(forwarding, event);
  if (!routes.length) return;
  const relayStore = snapshot.rustplusRelay || {};
  const payloadChatMessage = relayPayload.chatMessage && relayPayload.chatMessage.id === event.chatMessageId
    ? relayPayload.chatMessage
    : null;
  const chatMessage = (relayStore.chatMessages || []).find((message) => message.id === event.chatMessageId) || payloadChatMessage;
  if (!chatMessage) return;
  for (const route of routes) {
    const isKookRoute = route.platform === 'kook';
    const settings = isKookRoute ? null : discordSettingsForTarget(discordSettings(snapshot), route.targetId);
    const channelId = isKookRoute
      ? normalizeText(route.kookChannelId || route.channelId, KOOK_ID_MAX_LENGTH)
      : normalizeText(route.channelId || settings.channelId, DISCORD_ID_MAX_LENGTH);
    const platform = isKookRoute ? 'kook' : 'discord';
    let operationRun = null;
    try {
      operationRun = requireOperationRun(await createOperationRun(rustplusRelayChatForwardRunInput(
        route,
        event,
        chatMessage,
        channelId,
        {
          platform,
          settings: settings || {},
          targetId: settings?.targetId || route.targetId || ''
        }
      )).catch(() => null), 'Rust+ 聊天转发操作记录');
      if (isKookRoute) {
        if (!route.kookAccessToken || !channelId) {
          throw Object.assign(new Error('KOOK Access Token or Channel ID is not configured.'), { status: 400 });
        }
        const relayState = publicRustplusRelayState(snapshot, {
          clientId: route.clientId || event.clientId,
          serverKey: route.serverKey || event.serverKey,
          chatLimit: 1
        });
        const kookResult = await sendKookPipeMessage(route, buildRustplusRelayChatKookPipeBody(route, chatMessage, relayState));
        await recordRustplusRelayChatForwardSuccess(req, {
          operationRun,
          platform,
          route,
          event,
          chatMessage,
          channelId,
          result: kookResult
        });
        continue;
      }
      if (!discordBotToken(settings) || !channelId) {
        throw Object.assign(new Error('Discord Bot Token or Channel ID is not configured.'), { status: 400 });
      }
      const relayState = publicRustplusRelayState(snapshot, {
        clientId: route.clientId || event.clientId,
        serverKey: route.serverKey || event.serverKey,
        chatLimit: 1
      });
      const mentionMessage = rustplusRelayDiscordMentionMessage(snapshot, chatMessage);
      const discordPayload = buildRustplusRelayChatDiscordMessage(mentionMessage.message, relayState);
      discordPayload.allowed_mentions = mentionMessage.allowedMentions;
      const discordMessage = await sendDiscordChannelMessage(settings, discordPayload, channelId);
      await recordRustplusRelayChatForwardSuccess(req, {
        operationRun,
        platform,
        route,
        settings,
        event,
        chatMessage,
        channelId,
        result: discordMessage
      });
    } catch (error) {
      await finishOperationRun(operationRun, {
        status: 'failed',
        errorSummary: error.message || 'Rust+ clan chat third-party forward failed',
        retryable: true,
        metadata: rustplusRelayChatForwardRunMetadata(route, event, chatMessage, {
          platform,
          channelId,
          settings: settings || {},
          targetId: settings?.targetId || route.targetId || '',
          extra: {
            externalActionSucceeded: false
          }
        })
      });
      await markRustplusRelayDiscordForward({}, error, route.id || route.serverKey).catch(() => {});
      await appendLogDirect(
        req,
        isKookRoute ? 'rustplus_relay_chat_kook_forward_failed' : 'rustplus_relay_chat_discord_forward_failed',
        error.message || 'Rust+ clan chat third-party forward failed',
        {
          metadata: {
            channelId,
            platform: isKookRoute ? 'kook' : 'discord',
            targetId: settings?.targetId || '',
            targetName: settings?.targetName || '',
            serverKey: event.serverKey || '',
            routeId: route.id || '',
            chatMessageId: event.chatMessageId || ''
          }
        }
      ).catch(() => {});
    }
  }
}

export const forwardRustplusRelayChatToDiscord = forwardRustplusRelayChatToThirdParty;

async function editDiscordChannelMessage(settings, channelId, messageId, message) {
  const token = discordBotToken(settings);
  const targetChannelId = normalizeText(channelId, DISCORD_ID_MAX_LENGTH);
  const targetMessageId = normalizeText(messageId, 80);
  if (!token || !targetChannelId || !targetMessageId) {
    throw Object.assign(new Error('Discord Bot Token, Channel ID, or Message ID is not configured.'), { status: 400 });
  }
  const result = await discordApiRequest(`/channels/${encodeURIComponent(targetChannelId)}/messages/${encodeURIComponent(targetMessageId)}`, {
    method: 'PATCH',
    botToken: token,
    body: {
      ...message,
      allowed_mentions: { parse: [] }
    },
    scope: 'channel_message_update'
  });
  const { response, payload, error } = result;
  if (!result.ok) {
    const detail = normalizeText(payload?.message || payload?.error || `Discord HTTP ${response.status}`, 240);
    throw Object.assign(new Error(`Discord message update failed: ${detail}`), {
      status: error?.status || (response.status >= 500 ? 502 : 400),
      discordCode: payload?.code
    });
  }
  return payload;
}

async function deleteDiscordChannelMessage(settings, channelId, messageId) {
  const token = discordBotToken(settings);
  const targetChannelId = normalizeText(channelId, DISCORD_ID_MAX_LENGTH);
  const targetMessageId = normalizeText(messageId, 80);
  if (!token || !targetChannelId || !targetMessageId) {
    throw Object.assign(new Error('Discord Bot Token, Channel ID, or Message ID is not configured.'), { status: 400 });
  }
  const result = await discordApiRequest(`/channels/${encodeURIComponent(targetChannelId)}/messages/${encodeURIComponent(targetMessageId)}`, {
    method: 'DELETE',
    botToken: token,
    scope: 'channel_message_delete',
    okStatuses: [204, 404]
  });
  const { response, payload, error } = result;
  if (response.status === 204) return true;
  if (response.status === 404 || String(payload?.message || '').includes('Unknown Message')) return false;
  const detail = normalizeText(payload?.message || payload?.error || `Discord HTTP ${response.status}`, 240);
  throw Object.assign(new Error(`Discord message delete failed: ${detail}`), {
    status: error?.status || (response.status >= 500 ? 502 : 400),
    discordCode: payload?.code
  });
}

async function verifyDiscordInteractionSignature(req, publicKey) {
  const signature = String(req.get('x-signature-ed25519') || '');
  const timestamp = String(req.get('x-signature-timestamp') || '');
  if (!signature || !timestamp || !/^[a-f0-9]{128}$/i.test(signature) || !/^[a-f0-9]{64}$/i.test(publicKey || '')) {
    return false;
  }
  try {
    const key = await crypto.webcrypto.subtle.importKey(
      'raw',
      Buffer.from(publicKey, 'hex'),
      { name: 'Ed25519' },
      false,
      ['verify']
    );
    const body = Buffer.isBuffer(req.body) ? req.body : Buffer.from(String(req.body || ''));
    const signed = Buffer.concat([Buffer.from(timestamp), body]);
    return await crypto.webcrypto.subtle.verify({ name: 'Ed25519' }, key, Buffer.from(signature, 'hex'), signed);
  } catch {
    return false;
  }
}

function discordInteractionMessage(content) {
  return {
    type: 4,
    data: {
      content: normalizeText(content, 900),
      flags: 64
    }
  };
}

function discordInteractionDeferredUpdateMessage() {
  return { type: 6 };
}

function discordPublicInteractionMessage(data = {}) {
  return {
    type: 4,
    data: {
      ...data,
      allowed_mentions: { parse: [] }
    }
  };
}

function discordInteractionUpdateMessage(message) {
  return {
    type: 7,
    data: {
      content: normalizeText(message.content, 2000),
      embeds: message.embeds,
      components: message.components,
      allowed_mentions: message.allowed_mentions || { parse: [] }
    }
  };
}

function discordInteractionFollowupData(content) {
  if (content && typeof content === 'object') {
    const data = content.type && content.data ? content.data : content;
    return {
      ...data,
      flags: data.flags ?? 64,
      allowed_mentions: { parse: [] }
    };
  }
  return {
    content: normalizeText(content, 120),
    flags: 64,
    allowed_mentions: { parse: [] }
  };
}

