async function recordMessageDeletionTaskPersistenceFailureRun({ task = {}, stage = '', fallbackDeleteScheduled = false, error = {} } = {}) {
  const taskId = normalizeText(task.id, 160);
  if (!taskId) return null;
  const errorMessage = normalizeText(error?.message || error || 'Message deletion task persistence failed', 500);
  return createOperationRun({
    type: 'discord_original_interaction_delete_task',
    platform: 'discord',
    source: 'interaction',
    status: 'failed',
    targetType: 'message_deletion_task',
    targetId: taskId,
    channelId: normalizeText(task.channelId, DISCORD_ID_MAX_LENGTH),
    messageId: normalizeText(task.messageId, 120),
    dedupeKey: `discord:original-interaction-delete-task:${taskId}:${normalizeText(stage, 40) || 'persist'}`,
    errorSummary: errorMessage,
    retryable: true,
    metadata: {
      taskId,
      messageType: normalizeText(task.messageType, 80),
      stage: normalizeText(stage, 80),
      deleteAt: normalizeText(task.deleteAt, 80),
      trackingWriteFailed: true,
      trackingWriteError: normalizeText(errorMessage, 240),
      fallbackDeleteScheduled: Boolean(fallbackDeleteScheduled),
      externalActionAttempted: false,
      externalActionSucceeded: false
    }
  }).catch((reportError) => {
    console.warn('[nb-clan] message deletion persistence operation run failed:', reportError?.message || reportError);
    return null;
  });
}

