async function registerDiscordWipeAttendanceCommand(settings) {
  const token = discordBotToken(settings);
  const applicationId = normalizeText(settings?.applicationId, DISCORD_ID_MAX_LENGTH);
  const guildId = normalizeText(settings?.guildId, DISCORD_ID_MAX_LENGTH);
  if (!token || !applicationId || !guildId) {
    throw Object.assign(new Error('Discord Bot Token, Application ID, or Guild ID is not configured.'), { status: 400 });
  }
  const result = await discordApiRequest(`/applications/${encodeURIComponent(applicationId)}/guilds/${encodeURIComponent(guildId)}/commands`, {
    method: 'POST',
    botToken: token,
    body: {
      name: discordWipeAttendanceCommandName(settings),
      type: 1,
      description: discordText(DISCORD_DEFAULT_LANGUAGE, 'wipeAttendanceCommandDescription'),
      description_localizations: discordTextLocalizations('wipeAttendanceCommandDescription'),
      options: [
        {
          type: 5,
          name: DISCORD_WIPE_MENTION_OPTION_NAME,
          description: discordText(DISCORD_DEFAULT_LANGUAGE, 'wipeAttendanceMentionEveryoneOption'),
          description_localizations: discordTextLocalizations('wipeAttendanceMentionEveryoneOption'),
          required: false
        }
      ],
      default_member_permissions: '8',
      dm_permission: false
    },
    scope: 'guild_command_register'
  });
  const { response, payload, error } = result;
  if (!result.ok) {
    const detail = normalizeText(payload?.message || payload?.error || `Discord HTTP ${response.status}`, 240);
    throw Object.assign(new Error(`Discord command registration failed: ${detail}`), { status: error?.status || (response.status >= 500 ? 502 : 400) });
  }
  return payload;
}

