function canUseDiscordMemberManage(payload, settings) {
  const administratorPermission = 0x8n;
  if ((discordInteractionPermissions(payload) & administratorPermission) === administratorPermission) return true;
  const roleIds = discordRoleIdList(settings?.memberManageRoleId);
  if (!roleIds.length) return false;
  const interactionRoleIds = discordInteractionRoleIds(payload);
  return roleIds.some((roleId) => interactionRoleIds.has(roleId));
}

