function discordModalValue(payload, customId) {
  const stack = [...(payload?.data?.components || [])];
  while (stack.length) {
    const component = stack.shift();
    if (!component) continue;
    if (component.custom_id === customId) {
      if (Array.isArray(component.values)) return normalizeText(component.values[0], 160);
      if (Object.hasOwn(component, 'value')) return normalizeText(component.value, 160);
    }
    if (component.component) stack.push(component.component);
    if (Array.isArray(component.components)) stack.push(...component.components);
  }
  return '';
}

function discordMemberRegisterSpecialtyFromPayload(payload) {
  const customId = normalizeText(payload?.data?.custom_id, 100);
  const [, action, specialty] = customId.split(':');
  if (action === 'submit') return normalizeMemberSpecialty(specialty);
  if (action === 'specialty') {
    return normalizeMemberSpecialty(Array.isArray(payload?.data?.values) ? payload.data.values[0] : '');
  }
  if (action === 'vip_type') return normalizeMemberSpecialty(specialty);
  return '';
}

function discordMemberRegisterVipTypeFromPayload(payload) {
  const customId = normalizeText(payload?.data?.custom_id, 120);
  const [, action, _specialty, vipType] = customId.split(':');
  if (action === 'submit') return normalizeDiscordVitalVipType(vipType);
  if (action === 'vip_type') {
    return normalizeDiscordVitalVipType(Array.isArray(payload?.data?.values) ? payload.data.values[0] : '');
  }
  return 'none';
}

function findDiscordRegisterSquad(store, squadName) {
  const name = normalizeText(squadName, 80) || '57';
  const normalizedName = name.toLowerCase();
  let squad = activeSquads(store).find((item) => normalizeText(item.name, 80).toLowerCase() === normalizedName);
  if (squad) return squad;
  const createdAt = nowIso();
  squad = {
    id: createId('squad'),
    name,
    leaderUserId: '',
    leaderUserIds: [],
    notes: 'Auto-created by Discord member registration',
    createdBy: 'discord_member_register',
    createdAt,
    updatedAt: createdAt,
    archivedAt: ''
  };
  store.squads.unshift(squad);
  return squad;
}

function resolveDiscordRegisterSquad(store, application = {}, settings = {}) {
  const squadId = normalizeText(application.squadId, 80);
  if (squadId) {
    const squad = activeSquads(store).find((item) => item.id === squadId);
    if (squad) return squad;
  }
  return findDiscordRegisterSquad(store, application.squadName || settings.memberRegisterSquadName || '57');
}

function assignMemberToSquadDirect(store, member, squad, actorId) {
  store.squadMembers = store.squadMembers.filter((item) => item.memberId !== member.id);
  store.squadMembers.push({
    id: createId('squad_member'),
    squadId: squad.id,
    memberId: member.id,
    addedByUserId: actorId,
    createdAt: nowIso()
  });
}

