function wechatManagementActor(store, req) {
  if (req.user) return req.user;
  const wechatUser = req.wechatUser || null;
  if (!wechatUser) return { id: 'anonymous', username: 'anonymous', role: 'member' };
  const member = wechatUser.memberId ? (store.members || []).find((item) => item.id === wechatUser.memberId) : null;
  return req.wechatManagementUser || wechatManagementUserForMember(store, wechatUser, member) || {
    id: wechatUser.id,
    username: wechatUser.nickname || wechatUser.id,
    role: 'member'
  };
}

function resolveWechatAdminSyncWipe(store, requestedWipeId = '') {
  const normalizedWipeId = normalizeText(requestedWipeId, 120);
  if (!normalizedWipeId || normalizedWipeId === 'current') return currentWipe(store);
  return store.wipes.find((wipe) => wipe.id === normalizedWipeId) || null;
}

function assertWechatAdminSyncWipe(wipe) {
  if (!wipe) throw Object.assign(new Error('档期不存在'), { status: 404 });
  if (wipe.status !== 'closed' && !isWipeStartedServer(wipe)) {
    throw Object.assign(new Error('计划档尚未开荒'), { status: 400 });
  }
}

function wechatAdminWipeSyncJobsPayload(store, wipe, { limit = 8 } = {}) {
  const payload = syncJobsPayload(store, { limit: 100 });
  const targetWipeId = wipe?.id || '';
  const requestedLimit = Math.max(1, Math.min(20, Number(limit) || 8));
  const matchesWipeSync = (job = {}) => {
    const type = normalizeSyncJobType(job.type);
    return Boolean(
      targetWipeId &&
      job.targetWipeId === targetWipeId &&
      (type === 'kda' || type === 'battlemetrics_playtime')
    );
  };
  const current = payload.current.filter(matchesWipeSync);
  const recent = payload.recent.filter(matchesWipeSync).slice(0, requestedLimit);
  return {
    wipeId: targetWipeId,
    current,
    recent,
    activeTypes: {
      kda: current.some((job) => normalizeSyncJobType(job.type) === 'kda'),
      playtime: current.some((job) => normalizeSyncJobType(job.type) === 'battlemetrics_playtime')
    },
    partial: payload.partial,
    readError: payload.readError,
    updatedAt: payload.updatedAt
  };
}

function activeWipeParticipantMemberIds(store, wipe) {
  if (!wipe) return [];
  return store.wipeParticipants
    .filter((participant) => participant.wipeId === wipe.id && isParticipantAvailable(participant.status))
    .map((participant) => participant.memberId);
}

function publicWechatAdminLog(log = {}) {
  return {
    id: log.id || '',
    type: log.type || '',
    actorUserId: log.actorUserId || '',
    actorUsername: log.actorUsername || '',
    steamId: log.steamId || '',
    targetId: log.targetId || '',
    summary: expandVitalRustName(log.summary || ''),
    metadata: log.metadata && typeof log.metadata === 'object' ? log.metadata : {},
    createdAt: log.createdAt || ''
  };
}

function wechatAdminApplicationCounts(records = []) {
  const counts = Object.fromEntries([...WECHAT_APPLICATION_STATUSES].map((item) => [item, 0]));
  for (const record of records || []) {
    const key = wechatApplicationStatus(record);
    counts[key] = (counts[key] || 0) + 1;
  }
  return counts;
}

function finiteWechatSummaryCount(store, key) {
  const count = Number(store.summaryCounts?.[key]);
  return Number.isFinite(count) ? count : null;
}

function wechatAdminSummaryPayload(store, viewer) {
  const joinCounts = store.summaryApplicationCounts?.join || wechatAdminApplicationCounts(store.joinApplications || []);
  const activeWipe = currentWipe(store);
  const wipeSummary = wechatWipeParticipantsPayload(store, activeWipe, '', viewer).summary;
  const summaryMemberCount = finiteWechatSummaryCount(store, 'members');
  const visibleMemberCount = summaryMemberCount !== null
    ? summaryMemberCount
    : (store.members || [])
      .filter((member) => canViewAllData(viewer) || canManageMemberInStore(store, viewer, member))
      .length;
  const summarySquadCount = finiteWechatSummaryCount(store, 'squads');
  const visibleSquadCount = summarySquadCount !== null
    ? summarySquadCount
    : (canViewAllData(viewer) ? activeSquads(store) : leaderSquads(store, viewer)).length;
  const todayLogCount = Number(store.logSummary?.todayCount || 0);
  const summaryExportCount = finiteWechatSummaryCount(store, 'export');
  const exportCount = summaryExportCount !== null
    ? summaryExportCount
    : new Set(
      (store.wipes || [])
        .filter((wipe) => canViewWipeRecord(store, wipe, viewer))
        .map((wipe) => wipe.id)
        .filter(Boolean)
    ).size;
  return {
    counts: {
      review: joinCounts.pending || 0,
      wipe: wipeSummary.total || 0,
      members: visibleMemberCount,
      squads: visibleSquadCount,
      export: exportCount,
      logs: todayLogCount
    },
    review: {
      joinPending: joinCounts.pending || 0,
      joinCounts
    },
    wipe: {
      id: activeWipe?.id || '',
      participantCount: wipeSummary.total || 0,
      summary: wipeSummary
    },
    members: { total: visibleMemberCount },
    squads: { total: visibleSquadCount },
    export: { total: exportCount },
    logs: {
      total: todayLogCount,
      range: store.logSummary?.range || null
    }
  };
}

function findWechatQueryMembers(store, rawQuery) {
  const query = normalizeText(rawQuery, 500);
  if (!query) return [];
  const lowered = query.toLowerCase();
  return store.members
    .filter((member) => {
      const wechatUser = linkedWechatUserForMember(store, member);
      const specialties = normalizeMemberSpecialties(member.specialty).join(' ');
      return [
        member.steamId,
        member.customName,
        member.steamNickname,
        member.rawInput,
        member.discordId,
        member.wechatId,
        wechatUser?.id,
        wechatUser?.nickname,
        wechatUser?.wechatId,
        specialties
      ].some((value) => String(value || '').toLowerCase().includes(lowered));
    })
    .sort((left, right) => {
      const leftName = memberDisplayName(left).toLowerCase();
      const rightName = memberDisplayName(right).toLowerCase();
      const leftExact = left.steamId === query || leftName === lowered ? 0 : 1;
      const rightExact = right.steamId === query || rightName === lowered ? 0 : 1;
      if (leftExact !== rightExact) return leftExact - rightExact;
      return leftName.localeCompare(rightName);
    })
    .slice(0, 10);
}

function wechatRankingMetricValue(row, metric) {
  if (metric === 'kd') {
    const deaths = Math.max(1, Number(row.deaths || 0));
    return Number((Number(row.kills || 0) / deaths).toFixed(2));
  }
  if (metric === 'online_minutes') return wechatRankingOnlineMinutes(row);
  return Number(row[metric] || 0);
}

function wechatRankingMetricText(value, metric) {
  if (metric === 'online_minutes') return formatExportPlayTimeMinutes(value, 'zh');
  if (metric === 'kda' || metric === 'kd') return Number(value || 0).toFixed(2);
  return String(Math.round(Number(value || 0)));
}

function sameWechatRankingMember(left = {}, right = {}) {
  return Boolean(
    (left.memberId && right.memberId && left.memberId === right.memberId) ||
    (left.member?.id && right.memberId && left.member.id === right.memberId) ||
    (left.memberId && right.member?.id && left.memberId === right.member.id) ||
    (left.steamId && right.steamId && left.steamId === right.steamId) ||
    (left.member?.steamId && right.steamId && left.member.steamId === right.steamId) ||
    (left.steamId && right.member?.steamId && left.steamId === right.member.steamId)
  );
}

function wechatRankingMetricRanks(rows = [], targetRow = {}) {
  if (!targetRow || (!targetRow.memberId && !targetRow.steamId && !targetRow.member?.id && !targetRow.member?.steamId)) return {};
  return WECHAT_RANKING_METRIC_KEYS.reduce((result, metric) => {
    const sortedRows = [...rows].sort((left, right) => {
      const diff = wechatRankingMetricValue(right, metric) - wechatRankingMetricValue(left, metric);
      if (diff !== 0) return diff;
      return String(left.displayName || left.steamId).localeCompare(String(right.displayName || right.steamId));
    });
    const index = sortedRows.findIndex((row) => sameWechatRankingMember(row, targetRow));
    if (index >= 0) {
      const value = wechatRankingMetricValue(sortedRows[index], metric);
      result[metric] = {
        rank: index + 1,
        value,
        valueText: wechatRankingMetricText(value, metric)
      };
    }
    return result;
  }, {});
}

function wechatRankingOnlineMinutes(row = {}) {
  const rowMinutes = Number(row.onlineTimeMinutes || 0);
  if (Number.isFinite(rowMinutes) && rowMinutes > 0) return rowMinutes;
  const summary = row.onlineSummary || {};
  const serverMinutes = Number(summary.serverPlayTimeMinutes || 0);
  if (Number.isFinite(serverMinutes) && serverMinutes > 0) return serverMinutes;
  const serverSeconds = Number(summary.serverPlayTimeSeconds || 0);
  if (Number.isFinite(serverSeconds) && serverSeconds > 0) return Math.round(serverSeconds / 60);
  return Number.isFinite(rowMinutes) ? rowMinutes : 0;
}

function wechatRankingLiveMemberForRow(store, row, member, context = {}) {
  if (!store) return null;
  const membersById = context.membersById || null;
  const membersBySteamId = context.membersBySteamId || null;
  const memberId = row?.memberId || member?.id || '';
  if (memberId) {
    const matched = membersById
      ? membersById.get(memberId)
      : (store.members || []).find((item) => item.id === memberId);
    if (matched) return matched;
  }
  const steamId = row?.steamId || member?.steamId || '';
  if (steamId) {
    return membersBySteamId
      ? membersBySteamId.get(steamId) || null
      : (store.members || []).find((item) => item.steamId === steamId) || null;
  }
  return null;
}

function wechatRankingSnapshotMember(row, member) {
  if (member) return member;
  if (!row?.memberId && !row?.steamId) return null;
  return {
    id: row.memberId || '',
    steamId: row.steamId || '',
    displayName: row.displayName || row.name || row.steamId || '',
    customName: row.displayName || row.name || '',
    steamNickname: row.steamNickname || '',
    avatar: row.avatar || '',
    squadId: row.squadId || '',
    squadName: row.squadName || '',
    specialty: []
  };
}

function publicWechatRankingMemberDetail(store, wipe, row, member, context = {}) {
  const snapshotMember = wechatRankingSnapshotMember(row, member);
  if (!store || !snapshotMember || (!snapshotMember.id && !snapshotMember.steamId)) return null;
  const liveMember = wechatRankingLiveMemberForRow(store, row, snapshotMember, context);
  const isCurrentMember = Boolean(liveMember);
  const detail = publicWechatDirectoryMember(store, snapshotMember, context.viewer || null);
  const onlineSummary = row.onlineSummary || {};
  const currentKda = {
    wipeId: wipe?.id || row.wipeId || '',
    wipeName: expandVitalRustName(wipe?.name || ''),
    wipeStatus: wipe ? effectiveWipeStatus(wipe) : '',
    serverName: expandVitalRustName(wipe?.serverName || wipe?.name || ''),
    startedAt: wipe?.startedAt || '',
    kills: Number(row.kills || 0),
    deaths: Number(row.deaths || 0),
    assists: Number(row.assists || 0),
    t3Kills: Number(row.t3Kills || 0),
    kd: wechatRankingMetricValue(row, 'kd'),
    kda: Number(row.kda || 0),
    rockets: Number(row.rockets || 0),
    sulfur: Number(row.sulfur || 0),
    metalOre: Number(row.metalOre || 0),
    building: Number(row.building || 0),
    playTimeMinutes: Number(row.playTimeMinutes || 0),
    onlineTimeMinutes: wechatRankingOnlineMinutes(row),
    onlineSummary,
    syncedAt: row.syncedAt || ''
  };
  return {
    ...detail,
    isCurrentMember,
    currentMemberId: liveMember?.id || '',
    membershipState: isCurrentMember ? 'current' : 'archived',
    membershipLabel: isCurrentMember ? '当前成员' : '历史成员',
    membershipDescription: isCurrentMember
      ? ''
      : '该玩家来自结档快照，当前成员库已无此成员。',
    memberStatus: isCurrentMember ? normalizeMemberStatus(liveMember.memberStatus) : 'archived',
    memberStatusText: isCurrentMember ? memberStatusText(liveMember.memberStatus) : '历史成员',
    squad: (!isCurrentMember && row.squadName) ? row.squadName : detail.squad,
    squadName: (!isCurrentMember && row.squadName) ? row.squadName : detail.squadName,
    historicalSquadName: row.squadName || detail.squadName || '',
    currentKda,
    currentWipe: {
      ...(detail.currentWipe || {}),
      wipeId: wipe?.id || detail.currentWipe?.wipeId || '',
      wipeName: expandVitalRustName(wipe?.name || detail.currentWipe?.wipeName || ''),
      serverName: expandVitalRustName(wipe?.serverName || wipe?.name || detail.currentWipe?.serverName || ''),
      wipeStatus: wipe ? effectiveWipeStatus(wipe) : detail.currentWipe?.wipeStatus,
      startedAt: wipe?.startedAt || detail.currentWipe?.startedAt || '',
      kda: currentKda
    }
  };
}

function publicWechatRankingRow(row, index, metric, store = null, wipe = null, context = {}) {
  const value = wechatRankingMetricValue(row, metric);
  const member = row.member || null;
  return {
    id: row.memberId || member?.id || row.steamId || `rank_${index + 1}`,
    rank: index + 1,
    memberId: row.memberId || member?.id || '',
    steamId: row.steamId || member?.steamId || '',
    name: row.displayName || member?.displayName || (member ? memberDisplayName(member) : '') || row.steamId || '-',
    displayName: row.displayName || member?.displayName || (member ? memberDisplayName(member) : '') || row.steamId || '-',
    avatar: member?.avatar || row.avatar || '',
    squad: row.squadName || '未分队',
    squadName: row.squadName || '',
    metric,
    value,
    valueText: wechatRankingMetricText(value, metric),
    secondary: row.squadName || '未分队',
    kills: Number(row.kills || 0),
    deaths: Number(row.deaths || 0),
    kda: Number(row.kda || 0),
    kd: wechatRankingMetricValue(row, 'kd'),
    t3Kills: Number(row.t3Kills || 0),
    rockets: Number(row.rockets || 0),
    sulfur: Number(row.sulfur || 0),
    metalOre: Number(row.metalOre || 0),
    building: Number(row.building || 0),
    playTimeMinutes: Number(row.playTimeMinutes || 0),
    onlineTimeMinutes: wechatRankingOnlineMinutes(row),
    syncedAt: row.syncedAt || '',
    memberDetail: publicWechatRankingMemberDetail(store, wipe, row, member, context)
  };
}

function localMemberKdaRowForWipe(store, wipe, member, viewer, indexes = getStoreIndexes(store)) {
  if (!store || !wipe || !member) return null;
  const indexedRow = indexes.latestKdaByWipeMemberKey.get(`${wipe.id}:member:${member.id}`) ||
    indexes.latestKdaByWipeMemberKey.get(`${wipe.id}:steam:${member.steamId}`) ||
    null;
  const rows = indexedRow ? [indexedRow] : kdaRowsForWipe(store, wipe, viewer, {
    scope: canViewOperationalData(viewer, store) ? 'all' : 'my_squad',
    q: member.steamId,
    sort: 'kda',
    order: 'desc'
  });
  return rows.find((item) => item.memberId === member.id || item.steamId === member.steamId) ||
    (store.kdaRows || []).find((item) => item.wipeId === wipe.id && (item.memberId === member.id || item.steamId === member.steamId));
}

function currentMemberKdaPayloadFromRow(store, wipe, row, member) {
  if (!row) return null;
  const onlineSummary = kdaRowOnlineSummary(store, row, member, wipe);
  return {
    wipeId: wipe.id,
    wipeName: expandVitalRustName(wipe.name || ''),
    wipeStatus: effectiveWipeStatus(wipe),
    serverName: expandVitalRustName(wipe.serverName || wipe.name || ''),
    startedAt: wipe.startedAt || '',
    kdaUrl: buildKdaUrl(wipe.vitalServerId, wipe.vitalWipeId),
    playerKdaUrl: wipe.vitalServerId && wipe.vitalWipeId && member?.steamId
      ? `${buildKdaUrl(wipe.vitalServerId, wipe.vitalWipeId)}&vitalUserId=${encodeURIComponent(member.steamId)}`
      : '',
    kills: Number(row.kills || 0),
    assists: Number(row.assists || 0),
    t3Kills: Number(row.t3Kills || 0),
    deaths: Number(row.deaths || 0),
    kd: wechatRankingMetricValue(row, 'kd'),
    kda: Number(row.kda || 0),
    rockets: Number(row.rockets || 0),
    sulfur: Number(row.sulfur || 0),
    metalOre: Number(row.metalOre || 0),
    building: Number(row.building || 0),
    playTimeMinutes: Number(row.playTimeMinutes || 0),
    onlineTimeMinutes: kdaRowOnlineMinutesForWipe(row, onlineSummary, wipe),
    onlineSummary,
    source: row.source || '',
    syncedAt: row.syncedAt || ''
  };
}

function currentMemberKdaPayload(store, member, viewer, indexes = getStoreIndexes(store)) {
  if (!member || !viewer || !canViewWipesInStore(store, viewer)) return null;
  const wipe = queryReferenceWipe(store);
  if (!wipe || !canViewWipeRecord(store, wipe, viewer)) return null;
  const row = localMemberKdaRowForWipe(store, wipe, member, viewer, indexes);
  return currentMemberKdaPayloadFromRow(store, wipe, row, member);
}

function currentMemberKdaPublicPayload(store, member) {
  if (!member) return null;
  const wipe = queryReferenceWipe(store);
  if (!wipe) return null;
  const viewer = { id: 'wechat_query_public', username: 'wechat_query_public', role: 'admin' };
  const row = localMemberKdaRowForWipe(store, wipe, member, viewer);
  return currentMemberKdaPublicPayloadFromRow(store, wipe, row, member);
}

function currentMemberKdaPublicPayloadFromRow(store, wipe, row, member) {
  if (!store || !wipe || !row || !member) return null;
  const participant = store.wipeParticipants.find((item) => item.wipeId === wipe.id && item.memberId === member.id && isParticipantAvailable(item.status));
  const indexes = getStoreIndexes(store);
  const currentSquad = indexes.squadByMemberId.get(member.id);
  const squadId = participant?.squadId || row.squadId || currentSquad?.squadId || member.squadId || '';
  const squad = store.squads.find((item) => item.id === squadId) || null;
  const onlineSummary = kdaRowOnlineSummary(store, row, member, wipe);
  return {
    wipeId: wipe.id,
    wipeName: expandVitalRustName(wipe.name || ''),
    wipeStatus: effectiveWipeStatus(wipe),
    serverName: expandVitalRustName(wipe.serverName || wipe.name || ''),
    startedAt: wipe.startedAt || '',
    kdaUrl: buildKdaUrl(wipe.vitalServerId, wipe.vitalWipeId),
    playerKdaUrl: wipe.vitalServerId && wipe.vitalWipeId && member.steamId
      ? `${buildKdaUrl(wipe.vitalServerId, wipe.vitalWipeId)}&vitalUserId=${encodeURIComponent(member.steamId)}`
      : '',
    squad: publicSquadIdentity(store, squad),
    row: row ? {
      kills: Number(row.kills || 0),
      assists: Number(row.assists || 0),
      t3Kills: Number(row.t3Kills || 0),
      deaths: Number(row.deaths || 0),
      kd: wechatRankingMetricValue(row, 'kd'),
      kda: Number(row.kda || 0),
      rockets: Number(row.rockets || 0),
      sulfur: Number(row.sulfur || 0),
      metalOre: Number(row.metalOre || 0),
      building: Number(row.building || 0),
      playTimeMinutes: Number(row.playTimeMinutes || 0),
      onlineTimeMinutes: kdaRowOnlineMinutesForWipe(row, onlineSummary, wipe),
      onlineSummary,
      raw: row.raw || null,
      source: row.source || '',
      syncedAt: row.syncedAt || ''
    } : null
  };
}

function publicIntegrationQueryPayload(store, resolved, member) {
  const publicMember = member ? queryMemberPayload(store, member, { detailed: false }) : null;
  return {
    query: {
      steamInput: resolved.rawInput || '',
      steamId: resolved.steamId,
      kind: resolved.kind || ''
    },
    isMember: Boolean(publicMember),
    member: publicMember ? {
      steamId: publicMember.steamId,
      displayName: publicMember.displayName,
      steamNickname: member.steamNickname || '',
      avatar: publicMember.avatar || '',
      profileUrl: publicMember.profileUrl || steamProfileUrl(publicMember.steamId),
      squadId: publicMember.squadId || '',
      squadName: publicMember.squadName || '',
      squad: publicMember.squad || null
    } : null,
    currentWipe: publicMember ? {
      ...publicMember.currentWipe,
      kda: currentMemberKdaPublicPayload(store, member)
    } : null
  };
}

function canFetchWechatQueryCurrentVitalKda(wipe, member) {
  if (process.env.NB_DISABLE_EXTERNAL_VITAL === '1') return false;
  if (!wipe || !member?.steamId) return false;
  if (!isWipeStartedServer(wipe)) return false;
  return wipeKdaCapability(wipe).kdaSyncAvailable;
}

async function fetchWechatQueryCurrentVitalKdaPayload(store, wipe, member, options = {}) {
  if (!canFetchWechatQueryCurrentVitalKda(wipe, member)) return null;
  const cacheKey = `${wipe.id || ''}:${wipe.vitalServerId || ''}:${wipe.vitalWipeId || ''}:${member.steamId}`;
  const cache = options.currentVitalKdaCache instanceof Map ? options.currentVitalKdaCache : null;
  if (cache?.has(cacheKey)) return await cache.get(cacheKey);
  const request = (async () => {
    try {
      const payloadRows = await fetchVitalKdaRows(wipe, [member.steamId], { includes: VITAL_LOOKUP_INCLUDES });
      const payload = (payloadRows || []).find((item) => normalizeText(item?.context?.userId, 80) === member.steamId) || null;
      if (!payload) return null;
      const existing = localMemberKdaRowForWipe(store, wipe, member, { id: 'wechat_query_public', role: 'admin' });
      const row = vitalPlayerToKdaRow(store, wipe, member, payload, existing);
      return currentMemberKdaPublicPayloadFromRow(store, wipe, row, member);
    } catch (error) {
      if (envFlagEnabled(process.env.NB_DEBUG_WECHAT_QUERY_VITAL)) {
        console.warn('[nb-clan] wechat query Vital fallback failed:', error?.message || error);
      }
      return null;
    }
  })();
  if (cache) cache.set(cacheKey, request);
  try {
    return await request;
  } finally {
    if (cache?.get(cacheKey) === request) {
      request.then((payload) => cache.set(cacheKey, Promise.resolve(payload))).catch(() => cache.delete(cacheKey));
    }
  }
}

function wechatQueryKdaPayloadHasRealData(currentKda = null) {
  if (!currentKda) return false;
  const row = currentKda.row || currentKda;
  if (!row) return false;
  if (row?.source === 'local_demo' || row?.raw?.generated === true) return false;
  return Boolean(row?.source || currentKda.source || row?.syncedAt || currentKda.syncedAt || row?.raw);
}

async function currentWechatQueryKdaPayload(store, member, localKda = null, options = {}) {
  if (wechatQueryKdaPayloadHasRealData(localKda)) return localKda;
  const wipe = queryReferenceWipe(store);
  if (!wipe) return null;
  if (process.env.NB_DISABLE_EXTERNAL_VITAL === '1' && localKda) return localKda;
  return await fetchWechatQueryCurrentVitalKdaPayload(store, wipe, member, options);
}

async function publicWechatQueryMemberPayload(store, member, wechatUser = null, options = {}) {
  if (!member) return null;
  const profile = publicWechatMemberProfile(store, member, wechatUser, { detailed: true });
  const indexes = getStoreIndexes(store);
  const viewer = { id: wechatUser?.id || 'wechat_query', role: 'admin' };
  const profileStats = memberProfilePayload(store, member, indexes, {
    useKdaFallback: options.profileKdaFallback !== false
  });
  const referenceWipe = queryReferenceWipe(store);
  const integration = publicIntegrationQueryPayload(store, {
    rawInput: member.steamId,
    steamId: member.steamId,
    kind: 'member'
  }, member);
  const currentKda = await currentWechatQueryKdaPayload(store, member, integration.currentWipe?.kda || null, options);
  const currentWipe = currentKda
    ? { ...(integration.currentWipe || profile.currentWipe || {}), kda: currentKda }
    : (integration.currentWipe || profile.currentWipe || null);
  return {
    ...profile,
    steamNickname: member.steamNickname || '',
    profileUrl: profile.profileUrl || steamProfileUrl(member.steamId),
    specialty: normalizeMemberSpecialties(member.specialty),
    profileStats: publicWechatProfileStats(profileStats),
    serverOnline: memberServerOnlinePayload(store, member, referenceWipe, indexes),
    recentHistoryServerOnline: memberRecentHistoryServerOnlinePayload(store, member, viewer, indexes),
    currentWipe,
    currentKda
  };
}

function externalWechatQueryMember(steamId, profileStats = null) {
  const normalizedSteamId = normalizeText(steamId, 80);
  const displayName = normalizeText(profileStats?.displayName, 120) || normalizedSteamId;
  return {
    id: `wechat_external_${normalizedSteamId}`,
    steamId: normalizedSteamId,
    rawInput: normalizedSteamId,
    customName: displayName,
    steamNickname: displayName,
    avatar: normalizeText(profileStats?.avatar, 500),
    specialty: []
  };
}

function publicWechatExternalCurrentWipePayload(currentKda = null) {
  if (!currentKda) return null;
  return {
    id: currentKda.wipeId || '',
    name: currentKda.wipeName || '',
    status: currentKda.wipeStatus || '',
    serverName: currentKda.serverName || '',
    startedAt: currentKda.startedAt || '',
    kdaUrl: currentKda.kdaUrl || '',
    playerKdaUrl: currentKda.playerKdaUrl || '',
    kda: currentKda
  };
}

async function publicWechatExternalQueryPayload(store, steamId, options = {}) {
  const normalizedSteamId = normalizeText(steamId, 80);
  if (!normalizedSteamId) return null;
  let profileStats = null;
  try {
    profileStats = await fetchRustKdaMemberProfileStats(normalizedSteamId, { includeInventory: false });
  } catch (error) {
    profileStats = profileStatsFromExternalPayload(
      normalizedSteamId,
      null,
      null,
      compactExternalError(error),
      null,
      null,
      compactExternalError(error)
    );
  }
  const externalMember = externalWechatQueryMember(normalizedSteamId, profileStats);
  const currentKda = await currentWechatQueryKdaPayload(store, externalMember, null, options);
  const currentWipe = publicWechatExternalCurrentWipePayload(currentKda);
  return {
    type: 'external_steam',
    isClanMember: false,
    steamId: normalizedSteamId,
    displayName: profileStats?.displayName || normalizedSteamId,
    name: profileStats?.displayName || normalizedSteamId,
    avatar: profileStats?.avatar || '',
    profileUrl: profileStats?.profileUrl || steamProfileUrl(normalizedSteamId),
    steamNickname: profileStats?.displayName || '',
    specialty: [],
    squadName: '',
    squad: null,
    profileStats: publicWechatProfileStats(profileStats || profileStatsFromKdaRow({})),
    serverOnline: null,
    recentHistoryServerOnline: null,
    currentWipe,
    currentKda
  };
}

function publicWechatProfileStats(profileStats = {}) {
  const officialKda = profileStats.officialKda || null;
  return {
    playTimeMinutes: Number(profileStats.playTimeMinutes || 0),
    playTimeKnown: Boolean(profileStats.playTimeKnown),
    playTimeVisibility: profileStats.playTimeVisibility || '',
    inventoryValue: profileStats.inventoryValue ?? null,
    inventoryCurrency: profileStats.inventoryCurrency || 'USD',
    inventoryPublic: Boolean(profileStats.inventoryPublic),
    inventoryVisibility: profileStats.inventoryVisibility || '',
    profilePublic: Boolean(profileStats.profilePublic),
    accountRestricted: Boolean(profileStats.accountRestricted),
    accountRestrictionStatus: profileStats.accountRestrictionStatus || '',
    accountRestrictionCheckedAt: profileStats.accountRestrictionCheckedAt || '',
    accountRestrictionError: profileStats.accountRestrictionError || '',
    vacBanned: Boolean(profileStats.vacBanned),
    numberOfVacBans: Number(profileStats.numberOfVacBans || 0),
    numberOfGameBans: Number(profileStats.numberOfGameBans || 0),
    daysSinceLastBan: Number(profileStats.daysSinceLastBan || 0),
    communityBanned: Boolean(profileStats.communityBanned),
    economyBan: profileStats.economyBan || 'none',
    economyRestricted: Boolean(profileStats.economyRestricted),
    steamBanCheckedAt: profileStats.steamBanCheckedAt || '',
    steamBanError: profileStats.steamBanError || '',
    fetchedAt: profileStats.fetchedAt || '',
    error: profileStats.error || '',
    battlemetrics: publicBattlemetricsPlaytimePayload(profileStats.battlemetrics || {}),
    hexaytron: publicHexaytronProfilePayload(profileStats.hexaytron || null),
    officialKda: officialKda ? {
      kills: Number(officialKda.kills || 0),
      deaths: Number(officialKda.deaths || 0),
      assists: Number(officialKda.assists || 0),
      kda: Number(officialKda.kda || 0),
      headshots: Number(officialKda.headshots || 0),
      hits: Number(officialKda.hits || 0),
      playerHits: Number(officialKda.playerHits || officialKda.hits || 0),
      totalHits: Number(officialKda.totalHits || officialKda.hits || 0),
      buildingHits: Number(officialKda.buildingHits || 0),
      signHits: Number(officialKda.signHits || 0),
      animalHits: Number(officialKda.animalHits || 0),
      deadPlayerHits: Number(officialKda.deadPlayerHits || 0),
      otherHits: Number(officialKda.otherHits || 0),
      bulletsFired: Number(officialKda.bulletsFired || 0),
      accuracy: Number(officialKda.accuracy || 0),
      headshotRate: Number(officialKda.headshotRate || 0),
      rockets: Number(officialKda.rockets || 0),
      sulfur: Number(officialKda.sulfur || 0),
      metalOre: Number(officialKda.metalOre || 0),
      wood: Number(officialKda.wood || 0),
      stone: Number(officialKda.stone || 0),
      playTimeMinutes: Number(officialKda.playTimeMinutes || 0),
      achievementsCount: Number(officialKda.achievementsCount || 0)
    } : null,
    officialKdaFetchedAt: profileStats.officialKdaFetchedAt || '',
    officialKdaError: profileStats.officialKdaError || ''
  };
}

function normalizeWechatRankingMetric(value) {
  const raw = normalizeText(value, 40) || 'kda';
  return WECHAT_RANKING_METRIC_ALIASES[raw] || raw;
}

function wechatRankingEmptyState(wipe, rows = []) {
  if (Array.isArray(rows) && rows.length) return null;
  if (!wipe) {
    return {
      code: 'no_wipe',
      title: '暂无排行数据',
      description: '当前还没有开荒档期。'
    };
  }
  const capability = wipeKdaCapability(wipe);
  if (!capability.kdaSyncAvailable && capability.kdaSyncMessage) {
    return {
      code: capability.kdaSyncUnavailableReason || 'kda_sync_unavailable',
      title: '暂无自动 KDA 数据',
      description: capability.kdaSyncMessage
    };
  }
  return {
    code: 'no_data',
    title: '暂无排行数据',
    description: '当前档还没有同步或导入 KDA 数据。'
  };
}

function activeSquads(store) {
  return store.squads.filter((squad) => !squad.archivedAt);
}

function activeSquadById(store, squadId) {
  return activeSquads(store).find((squad) => squad.id === squadId) || null;
}

function findLeaderSquad(store, user) {
  return leaderSquads(store, user)[0] || null;
}

function leaderSquads(store, user) {
  return activeSquads(store).filter((squad) => isSquadLeader(user, squad));
}

function squadLeaderUsers(store, squad) {
  const usersById = new Map((store.users || []).map((user) => [user.id, user]));
  return squadLeaderIds(squad)
    .map((userId) => usersById.get(userId))
    .filter(Boolean);
}

function requestedSquadLeaderIds(body = {}) {
  const rawIds = Array.isArray(body.leaderUserIds)
    ? body.leaderUserIds
    : (body.leaderUserId ? [body.leaderUserId] : []);
  return [...new Set(rawIds.map((id) => normalizeText(id, 80)).filter(Boolean))];
}

function ensureLeaderSquad(store, user) {
  if (!isLeader(user)) return null;
  const existing = findLeaderSquad(store, user);
  if (existing) return existing;
  const createdAt = nowIso();
  const squad = {
    id: createId('squad'),
    name: `${user.steamNickname || user.username} Squad`,
    leaderUserId: user.id,
    leaderUserIds: [user.id],
    notes: '',
    createdBy: user.id,
    createdAt,
    updatedAt: createdAt,
    archivedAt: ''
  };
  store.squads.unshift(squad);
  return squad;
}

function assertUserSteamBindingAvailable(store, userId, steamId) {
  if (!steamId) return;
  const otherUser = store.users.find((user) => user.id !== userId && user.boundSteamId === steamId);
  if (otherUser) {
    throw Object.assign(new Error('该 SteamID 已被其他账号绑定'), { status: 409 });
  }
}

function assertSteamBindingAvailable(store, userId, steamId) {
  assertUserSteamBindingAvailable(store, userId, steamId);
  const existingMember = store.members.find((member) => member.steamId === steamId);
  if (existingMember && existingMember.invitedByUserId !== userId) {
    throw Object.assign(new Error('该 SteamID 已被其他成员记录使用'), { status: 409 });
  }
}

function ensureAccountMember(store, user, options = {}) {
  if (!user?.boundSteamId) return null;
  const shouldEnsureSquad = options.ensureSquad !== false;
  const createdAt = nowIso();
  let member = store.members.find((item) => item.steamId === user.boundSteamId);
  const canAttachToUserSquad = !member || member.invitedByUserId === user.id;

  if (!member) {
    member = {
      id: createId('member'),
      steamId: user.boundSteamId,
      rawInput: options.rawInput || user.boundSteamId,
      customName: '',
      steamNickname: user.steamNickname || '',
      avatar: options.avatar || '',
      discordId: '',
      wechatId: '',
      wechatUserId: '',
      phone: '',
      notes: '',
      specialty: [],
      battlemetricsId: '',
      invitedByUserId: user.id,
      createdAt,
      updatedAt: createdAt
    };
    store.members.push(member);
  } else {
    let changed = false;
    if (!member.rawInput) {
      member.rawInput = options.rawInput || user.boundSteamId;
      changed = true;
    }
    if (!member.steamNickname && user.steamNickname) {
      member.steamNickname = user.steamNickname;
      changed = true;
    }
    if (!member.avatar && options.avatar) {
      member.avatar = options.avatar;
      changed = true;
    }
    if (!member.specialty) {
      member.specialty = [];
      changed = true;
    }
    if (changed) member.updatedAt = nowIso();
  }

  let squad = null;
  if (canAttachToUserSquad) {
    squad = findLeaderSquad(store, user);
    if (!squad && shouldEnsureSquad && isLeader(user)) {
      squad = ensureLeaderSquad(store, user);
    }
  }
  if (squad) {
    const current = store.squadMembers.find((item) => item.memberId === member.id);
    if (!current || current.squadId !== squad.id) {
      store.squadMembers = store.squadMembers.filter((item) => item.memberId !== member.id);
      store.squadMembers.push({
        id: createId('squad_member'),
        squadId: squad.id,
        memberId: member.id,
        addedByUserId: user.id,
        createdAt: nowIso()
      });
    }
  }

  return member;
}

function ensureLeaderMember(store, user, options = {}) {
  if (!isLeader(user)) return null;
  return ensureAccountMember(store, user, options);
}

function ensureLeaderMembers(store, options = {}) {
  for (const user of store.users) {
    ensureLeaderMember(store, user, options);
  }
}

function ensureSquadLeaderMembers(store, options = {}) {
  const leaderIds = new Set(activeSquads(store).flatMap((squad) => squadLeaderIds(squad)));
  for (const user of store.users) {
    if (leaderIds.has(user.id)) {
      ensureAccountMember(store, user, options);
    }
  }
}

function accountMemberEnsureNeeded(store, user, options = {}) {
  if (!user?.boundSteamId) return false;
  const shouldEnsureSquad = options.ensureSquad !== false;
  const member = store.members.find((item) => item.steamId === user.boundSteamId);
  if (!member) return true;
  if (!member.rawInput) return true;
  if (!member.steamNickname && user.steamNickname) return true;
  if (!member.specialty) return true;
  const canAttachToUserSquad = member.invitedByUserId === user.id;
  if (!canAttachToUserSquad) return false;
  const squad = findLeaderSquad(store, user);
  if (!squad && shouldEnsureSquad && isLeader(user)) return true;
  if (!squad) return false;
  const current = store.squadMembers.find((item) => item.memberId === member.id);
  return !current || current.squadId !== squad.id;
}

function viewerMemberSyncNeeded(store, user) {
  if (!user) return false;
  if (isAdmin(user)) {
    const activeSquadLeaderIds = new Set(activeSquads(store).flatMap((squad) => squadLeaderIds(squad)));
    return store.users.some((candidate) => (
      (isLeader(candidate) || activeSquadLeaderIds.has(candidate.id)) &&
        accountMemberEnsureNeeded(store, candidate, { ensureSquad: false })
    ));
  }
  if (isLeader(user) || leaderSquads(store, user).length) {
    return accountMemberEnsureNeeded(store, user);
  }
  return false;
}

function viewerMemberSyncWriteOptions(user, snapshot = {}, options = {}) {
  if (!sqlitePrimaryMode()) return options;
  const userId = normalizeText(user?.id, 120);
  const optionUserIds = uniqueNormalizedTexts([
    ...(Array.isArray(options.userIds) ? options.userIds : [options.userIds]),
    options.userId,
    userId
  ], 120);
  return {
    ...options,
    requireScopedMemberBaseWrite: true,
    users: mergeRecordsById(snapshot.users || [], user ? [user] : [], options.users || []),
    members: mergeRecordsById(snapshot.members || [], options.members || []),
    squads: mergeRecordsById(snapshot.squads || [], options.squads || []),
    squadMembers: mergeRecordsById(snapshot.squadMembers || [], options.squadMembers || []),
    ...(optionUserIds.length ? { userIds: optionUserIds } : {})
  };
}

function memberSquadMap(store) {
  return new Map(store.squadMembers.map((item) => [item.memberId, item]));
}

function canManageMemberInStore(store, user, member, indexes = getStoreIndexes(store)) {
  if (!user || !member) return false;
  if (canEditModuleInStore(store, user, 'members')) return true;
  const memberSquad = indexes.squadByMemberId.get(member?.id);
  return canManageMember(user, member, {
    memberSquadId: memberSquad?.squadId || '',
    leaderSquadIds: leaderSquads(store, user).map((squad) => squad.id)
  });
}

function canUseSquadsInStore(store, user) {
  return canViewModuleInStore(store, user, 'squads') || canUseSquads(user, activeSquads(store));
}

function canViewSquadInStore(store, user, squad) {
  if (!squad || squad.archivedAt) return false;
  return canViewModuleInStore(store, user, 'squads') || canViewSquad(user, squad);
}

function canManageSquadInStore(store, user, squad) {
  if (!squad || squad.archivedAt) return false;
  return canEditModuleInStore(store, user, 'squads') || canManageSquad(user, squad);
}

function enrichSquad(store, squad, viewer = null) {
  const leaderUsers = squadLeaderUsers(store, squad);
  const leaderIds = squadLeaderIds(squad);
  const leaderNames = leaderUsers.map((user) => userDisplayName(user));
  const memberCount = store.squadMembers.filter((item) => item.squadId === squad.id).length;
  const activeWipe = store.wipes.find((wipe) => wipe.status === 'active');
  const participantCount = activeWipe
    ? store.wipeParticipants.filter((item) => item.wipeId === activeWipe.id && item.squadId === squad.id && isParticipantAvailable(item.status)).length
    : 0;
  return {
    ...squad,
    leaderUserId: leaderIds[0] || '',
    leaderUserIds: leaderIds,
    leaderName: leaderNames.join(', ') || '未知',
    leaderNames,
    memberCount,
    participantCount,
    canManage: canManageSquadInStore(store, viewer, squad),
    canView: canViewSquadInStore(store, viewer, squad)
  };
}

function timestampForSort(value) {
  const time = Date.parse(value || '');
  return Number.isFinite(time) ? time : 0;
}

function memberOnlineSummary(store, memberOrId, indexes = getStoreIndexes(store)) {
  const memberId = typeof memberOrId === 'string' ? memberOrId : memberOrId?.id;
  const cached = indexes.memberProfileByMemberId.get(memberId) || null;
  const weeklySeconds = Number(cached?.battlemetricsWeeklyPlayTimeSeconds || 0);
  const serverSeconds = Number(cached?.battlemetricsServerPlayTimeSeconds ?? cached?.battlemetricsTotalPlayTimeSeconds ?? 0);
  const totalSeconds = Number(cached?.battlemetricsTotalPlayTimeSeconds || 0);
  const cachedServerId = cached?.battlemetricsServerId || '';
  const cachedWipe = cached?.battlemetricsWipeId
    ? indexes.wipesById.get(cached.battlemetricsWipeId)
    : (cachedServerId ? indexes.latestWipeByBattlemetricsServerId.get(cachedServerId) : null);
  const fallbackSyncInfo = battlemetricsWipeSyncInfo(cachedWipe, cachedServerId);
  return {
    wipeId: cached?.battlemetricsWipeId || fallbackSyncInfo.wipeId || '',
    wipeName: cached?.battlemetricsWipeName || fallbackSyncInfo.wipeName || '',
    wipeStatus: fallbackSyncInfo.wipeStatus || cached?.battlemetricsWipeStatus || '',
    serverName: cached?.battlemetricsServerName || fallbackSyncInfo.serverName || '',
    battlemetricsPlayerId: cached?.battlemetricsPlayerId || '',
    battlemetricsServerId: cachedServerId,
    lastOnlineAt: cached?.battlemetricsLastOnlineAt || '',
    lastOfflineAt: cached?.battlemetricsLastOfflineAt || '',
    serverPlayTimeSeconds: Number.isFinite(serverSeconds) ? serverSeconds : 0,
    serverPlayTimeMinutes: Number.isFinite(serverSeconds) ? Math.round(serverSeconds / 60) : 0,
    totalPlayTimeSeconds: Number.isFinite(totalSeconds) ? totalSeconds : 0,
    totalPlayTimeMinutes: Number.isFinite(totalSeconds) ? Math.round(totalSeconds / 60) : 0,
    weeklyPlayTimeSeconds: Number.isFinite(weeklySeconds) ? weeklySeconds : 0,
    weeklyPlayTimeMinutes: Number.isFinite(weeklySeconds) ? Math.round(weeklySeconds / 60) : 0,
    syncedAt: cached?.battlemetricsSyncedAt || '',
    error: cached?.battlemetricsError || '',
    matchConfidence: cached?.battlemetricsMatchConfidence || '',
    matchAlias: cached?.battlemetricsMatchAlias || '',
    matchNotes: cached?.battlemetricsMatchNotes || '',
    matchFirstSeenAt: cached?.battlemetricsMatchFirstSeenAt || '',
    matchLastSeenAt: cached?.battlemetricsMatchLastSeenAt || '',
    matchServerTimePlayedSeconds: Number(cached?.battlemetricsMatchServerTimePlayedSeconds || 0),
    partial: Boolean(cached?.battlemetricsSessionTruncated),
    sessionTruncated: Boolean(cached?.battlemetricsSessionTruncated),
    sessionFetchedPages: Number(cached?.battlemetricsSessionFetchedPages || 0),
    sessionPageLimit: Number(cached?.battlemetricsSessionPageLimit || 0),
    rangeStopAt: cached?.battlemetricsRangeStopAt || ''
  };
}

function onlineMinutesFromSummary(summary = {}) {
  const explicitMinutes = Number(summary.onlineTimeMinutes || 0);
  if (Number.isFinite(explicitMinutes) && explicitMinutes > 0) return explicitMinutes;
  const serverMinutes = Number(summary.serverPlayTimeMinutes || 0);
  if (Number.isFinite(serverMinutes) && serverMinutes > 0) return serverMinutes;
  const serverSeconds = Number(summary.serverPlayTimeSeconds || 0);
  if (Number.isFinite(serverSeconds) && serverSeconds > 0) return Math.round(serverSeconds / 60);
  const weeklyMinutes = Number(summary.weeklyPlayTimeMinutes || 0);
  if (Number.isFinite(weeklyMinutes) && weeklyMinutes > 0) return weeklyMinutes;
  const weeklySeconds = Number(summary.weeklyPlayTimeSeconds || 0);
  if (Number.isFinite(weeklySeconds) && weeklySeconds > 0) return Math.round(weeklySeconds / 60);
  return 0;
}

function kdaOnlineSummary(store, member) {
  const summary = member?.onlineSummary || memberOnlineSummary(store, member);
  const weeklyMinutes = Number(summary?.weeklyPlayTimeMinutes ?? Math.round(Number(summary?.weeklyPlayTimeSeconds || 0) / 60));
  return {
    ...summary,
    weeklyPlayTimeMinutes: Number.isFinite(weeklyMinutes) ? weeklyMinutes : 0
  };
}

function kdaRowOnlineSummary(store, row, member, wipe = null) {
  const rowSummary = row?.onlineSummary || null;
  const kdaWipe = wipe || (row?.wipeId ? store.wipes.find((item) => item.id === row.wipeId) : null);
  if (kdaRowOnlineSummaryTrustedForWipe(row, kdaWipe)) {
    return rowSummary || {};
  }
  const fallback = kdaOnlineSummary(store, member);
  if (battlemetricsOnlineSummaryTrustedForWipe(fallback, kdaWipe)) return fallback;
  return {};
}

function kdaProfileTimeFields(store, wipe, member) {
  if (!member) return {};
  const cached = (store.memberProfiles || []).find((item) => item.memberId === member.id) || null;
  const playTimeMinutes = Number(cached?.playTimeMinutes || 0);
  const summary = memberOnlineSummary(store, member);
  const serverOnline = memberServerOnlinePayload(store, member, wipe);
  const onlineTimeMinutes = Number(serverOnline?.onlineTimeMinutes || 0);
  const fields = {};
  if (Number.isFinite(playTimeMinutes) && playTimeMinutes > 0) fields.playTimeMinutes = playTimeMinutes;
  if (Number.isFinite(onlineTimeMinutes) && onlineTimeMinutes > 0) {
    fields.onlineTimeMinutes = onlineTimeMinutes;
    fields.onlineSummary = {
      wipeId: serverOnline.wipeId || '',
      wipeName: serverOnline.wipeName || '',
      wipeStatus: serverOnline.wipeStatus || '',
      serverName: serverOnline.serverName || '',
      battlemetricsPlayerId: member.battlemetricsId || summary.battlemetricsPlayerId || '',
      battlemetricsServerId: serverOnline.battlemetricsServerId || '',
      lastOnlineAt: serverOnline.lastOnlineAt || '',
      lastOfflineAt: serverOnline.lastOfflineAt || '',
      serverPlayTimeSeconds: Number(serverOnline.onlineTimeSeconds || 0),
      serverPlayTimeMinutes: onlineTimeMinutes,
      weeklyPlayTimeSeconds: Number(serverOnline.weeklyPlayTimeSeconds || 0),
      weeklyPlayTimeMinutes: Number(serverOnline.weeklyPlayTimeMinutes || 0),
      syncedAt: serverOnline.syncedAt || '',
      error: serverOnline.error || '',
      matchConfidence: summary.matchConfidence || '',
      matchAlias: summary.matchAlias || '',
      matchNotes: summary.matchNotes || '',
      matchFirstSeenAt: summary.matchFirstSeenAt || '',
      matchLastSeenAt: summary.matchLastSeenAt || '',
      matchServerTimePlayedSeconds: Number(summary.matchServerTimePlayedSeconds || 0),
      partial: Boolean(summary.partial || summary.sessionTruncated),
      sessionTruncated: Boolean(summary.sessionTruncated),
      sessionFetchedPages: Number(summary.sessionFetchedPages || 0),
      sessionPageLimit: Number(summary.sessionPageLimit || 0),
      rangeStopAt: summary.rangeStopAt || ''
    };
  }
  return fields;
}

function kdaDataFreshness(rows = []) {
  const latestMs = rows.reduce((latest, row) => {
    const time = timestampForSort(row?.capturedAt || row?.syncedAt || row?.updatedAt || row?.createdAt);
    return Math.max(latest, time);
  }, 0);
  return {
    syncedAt: latestMs ? new Date(latestMs).toISOString() : '',
    rowCount: rows.length
  };
}

function memberPlaySummary(store, memberId) {
  const activeWipe = currentWipe(store);
  const currentParticipant = activeWipe && isWipeStartedServer(activeWipe)
    ? store.wipeParticipants.find((item) => item.wipeId === activeWipe.id && item.memberId === memberId && isParticipantAvailable(item.status))
    : null;
  if (currentParticipant) {
    return {
      playStatus: 'playing',
      isPlayingCurrentWipe: true,
      currentWipeId: activeWipe.id,
      lastPlayedAt: '',
      lastPlayedWipeName: ''
    };
  }

  const closedWipesById = new Map(store.wipes.filter((wipe) => wipe.status === 'closed').map((wipe) => [wipe.id, wipe]));
  const lastPlayed = store.wipeParticipants
    .filter((item) => item.memberId === memberId && isParticipantAvailable(item.status))
    .map((item) => {
      const wipe = closedWipesById.get(item.wipeId);
      return wipe ? { participant: item, wipe } : null;
    })
    .filter(Boolean)
    .sort((a, b) => timestampForSort(b.wipe.closedAt || b.wipe.updatedAt || b.wipe.startedAt) - timestampForSort(a.wipe.closedAt || a.wipe.updatedAt || a.wipe.startedAt))[0];

  return {
    playStatus: lastPlayed ? 'last_played' : 'never_played',
    isPlayingCurrentWipe: false,
    currentWipeId: '',
    lastPlayedAt: lastPlayed?.wipe.closedAt || lastPlayed?.wipe.updatedAt || lastPlayed?.wipe.startedAt || '',
    lastPlayedWipeName: expandVitalRustName(lastPlayed?.wipe.name || '')
  };
}

function enrichSquadMembers(store, squadId, viewer) {
  return squadMemberListPayload(store, squadId, viewer).members;
}

function squadMemberListPayload(store, squadId, viewer, query = {}) {
  const params = memberListQueryParams(query);
  const indexes = getStoreIndexes(store);
  const memberIds = new Set(store.squadMembers.filter((item) => item.squadId === squadId).map((item) => item.memberId));
  const squadMembers = store.members.filter((member) => memberIds.has(member.id));
  const total = squadMembers.length;
  const pageMembers = params.hasLimit ? squadMembers.slice(params.offset, params.offset + params.limit) : squadMembers;
  const limit = params.hasLimit ? params.limit : total;
  const members = enrichMembers(store, viewer, pageMembers, indexes)
    .map((member) => ({
      ...member,
      ...memberPlaySummary(store, member.id)
    }));
  return {
    members,
    total,
    offset: params.hasLimit ? params.offset : 0,
    limit,
    hasMore: params.hasLimit && params.offset + pageMembers.length < total
  };
}

function visibleSquads(store, user) {
  if (canViewModuleInStore(store, user, 'squads')) return activeSquads(store);
  if (canViewOperationalData(user, store)) return activeSquads(store);
  if (isLeader(user)) return activeSquads(store);
  return leaderSquads(store, user);
}

function requestedSquadFilterIds(filters = {}) {
  const rawValues = [];
  if (Array.isArray(filters.squadIds)) {
    rawValues.push(...filters.squadIds);
  } else if (filters.squadIds) {
    rawValues.push(...String(filters.squadIds).split(','));
  }
  if (filters.scope === 'squad' && filters.squadId) {
    rawValues.push(filters.squadId);
  }
  return [...new Set(rawValues.map((value) => normalizeText(value, 80)).filter(Boolean))];
}

function visibleSquadSelection(store, user, filters = {}, allowedSquads = null) {
  const requestedIds = requestedSquadFilterIds(filters);
  const allowedIds = new Set((allowedSquads || visibleSquads(store, user)).map((squad) => squad.id));
  return {
    requested: requestedIds.length > 0,
    ids: new Set(requestedIds.filter((id) => allowedIds.has(id)))
  };
}

function candidateMembersForSquad(store, user, squad) {
  const squadByMember = memberSquadMap(store);
  return enrichMembers(store, user).filter((member) => {
    const current = squadByMember.get(member.id);
    if (current?.squadId === squad.id) return false;
    if (isAdmin(user)) return true;
    if (canEditModuleInStore(store, user, 'squads')) return true;
    if (current && current.squadId !== squad.id) return false;
    return canManageMemberInStore(store, user, member);
  });
}

function assignableSquads(store, user) {
  if (canEditModuleInStore(store, user, 'members') || canEditModuleInStore(store, user, 'squads')) return activeSquads(store);
  return leaderSquads(store, user);
}

function canAssignMemberSquad(store, user, member, squadId) {
  if (!squadId) return canEditModuleInStore(store, user, 'members') || canManageMemberInStore(store, user, member);
  const squad = activeSquadById(store, squadId);
  if (!squad) return false;
  if (canEditModuleInStore(store, user, 'members') || canEditModuleInStore(store, user, 'squads')) return true;
  return isSquadLeader(user, squad) && canManageMemberInStore(store, user, member);
}

function setMemberSquad(store, member, squadId, user) {
  const requestedSquadId = normalizeText(squadId, 80);
  if (requestedSquadId && !activeSquadById(store, requestedSquadId)) {
    throw Object.assign(new Error('队伍不存在'), { status: 404 });
  }
  if (!canAssignMemberSquad(store, user, member, requestedSquadId)) {
    throw Object.assign(new Error('无权分配该队伍'), { status: 403 });
  }
  store.squadMembers = store.squadMembers.filter((item) => item.memberId !== member.id);
  if (requestedSquadId) {
    store.squadMembers.push({
      id: createId('squad_member'),
      squadId: requestedSquadId,
      memberId: member.id,
      addedByUserId: user.id,
      createdAt: nowIso()
    });
  }
  syncLiveMemberWipeSquadRecords(store, [member], requestedSquadId);
}

function liveWipeIdSet(store) {
  return new Set((store.wipes || [])
    .filter((wipe) => wipe.status !== 'closed')
    .map((wipe) => wipe.id));
}

function removeLiveMemberWipeRecords(store, targets) {
  store.wipeParticipants ||= [];
  store.kdaRows ||= [];
  store.kdaSnapshots ||= [];
  const deleteScope = liveMemberDeleteScope(targets);
  if (!deleteScope.memberIds.size && !deleteScope.steamIds.size) return { participants: 0, kdaRows: 0, kdaSnapshots: 0 };
  const liveWipeIds = liveWipeIdSet(store);
  const keepLiveMemberRecord = (item) => !liveWipeIds.has(item.wipeId) || !liveMemberRecordMatchesDeleteScope(item, deleteScope);
  const beforeParticipants = store.wipeParticipants.length;
  const beforeKdaRows = store.kdaRows.length;
  const beforeKdaSnapshots = store.kdaSnapshots.length;
  store.wipeParticipants = store.wipeParticipants.filter(keepLiveMemberRecord);
  store.kdaRows = store.kdaRows.filter(keepLiveMemberRecord);
  store.kdaSnapshots = store.kdaSnapshots.filter(keepLiveMemberRecord);
  return {
    participants: beforeParticipants - store.wipeParticipants.length,
    kdaRows: beforeKdaRows - store.kdaRows.length,
    kdaSnapshots: beforeKdaSnapshots - store.kdaSnapshots.length
  };
}

function syncLiveMemberWipeSquadRecords(store, targets, squadId) {
  store.wipeParticipants ||= [];
  store.kdaRows ||= [];
  store.kdaSnapshots ||= [];
  const deleteScope = liveMemberDeleteScope(targets);
  const targetIds = deleteScope.memberIds;
  if (!targetIds.size && !deleteScope.steamIds.size) return { participants: 0, kdaRows: 0, kdaSnapshots: 0 };
  const nextSquadId = normalizeText(squadId, 80);
  if (!nextSquadId) return removeLiveMemberWipeRecords(store, deleteScope);
  const liveWipeIds = liveWipeIdSet(store);
  const timestamp = nowIso();
  const syncRow = (row) => {
    if (!targetIds.has(row.memberId) || !liveWipeIds.has(row.wipeId)) return false;
    if (row.squadId === nextSquadId) return false;
    row.squadId = nextSquadId;
    row.updatedAt = timestamp;
    return true;
  };
  return {
    participants: (store.wipeParticipants || []).filter(syncRow).length,
    kdaRows: (store.kdaRows || []).filter(syncRow).length,
    kdaSnapshots: (store.kdaSnapshots || []).filter(syncRow).length
  };
}

function reconcileLiveMemberWipeSquadRecords(store) {
  store.wipeParticipants ||= [];
  store.kdaRows ||= [];
  store.kdaSnapshots ||= [];
  const liveWipeIds = liveWipeIdSet(store);
  if (!liveWipeIds.size) return { removed: { participants: 0, kdaRows: 0, kdaSnapshots: 0 }, synced: 0 };
  const membersById = new Map((store.members || []).map((member) => [member.id, member]));
  const memberIds = new Set(membersById.keys());
  const memberSteamIds = new Set((store.members || []).map((member) => normalizeText(member.steamId, 32)).filter(Boolean));
  const squadByMember = memberSquadMap(store);
  const removeTargets = [];
  let synced = 0;
  for (const participant of store.wipeParticipants || []) {
    if (!liveWipeIds.has(participant.wipeId)) continue;
    const currentSquadId = memberIds.has(participant.memberId) ? (squadByMember.get(participant.memberId)?.squadId || '') : '';
    if (!currentSquadId) {
      removeTargets.push({ memberId: participant.memberId });
      continue;
    }
    if (participant.squadId !== currentSquadId) {
      participant.squadId = currentSquadId;
      participant.updatedAt = nowIso();
      synced += 1;
    }
  }
  for (const row of [...(store.kdaRows || []), ...(store.kdaSnapshots || [])]) {
    if (!liveWipeIds.has(row.wipeId)) continue;
    const rowMemberId = normalizeText(row.memberId, 120);
    const rowSteamId = normalizeText(row.steamId || row.member?.steamId, 32);
    if (rowMemberId && !memberIds.has(rowMemberId)) {
      removeTargets.push({ memberId: rowMemberId });
    } else if (!rowMemberId && rowSteamId && !memberSteamIds.has(rowSteamId)) {
      removeTargets.push({ steamId: rowSteamId });
    }
  }
  const removed = removeLiveMemberWipeRecords(store, removeTargets);
  for (const row of [...(store.kdaRows || []), ...(store.kdaSnapshots || [])]) {
    if (!liveWipeIds.has(row.wipeId)) continue;
    const currentSquadId = squadByMember.get(row.memberId)?.squadId || '';
    if (currentSquadId && row.squadId !== currentSquadId) {
      row.squadId = currentSquadId;
      row.updatedAt = nowIso();
      synced += 1;
    }
  }
  return { removed, synced };
}

function collectionPatchFromBeforeAfter(before = [], after = []) {
  const beforeById = new Map((before || []).map((item) => [item.id || item.key, item]).filter(([id]) => Boolean(id)));
  const afterById = new Map((after || []).map((item) => [item.id || item.key, item]).filter(([id]) => Boolean(id)));
  const deletedIds = [...beforeById.keys()].filter((id) => !afterById.has(id));
  const updated = [...afterById.values()].filter((item) => {
    const previous = beforeById.get(item.id || item.key);
    return previous && (previous.squadId !== item.squadId || previous.updatedAt !== item.updatedAt);
  });
  return { updated, deletedIds };
}

async function reconcileLiveMemberWipeSquadRecordsOnStartup() {
  if (!sqlitePrimaryMode()) {
    return updateStore((store) => {
      reconcileLiveMemberWipeSquadRecords(store);
    });
  }

  return runStoreWriteTask(async () => {
    const [activeWipes, plannedWipes, missingStatusWipes] = await Promise.all([
      getSqliteRecordsByJsonField('wipes', 'status', ['active'], { limit: 0 }),
      getSqliteRecordsByJsonField('wipes', 'status', ['planned'], { limit: 0 }),
      getSqliteRecordsWhereJsonFieldMissing('wipes', 'status', { limit: 0 })
    ]);
    const wipes = mergeRecordsById(activeWipes, plannedWipes, missingStatusWipes);
    const liveWipeIds = [...liveWipeIdSet({ wipes })];
    const [wipeParticipants, kdaRows, kdaSnapshots] = liveWipeIds.length
      ? await Promise.all([
          getSqliteRecordsByJsonField('wipeParticipants', 'wipeId', liveWipeIds, { limit: 0 }),
          getSqliteRecordsByJsonField('kdaRows', 'wipeId', liveWipeIds, { limit: 0 }),
          getSqliteRecordsByJsonField('kdaSnapshots', 'wipeId', liveWipeIds, { limit: 0 })
        ])
      : [[], [], []];
    const scopedMemberIds = uniqueNormalizedTexts([
      ...wipeParticipants.map((item) => item.memberId),
      ...kdaRows.map((item) => item.memberId),
      ...kdaSnapshots.map((item) => item.memberId)
    ], 120);
    const scopedSteamIds = uniqueNormalizedTexts([
      ...kdaRows.map((item) => item.steamId || item.member?.steamId),
      ...kdaSnapshots.map((item) => item.steamId || item.member?.steamId)
    ], 80);
    const [membersById, membersBySteamId] = await Promise.all([
      scopedMemberIds.length ? readSqliteRecordsByIds('members', scopedMemberIds) : Promise.resolve([]),
      scopedSteamIds.length ? getSqliteRecordsByJsonField('members', 'steamId', scopedSteamIds, { limit: 0 }) : Promise.resolve([])
    ]);
    const members = mergeRecordsById(membersById, membersBySteamId);
    const existingMemberIds = uniqueNormalizedTexts(members.map((member) => member.id), 120);
    const squadMembers = existingMemberIds.length
      ? await getSqliteRecordsByJsonField('squadMembers', 'memberId', existingMemberIds, { limit: 0 })
      : [];
    const beforeWipeParticipants = cloneRecordsForPatch(wipeParticipants);
    const beforeKdaRows = cloneRecordsForPatch(kdaRows);
    const beforeKdaSnapshots = cloneRecordsForPatch(kdaSnapshots);
    const store = { members, squadMembers, wipes, wipeParticipants, kdaRows, kdaSnapshots };
    const result = reconcileLiveMemberWipeSquadRecords(store);
    const changed = Number(result?.synced || 0) +
      Number(result?.removed?.participants || 0) +
      Number(result?.removed?.kdaRows || 0) +
      Number(result?.removed?.kdaSnapshots || 0);
    if (!changed) return result;

    const participantsPatch = collectionPatchFromBeforeAfter(beforeWipeParticipants, store.wipeParticipants);
    const kdaRowsPatch = collectionPatchFromBeforeAfter(beforeKdaRows, store.kdaRows);
    const kdaSnapshotsPatch = collectionPatchFromBeforeAfter(beforeKdaSnapshots, store.kdaSnapshots);
    await writeSqliteStorePatch({
      reason: 'live_member_wipe_squad_startup_reconcile',
      upserts: {
        ...(participantsPatch.updated.length ? { wipeParticipants: participantsPatch.updated } : {}),
        ...(kdaRowsPatch.updated.length ? { kdaRows: kdaRowsPatch.updated } : {}),
        ...(kdaSnapshotsPatch.updated.length ? { kdaSnapshots: kdaSnapshotsPatch.updated } : {})
      },
      deletes: {
        ...(participantsPatch.deletedIds.length ? { wipeParticipants: participantsPatch.deletedIds } : {}),
        ...(kdaRowsPatch.deletedIds.length ? { kdaRows: kdaRowsPatch.deletedIds } : {}),
        ...(kdaSnapshotsPatch.deletedIds.length ? { kdaSnapshots: kdaSnapshotsPatch.deletedIds } : {})
      }
    });
    await patchStoreCache((cachedStore) => {
      const applyCollectionPatch = (collection, patch) => {
        cachedStore[collection] ||= [];
        if (patch.deletedIds.length) {
          const deleted = new Set(patch.deletedIds);
          cachedStore[collection] = cachedStore[collection].filter((item) => !deleted.has(item.id || item.key));
        }
        for (const item of patch.updated) replaceCachedRecord(cachedStore[collection], item);
      };
      applyCollectionPatch('wipeParticipants', participantsPatch);
      applyCollectionPatch('kdaRows', kdaRowsPatch);
      applyCollectionPatch('kdaSnapshots', kdaSnapshotsPatch);
    });
    return result;
  });
}

function removeMemberRuntimeRecords(store, targets) {
  const deleteScope = liveMemberDeleteScope(targets);
  const deleteIds = deleteScope.memberIds;
  store.squadMembers = store.squadMembers.filter((item) => !deleteIds.has(item.memberId));
  removeLiveMemberWipeRecords(store, deleteScope);
  store.memberProfiles = store.memberProfiles.filter((item) => !deleteIds.has(item.memberId));
  store.accountAlertDismissals = (store.accountAlertDismissals || []).filter((item) => !deleteIds.has(item.memberId));
  cleanupMemberLinkedAccounts(store, deleteScope);
}

function cleanupMemberLinkedAccounts(store, deleteScope = {}) {
  const steamIds = deleteScope.steamIds || new Set();
  if (!steamIds.size) return { deletedUserIds: [], unboundUserIds: [] };
  const deletedUserIds = [];
  store.users = (store.users || []).filter((user) => {
    const boundSteamId = normalizeText(user.boundSteamId, 80);
    if (!boundSteamId || !steamIds.has(boundSteamId) || isRootUser(user) || !isMember(user)) return true;
    deletedUserIds.push(user.id);
    return false;
  });
  if (deletedUserIds.length) {
    const deleted = new Set(deletedUserIds);
    store.sessions = (store.sessions || []).filter((session) => !deleted.has(session.userId));
  }
  return { deletedUserIds, unboundUserIds: [] };
}

function cleanupOrphanMemberAccounts(store) {
  const memberSteamIds = new Set((store.members || [])
    .map((member) => normalizeText(member.steamId, 80))
    .filter(Boolean));
  const deletedUserIds = [];
  const deletedUsernames = [];
  store.users = (store.users || []).filter((user) => {
    const boundSteamId = normalizeText(user.boundSteamId, 80);
    if (!boundSteamId || memberSteamIds.has(boundSteamId) || isRootUser(user) || !isMember(user)) return true;
    deletedUserIds.push(user.id);
    deletedUsernames.push(normalizeText(user.username, 128) || user.id);
    return false;
  });
  if (deletedUserIds.length) {
    const deleted = new Set(deletedUserIds);
    store.sessions = (store.sessions || []).filter((session) => !deleted.has(session.userId));
  }
  return {
    deleted: deletedUserIds.length,
    deletedUserIds,
    deletedUsernames
  };
}

function normalizeWipeDateTimeInput(value) {
  const text = normalizeText(value, 80);
  if (!text) return '';
  const time = Date.parse(text);
  return Number.isFinite(time) ? new Date(time).toISOString() : '';
}

function normalizeClientTimeZone(body = {}) {
  return normalizeText(body?.timeZone || body?.browserTimeZone || body?.clientTimeZone, 80);
}

function effectiveWipeStatus(wipe, nowMs = Date.now()) {
  if (!wipe) return '';
  if (wipe.status === 'closed') return 'closed';
  return isWipeStartedServer(wipe, nowMs) ? 'active' : 'planned';
}

function shouldPromoteStartedWipeToCurrent(wipe, nowMs = Date.now()) {
  if (!wipe || wipe.status === 'closed' || !isWipeStartedServer(wipe, nowMs)) return false;
  const mode = normalizeText(wipe.wipeMode, 40).toLowerCase();
  const label = normalizeText(wipe.wipeLabel, 120).toLowerCase();
  return mode === 'next' || mode === 'planned' || label === 'next' || label === 'planned';
}

function hasStartedWipesToPromote(store, nowMs = Date.now()) {
  return (store.wipes || []).some((wipe) => shouldPromoteStartedWipeToCurrent(wipe, nowMs));
}

function promoteStartedWipesToCurrent(store, { nowMs = Date.now(), req = null } = {}) {
  const promotedAt = nowIso();
  let promoted = 0;
  for (const wipe of store.wipes || []) {
    if (!shouldPromoteStartedWipeToCurrent(wipe, nowMs)) continue;
    const previousWipeMode = wipe.wipeMode || '';
    const previousWipeLabel = wipe.wipeLabel || '';
    wipe.wipeMode = 'current';
    wipe.wipeLabel = 'Current';
    wipe.updatedAt = promotedAt;
    promoted += 1;
    appendLog(store, req, 'wipe_auto_current', `自动切换当前 Wipe ${wipe.name}`, {
      actorUserId: 'system',
      actorUsername: 'system',
      targetId: wipe.id,
      metadata: {
        previousWipeMode,
        previousWipeLabel,
        startedAt: wipe.startedAt || '',
        promotedAt
      }
    });
  }
  return promoted;
}

async function promoteStartedWipesToCurrentDirect(req = null, nowMs = Date.now()) {
  return runStoreWriteTask(async () => {
    const wipes = await getSqliteRecordsByJsonField('wipes', 'status', ['active', 'planned'], { limit: 0 });
    const promotedAt = nowIso();
    const updatedWipes = [];
    const createdLogs = [];
    for (const wipe of wipes || []) {
      if (!shouldPromoteStartedWipeToCurrent(wipe, nowMs)) continue;
      const previousWipeMode = wipe.wipeMode || '';
      const previousWipeLabel = wipe.wipeLabel || '';
      const nextWipe = {
        ...wipe,
        wipeMode: 'current',
        wipeLabel: 'Current',
        updatedAt: promotedAt
      };
      updatedWipes.push(nextWipe);
      createdLogs.push(createLogEntry(req, 'wipe_auto_current', `自动切换当前 Wipe ${nextWipe.name}`, {
        actorUserId: 'system',
        actorUsername: 'system',
        targetId: nextWipe.id,
        metadata: {
          previousWipeMode,
          previousWipeLabel,
          startedAt: nextWipe.startedAt || '',
          promotedAt
        }
      }));
    }
    if (!updatedWipes.length) return 0;

    const patchResult = await writeSqliteStorePatch({
      reason: 'wipe_auto_current',
      upserts: {
        wipes: updatedWipes,
        logs: createdLogs
      },
      trims: logTrimPatch()
    });
    await patchStoreCache((store) => {
      store.wipes ||= [];
      for (const wipe of updatedWipes) replaceCachedRecord(store.wipes, wipe);
      applyCachedLogPatch(store, createdLogs, trimmedLogIds(patchResult));
    });
    return updatedWipes.length;
  });
}

async function promoteStartedWipesToCurrentIfNeeded(req = null) {
  const nowMs = Date.now();
  if (sqlitePrimaryMode()) {
    try {
      return await promoteStartedWipesToCurrentDirect(req, nowMs);
    } catch (error) {
      console.warn('[nb-clan] sqlite wipe promotion direct failed:', error?.message || error);
      return 0;
    }
  }
  if (sqliteEnabled()) {
    try {
      const wipes = await getSqliteRecordsByJsonField('wipes', 'status', ['active', 'planned'], { limit: 0 });
      if (!wipes.some((wipe) => shouldPromoteStartedWipeToCurrent(wipe, nowMs))) return 0;
    } catch (error) {
      console.warn('[nb-clan] sqlite wipe promotion fallback:', error?.message || error);
      const snapshot = await readStore();
      if (!hasStartedWipesToPromote(snapshot, nowMs)) return 0;
    }
  } else {
    const snapshot = await readStore();
    if (!hasStartedWipesToPromote(snapshot, nowMs)) return 0;
  }
  return updateStore((store) => promoteStartedWipesToCurrent(store, { nowMs, req }));
}

async function promoteAndRefreshStartedWipeVitalMetadata(req = null) {
  const promoted = await promoteStartedWipesToCurrentIfNeeded(req);
  try {
    await refreshStartedWipeVitalMetadataIfNeeded('current', req);
  } catch (error) {
    console.warn('[nb-clan] wipe vital metadata background refresh failed:', error?.message || error);
  }
  return promoted;
}

const VITAL_WIPE_START_MATCH_TOLERANCE_MS = 2 * 60 * 60 * 1000;
const VITAL_WIPE_METADATA_REFRESH_INTERVAL_MS = 5 * 60 * 1000;
const vitalWipeMetadataRefreshAt = new Map();

function remoteVitalWipeMatchesStartedWipe(wipe, remoteWipe) {
  const localStartMs = Date.parse(wipe?.startedAt || '');
  const remoteStartMs = Date.parse(remoteWipe?.startTime || '');
  if (!Number.isFinite(localStartMs) || !Number.isFinite(remoteStartMs)) return false;
  return Math.abs(remoteStartMs - localStartMs) <= VITAL_WIPE_START_MATCH_TOLERANCE_MS;
}

function activeVitalWipes(wipes = []) {
  return (wipes || [])
    .filter((wipe) => wipe && !wipe.endTime)
    .toSorted((left, right) => (
      timestampForSort(right.startTime) - timestampForSort(left.startTime)
    ));
}

function kdaRecordUsesVitalWipe(record = {}) {
  return record.source === 'vital' || record.source === 'local_demo';
}

function kdaRecordMatchesVitalWipe(record = {}, wipe = {}) {
  if (!kdaRecordUsesVitalWipe(record)) return true;
  if (record.source !== 'vital') return true;
  const recordVitalWipeId = normalizeText(record.vitalWipeId, 120);
  const currentVitalWipeId = normalizeText(wipe.vitalWipeId, 120);
  if (!currentVitalWipeId) return false;
  return !recordVitalWipeId || recordVitalWipeId === currentVitalWipeId;
}

function selectActiveVitalWipe(wipes = [], localWipe = null, now = new Date()) {
  const normalized = normalizeVitalWipes(wipes, {
    serverId: localWipe?.vitalServerId || '',
    now
  });
  const active = activeVitalWipes(normalized);
  if (!localWipe) return active[0] || null;

  const newestActiveWipe = active[0] || null;
  if (!newestActiveWipe) return null;
  const newestActiveWipeId = normalizeText(newestActiveWipe.id, 120);
  const existingVitalWipeId = normalizeText(localWipe.vitalWipeId, 120);
  if (existingVitalWipeId && newestActiveWipeId === existingVitalWipeId) return newestActiveWipe;

  const existingRemoteWipe = existingVitalWipeId
    ? normalized.find((remoteWipe) => normalizeText(remoteWipe.id, 120) === existingVitalWipeId)
    : null;
  const existingBoundStartMs = Date.parse(
    localWipe.vitalWipeStartedAt || existingRemoteWipe?.startTime || localWipe.startedAt || ''
  );
  const matchingWipe = active.find((remoteWipe) => remoteVitalWipeMatchesStartedWipe(localWipe, remoteWipe));
  if (matchingWipe) {
    const matchingStartMs = Date.parse(matchingWipe.startTime || '');
    if (!existingVitalWipeId || !Number.isFinite(existingBoundStartMs) || matchingStartMs >= existingBoundStartMs) {
      return matchingWipe;
    }
    return null;
  }

  const newestStartMs = Date.parse(newestActiveWipe.startTime || '');
  const localStartMs = Date.parse(localWipe.startedAt || '');
  if (!Number.isFinite(newestStartMs)) return null;
  if (
    Number.isFinite(localStartMs)
    && newestStartMs + VITAL_WIPE_START_MATCH_TOLERANCE_MS < localStartMs
  ) {
    return null;
  }

  if (existingVitalWipeId && Number.isFinite(existingBoundStartMs) && newestStartMs <= existingBoundStartMs) {
    return null;
  }
  return newestActiveWipe;
}

function vitalMetadataPatchForStartedWipe(wipe, remoteWipe = null, options = {}) {
  if (!wipe || wipe.status === 'closed' || !isWipeStartedServer(wipe)) return {};
  const vitalServerId = normalizeText(wipe.vitalServerId, 80);
  if (!vitalServerId) return {};

  const existingVitalWipeId = normalizeText(wipe.vitalWipeId, 120);
  const remoteVitalWipeId = normalizeText(remoteWipe?.id, 120);
  const remoteVitalWipeStartedAtMs = Date.parse(remoteWipe?.startTime || '');
  const remoteVitalWipeStartedAt = Number.isFinite(remoteVitalWipeStartedAtMs)
    ? new Date(remoteVitalWipeStartedAtMs).toISOString()
    : '';
  const existingVitalWipeStartedAtMs = Date.parse(wipe.vitalWipeStartedAt || '');
  const patch = {};

  if (options.clearStaleVitalWipeId && existingVitalWipeId) {
    patch.vitalWipeId = '';
    patch.kdaUrl = '';
  } else if (remoteVitalWipeId && remoteVitalWipeId !== existingVitalWipeId) {
    patch.vitalWipeId = remoteVitalWipeId;
  }
  if (
    remoteVitalWipeId
    && remoteVitalWipeStartedAt
    && remoteVitalWipeStartedAt !== normalizeText(wipe.vitalWipeStartedAt, 80)
    && (
      remoteVitalWipeId !== existingVitalWipeId
      || !Number.isFinite(existingVitalWipeStartedAtMs)
      || remoteVitalWipeStartedAtMs >= existingVitalWipeStartedAtMs
    )
  ) {
    patch.vitalWipeStartedAt = remoteVitalWipeStartedAt;
  }
  const vitalWipeId = Object.hasOwn(patch, 'vitalWipeId')
    ? patch.vitalWipeId
    : (existingVitalWipeId || remoteVitalWipeId);

  const kdaUrl = buildKdaUrl(vitalServerId, vitalWipeId);
  if (kdaUrl && (!normalizeText(wipe.kdaUrl, 500) || Object.hasOwn(patch, 'vitalWipeId'))) patch.kdaUrl = kdaUrl;

  const remoteMapUrl = normalizeText(remoteWipe?.mapUrl, 500);
  if (remoteMapUrl && (!normalizeText(wipe.mapLink, 500) || patch.vitalWipeId)) patch.mapLink = remoteMapUrl;

  const remoteMapSize = normalizeText(remoteWipe?.mapSize, 40);
  if (remoteMapSize && (!normalizeText(wipe.mapSize, 40) || patch.vitalWipeId)) patch.mapSize = remoteMapSize;

  const remoteProtocol = normalizeText(remoteWipe?.protocol, 80);
  if (remoteProtocol && (!normalizeText(wipe.protocol, 80) || patch.vitalWipeId)) patch.protocol = remoteProtocol;

  return patch;
}

async function refreshStartedWipeVitalMetadataIfNeeded(wipeId = '', req = null, options = {}) {
  const normalizedWipeId = normalizeText(wipeId, 120);
  const wipe = await readWipeForVitalMetadataRefresh(normalizedWipeId);
  if (!wipe || wipe.status === 'closed' || !isWipeStartedServer(wipe)) return false;

  const vitalServerId = normalizeText(wipe.vitalServerId, 80);
  if (!vitalServerId) return false;

  const existingVitalWipeId = normalizeText(wipe.vitalWipeId, 120);
  const requestedCurrentWipe = !normalizedWipeId || normalizedWipeId === 'current';
  const selectedCurrentWipe = requestedCurrentWipe
    ? wipe
    : await readWipeForVitalMetadataRefresh('current');
  const shouldRefreshActiveStartedWipe = wipe.status === 'active'
    && isWipeStartedServer(wipe)
    && selectedCurrentWipe?.id === wipe.id;
  if (options.requireMissingVitalWipeId && existingVitalWipeId && !shouldRefreshActiveStartedWipe) return false;

  let remoteWipe = null;
  let clearStaleVitalWipeId = false;
  const lastRemoteRefreshAt = vitalWipeMetadataRefreshAt.get(wipe.id) || 0;
  const remoteRefreshDue = options.forceRemoteRefresh === true
    || Date.now() - lastRemoteRefreshAt >= VITAL_WIPE_METADATA_REFRESH_INTERVAL_MS;
  if (
    process.env.NB_DISABLE_EXTERNAL_VITAL !== '1'
    && (!existingVitalWipeId || shouldRefreshActiveStartedWipe)
    && remoteRefreshDue
  ) {
    vitalWipeMetadataRefreshAt.set(wipe.id, Date.now());
    const remoteResult = await fetchVitalWipesResult(vitalServerId, { fresh: true });
    if (remoteResult.ok) {
      const remoteWipes = normalizeVitalWipes(remoteResult.rows, { serverId: vitalServerId });
      remoteWipe = selectActiveVitalWipe(remoteWipes, wipe);
      const existingRemoteWipe = existingVitalWipeId
        ? remoteWipes.find((item) => normalizeText(item.id, 120) === existingVitalWipeId)
        : null;
      clearStaleVitalWipeId = Boolean(
        existingVitalWipeId &&
        !remoteWipe &&
        (
          !existingRemoteWipe ||
          existingRemoteWipe.endTime ||
          !remoteVitalWipeMatchesStartedWipe(wipe, existingRemoteWipe)
        )
      );
    }
  }

  const metadataOptions = { clearStaleVitalWipeId };
  const patch = vitalMetadataPatchForStartedWipe(wipe, remoteWipe, metadataOptions);
  if (!Object.keys(patch).length) return false;

  if (sqlitePrimaryMode()) {
    try {
      let resetKdaRows = 0;
      let resetKdaSnapshots = 0;
      const updatedWipe = await runStoreWriteTask(async () => {
        const current = await getSqliteRecord('wipes', wipe.id);
        const nextPatch = vitalMetadataPatchForStartedWipe(current, remoteWipe, metadataOptions);
        if (!Object.keys(nextPatch).length) return null;
        const vitalWipeChanged = Object.hasOwn(nextPatch, 'vitalWipeId')
          && normalizeText(nextPatch.vitalWipeId, 120) !== normalizeText(current.vitalWipeId, 120);
        const [wipeKdaRows, wipeKdaSnapshots] = vitalWipeChanged
          ? await Promise.all([
              getSqliteRecordsByJsonField('kdaRows', 'wipeId', [wipe.id], { limit: 0 }),
              getSqliteRecordsByJsonField('kdaSnapshots', 'wipeId', [wipe.id], { limit: 0 })
            ])
          : [[], []];
        const staleKdaRows = wipeKdaRows.filter(kdaRecordUsesVitalWipe);
        const staleKdaSnapshots = wipeKdaSnapshots.filter(kdaRecordUsesVitalWipe);
        resetKdaRows = staleKdaRows.length;
        resetKdaSnapshots = staleKdaSnapshots.length;
        const nextWipe = {
          ...current,
          ...nextPatch,
          updatedAt: nowIso()
        };
        await writeSqliteStorePatch({
          reason: 'wipe_vital_metadata_refresh',
          upserts: { wipes: [nextWipe] },
          deletes: {
            ...(staleKdaRows.length ? { kdaRows: staleKdaRows.map((row) => row.id) } : {}),
            ...(staleKdaSnapshots.length ? { kdaSnapshots: staleKdaSnapshots.map((row) => row.id) } : {})
          }
        });
        await patchStoreCache((store) => {
          store.wipes ||= [];
          replaceCachedRecord(store.wipes, nextWipe);
          if (vitalWipeChanged) {
            const staleKdaRowIds = new Set(staleKdaRows.map((row) => row.id));
            const staleKdaSnapshotIds = new Set(staleKdaSnapshots.map((row) => row.id));
            store.kdaRows = (store.kdaRows || []).filter((row) => !staleKdaRowIds.has(row.id));
            store.kdaSnapshots = (store.kdaSnapshots || []).filter((row) => !staleKdaSnapshotIds.has(row.id));
          }
        });
        return nextWipe;
      });
      if (!updatedWipe) return false;
      await appendLogDirect(req, 'wipe_vital_metadata_refresh', `自动回填 Vital Wipe 信息 ${updatedWipe.name}`, {
        actorUserId: req?.user?.id || 'system',
        actorUsername: req?.user?.username || 'system',
        targetId: updatedWipe.id,
        metadata: {
          vitalServerId: updatedWipe.vitalServerId || '',
          vitalWipeId: updatedWipe.vitalWipeId || '',
          kdaUrl: updatedWipe.kdaUrl || '',
          resetKdaRows,
          resetKdaSnapshots
        }
      });
      queueMemberRankingCardRefresh('vital-wipe-metadata-change');
      if (updatedWipe.vitalWipeId) {
        queueBackgroundTask(
          `kda-sync-vital-wipe-metadata:${updatedWipe.id}:${updatedWipe.vitalWipeId}`,
          () => syncCurrentWipeKdaInBackground(),
          0,
          { queue: 'sync' }
        ).catch(() => {});
      }
      return true;
    } catch (error) {
      console.warn('[nb-clan] sqlite wipe vital metadata refresh failed:', error?.message || error);
      return false;
    }
  }

  let changed = false;
  let updatedVitalWipeId = '';
  await updateStore((store) => {
    const current = store.wipes.find((item) => item.id === wipe.id);
    const nextPatch = vitalMetadataPatchForStartedWipe(current, remoteWipe, metadataOptions);
    if (!Object.keys(nextPatch).length) return;
    const vitalWipeChanged = Object.hasOwn(nextPatch, 'vitalWipeId')
      && normalizeText(nextPatch.vitalWipeId, 120) !== normalizeText(current.vitalWipeId, 120);
    const resetKdaRows = vitalWipeChanged
      ? store.kdaRows.filter((row) => row.wipeId === wipe.id && kdaRecordUsesVitalWipe(row)).length
      : 0;
    const resetKdaSnapshots = vitalWipeChanged
      ? store.kdaSnapshots.filter((row) => row.wipeId === wipe.id && kdaRecordUsesVitalWipe(row)).length
      : 0;
    if (vitalWipeChanged) {
      store.kdaRows = store.kdaRows.filter((row) => row.wipeId !== wipe.id || !kdaRecordUsesVitalWipe(row));
      store.kdaSnapshots = store.kdaSnapshots.filter((row) => row.wipeId !== wipe.id || !kdaRecordUsesVitalWipe(row));
    }
    Object.assign(current, nextPatch, { updatedAt: nowIso() });
    changed = true;
    updatedVitalWipeId = normalizeText(current.vitalWipeId, 120);
    appendLog(store, req, 'wipe_vital_metadata_refresh', `自动回填 Vital Wipe 信息 ${current.name}`, {
      actorUserId: req?.user?.id || 'system',
      actorUsername: req?.user?.username || 'system',
      targetId: current.id,
      metadata: {
        vitalServerId: current.vitalServerId || '',
        vitalWipeId: current.vitalWipeId || '',
        kdaUrl: current.kdaUrl || '',
        resetKdaRows,
        resetKdaSnapshots
      }
    });
  });
  if (changed) {
    queueMemberRankingCardRefresh('vital-wipe-metadata-change');
    if (updatedVitalWipeId) {
      queueBackgroundTask(
        `kda-sync-vital-wipe-metadata:${wipe.id}:${updatedVitalWipeId}`,
        () => syncCurrentWipeKdaInBackground(),
        0,
        { queue: 'sync' }
      ).catch(() => {});
    }
  }
  return changed;
}

function buildDiscordPlannedWipeDraft(store, body, req, options = {}) {
  const requestedVitalServerId = normalizeText(body?.vitalServerId, 80);
  const vitalServers = vitalServersForStore(store);
  const vitalServer = vitalServers.find((server) => server.vitalServerId === requestedVitalServerId) || vitalServers[0];
  const times = computedWipeTimes(vitalServer);
  const nowMs = Date.now();
  const requestedStartedAt = normalizeWipeDateTimeInput(body?.startedAt);
  const requestedStartedAtMs = Date.parse(requestedStartedAt);
  const useRequestedStartedAt = Number.isFinite(requestedStartedAtMs) && requestedStartedAtMs > nowMs;
  const startedAt = useRequestedStartedAt ? new Date(requestedStartedAtMs).toISOString() : times.nextStart;
  const clientTimeZone = normalizeClientTimeZone(body);
  const serverName = expandVitalRustName(normalizeText(body?.serverName, 120) || vitalServer.name);
  const vitalWipeId = useRequestedStartedAt ? normalizeText(body?.vitalWipeId, 120) : '';
  const createdAt = normalizeText(options.createdAt, 80) || nowIso();
  return {
    id: normalizeText(options.id, 80) || createId('wipe'),
    name: normalizeText(body?.name, 120) || `${serverName} ${startedAt.slice(0, 10)}`,
    status: 'active',
    serverName,
    startedAt,
    closedAt: '',
    wipeLabel: useRequestedStartedAt ? (normalizeText(body?.wipeLabel, 120) || 'Planned') : 'Planned',
    wipeMode: useRequestedStartedAt ? (normalizeText(body?.wipeMode, 40) || 'next') : 'next',
    startedAtTimeZone: clientTimeZone,
    nextWipeAt: normalizeWipeDateTimeInput(body?.nextWipeAt),
    nextWipeAtTimeZone: clientTimeZone,
    directConnect: normalizeText(body?.directConnect, 240) || vitalServer.directConnect || '',
    vipUrl: normalizeText(body?.vipUrl, 240) || vitalServer.vipUrl || '',
    mapLink: normalizeText(body?.mapLink, 500),
    rustMapsLink: normalizeText(body?.rustMapsLink, 500),
    notes: normalizeText(body?.notes, 1000),
    vitalServerId: vitalServer.vitalServerId,
    vitalWipeId,
    battlemetricsId: normalizeText(body?.battlemetricsId, 80) || vitalServer.battlemetricsId || '',
    kdaUrl: normalizeText(body?.kdaUrl, 500) || buildKdaUrl(vitalServer.vitalServerId, vitalWipeId),
    createdBy: req.user?.id || '',
    createdAt,
    updatedAt: createdAt
  };
}

function createDiscordPlannedWipe(store, body, req) {
  const wipe = buildDiscordPlannedWipeDraft(store, body, req);
  store.wipes.unshift(wipe);
  appendLog(store, req, 'wipe_create', `Auto-created Discord planned wipe ${wipe.name}`, { targetId: wipe.id });
  return wipe;
}

function sameWipeServer(left, right) {
  if (!left || !right) return false;
  if (left.vitalServerId && right.vitalServerId && String(left.vitalServerId) === String(right.vitalServerId)) return true;
  if (battlemetricsServerIdForWipe(left) && battlemetricsServerIdForWipe(left) === battlemetricsServerIdForWipe(right)) return true;
  const leftName = expandVitalRustName(left.serverName || left.name || '').toLowerCase();
  const rightName = expandVitalRustName(right.serverName || right.name || '').toLowerCase();
  return Boolean(leftName && rightName && leftName === rightName);
}

function latestClosedWipe(store, { sameServerAs = null } = {}) {
  return store.wipes
    .filter((wipe) => wipe.status === 'closed')
    .filter((wipe) => !sameServerAs || sameWipeServer(wipe, sameServerAs))
    .toSorted((left, right) => {
      const rightTime = timestampForSort(right.closedAt || right.updatedAt || right.startedAt);
      const leftTime = timestampForSort(left.closedAt || left.updatedAt || left.startedAt);
      return rightTime - leftTime;
    })[0] || null;
}

function queryReferenceWipe(store) {
  const active = currentWipe(store);
  if (active && isWipeStartedServer(active)) return active;
  return latestClosedWipe(store) || active || null;
}

function wipeHasKdaRows(store, wipe) {
  if (!store || !wipe?.id) return false;
  return (store.kdaRows || []).some((row) => row.wipeId === wipe.id);
}

function wechatRankingWipe(store) {
  const active = currentWipe(store);
  if (active && isWipeStartedServer(active) && wipeHasKdaRows(store, active)) return active;
  return latestClosedWipe(store) || active || null;
}

function latestClosedBattlemetricsWipe(store, { sameServerAs = null } = {}) {
  return store.wipes
    .filter((wipe) => wipe.status === 'closed')
    .filter((wipe) => battlemetricsServerIdForWipe(wipe))
    .filter((wipe) => !sameServerAs || sameWipeServer(wipe, sameServerAs))
    .toSorted((left, right) => {
      const rightTime = timestampForSort(right.closedAt || right.updatedAt || right.startedAt);
      const leftTime = timestampForSort(left.closedAt || left.updatedAt || left.startedAt);
      return rightTime - leftTime;
    })[0] || null;
}

function battlemetricsReferenceWipe(store, nowMs = Date.now()) {
  const active = currentWipe(store);
  if (active && isWipeStartedServer(active, nowMs) && battlemetricsServerIdForWipe(active)) return active;
  const started = store.wipes
    .filter((wipe) => wipe.status !== 'closed' && isWipeStartedServer(wipe, nowMs) && battlemetricsServerIdForWipe(wipe))
    .toSorted((left, right) => {
      const rightTime = timestampForSort(right.startedAt || right.updatedAt || right.createdAt);
      const leftTime = timestampForSort(left.startedAt || left.updatedAt || left.createdAt);
      return rightTime - leftTime;
    })[0] || null;
  if (started) return started;
  return latestClosedBattlemetricsWipe(store, { sameServerAs: active }) ||
    latestClosedBattlemetricsWipe(store) ||
    queryReferenceWipe(store);
}

function assertWipeMutable(wipe) {
  if (!wipe) throw Object.assign(new Error('档期不存在'), { status: 404 });
  if (wipe.status === 'closed') throw Object.assign(new Error('当前档已结档，不可修改'), { status: 409 });
}

function publicUpload(upload) {
  return {
    id: upload.id,
    kind: upload.kind || '',
    url: upload.url,
    originalName: upload.originalName,
    mimeType: upload.mimeType,
    size: upload.size,
    width: Number(upload.width || 0),
    height: Number(upload.height || 0),
    createdAt: upload.createdAt
  };
}

function uploadFilePath(upload) {
  const fileName = path.basename(upload?.fileName || '');
  if (!fileName || fileName !== upload.fileName) return '';
  if (upload.kind === 'team_logo') return path.join(DATA_DIR, 'uploads', 'team-logo', fileName);
  if (upload.kind === 'wechat_avatar') return path.join(DATA_DIR, 'uploads', 'wechat-avatars', fileName);
  if (upload.kind === 'server_screenshot') return path.join(DATA_DIR, 'uploads', 'server-screenshots', fileName);
  if (upload.kind === 'map_file' || upload.kind === 'map_image') return path.join(DATA_DIR, 'uploads', 'map-files', fileName);
  return '';
}

function isRustMapsWipeMapImage(upload, wipeId = '') {
  if (!upload || upload.kind !== 'map_image' || upload.ownerType !== 'wipe') return false;
  if (wipeId && upload.ownerId !== wipeId) return false;
  return upload.source === 'rustmaps' || upload.originalName === 'RustMaps full map & icons.png';
}

function imageExtensionFromContentType(contentType, imageUrl = '') {
  const type = normalizeText(contentType, 80).split(';')[0].trim().toLowerCase();
  if (type === 'image/jpeg') return '.jpg';
  if (type === 'image/webp') return '.webp';
  if (type === 'image/png') return '.png';
  const pathName = (() => {
    try {
      return new URL(imageUrl).pathname.toLowerCase();
    } catch {
      return '';
    }
  })();
  if (pathName.endsWith('.jpg') || pathName.endsWith('.jpeg')) return '.jpg';
  if (pathName.endsWith('.webp')) return '.webp';
  return '.png';
}

async function fetchRustMapsImageAsset(imageUrl) {
  const url = normalizeRustMapsContentImageUrl(imageUrl);
  if (!url) throw Object.assign(new Error('RustMaps 地图图片链接无效'), { status: 400 });
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 12000);
  try {
    const response = await nodeFetch(url, { signal: controller.signal });
    if (!response.ok) {
      throw Object.assign(new Error('RustMaps 地图图片读取失败'), { status: 502 });
    }
    const contentType = response.headers.get('content-type') || 'image/png';
    if (!String(contentType).toLowerCase().startsWith('image/')) {
      throw Object.assign(new Error('RustMaps 地图图片格式不支持'), { status: 415 });
    }
    const buffer = Buffer.from(await response.arrayBuffer());
    if (!buffer.length || buffer.length > RUSTMAPS_IMAGE_MAX_BYTES) {
      throw Object.assign(new Error('RustMaps 地图图片大小不支持'), { status: 413 });
    }
    return {
      buffer,
      mimeType: normalizeText(contentType.split(';')[0], 80) || 'image/png',
      ext: imageExtensionFromContentType(contentType, url)
    };
  } finally {
    clearTimeout(timeout);
  }
}

async function clearRustMapsImageForWipeDirect(wipeId) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedWipeId = normalizeText(wipeId, 120);
      if (!normalizedWipeId) return [];
      const [wipe, uploads] = await Promise.all([
        getSqliteRecord('wipes', normalizedWipeId),
        getSqliteRecordsByJsonField('uploads', 'ownerId', [normalizedWipeId], { limit: 0 })
      ]);
      const removedUploads = (uploads || []).filter((upload) => isRustMapsWipeMapImage(upload, normalizedWipeId));
      const wipeNeedsPatch = Boolean(wipe?.rustMapsImageUrl || wipe?.rustMapsImageSourceUrl || wipe?.rustMapsImageUpdatedAt);
      if (!removedUploads.length && !wipeNeedsPatch) return [];
      const nextWipe = wipe ? {
        ...wipe,
        rustMapsImageUrl: '',
        rustMapsImageSourceUrl: '',
        rustMapsImageUpdatedAt: ''
      } : null;
      await writeSqliteStorePatch({
        reason: 'rustmaps_image_clear',
        upserts: nextWipe ? { wipes: [nextWipe] } : {},
        deletes: removedUploads.length ? { uploads: removedUploads.map((upload) => upload.id) } : {}
      });
      await patchStoreCache((cachedStore) => {
        if (nextWipe) {
          cachedStore.wipes ||= [];
          replaceCachedRecord(cachedStore.wipes, nextWipe);
        }
        if (removedUploads.length) {
          const removedIds = new Set(removedUploads.map((upload) => upload.id));
          cachedStore.uploads = (cachedStore.uploads || []).filter((upload) => !removedIds.has(upload.id));
        }
      });
      return removedUploads;
    });
  } catch (error) {
    console.warn('[nb-clan] sqlite rustmaps image clear fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('RustMaps 图片清理写入', error);
  }
}

async function clearRustMapsImageForWipe(wipeId) {
  const directRemovedUploads = await clearRustMapsImageForWipeDirect(wipeId);
  const removedUploads = directRemovedUploads || await updateStore((store) => {
    store.uploads ||= [];
    const removed = store.uploads.filter((upload) => isRustMapsWipeMapImage(upload, wipeId));
    store.uploads = store.uploads.filter((upload) => !isRustMapsWipeMapImage(upload, wipeId));
    const wipe = store.wipes.find((item) => item.id === wipeId);
    if (wipe) {
      wipe.rustMapsImageUrl = '';
      wipe.rustMapsImageSourceUrl = '';
      wipe.rustMapsImageUpdatedAt = '';
    }
    return removed;
  });
  await Promise.all(removedUploads.map((upload) => {
    const filePath = uploadFilePath(upload);
    return filePath ? fs.unlink(filePath).catch(() => {}) : Promise.resolve();
  }));
}

async function writeRustMapsImageSyncDirect(wipeId, { rustMapsLink, upload, imageUrl, createdAt } = {}) {
  if (!sqlitePrimaryMode()) return null;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedWipeId = normalizeText(wipeId, 120);
      if (!normalizedWipeId || !upload?.id) {
        return { handled: true, removedUploads: null };
      }
      const [wipe, uploads] = await Promise.all([
        getSqliteRecord('wipes', normalizedWipeId),
        getSqliteRecordsByJsonField('uploads', 'ownerId', [normalizedWipeId], { limit: 0 })
      ]);
      if (!wipe || normalizeRustMapsMapUrl(wipe.rustMapsLink) !== rustMapsLink) {
        return { handled: true, removedUploads: null };
      }
      const removedUploads = (uploads || []).filter((item) => isRustMapsWipeMapImage(item, normalizedWipeId));
      const nextWipe = {
        ...wipe,
        rustMapsImageUrl: upload.url,
        rustMapsImageSourceUrl: imageUrl,
        rustMapsImageUpdatedAt: createdAt,
        rustMapsImageError: '',
        rustMapsImageErrorAt: ''
      };
      await writeSqliteStorePatch({
        reason: 'rustmaps_image_sync',
        upserts: {
          wipes: [nextWipe],
          uploads: [upload]
        },
        deletes: removedUploads.length ? { uploads: removedUploads.map((item) => item.id) } : {},
        positions: { uploads: { [upload.id]: 0 } }
      });
      await patchStoreCache((cachedStore) => {
        cachedStore.wipes ||= [];
        replaceCachedRecord(cachedStore.wipes, nextWipe);
        const removedIds = new Set(removedUploads.map((item) => item.id));
        cachedStore.uploads = (cachedStore.uploads || []).filter((item) => !removedIds.has(item.id) && item.id !== upload.id);
        cachedStore.uploads.unshift(upload);
      });
      return { handled: true, removedUploads };
    });
  } catch (error) {
    console.warn('[nb-clan] sqlite rustmaps image sync fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('RustMaps 图片同步写入', error);
  }
}

async function writeRustMapsImageErrorDirect(wipeId, message) {
  if (!sqlitePrimaryMode()) return false;
  try {
    return await runStoreWriteTask(async () => {
      const normalizedWipeId = normalizeText(wipeId, 120);
      const wipe = normalizedWipeId ? await getSqliteRecord('wipes', normalizedWipeId) : null;
      if (!wipe) return true;
      const nextWipe = {
        ...wipe,
        rustMapsImageError: message,
        rustMapsImageErrorAt: nowIso()
      };
      await writeSqliteStorePatch({
        reason: 'rustmaps_image_error',
        upserts: { wipes: [nextWipe] }
      });
      await patchStoreCache((cachedStore) => {
        cachedStore.wipes ||= [];
        replaceCachedRecord(cachedStore.wipes, nextWipe);
      });
      return true;
    });
  } catch (error) {
    console.warn('[nb-clan] sqlite rustmaps image error fallback:', error?.message || error);
    throw sqliteDirectWriteUnavailableError('RustMaps 图片错误状态写入', error);
  }
}

async function syncRustMapsImageForWipe(wipeId, createdBy = '') {
  const { wipe, uploads } = await readRustMapsImageSyncContext(wipeId);
  const rustMapsLink = normalizeRustMapsMapUrl(wipe?.rustMapsLink);
  if (!wipe || !rustMapsLink) {
    if (wipeId) await clearRustMapsImageForWipe(wipeId);
    return null;
  }
  const existing = (uploads || []).find((upload) =>
    isRustMapsWipeMapImage(upload, wipeId) &&
    upload.externalPageUrl === rustMapsLink &&
    upload.externalImageUrl &&
    upload.url
  );
  if (existing) {
    const existingPath = uploadFilePath(existing);
    if (existingPath && existsSync(existingPath)) return existing;
  }
  const imageUrl = await resolveRustMapsImageUrl(rustMapsLink);
  const image = await fetchRustMapsImageAsset(imageUrl);
  const uploadDir = path.join(DATA_DIR, 'uploads', 'map-files');
  const fileName = `${createId('upload')}${image.ext}`;
  const filePath = path.join(uploadDir, fileName);
  const createdAt = nowIso();
  await fs.mkdir(uploadDir, { recursive: true });
  await fs.writeFile(filePath, image.buffer);
  const upload = {
    id: createId('upload'),
    ownerType: 'wipe',
    ownerId: wipeId,
    kind: 'map_image',
    source: 'rustmaps',
    fileName,
    originalName: 'RustMaps full map & icons.png',
    mimeType: image.mimeType,
    size: image.buffer.length,
    url: `/uploads/map-files/${fileName}`,
    externalPageUrl: rustMapsLink,
    externalImageUrl: imageUrl,
    createdBy,
    createdAt
  };
  let directWrite = null;
  try {
    directWrite = await writeRustMapsImageSyncDirect(wipeId, { rustMapsLink, upload, imageUrl, createdAt });
  } catch (error) {
    await fs.unlink(filePath).catch(() => {});
    throw error;
  }
  const removedUploads = directWrite?.handled
    ? directWrite.removedUploads
    : await updateStore((store) => {
        const currentWipe = store.wipes.find((item) => item.id === wipeId);
        if (!currentWipe || normalizeRustMapsMapUrl(currentWipe.rustMapsLink) !== rustMapsLink) return null;
        store.uploads ||= [];
        const removed = store.uploads.filter((item) => isRustMapsWipeMapImage(item, wipeId));
        store.uploads = store.uploads.filter((item) => !isRustMapsWipeMapImage(item, wipeId));
        store.uploads.unshift(upload);
        currentWipe.rustMapsImageUrl = upload.url;
        currentWipe.rustMapsImageSourceUrl = imageUrl;
        currentWipe.rustMapsImageUpdatedAt = createdAt;
        currentWipe.rustMapsImageError = '';
        currentWipe.rustMapsImageErrorAt = '';
        return removed;
      });
  if (!removedUploads) {
    await fs.unlink(filePath).catch(() => {});
    return null;
  }
  await Promise.all(removedUploads.map((item) => {
    const removedPath = uploadFilePath(item);
    return removedPath ? fs.unlink(removedPath).catch(() => {}) : Promise.resolve();
  }));
  return upload;
}

async function syncRustMapsImageForWipeSafe(wipeId, createdBy = '') {
  try {
    return await syncRustMapsImageForWipe(wipeId, createdBy);
  } catch (error) {
    const message = normalizeText(error?.message || 'RustMaps 地图图片同步失败', 240);
    try {
      const directWrite = await writeRustMapsImageErrorDirect(wipeId, message);
      if (!directWrite) {
        await updateStore((store) => {
          const wipe = store.wipes.find((item) => item.id === wipeId);
          if (!wipe) return;
          wipe.rustMapsImageError = message;
          wipe.rustMapsImageErrorAt = nowIso();
        });
      }
    } catch (writeError) {
      console.warn('[nb-clan] sqlite rustmaps image error write failed:', writeError?.message || writeError);
    }
    return null;
  }
}

function queueRustMapsImageSyncForWipe(wipeId, createdBy = '') {
  if (!wipeId) return;
  queueBackgroundTask(
    `rustmaps-image-sync:${wipeId}`,
    () => syncRustMapsImageForWipeSafe(wipeId, createdBy),
    0
  );
}

function enrichWipe(store, wipe, user) {
  if (!wipe) return null;
  const uploads = store.uploads.filter((upload) => upload.ownerType === 'wipe' && upload.ownerId === wipe.id);
  const participants = visibleParticipants(store, wipe, user);
  const settlement = store.wipeSettlements.find((item) => item.wipeId === wipe.id) || null;
  const scopedSettlement = settlement ? settlementForViewer(store, settlement, user) : null;
  const serverVip = serverVipContextForWipe(wipe);
  const participantCount = wipe.status === 'closed'
    ? Number(scopedSettlement?.summary?.participantCount ?? settlement?.summary?.participantCount ?? participants.length)
    : participants.length;
  return {
    ...wipe,
    name: expandVitalRustName(wipe.name),
    serverName: expandVitalRustName(wipe.serverName),
    rawStatus: wipe.status,
    status: effectiveWipeStatus(wipe),
    screenshots: uploads.filter((upload) => upload.kind === 'server_screenshot').map(publicUpload),
    mapFiles: uploads.filter((upload) => upload.kind === 'map_file' || upload.kind === 'map_image').map(publicUpload),
    serverVip,
    vipProvider: serverVip.provider,
    vipLabel: serverVip.label,
    ...publicWipeKdaCapability(wipe),
    participantCount,
    settlementSummary: scopedSettlement?.summary || settlement?.summary || null
  };
}

function wipeListParticipantCount(store, wipe, user, leaderSquadIds = null) {
  if (!wipe) return 0;
  const settlement = wipe.status === 'closed'
    ? store.wipeSettlements.find((item) => item.wipeId === wipe.id) || null
    : null;
  if (canViewOperationalData(user, store)) {
    return Number(settlement?.summary?.participantCount ?? store.wipeParticipants.filter((item) => item.wipeId === wipe.id).length);
  }
  const allowedSquadIds = leaderSquadIds || new Set(leaderSquads(store, user).map((squad) => squad.id));
  if (settlement?.participantsSnapshot?.length) {
    return settlement.participantsSnapshot.filter((participant) => allowedSquadIds.has(participant.squadId)).length;
  }
  return store.wipeParticipants.filter((participant) => (
    participant.wipeId === wipe.id && allowedSquadIds.has(participant.squadId)
  )).length;
}

function enrichWipeListItem(store, wipe, user, leaderSquadIds = null) {
  if (!wipe) return null;
  return {
    id: wipe.id,
    name: expandVitalRustName(wipe.name),
    serverName: expandVitalRustName(wipe.serverName),
    rawStatus: wipe.status,
    status: effectiveWipeStatus(wipe),
    startedAt: wipe.startedAt || '',
    closedAt: wipe.closedAt || '',
    createdAt: wipe.createdAt || '',
    updatedAt: wipe.updatedAt || '',
    notes: wipe.notes || '',
    vitalServerId: wipe.vitalServerId || '',
    vitalWipeId: wipe.vitalWipeId || '',
    ...publicWipeKdaCapability(wipe),
    battlemetricsId: wipe.battlemetricsId || '',
    participantCount: wipeListParticipantCount(store, wipe, user, leaderSquadIds)
  };
}

function visibleParticipants(store, wipe, user, filters = {}) {
  const membersById = new Map(enrichMembers(store, user).map((member) => [member.id, member]));
  const leaderSquadIds = new Set(leaderSquads(store, user).map((squad) => squad.id));
  const squadSelection = visibleSquadSelection(store, user, filters);
  return store.wipeParticipants
    .filter((participant) => participant.wipeId === wipe.id)
    .filter((participant) => {
      if (canViewOperationalData(user, store)) {
        return !squadSelection.requested || squadSelection.ids.has(participant.squadId);
      }
      if (!leaderSquadIds.has(participant.squadId)) return false;
      return !squadSelection.requested || squadSelection.ids.has(participant.squadId);
    })
    .map((participant) => {
      const member = membersById.get(participant.memberId) || null;
      const currentServerVip = publicCurrentServerVip(member || {}, wipe);
      return {
        ...participant,
        status: normalizeParticipantStatus(participant.status),
        member,
        squadName: store.squads.find((squad) => squad.id === participant.squadId)?.name || '',
        currentServerVip,
        currentServerVipType: currentServerVip.type,
        serverVip: currentServerVip
      };
    })
    .filter((participant) => participant.member);
}

function wipeParticipantListQueryParams(query = {}) {
  const hasLimit = Object.hasOwn(query, 'limit');
  const rawLimit = Math.floor(Number(query.limit));
  const rawOffset = Math.floor(Number(query.offset));
  return {
    hasLimit,
    limit: hasLimit ? Math.max(1, Math.min(100, Number.isFinite(rawLimit) ? rawLimit : 5)) : 0,
    offset: Math.max(0, Number.isFinite(rawOffset) ? rawOffset : 0)
  };
}

function wipeParticipantSummary(participants = [], wipe = null) {
  const vipContext = serverVipContextForWipe(wipe);
  const summary = {
    total: 0,
    onTime: 0,
    on_time: 0,
    join8h: 0,
    join_8h: 0,
    join16h: 0,
    join_16h: 0,
    notAttending: 0,
    not_attending: 0,
    late: 0,
    skip: 0,
    available: 0,
    legacySummary: {
      late: 0,
      skip: 0
    },
    vip: 0,
    priority: 0,
    queueSkip: 0,
    vipProvider: vipContext.provider,
    vipLabel: vipContext.label,
    prioritySupported: vipContext.supportsPriority,
    queueSkipSupported: vipContext.supportsQueueSkip,
    squads: []
  };
  const rowsBySquad = new Map();
  for (const participant of participants) {
    const status = normalizeParticipantStatus(participant.status);
    countWechatWipeSignupSummary(summary, status);
    const available = isParticipantAvailable(status);
    if (available) {
      const vip = participant.currentServerVip || participant.serverVip || publicCurrentServerVip(participant.member || participant, wipe);
      const vipType = vip.active ? vip.type : 'none';
      if (vipType === 'priority') {
        summary.vip += 1;
        summary.priority += 1;
      } else if (vipType === 'queue_skip') {
        summary.vip += 1;
        summary.queueSkip += 1;
      }
    }
    if (status !== 'on_time') continue;
    const name = participant.squadName || '';
    const key = participant.squadId || `unassigned:${name}`;
    const row = rowsBySquad.get(key) || { id: key, name, count: 0 };
    row.count += 1;
    rowsBySquad.set(key, row);
  }
  summary.squads = [...rowsBySquad.values()]
    .sort((left, right) => right.count - left.count || left.name.localeCompare(right.name));
  return summary;
}

function wipeParticipantsPayload(store, wipe, user, query = {}) {
  const params = wipeParticipantListQueryParams(query);
  const allParticipants = visibleParticipants(store, wipe, user);
  const total = allParticipants.length;
  const participants = params.hasLimit ? allParticipants.slice(params.offset, params.offset + params.limit) : allParticipants;
  const limit = params.hasLimit ? params.limit : total;
  const boundSteamId = normalizeText(user?.boundSteamId, 80);
  const myParticipant = boundSteamId
    ? allParticipants.find((participant) => participant.member?.steamId === boundSteamId) || null
    : null;
  return {
    participants,
    total,
    offset: params.hasLimit ? params.offset : 0,
    limit,
    hasMore: params.hasLimit && params.offset + participants.length < total,
    summary: wipeParticipantSummary(allParticipants, wipe),
    myParticipant
  };
}

function wipeParticipantMutationResponseQuery(body = {}) {
  if (!Object.hasOwn(body || {}, 'responseLimit')) return {};
  return {
    limit: body.responseLimit,
    offset: body.responseOffset
  };
}

function canViewWipeRecord(store, wipe, user) {
  if (canViewOperationalData(user, store)) return true;
  const leaderSquadIds = new Set(leaderSquads(store, user).map((squad) => squad.id));
  if (!leaderSquadIds.size) return isLeader(user) && wipe.status === 'active';
  if (wipe.status === 'active') return true;
  if (wipe.status !== 'closed') return true;
  const settlement = store.wipeSettlements.find((item) => item.wipeId === wipe.id);
  const settlementParticipants = settlement?.participantsSnapshot || [];
  if (settlementParticipants.some((participant) => leaderSquadIds.has(participant.squadId))) return true;
  return store.wipeParticipants.some((participant) => participant.wipeId === wipe.id && leaderSquadIds.has(participant.squadId));
}

function canViewWipesInStore(store, user) {
  return canViewWipes(user, activeSquads(store)) || canViewModuleInStore(store, user, 'history') || canViewModuleInStore(store, user, 'kda');
}

function participantCandidates(store, wipe, user) {
  const existing = new Set(store.wipeParticipants.filter((item) => item.wipeId === wipe.id).map((item) => item.memberId));
  const squadsByMember = memberSquadMap(store);
  const captainSquads = leaderSquads(store, user);
  return enrichMembers(store, user).filter((member) => {
    if (existing.has(member.id)) return false;
    if (isAdmin(user)) return true;
    const memberSquad = squadsByMember.get(member.id);
    const leaderSquad = memberSquad
      ? captainSquads.find((squad) => squad.id === memberSquad.squadId) || null
      : captainSquads[0] || null;
    return canManageWipeParticipant(user, member, memberSquad, leaderSquad);
  });
}

function hashNumber(value) {
  let hash = 2166136261;
  for (const char of String(value || '')) {
    hash ^= char.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return Math.abs(hash >>> 0);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function estimateVitalKdaSyncSeconds(participantCount) {
  const total = Math.max(0, Math.floor(Number(participantCount) || 0));
  if (!total) return 3;
  const batches = Math.max(1, Math.ceil(total / VITAL_KDA_BATCH_SIZE));
  const requestBudgetMs = batches * 1800;
  const throttleBudgetMs = Math.max(0, batches - 1) * VITAL_KDA_SYNC_DELAY_MS;
  return Math.max(3, Math.ceil((requestBudgetMs + throttleBudgetMs) / 1000));
}

function estimateBattlemetricsSyncSeconds(targetsOrCount) {
  const targets = Array.isArray(targetsOrCount) ? targetsOrCount : null;
  const total = targets ? targets.length : Math.max(0, Math.floor(Number(targetsOrCount) || 0));
  if (!total) return 3;
  const missingMatchCount = targets
    ? targets.filter((member) => !member?.battlemetricsId).length
    : total;
  const matchRequestCount = Math.ceil(missingMatchCount / BATTLEMETRICS_MATCH_BATCH_SIZE);
  const sessionRequestCount = total;
  const requestCount = matchRequestCount + sessionRequestCount;
  const minuteWindowBudgetMs = Math.ceil(BATTLEMETRICS_RATE_LIMIT_WINDOW_MS / BATTLEMETRICS_REQUESTS_PER_MINUTE);
  const requestBudgetMs = requestCount * Math.max(BATTLEMETRICS_MIN_INTERVAL_MS, minuteWindowBudgetMs);
  return Math.max(3, Math.ceil((requestBudgetMs + 1500) / 1000));
}

function estimateMemberProfileSyncSeconds(targetsOrCount) {
  const total = Array.isArray(targetsOrCount)
    ? targetsOrCount.length
    : Math.max(0, Math.floor(Number(targetsOrCount) || 0));
  if (!total) return 3;
  const minimumRequestMs = RUST_KDA_FAST_LOCAL ? 500 : 900;
  const perMemberMs = Math.max(minimumRequestMs, MEMBER_PROFILE_QUEUE_DELAY_MS, STEAM_BROADCAST_REQUEST_INTERVAL_MS);
  const steamWebApiBatches = Math.max(1, Math.ceil(total / 100));
  const steamWebApiBudgetMs = steamWebApiBatches * STEAM_WEB_API_REQUEST_INTERVAL_MS;
  return Math.max(3, Math.ceil((total * perMemberMs + steamWebApiBudgetMs + 1200) / 1000));
}

function estimateHexaytronSyncSeconds(targetsOrCount) {
  const total = Array.isArray(targetsOrCount)
    ? targetsOrCount.length
    : Math.max(0, Math.floor(Number(targetsOrCount) || 0));
  if (!total) return 3;
  return Math.max(3, Math.ceil((total * (HEXAYTRON_POLL_TIMEOUT_MS + HEXAYTRON_SYNC_INTERVAL_MS)) / 1000));
}

function finiteNumber(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : null;
}

function optionalFiniteNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  return finiteNumber(value);
}

function firstOptionalFiniteNumber(...values) {
  for (const value of values) {
    const numeric = optionalFiniteNumber(value);
    if (numeric !== null) return numeric;
  }
  return null;
}

function firstFiniteNumber(...values) {
  for (const value of values) {
    const numeric = finiteNumber(value);
    if (numeric !== null) return numeric;
  }
  return null;
}

function nestedValue(source, path) {
  const parts = String(path || '').split('.');
  let cursor = source || {};
  for (let index = 0; index < parts.length; index += 1) {
    const remaining = parts.slice(index).join('.');
    if (cursor && Object.hasOwn(cursor, remaining)) return cursor[remaining];
    const part = parts[index];
    if (cursor == null || cursor[part] == null) return undefined;
    cursor = cursor[part];
  }
  return cursor;
}

function playTimeMinutesFromPayload(payload = {}) {
  const minutes = firstOptionalFiniteNumber(
    payload.playTimeMinutes,
    payload.playtimeMinutes,
    payload.player?.playTimeMinutes,
    payload.player?.playtimeMinutes,
    payload.statistics?.playTimeMinutes,
    payload.statistics?.playtimeMinutes,
    nestedValue(payload, 'statistics.playtime.minutes')
  );
  if (minutes !== null) return Math.max(0, Math.round(minutes));

  const hours = firstOptionalFiniteNumber(
    payload.playTimeHours,
    payload.playtimeHours,
    payload.player?.playTimeHours,
    payload.player?.playtimeHours,
    nestedValue(payload, 'statistics.playtime.hours')
  );
  if (hours !== null) return Math.max(0, Math.round(hours * 60));

  const seconds = firstOptionalFiniteNumber(
    payload.playTimeSeconds,
    payload.playtimeSeconds,
    payload.player?.playTimeSeconds,
    payload.player?.playtimeSeconds,
    nestedValue(payload, 'statistics.playtime.seconds')
  );
  if (seconds !== null) return Math.max(0, Math.round(seconds / 60));
  return 0;
}

function playTimeKnownFromPayload(payload = {}) {
  return firstOptionalFiniteNumber(
    payload.playTimeMinutes,
    payload.playtimeMinutes,
    payload.player?.playTimeMinutes,
    payload.player?.playtimeMinutes,
    payload.statistics?.playTimeMinutes,
    payload.statistics?.playtimeMinutes,
    nestedValue(payload, 'statistics.playtime.minutes'),
    payload.playTimeHours,
    payload.playtimeHours,
    payload.player?.playTimeHours,
    payload.player?.playtimeHours,
    nestedValue(payload, 'statistics.playtime.hours'),
    payload.playTimeSeconds,
    payload.playtimeSeconds,
    payload.player?.playTimeSeconds,
    payload.player?.playtimeSeconds,
    nestedValue(payload, 'statistics.playtime.seconds')
  ) !== null;
}

function inventoryValueFromPayload(payload = {}) {
  const tradableValue = firstOptionalFiniteNumber(
    payload.totalSummary?.tradableValue,
    payload.skinsSummary?.tradableValue,
    payload.skinsSummary?.totalValue
  );
  const storeOwnedValue = firstOptionalFiniteNumber(
    payload.storeSummary?.ownedValue,
    payload.totalSummary?.ownedStoreValue
  );
  const totalValue = firstOptionalFiniteNumber(
    payload.totalSummary?.totalValue,
    payload.inventoryValue,
    payload.value
  );
  const dlcValue = firstOptionalFiniteNumber(payload.dlcSummary?.ownedValue);
  const inventoryAvailable = payload.inventoryAvailable === true || payload.skinsSummary?.available === true;
  const dlcAvailable = payload.dlcSummary?.available === true;
  const storeOwnedCount = firstOptionalFiniteNumber(payload.storeSummary?.ownedCount, payload.totalSummary?.ownedStoreItems);
  const hasStoreMatch = (storeOwnedCount !== null && storeOwnedCount > 0) || (storeOwnedValue !== null && storeOwnedValue > 0);
  const hasPositiveValue = [tradableValue, storeOwnedValue, totalValue, dlcValue].some((value) => value !== null && value > 0);
  const hasPublicEvidence = inventoryAvailable || dlcAvailable || hasStoreMatch || hasPositiveValue;
  if (!hasPublicEvidence) return null;
  if (tradableValue !== null || storeOwnedValue !== null) {
    return Number(((tradableValue || 0) + (storeOwnedValue || 0)).toFixed(2));
  }
  return firstFiniteNumber(totalValue, dlcValue);
}

function profilePublicFromPayload(playerPayload = null, steamProfilePayload = null) {
  if (typeof steamProfilePayload?.profilePublic === 'boolean') return steamProfilePayload.profilePublic;
  const privacyState = normalizeText(playerPayload?.privacyState || playerPayload?.profile?.privacyState, 40).toLowerCase();
  if (privacyState) return privacyState !== 'private';
  const visibilityState = normalizeText(playerPayload?.visibilityState || playerPayload?.profile?.visibilityState, 20);
  if (visibilityState) return visibilityState !== '1';
  return Boolean(playerPayload && !playerPayload.error);
}

function accountRestrictionFieldsFromPayload(accountRestrictionPayload = null, accountRestrictionError = '') {
  const accountRestrictionStatus = normalizeText(accountRestrictionPayload?.success, 60);
  const accountRestricted = Boolean(accountRestrictionPayload?.restricted || accountRestrictionStatus === 'user_restricted');
  return {
    accountRestricted,
    accountRestrictionStatus,
    accountRestrictionCheckedAt: accountRestrictionPayload ? nowIso() : '',
    accountRestrictionRetryMs: firstFiniteNumber(accountRestrictionPayload?.retryMs, accountRestrictionPayload?.retry),
    accountRestrictionEresult: firstFiniteNumber(accountRestrictionPayload?.eresult),
    accountRestrictionError: normalizeText(accountRestrictionError || accountRestrictionPayload?.error, 240)
  };
}

function accountRestrictionStatsFromPayload(steamId, accountRestrictionPayload = null, accountRestrictionError = '') {
  const fields = accountRestrictionFieldsFromPayload(accountRestrictionPayload, accountRestrictionError);
  return {
    steamId,
    ...fields,
    fetchedAt: fields.accountRestrictionCheckedAt || nowIso()
  };
}

function steamBanFieldsFromPayload(steamBanPayload = null, steamBanError = '') {
  if (!steamBanPayload) {
    return {
      steamBanError: normalizeText(steamBanError, 240)
    };
  }
  const numberOfVacBans = Math.max(0, Math.floor(Number(steamBanPayload.numberOfVacBans || 0)));
  const numberOfGameBans = Math.max(0, Math.floor(Number(steamBanPayload.numberOfGameBans || 0)));
  const daysSinceLastBan = Math.max(0, Math.floor(Number(steamBanPayload.daysSinceLastBan || 0)));
  const economyBan = normalizeText(steamBanPayload.economyBan || 'none', 80).toLowerCase() || 'none';
  return {
    vacBanned: Boolean(steamBanPayload.vacBanned || numberOfVacBans > 0),
    numberOfVacBans,
    numberOfGameBans,
    daysSinceLastBan,
    communityBanned: Boolean(steamBanPayload.communityBanned),
    economyBan,
    economyRestricted: Boolean(economyBan && economyBan !== 'none'),
    steamBanCheckedAt: nowIso(),
    steamBanError: normalizeText(steamBanError || steamBanPayload.error, 240)
  };
}

function steamBanStatsFromPayload(steamId, steamBanPayload = null, steamBanError = '') {
  return {
    steamId,
    ...steamBanFieldsFromPayload(steamBanPayload, steamBanError)
  };
}

async function fetchSteamBanStatsForSteamIds(steamIds = [], store = null) {
  const result = await fetchSteamPlayerBans(steamIds, { apiKey: store ? steamWebApiKey(store) : '' });
  const statsBySteamId = new Map();
  if (result.skipped) return statsBySteamId;
  for (const steamId of steamIds) {
    statsBySteamId.set(steamId, steamBanStatsFromPayload(steamId, result.bansBySteamId.get(steamId) || null, result.error));
  }
  return statsBySteamId;
}

function memberProfileStatsWithoutAccountRestriction(stats = {}) {
  const {
    accountRestricted,
    accountRestrictionStatus,
    accountRestrictionCheckedAt,
    accountRestrictionRetryMs,
    accountRestrictionEresult,
    accountRestrictionError,
    ...profileStats
  } = stats || {};
  return profileStats;
}

function steamIdentityProfileStats(steamId, steamProfile = null) {
  const steamDisplayName = normalizeText(steamProfile?.nickname, 120);
  return {
    steamId,
    displayName: steamDisplayName,
    steamDisplayName,
    avatar: normalizeText(steamProfile?.avatar, 500),
    profileUrl: normalizeText(steamProfile?.profileUrl, 500) || steamProfileUrl(steamId),
    profilePublic: Boolean(steamProfile?.profilePublic)
  };
}

async function fetchSteamAccountRestrictionStats(steamId) {
  try {
    const payload = await fetchSteamBroadcastRestriction(steamId);
    return accountRestrictionStatsFromPayload(steamId, payload, payload?.error || '');
  } catch (error) {
    return accountRestrictionStatsFromPayload(steamId, null, compactExternalError(error) || 'Steam broadcast unavailable');
  }
}

function profileStatsFromExternalPayload(steamId, playerPayload = null, inventoryPayload = null, error = '', steamProfilePayload = null, officialKdaPayload = null, officialKdaError = '', accountRestrictionPayload = null, accountRestrictionError = '', steamBanPayload = null, steamBanError = '') {
  const playTimeMinutes = playTimeMinutesFromPayload(playerPayload || {});
  const playTimeKnown = playTimeKnownFromPayload(playerPayload || {});
  const inventoryValue = inventoryValueFromPayload(inventoryPayload || {});
  const inventoryPublic = inventoryValue !== null;
  const profilePublic = profilePublicFromPayload(playerPayload, steamProfilePayload);
  const officialKda = publicRustKdaStatsPayload(officialKdaPayload);
  const displayName = normalizeText(steamProfilePayload?.nickname || playerPayload?.name, 120);
  const steamDisplayName = normalizeText(steamProfilePayload?.nickname, 120);
  return {
    steamId,
    displayName,
    steamDisplayName,
    avatar: normalizeText(playerPayload?.avatarMedium || playerPayload?.avatarFull || playerPayload?.avatar || steamProfilePayload?.avatar, 500),
    profileUrl: normalizeText(playerPayload?.profileUrl || steamProfilePayload?.profileUrl, 500) || steamProfileUrl(steamId),
    playTimeMinutes,
    playTimeVisibility: playTimeKnown ? 'public' : (playerPayload ? 'private' : 'unknown'),
    inventoryValue,
    inventoryCurrency: normalizeText(inventoryPayload?.totalSummary?.currency, 12) || 'USD',
    inventoryPublic,
    inventoryVisibility: inventoryPublic ? 'public' : (inventoryPayload ? 'private' : 'unknown'),
    profilePublic,
    ...accountRestrictionFieldsFromPayload(accountRestrictionPayload, accountRestrictionError),
    ...steamBanFieldsFromPayload(steamBanPayload, steamBanError),
    playTimeKnown,
    fetchedAt: nowIso(),
    source: RUST_KDA_QUERY_SOURCE,
    error: normalizeText(error, 240),
    officialKda,
    officialKdaFetchedAt: officialKda ? nowIso() : '',
    officialKdaError: normalizeText(officialKdaError, 240)
  };
}

function profileStatsFromKdaRow(row = {}) {
  const playTimeMinutes = Number(row.playTimeMinutes || 0);
  return {
    playTimeMinutes: Number.isFinite(playTimeMinutes) ? playTimeMinutes : 0,
    playTimeKnown: Object.hasOwn(row, 'playTimeMinutes') && Number.isFinite(playTimeMinutes) && playTimeMinutes > 0,
    playTimeVisibility: 'unknown',
    inventoryValue: null,
    inventoryCurrency: 'USD',
    inventoryPublic: false,
    inventoryVisibility: 'unknown',
    profilePublic: false,
    accountRestricted: false,
    accountRestrictionStatus: '',
    accountRestrictionCheckedAt: '',
    accountRestrictionRetryMs: null,
    accountRestrictionEresult: null,
    accountRestrictionError: '',
    vacBanned: false,
    numberOfVacBans: 0,
    numberOfGameBans: 0,
    daysSinceLastBan: 0,
    communityBanned: false,
    economyBan: 'none',
    economyRestricted: false,
    steamBanCheckedAt: '',
    steamBanError: '',
    fetchedAt: row.syncedAt || '',
    source: row.source || ''
  };
}

function upsertMemberProfileCache(store, member, stats) {
  if (!member || !stats) return;
  const existingIndex = store.memberProfiles.findIndex((item) => item.memberId === member.id);
  const existing = existingIndex >= 0 ? store.memberProfiles[existingIndex] : {};
  const battlemetricsError = normalizeText(stats.battlemetricsError, 240);
  const clearBattlemetricsServerOnline = Boolean(battlemetricsError && (
    Object.hasOwn(stats, 'battlemetricsServerId') ||
    Object.hasOwn(stats, 'battlemetricsWipeId') ||
    Object.hasOwn(stats, 'battlemetricsServerName') ||
    Object.hasOwn(stats, 'battlemetricsWipeName')
  ));
  const hasPlayTimeSignal = Object.hasOwn(stats, 'playTimeMinutes') || Object.hasOwn(stats, 'playTimeKnown');
  const statsPlayTimeMinutes = optionalFiniteNumber(stats.playTimeMinutes);
  const hasStatsPlayTime = statsPlayTimeMinutes !== null && statsPlayTimeMinutes >= 0;
  const nextPlayTimeMinutes = hasPlayTimeSignal
    ? (hasStatsPlayTime ? statsPlayTimeMinutes : 0)
    : Number(existing.playTimeMinutes || 0);
  const nextPlayTimeKnown = hasPlayTimeSignal
    ? Boolean(hasStatsPlayTime && stats.playTimeKnown)
    : Boolean(existing.playTimeKnown ?? false);
  const statsSteamDisplayName = normalizeText(stats.steamDisplayName, 120);
  const statsDisplayName = normalizeText(stats.displayName, 120);
  const nextDisplayName = statsSteamDisplayName || (!existing.displayName ? statsDisplayName : existing.displayName) || '';
  const nextAvatar = normalizeText(stats.avatar, 500) || existing.avatar || '';
  const nextProfileUrl = normalizeText(stats.profileUrl, 500) || existing.profileUrl || steamProfileUrl(member.steamId);
  const nextProfile = {
    id: existing.id || createId('member_profile'),
    memberId: member.id,
    steamId: member.steamId,
    displayName: nextDisplayName,
    avatar: nextAvatar,
    profileUrl: nextProfileUrl,
    playTimeMinutes: nextPlayTimeMinutes,
    playTimeKnown: nextPlayTimeKnown,
    playTimeVisibility: stats.playTimeVisibility ?? existing.playTimeVisibility ?? '',
    inventoryValue: stats.inventoryValue ?? existing.inventoryValue ?? null,
    inventoryCurrency: stats.inventoryCurrency ?? existing.inventoryCurrency ?? 'USD',
    inventoryPublic: Boolean(stats.inventoryPublic ?? existing.inventoryPublic ?? false),
    inventoryVisibility: stats.inventoryVisibility ?? existing.inventoryVisibility ?? '',
    profilePublic: Boolean(stats.profilePublic ?? existing.profilePublic ?? false),
    accountRestricted: Boolean(stats.accountRestricted ?? existing.accountRestricted ?? false),
    accountRestrictionStatus: stats.accountRestrictionStatus ?? existing.accountRestrictionStatus ?? '',
    accountRestrictionCheckedAt: stats.accountRestrictionCheckedAt ?? existing.accountRestrictionCheckedAt ?? '',
    accountRestrictionRetryMs: stats.accountRestrictionRetryMs ?? existing.accountRestrictionRetryMs ?? null,
    accountRestrictionEresult: stats.accountRestrictionEresult ?? existing.accountRestrictionEresult ?? null,
    accountRestrictionError: stats.accountRestrictionError ?? existing.accountRestrictionError ?? '',
    vacBanned: Boolean(stats.vacBanned ?? existing.vacBanned ?? false),
    numberOfVacBans: Number(stats.numberOfVacBans ?? existing.numberOfVacBans ?? 0),
    numberOfGameBans: Number(stats.numberOfGameBans ?? existing.numberOfGameBans ?? 0),
    daysSinceLastBan: Number(stats.daysSinceLastBan ?? existing.daysSinceLastBan ?? 0),
    communityBanned: Boolean(stats.communityBanned ?? existing.communityBanned ?? false),
    economyBan: stats.economyBan ?? existing.economyBan ?? 'none',
    economyRestricted: Boolean(stats.economyRestricted ?? existing.economyRestricted ?? false),
    steamBanCheckedAt: stats.steamBanCheckedAt ?? existing.steamBanCheckedAt ?? '',
    steamBanError: stats.steamBanError ?? existing.steamBanError ?? '',
    fetchedAt: stats.fetchedAt ?? existing.fetchedAt ?? '',
    source: stats.source ?? existing.source ?? '',
    error: stats.error ?? existing.error ?? '',
    officialKda: stats.officialKda ?? existing.officialKda ?? null,
    officialKdaFetchedAt: stats.officialKdaFetchedAt ?? existing.officialKdaFetchedAt ?? '',
    officialKdaError: stats.officialKdaError ?? existing.officialKdaError ?? '',
    battlemetricsPlayerId: stats.battlemetricsPlayerId ?? existing.battlemetricsPlayerId ?? '',
    battlemetricsServerId: stats.battlemetricsServerId ?? existing.battlemetricsServerId ?? '',
    battlemetricsServerName: stats.battlemetricsServerName ?? existing.battlemetricsServerName ?? '',
    battlemetricsWipeId: stats.battlemetricsWipeId ?? existing.battlemetricsWipeId ?? '',
    battlemetricsWipeName: stats.battlemetricsWipeName ?? existing.battlemetricsWipeName ?? '',
    battlemetricsWipeStatus: stats.battlemetricsWipeStatus ?? existing.battlemetricsWipeStatus ?? '',
    battlemetricsLastOnlineAt: stats.battlemetricsLastOnlineAt ?? (clearBattlemetricsServerOnline ? '' : existing.battlemetricsLastOnlineAt) ?? '',
    battlemetricsLastOfflineAt: stats.battlemetricsLastOfflineAt ?? (clearBattlemetricsServerOnline ? '' : existing.battlemetricsLastOfflineAt) ?? '',
    battlemetricsTotalPlayTimeSeconds: Number(stats.battlemetricsTotalPlayTimeSeconds ?? existing.battlemetricsTotalPlayTimeSeconds ?? 0),
    battlemetricsServerPlayTimeSeconds: Number(stats.battlemetricsServerPlayTimeSeconds ?? (clearBattlemetricsServerOnline ? 0 : existing.battlemetricsServerPlayTimeSeconds) ?? existing.battlemetricsTotalPlayTimeSeconds ?? 0),
    battlemetricsWeeklyPlayTimeSeconds: Number(stats.battlemetricsWeeklyPlayTimeSeconds ?? (clearBattlemetricsServerOnline ? 0 : existing.battlemetricsWeeklyPlayTimeSeconds) ?? 0),
    battlemetricsSyncedAt: stats.battlemetricsSyncedAt ?? existing.battlemetricsSyncedAt ?? '',
    battlemetricsError: stats.battlemetricsError ?? existing.battlemetricsError ?? '',
    battlemetricsMatchConfidence: stats.battlemetricsMatchConfidence ?? existing.battlemetricsMatchConfidence ?? '',
    battlemetricsMatchAlias: stats.battlemetricsMatchAlias ?? existing.battlemetricsMatchAlias ?? '',
    battlemetricsMatchNotes: stats.battlemetricsMatchNotes ?? existing.battlemetricsMatchNotes ?? '',
    battlemetricsMatchFirstSeenAt: stats.battlemetricsMatchFirstSeenAt ?? existing.battlemetricsMatchFirstSeenAt ?? '',
    battlemetricsMatchLastSeenAt: stats.battlemetricsMatchLastSeenAt ?? existing.battlemetricsMatchLastSeenAt ?? '',
    battlemetricsMatchServerTimePlayedSeconds: Number(stats.battlemetricsMatchServerTimePlayedSeconds ?? existing.battlemetricsMatchServerTimePlayedSeconds ?? 0),
    battlemetricsSessionTruncated: Boolean(stats.battlemetricsSessionTruncated ?? (clearBattlemetricsServerOnline ? false : existing.battlemetricsSessionTruncated) ?? false),
    battlemetricsSessionFetchedPages: Number(stats.battlemetricsSessionFetchedPages ?? (clearBattlemetricsServerOnline ? 0 : existing.battlemetricsSessionFetchedPages) ?? 0),
    battlemetricsSessionPageLimit: Number(stats.battlemetricsSessionPageLimit ?? (clearBattlemetricsServerOnline ? 0 : existing.battlemetricsSessionPageLimit) ?? 0),
    battlemetricsRangeStopAt: stats.battlemetricsRangeStopAt ?? (clearBattlemetricsServerOnline ? '' : existing.battlemetricsRangeStopAt) ?? '',
    hexaytron: stats.hexaytron ?? existing.hexaytron ?? null
  };
  if (existingIndex >= 0) store.memberProfiles[existingIndex] = nextProfile;
  else store.memberProfiles.push(nextProfile);

  let changed = false;
  const nextSteamNickname = normalizeText(stats.steamDisplayName || stats.steamNickname, 120);
  if (nextSteamNickname && member.steamNickname !== nextSteamNickname) {
    member.steamNickname = nextSteamNickname;
    changed = true;
  } else if (nextProfile.displayName && !member.steamNickname) {
    member.steamNickname = nextProfile.displayName;
    changed = true;
  }
  if (nextProfile.avatar && member.avatar !== nextProfile.avatar) {
    member.avatar = nextProfile.avatar;
    changed = true;
  }
  if (changed) member.updatedAt = nowIso();
  if (nextProfile.battlemetricsPlayerId && member.battlemetricsId !== nextProfile.battlemetricsPlayerId) {
    member.battlemetricsId = nextProfile.battlemetricsPlayerId;
    member.updatedAt = nowIso();
  }
}

function memberProfilePayload(store, member, indexes = getStoreIndexes(store), options = {}) {
  const useKdaFallback = options.useKdaFallback !== false;
  const currentKda = useKdaFallback ? (indexes.latestKdaByMemberId.get(member.id) || null) : null;
  const cached = indexes.memberProfileByMemberId.get(member.id) || null;
  const fallback = currentKda ? profileStatsFromKdaRow(currentKda) : profileStatsFromKdaRow({});
  const cachedPlayTimeMinutes = Number(cached?.playTimeMinutes || 0);
  const cachedPlayTimeVisibility = normalizeText(cached?.playTimeVisibility, 20);
  const cachedPlayTimeKnown = cachedPlayTimeVisibility
    ? cachedPlayTimeVisibility === 'public' && Boolean(cached?.playTimeKnown) && Number.isFinite(cachedPlayTimeMinutes)
    : cachedPlayTimeMinutes > 0 && (Boolean(cached?.playTimeKnown) || cachedPlayTimeMinutes > 0);
  const fallbackPlayTimeKnown = !cached && Boolean(fallback.playTimeKnown);
  const cachedInventoryValue = cached?.inventoryValue;
  const cachedInventoryNumber = optionalFiniteNumber(cachedInventoryValue);
  const cachedInventoryVisibility = normalizeText(cached?.inventoryVisibility, 20);
  const cachedInventoryPublic = cachedInventoryVisibility
    ? cachedInventoryVisibility === 'public' && cachedInventoryNumber !== null
    : Boolean(cached?.inventoryPublic) && cachedInventoryNumber !== null && cachedInventoryNumber > 0;
  const playTimeKnown = cachedPlayTimeKnown || fallbackPlayTimeKnown;
  return {
    playTimeMinutes: cachedPlayTimeKnown ? cachedPlayTimeMinutes : (fallbackPlayTimeKnown ? Number(fallback.playTimeMinutes || 0) : 0),
    playTimeKnown,
    playTimeVisibility: cachedPlayTimeVisibility || (playTimeKnown ? 'public' : (cached ? 'private' : 'unknown')),
    inventoryValue: cachedInventoryPublic ? cachedInventoryNumber : null,
    inventoryCurrency: cached?.inventoryCurrency || fallback.inventoryCurrency || 'USD',
    inventoryPublic: cachedInventoryPublic,
    inventoryVisibility: cachedInventoryPublic ? 'public' : (cachedInventoryVisibility || (cached ? 'private' : 'unknown')),
    profilePublic: Boolean(cached?.profilePublic),
    accountRestricted: Boolean(cached?.accountRestricted),
    accountRestrictionStatus: cached?.accountRestrictionStatus || '',
    accountRestrictionCheckedAt: cached?.accountRestrictionCheckedAt || '',
    accountRestrictionRetryMs: cached?.accountRestrictionRetryMs ?? null,
    accountRestrictionEresult: cached?.accountRestrictionEresult ?? null,
    accountRestrictionError: cached?.accountRestrictionError || '',
    vacBanned: Boolean(cached?.vacBanned),
    numberOfVacBans: Number(cached?.numberOfVacBans || 0),
    numberOfGameBans: Number(cached?.numberOfGameBans || 0),
    daysSinceLastBan: Number(cached?.daysSinceLastBan || 0),
    communityBanned: Boolean(cached?.communityBanned),
    economyBan: cached?.economyBan || 'none',
    economyRestricted: Boolean(cached?.economyRestricted),
    steamBanCheckedAt: cached?.steamBanCheckedAt || '',
    steamBanError: cached?.steamBanError || '',
    fetchedAt: cached?.fetchedAt || fallback.fetchedAt || '',
    source: cached?.source || fallback.source || '',
    error: cached?.error || '',
    officialKda: cached?.officialKda || null,
    officialKdaFetchedAt: cached?.officialKdaFetchedAt || '',
    officialKdaError: cached?.officialKdaError || '',
    battlemetrics: memberDisplayOnlineSummary(store, member, null, indexes),
    hexaytron: publicHexaytronProfilePayload(cached?.hexaytron || null)
  };
}

function publicBattlemetricsPlaytimePayload(summary = {}) {
  const serverSeconds = Number(summary.serverPlayTimeSeconds || 0);
  const totalSeconds = Number(summary.totalPlayTimeSeconds || 0);
  const weeklySeconds = Number(summary.weeklyPlayTimeSeconds || 0);
  return {
    wipeId: summary.wipeId || '',
    wipeName: summary.wipeName || '',
    wipeStatus: summary.wipeStatus || '',
    serverName: summary.serverName || '',
    battlemetricsPlayerId: summary.battlemetricsPlayerId || '',
    battlemetricsServerId: summary.battlemetricsServerId || '',
    lastOnlineAt: summary.lastOnlineAt || '',
    lastOfflineAt: summary.lastOfflineAt || '',
    serverPlayTimeSeconds: Number.isFinite(serverSeconds) ? serverSeconds : 0,
    serverPlayTimeMinutes: Number.isFinite(serverSeconds) ? Math.round(serverSeconds / 60) : 0,
    totalPlayTimeSeconds: Number.isFinite(totalSeconds) ? totalSeconds : 0,
    totalPlayTimeMinutes: Number.isFinite(totalSeconds) ? Math.round(totalSeconds / 60) : 0,
    weeklyPlayTimeSeconds: Number.isFinite(weeklySeconds) ? weeklySeconds : 0,
    weeklyPlayTimeMinutes: Number.isFinite(weeklySeconds) ? Math.round(weeklySeconds / 60) : 0,
    syncedAt: summary.syncedAt || '',
    error: summary.error || ''
  };
}

function memberProfileDetailPayload(store, memberId, viewer) {
  const indexes = getStoreIndexes(store);
  const rawMember = (store.members || []).find((item) => item.id === memberId);
  const member = rawMember ? enrichMember(store, rawMember, viewer, indexes) : null;
  if (!member) return null;
  const detail = queryMemberPayload(store, member, { detailed: true, viewer, indexes });
  return {
    ...detail,
    id: member.id,
    rawInput: member.rawInput || '',
    createdAt: member.createdAt || '',
    updatedAt: member.updatedAt || '',
    playSummary: memberPlaySummary(store, member.id),
    onlineSummary: memberDisplayOnlineSummary(store, member, viewer, indexes),
    profileStats: memberProfilePayload(store, member, indexes)
  };
}

function battlemetricsMatchNotesText(notes) {
  if (Array.isArray(notes)) return normalizeText(notes.map((note) => normalizeText(note, 120)).filter(Boolean).join('; '), 240);
  return normalizeText(notes, 240);
}

function setMemberBattlemetricsId(store, member, battlemetricsId, { source = 'manual', displayName = '', confidence = '', alias = '', notes = '' } = {}) {
  if (!member) return null;
  store.memberProfiles ||= [];
  const nextId = normalizeText(battlemetricsId, 80);
  const currentSummary = memberOnlineSummary(store, member);
  const previousId = normalizeText(member.battlemetricsId || currentSummary.battlemetricsPlayerId, 80);
  const idChanged = previousId !== nextId;
  const updatedAt = nowIso();
  member.battlemetricsId = nextId;
  member.updatedAt = updatedAt;

  const existingIndex = store.memberProfiles.findIndex((item) => item.memberId === member.id);
  const profile = existingIndex >= 0 ? store.memberProfiles[existingIndex] : {
    id: createId('member_profile'),
    memberId: member.id,
    steamId: member.steamId,
    profileUrl: steamProfileUrl(member.steamId)
  };

  profile.steamId = member.steamId;
  profile.profileUrl ||= steamProfileUrl(member.steamId);
  profile.battlemetricsPlayerId = nextId;
  profile.fetchedAt = updatedAt;
  profile.source = source;
  profile.battlemetricsError = '';
  profile.battlemetricsMatchConfidence = nextId ? normalizeText(confidence || source, 80) : '';
  profile.battlemetricsMatchAlias = nextId ? normalizeText(alias, 120) : '';
  profile.battlemetricsMatchNotes = nextId ? battlemetricsMatchNotesText(notes) : '';
  if (displayName) profile.displayName = normalizeText(displayName, 120);
  if (idChanged) {
    profile.battlemetricsServerId = '';
    profile.battlemetricsServerName = '';
    profile.battlemetricsWipeId = '';
    profile.battlemetricsWipeName = '';
    profile.battlemetricsWipeStatus = '';
    profile.battlemetricsLastOnlineAt = '';
    profile.battlemetricsLastOfflineAt = '';
    profile.battlemetricsTotalPlayTimeSeconds = 0;
    profile.battlemetricsServerPlayTimeSeconds = 0;
    profile.battlemetricsWeeklyPlayTimeSeconds = 0;
    profile.battlemetricsSyncedAt = '';
    profile.battlemetricsMatchFirstSeenAt = '';
    profile.battlemetricsMatchLastSeenAt = '';
    profile.battlemetricsMatchServerTimePlayedSeconds = 0;
    profile.battlemetricsSessionTruncated = false;
    profile.battlemetricsSessionFetchedPages = 0;
    profile.battlemetricsSessionPageLimit = 0;
    profile.battlemetricsRangeStopAt = '';
  }

  if (existingIndex >= 0) store.memberProfiles[existingIndex] = profile;
  else store.memberProfiles.push(profile);
  return profile;
}

function setMemberHexaytronProfile(store, member, profile) {
  if (!member || !profile) return null;
  store.memberProfiles ||= [];
  const existingIndex = store.memberProfiles.findIndex((item) => item.memberId === member.id);
  const existing = existingIndex >= 0 ? store.memberProfiles[existingIndex] : {
    id: createId('member_profile'),
    memberId: member.id,
    steamId: member.steamId,
    profileUrl: steamProfileUrl(member.steamId)
  };
  const nextProfile = {
    ...existing,
    memberId: member.id,
    steamId: member.steamId,
    profileUrl: existing.profileUrl || steamProfileUrl(member.steamId),
    hexaytron: {
      ...publicHexaytronProfilePayload(profile),
      guildId: normalizeText(profile.guildId || HEXAYTRON_DISCORD_GUILD_ID, DISCORD_ID_MAX_LENGTH),
      channelId: normalizeText(profile.channelId || HEXAYTRON_DISCORD_CHANNEL_ID, DISCORD_ID_MAX_LENGTH),
      requestMessageId: normalizeText(profile.requestMessageId, 80),
      requestCommand: normalizeText(profile.requestCommand, 160),
      sourceAuthorId: normalizeText(profile.sourceAuthorId, 80),
      sourceAuthorName: normalizeText(profile.sourceAuthorName, 120),
      rawText: normalizeText(profile.rawText, 2000)
    }
  };
  if (existingIndex >= 0) store.memberProfiles[existingIndex] = nextProfile;
  else store.memberProfiles.push(nextProfile);
  member.updatedAt = nowIso();
  return nextProfile;
}

function battlemetricsServerIdForWipe(wipe) {
  if (!wipe) return '';
  if (wipe.battlemetricsId) return String(wipe.battlemetricsId);
  const byVital = VITAL_RUST_2X_SERVERS.find((server) => server.vitalServerId === String(wipe.vitalServerId || ''));
  if (byVital?.battlemetricsId) return String(byVital.battlemetricsId);
  const byPreset = wipeServerPresetById(wipe.serverPresetId);
  if (byPreset?.battlemetricsId) return String(byPreset.battlemetricsId);
  const normalizedName = expandVitalRustName(wipe.serverName || wipe.name || '').toLowerCase();
  const byName = WIPE_SERVER_PRESETS.find((server) => normalizedName.includes(expandVitalRustName(server.name).toLowerCase()));
  return byName?.battlemetricsId ? String(byName.battlemetricsId) : '';
}

function battlemetricsWipeSyncInfo(wipe, serverId = '') {
  if (!wipe) {
    return { wipeId: '', wipeName: '', wipeStatus: '', serverId: serverId || '', serverName: '' };
  }
  return {
    wipeId: wipe.id || '',
    wipeName: expandVitalRustName(wipe.name || ''),
    wipeStatus: effectiveWipeStatus(wipe),
    serverId: serverId || battlemetricsServerIdForWipe(wipe),
    serverName: expandVitalRustName(wipe.serverName || wipe.name || '')
  };
}

function battlemetricsProfileSyncFields(wipe, serverId = '') {
  const syncInfo = battlemetricsWipeSyncInfo(wipe, serverId);
  return {
    battlemetricsWipeId: syncInfo.wipeId,
    battlemetricsWipeName: syncInfo.wipeName,
    battlemetricsWipeStatus: syncInfo.wipeStatus,
    battlemetricsServerId: syncInfo.serverId,
    battlemetricsServerName: syncInfo.serverName
  };
}

function battlemetricsUrl(route, query = {}) {
  const url = new URL(route, BATTLEMETRICS_API_BASE_URL);
  for (const [key, value] of Object.entries(query)) {
    if (value === null || value === undefined || value === '') continue;
    url.searchParams.set(key, String(value));
  }
  return url.toString();
}

const proxyAgentCache = new Map();

function createProxyAgent(proxyUrl, label = '代理配置') {
  const normalizedProxyUrl = validateProxyUrl(proxyUrl, label);
  if (!normalizedProxyUrl) return null;
  let parsed;
  try {
    parsed = new URL(normalizedProxyUrl);
  } catch {
    throw new Error(`${label}格式无效`);
  }
  if (['socks:', 'socks4:', 'socks4a:', 'socks5:', 'socks5h:'].includes(parsed.protocol)) {
    return new SocksProxyAgent(parsed);
  }
  if (['http:', 'https:'].includes(parsed.protocol)) {
    return new HttpsProxyAgent(parsed);
  }
  throw new Error(`${label}只支持 http, https, socks4, socks5, socks5h`);
}

function proxyAgentForUrl(proxyUrl, label = '代理配置') {
  const normalizedProxyUrl = validateProxyUrl(proxyUrl, label);
  if (!normalizedProxyUrl) return null;
  if (!proxyAgentCache.has(normalizedProxyUrl)) {
    proxyAgentCache.set(normalizedProxyUrl, createProxyAgent(normalizedProxyUrl, label));
  }
  return proxyAgentCache.get(normalizedProxyUrl);
}

async function serviceFetch(service, url, options = {}) {
  const store = await readServiceProxyStore();
  const proxy = proxySettingForService(store, service);
  if (!proxy.url || isLocalServiceUrl(url)) return fetch(url, options);
  const agent = proxyAgentForUrl(proxy.url, proxy.label);
  return nodeFetch(url, { ...options, agent });
}

function battlemetricsFetch(url, options = {}) {
  return serviceFetch('battlemetrics', url, options);
}

function kdaFetch(url, options = {}) {
  return serviceFetch('kda', url, options);
}

function kdaApiUrl(pathname) {
  const path = String(pathname || '');
  if (/^https?:\/\//i.test(path)) return path;
  if (!RUST_KDA_BASE_URL) return path.startsWith('/') ? path : `/${path}`;
  return `${RUST_KDA_BASE_URL}${path.startsWith('/') ? path : `/${path}`}`;
}

function battlemetricsSafeErrorMessage(response, text = '') {
  const body = String(text || '');
  const isCloudflareChallenge = response.status === 403 && /cloudflare|Just a moment|challenge-platform/i.test(body);
  if (isCloudflareChallenge) {
    const error = Object.assign(new Error('BattleMetrics API 被 Cloudflare 阻止，请稍后重试或配置可访问的代理'), {
      status: 503,
      code: 'battlemetrics_cloudflare_blocked',
      global: true
    });
    return error;
  }
  const contentType = response.headers.get('content-type') || '';
  if (contentType.includes('application/json')) {
    try {
      const payload = JSON.parse(body);
      const detail = payload?.errors?.[0]?.detail || payload?.errors?.[0]?.title || payload?.message || '';
      if (detail) {
        return Object.assign(new Error(`BattleMetrics HTTP ${response.status}: ${normalizeText(detail, 180)}`), { status: response.status });
      }
    } catch {
      // Fall through to generic error.
    }
  }
  return Object.assign(new Error(`BattleMetrics HTTP ${response.status}`), { status: response.status });
}

function retryAfterMs(value) {
  if (!value) return 0;
  const seconds = Number(value);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
  const dateMs = Date.parse(value);
  return Number.isFinite(dateMs) ? Math.max(0, dateMs - Date.now()) : 0;
}

function battlemetricsQueueSnapshot() {
  return battlemetricsQueue.snapshot();
}

const BATTLEMETRICS_PROVIDER = 'battlemetrics_api';

function battlemetricsProviderScope(queueMeta = {}) {
  return normalizeText(queueMeta?.operation, 80) || 'request';
}

function recordBattlemetricsProviderFailure(error, scope) {
  if (!error?.circuitOpen) recordExternalProviderFailure(BATTLEMETRICS_PROVIDER, error, scope);
}

function queueBattlemetricsJson(apiKey, route, options = {}) {
  const queueMeta = battlemetricsQueue.normalizeMeta(options.queue || {});
  const providerScope = battlemetricsProviderScope(queueMeta);
  const run = async (task) => {
    try {
      assertExternalProviderAvailable(BATTLEMETRICS_PROVIDER, providerScope);
      if (battlemetricsQueue.blockedUntilMs() > Date.now()) {
        throw Object.assign(new Error('BattleMetrics API 被 Cloudflare 阻止，请稍后重试或配置可访问的代理'), {
          status: 503,
          code: 'battlemetrics_cloudflare_blocked',
          global: true
        });
      }
      let attempt = 0;
      let lastError = null;
      const url = route.startsWith('http') ? route : battlemetricsUrl(route, options.query || {});
      while (attempt <= BATTLEMETRICS_MAX_RETRIES) {
        await battlemetricsQueue.waitTurn(queueMeta);
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), BATTLEMETRICS_REQUEST_TIMEOUT_MS);
        try {
          const response = await battlemetricsFetch(url, {
            method: options.method || 'GET',
            headers: {
              accept: 'application/json',
              ...(options.body ? { 'content-type': 'application/json' } : {}),
              ...(apiKey ? { authorization: `Bearer ${apiKey}` } : {})
            },
            signal: controller.signal,
            body: options.body ? JSON.stringify(options.body) : undefined
          });
          battlemetricsQueue.observeRateLimitHeaders(response.headers);
          if (response.status === 429) {
            clearTimeout(timeout);
            const delayMs = retryAfterMs(response.headers.get('retry-after')) || BATTLEMETRICS_RATE_LIMIT_WINDOW_MS;
            battlemetricsQueue.markRateLimited(delayMs);
            await sleep(delayMs);
            attempt += 1;
            continue;
          }
          const text = await response.text();
          clearTimeout(timeout);
          if (!response.ok) {
            const error = battlemetricsSafeErrorMessage(response, text);
            if (error.global && error.code === 'battlemetrics_cloudflare_blocked') {
              battlemetricsQueue.markBlocked(BATTLEMETRICS_BLOCKED_BACKOFF_MS);
              throw error;
            }
            if (response.status >= 500 && attempt < BATTLEMETRICS_MAX_RETRIES) {
              lastError = error;
              await sleep(Math.min(30_000, 1000 * 2 ** attempt));
              attempt += 1;
              continue;
            }
            throw error;
          }
          const payload = text ? JSON.parse(text) : null;
          recordExternalProviderSuccess(BATTLEMETRICS_PROVIDER, providerScope);
          return payload;
        } catch (error) {
          clearTimeout(timeout);
          lastError = error;
          if (error?.name === 'AbortError') {
            throw Object.assign(new Error(`BattleMetrics request timeout after ${BATTLEMETRICS_REQUEST_TIMEOUT_MS}ms`), { status: 504 });
          }
          if (error.status || attempt >= BATTLEMETRICS_MAX_RETRIES) throw error;
          await sleep(Math.min(30_000, 1000 * 2 ** attempt));
          attempt += 1;
        }
      }
      throw lastError || new Error('BattleMetrics request failed');
    } catch (error) {
      recordBattlemetricsProviderFailure(error, providerScope);
      throw error;
    }
  };
  return battlemetricsQueue.enqueue({ meta: queueMeta, run });
}

export const __battlemetricsProviderHealthForTests = {
  queueBattlemetricsJson,
  resetQueue: () => battlemetricsQueue.resetForTests()
};

function battlemetricsDocumentRows(document) {
  return [
    ...(Array.isArray(document?.data) ? document.data : (document?.data ? [document.data] : [])),
    ...(Array.isArray(document?.included) ? document.included : [])
  ];
}

function battlemetricsRelationshipPlayerRefs(relationships) {
  const refs = [];
  if (!relationships || typeof relationships !== 'object') return refs;
  for (const rel of Object.values(relationships)) {
    const values = Array.isArray(rel?.data) ? rel.data : (rel?.data ? [rel.data] : []);
    for (const value of values) {
      if (value?.type === 'player' && value.id) refs.push(value);
    }
  }
  return refs;
}

function extractBattlemetricsPlayers(document) {
  const rows = battlemetricsDocumentRows(document);
  const players = new Map();
  const visitRelationships = (relationships) => {
    for (const value of battlemetricsRelationshipPlayerRefs(relationships)) {
      if (!players.has(value.id)) {
        players.set(value.id, { type: 'player', id: value.id, attributes: {} });
      }
    }
  };
  for (const row of rows) {
    if (row?.type === 'player' && row.id) players.set(row.id, row);
    visitRelationships(row?.relationships);
  }
  return [...players.values()];
}

function extractBattlemetricsPlayerMatches(document) {
  const rows = battlemetricsDocumentRows(document);
  const playersById = new Map();
  for (const row of rows) {
    if (row?.type === 'player' && row.id) playersById.set(row.id, row);
  }
  for (const row of rows) {
    for (const ref of battlemetricsRelationshipPlayerRefs(row?.relationships)) {
      if (!playersById.has(ref.id)) playersById.set(ref.id, { type: 'player', id: ref.id, attributes: {} });
    }
  }

  const matches = new Map();
  for (const row of rows) {
    if (row?.type !== 'identifier') continue;
    const identifier = normalizeText(row?.attributes?.identifier || row?.id, 80);
    if (!identifier) continue;
    const playerRef = battlemetricsRelationshipPlayerRefs(row?.relationships)[0];
    const player = playerRef?.id ? playersById.get(playerRef.id) : null;
    if (player?.id) matches.set(identifier, player);
  }
  return matches;
}

function battlemetricsPlayerName(player) {
  return normalizeText(player?.attributes?.name || player?.attributes?.displayName || player?.attributes?.nickname || '', 120);
}

function battlemetricsComparableName(value) {
  return normalizeText(value, 120).toLocaleLowerCase('en-US');
}

function battlemetricsSearchAliasCandidates(member, cachedProfile = null) {
  const aliases = [
    member?.customName,
    member?.steamNickname,
    cachedProfile?.displayName,
    memberDisplayName(member)
  ];
  const seen = new Set();
  return aliases
    .map((value) => normalizeText(value, 120))
    .filter((value) => value && value.length >= BATTLEMETRICS_MIN_ALIAS_SEARCH_LENGTH)
    .filter((value) => !/^Steam \d{6}$/i.test(value))
    .filter((value) => {
      const key = battlemetricsComparableName(value);
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function battlemetricsRangeForWipe(wipe, now = new Date()) {
  const closedAtMs = timestampForSort(wipe?.closedAt);
  const rangeStop = wipe?.status === 'closed' && closedAtMs ? new Date(closedAtMs) : now;
  const weeklyRangeStart = new Date(rangeStop.getTime() - 7 * 24 * 60 * 60 * 1000);
  const serverRangeStart = wipeStartTimeMs(wipe) ? new Date(wipeStartTimeMs(wipe)) : weeklyRangeStart;
  const fetchRangeStart = serverRangeStart < weeklyRangeStart ? serverRangeStart : weeklyRangeStart;
  return { rangeStop, weeklyRangeStart, serverRangeStart, fetchRangeStart };
}

function battlemetricsAssignedPlayerOwners(members = [], profiles = []) {
  const owners = new Map();
  for (const member of members || []) {
    addBattlemetricsPlayerOwner(owners, member?.battlemetricsId, member?.id);
  }
  for (const profile of profiles || []) {
    addBattlemetricsPlayerOwner(owners, profile?.battlemetricsPlayerId, profile?.memberId);
  }
  return owners;
}

function memberNeedsBattlemetricsIdSync(member, profilesByMemberId = new Map()) {
  if (!member?.steamId) return false;
  if (normalizeText(member.battlemetricsId, 80)) return false;
  const profile = profilesByMemberId.get(member.id);
  return !normalizeText(profile?.battlemetricsPlayerId, 80);
}

function addBattlemetricsPlayerOwner(owners, playerId, memberId) {
  const normalizedPlayerId = normalizeText(playerId, 80);
  const normalizedMemberId = normalizeText(memberId, 120);
  if (!normalizedPlayerId || !normalizedMemberId) return;
  if (!owners.has(normalizedPlayerId)) owners.set(normalizedPlayerId, new Set());
  owners.get(normalizedPlayerId).add(normalizedMemberId);
}

function battlemetricsPlayerHasOtherOwner(owners, playerId, memberId) {
  const normalizedPlayerId = normalizeText(playerId, 80);
  const normalizedMemberId = normalizeText(memberId, 120);
  if (!normalizedPlayerId || !owners?.has(normalizedPlayerId)) return false;
  return [...owners.get(normalizedPlayerId)].some((ownerId) => ownerId && ownerId !== normalizedMemberId);
}

function battlemetricsDuplicateIdError() {
  return Object.assign(new Error('BattleMetrics 匹配到的 BM ID 已绑定其他成员'), { status: 409 });
}

function battlemetricsReviewCandidatePayload(verified = {}, playerName = '') {
  const player = verified.player || {};
  const serverInfo = verified.serverInfo || {};
  const attributes = serverInfo.attributes || {};
  const battlemetricsId = normalizeText(player.id, 80);
  if (!battlemetricsId) return null;
  return {
    battlemetricsId,
    displayName: normalizeText(playerName || battlemetricsPlayerName(player), 120),
    alias: normalizeText(verified.alias, 120),
    confidence: normalizeText(verified.confidence, 80),
    firstSeenAt: normalizeText(attributes.firstSeen, 80),
    lastSeenAt: normalizeText(attributes.lastSeen, 80),
    serverTimePlayedSeconds: Math.max(0, Number(attributes.timePlayed || 0)),
    online: Boolean(attributes.online)
  };
}

function battlemetricsServerInfoActiveInRange(serverInfo, serverRangeStart, rangeStop) {
  const firstSeenMs = timestampForSort(serverInfo?.attributes?.firstSeen);
  const lastSeenMs = timestampForSort(serverInfo?.attributes?.lastSeen);
  if (!firstSeenMs && !lastSeenMs) return false;
  if (lastSeenMs && lastSeenMs < serverRangeStart.getTime()) return false;
  if (firstSeenMs && firstSeenMs > rangeStop.getTime()) return false;
  return true;
}

async function verifyBattlemetricsPlayerOnServer({ apiKey, member, player, serverId, serverRangeStart, rangeStop, assignedPlayerOwners = null, confidence, alias = '', notes = [], queue = null }) {
  const playerId = normalizeText(player?.id, 80);
  if (!playerId) return null;
  if (battlemetricsPlayerHasOtherOwner(assignedPlayerOwners, playerId, member?.id)) {
    return { conflict: true, playerId };
  }
  if (!serverId || !serverRangeStart || !rangeStop) {
    return {
      player: { ...player, id: playerId },
      confidence,
      alias,
      notes
    };
  }
  let serverInfo = null;
  try {
    serverInfo = await battlemetricsPlayerServerInfo(apiKey, playerId, serverId, queue);
  } catch (error) {
    if (error.status === 404) return null;
    throw error;
  }
  if (!battlemetricsServerInfoActiveInRange(serverInfo, serverRangeStart, rangeStop)) return null;
  return {
    player: { ...player, id: playerId },
    serverInfo,
    confidence,
    alias,
    notes
  };
}

function battlemetricsMatchPayload(steamIds) {
  const payload = {
    data: steamIds.map((steamId) => ({
      type: 'identifier',
      attributes: {
        type: 'steamID',
        identifier: String(steamId)
      }
    }))
  };
  return payload;
}

async function battlemetricsMatchSteamIds(apiKey, steamIds, queue = null) {
  const normalizedSteamIds = [...new Set((steamIds || []).map((steamId) => normalizeText(steamId, 80)).filter(Boolean))];
  const matches = new Map();
  for (let index = 0; index < normalizedSteamIds.length; index += BATTLEMETRICS_MATCH_BATCH_SIZE) {
    const batch = normalizedSteamIds.slice(index, index + BATTLEMETRICS_MATCH_BATCH_SIZE);
    const response = await queueBattlemetricsJson(apiKey, '/players/match', {
      method: 'POST',
      body: battlemetricsMatchPayload(batch),
      queue: { ...queue, operation: 'match_players', label: 'Match SteamIDs to BattleMetrics players' }
    });
    const batchMatches = extractBattlemetricsPlayerMatches(response);
    for (const [steamId, player] of batchMatches) matches.set(steamId, player);
    if (batch.length === 1 && !matches.has(batch[0])) {
      const players = extractBattlemetricsPlayers(response);
      if (players[0]?.id) matches.set(batch[0], players[0]);
    }
  }
  return matches;
}

async function battlemetricsMatchSteamId(apiKey, steamId, queue = null) {
  const response = await queueBattlemetricsJson(apiKey, '/players/match', {
    method: 'POST',
    body: battlemetricsMatchPayload([steamId]),
    queue: { ...queue, operation: 'match_player', label: 'Match SteamID to BattleMetrics player' }
  });
  return extractBattlemetricsPlayers(response);
}

async function prefetchBattlemetricsPlayerMatches(apiKey, targets, profilesByMemberId, queue = null) {
  const attemptedSteamIds = new Set();
  const missingMatchSteamIds = [];
  for (const member of targets) {
    const cachedBattlemetricsId = normalizeText(member?.battlemetricsId || profilesByMemberId.get(member.id)?.battlemetricsPlayerId, 80);
    const steamId = normalizeText(member?.steamId, 80);
    if (cachedBattlemetricsId || !steamId) continue;
    attemptedSteamIds.add(steamId);
    missingMatchSteamIds.push(steamId);
  }
  if (!missingMatchSteamIds.length) return { attemptedSteamIds, playersBySteamId: new Map() };
  const playersBySteamId = await battlemetricsMatchSteamIds(apiKey, missingMatchSteamIds, queue);
  return { attemptedSteamIds, playersBySteamId };
}

async function battlemetricsPlayerServerInfo(apiKey, playerId, serverId, queue = null) {
  const response = await queueBattlemetricsJson(apiKey, `/players/${encodeURIComponent(playerId)}/servers/${encodeURIComponent(serverId)}`, {
    queue: { ...queue, operation: 'player_server', label: 'Fetch player server summary' }
  });
  return response?.data || null;
}

async function battlemetricsSearchPlayers(apiKey, alias, serverId, queue = null) {
  if (!alias || !serverId) return [];
  const response = await queueBattlemetricsJson(apiKey, '/players', {
    query: {
      'filter[search]': alias,
      'filter[servers]': serverId,
      'page[size]': BATTLEMETRICS_SEARCH_PAGE_SIZE
    },
    queue: { ...queue, operation: 'player_search', label: 'Search BattleMetrics players by nickname' }
  });
  return extractBattlemetricsPlayers(response);
}

async function resolveBattlemetricsPlayerByAlias({ apiKey, member, cachedProfile = null, serverId, serverRangeStart, rangeStop, assignedPlayerOwners = null, queue = null }) {
  if (!serverId) return null;
  const aliases = battlemetricsSearchAliasCandidates(member, cachedProfile);
  let duplicateConflict = false;
  let reviewCandidate = false;
  const reviewCandidates = [];

  for (const alias of aliases) {
    const aliasKey = battlemetricsComparableName(alias);
    const verifiedExactMatches = [];
    const candidates = await battlemetricsSearchPlayers(apiKey, alias, serverId, queue);
    for (const candidate of candidates) {
      const playerName = battlemetricsPlayerName(candidate);
      const isExactName = playerName && battlemetricsComparableName(playerName) === aliasKey;
      const verified = await verifyBattlemetricsPlayerOnServer({
        apiKey,
        member,
        player: candidate,
        serverId,
        serverRangeStart,
        rangeStop,
        assignedPlayerOwners,
        confidence: isExactName ? 'exact-active-name' : 'active-search-candidate',
        alias,
        notes: isExactName ? [] : ['BattleMetrics 昵称搜索非精确候选，需人工复核'],
        queue
      });
      if (verified?.conflict) {
        duplicateConflict = true;
        continue;
      }
      if (!verified) continue;
      const lastSeenMs = timestampForSort(verified.serverInfo?.attributes?.lastSeen);
      if (isExactName) verifiedExactMatches.push({ ...verified, lastSeenMs });
      else {
        reviewCandidate = true;
        const candidatePayload = battlemetricsReviewCandidatePayload(verified, playerName);
        if (candidatePayload) reviewCandidates.push(candidatePayload);
      }
    }

    if (verifiedExactMatches.length) {
      verifiedExactMatches.sort((left, right) => right.lastSeenMs - left.lastSeenMs);
      const winner = verifiedExactMatches[0];
      if (verifiedExactMatches.length > 1) {
        winner.notes = [
          ...(winner.notes || []),
          'BattleMetrics 昵称存在多个精确候选，已选择最近活跃记录'
        ];
      }
      return winner;
    }
  }

  if (duplicateConflict) throw battlemetricsDuplicateIdError();
  if (reviewCandidate) {
    throw Object.assign(new Error('BattleMetrics 昵称搜索仅找到待人工复核候选'), {
      status: 409,
      battlemetricsCandidates: normalizeBattlemetricsReviewCandidates(reviewCandidates)
    });
  }
  return null;
}

async function resolveBattlemetricsPlayerForMember({ apiKey, member, cachedProfile = null, matchedPlayer = undefined, serverId = '', serverRangeStart = null, rangeStop = null, assignedPlayerOwners = null, useCached = true, verifySteamMatch = true, queue = null }) {
  const explicitBattlemetricsId = normalizeText(member?.battlemetricsId, 80);
  const cachedProfileBattlemetricsId = normalizeText(cachedProfile?.battlemetricsPlayerId, 80);
  const cachedBattlemetricsId = explicitBattlemetricsId || cachedProfileBattlemetricsId;
  if (useCached && cachedBattlemetricsId) {
    if (battlemetricsPlayerHasOtherOwner(assignedPlayerOwners, cachedBattlemetricsId, member?.id)) {
      throw battlemetricsDuplicateIdError();
    }
    const cachedPlayer = { id: cachedBattlemetricsId, type: 'player', attributes: {} };
    const confidence = cachedProfile?.battlemetricsMatchConfidence || 'player-id';
    const alias = cachedProfile?.battlemetricsMatchAlias || '';
    const notes = [
      cachedProfile?.battlemetricsMatchNotes,
      serverId && serverRangeStart && rangeStop ? '缓存 BM ID 已通过当前服务器活跃范围复核' : ''
    ].filter(Boolean);
    let verifiedCached = null;
    try {
      verifiedCached = await verifyBattlemetricsPlayerOnServer({
        apiKey,
        member,
        player: cachedPlayer,
        serverId,
        serverRangeStart,
        rangeStop,
        assignedPlayerOwners,
        confidence,
        alias,
        notes,
        queue
      });
    } catch (error) {
      if (explicitBattlemetricsId && serverId && serverRangeStart && rangeStop && error?.status === 400) {
        throw Object.assign(new Error('已保存 BM ID，但当前服务器未找到该玩家记录'), {
          status: 404,
          battlemetricsId: explicitBattlemetricsId
        });
      }
      throw error;
    }
    if (verifiedCached?.conflict) throw battlemetricsDuplicateIdError();
    if (verifiedCached) return verifiedCached;
    if (explicitBattlemetricsId && serverId && serverRangeStart && rangeStop) {
      throw Object.assign(new Error('已保存 BM ID，但当前服务器未找到该玩家记录'), {
        status: 404,
        battlemetricsId: explicitBattlemetricsId
      });
    }
  }

  const steamMatchedPlayers = matchedPlayer !== undefined
    ? (matchedPlayer?.id ? [matchedPlayer] : [])
    : await battlemetricsMatchSteamId(apiKey, member.steamId, queue);
  let duplicateConflict = false;
  for (const player of steamMatchedPlayers) {
    const steamMatchServerId = verifySteamMatch ? serverId : '';
    const verified = await verifyBattlemetricsPlayerOnServer({
      apiKey,
      member,
      player,
      serverId: steamMatchServerId,
      serverRangeStart: verifySteamMatch ? serverRangeStart : null,
      rangeStop: verifySteamMatch ? rangeStop : null,
      assignedPlayerOwners,
      confidence: 'steam-match',
      queue
    });
    if (verified?.conflict) {
      duplicateConflict = true;
      continue;
    }
    if (verified) return verified;
  }
  if (duplicateConflict) throw battlemetricsDuplicateIdError();

  return resolveBattlemetricsPlayerByAlias({
    apiKey,
    member,
    cachedProfile,
    serverId,
    serverRangeStart,
    rangeStop,
    assignedPlayerOwners,
    queue
  });
}

function battlemetricsIdentityContext(store, requestedWipeId = 'current') {
  const wipe = battlemetricsTargetWipe(store, requestedWipeId);
  const serverId = battlemetricsServerIdForWipe(wipe);
  const range = wipe && serverId ? battlemetricsRangeForWipe(wipe) : {};
  return {
    wipe,
    serverId,
    serverRangeStart: range.serverRangeStart || null,
    rangeStop: range.rangeStop || null
  };
}

async function resolveBattlemetricsIdentityForMember({ apiKey, member, cachedProfile = null, matchedPlayer = undefined, wipe = null, serverId = '', serverRangeStart = null, rangeStop = null, assignedPlayerOwners = null, useCachedProfile = true, queue = null }) {
  const cachedBattlemetricsId = normalizeText(useCachedProfile ? cachedProfile?.battlemetricsPlayerId : '', 80);
  if (cachedBattlemetricsId) {
    if (battlemetricsPlayerHasOtherOwner(assignedPlayerOwners, cachedBattlemetricsId, member?.id)) {
      throw battlemetricsDuplicateIdError();
    }
    const verifiedCached = await verifyBattlemetricsPlayerOnServer({
      apiKey,
      member,
      player: { id: cachedBattlemetricsId, type: 'player', attributes: {} },
      serverId,
      serverRangeStart,
      rangeStop,
      assignedPlayerOwners,
      confidence: cachedProfile?.battlemetricsMatchConfidence || 'profile-cache',
      alias: cachedProfile?.battlemetricsMatchAlias || '',
      notes: [
        cachedProfile?.battlemetricsMatchNotes,
        serverId && serverRangeStart && rangeStop ? '缓存 BM ID 已通过当前服务器活跃范围复核' : ''
      ].filter(Boolean),
      queue
    });
    if (verifiedCached?.conflict) throw battlemetricsDuplicateIdError();
    if (verifiedCached) return verifiedCached;
  }

  return resolveBattlemetricsPlayerForMember({
    apiKey,
    member,
    cachedProfile,
    matchedPlayer,
    serverId,
    serverRangeStart,
    rangeStop,
    assignedPlayerOwners,
    useCached: false,
    verifySteamMatch: Boolean(serverId && serverRangeStart && rangeStop),
    queue
  });
}

async function battlemetricsPlayerSessions(apiKey, playerId, serverId, rangeStart, queue = null) {
  const sessions = [];
  const query = { 'page[size]': 100 };
  if (serverId) query['filter[servers]'] = serverId;
  let url = battlemetricsUrl(`/players/${encodeURIComponent(playerId)}/relationships/sessions`, query);
  let fetchedPages = 0;
  let reachedRangeStart = false;
  const seenUrls = new Set();
  for (let page = 0; url && page < BATTLEMETRICS_SESSION_PAGE_LIMIT; page += 1) {
    if (seenUrls.has(url)) break;
    seenUrls.add(url);
    const response = await queueBattlemetricsJson(apiKey, url, {
      queue: { ...queue, operation: 'player_sessions', label: 'Fetch player sessions' }
    });
    fetchedPages = page + 1;
    const rows = Array.isArray(response?.data) ? response.data : [];
    sessions.push(...rows);
    const oldest = rows[rows.length - 1];
    const oldestStop = Date.parse(oldest?.attributes?.stop || oldest?.attributes?.start || '');
    if (rangeStart && Number.isFinite(oldestStop) && oldestStop < rangeStart.getTime()) {
      reachedRangeStart = true;
      url = '';
      break;
    }
    url = response?.links?.next || '';
  }
  return {
    rows: sessions,
    fetchedPages,
    pageLimit: BATTLEMETRICS_SESSION_PAGE_LIMIT,
    truncated: Boolean(url && !reachedRangeStart),
    nextUrl: url || ''
  };
}

function battlemetricsTotalSessionSeconds(sessions = [], rangeStop = new Date()) {
  const rangeStart = new Date(0);
  return sessions.reduce((sum, session) => sum + clippedSessionSeconds(session, rangeStart, rangeStop), 0);
}

function clippedSessionSeconds(session, rangeStart, rangeStop) {
  const startedAt = new Date(session?.attributes?.start || '');
  const hasStop = Boolean(session?.attributes?.stop);
  const stoppedAt = hasStop ? new Date(session.attributes.stop) : rangeStop;
  if (Number.isNaN(startedAt.getTime()) || Number.isNaN(stoppedAt.getTime())) return 0;
  if (!hasStop && stoppedAt.getTime() - startedAt.getTime() > BATTLEMETRICS_MAX_OPEN_SESSION_MS) return 0;
  const clippedStart = startedAt < rangeStart ? rangeStart : startedAt;
  const clippedStop = stoppedAt > rangeStop ? rangeStop : stoppedAt;
  const durationMs = clippedStop.getTime() - clippedStart.getTime();
  return durationMs > 0 ? Math.round(durationMs / 1000) : 0;
}

function battlemetricsPlaytimeStats({ member, serverId, player, sessions, sessionMeta = {}, serverRangeStart, weeklyRangeStart, rangeStop }) {
  const playerId = player?.id || '';
  const scopedSessions = sessions.filter((session) => clippedSessionSeconds(session, serverRangeStart, rangeStop) > 0);
  const sortedSessions = scopedSessions.sort((left, right) => {
    const leftTime = Date.parse(left?.attributes?.start || left?.attributes?.stop || '') || 0;
    const rightTime = Date.parse(right?.attributes?.start || right?.attributes?.stop || '') || 0;
    return rightTime - leftTime;
  });
  const lastSession = sortedSessions[0] || null;
  const serverSeconds = sessions.reduce((sum, session) => sum + clippedSessionSeconds(session, serverRangeStart, rangeStop), 0);
  const weeklySeconds = sessions.reduce((sum, session) => sum + clippedSessionSeconds(session, weeklyRangeStart, rangeStop), 0);
  const isHistoricalRange = rangeStop.getTime() < Date.now() - 60_000;
  const isOnline = !isHistoricalRange && Boolean(lastSession && !lastSession?.attributes?.stop);
  return {
    battlemetricsPlayerId: playerId,
    battlemetricsServerId: String(serverId),
    battlemetricsLastOnlineAt: lastSession?.attributes?.start || '',
    battlemetricsLastOfflineAt: lastSession?.attributes?.stop || (isOnline ? '' : ''),
    battlemetricsServerPlayTimeSeconds: serverSeconds,
    battlemetricsWeeklyPlayTimeSeconds: weeklySeconds,
    battlemetricsSyncedAt: nowIso(),
    battlemetricsError: '',
    battlemetricsSessionTruncated: Boolean(sessionMeta.truncated),
    battlemetricsSessionFetchedPages: Number(sessionMeta.fetchedPages || 0),
    battlemetricsSessionPageLimit: Number(sessionMeta.pageLimit || BATTLEMETRICS_SESSION_PAGE_LIMIT),
    battlemetricsRangeStopAt: rangeStop.toISOString(),
    displayName: normalizeText(player?.attributes?.name || lastSession?.attributes?.name, 120) || undefined,
    profileUrl: steamProfileUrl(member.steamId)
  };
}

function mergeBattlemetricsPlaytimeStats(serverStats = {}, totalStats = {}) {
  const totalSeconds = Number(totalStats?.battlemetricsTotalPlayTimeSeconds || 0);
  return {
    ...totalStats,
    ...serverStats,
    battlemetricsPlayerId: serverStats?.battlemetricsPlayerId || totalStats?.battlemetricsPlayerId || '',
    battlemetricsTotalPlayTimeSeconds: Number.isFinite(totalSeconds) ? totalSeconds : 0,
    battlemetricsSyncedAt: serverStats?.battlemetricsSyncedAt || totalStats?.battlemetricsSyncedAt || nowIso(),
    battlemetricsError: totalStats?.battlemetricsError || serverStats?.battlemetricsError || ''
  };
}

async function fetchBattlemetricsMemberPlaytime({ apiKey, member, wipe, cachedProfile = null, matchedPlayer = undefined, assignedPlayerOwners = null, now = new Date(), queue = null }) {
  const serverId = battlemetricsServerIdForWipe(wipe);
  if (!serverId) throw new Error('当前服务器缺少 BattleMetrics Server ID');
  const { rangeStop, weeklyRangeStart, serverRangeStart, fetchRangeStart } = battlemetricsRangeForWipe(wipe, now);
  const resolution = await resolveBattlemetricsPlayerForMember({
    apiKey,
    member,
    cachedProfile,
    matchedPlayer,
    serverId,
    serverRangeStart,
    rangeStop,
    assignedPlayerOwners,
    queue
  });
  if (!resolution?.player?.id) throw new Error('BattleMetrics 未匹配到该 SteamID 或昵称');
  const sessionResult = await battlemetricsPlayerSessions(apiKey, resolution.player.id, serverId, fetchRangeStart, queue);
  return {
    ...battlemetricsPlaytimeStats({ member, serverId, player: resolution.player, sessions: sessionResult.rows, sessionMeta: sessionResult, serverRangeStart, weeklyRangeStart, rangeStop }),
    ...battlemetricsProfileSyncFields(wipe, serverId),
    battlemetricsMatchConfidence: resolution.confidence || '',
    battlemetricsMatchAlias: resolution.alias || '',
    battlemetricsMatchNotes: battlemetricsMatchNotesText(resolution.notes || ''),
    battlemetricsMatchFirstSeenAt: resolution.serverInfo?.attributes?.firstSeen || '',
    battlemetricsMatchLastSeenAt: resolution.serverInfo?.attributes?.lastSeen || '',
    battlemetricsMatchServerTimePlayedSeconds: Number(resolution.serverInfo?.attributes?.timePlayed || 0)
  };
}

async function syncRustplusRelayBattlemetricsOnlineFallback({ memberId = '', battlemetricsPlayerId = '', serverId = '', serverName = '', wipeId = '' } = {}) {
  return { updated: false, reason: 'disabled_for_member_profiles' };
}

async function fetchBattlemetricsTotalPlaytime({ apiKey, member, cachedProfile = null, matchedPlayer = undefined, assignedPlayerOwners = null, now = new Date(), queue = null }) {
  const resolution = await resolveBattlemetricsPlayerForMember({
    apiKey,
    member,
    cachedProfile,
    matchedPlayer,
    serverId: '',
    serverRangeStart: null,
    rangeStop: now,
    assignedPlayerOwners,
    verifySteamMatch: false,
    queue
  });
  if (!resolution?.player?.id) throw new Error('BattleMetrics 未匹配到该 SteamID 或昵称');
  const sessionResult = await battlemetricsPlayerSessions(apiKey, resolution.player.id, '', null, {
    ...queue,
    operation: 'player_total_sessions',
    label: 'Fetch player all-server sessions'
  });
  const totalSeconds = battlemetricsTotalSessionSeconds(sessionResult.rows, now);
  return {
    battlemetricsPlayerId: resolution.player.id,
    battlemetricsTotalPlayTimeSeconds: totalSeconds,
    battlemetricsSyncedAt: nowIso(),
    battlemetricsError: '',
    battlemetricsSessionTruncated: Boolean(sessionResult.truncated),
    battlemetricsSessionFetchedPages: Number(sessionResult.fetchedPages || 0),
    battlemetricsSessionPageLimit: Number(sessionResult.pageLimit || BATTLEMETRICS_SESSION_PAGE_LIMIT),
    battlemetricsRangeStopAt: now.toISOString(),
    battlemetricsMatchConfidence: resolution.confidence || '',
    battlemetricsMatchAlias: resolution.alias || '',
    battlemetricsMatchNotes: battlemetricsMatchNotesText(resolution.notes || ''),
    displayName: normalizeText(resolution.player?.attributes?.name, 120) || undefined,
    profileUrl: steamProfileUrl(member.steamId)
  };
}

function kdaSnapshotFromRow(row, capturedAt = nowIso()) {
  return {
    id: createId('kda_snapshot'),
    capturedAt,
    wipeId: row.wipeId,
    vitalWipeId: normalizeText(row.vitalWipeId, 120),
    memberId: row.memberId,
    steamId: row.steamId,
    kills: Number(row.kills || 0),
    deaths: Number(row.deaths || 0),
    assists: Number(row.assists || 0),
    t3Kills: Number(row.t3Kills || 0),
    kda: Number(row.kda || 0),
    rockets: Number(row.rockets || 0),
    sulfur: Number(row.sulfur || 0),
    metalOre: Number(row.metalOre || 0),
    building: Number(row.building || 0),
    playTimeMinutes: Number(row.playTimeMinutes || 0),
    onlineTimeMinutes: Number(row.onlineTimeMinutes || 0),
    onlineSummary: row.onlineSummary || null,
    source: row.source || '',
    syncedAt: row.syncedAt || capturedAt
  };
}

function recordKdaSnapshots(store, rows, capturedAt = nowIso()) {
  const snapshots = (rows || []).filter(Boolean).map((row) => kdaSnapshotFromRow(row, capturedAt));
  if (!snapshots.length) return;
  store.kdaSnapshots.push(...snapshots);
  if (store.kdaSnapshots.length > KDA_SNAPSHOT_LIMIT) {
    store.kdaSnapshots = store.kdaSnapshots.slice(-KDA_SNAPSHOT_LIMIT);
  }
}

function updateSettlementKdaRows(store, wipe, rows = []) {
  if (!wipe || wipe.status !== 'closed' || !rows.length) return;
  const settlement = store.wipeSettlements.find((item) => item.wipeId === wipe.id);
  if (!settlement?.kdaSnapshot?.length) return;
  const changedRows = rows.filter(Boolean);
  for (const row of changedRows) {
    const index = settlement.kdaSnapshot.findIndex((item) => (
      item.memberId === row.memberId ||
      (row.steamId && item.steamId === row.steamId)
    ));
    if (index >= 0) settlement.kdaSnapshot[index] = { ...settlement.kdaSnapshot[index], ...row };
    else settlement.kdaSnapshot.push(row);
  }
  settlement.summary = summaryForKdaRows(settlement.kdaSnapshot || [], settlement.participantsSnapshot || []);
}

function parseExportDate(value, label) {
  const normalized = normalizeText(value, 80);
  if (!normalized) return { iso: '', ms: null };
  const ms = Date.parse(normalized);
  if (!Number.isFinite(ms)) {
    throw Object.assign(new Error(`${label} 格式错误`), { status: 400 });
  }
  return { iso: new Date(ms).toISOString(), ms };
}

function exportTimeRangeFromQuery(query = {}) {
  const from = parseExportDate(query.from || query.start || query.startedAt, '开始时间');
  const to = parseExportDate(query.to || query.end || query.endedAt, '结束时间');
  if (from.ms !== null && to.ms !== null) {
    if (to.ms <= from.ms) throw Object.assign(new Error('结束时间必须晚于开始时间'), { status: 400 });
    if (to.ms - from.ms < 60 * 60 * 1000) throw Object.assign(new Error('时间范围最小 1 小时'), { status: 400 });
  }
  return {
    requested: from.ms !== null || to.ms !== null,
    from: from.iso,
    to: to.iso,
    fromMs: from.ms,
    toMs: to.ms
  };
}

function exportTimeRangeRequestedFromQuery(query = {}) {
  return [
    query.from,
    query.start,
    query.startedAt,
    query.to,
    query.end,
    query.endedAt
  ].some((value) => Boolean(normalizeText(value, 80)));
}

function kdaRowTimeMs(row) {
  return timestampForSort(row.capturedAt || row.syncedAt || row.updatedAt || row.createdAt);
}

function rowInTimeRange(row, range) {
  if (!range?.requested) return true;
  const time = kdaRowTimeMs(row);
  if (!time) return false;
  if (range.fromMs !== null && time < range.fromMs) return false;
  if (range.toMs !== null && time > range.toMs) return false;
  return true;
}

function deltaOnlineSummary(endSummary = {}, baselineSummary = null, onlineMinutes = 0) {
  const next = { ...(endSummary || {}) };
  const endServerSeconds = Number(endSummary?.serverPlayTimeSeconds || 0);
  const baselineServerSeconds = Number(baselineSummary?.serverPlayTimeSeconds || 0);
  const serverSeconds = Math.max(0, endServerSeconds - baselineServerSeconds);
  const endWeeklySeconds = Number(endSummary?.weeklyPlayTimeSeconds || 0);
  const baselineWeeklySeconds = Number(baselineSummary?.weeklyPlayTimeSeconds || 0);
  const weeklySeconds = Math.max(0, endWeeklySeconds - baselineWeeklySeconds);
  const minutes = Math.max(0, Number(onlineMinutes || Math.round(serverSeconds / 60) || 0));
  next.serverPlayTimeSeconds = serverSeconds || minutes * 60;
  next.serverPlayTimeMinutes = minutes;
  next.onlineTimeSeconds = next.serverPlayTimeSeconds;
  next.onlineTimeMinutes = minutes;
  next.weeklyPlayTimeSeconds = weeklySeconds;
  next.weeklyPlayTimeMinutes = Math.round(weeklySeconds / 60);
  next.rangeDelta = Boolean(baselineSummary);
  return next;
}

function deltaKdaRow(endRow, baselineRow = null) {
  const numericKeys = ['kills', 'deaths', 'assists', 't3Kills', 'rockets', 'sulfur', 'metalOre', 'building', 'playTimeMinutes', 'onlineTimeMinutes'];
  const next = { ...endRow };
  for (const key of numericKeys) {
    const value = Number(endRow?.[key] || 0) - Number(baselineRow?.[key] || 0);
    next[key] = Math.max(0, value);
  }
  const denominator = Math.max(Number(next.deaths || 0), 1);
  next.kda = Number(((Number(next.kills || 0) + Number(next.assists || 0)) / denominator).toFixed(2));
  next.syncedAt = endRow.syncedAt || endRow.capturedAt || '';
  next.capturedAt = endRow.capturedAt || endRow.syncedAt || '';
  if (endRow.onlineSummary || baselineRow?.onlineSummary) {
    next.onlineSummary = deltaOnlineSummary(endRow.onlineSummary || {}, baselineRow?.onlineSummary || null, next.onlineTimeMinutes);
  }
  next.source = endRow.source || '';
  return next;
}

function kdaRowsForTimeRange(store, wipe, range) {
  if (!range?.requested) return null;
  const snapshots = (store.kdaSnapshots || [])
    .filter((row) => row.wipeId === wipe.id && kdaRecordMatchesVitalWipe(row, wipe))
    .sort((left, right) => kdaRowTimeMs(left) - kdaRowTimeMs(right));
  if (!snapshots.length) return [];

  const rowsByMemberId = new Map();
  for (const row of snapshots) {
    if (!rowsByMemberId.has(row.memberId)) rowsByMemberId.set(row.memberId, []);
    rowsByMemberId.get(row.memberId).push(row);
  }

  const rows = [];
  const toMs = range.toMs ?? Date.now();
  for (const memberRows of rowsByMemberId.values()) {
    const endRow = [...memberRows].reverse().find((row) => {
      const time = kdaRowTimeMs(row);
      if (!time || time > toMs) return false;
      return range.fromMs === null || time >= range.fromMs;
    });
    if (!endRow) continue;
    const baselineRow = range.fromMs === null
      ? null
      : [...memberRows].reverse().find((row) => {
          const time = kdaRowTimeMs(row);
          return time && time < range.fromMs;
        }) || null;
    rows.push(deltaKdaRow(endRow, baselineRow));
  }
  return rows;
}

function generatedKdaRow(store, wipe, member) {
  const seed = hashNumber(`${wipe.id}:${member.steamId}`);
  const kills = seed % 90;
  const deaths = Math.floor(seed / 7) % 35;
  const assists = Math.floor(seed / 13) % 24;
  const sulfur = (Math.floor(seed / 17) % 480) * 100;
  const metalOre = (Math.floor(seed / 23) % 900) * 100;
  const building = Math.floor(seed / 31) % 260;
  const t3Kills = Math.floor(seed / 41) % Math.max(kills + 1, 1);
  const rockets = Math.floor(seed / 43) % 90;
  const playTimeMinutes = 120 + (Math.floor(seed / 37) % 3600);
  const denominator = Math.max(deaths, 1);
  const profileTimeFields = kdaProfileTimeFields(store, wipe, member);
  return {
    id: createId('kda'),
    wipeId: wipe.id,
    memberId: member.id,
    steamId: member.steamId,
    kills,
    deaths,
    assists,
    t3Kills,
    kd: Number((kills / denominator).toFixed(2)),
    kda: Number(((kills + assists) / denominator).toFixed(2)),
    rockets,
    sulfur,
    metalOre,
    building,
    onlineTimeMinutes: Number(profileTimeFields.onlineTimeMinutes || 0),
    ...(profileTimeFields.onlineSummary ? { onlineSummary: profileTimeFields.onlineSummary } : {}),
    playTimeMinutes: Number(profileTimeFields.playTimeMinutes || playTimeMinutes),
    raw: { generated: true },
    source: 'local_demo',
    syncedAt: nowIso()
  };
}

function wipeAvailableParticipants(store, wipe) {
  if (!wipe?.id) return [];
  return (store.wipeParticipants || []).filter((item) => item.wipeId === wipe.id && isParticipantAvailable(item.status));
}

function markAllMembersKdaScope(wipe, at = nowIso()) {
  if (!wipe || wipeHasAllMembersKdaScope(wipe)) return wipe;
  wipe.kdaMemberScope = 'all_members';
  wipe.kdaMemberScopeUpdatedAt = at;
  return wipe;
}

function kdaSyncTargetParticipants(store, wipe) {
  const participants = wipeAvailableParticipants(store, wipe);
  if (!kdaSyncUsesAllMembers(store, wipe)) return participants;
  const participantByMemberId = new Map(participants.map((participant) => [participant.memberId, participant]));
  return (store.members || [])
    .filter((member) => normalizeText(member.steamId, 32))
    .map((member) => participantByMemberId.get(member.id) || {
      id: `kda_target_${wipe.id}_${member.id}`,
      wipeId: wipe.id,
      memberId: member.id,
      status: 'all_members'
    });
}

function syncKdaRows(store, wipe) {
  if (process.env.NB_DISABLE_EXTERNAL_VITAL !== '1') return false;
  if (kdaSyncUsesAllMembers(store, wipe)) markAllMembersKdaScope(wipe);
  const participants = kdaSyncTargetParticipants(store, wipe);
  const membersById = new Map(store.members.map((member) => [member.id, member]));
  const existingKeys = new Set(store.kdaRows.filter((row) => row.wipeId === wipe.id).map((row) => row.memberId));
  let changed = false;
  const changedRows = [];
  for (const participant of participants) {
    if (existingKeys.has(participant.memberId)) continue;
    const member = membersById.get(participant.memberId);
    if (!member) continue;
    const row = generatedKdaRow(store, wipe, member);
    store.kdaRows.push(row);
    changedRows.push(row);
    changed = true;
  }
  recordKdaSnapshots(store, changedRows);
  return changed;
}

async function syncGeneratedKdaRowsForWipeIfNeeded(wipeId, reason = 'kda_generated_rows_refresh', options = {}) {
  if (process.env.NB_DISABLE_EXTERNAL_VITAL !== '1') return false;
  const normalizedWipeId = normalizeText(wipeId, 120);
  if (!normalizedWipeId || normalizedWipeId === 'current') return false;
  if (!sqlitePrimaryMode()) {
    return updateStore((store) => {
      const wipe = store.wipes.find((item) => item.id === normalizedWipeId);
      if (!wipe || (wipe.status !== 'closed' && !isWipeStartedServer(wipe))) return false;
      if (wipe.status === 'closed' && !options.allowClosed) return false;
      const changed = syncKdaRows(store, wipe);
      if (options.refreshSettlement && wipe.status === 'closed') refreshSettlementSnapshotForWipe(store, wipe);
      return changed;
    });
  }

  return runStoreWriteTask(async () => {
    const store = await readGeneratedKdaRowsWriteStore(normalizedWipeId, options);
    const wipe = store.wipes.find((item) => item.id === normalizedWipeId);
    if (!wipe || (wipe.status !== 'closed' && !isWipeStartedServer(wipe))) return false;
    if (wipe.status === 'closed' && !options.allowClosed) return false;
    const collections = [
      'wipes',
      'kdaRows',
      'kdaSnapshots',
      ...(options.refreshSettlement ? ['wipeSettlements'] : [])
    ];
    const before = snapshotStoreCollections(store, collections);
    const generatedChanged = syncKdaRows(store, wipe);
    if (options.refreshSettlement && wipe.status === 'closed') refreshSettlementSnapshotForWipe(store, wipe);

    const { upserts, deletes, changed } = diffStoreCollections(before, store, collections);
    if (!changed) return false;
    await writeSqliteStorePatch({ reason, upserts, deletes });
    await patchStoreCache((cachedStore) => {
      applyStoreCollectionCachePatch(cachedStore, collections, upserts, deletes);
    });
    return generatedChanged;
  });
}

async function refreshGeneratedKdaRowsForReadStore(store, wipe, reason = 'kda_generated_rows_refresh', options = {}) {
  if (!store || !wipe || wipe.status === 'closed' || !isWipeStartedServer(wipe)) return wipe;
  await syncGeneratedKdaRowsForWipeIfNeeded(wipe.id, reason);
  const refreshedStore = await readKdaRuntimeStore({
    wipeIds: [wipe.id],
    includeKdaSnapshots: Boolean(options.includeKdaSnapshots),
    scopeMembersToRows: true
  });
  const refreshedWipe = refreshedStore.wipes.find((item) => item.id === wipe.id);
  if (!refreshedWipe) return wipe;
  store.wipes = refreshedStore.wipes;
  store.members = refreshedStore.members;
  store.squads = refreshedStore.squads;
  store.squadMembers = refreshedStore.squadMembers;
  store.wipeParticipants = refreshedStore.wipeParticipants;
  store.kdaRows = refreshedStore.kdaRows;
  store.kdaSnapshots = refreshedStore.kdaSnapshots;
  store.wipeSettlements = refreshedStore.wipeSettlements;
  store.memberProfiles = refreshedStore.memberProfiles;
  store.uploads = refreshedStore.uploads;
  store.syncState = refreshedStore.syncState || store.syncState || {};
  return refreshedWipe;
}

function vitalStatNumber(stats, path) {
  const parts = String(path || '').split('.');
  let cursor = stats || {};
  for (let index = 0; index < parts.length; index += 1) {
    const remaining = parts.slice(index).join('.');
    if (cursor && Object.hasOwn(cursor, remaining)) {
      const numeric = Number(cursor[remaining]);
      return Number.isFinite(numeric) ? numeric : 0;
    }
    const part = parts[index];
    if (cursor == null || cursor[part] == null) return 0;
    cursor = cursor[part];
  }
  const numeric = Number(cursor);
  return Number.isFinite(numeric) ? numeric : 0;
}

function sumNumericLeafValues(value) {
  if (value == null) return 0;
  if (typeof value !== 'object') {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : 0;
  }
  return Object.values(value).reduce((total, item) => total + sumNumericLeafValues(item), 0);
}

function vitalPlayerToKdaRow(store, wipe, member, payload, existing = null) {
  const stats = payload?.statistics || {};
  const kills = vitalStatNumber(stats, 'combat.kills');
  const deaths = vitalStatNumber(stats, 'combat.deaths');
  const assists = 0;
  const denominator = Math.max(deaths, 1);
  const profileTimeFields = kdaProfileTimeFields(store, wipe, member);
  const existingOnlineSummary = battlemetricsOnlineSummaryTrustedForWipe(existing?.onlineSummary, wipe)
    ? existing.onlineSummary
    : null;
  const existingOnlineTimeMinutes = existingOnlineSummary
    ? kdaRowOnlineMinutesForWipe(existing, existingOnlineSummary, wipe)
    : 0;
  const existingPlayTimeMinutes = Number(existing?.playTimeMinutes || 0);
  const payloadPlayTimeMinutes = playTimeMinutesFromPayload(payload);
  const onlineSummary = existingOnlineTimeMinutes > 0
    ? existingOnlineSummary
    : profileTimeFields.onlineSummary || existingOnlineSummary;
  return {
    id: existing?.id || createId('kda'),
    wipeId: wipe.id,
    vitalWipeId: normalizeText(wipe.vitalWipeId, 120),
    memberId: member.id,
    steamId: member.steamId,
    kills,
    deaths,
    assists,
    t3Kills: vitalStatNumber(stats, 'combat.killsT3'),
    kd: Number((kills / denominator).toFixed(2)),
    kda: Number((kills / denominator).toFixed(2)),
    rockets: vitalStatNumber(stats, 'raiding.rockets'),
    sulfur: vitalStatNumber(stats, 'farming.gathered.sulfur.ore'),
    metalOre: vitalStatNumber(stats, 'farming.gathered.metal.ore'),
    building: sumNumericLeafValues(stats.building?.buildings),
    onlineTimeMinutes: existingOnlineTimeMinutes > 0 ? existingOnlineTimeMinutes : Number(profileTimeFields.onlineTimeMinutes || 0),
    ...(onlineSummary ? { onlineSummary } : {}),
    playTimeMinutes: payloadPlayTimeMinutes || existingPlayTimeMinutes || Number(profileTimeFields.playTimeMinutes || 0),
    raw: payload,
    source: 'vital',
    syncedAt: nowIso()
  };
}

function battlemetricsOnlineOnlyKdaRow(store, wipe, member, existing = null) {
  const profileTimeFields = kdaProfileTimeFields(store, wipe, member);
  const existingOnlineSummary = battlemetricsOnlineSummaryTrustedForWipe(existing?.onlineSummary, wipe)
    ? existing.onlineSummary
    : null;
  const onlineSummary = profileTimeFields.onlineSummary || existingOnlineSummary || null;
  const onlineTimeMinutes = Number(profileTimeFields.onlineTimeMinutes || kdaRowOnlineMinutesForWipe(existing, existingOnlineSummary, wipe) || 0);
  if (!onlineTimeMinutes && !onlineSummary?.battlemetricsPlayerId && !onlineSummary?.syncedAt) return null;
  const kills = Number(existing?.kills || 0);
  const deaths = Number(existing?.deaths || 0);
  const assists = Number(existing?.assists || 0);
  const denominator = Math.max(deaths, 1);
  return {
    id: existing?.id || createId('kda'),
    wipeId: wipe.id,
    memberId: member.id,
    steamId: member.steamId,
    kills,
    deaths,
    assists,
    t3Kills: Number(existing?.t3Kills || 0),
    kd: Number((kills / denominator).toFixed(2)),
    kda: Number(((kills + assists) / denominator).toFixed(2)),
    rockets: Number(existing?.rockets || 0),
    sulfur: Number(existing?.sulfur || 0),
    metalOre: Number(existing?.metalOre || 0),
    building: Number(existing?.building || 0),
    onlineTimeMinutes,
    ...(onlineSummary ? { onlineSummary } : {}),
    playTimeMinutes: Number(existing?.playTimeMinutes || profileTimeFields.playTimeMinutes || 0),
    raw: existing?.raw || { battlemetricsOnlineOnly: true },
    source: existing?.source && existing.source !== 'local_demo' ? existing.source : 'battlemetrics_online',
    syncedAt: onlineSummary?.syncedAt || existing?.syncedAt || nowIso()
  };
}

function ensureBattlemetricsOnlineKdaRows(store, wipe, requestedMemberIds = null, { skipMemberIds = new Set() } = {}) {
  if (!wipe) return [];
  const requested = requestedMemberIds ? new Set(requestedMemberIds) : null;
  const skipped = new Set(skipMemberIds || []);
  const membersById = new Map(store.members.map((member) => [member.id, member]));
  const existingIndexByMemberId = new Map(store.kdaRows.map((row, index) => [`${row.wipeId}:${row.memberId}`, index]));
  const changedRows = [];
  const participants = kdaSyncUsesAllMembers(store, wipe)
    ? kdaSyncTargetParticipants(store, wipe)
    : wipeAvailableParticipants(store, wipe);
  for (const participant of participants) {
    if (participant.wipeId !== wipe.id) continue;
    if (requested && !requested.has(participant.memberId)) continue;
    if (skipped.has(participant.memberId)) continue;
    const member = membersById.get(participant.memberId);
    if (!member?.steamId) continue;
    const existingIndex = existingIndexByMemberId.get(`${wipe.id}:${member.id}`);
    const existing = existingIndex !== undefined ? store.kdaRows[existingIndex] : null;
    const row = battlemetricsOnlineOnlyKdaRow(store, wipe, member, existing);
    if (!row) continue;
    if (existingIndex !== undefined) store.kdaRows[existingIndex] = row;
    else {
      store.kdaRows.push(row);
      existingIndexByMemberId.set(`${wipe.id}:${member.id}`, store.kdaRows.length - 1);
    }
    changedRows.push(row);
  }
  return changedRows;
}

function vitalKdaProviderScope(wipe = {}) {
  return [
    'server',
    normalizeText(wipe.vitalServerId, 40) || 'unknown',
    'wipe',
    normalizeText(wipe.vitalWipeId || wipe.id, 120) || 'all'
  ].join(':');
}

async function fetchVitalRowsBatch(wipe, steamIds, includes = VITAL_KDA_INCLUDES, attempt = 0) {
  const scope = vitalKdaProviderScope(wipe);
  try {
    assertExternalProviderAvailable('vital_kda', scope);
    const payload = {
      playerIds: steamIds,
      serverId: Number(wipe.vitalServerId),
      includes
    };
    if (wipe.vitalWipeId) payload.wipeId = wipe.vitalWipeId;
    const rows = await fetchVitalPlayersOverview(payload);
    recordExternalProviderSuccess('vital_kda', scope);
    return rows;
  } catch (error) {
    if (Number(error?.status) === 429 && attempt < 3) {
      const delay = (attempt + 1) * 2500;
      await sleep(delay);
      return fetchVitalRowsBatch(wipe, steamIds, includes, attempt + 1);
    }
    if (error?.circuitOpen) throw error;
    if (!error?.circuitOpen) recordExternalProviderFailure('vital_kda', error, scope);
    const responseMessage = normalizeText(error?.payload?.error || error?.payload?.message || error?.message, 240);
    throw Object.assign(new Error(`Vital KDA HTTP ${error?.status || 502}${responseMessage ? `: ${responseMessage}` : ''}`), { status: 502 });
  }
}

async function fetchVitalKdaBatch(wipe, steamIds, attempt = 0) {
  return fetchVitalRowsBatch(wipe, steamIds, VITAL_KDA_INCLUDES, attempt);
}

async function fetchVitalKdaRows(wipe, steamIds, { shouldCancel = null, includes = VITAL_KDA_INCLUDES } = {}) {
  const rows = [];
  for (let index = 0; index < steamIds.length; index += VITAL_KDA_BATCH_SIZE) {
    if (shouldCancel && await shouldCancel()) throw createSyncCancelledError();
    const batch = steamIds.slice(index, index + VITAL_KDA_BATCH_SIZE);
    rows.push(...await fetchVitalRowsBatch(wipe, batch, includes));
    if (shouldCancel && await shouldCancel()) throw createSyncCancelledError();
    if (index + VITAL_KDA_BATCH_SIZE < steamIds.length) {
      await sleep(VITAL_KDA_SYNC_DELAY_MS);
      if (shouldCancel && await shouldCancel()) throw createSyncCancelledError();
    }
  }
  return rows;
}

async function fetchVitalLookupRows(wipe, steamIds) {
  const rows = [];
  for (let index = 0; index < steamIds.length; index += VITAL_KDA_BATCH_SIZE) {
    const batch = steamIds.slice(index, index + VITAL_KDA_BATCH_SIZE);
    rows.push(...await fetchVitalRowsBatch(wipe, batch, VITAL_LOOKUP_INCLUDES));
    if (index + VITAL_KDA_BATCH_SIZE < steamIds.length) {
      await sleep(VITAL_KDA_SYNC_DELAY_MS);
    }
  }
  return rows;
}

function memberProfileKdaFallbackCacheKey(wipe, steamId) {
  return `${wipe?.id || ''}:${wipe?.vitalServerId || ''}:${wipe?.vitalWipeId || ''}:${normalizeText(steamId, 80)}`;
}

function readMemberProfileKdaFallbackCache(key) {
  const cached = memberProfileKdaFallbackCache.get(key);
  if (!cached) return { hit: false, row: null };
  if (cached.expiresAt <= Date.now()) {
    memberProfileKdaFallbackCache.delete(key);
    return { hit: false, row: null };
  }
  return { hit: true, row: cached.row || null };
}

function writeMemberProfileKdaFallbackCache(key, row) {
  if (!MEMBER_PROFILE_KDA_FALLBACK_CACHE_TTL_MS) return;
  if (memberProfileKdaFallbackCache.size >= RUST_KDA_CACHE_MAX_ENTRIES) {
    const oldestKey = memberProfileKdaFallbackCache.keys().next().value;
    if (oldestKey) memberProfileKdaFallbackCache.delete(oldestKey);
  }
  memberProfileKdaFallbackCache.set(key, {
    row: row || null,
    expiresAt: Date.now() + MEMBER_PROFILE_KDA_FALLBACK_CACHE_TTL_MS
  });
}

function canFetchMemberProfileKdaFallback(wipe, member) {
  if (process.env.NB_DISABLE_EXTERNAL_VITAL === '1') return false;
  if (!wipe || !member?.steamId) return false;
  if (wipe.status !== 'closed' && !isWipeStartedServer(wipe)) return false;
  return wipeKdaCapability(wipe).kdaSyncAvailable;
}

async function fetchMemberProfileKdaFallbackRow(store, wipe, member) {
  if (!canFetchMemberProfileKdaFallback(wipe, member)) return null;
  const key = memberProfileKdaFallbackCacheKey(wipe, member.steamId);
  const cached = readMemberProfileKdaFallbackCache(key);
  if (cached.hit) return cached.row;
  const inFlight = memberProfileKdaFallbackInFlight.get(key);
  if (inFlight) return inFlight;
  const request = fetchVitalKdaRows(wipe, [member.steamId])
    .then((payloadRows) => {
      const payload = (payloadRows || []).find((item) => normalizeText(item?.context?.userId, 80) === member.steamId) || null;
      const row = payload ? vitalPlayerToKdaRow(store, wipe, member, payload, null) : null;
      writeMemberProfileKdaFallbackCache(key, row);
      return row;
    })
    .catch((error) => {
      if (envFlagEnabled(process.env.NB_DEBUG_MEMBER_PROFILE_KDA_FALLBACK)) {
        console.warn('[nb-clan] member profile KDA fallback failed:', error?.message || error);
      }
      return null;
    })
    .finally(() => {
      memberProfileKdaFallbackInFlight.delete(key);
    });
  memberProfileKdaFallbackInFlight.set(key, request);
  return request;
}

async function enrichMemberProfileDetailCurrentKda(store, memberId, viewer, detail) {
  if (!detail || detail.currentKda || !viewer || !canViewWipesInStore(store, viewer)) return detail;
  if (!canViewOperationalData(viewer, store)) return detail;
  const indexes = getStoreIndexes(store);
  const rawMember = (store.members || []).find((item) => item.id === memberId);
  const member = rawMember ? enrichMember(store, rawMember, viewer, indexes) : null;
  if (!member) return detail;
  const wipe = queryReferenceWipe(store);
  if (!wipe || !canViewWipeRecord(store, wipe, viewer)) return detail;
  const row = await fetchMemberProfileKdaFallbackRow(store, wipe, member);
  const currentKda = currentMemberKdaPayloadFromRow(store, wipe, row, member);
  return currentKda ? { ...detail, currentKda } : detail;
}

const rustKdaJsonInFlight = new Map();
const rustKdaJsonCache = new Map();
const memberProfileKdaFallbackInFlight = new Map();
const memberProfileKdaFallbackCache = new Map();

function isRustKdaInventoryPath(pathname) {
  return /^\/?api\/inventory\//.test(String(pathname || ''));
}

function rustKdaRequestTimeoutMs(pathname) {
  return isRustKdaInventoryPath(pathname) ? RUST_KDA_INVENTORY_REQUEST_TIMEOUT_MS : RUST_KDA_REQUEST_TIMEOUT_MS;
}

function rustKdaCacheTtlMs(pathname) {
  return isRustKdaInventoryPath(pathname) ? RUST_KDA_INVENTORY_CACHE_TTL_MS : RUST_KDA_CACHE_TTL_MS;
}

function rustKdaCacheKey(pathname) {
  return String(pathname || '').replace(/^\/+/, '/');
}

function rustKdaProviderScope(pathname) {
  if (isRustKdaInventoryPath(pathname)) return 'inventory';
  if (/^\/?api\/player\//.test(String(pathname || ''))) return 'player';
  if (/^\/?api\/kda\//.test(String(pathname || ''))) return 'official_kda';
  return 'http';
}

function readRustKdaJsonCache(key) {
  const cached = rustKdaJsonCache.get(key);
  if (!cached) return null;
  if (cached.expiresAt <= Date.now()) {
    rustKdaJsonCache.delete(key);
    return null;
  }
  return cached.payload;
}

function writeRustKdaJsonCache(key, payload, ttlMs) {
  if (!ttlMs) return;
  if (rustKdaJsonCache.size >= RUST_KDA_CACHE_MAX_ENTRIES) {
    const oldestKey = rustKdaJsonCache.keys().next().value;
    if (oldestKey) rustKdaJsonCache.delete(oldestKey);
  }
  rustKdaJsonCache.set(key, { payload, expiresAt: Date.now() + ttlMs });
}

async function fetchRustKdaJsonUncached(pathname, attempt = 0, options = {}) {
  if (!RUST_KDA_HTTP_PROVIDER_ENABLED) {
    return fetchInternalRustKdaJson(pathname, {
      steamWebApiKey: options.steamWebApiKey || options.steamApiKey || ''
    });
  }
  const providerScope = rustKdaProviderScope(pathname);
  assertExternalProviderAvailable('rust_kda_http', providerScope);
  const requestedTimeoutMs = Number(options.timeoutMs || 0);
  const timeoutMs = Number.isFinite(requestedTimeoutMs) && requestedTimeoutMs > 0
    ? Math.max(1000, requestedTimeoutMs)
    : rustKdaRequestTimeoutMs(pathname);
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await kdaFetch(kdaApiUrl(pathname), { signal: controller.signal });
    if (response.status === 429 && attempt < 3) {
      const retryAfter = Number(response.headers.get('retry-after'));
      const delay = Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : (attempt + 1) * 3000;
      clearTimeout(timeout);
      await sleep(delay);
      return fetchRustKdaJsonUncached(pathname, attempt + 1, options);
    }
    if (!response.ok) {
      throw Object.assign(new Error(`Rust KDA HTTP ${response.status}`), { status: response.status });
    }
    const payload = await response.json();
    recordExternalProviderSuccess('rust_kda_http', providerScope);
    return payload;
  } catch (error) {
    if (error?.circuitOpen) throw error;
    if (error?.name === 'AbortError') {
      const timeoutError = Object.assign(new Error(`Rust KDA request timeout after ${timeoutMs}ms`), { status: 504 });
      recordExternalProviderFailure('rust_kda_http', timeoutError, providerScope);
      throw timeoutError;
    }
    recordExternalProviderFailure('rust_kda_http', error, providerScope);
    throw error;
  } finally {
    clearTimeout(timeout);
  }
}

async function fetchRustKdaJson(pathname, attempt = 0, options = {}) {
  if (attempt && typeof attempt === 'object') {
    options = attempt;
    attempt = 0;
  }
  if (attempt > 0) return fetchRustKdaJsonUncached(pathname, attempt, options);
  const key = rustKdaCacheKey(pathname);
  const force = Boolean(options.force);
  const cached = force ? null : readRustKdaJsonCache(key);
  if (!force && cached) return cached;
  const inFlight = force ? null : rustKdaJsonInFlight.get(key);
  if (!force && inFlight) return inFlight;
  const request = fetchRustKdaJsonUncached(pathname, 0, options)
    .then((payload) => {
      writeRustKdaJsonCache(key, payload, rustKdaCacheTtlMs(pathname));
      return payload;
    })
    .finally(() => {
      if (rustKdaJsonInFlight.get(key) === request) rustKdaJsonInFlight.delete(key);
    });
  if (!force) rustKdaJsonInFlight.set(key, request);
  return request;
}

function recordWechatQueryTiming(timings, key, startedAt, ok = true, error = '') {
  if (!Array.isArray(timings) || !key) return;
  timings.push({
    key,
    ms: Math.max(0, Date.now() - startedAt),
    ok: Boolean(ok),
    ...(error ? { error: normalizeText(error?.message || error, 160) } : {})
  });
}

async function timeWechatQueryStep(timings, key, task) {
  const startedAt = Date.now();
  try {
    const result = await task();
    recordWechatQueryTiming(timings, key, startedAt, true);
    return result;
  } catch (error) {
    recordWechatQueryTiming(timings, key, startedAt, false, error);
    throw error;
  }
}

async function fetchRustKdaMemberProfileStats(steamId, {
  includeInventory = true,
  includeAccountRestriction = false,
  includeSteamBans = false,
  steamWebApiKey: steamWebApiKeyOverride = '',
  steamProfileOverride,
  timings = null,
  force = false,
  rustKdaTimeoutMs = 0,
  inventoryTimeoutMs = 0
} = {}) {
  let providerSteamWebApiKey = String(steamWebApiKeyOverride || steamWebApiEnvKey()).trim();
  if (!providerSteamWebApiKey) {
    try {
      providerSteamWebApiKey = steamWebApiKey(await readSettingsRuntimeStore());
    } catch {
      providerSteamWebApiKey = '';
    }
  }
  let playerPayload = null;
  let inventoryPayload = null;
  let steamProfilePayload = null;
  let officialKdaPayload = null;
  let accountRestrictionPayload = null;
  let steamBanPayload = null;
  let error = '';
  let officialKdaError = '';
  let accountRestrictionError = '';
  let steamBanError = '';
  const [playerResult, inventoryResult, officialKdaResult, steamProfileResult, accountRestrictionResult, steamBanResult] = await Promise.allSettled([
    timeWechatQueryStep(timings, 'rustKda.player', () => fetchRustKdaJson(`/api/player/${encodeURIComponent(steamId)}`, { steamWebApiKey: providerSteamWebApiKey, force, timeoutMs: rustKdaTimeoutMs })),
    includeInventory ? timeWechatQueryStep(timings, 'rustKda.inventory', () => fetchRustKdaJson(`/api/inventory/${encodeURIComponent(steamId)}`, { steamWebApiKey: providerSteamWebApiKey, force, timeoutMs: inventoryTimeoutMs || rustKdaTimeoutMs })) : Promise.resolve(null),
    timeWechatQueryStep(timings, 'rustKda.officialKda', () => fetchRustKdaJson(`/api/kda/${encodeURIComponent(steamId)}`, { steamWebApiKey: providerSteamWebApiKey, force, timeoutMs: rustKdaTimeoutMs })),
    timeWechatQueryStep(
      timings,
      'steam.profile',
      () => steamProfileOverride === undefined ? fetchSteamProfile(steamId) : Promise.resolve(steamProfileOverride)
    ),
    includeAccountRestriction ? timeWechatQueryStep(timings, 'steam.accountRestriction', () => fetchSteamBroadcastRestriction(steamId)) : Promise.resolve(null),
    includeSteamBans ? timeWechatQueryStep(timings, 'steam.bans', () => fetchSteamPlayerBans([steamId], { apiKey: providerSteamWebApiKey })) : Promise.resolve({ bansBySteamId: new Map(), error: '', skipped: true })
  ]);
  if (playerResult.status === 'fulfilled') {
    playerPayload = playerResult.value;
  } else {
    error = playerResult.reason?.message || 'player unavailable';
  }
  if (inventoryResult.status === 'fulfilled') {
    inventoryPayload = inventoryResult.value;
  } else {
    error = [error, inventoryResult.reason?.message || 'inventory unavailable'].filter(Boolean).join('; ');
  }
  if (officialKdaResult.status === 'fulfilled') {
    officialKdaPayload = officialKdaResult.value;
  } else {
    officialKdaError = officialKdaResult.reason?.message || 'official kda unavailable';
  }
  if (steamProfileResult.status === 'fulfilled') {
    steamProfilePayload = steamProfileResult.value;
  }
  if (accountRestrictionResult.status === 'fulfilled') {
    accountRestrictionPayload = accountRestrictionResult.value;
    accountRestrictionError = accountRestrictionPayload?.error || '';
  } else {
    accountRestrictionError = accountRestrictionResult.reason?.message || 'Steam broadcast unavailable';
  }
  if (steamBanResult.status === 'fulfilled') {
    const bansBySteamId = steamBanResult.value?.bansBySteamId || new Map();
    steamBanPayload = bansBySteamId.get(steamId) || null;
    steamBanError = steamBanResult.value?.skipped ? '' : (steamBanResult.value?.error || '');
  } else {
    steamBanError = steamBanResult.reason?.message || 'Steam Web API unavailable';
  }
  return profileStatsFromExternalPayload(steamId, playerPayload, inventoryPayload, error, steamProfilePayload, officialKdaPayload, officialKdaError, accountRestrictionPayload, accountRestrictionError, steamBanPayload, steamBanError);
}

function compactExternalError(error) {
  return normalizeText(error?.message || error || '', 240);
}

function flattenNumericMetrics(source = {}, prefix = '', output = [], maxItems = 500) {
  if (!source || output.length >= maxItems || Array.isArray(source)) return output;
  for (const [key, value] of Object.entries(source)) {
    const nextKey = prefix ? `${prefix}.${key}` : key;
    if (typeof value === 'number' && Number.isFinite(value)) {
      output.push({ key: nextKey, value });
    } else if (typeof value === 'string' && value.trim() && Number.isFinite(Number(value))) {
      output.push({ key: nextKey, value: Number(value) });
    } else if (value && typeof value === 'object') {
      flattenNumericMetrics(value, nextKey, output, maxItems);
    }
    if (output.length >= maxItems) break;
  }
  return output;
}

function publicRustKdaSectionPayload(payload = {}) {
  const sections = Array.isArray(payload?.sections) ? payload.sections : [];
  return sections.slice(0, 16).map((section, index) => ({
    id: normalizeText(section?.id, 80) || `section_${index + 1}`,
    title: normalizeText(section?.title, 120) || normalizeText(section?.label, 120) || `Section ${index + 1}`,
    emoji: normalizeText(section?.emoji, 16),
    color: normalizeText(section?.color, 32),
    items: (Array.isArray(section?.items) ? section.items : [])
      .slice(0, 36)
      .map((item, itemIndex) => ({
        id: normalizeText(item?.id, 80) || `item_${itemIndex + 1}`,
        label: normalizeText(item?.label, 120) || normalizeText(item?.name, 120) || `Metric ${itemIndex + 1}`,
        icon: normalizeText(item?.icon, 16),
        value: firstFiniteNumber(item?.value)
      }))
      .filter((item) => item.value !== null)
  })).filter((section) => section.items.length);
}

function externalKdaMetric(payload, keys, fallback = 0) {
  const sources = [payload, payload?.data, payload?.stats, payload?.statistics, payload?.result, payload?.player].filter(Boolean);
  for (const source of sources) {
    for (const key of keys) {
      const numeric = firstFiniteNumber(nestedValue(source, key), source[key]);
      if (numeric !== null) return numeric;
    }
  }
  return fallback;
}

function sumExternalKdaMetrics(payload, keys) {
  let total = 0;
  let found = false;
  for (const key of keys) {
    const numeric = externalKdaMetric(payload, [key], null);
    if (numeric !== null) {
      total += numeric;
      found = true;
    }
  }
  return found ? total : null;
}

function publicRustKdaPlayerPayload(steamId, playerPayload = null, steamProfilePayload = null, member = null) {
  const profileStats = profileStatsFromExternalPayload(steamId, playerPayload, null, '', steamProfilePayload);
  return {
    steamId,
    displayName: profileStats.displayName || memberDisplayName(member || { steamId }),
    avatar: profileStats.avatar || member?.avatar || '',
    profileUrl: profileStats.profileUrl || member?.profileUrl || steamProfileUrl(steamId),
    status: normalizeText(playerPayload?.status || playerPayload?.gameInfo || '', 80),
    country: normalizeText(playerPayload?.country, 24),
    createdAt: normalizeText(playerPayload?.createdAt, 80),
    lastLogoff: playerPayload?.lastLogoff || null,
    playTimeMinutes: profileStats.playTimeMinutes,
    playTimeKnown: profileStats.playTimeKnown,
    achievementsCount: firstFiniteNumber(playerPayload?.achievementsCount),
    raw: playerPayload || null
  };
}

function publicSteamAccountStatusPayload(profileStats = {}) {
  return {
    steamId: normalizeText(profileStats.steamId, 80),
    profilePublic: Boolean(profileStats.profilePublic),
    accountRestricted: Boolean(profileStats.accountRestricted),
    accountRestrictionStatus: profileStats.accountRestrictionStatus || '',
    accountRestrictionCheckedAt: profileStats.accountRestrictionCheckedAt || '',
    accountRestrictionRetryMs: profileStats.accountRestrictionRetryMs ?? null,
    accountRestrictionEresult: profileStats.accountRestrictionEresult ?? null,
    accountRestrictionError: profileStats.accountRestrictionError || '',
    vacBanned: Boolean(profileStats.vacBanned),
    numberOfVacBans: Number(profileStats.numberOfVacBans || 0),
    numberOfGameBans: Number(profileStats.numberOfGameBans || 0),
    daysSinceLastBan: Number(profileStats.daysSinceLastBan || 0),
    communityBanned: Boolean(profileStats.communityBanned),
    economyBan: profileStats.economyBan || 'none',
    economyRestricted: Boolean(profileStats.economyRestricted),
    steamBanCheckedAt: profileStats.steamBanCheckedAt || '',
    steamBanError: profileStats.steamBanError || ''
  };
}

function publicRustKdaMemberPayload(store, member = null) {
  if (!member) return null;
  const squadMember = store.squadMembers.find((item) => item.memberId === member.id);
  const squad = squadMember ? store.squads.find((item) => item.id === squadMember.squadId) : null;
  return {
    id: member.id,
    steamId: member.steamId,
    displayName: memberDisplayName(member),
    customName: member.customName || '',
    steamNickname: member.steamNickname || '',
    avatar: member.avatar || '',
    profileUrl: member.profileUrl || steamProfileUrl(member.steamId),
    squadId: squad?.id || member.squadId || '',
    squadName: squad?.name || member.squadName || ''
  };
}

function publicRustKdaStatsPayload(payload = null) {
  if (!payload) return null;
  const rustStats = payload?.rustStats || null;
  const rawStats = rustStats?.raw_stats || payload?.raw_stats || payload?.stats || null;
  const kills = externalKdaMetric(payload, ['kills', 'playerKills', 'kill_player', 'summary.kills', 'combat.kills', 'statistics.combat.kills', 'stats.kills', 'stats.kill_player']);
  const deaths = externalKdaMetric(payload, ['deaths', 'death', 'summary.deaths', 'deaths.total', 'combat.deaths', 'statistics.combat.deaths', 'stats.deaths', 'stats.death']);
  const assists = externalKdaMetric(payload, ['assists', 'summary.assists', 'combat.assists', 'statistics.combat.assists', 'stats.assists']);
  const denominator = Math.max(1, deaths || 0);
  const derivedKda = Number(((kills + assists) / denominator).toFixed(2));
  const headshots = externalKdaMetric(payload, ['headshots', 'headshot', 'headshotKills', 'summary.headshots', 'combat.headshots', 'statistics.combat.headshots', 'stats.headshots', 'stats.headshot']);
  const hits = externalKdaMetric(payload, ['hits', 'playerHits', 'bullets.hits.players', 'rustStats.bullets.hits.players', 'summary.bulletsHitPlayer', 'bullet.hitsPlayer', 'bullet_hit_player', 'combat.hits', 'statistics.combat.hits', 'stats.bullet_hit_player']);
  const bulletsFired = externalKdaMetric(payload, ['bulletsFired', 'shots', 'bullets.fired', 'rustStats.bullets.fired', 'summary.bulletsFired', 'bullet.fired', 'bullet_fired', 'combat.bulletsFired', 'combat.shots', 'statistics.combat.bulletsFired', 'statistics.combat.shots', 'stats.bullet_fired']);
  const totalHitsFromBuckets = sumExternalKdaMetrics(payload, [
    'bullets.hits.players',
    'bullets.hits.buildings',
    'bullets.hits.signs',
    'bullets.hits.wolves',
    'bullets.hits.bears',
    'bullets.hits.boars',
    'bullets.hits.deer',
    'bullets.hits.horses',
    'bullets.hits.dead_players',
    'bullets.hits.other',
    'rustStats.bullets.hits.players',
    'rustStats.bullets.hits.buildings',
    'rustStats.bullets.hits.signs',
    'rustStats.bullets.hits.wolves',
    'rustStats.bullets.hits.bears',
    'rustStats.bullets.hits.boars',
    'rustStats.bullets.hits.deer',
    'rustStats.bullets.hits.horses',
    'rustStats.bullets.hits.dead_players',
    'rustStats.bullets.hits.other'
  ]);
  const totalHits = externalKdaMetric(payload, ['totalHits', 'bulletsHitTotal', 'bullets.total_hits', 'rustStats.bullets.total_hits', 'summary.bulletsHit', 'bullet.hitsTotal', 'bullet_hit_entity', 'stats.bullet_hit_entity'], totalHitsFromBuckets ?? hits);
  const buildingHits = externalKdaMetric(payload, ['buildingHits', 'bullets.hits.buildings', 'rustStats.bullets.hits.buildings', 'bullet_hit_building', 'stats.bullet_hit_building']);
  const signHits = externalKdaMetric(payload, ['signHits', 'bullets.hits.signs', 'rustStats.bullets.hits.signs', 'bullet_hit_sign', 'stats.bullet_hit_sign']);
  const animalHits = sumExternalKdaMetrics(payload, [
    'bullets.hits.wolves',
    'bullets.hits.bears',
    'bullets.hits.boars',
    'bullets.hits.deer',
    'bullets.hits.horses',
    'rustStats.bullets.hits.wolves',
    'rustStats.bullets.hits.bears',
    'rustStats.bullets.hits.boars',
    'rustStats.bullets.hits.deer',
    'rustStats.bullets.hits.horses',
    'bullet_hit_wolf',
    'bullet_hit_bear',
    'bullet_hit_boar',
    'bullet_hit_stag',
    'bullet_hit_horse',
    'stats.bullet_hit_wolf',
    'stats.bullet_hit_bear',
    'stats.bullet_hit_boar',
    'stats.bullet_hit_stag',
    'stats.bullet_hit_horse'
  ]) ?? 0;
  const deadPlayerHits = externalKdaMetric(payload, ['deadPlayerHits', 'bullets.hits.dead_players', 'rustStats.bullets.hits.dead_players', 'bullet_hit_playercorpse', 'bullet_hit_corpse', 'stats.bullet_hit_playercorpse', 'stats.bullet_hit_corpse']);
  const otherHits = externalKdaMetric(payload, ['otherHits', 'bullets.hits.other', 'rustStats.bullets.hits.other']);
  const accuracy = externalKdaMetric(payload, ['accuracy', 'summary.accuracy'], bulletsFired > 0 ? Number(((hits / bulletsFired) * 100).toFixed(2)) : 0);
  const headshotRate = externalKdaMetric(payload, ['headshotRate', 'summary.headshotRate'], hits > 0 ? Number(((headshots / hits) * 100).toFixed(2)) : 0);
  const metrics = flattenNumericMetrics(rawStats || payload?.statistics || payload?.stats || payload?.data || payload)
    .filter((item) => !['steamId', 'steamid', 'profileId'].includes(item.key));
  return {
    kills,
    deaths,
    assists,
    kda: externalKdaMetric(payload, ['kda', 'kd', 'kdr', 'summary.kdRatio', 'killDeathRatio', 'stats.kda'], derivedKda),
    headshots,
    hits,
    playerHits: hits,
    totalHits,
    buildingHits,
    signHits,
    animalHits,
    deadPlayerHits,
    otherHits,
    bulletsFired,
    accuracy,
    headshotRate,
    rockets: externalKdaMetric(payload, ['rockets', 'rocket_fired', 'rocketsFired', 'summary.rocketsFired', 'misc.rocketsFired', 'raiding.rockets', 'statistics.raiding.rockets', 'stats.rocket_fired']),
    sulfur: externalKdaMetric(payload, ['sulfur', 'sulfurOre', 'harvest.sulfur_ore', 'harvested_sulfur_ore', 'resources.sulfurOre', 'resources.sulfur', 'farming.gathered.sulfur.ore', 'statistics.farming.gathered.sulfur.ore', 'stats.harvest.sulfur_ore', 'stats.harvested_sulfur_ore']),
    metalOre: externalKdaMetric(payload, ['metalOre', 'harvest.metal_ore', 'acquired_metal.ore', 'resources.metalOre', 'farming.gathered.metal.ore', 'statistics.farming.gathered.metal.ore', 'stats.harvest.metal_ore', 'stats.acquired_metal.ore']),
    wood: externalKdaMetric(payload, ['wood', 'harvest.wood', 'harvested_wood', 'resources.wood', 'farming.gathered.wood', 'statistics.farming.gathered.wood', 'stats.harvest.wood', 'stats.harvested_wood']),
    stone: externalKdaMetric(payload, ['stone', 'harvest.stones', 'harvested_stones', 'resources.stone', 'farming.gathered.stones', 'statistics.farming.gathered.stones', 'stats.harvest.stones', 'stats.harvested_stones']),
    playTimeMinutes: externalKdaMetric(payload, ['playTimeMinutes', 'playtimeMinutes', 'minutes_played', 'rustStats.minutes_played', 'onlineTimeMinutes', 'timePlayedMinutes']),
    achievementsCount: externalKdaMetric(payload, ['achievementsCount', 'achievement_count', 'rustStats.achievement_count']),
    privateProfile: payload?.is_private === true ? true : (payload?.is_private === false ? false : null),
    rustStats,
    rawStats,
    sections: publicRustKdaSectionPayload(payload),
    metrics,
    raw: payload
  };
}

