function officialKdaProfilePatch(member = {}, existing = {}, officialKda = null) {
  if (!member?.id || !member?.steamId || !officialKda) return null;
  return {
    ...existing,
    id: existing.id || createId('member_profile'),
    memberId: member.id,
    steamId: member.steamId,
    profileUrl: existing.profileUrl || steamProfileUrl(member.steamId),
    inventoryCurrency: existing.inventoryCurrency || 'USD',
    officialKda,
    officialKdaFetchedAt: nowIso(),
    officialKdaError: ''
  };
}

async function cacheOfficialKdaQueryResult(steamId, officialKda) {
  if (!officialKda) return;
  const normalizedSteamId = normalizeText(steamId, 80);
  if (sqlitePrimaryMode()) {
    try {
      return await runStoreWriteTask(async () => {
        const members = normalizedSteamId
          ? await getSqliteRecordsByJsonField('members', 'steamId', [normalizedSteamId], { limit: 0 })
          : [];
        const member = members.find((item) => item.steamId === normalizedSteamId);
        if (!member) return false;
        const [profilesByMemberId, profilesBySteamId] = await Promise.all([
          getSqliteRecordsByJsonField('memberProfiles', 'memberId', [member.id], { limit: 0 }),
          getSqliteRecordsByJsonField('memberProfiles', 'steamId', [member.steamId], { limit: 0 })
        ]);
        const existing = profilesByMemberId[0] || profilesBySteamId[0] || {};
        const nextProfile = officialKdaProfilePatch(member, existing, officialKda);
        if (!nextProfile) return false;
        await writeSqliteStorePatch({
          reason: 'official_kda_query_cache',
          upserts: { memberProfiles: [nextProfile] }
        });
        await patchStoreCache((cachedStore) => {
          cachedStore.memberProfiles ||= [];
          replaceCachedRecord(cachedStore.memberProfiles, nextProfile);
        });
        return true;
      });
    } catch (error) {
      console.warn('[nb-clan] sqlite official KDA cache write failed:', error?.message || error);
      return false;
    }
    return false;
  }
  await updateStore((store) => {
    store.memberProfiles ||= [];
    const member = store.members.find((item) => item.steamId === normalizedSteamId);
    if (!member) return;
    const existingIndex = store.memberProfiles.findIndex((item) => item.memberId === member.id);
    const existing = existingIndex >= 0 ? store.memberProfiles[existingIndex] : {};
    const nextProfile = officialKdaProfilePatch(member, existing, officialKda);
    if (!nextProfile) return;
    if (existingIndex >= 0) store.memberProfiles[existingIndex] = nextProfile;
    else store.memberProfiles.push(nextProfile);
  });
}

async function rustKdaQueryPayload(req, mode = 'kda') {
  const resolved = await resolveSteamInput(req.query?.steamInput);
  if (!resolved.ok) {
    throw Object.assign(new Error(resolved.message), { status: 400 });
  }
  const steamId = resolved.steamId;
  const store = await readMemberQueryRuntimeStore(steamId, { includeSettings: true });
  const providerSteamWebApiKey = steamWebApiKey(store);
  const member = store.members.find((item) => item.steamId === steamId) || null;
  const cachedProfile = member ? store.memberProfiles.find((item) => item.memberId === member.id) : null;
  const cachedKda = mode === 'kda' ? (cachedProfile?.officialKda || null) : null;
  const includeSteamAccountChecks = mode === 'kda';
  const [playerResult, targetResult, steamProfileResult, accountRestrictionResult, steamBanResult] = await Promise.allSettled([
    fetchRustKdaJson(`/api/player/${encodeURIComponent(steamId)}`, { steamWebApiKey: providerSteamWebApiKey }),
    fetchRustKdaJson(`/${mode === 'inventory' ? 'api/inventory' : 'api/kda'}/${encodeURIComponent(steamId)}`, { steamWebApiKey: providerSteamWebApiKey }),
    fetchSteamProfile(steamId),
    includeSteamAccountChecks ? fetchSteamBroadcastRestriction(steamId) : Promise.resolve(null),
    includeSteamAccountChecks ? fetchSteamPlayerBans([steamId], { apiKey: providerSteamWebApiKey }) : Promise.resolve({ bansBySteamId: new Map(), error: '', skipped: true })
  ]);
  const playerPayload = playerResult.status === 'fulfilled' ? playerResult.value : null;
  const targetPayload = targetResult.status === 'fulfilled' ? targetResult.value : null;
  const steamProfilePayload = steamProfileResult.status === 'fulfilled' ? steamProfileResult.value : null;
  const accountRestrictionPayload = accountRestrictionResult.status === 'fulfilled' ? accountRestrictionResult.value : null;
  const accountRestrictionError = includeSteamAccountChecks
    ? (accountRestrictionResult.status === 'fulfilled'
      ? (accountRestrictionPayload?.error || '')
      : compactExternalError(accountRestrictionResult.reason) || 'Steam broadcast unavailable')
    : '';
  let steamBanPayload = null;
  let steamBanError = '';
  if (includeSteamAccountChecks) {
    if (steamBanResult.status === 'fulfilled') {
      const bansBySteamId = steamBanResult.value?.bansBySteamId || new Map();
      steamBanPayload = bansBySteamId.get(steamId) || null;
      steamBanError = steamBanResult.value?.error || '';
    } else {
      steamBanError = compactExternalError(steamBanResult.reason) || 'Steam Web API unavailable';
    }
  }
  if (!playerPayload && !targetPayload && !cachedKda) {
    throw Object.assign(new Error(compactExternalError(targetResult.reason || playerResult.reason) || 'Rust KDA 查询失败'), { status: 502 });
  }
  const kdaPayload = mode === 'kda' ? (publicRustKdaStatsPayload(targetPayload) || cachedKda) : null;
  const accountStats = includeSteamAccountChecks
    ? profileStatsFromExternalPayload(
      steamId,
      playerPayload,
      null,
      '',
      steamProfilePayload,
      null,
      '',
      accountRestrictionPayload,
      accountRestrictionError,
      steamBanPayload,
      steamBanError
    )
    : null;
  if (mode === 'kda' && targetPayload && member && kdaPayload) {
    await cacheOfficialKdaQueryResult(steamId, kdaPayload);
  }
  const source = RUST_KDA_QUERY_SOURCE;
  const externalUrl = RUST_KDA_PUBLIC_BASE_URL ? `${RUST_KDA_PUBLIC_BASE_URL}/` : '';
  return {
    steamId,
    source,
    externalUrl,
    player: publicRustKdaPlayerPayload(steamId, playerPayload, steamProfilePayload, member),
    member: publicRustKdaMemberPayload(store, member),
    account: accountStats ? publicSteamAccountStatusPayload(accountStats) : null,
    kda: kdaPayload,
    inventory: mode === 'inventory' ? publicRustKdaInventoryPayload(targetPayload) : null,
    errors: {
      player: playerResult.status === 'rejected' ? compactExternalError(playerResult.reason) : '',
      [mode]: targetResult.status === 'rejected' && !(mode === 'kda' && kdaPayload) ? compactExternalError(targetResult.reason) : '',
      accountRestriction: accountRestrictionError,
      steamBan: steamBanError
    },
    fetchedAt: nowIso()
  };
}

function normalizeVitalLookupServerId(value) {
  const serverId = normalizeText(value, 80);
  if (!serverId || !/^\d{1,8}$/.test(serverId)) {
    throw Object.assign(new Error('Vital 服务器 ID 无效'), { status: 400 });
  }
  return serverId;
}

function normalizeVitalLookupWipeId(value) {
  const wipeId = normalizeText(value, 120);
  if (wipeId && !/^[A-Za-z0-9_.:-]{1,80}$/.test(wipeId)) {
    throw Object.assign(new Error('Vital Wipe ID 无效'), { status: 400 });
  }
  return wipeId;
}

function vitalLookupContext(store, body = {}) {
  const requestedServerId = normalizeText(body?.vitalServerId || body?.serverId, 80);
  const hasRequestedWipeId = Boolean(body && (Object.hasOwn(body, 'vitalWipeId') || Object.hasOwn(body, 'wipeId')));
  const requestedWipeId = hasRequestedWipeId
    ? normalizeText(Object.hasOwn(body, 'vitalWipeId') ? body.vitalWipeId : body.wipeId, 120)
    : '';
  const referenceWipe = queryReferenceWipe(store);
  const vitalServers = vitalServersForStore(store);
  const configuredServer = vitalServers.find((server) => (
    requestedServerId
      ? String(server.vitalServerId) === requestedServerId
      : String(server.vitalServerId) === String(referenceWipe?.vitalServerId || '')
  )) || (requestedServerId ? null : vitalServers[0]) || null;
  const vitalServerId = normalizeVitalLookupServerId(requestedServerId || referenceWipe?.vitalServerId || configuredServer?.vitalServerId);
  const fallbackWipeId = String(referenceWipe?.vitalServerId || '') === vitalServerId ? referenceWipe?.vitalWipeId : '';
  const vitalWipeId = normalizeVitalLookupWipeId(hasRequestedWipeId ? requestedWipeId : fallbackWipeId);
  const matchingWipe = vitalWipeId
    ? (store.wipes || []).find((wipe) => (
        String(wipe.vitalServerId || '') === vitalServerId
          && String(wipe.vitalWipeId || '') === vitalWipeId
      )) || null
    : null;
  const serverName = expandVitalRustName(configuredServer?.name || matchingWipe?.serverName || matchingWipe?.name || `Vital ${vitalServerId}`);
  const wipeName = vitalWipeId
    ? (matchingWipe?.name || serverName)
    : 'All Wipes';
  return {
    id: matchingWipe?.id || `vital_lookup_${vitalServerId}_${vitalWipeId || 'all'}`,
    name: wipeName,
    status: matchingWipe?.status || 'active',
    serverName,
    vitalServerId,
    vitalWipeId,
    kdaUrl: buildKdaUrl(vitalServerId, vitalWipeId)
  };
}

function publicVitalLookupRow(row = null) {
  if (!row) return null;
  return {
    kills: Number(row.kills || 0),
    deaths: Number(row.deaths || 0),
    assists: Number(row.assists || 0),
    t3Kills: Number(row.t3Kills || 0),
    kd: Number(row.kd || 0),
    kda: Number(row.kda || 0),
    rockets: Number(row.rockets || 0),
    sulfur: Number(row.sulfur || 0),
    metalOre: Number(row.metalOre || 0),
    building: Number(row.building || 0),
    onlineTimeMinutes: Number(row.onlineTimeMinutes || 0),
    playTimeMinutes: Number(row.playTimeMinutes || 0),
    source: row.source || 'vital',
    syncedAt: row.syncedAt || ''
  };
}

async function rustKdaVitalQueryPayload(req) {
  const body = req.body || {};
  const resolved = await resolveSteamInput(body.steamInput || req.query?.steamInput);
  if (!resolved.ok) {
    throw Object.assign(new Error(resolved.message), { status: 400 });
  }
  const steamId = resolved.steamId;
  const store = await readMemberQueryRuntimeStore(steamId, { includeSettings: true });
  const providerSteamWebApiKey = steamWebApiKey(store);
  const member = store.members.find((item) => item.steamId === steamId) || null;
  const lookupWipe = vitalLookupContext(store, body);
  const [playerResult, vitalResult, steamProfileResult] = await Promise.allSettled([
    fetchRustKdaJson(`/api/player/${encodeURIComponent(steamId)}`, { steamWebApiKey: providerSteamWebApiKey }),
    fetchVitalLookupRows(lookupWipe, [steamId]),
    fetchSteamProfile(steamId)
  ]);
  const playerPayload = playerResult.status === 'fulfilled' ? playerResult.value : null;
  const vitalRows = vitalResult.status === 'fulfilled' ? vitalResult.value : [];
  const vitalPayload = vitalRows.find((item) => normalizeText(item?.context?.userId, 32) === steamId) || vitalRows[0] || null;
  const steamProfilePayload = steamProfileResult.status === 'fulfilled' ? steamProfileResult.value : null;
  const lookupMember = member || {
    id: `vital_lookup_${steamId}`,
    steamId,
    steamNickname: normalizeText(vitalPayload?.player?.name || playerPayload?.name, 120),
    avatar: normalizeText(vitalPayload?.player?.avatarMedium || vitalPayload?.player?.avatarFull || vitalPayload?.player?.avatar || '', 500)
  };
  const row = vitalPayload ? vitalPlayerToKdaRow(store, lookupWipe, lookupMember, vitalPayload, null) : null;
  if (!playerPayload && !vitalPayload) {
    throw Object.assign(new Error(compactExternalError(vitalResult.reason || playerResult.reason) || 'Vital 查询失败'), { status: 502 });
  }
  return {
    steamId,
    source: RUST_KDA_QUERY_SOURCE,
    externalUrl: lookupWipe.kdaUrl || '',
    player: publicRustKdaPlayerPayload(steamId, playerPayload, steamProfilePayload, lookupMember),
    member: publicRustKdaMemberPayload(store, member),
    vital: vitalPayload ? {
      serverId: lookupWipe.vitalServerId,
      wipeId: lookupWipe.vitalWipeId,
      serverName: lookupWipe.serverName,
      wipeName: lookupWipe.name,
      stats: publicRustKdaStatsPayload(vitalPayload),
      row: publicVitalLookupRow(row),
      player: vitalPayload.player || null,
      context: vitalPayload.context || null,
      raw: vitalPayload
    } : null,
    errors: {
      player: playerResult.status === 'rejected' ? compactExternalError(playerResult.reason) : '',
      vital: vitalResult.status === 'rejected' ? compactExternalError(vitalResult.reason) : ''
    },
    fetchedAt: nowIso()
  };
}

async function rustKdaMooseQueryPayload(req) {
  const body = req.body || {};
  const resolved = await resolveSteamInput(body.steamInput || req.query?.steamInput);
  if (!resolved.ok) {
    throw Object.assign(new Error(resolved.message), { status: 400 });
  }
  const serverId = normalizeText(body.serverId, 80);
  const period = normalizeText(body.period, 120);
  if (!serverId) throw Object.assign(new Error('请选择 Moose 服务器'), { status: 400 });
  if (!period) throw Object.assign(new Error('请选择 Moose 档期'), { status: 400 });

  const steamId = resolved.steamId;
  const store = await readMemberQueryRuntimeStore(steamId, { includeSettings: true });
  const member = store.members.find((item) => item.steamId === steamId) || null;
  const knownPlayerName = normalizeText(member?.steamNickname, 120);
  const steamProfilePromise = fetchSteamProfile(steamId).catch(() => null);
  let steamProfilePayload = null;
  let moose;
  if (knownPlayerName) {
    [moose, steamProfilePayload] = await Promise.all([
      fetchMoosePlayerStats({
        serverId,
        period,
        steamId,
        playerName: knownPlayerName,
        categoryIds: Array.isArray(body.categoryIds) ? body.categoryIds : []
      }),
      steamProfilePromise
    ]);
  } else {
    steamProfilePayload = await steamProfilePromise;
    moose = await fetchMoosePlayerStats({
      serverId,
      period,
      steamId,
      playerName: normalizeText(steamProfilePayload?.nickname, 120),
      categoryIds: Array.isArray(body.categoryIds) ? body.categoryIds : []
    });
  }
  const playerName = normalizeText(steamProfilePayload?.nickname || knownPlayerName, 120);
  const lookupMember = member || {
    id: `moose_lookup_${steamId}`,
    steamId,
    steamNickname: moose.identity?.playerName || playerName,
    avatar: moose.identity?.avatar || steamProfilePayload?.avatar || ''
  };
  return {
    steamId,
    source: 'Moose.GG',
    externalUrl: moose.source || 'https://moose.gg/stats',
    player: publicRustKdaPlayerPayload(steamId, null, steamProfilePayload, lookupMember),
    member: publicRustKdaMemberPayload(store, member),
    moose,
    errors: {
      steamProfile: steamProfilePayload ? '' : 'Steam profile unavailable'
    },
    fetchedAt: nowIso()
  };
}

function upsertVitalKdaRows(store, wipe, payloadRows, requestedMemberIds = new Set()) {
  if (kdaSyncUsesAllMembers(store, wipe)) markAllMembersKdaScope(wipe);
  const membersBySteamId = new Map(store.members.map((member) => [member.steamId, member]));
  const participantMemberIds = new Set(wipeAvailableParticipants(store, wipe).map((participant) => participant.memberId));
  const allowAllMemberRows = kdaSyncUsesAllMembers(store, wipe);
  if (requestedMemberIds.size) {
    store.kdaRows = store.kdaRows.filter((row) => !(row.wipeId === wipe.id && row.source === 'local_demo' && requestedMemberIds.has(row.memberId)));
  }
  const existingIndexByMemberId = new Map(store.kdaRows.map((row, index) => [`${row.wipeId}:${row.memberId}`, index]));
  let imported = 0;
  let ignored = 0;
  const matchedRequestedMemberIds = new Set();
  const changedRows = [];
  for (const payload of payloadRows) {
    const steamId = normalizeText(payload?.context?.userId, 32);
    const member = membersBySteamId.get(steamId);
    const isRequestedAllMemberRow = allowAllMemberRows && (!requestedMemberIds.size || requestedMemberIds.has(member?.id));
    if (!steamId || !member || (!participantMemberIds.has(member.id) && !isRequestedAllMemberRow)) {
      ignored += 1;
      continue;
    }
    const playerName = normalizeText(payload?.player?.name, 120);
    const playerAvatar = normalizeText(payload?.player?.avatarMedium || payload?.player?.avatarFull || payload?.player?.avatar, 500);
    if (playerName && !member.steamNickname) member.steamNickname = playerName;
    if (playerAvatar && member.avatar !== playerAvatar) member.avatar = playerAvatar;
    const existingIndex = existingIndexByMemberId.get(`${wipe.id}:${member.id}`);
    const existing = existingIndex !== undefined ? store.kdaRows[existingIndex] : null;
    const row = vitalPlayerToKdaRow(store, wipe, member, payload, existing);
    if (existingIndex !== undefined) store.kdaRows[existingIndex] = row;
    else store.kdaRows.push(row);
    changedRows.push(row);
    if (!requestedMemberIds.size || requestedMemberIds.has(member.id)) matchedRequestedMemberIds.add(member.id);
    imported += 1;
  }
  const onlineOnlyRows = ensureBattlemetricsOnlineKdaRows(store, wipe, requestedMemberIds.size ? requestedMemberIds : null, {
    skipMemberIds: new Set(changedRows.map((row) => row.memberId).filter(Boolean))
  });
  recordKdaSnapshots(store, [...changedRows, ...onlineOnlyRows]);
  const missing = requestedMemberIds.size
    ? Math.max(0, requestedMemberIds.size - matchedRequestedMemberIds.size)
    : 0;
  return { imported, ignored: ignored + missing, missing, onlineOnly: onlineOnlyRows.length };
}

async function syncVitalKdaForWipe(wipe, participants, membersById, options = {}) {
  if (!wipe.vitalServerId || !wipe.vitalWipeId) {
    throw Object.assign(new Error('等待 Vital 生成 Wipe ID'), { status: 400 });
  }
  const steamIds = participants
    .map((participant) => membersById.get(participant.memberId)?.steamId)
    .filter(Boolean);
  if (!steamIds.length) return [];
  return fetchVitalKdaRows(wipe, [...new Set(steamIds)], options);
}

function visibleKdaRowsFromSource(store, wipe, user, sourceRows, { scope = '', squadId = '', squadIds = '', q = '', sort = 'kda', order = 'desc' } = {}) {
  const enrichedMembers = enrichMembers(store, user);
  const members = new Map(enrichedMembers.map((member) => [member.id, member]));
  const membersBySteamId = new Map(enrichedMembers.map((member) => [member.steamId, member]).filter(([steamId]) => steamId));
  const leaderSquadIds = new Set(leaderSquads(store, user).map((squad) => squad.id));
  const settlement = wipe.status === 'closed'
    ? store.wipeSettlements.find((item) => item.wipeId === wipe.id) || null
    : null;
  const squadSelection = visibleSquadSelection(
    store,
    user,
    { scope, squadId, squadIds },
    settlement?.squadsSnapshot?.length ? settlement.squadsSnapshot : null
  );
  const archivedParticipantsByMemberId = new Map((settlement?.participantsSnapshot || [])
    .filter((participant) => participant?.memberId)
    .map((participant) => [participant.memberId, participant]));
  const archivedRowsByMemberId = new Map((settlement?.kdaSnapshot || [])
    .filter((row) => row?.memberId)
    .map((row) => [row.memberId, row]));
  const participantRows = store.wipeParticipants.filter((participant) => participant.wipeId === wipe.id);
  if (settlement?.participantsSnapshot?.length) {
    const existingParticipantIds = new Set(participantRows.map((participant) => participant.memberId));
    for (const participant of settlement.participantsSnapshot) {
      if (participant?.memberId && !existingParticipantIds.has(participant.memberId)) {
        participantRows.push(participant);
      }
    }
  }

  const canViewAllKdaRows = canViewOperationalData(user, store);
  const allowCurrentMemberRows = kdaSyncUsesAllMembers(store, wipe);
  const currentSquadByMemberId = memberSquadMap(store);
  const squadsById = new Map(store.squads.map((squad) => [squad.id, squad]));
  const rawParticipantsByMemberId = new Map(participantRows
    .filter((participant) => participant.memberId)
    .map((participant) => [participant.memberId, participant]));

  const participantsByMemberId = new Map(
    participantRows
      .filter((participant) => isParticipantAvailable(participant.status))
      .filter((participant) => {
        if (canViewAllKdaRows) {
          return !squadSelection.requested || squadSelection.ids.has(participant.squadId);
        }
        if (!leaderSquadIds.has(participant.squadId)) return false;
        return !squadSelection.requested || squadSelection.ids.has(participant.squadId);
      })
      .map((participant) => [participant.memberId, participant])
  );

  function currentMemberRowIsVisible(row) {
    if (!allowCurrentMemberRows || !row?.memberId) return false;
    if (participantsByMemberId.has(row.memberId)) return false;
    const member = members.get(row.memberId) || membersBySteamId.get(row.steamId);
    if (!member) return false;
    const rawParticipant = rawParticipantsByMemberId.get(row.memberId);
    const currentSquad = currentSquadByMemberId.get(row.memberId);
    const currentSquadId = rawParticipant?.squadId || currentSquad?.squadId || row.squadId || '';
    if (canViewAllKdaRows) {
      return !squadSelection.requested || squadSelection.ids.has(currentSquadId);
    }
    if (!currentSquadId || !leaderSquadIds.has(currentSquadId)) return false;
    return !squadSelection.requested || squadSelection.ids.has(currentSquadId);
  }

  const rows = (sourceRows || [])
    .filter((row) => {
      if (row.wipeId !== wipe.id) return false;
      if (!kdaRecordMatchesVitalWipe(row, wipe)) return false;
      return participantsByMemberId.has(row.memberId) || currentMemberRowIsVisible(row);
    })
    .map((row) => {
      const { kd, ...rowWithoutKd } = row;
      const archivedParticipant = archivedParticipantsByMemberId.get(row.memberId);
      const archivedRow = archivedRowsByMemberId.get(row.memberId);
      const member = members.get(row.memberId) ||
        archivedParticipant?.member ||
        archivedRow?.member ||
        membersBySteamId.get(row.steamId) ||
        (row.steamId ? { id: row.memberId, steamId: row.steamId, displayName: row.displayName || row.steamId } : null);
      const participant = participantsByMemberId.get(row.memberId);
      const rawParticipant = participant || rawParticipantsByMemberId.get(row.memberId);
      const currentSquad = participant ? null : currentSquadByMemberId.get(row.memberId);
      const rowSquadId = participant?.squadId || rawParticipant?.squadId || currentSquad?.squadId || row.squadId || '';
      const squad = rowSquadId ? squadsById.get(rowSquadId) || null : null;
      const onlineSummary = kdaRowOnlineSummary(store, row, member, wipe);
      return {
        ...rowWithoutKd,
        t3Kills: Number(row.t3Kills || 0),
        rockets: Number(row.rockets || 0),
        onlineTimeMinutes: kdaRowOnlineMinutesForWipe(row, onlineSummary, wipe),
        onlineSummary,
        member,
        displayName: member?.displayName || row.steamId,
        squadId: squad?.id || rowSquadId,
        squadName: squad?.name || participant?.squadName || rawParticipant?.squadName || row.squadName || ''
      };
    })
    .filter((row) => row.member);
  return filterAndSortKdaRows(rows, { q, sort, order });
}

function visibleKdaRows(store, wipe, user, filters = {}) {
  const rangedRows = kdaRowsForTimeRange(store, wipe, filters.timeRange);
  const hasRangedRows = Array.isArray(rangedRows);
  const sourceRows = hasRangedRows ? rangedRows : store.kdaRows;
  const rows = visibleKdaRowsFromSource(store, wipe, user, sourceRows, filters);
  if (hasRangedRows || !filters.timeRange?.requested) return rows;
  return rows.filter((row) => rowInTimeRange(row, filters.timeRange));
}

function compareKdaRows(left, right, { sort = 'kda', order = 'desc' } = {}) {
  const numericSorts = new Set(['kda', 'kills', 't3Kills', 'deaths', 'rockets', 'sulfur', 'metalOre', 'building', 'playTimeMinutes', 'onlineTimeMinutes']);
  const textSorts = new Set(['displayName', 'squadName']);
  const allowedSorts = new Set([...numericSorts, ...textSorts]);
  const sortKey = allowedSorts.has(sort) ? sort : 'kda';
  const direction = order === 'asc' ? 1 : -1;
  if (textSorts.has(sortKey)) {
    const textDiff = String(left[sortKey] || left.steamId).localeCompare(String(right[sortKey] || right.steamId));
    if (textDiff !== 0) return textDiff * direction;
    return String(left.steamId).localeCompare(String(right.steamId));
  }
  const diff = Number(left[sortKey] || 0) - Number(right[sortKey] || 0);
  if (diff !== 0) return diff * direction;
  return String(left.displayName || left.steamId).localeCompare(String(right.displayName || right.steamId));
}

function filterAndSortKdaRows(rows, { q = '', sort = 'kda', order = 'desc' } = {}) {
  const normalizedQuery = normalizeText(q, 120).toLowerCase();
  return rows
    .filter((row) => {
      if (!normalizedQuery) return true;
      return [
        row.displayName,
        row.customName,
        row.steamNickname,
        row.member?.displayName,
        row.member?.customName,
        row.member?.steamNickname,
        row.steamId,
        row.squadName
      ].some((value) => String(value || '').toLowerCase().includes(normalizedQuery));
    })
    .sort((left, right) => compareKdaRows(left, right, { sort, order }));
}

function topRowsByKdaMetric(kdaRows, keys) {
  const topRows = Object.fromEntries(keys.map((key) => [key, null]));
  for (const row of kdaRows) {
    for (const key of keys) {
      if (!topRows[key] || Number(row[key] || 0) > Number(topRows[key][key] || 0)) {
        topRows[key] = row;
      }
    }
  }
  return topRows;
}

function summaryForKdaRows(kdaRows, participants) {
  const topRows = topRowsByKdaMetric(kdaRows, ['kills', 't3Kills', 'rockets', 'sulfur', 'metalOre', 'building']);
  return {
    participantCount: participants.length,
    squadCount: new Set(participants.map((item) => item.squadId).filter(Boolean)).size,
    topKillsSteamId: topRows.kills?.steamId || '',
    topT3KillsSteamId: topRows.t3Kills?.steamId || '',
    topRocketsSteamId: topRows.rockets?.steamId || '',
    topSulfurSteamId: topRows.sulfur?.steamId || '',
    topMetalOreSteamId: topRows.metalOre?.steamId || '',
    topBuildingSteamId: topRows.building?.steamId || ''
  };
}

function settlementForWipe(store, wipe, user) {
  const participants = visibleParticipants(store, wipe, user);
  const kdaRows = visibleKdaRows(store, wipe, user, { scope: canViewOperationalData(user, store) ? 'all' : 'my_squad' });
  return {
    kdaMemberScope: kdaSyncUsesAllMembers(store, wipe) ? 'all_members' : 'participants',
    serverSnapshot: { ...wipe },
    participantsSnapshot: participants,
    squadsSnapshot: activeSquads(store).map((squad) => enrichSquad(store, squad)),
    kdaSnapshot: kdaRows,
    summary: summaryForKdaRows(kdaRows, participants)
  };
}

function mergeSettlementSnapshots(existing, next) {
  const participantsByMemberId = new Map();
  for (const participant of existing?.participantsSnapshot || []) {
    if (participant?.memberId) participantsByMemberId.set(participant.memberId, participant);
  }
  for (const participant of next?.participantsSnapshot || []) {
    if (participant?.memberId) participantsByMemberId.set(participant.memberId, participant);
  }

  const rowsByMemberId = new Map();
  for (const row of existing?.kdaSnapshot || []) {
    if (row?.memberId) rowsByMemberId.set(row.memberId, row);
  }
  for (const row of next?.kdaSnapshot || []) {
    if (row?.memberId) rowsByMemberId.set(row.memberId, row);
  }

  const squadsById = new Map();
  for (const squad of existing?.squadsSnapshot || []) {
    if (squad?.id) squadsById.set(squad.id, squad);
  }
  for (const squad of next?.squadsSnapshot || []) {
    if (squad?.id) squadsById.set(squad.id, squad);
  }

  const participantsSnapshot = [...participantsByMemberId.values()];
  const kdaSnapshot = [...rowsByMemberId.values()];
  return {
    ...next,
    participantsSnapshot,
    squadsSnapshot: [...squadsById.values()],
    kdaSnapshot,
    summary: summaryForKdaRows(kdaSnapshot, participantsSnapshot)
  };
}

function refreshSettlementSnapshotForWipe(store, wipe, user = SYSTEM_ADMIN_USER) {
  if (!wipe || wipe.status !== 'closed') return;
  const index = store.wipeSettlements.findIndex((item) => item.wipeId === wipe.id);
  if (index < 0) return;
  const existing = store.wipeSettlements[index];
  const settlement = settlementForWipe(store, wipe, user);
  store.wipeSettlements[index] = {
    ...existing,
    ...mergeSettlementSnapshots(existing, settlement)
  };
}

function closeWipeInStore(store, requestedWipe, actor, req, { logType = 'wipe_close', logPrefix = '结档' } = {}) {
  const targetId = normalizeText(requestedWipe?.id, 120);
  const index = store.wipes.findIndex((wipe) => wipe.id === targetId);
  const wipe = store.wipes[index];
  assertWipeMutable(wipe);
  if (isWipeStartedServer(wipe)) syncKdaRows(store, wipe);
  const generatedAt = nowIso();
  const allMembersKdaScope = kdaSyncUsesAllMembers(store, wipe);
  const closedWipe = {
    ...wipe,
    ...(allMembersKdaScope ? {
      kdaMemberScope: 'all_members',
      kdaMemberScopeUpdatedAt: wipe.kdaMemberScopeUpdatedAt || generatedAt
    } : {}),
    status: 'closed',
    closedAt: generatedAt,
    signupStatus: 'closed',
    signupClosedAt: wipe.signupClosedAt || generatedAt,
    signupCloseAt: wipe.signupCloseAt || generatedAt,
    updatedAt: generatedAt
  };
  const settlement = settlementForWipe(store, closedWipe, actor);
  store.wipeSettlements ||= [];
  store.wipeSettlements = store.wipeSettlements.filter((item) => item.wipeId !== wipe.id);
  store.wipeSettlements.push({
    id: createId('settlement'),
    wipeId: wipe.id,
    generatedByUserId: actor?.id || reviewActorId(req) || 'system',
    generatedAt,
    ...settlement
  });
  store.wipes[index] = closedWipe;
  appendLog(store, req, logType, `${logPrefix} ${wipe.name}`, { targetId: wipe.id });
  return closedWipe;
}

function settlementHasAllMembersKdaScope(settlement) {
  return normalizeKdaMemberScope(settlement?.kdaMemberScope) === 'all_members' ||
    wipeHasAllMembersKdaScope(settlement?.serverSnapshot);
}

function settlementForViewer(store, settlement, user, filters = {}) {
  if (!settlement) return null;
  const leaderSquadIds = new Set(leaderSquads(store, user).map((squad) => squad.id));
  const snapshotSquads = settlement.squadsSnapshot?.length ? settlement.squadsSnapshot : visibleSquads(store, user).map((squad) => enrichSquad(store, squad));
  const allowedSnapshotSquads = canViewOperationalData(user, store)
    ? snapshotSquads
    : snapshotSquads.filter((squad) => leaderSquadIds.has(squad.id));
  const squadSelection = visibleSquadSelection(store, user, filters, allowedSnapshotSquads);
  const allMembersKdaScope = settlementHasAllMembersKdaScope(settlement);
  const currentSquadByMemberId = memberSquadMap(store);
  const snapshotSquadsById = new Map(snapshotSquads.map((squad) => [squad.id, squad]));
  const liveSquadsById = new Map((store.squads || []).map((squad) => [squad.id, squad]));
  const participantsSnapshot = (settlement.participantsSnapshot || []).filter((participant) => {
    if (canViewOperationalData(user, store)) {
      return !squadSelection.requested || squadSelection.ids.has(participant.squadId);
    }
    if (!leaderSquadIds.has(participant.squadId)) return false;
    return !squadSelection.requested || squadSelection.ids.has(participant.squadId);
  });
  const participantByMemberId = new Map(participantsSnapshot.map((participant) => [participant.memberId, participant]));
  const membersBySteamId = new Map(store.members.map((member) => [member.steamId, member]).filter(([steamId]) => steamId));

  const rowSquadIdForSettlement = (row, participant = null) => (
    row?.squadId || participant?.squadId || currentSquadByMemberId.get(row?.memberId)?.squadId || ''
  );
  const settlementKdaRowVisible = (row) => {
    if (participantByMemberId.has(row.memberId)) return true;
    if (!allMembersKdaScope || !row?.memberId) return false;
    const rowSquadId = rowSquadIdForSettlement(row);
    if (canViewOperationalData(user, store)) {
      return !squadSelection.requested || squadSelection.ids.has(rowSquadId);
    }
    if (!rowSquadId || !leaderSquadIds.has(rowSquadId)) return false;
    return !squadSelection.requested || squadSelection.ids.has(rowSquadId);
  };

  const kdaSnapshot = filterAndSortKdaRows(
    (settlement.kdaSnapshot || [])
      .filter((row) => settlementKdaRowVisible(row))
      .filter((row) => rowInTimeRange(row, filters.timeRange))
      .map((row) => {
        const { kd, ...rowWithoutKd } = row;
        const participant = participantByMemberId.get(row.memberId);
        const rowSquadId = rowSquadIdForSettlement(row, participant);
        const squad = rowSquadId
          ? snapshotSquadsById.get(rowSquadId) || liveSquadsById.get(rowSquadId) || null
          : null;
        const member = row.member || participant?.member || membersBySteamId.get(row.steamId) ||
          (row.steamId ? { id: row.memberId, steamId: row.steamId, displayName: row.displayName || row.steamId } : null);
        const onlineSummary = kdaRowOnlineSummary(store, row, member || row.memberId, settlement.serverSnapshot);
        return {
          ...rowWithoutKd,
          t3Kills: Number(row.t3Kills || 0),
          rockets: Number(row.rockets || 0),
          onlineTimeMinutes: kdaRowOnlineMinutesForWipe(row, onlineSummary, settlement.serverSnapshot),
          onlineSummary,
          member,
          squadId: rowSquadId,
          squadName: row.squadName || participant?.squadName || squad?.name || ''
        };
      }),
    filters
  );
  const visibleSquadIds = new Set(participantsSnapshot.map((participant) => participant.squadId).filter(Boolean));
  const visibleKdaSquadIds = new Set(kdaSnapshot.map((row) => row.squadId).filter(Boolean));
  const squadsSnapshot = snapshotSquads.filter((squad) => {
    if (squadSelection.requested) return squadSelection.ids.has(squad.id);
    if (canViewOperationalData(user, store)) return true;
    return visibleSquadIds.has(squad.id) || visibleKdaSquadIds.has(squad.id);
  });
  return {
    ...settlement,
    participantsSnapshot,
    squadsSnapshot,
    kdaSnapshot,
    summary: summaryForKdaRows(kdaSnapshot, participantsSnapshot)
  };
}

function detailForWipe(store, wipe, user, filters = {}) {
  const settlement = (store.wipeSettlements || []).find((item) => item.wipeId === wipe.id) || null;
  const scopedSettlement = settlementForViewer(store, settlement, user, filters);
  const useSnapshot = wipe.status === 'closed' && scopedSettlement;
  const participants = useSnapshot ? scopedSettlement.participantsSnapshot : visibleParticipants(store, wipe, user, filters);
  const kdaRows = useSnapshot ? scopedSettlement.kdaSnapshot : visibleKdaRows(store, wipe, user, filters);
  const squads = useSnapshot ? scopedSettlement.squadsSnapshot : visibleSquads(store, user).map((squad) => enrichSquad(store, squad));
  return {
    wipe: enrichWipe(store, wipe, user),
    participants,
    rows: kdaRows,
    squads,
    dataFreshness: kdaDataFreshness(kdaRows),
    settlement: scopedSettlement
  };
}

function kdaRowsForWipe(store, wipe, user, filters = {}) {
  if (filters.timeRange?.requested) {
    const rangedRows = kdaRowsForTimeRange(store, wipe, filters.timeRange);
    if (Array.isArray(rangedRows)) return visibleKdaRowsFromSource(store, wipe, user, rangedRows, filters);
  }
  if (wipe.status === 'closed') {
    const settlement = (store.wipeSettlements || []).find((item) => item.wipeId === wipe.id) || null;
    return settlementForViewer(store, settlement, user, filters)?.kdaSnapshot || [];
  }
  return visibleKdaRows(store, wipe, user, filters);
}

function parseCsvLine(line) {
  const values = [];
  let current = '';
  let quoted = false;
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];
    if (char === '"' && quoted && line[index + 1] === '"') {
      current += '"';
      index += 1;
    } else if (char === '"') {
      quoted = !quoted;
    } else if (char === ',' && !quoted) {
      values.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }
  values.push(current.trim());
  return values;
}

function parseCsvRows(text) {
  const lines = String(text || '').split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  if (lines.length < 2) return [];
  const headers = parseCsvLine(lines[0]);
  return lines.slice(1).map((line) => {
    const values = parseCsvLine(line);
    return Object.fromEntries(headers.map((header, index) => [header, values[index] ?? '']));
  });
}

function parseKdaImportRows(body) {
  if (Array.isArray(body?.rows)) return body.rows;
  const text = String(body?.text || '').trim();
  if (!text) return [];
  if (text.startsWith('{') || text.startsWith('[')) {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) return parsed;
    if (Array.isArray(parsed.rows)) return parsed.rows;
    if (parsed.steamId || parsed.steam_id || parsed['Steam ID']) return [parsed];
    return [];
  }
  return parseCsvRows(text);
}

function rowValue(row, keys) {
  const normalized = new Map(Object.entries(row || {}).map(([key, value]) => [
    normalizeText(key, 80).toLowerCase().replace(/[\s_-]+/g, ''),
    value
  ]));
  for (const key of keys) {
    const value = normalized.get(normalizeText(key, 80).toLowerCase().replace(/[\s_-]+/g, ''));
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return '';
}

function numberValue(row, keys, fallback = 0) {
  const value = rowValue(row, keys);
  if (value === '') return fallback;
  const numeric = Number(String(value).replace(/[^\d.-]/g, ''));
  return Number.isFinite(numeric) ? numeric : fallback;
}

function upsertImportedKdaRows(store, wipe, rows) {
  const membersBySteamId = new Map(store.members.map((member) => [member.steamId, member]));
  const participantsByMemberId = new Map(
    store.wipeParticipants
      .filter((participant) => participant.wipeId === wipe.id && isParticipantAvailable(participant.status))
      .map((participant) => [participant.memberId, participant])
  );
  const existingIndexByMemberId = new Map(store.kdaRows.map((row, index) => [`${row.wipeId}:${row.memberId}`, index]));
  const onlineTimeKeys = ['onlineTimeMinutes', 'online time minutes', 'battlemetrics online minutes', '在线时长', 'BM在线分钟'];
  const playTimeKeys = ['playTimeMinutes', 'play time minutes', 'online minutes', '在线分钟', '在线时间', 'минуты онлайн', 'online dakika', 'นาทีออนไลน์', '온라인 분'];
  let imported = 0;
  let ignored = 0;
  const changedRows = [];
  for (const rawRow of rows) {
    const steamId = normalizeText(rowValue(rawRow, ['steamId', 'steam id', 'steam_id', 'Steam ID', 'steamid']), 32);
    const member = membersBySteamId.get(steamId);
    const participant = member ? participantsByMemberId.get(member.id) : null;
    if (!steamId || !member || !participant) {
      ignored += 1;
      continue;
    }
    const existingIndex = existingIndexByMemberId.get(`${wipe.id}:${member.id}`);
    const existing = existingIndex !== undefined ? store.kdaRows[existingIndex] : null;
    const profileTimeFields = kdaProfileTimeFields(store, wipe, member);
    const kills = numberValue(rawRow, ['kills', 'kill', '击杀', 'ฆ่า', '킬'], existing?.kills || 0);
    const deaths = numberValue(rawRow, ['deaths', 'death', '死亡', 'ตาย', '데스'], existing?.deaths || 0);
    const assists = numberValue(rawRow, ['assists', 'assist', '助攻'], existing?.assists || 0);
    const t3Kills = numberValue(rawRow, ['t3Kills', 't3 kills', 't3_kills', 't3 kill', 't3击杀', 'T3 击杀', 'убийства t3', 't3 öldürme', 'ฆ่า t3', 't3 킬'], existing?.t3Kills || 0);
    const denominator = Math.max(deaths, 1);
    const kd = numberValue(rawRow, ['kd'], Number((kills / denominator).toFixed(2)));
    const kda = numberValue(rawRow, ['kda'], Number(((kills + assists) / denominator).toFixed(2)));
    const rockets = numberValue(rawRow, ['rockets', 'rocket', '火箭', 'ракеты', 'roket', 'จรวด', '로켓'], existing?.rockets || 0);
    const hasOnlineTime = rowValue(rawRow, onlineTimeKeys) !== '';
    const existingOnlineSummary = battlemetricsOnlineSummaryTrustedForWipe(existing?.onlineSummary, wipe)
      ? existing.onlineSummary
      : null;
    const existingOnlineTimeMinutes = existingOnlineSummary
      ? kdaRowOnlineMinutesForWipe(existing, existingOnlineSummary, wipe)
      : 0;
    const onlineSummary = hasOnlineTime || existingOnlineTimeMinutes > 0
      ? existingOnlineSummary
      : profileTimeFields.onlineSummary || existingOnlineSummary;
    const hasPlayTime = rowValue(rawRow, playTimeKeys) !== '';
    const row = {
      id: existing?.id || createId('kda'),
      wipeId: wipe.id,
      memberId: member.id,
      steamId: member.steamId,
      kills,
      deaths,
      assists,
      t3Kills,
      kd,
      kda,
      rockets,
      sulfur: numberValue(rawRow, ['sulfur', '硫磺', 'сера', 'sülfür', 'ซัลเฟอร์', '유황'], existing?.sulfur || 0),
      metalOre: numberValue(rawRow, ['metalOre', 'metal ore', 'metal_ore', 'metal', '金属矿石', 'металл', 'metal cevheri', 'แร่โลหะ', '금속 광석'], existing?.metalOre || 0),
      building: numberValue(rawRow, ['building', 'build', '建筑', 'строительство', 'inşa', 'สิ่งก่อสร้าง', '건축'], existing?.building || 0),
      onlineTimeMinutes: hasOnlineTime
        ? numberValue(rawRow, onlineTimeKeys, existing?.onlineTimeMinutes || 0)
        : (existingOnlineTimeMinutes || Number(profileTimeFields.onlineTimeMinutes || 0)),
      ...(onlineSummary ? { onlineSummary } : {}),
      playTimeMinutes: hasPlayTime
        ? numberValue(rawRow, playTimeKeys, existing?.playTimeMinutes || 0)
        : (Number(existing?.playTimeMinutes || 0) || Number(profileTimeFields.playTimeMinutes || 0)),
      raw: rawRow,
      source: 'manual_import',
      syncedAt: nowIso()
    };
    if (existingIndex !== undefined) store.kdaRows[existingIndex] = row;
    else store.kdaRows.push(row);
    changedRows.push(row);
    imported += 1;
  }
  recordKdaSnapshots(store, changedRows);
  return { imported, ignored };
}

function csvEscape(value) {
  const text = String(value ?? '');
  if (/[",\n]/.test(text)) return `"${text.replaceAll('"', '""')}"`;
  return text;
}

function htmlEscape(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

