function exportText(language, key) {
  return EXPORT_TEXT[language]?.[key] || EXPORT_TEXT.zh[key] || key;
}

const EXPORT_TIME_ZONES = {
  zh: 'Asia/Shanghai',
  en: 'America/New_York',
  ru: 'Europe/Moscow',
  tr: 'Europe/Istanbul',
  th: 'Asia/Bangkok',
  ko: 'Asia/Seoul'
};

const EXPORT_LOCALES = {
  zh: 'zh-CN',
  en: 'en-US',
  ru: 'ru-RU',
  tr: 'tr-TR',
  th: 'th-TH',
  ko: 'ko-KR'
};

const RANKING_TYPES = [
  { id: 'kills', metric: 'kills', labelKey: 'rankKills', slug: 'kills-ranking' },
  { id: 't3Kills', metric: 't3Kills', labelKey: 'rankT3Kills', slug: 't3-kills-ranking' },
  { id: 'rockets', metric: 'rockets', labelKey: 'rankRpg', slug: 'rpg-ranking' },
  { id: 'metalOre', metric: 'metalOre', labelKey: 'rankMetalOre', slug: 'metal-ore-ranking' },
  { id: 'sulfur', metric: 'sulfur', labelKey: 'rankSulfur', slug: 'sulfur-ranking' },
  { id: 'building', metric: 'building', labelKey: 'rankBuilding', slug: 'building-ranking' },
  { id: 'online_minutes', metric: 'onlineTimeMinutes', labelKey: 'rankOnlineTime', slug: 'online-time-ranking' }
];

function validExportLanguage(language) {
  return EXPORT_TEXT[language] ? language : 'zh';
}

function exportTimeZone(language, requestedTimeZone = '') {
  const fallback = EXPORT_TIME_ZONES[validExportLanguage(language)] || EXPORT_TIME_ZONES.zh;
  const candidate = normalizeText(requestedTimeZone, 80) || fallback;
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: candidate }).format(new Date());
    return candidate;
  } catch {
    return fallback;
  }
}

function formatExportDateTime(value, language = 'zh', timeZone = '') {
  if (!value) return '-';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '-';
  const locale = EXPORT_LOCALES[validExportLanguage(language)] || EXPORT_LOCALES.zh;
  const zone = exportTimeZone(language, timeZone);
  return new Intl.DateTimeFormat(locale, {
    timeZone: zone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
    timeZoneName: 'short'
  }).format(date);
}

function formatExportNumber(value, language = 'zh', maximumFractionDigits = 0) {
  return new Intl.NumberFormat(EXPORT_LOCALES[validExportLanguage(language)] || EXPORT_LOCALES.zh, {
    maximumFractionDigits
  }).format(Number(value || 0));
}

function formatExportCompactResource(value, language = 'zh') {
  const numeric = Number(value || 0);
  if (!Number.isFinite(numeric)) return '0';
  const sign = numeric < 0 ? '-' : '';
  const abs = Math.abs(numeric);
  if (abs < 10000) return `${sign}${formatExportNumber(abs, language)}`;
  const scaled = abs / 10000;
  const maximumFractionDigits = scaled < 100 ? 2 : 1;
  const text = new Intl.NumberFormat(EXPORT_LOCALES[validExportLanguage(language)] || EXPORT_LOCALES.zh, {
    maximumFractionDigits
  }).format(scaled);
  return `${sign}${text}w`;
}

function formatExportPlayTimeMinutes(minutes, language = 'zh') {
  const value = Number(minutes || 0);
  if (!Number.isFinite(value) || value <= 0) return '-';
  const hours = value / 60;
  return `${formatExportNumber(hours, language, hours < 100 ? 1 : 0)} h`;
}

function formatKdaMetricValue(row, key, language = 'zh') {
  if (key === 'kda') return formatExportNumber(row?.[key], language, 2);
  if (key === 'sulfur' || key === 'metalOre') return formatExportCompactResource(row?.[key], language);
  if (key === 'playTimeMinutes' || key === 'onlineTimeMinutes') return formatExportPlayTimeMinutes(row?.[key], language);
  return formatExportNumber(row?.[key], language);
}

function exportWipeStatusText(wipe, language = 'zh') {
  const status = effectiveWipeStatus(wipe);
  if (status === 'closed') return exportText(language, 'statusClosed');
  if (status === 'planned') return exportText(language, 'statusPlanned');
  return exportText(language, 'statusActive');
}

function wipePlayDays(wipe, exportedAt = nowIso()) {
  const started = new Date(wipe?.startedAt || '');
  const ended = new Date(wipe?.closedAt || exportedAt);
  if (Number.isNaN(started.getTime()) || Number.isNaN(ended.getTime()) || ended <= started) return 0;
  return Number(((ended.getTime() - started.getTime()) / 86_400_000).toFixed(1));
}

function rankingSpecById(id) {
  const normalized = normalizeWechatRankingMetric(id);
  return RANKING_TYPES.find((item) => item.id === normalized || item.metric === normalized) || RANKING_TYPES[0];
}

function rankingSpecsFromQuery(value) {
  const normalized = normalizeText(value, 80) || 'kills';
  if (normalized === 'all') return RANKING_TYPES;
  const ids = normalized.split(',').map((item) => item.trim()).filter(Boolean);
  const specs = ids.map(rankingSpecById);
  return specs.length ? specs : [RANKING_TYPES[0]];
}

function sortRowsForRanking(rows, rankingSpec) {
  return [...rows].sort((left, right) => {
    const diff = Number(right[rankingSpec.metric] || 0) - Number(left[rankingSpec.metric] || 0);
    if (diff !== 0) return diff;
    return String(left.displayName || left.steamId).localeCompare(String(right.displayName || right.steamId));
  });
}

function rankingMetricLabel(language, rankingSpec) {
  if (rankingSpec.metric === 'onlineTimeMinutes') return exportText(language, 'onlineTime');
  return rankingSpec.metric === 'rockets' ? exportText(language, 'rpg') : exportText(language, rankingSpec.metric);
}

function rankingTitle(language, rankingSpec) {
  return exportText(language, rankingSpec.labelKey);
}

function rankingReportTitle(language, rankingSpec) {
  const title = rankingTitle(language, rankingSpec);
  if (validExportLanguage(language) === 'zh') return `${brandName()} · ${title.replace(/排行$/, '排行榜')}`;
  if (validExportLanguage(language) === 'en') return `${brandName()} · ${title.replace(/ ranking$/i, ' leaderboard')}`;
  return `${brandName()} · ${title}`;
}

function rankingMedal(index) {
  if (index === 0) return { className: 'gold', label: '♛' };
  if (index === 1) return { className: 'silver', label: '♛' };
  if (index === 2) return { className: 'bronze', label: '♛' };
  return null;
}

function rankingClass(index) {
  if (index === 0) return 'rank-gold';
  if (index === 1) return 'rank-silver';
  if (index === 2) return 'rank-bronze';
  return '';
}

function kdaRowsToCsv(rows, language = 'zh') {
  const labels = EXPORT_LABELS[language] || EXPORT_LABELS.zh;
  const lines = [labels.map(csvEscape).join(',')];
  rows.forEach((row, index) => {
    lines.push([
      index + 1,
      row.displayName,
      row.steamId,
      row.squadName,
      formatExportPlayTimeMinutes(row.onlineTimeMinutes, language),
      row.kills,
      row.t3Kills || 0,
      row.deaths,
      row.kda,
      row.rockets || 0,
      formatExportCompactResource(row.sulfur, language),
      formatExportCompactResource(row.metalOre, language),
      row.building,
      row.playTimeMinutes
    ].map(csvEscape).join(','));
  });
  return `${lines.join('\n')}\n`;
}

function kdaTotals(rows) {
  return rows.reduce((acc, row) => ({
    kills: acc.kills + Number(row.kills || 0),
    t3Kills: acc.t3Kills + Number(row.t3Kills || 0),
    deaths: acc.deaths + Number(row.deaths || 0),
    rockets: acc.rockets + Number(row.rockets || 0),
    sulfur: acc.sulfur + Number(row.sulfur || 0),
    metalOre: acc.metalOre + Number(row.metalOre || 0),
    building: acc.building + Number(row.building || 0)
  }), { kills: 0, t3Kills: 0, deaths: 0, rockets: 0, sulfur: 0, metalOre: 0, building: 0 });
}

function topMetricRow(rows, key) {
  return [...rows].sort((a, b) => Number(b[key] || 0) - Number(a[key] || 0))[0] || null;
}

