function avatarMarkup(member, displayName) {
  const avatar = safeSteamAvatarUrl(member?.avatar);
  if (avatar) {
    return `<img class="avatar" src="${htmlEscape(avatar)}" alt="" loading="eager" referrerpolicy="no-referrer">`;
  }
  const text = String(displayName || '?').trim().slice(0, 1).toUpperCase() || '?';
  return `<span class="avatar-fallback">${htmlEscape(text)}</span>`;
}

function reportShell({ language, title, metaChips, stats, content }) {
  return `<!doctype html>
<html lang="${htmlEscape(language)}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${htmlEscape(title)}</title>
  <style>${reportCss()}</style>
</head>
<body>
  <main class="sheet">
    <section class="cover">
      <h1>${htmlEscape(title)}</h1>
      <div class="meta-chips">${metaChips.map((item) => `<span class="chip">${htmlEscape(item)}</span>`).join('')}</div>
    </section>
    <section class="stats">${stats.map(([label, value]) => `<div class="stat"><label>${htmlEscape(label)}</label><strong>${htmlEscape(value)}</strong></div>`).join('')}</section>
    ${content}
  </main>
</body>
</html>`;
}

function kdaLeaderboardTable(rows, language, { rankingSpec = RANKING_TYPES[0] } = {}) {
  if (!rows.length) return `<div class="empty">${htmlEscape(exportText(language, 'noRecords'))}</div>`;
  const labels = EXPORT_LABELS[language] || EXPORT_LABELS.zh;
  const metricColumns = [
    { key: 'kills', label: exportText(language, 'kills') },
    { key: 't3Kills', label: exportText(language, 't3Kills') },
    { key: 'deaths', label: exportText(language, 'deaths') },
    { key: 'kda', label: 'KDA' },
    { key: 'rockets', label: exportText(language, 'rpg') },
    { key: 'sulfur', label: exportText(language, 'sulfur'), wide: true },
    { key: 'metalOre', label: exportText(language, 'metalOre'), wide: true },
    { key: 'building', label: exportText(language, 'building'), wide: true }
  ];
  const rankingColumns = [
    { key: 'onlineTimeMinutes', label: exportText(language, 'onlineTime') },
    ...metricColumns
  ];
  const primaryMetric = rankingColumns.find((column) => column.key === rankingSpec.metric) || metricColumns[0];
  const secondaryMetrics = metricColumns.filter((column) => column.key !== primaryMetric.key);
  const showOnlineColumn = primaryMetric.key !== 'onlineTimeMinutes';
  const headers = [
    { label: '#', className: '' },
    { label: labels[1], className: '' },
    { label: exportText(language, 'squad'), className: '' },
    ...(showOnlineColumn ? [{ label: exportText(language, 'onlineTime'), className: '' }] : []),
    { label: rankingMetricLabel(language, rankingSpec), className: 'leaderboard-primary-stat' },
    ...secondaryMetrics.map((column) => ({ label: column.label, className: '' }))
  ];
  const bodyRows = rows.map((row, index) => {
    const member = row.member || {};
    const displayName = row.displayName || member.displayName || row.steamId || '-';
    const steamName = member.steamNickname && member.customName ? `${member.steamNickname}` : '';
    const medal = rankingMedal(index);
    const avatar = `<span class="avatar-wrap">${avatarMarkup(member, displayName)}${medal ? `<span class="medal medal-${medal.className}">${htmlEscape(medal.label)}</span>` : ''}</span>`;
    return `<tr class="${rankingClass(index)}">
      <td class="leaderboard-rank">#${String(index + 1).padStart(2, '0')}</td>
      <td class="leaderboard-player">
        <div class="leaderboard-identity">
          ${avatar}
          <div>
            <div class="leaderboard-name">${htmlEscape(displayName)}</div>
            ${steamName ? `<div class="leaderboard-steam">Steam: ${htmlEscape(steamName)}</div>` : ''}
            <div class="leaderboard-steam mono">${htmlEscape(row.steamId || member.steamId || '')}</div>
          </div>
        </div>
      </td>
      <td>${htmlEscape(row.squadName || '-')}</td>
      ${showOnlineColumn ? `<td>${htmlEscape(formatKdaMetricValue(row, 'onlineTimeMinutes', language))}</td>` : ''}
      <td class="leaderboard-primary-stat">${htmlEscape(formatKdaMetricValue(row, primaryMetric.key, language))}</td>
      ${secondaryMetrics.map((column) => `<td>${htmlEscape(formatKdaMetricValue(row, column.key, language))}</td>`).join('')}
    </tr>`;
  }).join('');
  return `<section class="leaderboard">
    <table class="leaderboard-table">
      <colgroup>
        <col class="leaderboard-rank">
        <col class="leaderboard-player">
        <col class="leaderboard-squad">
        ${showOnlineColumn ? '<col class="leaderboard-online">' : ''}
        <col class="leaderboard-primary-stat">
        ${secondaryMetrics.map((column) => `<col class="${column.wide ? 'leaderboard-wide-stat' : 'leaderboard-stat'}">`).join('')}
      </colgroup>
      <thead><tr>${headers.map((header) => `<th${header.className ? ` class="${header.className}"` : ''}>${htmlEscape(header.label)}</th>`).join('')}</tr></thead>
      <tbody>${bodyRows}</tbody>
    </table>
  </section>`;
}

function topPerformerCards(rows, language) {
  const items = [
    ['topKills', 'kills'],
    ['topT3Kills', 't3Kills'],
    ['topRockets', 'rockets'],
    ['topSulfur', 'sulfur'],
    ['topMetalOre', 'metalOre'],
    ['topBuilding', 'building']
  ];
  return `<section class="section result">
    <h2>${htmlEscape(exportText(language, 'settlement'))}</h2>
    <div class="kv-grid">${items.map(([labelKey, valueKey]) => {
      const row = topMetricRow(rows, valueKey);
      const name = row?.displayName || row?.member?.displayName || row?.steamId || '-';
      const value = row ? formatKdaMetricValue(row, valueKey, language) : '-';
      return `<div class="kv"><span class="label">${htmlEscape(exportText(language, labelKey))}</span><strong>${htmlEscape(name)}</strong><div class="sub">${htmlEscape(value)}</div></div>`;
    }).join('')}</div>
  </section>`;
}

function rankingPageMarkup(rows, language, rankingSpec) {
  const sortedRows = sortRowsForRanking(rows, rankingSpec);
  return `<section class="ranking-page">
    <div class="ranking-heading">
      <h2 class="ranking-title">${htmlEscape(rankingReportTitle(language, rankingSpec))}</h2>
    </div>
    ${kdaLeaderboardTable(sortedRows, language, { rankingSpec })}
  </section>`;
}

function kdaRowsToHtml(rows, language = 'zh', { wipe, user, rankingSpec = RANKING_TYPES[0], timeZone = '' } = {}) {
  const totals = kdaTotals(rows);
  const exportedAt = nowIso();
  const days = wipePlayDays(wipe, exportedAt);
  const title = expandVitalRustName(wipe?.name || exportText(language, 'kdaData'));
  const serverName = expandVitalRustName(wipe?.serverName || '');
  const freshness = kdaDataFreshness(rows);
  return reportShell({
    language,
    title,
    metaChips: [
      serverName,
      `${exportText(language, 'dataSyncedAt')}: ${formatExportDateTime(freshness.syncedAt, language, timeZone)}`,
      `${exportText(language, 'exportTime')}: ${formatExportDateTime(exportedAt, language, timeZone)}`,
      `${exportText(language, 'exportedBy')}: ${userDisplayName(user)}`
    ].filter(Boolean),
    stats: [
      [exportText(language, 'memberCount'), rows.length],
      [exportText(language, 'kills'), totals.kills],
      [exportText(language, 't3Kills'), totals.t3Kills],
      [exportText(language, 'rockets'), totals.rockets],
      [exportText(language, 'sulfur'), formatExportCompactResource(totals.sulfur, language)],
      [exportText(language, 'metalOre'), formatExportCompactResource(totals.metalOre, language)],
      [exportText(language, 'building'), totals.building],
      [exportText(language, 'playDays'), days]
    ],
    content: `${topPerformerCards(rows, language)}${rankingPageMarkup(rows, language, rankingSpec)}`
  });
}

function participantStatusLabel(status, language) {
  const normalized = normalizeParticipantStatus(status);
  if (normalized === 'join_8h') return exportText(language, 'statusParticipantJoin8h') || 'Join in 8h';
  if (normalized === 'join_16h') return exportText(language, 'statusParticipantJoin16h') || exportText(language, 'statusParticipantBench');
  if (normalized === 'not_attending') return exportText(language, 'statusParticipantNotAttending') || 'Not Attending';
  return exportText(language, 'statusParticipantActive');
}

function displayParticipantName(participant) {
  return participant?.member?.displayName || participant?.member?.steamId || participant?.steamId || '';
}

function exportDetailToCsv(detail, language, user, { exportedAt = nowIso(), timeZone = '' } = {}) {
  const wipe = detail.wipe;
  const kdaLabels = EXPORT_LABELS[language] || EXPORT_LABELS.zh;
  const freshness = kdaDataFreshness(detail.rows || []);
  const lines = [];
  const section = (title) => {
    if (lines.length) lines.push('');
    lines.push(csvEscape(title));
  };

  section(exportText(language, 'serverInfo'));
  lines.push([exportText(language, 'field'), exportText(language, 'value')].map(csvEscape).join(','));
  [
    [exportText(language, 'wipeName'), wipe.name],
    [exportText(language, 'serverName'), wipe.serverName],
    [exportText(language, 'status'), exportWipeStatusText(wipe, language)],
    [exportText(language, 'startedAt'), formatExportDateTime(wipe.startedAt, language, timeZone)],
    [exportText(language, 'closedAt'), formatExportDateTime(wipe.closedAt, language, timeZone)],
    [exportText(language, 'directConnect'), wipe.directConnect],
    [exportText(language, 'vipUrl'), wipe.vipUrl],
    [exportText(language, 'notes'), wipe.notes],
    [exportText(language, 'dataSyncedAt'), formatExportDateTime(freshness.syncedAt, language, timeZone)],
    [exportText(language, 'exportTime'), formatExportDateTime(exportedAt, language, timeZone)],
    [exportText(language, 'exportedBy'), userDisplayName(user)]
  ].forEach((row) => lines.push(row.map(csvEscape).join(',')));

  section(exportText(language, 'participants'));
  lines.push(['#', exportText(language, 'value'), 'Steam ID', kdaLabels[3], exportText(language, 'participantStatus')].map(csvEscape).join(','));
  detail.participants.forEach((participant, index) => {
    lines.push([
      index + 1,
      displayParticipantName(participant),
      participant.member?.steamId || '',
      participant.squadName || '',
      participantStatusLabel(participant.status, language)
    ].map(csvEscape).join(','));
  });

  section(exportText(language, 'squadSummary'));
  lines.push([exportText(language, 'squadSummary'), exportText(language, 'memberCount'), exportText(language, 'kills'), exportText(language, 'sulfur'), exportText(language, 'metalOre'), exportText(language, 'building')].map(csvEscape).join(','));
  const summary = new Map();
  for (const participant of detail.participants) {
    const key = participant.squadId || 'unassigned';
    if (!summary.has(key)) {
      summary.set(key, { name: participant.squadName || '', memberIds: new Set(), kills: 0, sulfur: 0, metalOre: 0, building: 0 });
    }
    summary.get(key).memberIds.add(participant.memberId);
  }
  for (const row of detail.rows) {
    const key = row.squadId || 'unassigned';
    if (!summary.has(key)) {
      summary.set(key, { name: row.squadName || '', memberIds: new Set(), kills: 0, sulfur: 0, metalOre: 0, building: 0 });
    }
    const item = summary.get(key);
    item.memberIds.add(row.memberId);
    item.kills += Number(row.kills || 0);
    item.sulfur += Number(row.sulfur || 0);
    item.metalOre += Number(row.metalOre || 0);
    item.building += Number(row.building || 0);
  }
  for (const item of summary.values()) {
    lines.push([item.name || '-', item.memberIds.size, item.kills, formatExportCompactResource(item.sulfur, language), formatExportCompactResource(item.metalOre, language), item.building].map(csvEscape).join(','));
  }

  section(exportText(language, 'kdaData'));
  lines.push(...kdaRowsToCsv(detail.rows, language).trimEnd().split('\n'));
  return `${lines.join('\n')}\n`;
}

function exportDetailToHtml(detail, language, user, { rankingSpec = RANKING_TYPES[0], exportedAt = nowIso(), timeZone = '' } = {}) {
  const wipe = detail.wipe;
  const rows = detail.rows || [];
  const totals = kdaTotals(rows);
  const days = wipePlayDays(wipe, exportedAt);
  const freshness = kdaDataFreshness(rows);
  const serverItems = [
    [exportText(language, 'serverName'), wipe.serverName || '-'],
    [exportText(language, 'status'), exportWipeStatusText(wipe, language)],
    [exportText(language, 'startedAt'), formatExportDateTime(wipe.startedAt, language, timeZone)],
    [exportText(language, 'closedAt'), formatExportDateTime(wipe.closedAt, language, timeZone)],
    [exportText(language, 'directConnect'), wipe.directConnect || '-'],
    [exportText(language, 'vipUrl'), wipe.vipUrl || '-'],
    [exportText(language, 'notes'), wipe.notes || '-']
  ];
  const content = `
    <section class="section">
      <h2>${htmlEscape(exportText(language, 'serverInfo'))}</h2>
      <div class="kv-grid">${serverItems.map(([label, value]) => `<div class="kv"><span class="label">${htmlEscape(label)}</span><strong>${htmlEscape(value)}</strong></div>`).join('')}</div>
    </section>
    ${topPerformerCards(rows, language)}
    ${rankingPageMarkup(rows, language, rankingSpec)}`;
  return reportShell({
    language,
    title: wipe.name || exportText(language, 'settlement'),
    metaChips: [
      wipe.serverName || '',
      `${exportText(language, 'dataSyncedAt')}: ${formatExportDateTime(freshness.syncedAt, language, timeZone)}`,
      `${exportText(language, 'exportTime')}: ${formatExportDateTime(exportedAt, language, timeZone)}`,
      `${exportText(language, 'exportedBy')}: ${userDisplayName(user)}`
    ].filter(Boolean),
    stats: [
      [exportText(language, 'memberCount'), detail.participants?.length || 0],
      [exportText(language, 'kills'), totals.kills],
      [exportText(language, 't3Kills'), totals.t3Kills],
      [exportText(language, 'rockets'), totals.rockets],
      [exportText(language, 'sulfur'), formatExportCompactResource(totals.sulfur, language)],
      [exportText(language, 'metalOre'), formatExportCompactResource(totals.metalOre, language)],
      [exportText(language, 'building'), totals.building],
      [exportText(language, 'playDays'), days]
    ],
    content
  });
}

function safeFileName(value) {
  return String(value || 'export')
    .replace(/[^a-zA-Z0-9_-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '') || 'export';
}

function cleanDownloadFileName(value, fallback = 'export') {
  return String(value || fallback)
    .replace(/[\u0000-\u001F\u007F<>:"/\\|?*]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 180) || fallback;
}

function downloadNameSlug(value, fallback = 'export') {
  return cleanDownloadFileName(value, fallback)
    .replace(/[^a-zA-Z0-9\u00C0-\uFFFF]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 120) || fallback;
}

function wipeDateToken(wipe) {
  const value = wipe?.startedAt || wipe?.createdAt || nowIso();
  const direct = String(value || '').match(/^\d{4}-\d{2}-\d{2}/)?.[0];
  if (direct) return direct;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? nowIso().slice(0, 10) : date.toISOString().slice(0, 10);
}

function wipeShortDateToken(wipe) {
  return wipeDateToken(wipe).slice(5);
}

function exportServerNameSlug(wipe) {
  const configured = VITAL_RUST_2X_SERVERS.find((server) => (
    server.vitalServerId === String(wipe?.vitalServerId || '') ||
    server.id === String(wipe?.vitalServerId || '')
  ));
  const rawName = expandVitalRustName(wipe?.serverName || wipe?.name || configured?.name || 'Vital Rust');
  const displayName = String(rawName || '')
    .split(/[·|]/)[0]
    .replace(/\bVT\b/g, 'Vital Rust')
    .replace(/\b\d{4}[-/.]\d{2}[-/.]\d{2}\b/g, ' ')
    .replace(/[-–—_/\\]+/g, ' ')
    .replace(/\b\d+\s*x\b/gi, ' ')
    .replace(/\bRust\b/gi, ' ')
    .replace(/\b(Server|Wipe)\b/gi, ' ')
    .replace(/\b(Active|Closed|Current|Planned)\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return downloadNameSlug(displayName, 'Vital');
}

function rankingExportBaseName(wipe) {
  return `NB-${exportServerNameSlug(wipe)}-${wipeShortDateToken(wipe)}`;
}

function rankingPdfFileName(wipe, language, rankingSpec) {
  return cleanDownloadFileName(`${rankingExportBaseName(wipe)} - ${rankingTitle(language, rankingSpec)}.pdf`);
}

function rankingHtmlFileName(wipe, language, rankingSpec) {
  return cleanDownloadFileName(`${rankingExportBaseName(wipe)} - ${rankingTitle(language, rankingSpec)}.html`);
}

function rankingCsvFileName(wipe, language, labelKey = 'kdaData') {
  return cleanDownloadFileName(`${rankingExportBaseName(wipe)} - ${exportText(language, labelKey)}.csv`);
}

function rankingZipFileName(wipe, language) {
  return cleanDownloadFileName(`${rankingExportBaseName(wipe)} - ${exportText(language, 'allRankings')}.zip`);
}

function rankingZipFolderName(wipe, language) {
  return cleanDownloadFileName(`${rankingExportBaseName(wipe)} - ${exportText(language, 'allRankings')}`);
}

function asciiDownloadFileName(fileName) {
  const cleanName = cleanDownloadFileName(fileName);
  const extension = path.extname(cleanName);
  const baseName = extension ? cleanName.slice(0, -extension.length) : cleanName;
  return `${safeFileName(baseName)}${extension || ''}`;
}

function encodeRFC5987ValueChars(value) {
  return encodeURIComponent(value).replace(/['()*]/g, (char) => `%${char.charCodeAt(0).toString(16).toUpperCase()}`);
}

function contentDispositionAttachment(fileName, asciiFileName = fileName) {
  const cleanName = cleanDownloadFileName(fileName);
  return `attachment; filename="${asciiDownloadFileName(asciiFileName || cleanName)}"; filename*=UTF-8''${encodeRFC5987ValueChars(cleanName)}`;
}

function setDownloadFileHeaders(res, { contentType, fileName, asciiFileName, contentLength }) {
  const fallbackName = asciiDownloadFileName(asciiFileName || fileName);
  if (contentType) res.setHeader('Content-Type', contentType);
  res.setHeader('Content-Disposition', contentDispositionAttachment(fileName, asciiFileName));
  res.setHeader('X-NB-Download-Filename', fallbackName);
  if (contentLength !== undefined && contentLength !== null) {
    res.setHeader('Content-Length', String(contentLength));
  }
}

