function queryImageText(language, key) {
  const lang = validExportLanguage(language);
  return QUERY_IMAGE_TEXT[lang]?.[key] || QUERY_IMAGE_TEXT.en[key] || QUERY_IMAGE_TEXT.zh[key] || key;
}

function vitalStatText(language, key) {
  const lang = validExportLanguage(language);
  const exactKey = QUERY_VITAL_LABEL_KEYS[key];
  if (exactKey) return exportText(lang, exactKey);
  const exact = QUERY_VITAL_LABELS[lang]?.[key] || QUERY_VITAL_LABELS.en[key];
  if (exact) return exact;

  const words = QUERY_VITAL_WORDS[lang] || {};
  const englishWords = QUERY_VITAL_WORDS.en || {};
  return String(key || '')
    .split('.')
    .map((part) => words[part] || englishWords[part] || part.replace(/([a-z])([A-Z])/g, '$1 $2'))
    .filter(Boolean)
    .join(' / ');
}

function safeSteamAvatarUrl(value) {
  const url = normalizeText(value, 500);
  if (!url) return '';
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== 'https:') return '';
    if (parsed.hostname === 'avatars.steamstatic.com' || parsed.hostname.endsWith('.steamstatic.com')) return parsed.toString();
  } catch {
    return '';
  }
  return '';
}

function flattenVitalStats(value, prefix = '') {
  if (value === null || value === undefined) return [];
  if (typeof value !== 'object') {
    return [{ key: prefix || 'value', value }];
  }
  const rows = [];
  for (const [key, child] of Object.entries(value)) {
    const nextKey = prefix ? `${prefix}.${key}` : key;
    rows.push(...flattenVitalStats(child, nextKey));
  }
  return rows;
}

function queryDetailImageHtml({ member, kda, language = 'zh', timeZone = '' }) {
  const lang = validExportLanguage(language);
  const avatar = safeSteamAvatarUrl(member.avatar);
  const initial = htmlEscape(String(member.displayName || member.steamId || '?').slice(0, 1).toUpperCase());
  const specialties = normalizeMemberSpecialties(member.specialty)
    .map((item) => queryImageText(lang, item))
    .join(' / ');
  const leaders = (kda?.squad?.leaders || [])
    .map((leader) => leader.displayName || leader.steamId)
    .filter(Boolean)
    .join(' / ');
  const row = kda?.row || null;
  const metricRows = row ? [
    ['onlineTimeMinutes', exportText(lang, 'onlineTime'), row.onlineTimeMinutes],
    ['kills', exportText(lang, 'kills'), row.kills],
    ['t3Kills', exportText(lang, 't3Kills'), row.t3Kills],
    ['deaths', exportText(lang, 'deaths'), row.deaths],
    ['kda', exportText(lang, 'kda'), row.kda],
    ['rockets', exportText(lang, 'rpg'), row.rockets],
    ['sulfur', exportText(lang, 'sulfur'), row.sulfur],
    ['metalOre', exportText(lang, 'metalOre'), row.metalOre],
    ['building', exportText(lang, 'building'), row.building]
  ] : [];
  const vitalRows = row?.raw?.statistics
    ? flattenVitalStats(row.raw.statistics).slice(0, 80)
    : [];
  const generatedAt = nowIso();

  return `<!doctype html>
<html lang="${htmlEscape(lang)}">
<head>
<meta charset="utf-8" />
<style>
* { box-sizing: border-box; }
body {
  margin: 0;
  padding: 28px;
  color: #eef5ff;
  background: #08111f;
  font-family: "Microsoft YaHei UI", "Microsoft YaHei", "Noto Sans CJK SC", "PingFang SC", "Segoe UI", Arial, sans-serif;
}
.capture-card {
  width: 980px;
  overflow: hidden;
  border: 1px solid rgba(122, 204, 255, .34);
  border-radius: 22px;
  background:
    radial-gradient(circle at 80% -10%, rgba(78, 143, 255, .34), transparent 34%),
    linear-gradient(145deg, #0d1729 0%, #111d30 48%, #0c1423 100%);
  box-shadow: 0 24px 70px rgba(0, 0, 0, .42), inset 0 0 0 1px rgba(255, 255, 255, .05);
}
.top {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 18px;
  align-items: center;
  padding: 24px;
  border-bottom: 1px solid rgba(201, 222, 255, .13);
}
.avatar {
  width: 92px;
  height: 92px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 1px solid rgba(122, 204, 255, .42);
  border-radius: 22px;
  color: #dff5ff;
  background: rgba(89, 119, 176, .24);
  font-size: 38px;
  font-weight: 800;
}
.avatar img { width: 100%; height: 100%; object-fit: cover; }
.title h1 {
  margin: 0 0 10px;
  color: #fff;
  font-size: 30px;
  line-height: 1.15;
}
.title p {
  margin: 0;
  color: #9fb3d1;
  font-size: 14px;
  overflow-wrap: anywhere;
}
.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}
.chip {
  padding: 7px 10px;
  border: 1px solid rgba(122, 204, 255, .22);
  border-radius: 999px;
  color: #c8d9f4;
  background: rgba(122, 204, 255, .08);
  font-size: 12px;
  font-weight: 700;
}
.content {
  display: grid;
  gap: 14px;
  padding: 18px;
}
.grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.panel {
  min-width: 0;
  padding: 14px;
  border: 1px solid rgba(179, 204, 239, .18);
  border-radius: 16px;
  background: rgba(255, 255, 255, .055);
}
.panel h2 {
  margin: 0 0 10px;
  color: #dcecff;
  font-size: 15px;
}
.kv {
  display: grid;
  grid-template-columns: 128px minmax(0, 1fr);
  gap: 10px;
  padding: 8px 0;
  border-top: 1px solid rgba(201, 222, 255, .09);
}
.kv:first-of-type { border-top: 0; }
.kv span {
  color: #8fa5c4;
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
}
.kv strong {
  min-width: 0;
  color: #f8fbff;
  font-size: 13px;
  overflow-wrap: anywhere;
}
.metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}
.metric {
  min-height: 72px;
  padding: 12px;
  border: 1px solid rgba(122, 204, 255, .22);
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(122,204,255,.12), rgba(82,99,216,.08));
}
.metric span {
  display: block;
  color: #9fb3d1;
  font-size: 11px;
  font-weight: 800;
}
.metric strong {
  display: block;
  margin-top: 8px;
  color: #ffffff;
  font-size: 20px;
  line-height: 1.1;
  overflow-wrap: anywhere;
}
.vital-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}
.vital-item {
  min-width: 0;
  padding: 9px;
  border: 1px solid rgba(201, 222, 255, .12);
  border-radius: 12px;
  background: rgba(3, 8, 16, .22);
}
.vital-item span,
.vital-item strong {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}
.vital-item span {
  color: #8fa5c4;
  font-size: 10px;
}
.vital-item strong {
  margin-top: 4px;
  color: #f8fbff;
  font-size: 12px;
}
.empty {
  padding: 18px;
  border: 1px dashed rgba(201, 222, 255, .24);
  border-radius: 14px;
  color: #9fb3d1;
  text-align: center;
}
.footer {
  padding: 12px 18px 18px;
  color: #8196b6;
  font-size: 11px;
}
</style>
</head>
<body>
  <article class="capture-card">
    <section class="top">
      <div class="avatar">${avatar ? `<img src="${htmlEscape(avatar)}" alt="" />` : initial}</div>
      <div class="title">
        <h1>${htmlEscape(queryImageText(lang, 'title'))}</h1>
        <p>${htmlEscape(member.displayName || member.steamNickname || member.steamId || '-')} · ${htmlEscape(member.steamId || '-')}</p>
        <div class="chips">
          <span class="chip">${brandName()}</span>
          <span class="chip">${htmlEscape(kda?.serverName || '-')}</span>
          <span class="chip">${htmlEscape(formatExportDateTime(generatedAt, lang, timeZone))}</span>
        </div>
      </div>
    </section>
    <section class="content">
      <div class="grid">
        <section class="panel">
          <h2>${htmlEscape(queryImageText(lang, 'member'))}</h2>
          <div class="kv"><span>${htmlEscape(queryImageText(lang, 'steamNickname'))}</span><strong>${htmlEscape(member.steamNickname || '-')}</strong></div>
          <div class="kv"><span>${htmlEscape(queryImageText(lang, 'steamId'))}</span><strong>${htmlEscape(member.steamId || '-')}</strong></div>
          <div class="kv"><span>${htmlEscape(queryImageText(lang, 'specialty'))}</span><strong>${htmlEscape(specialties || '-')}</strong></div>
          <div class="kv"><span>${htmlEscape(queryImageText(lang, 'squad'))}</span><strong>${htmlEscape(kda?.squad?.name || member.squadName || '-')}</strong></div>
          <div class="kv"><span>${htmlEscape(queryImageText(lang, 'leaders'))}</span><strong>${htmlEscape(leaders || '-')}</strong></div>
        </section>
        <section class="panel">
          <h2>${htmlEscape(queryImageText(lang, 'server'))}</h2>
          <div class="kv"><span>${htmlEscape(exportText(lang, 'serverName'))}</span><strong>${htmlEscape(kda?.wipeName || kda?.serverName || '-')}</strong></div>
          <div class="kv"><span>${htmlEscape(exportText(lang, 'startedAt'))}</span><strong>${htmlEscape(formatExportDateTime(kda?.startedAt, lang, timeZone) || '-')}</strong></div>
          <div class="kv"><span>${htmlEscape(queryImageText(lang, 'kdaUrl'))}</span><strong>${htmlEscape(kda?.playerKdaUrl || kda?.kdaUrl || '-')}</strong></div>
          <div class="kv"><span>${htmlEscape(queryImageText(lang, 'generatedAt'))}</span><strong>${htmlEscape(formatExportDateTime(generatedAt, lang, timeZone))}</strong></div>
        </section>
      </div>
      ${row ? `<section class="panel"><h2>${htmlEscape(exportText(lang, 'kdaData'))}</h2><div class="metrics">${metricRows.map((item) => `<div class="metric"><span>${htmlEscape(item[1])}</span><strong>${htmlEscape(formatKdaMetricValue(row, item[0], lang))}</strong></div>`).join('')}</div></section>` : `<div class="empty">${htmlEscape(queryImageText(lang, 'noKda'))}</div>`}
      <section class="panel">
        <h2>${htmlEscape(queryImageText(lang, 'vitalStats'))}</h2>
        ${vitalRows.length ? `<div class="vital-grid">${vitalRows.map((item) => `<div class="vital-item"><span>${htmlEscape(vitalStatText(lang, item.key))}</span><strong>${htmlEscape(String(item.value))}</strong></div>`).join('')}</div>` : `<div class="empty">${htmlEscape(queryImageText(lang, 'noKda'))}</div>`}
      </section>
    </section>
    <footer class="footer">${brandName()} · ${htmlEscape(formatExportDateTime(generatedAt, lang, timeZone))}</footer>
  </article>
</body>
</html>`;
}

async function htmlToPngBuffer(html) {
  return withChromiumSlot(async () => {
    const { default: puppeteer } = await import('puppeteer-core');
    const browser = await puppeteer.launch({
      executablePath: chromiumExecutablePath(),
      headless: 'new',
      args: chromiumLaunchArgs()
    });
    try {
      const page = await browser.newPage();
      await page.setViewport({ width: 1040, height: 1400, deviceScaleFactor: 2 });
      await page.setContent(html, { waitUntil: 'networkidle0', timeout: 30000 });
      const card = await page.$('.capture-card');
      const buffer = card
        ? await card.screenshot({ type: 'png' })
        : await page.screenshot({ type: 'png', fullPage: true });
      await page.close();
      return buffer;
    } finally {
      await browser.close();
    }
  });
}

async function htmlDocumentsToPdfBuffers(htmlDocuments) {
  return withChromiumSlot(async () => {
    const { default: puppeteer } = await import('puppeteer-core');
    const browser = await puppeteer.launch({
      executablePath: chromiumExecutablePath(),
      headless: 'new',
      args: chromiumLaunchArgs()
    });
    try {
      const buffers = [];
      for (const html of htmlDocuments) {
        const page = await browser.newPage();
        await page.setContent(html, { waitUntil: 'networkidle0', timeout: 30000 });
        buffers.push(await page.pdf({
          format: 'A4',
          landscape: true,
          printBackground: true,
          preferCSSPageSize: true,
          margin: { top: '12mm', right: '12mm', bottom: '12mm', left: '12mm' }
        }));
        await page.close();
      }
      return buffers;
    } finally {
      await browser.close();
    }
  });
}

async function sendRankingPdfExport(res, { detail, rows, wipe, language, user, rankingSpecs, timeZone, detailExport = false }) {
  const exportedAt = nowIso();
  const documents = rankingSpecs.map((rankingSpec) => {
    return {
      fileName: rankingPdfFileName(wipe, language, rankingSpec),
      asciiFileName: rankingPdfFileName(wipe, 'en', rankingSpec),
      html: detailExport
        ? exportDetailToHtml(detail, language, user, { rankingSpec, exportedAt, timeZone })
        : kdaRowsToHtml(rows, language, { wipe, user, rankingSpec, timeZone })
    };
  });
  const pdfBuffers = await htmlDocumentsToPdfBuffers(documents.map((item) => item.html));
  if (documents.length === 1) {
    setDownloadFileHeaders(res, {
      contentType: 'application/pdf',
      fileName: documents[0].fileName,
      asciiFileName: documents[0].asciiFileName,
      contentLength: pdfBuffers[0].length
    });
    res.send(pdfBuffers[0]);
    return;
  }
  const zip = new JSZip();
  const folderName = rankingZipFolderName(wipe, language);
  documents.forEach((document, index) => {
    zip.file(`${folderName}/${document.fileName}`, pdfBuffers[index]);
  });
  const zipBuffer = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });
  setDownloadFileHeaders(res, {
    contentType: 'application/zip',
    fileName: rankingZipFileName(wipe, language),
    asciiFileName: rankingZipFileName(wipe, 'en'),
    contentLength: zipBuffer.length
  });
  res.send(zipBuffer);
}

