  router.put('/wechat/join-applications/:id', requireWechatAuth, defaultJsonParser, ...WECHAT_APPLICATION_EDIT_RATE_LIMITERS, async (req, res, next) => {
    try {
      const applicationId = normalizeText(req.params.id, 120);
      const snapshot = sqlitePrimaryMode()
        ? await readWechatApplicationWriteStore(req.wechatUser.id)
        : await readMemberRankingRuntimeStore({ reference: 'wechatRanking' });
      const snapshotApplication = (snapshot.joinApplications || []).find((item) => item.id === applicationId && item.wechatUserId === req.wechatUser.id);
      if (!snapshotApplication) {
        fail(res, 404, '成员注册申请不存在');
        return;
      }
      if (!isWechatApplicationActive(snapshotApplication)) {
        fail(res, 400, '当前申请状态不能修改');
        return;
      }
      const requestedStatus = normalizeText(req.body?.status, 20);
      let resolved = null;
      let joinInput = null;
      if (requestedStatus !== 'cancelled') {
        const mergedJoinInput = {
          ...snapshotApplication,
          ...(req.body || {})
        };
        if (Object.hasOwn(req.body || {}, 'notes')) {
          mergedJoinInput.reason = req.body.notes;
        } else if (Object.hasOwn(req.body || {}, 'reason')) {
          mergedJoinInput.notes = req.body.reason;
        }
        joinInput = normalizeWechatJoinApplicationInput(mergedJoinInput);
        if (Object.hasOwn(req.body || {}, 'steamInput')) {
          resolved = await resolveWechatJoinSteamTarget(snapshot, req.body.steamInput, applicationId, req.wechatUser.id);
        }
      }

      let editedApplicationId = '';
      let adminReviewMessages = [];
      let directStore = null;
      if (sqlitePrimaryMode()) {
        const result = await editJoinApplicationDirect(req, { applicationId, requestedStatus, resolved, joinInput });
        editedApplicationId = result.application.id;
        adminReviewMessages = result.adminReviewMessages || [];
        directStore = result.store;
      } else {
        await updateStore((store) => {
        const application = (store.joinApplications || []).find((item) => item.id === applicationId && item.wechatUserId === req.wechatUser.id);
        if (!application) throw Object.assign(new Error('成员注册申请不存在'), { status: 404 });
        if (!isWechatApplicationActive(application)) {
          throw Object.assign(new Error('当前申请状态不能修改'), { status: 400 });
        }
        const wechatUser = (store.wechatUsers || []).find((item) => item.id === req.wechatUser.id);
        if (!wechatUser) throw Object.assign(new Error('微信用户不存在'), { status: 404 });
        if (wechatUser.status === 'blocked') throw Object.assign(new Error('当前微信账号已被限制使用'), { status: 403 });
        if (wechatUser.memberId) throw Object.assign(new Error('当前微信已绑定成员'), { status: 409 });

        const updatedAt = nowIso();
        const previousStatus = wechatApplicationStatus(application);
        if (requestedStatus === 'cancelled') {
          application.status = 'cancelled';
          application.updatedAt = updatedAt;
          editedApplicationId = application.id;
          appendLog(store, req, 'join_application_cancel', `取消成员注册 ${application.steamId}`, {
            steamId: application.steamId,
            targetId: application.id,
            metadata: { applicationId: application.id, wechatUserId: wechatUser.id }
          });
          return;
        }
        if (requestedStatus && !WECHAT_APPLICATION_STATUSES.has(requestedStatus)) {
          throw Object.assign(new Error('申请状态无效'), { status: 400 });
        }
        if (resolved) {
          const previousSteamId = normalizeText(application.steamId, 80);
          const targetMember = assertWechatMemberRegistrationTargetAvailable(store, resolved.steamId, {
            ignoredApplicationId: application.id,
            wechatUserId: wechatUser.id
          });
          const steamChanged = previousSteamId !== resolved.steamId;
          application.steamInput = resolved.rawInput || normalizeText(req.body?.steamInput, 500);
          application.steamId = resolved.steamId;
          application.steamNickname = targetMember?.steamNickname || (steamChanged ? '' : application.steamNickname || '');
          application.steamAvatar = targetMember?.avatar || (steamChanged ? '' : application.steamAvatar || '');
          application.targetMemberId = targetMember?.id || '';
          application.registrationMode = targetMember ? 'claim' : 'create';
          if (steamChanged) {
            application.profileStats = null;
            application.profileStatsFetchedAt = '';
          }
        } else {
          const targetMember = assertWechatMemberRegistrationTargetAvailable(store, application.steamId, {
            ignoredApplicationId: application.id,
            wechatUserId: wechatUser.id
          });
          application.targetMemberId = targetMember?.id || '';
          application.registrationMode = targetMember ? 'claim' : 'create';
        }
        Object.assign(application, {
          wechatId: '',
          discordId: '',
          region: '',
          timezone: '',
          timeZone: '',
          inviterText: joinInput.inviterText,
          notes: joinInput.notes,
          reason: joinInput.reason,
          specialties: joinInput.specialties,
          specialtiesRaw: joinInput.specialtiesRaw,
          status: 'pending',
          updatedAt
        });
        editedApplicationId = application.id;
        if (previousStatus !== 'pending') {
          adminReviewMessages = collectWechatAdminReviewNotifications(store, {
            application,
            applicationType: 'join'
          });
        }
        appendLog(store, req, 'join_application_edit', `更新成员注册 ${application.steamId}`, {
          steamId: application.steamId,
          targetId: application.id,
          metadata: { applicationId: application.id, wechatUserId: wechatUser.id }
        });
        });
      }
      void queueWechatSubscribeMessages('admin-join-review-resubmit', adminReviewMessages);
      const store = directStore || await readWechatAccessStatusStore(req.wechatUser.id);
      const wechatUser = (store.wechatUsers || []).find((item) => item.id === req.wechatUser.id) || req.wechatUser;
      const application = (store.joinApplications || []).find((item) => item.id === editedApplicationId);
      send(res, {
        application: publicJoinApplication(store, application),
        accessStatus: wechatAccessStatusPayload(store, wechatUser)
      });
      if (requestedStatus !== 'cancelled') {
        queueWechatJoinApplicationProfileEnrichment(editedApplicationId, application?.steamId || resolved?.steamId || snapshotApplication.steamId);
      }
    } catch (error) {
      next(error);
    }
  });

