  router.get('/wechat/admin/join-applications', requireWechatOrWebReviewManager, ...WECHAT_ADMIN_READ_RATE_LIMITERS, async (req, res, next) => {
    try {
      const store = await readWechatAdminReviewStore();
      const status = normalizeText(req.query?.status, 20);
      const q = normalizeText(req.query?.q, 120).toLowerCase();
      const filtered = (store.joinApplications || [])
        .filter((item) => !status || status === 'all' || wechatApplicationStatus(item) === status)
        .filter((item) => {
          if (!q) return true;
          const member = item.memberId ? store.members.find((candidate) => candidate.id === item.memberId) : null;
          const wechatUser = item.wechatUserId ? (store.wechatUsers || []).find((candidate) => candidate.id === item.wechatUserId) : null;
          return [
            item.steamId,
            item.steamNickname,
            item.discordId,
            item.region,
            item.timezone,
            item.inviterText,
            item.reason,
            ...(item.specialties || []),
            member ? memberDisplayName(member) : '',
            wechatUser?.nickname || ''
          ].some((value) => String(value || '').toLowerCase().includes(q));
        });
      const counts = Object.fromEntries([...WECHAT_APPLICATION_STATUSES].map((item) => [item, 0]));
      for (const application of store.joinApplications || []) {
        const key = wechatApplicationStatus(application);
        counts[key] = (counts[key] || 0) + 1;
      }
      send(res, {
        applications: sortedJoinApplications(store, filtered),
        counts
      });
    } catch (error) {
      next(error);
    }
  });

  router.post('/wechat/admin/join-applications/:id/review', requireWechatOrWebReviewManager, defaultJsonParser, async (req, res, next) => {
    let affectedMemberId = '';
    try {
      const applicationId = normalizeText(req.params.id, 120);
      const nextStatus = normalizeText(req.body?.status, 20);
      if (!WECHAT_JOIN_REVIEW_STATUSES.has(nextStatus)) {
        fail(res, 400, '审核状态无效');
        return;
      }
      const adminNote = normalizeText(req.body?.adminNote || req.body?.reviewNote, 1000);
      let reviewedApplicationId = '';
      let directReview = null;
      let reviewNotificationMessages = [];
      if (sqlitePrimaryMode()) {
        directReview = await reviewJoinApplicationDirect(req, { applicationId, nextStatus, adminNote });
        reviewedApplicationId = directReview.application.id;
        affectedMemberId = directReview.affectedMemberId;
        reviewNotificationMessages = directReview.reviewNotificationMessages || [];
      } else {
        await updateStore((store) => {
        const application = (store.joinApplications || []).find((item) => item.id === applicationId);
        if (!application) throw Object.assign(new Error('成员注册申请不存在'), { status: 404 });
        const wechatUser = (store.wechatUsers || []).find((item) => item.id === application.wechatUserId);
        if (!wechatUser) throw Object.assign(new Error('微信用户不存在'), { status: 404 });
        if (wechatUser.status === 'blocked') throw Object.assign(new Error('当前微信账号已被限制使用'), { status: 403 });
        if (application.status === 'approved' || application.status === 'cancelled') {
          throw Object.assign(new Error('当前申请状态不能审核'), { status: 400 });
        }
        if (wechatUser.memberId) {
          throw Object.assign(new Error('当前微信已绑定成员'), { status: 409 });
        }

        const reviewedAt = nowIso();
        application.status = nextStatus;
        application.adminNote = adminNote;
        application.reviewNote = adminNote;
        application.reviewedByUserId = reviewActorId(req);
        application.reviewedAt = reviewedAt;
        application.updatedAt = reviewedAt;
        reviewedApplicationId = application.id;

        if (nextStatus === 'approved') {
          const registration = applyWechatMemberRegistrationApproval(store, {
            application,
            wechatUser,
            reviewedAt,
            reviewerUserId: reviewActorId(req)
          });
          const member = registration.member;
          affectedMemberId = member.id;
          recordWechatReviewNotification(store, {
            wechatUser,
            application,
            applicationType: 'join',
            status: nextStatus,
            adminNote
          });
          appendLog(store, req, 'join_application_approve', `通过成员注册 ${memberDisplayName(member)}`, {
            targetId: application.id,
            steamId: member.steamId,
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req),
            metadata: {
              applicationId: application.id,
              memberId: member.id,
              wechatUserId: wechatUser.id,
              registrationMode: application.registrationMode
            }
          });
          appendLog(
            store,
            req,
            registration.created ? 'member_add' : 'wechat_member_claim',
            registration.created
              ? `成员注册创建成员 ${memberDisplayName(member)}`
              : `成员注册认领成员 ${memberDisplayName(member)}`,
            {
              targetId: member.id,
              steamId: member.steamId,
              actorUserId: reviewActorId(req),
              actorUsername: requestActorUsername(req),
              metadata: {
                applicationId: application.id,
                rawInput: member.rawInput,
                source: 'wechat_member_registration'
              }
            }
          );
          reviewNotificationMessages = collectWechatReviewResultSubscribeMessages(store, {
            application,
            applicationType: 'join',
            status: nextStatus,
            adminNote
          });
          return;
        }

        recordWechatReviewNotification(store, {
          wechatUser,
          application,
          applicationType: 'join',
          status: nextStatus,
          adminNote
        });
        appendLog(store, req, nextStatus === 'need_more' ? 'join_application_need_more' : 'join_application_reject', `审核成员注册 ${application.steamId} ${nextStatus}`, {
          targetId: application.id,
          steamId: application.steamId,
          actorUserId: reviewActorId(req),
          actorUsername: requestActorUsername(req),
          metadata: { applicationId: application.id, wechatUserId: wechatUser.id, status: nextStatus }
        });
        reviewNotificationMessages = collectWechatReviewResultSubscribeMessages(store, {
          application,
          applicationType: 'join',
          status: nextStatus,
          adminNote
        });
        });
      }
      const syncResult = affectedMemberId
        ? await triggerNewMemberDataSyncSafe([affectedMemberId], { source: 'wechat_member_registration' })
        : { queued: false, requested: 0 };
      const store = directReview?.store || await readStore();
      const application = (store.joinApplications || []).find((item) => item.id === reviewedApplicationId);
      const wechatUser = application ? (store.wechatUsers || []).find((item) => item.id === application.wechatUserId) : null;
      send(res, {
        application: publicJoinApplication(store, application, { includeWechatUser: true }),
        accessStatus: wechatUser ? wechatAccessStatusPayload(store, wechatUser) : null,
        syncQueued: syncResult.queued ? syncResult.requested : 0
      });
      void queueWechatSubscribeMessages('join-review-result', reviewNotificationMessages);
    } catch (error) {
      next(error);
    }
  });

