  router.post('/wechat/admin/wipes', requireWechatOrWebAdmin, defaultJsonParser, async (req, res, next) => {
    try {
      let createdWipeId = '';
      let notificationMessages = [];
      const directResult = await writeWechatAdminWipeLifecycleDirect(req, 'create', { body: req.body || {} });
      if (directResult) {
        createdWipeId = directResult.updatedWipeId;
        notificationMessages = directResult.notificationMessages || [];
      } else {
        await updateStore((store) => {
          if (currentWipe(store)) throw Object.assign(new Error('已经存在进行中的档期'), { status: 409 });
          const fields = wechatWipeFieldsFromBody(store, req.body || {});
          if (!fields.serverName) throw Object.assign(new Error('服务器名称必填'), { status: 400 });
          const createdAt = nowIso();
          const signupStatus = normalizeText(req.body?.signupStatus, 40) === 'closed' ? 'closed' : 'open';
          const wipe = {
            id: createId('wipe'),
            status: 'active',
            closedAt: '',
            ...fields,
            signupStatus,
            signupOpenedAt: signupStatus === 'open' ? createdAt : '',
            signupClosedAt: signupStatus === 'closed' ? createdAt : '',
            createdBy: reviewActorId(req),
            createdAt,
            updatedAt: createdAt
          };
          store.wipes.unshift(wipe);
          createdWipeId = wipe.id;
          if (signupStatus === 'open') {
            notificationMessages = collectWechatWipeOpenNotifications(store, wipe);
          }
          appendLog(store, req, 'wechat_admin_wipe_create', `微信管理创建开荒 ${wipe.name}`, {
            targetId: wipe.id,
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req),
            metadata: { vitalServerId: wipe.vitalServerId, signupStatus }
          });
        });
      }
      const store = sqlitePrimaryMode()
        ? await readWechatWipeRuntimeStore(createdWipeId, { includePermissionRoles: true })
        : await readWipeRuntimeStore({
            includeUploads: true,
            includeWechatUsers: true,
            includePermissionRoles: true,
            includeSettings: true
          });
      const wipe = store.wipes.find((item) => item.id === createdWipeId);
      send(res, {
        wipe: publicWechatAdminWipe(store, wipe),
        current: publicWechatAdminWipe(store, currentWipe(store))
      });
      void queueWechatWipeReminderSchedule(createdWipeId);
      void queueWechatSubscribeMessages('wipe-open-create', notificationMessages);
    } catch (error) {
      next(error);
    }
  });

