  router.post('/wechat/admin/wipes/:id/sync-kda', requireWechatOrWebAdmin, rateLimit({ name: 'wechat_admin_kda_sync', windowMs: 180_000, max: 1 }), async (req, res, next) => {
    let syncJob = null;
    try {
      const requestedWipeId = normalizeText(req.params.id, 120);
      await refreshStartedWipeVitalMetadataIfNeeded(requestedWipeId, req, { requireMissingVitalWipeId: true });
      const snapshot = await readKdaRuntimeStore(requestedWipeId === 'current'
        ? { reference: 'current' }
        : { requestedWipeId });
      const targetWipe = resolveWechatAdminSyncWipe(snapshot, requestedWipeId);
      assertWechatAdminSyncWipe(targetWipe);

      const activeParticipants = kdaSyncTargetParticipants(snapshot, targetWipe);
      const membersById = new Map(snapshot.members.map((member) => [member.id, member]));
      const kdaCapability = wipeKdaCapability(targetWipe);
      const requested = activeParticipants.length;
      const estimatedSeconds = estimateVitalKdaSyncSeconds(requested);
      const startedAt = nowIso();
      let counts = { imported: 0, ignored: 0, requested, completed: 0, estimatedSeconds, source: 'none', ...kdaCapability };

      const activeSyncJobInput = {
        type: 'kda',
        scope: 'kda',
        targetWipeId: targetWipe.id,
        targetVitalWipeId: normalizeText(targetWipe.vitalWipeId, 120),
        targetServerId: normalizeText(targetWipe.vitalServerId, 80)
      };
      const activeJob = findActiveSyncJob(snapshot, activeSyncJobInput);
      if (activeJob) {
        const store = await readKdaRuntimeStore({
          wipeIds: [targetWipe.id],
          syncJobIds: [activeJob.id],
          scopeMembersToRows: true
        });
        const wipe = store.wipes.find((item) => item.id === targetWipe.id);
        const payload = wechatWipeParticipantsPayload(store, wipe, '');
        send(res, {
          ...counts,
          job: publicSyncJob((store.syncJobs || []).find((job) => job.id === activeJob.id) || activeJob),
          syncState: publicSyncState(store.syncState?.kda || {}),
          wipe: publicWechatWipe(wipe, store),
          reused: true,
          ...payload
        });
        return;
      }

      const backgroundRequested = ['1', 'true', 'yes', 'queue', 'queued'].includes(
        normalizeText(req.query?.background || req.query?.async || req.query?.queued, 20).toLowerCase()
      );
      if (backgroundRequested) {
        const finishedAt = requested ? '' : nowIso();
        const actor = wechatAdminActor(req);
        const syncJobResult = await createSyncJobUnlessActive({
          type: 'kda',
          source: 'manual',
          scope: 'kda',
          status: requested ? 'queued' : 'completed',
          targetWipeId: targetWipe.id,
          targetVitalWipeId: normalizeText(targetWipe.vitalWipeId, 120),
          targetServerId: normalizeText(targetWipe.vitalServerId, 80),
          targetServerName: expandVitalRustName(targetWipe.serverName || targetWipe.name || ''),
          totalCount: requested,
          percent: requested ? 0 : 100,
          etaSeconds: requested ? estimatedSeconds : 0,
          finishedAt,
          createdBy: reviewActorId(req),
          metadata: {
            runner: SYNC_JOB_RUNNER_METADATA_KEY,
            requestedWipeId: targetWipe.id,
            targetVitalWipeId: normalizeText(targetWipe.vitalWipeId, 120),
            statusKey: 'kda',
            createdByUsername: actor.username || ''
          }
        }, activeSyncJobInput);
        syncJob = syncJobResult.job;
        if (syncJobResult.reused) {
          const store = await readKdaRuntimeStore({
            wipeIds: [targetWipe.id],
            syncJobIds: [syncJob.id],
            scopeMembersToRows: true
          });
          const wipe = store.wipes.find((item) => item.id === targetWipe.id);
          const payload = wechatWipeParticipantsPayload(store, wipe, '');
          send(res, {
            ...counts,
            job: publicSyncJob((store.syncJobs || []).find((job) => job.id === syncJob.id) || syncJob),
            syncState: publicSyncState(store.syncState?.kda || {}),
            wipe: publicWechatWipe(wipe, store),
            reused: true,
            ...payload
          });
          return;
        }
        await writeSyncState('kda', {
          status: requested ? 'queued' : 'complete',
          source: 'manual',
          requested,
          imported: 0,
          ignored: 0,
          completed: 0,
          failed: 0,
          percent: syncStatePercent(0, requested),
          estimatedSeconds,
          etaSeconds: requested ? estimatedSeconds : 0,
          wipeId: targetWipe.id,
          wipeStatus: effectiveWipeStatus(targetWipe),
          ...kdaCapability,
          startedAt: '',
          syncedAt: requested ? '' : finishedAt,
          error: '',
          syncJobId: syncJob.id,
          syncJobType: 'kda',
          syncJobSource: 'manual',
          syncJobScope: 'kda'
        });
        await appendLogDirect(req, 'wechat_admin_kda_sync', `微信管理排队同步 KDA ${targetWipe.name}`, {
          targetId: targetWipe.id,
          actorUserId: actor.id,
          actorUsername: actor.username,
          metadata: { ...counts, queued: Boolean(requested), syncJobId: syncJob.id }
        });
        if (requested) scheduleSyncJobRunner({ force: true });

        const store = await readKdaRuntimeStore({
          wipeIds: [targetWipe.id],
          syncJobIds: [syncJob.id],
          scopeMembersToRows: true
        });
        const wipe = store.wipes.find((item) => item.id === targetWipe.id);
        const payload = wechatWipeParticipantsPayload(store, wipe, '');
        send(res, {
          ...counts,
          queued: Boolean(requested),
          job: publicSyncJob((store.syncJobs || []).find((job) => job.id === syncJob.id) || syncJob),
          syncState: publicSyncState(store.syncState?.kda || {}),
          wipe: publicWechatWipe(wipe, store),
          ...payload
        });
        return;
      }

      const inlineSyncJobResult = await createSyncJobUnlessActive({
        type: 'kda',
        source: 'manual',
        scope: 'kda',
        status: requested ? 'running' : 'completed',
        targetWipeId: targetWipe.id,
        targetVitalWipeId: normalizeText(targetWipe.vitalWipeId, 120),
        targetServerId: normalizeText(targetWipe.vitalServerId, 80),
        targetServerName: expandVitalRustName(targetWipe.serverName || targetWipe.name || ''),
        totalCount: requested,
        percent: requested ? 0 : 100,
        etaSeconds: requested ? estimatedSeconds : 0,
        startedAt,
        finishedAt: requested ? '' : startedAt,
        createdBy: reviewActorId(req)
      }, activeSyncJobInput);
      syncJob = inlineSyncJobResult.job;
      if (inlineSyncJobResult.reused) {
        const store = await readKdaRuntimeStore({
          wipeIds: [targetWipe.id],
          syncJobIds: [syncJob.id],
          scopeMembersToRows: true
        });
        const wipe = store.wipes.find((item) => item.id === targetWipe.id);
        const payload = wechatWipeParticipantsPayload(store, wipe, '');
        send(res, {
          ...counts,
          job: publicSyncJob((store.syncJobs || []).find((job) => job.id === syncJob.id) || syncJob),
          syncState: publicSyncState(store.syncState?.kda || {}),
          wipe: publicWechatWipe(wipe, store),
          reused: true,
          ...payload
        });
        return;
      }
      await writeSyncState('kda', {
        status: requested ? 'running' : 'complete',
        source: 'manual',
        requested,
        imported: 0,
        ignored: 0,
        completed: 0,
        failed: 0,
        percent: syncStatePercent(0, requested),
        estimatedSeconds,
        etaSeconds: requested ? estimatedSeconds : 0,
        wipeId: targetWipe.id,
        wipeStatus: effectiveWipeStatus(targetWipe),
        ...kdaCapability,
        startedAt,
        syncedAt: requested ? '' : startedAt,
        error: '',
        syncJobId: syncJob.id,
        syncJobType: 'kda',
        syncJobSource: 'manual',
        syncJobScope: 'kda'
      });

      if (process.env.NB_DISABLE_EXTERNAL_VITAL === '1') {
        await updateKdaWriteStore((store) => {
          const wipe = store.wipes.find((item) => item.id === targetWipe.id);
          const changed = syncKdaRows(store, wipe);
          counts = { ...counts, imported: changed ? requested : 0, ignored: 0, completed: requested, failed: 0, source: 'local_demo' };
          refreshSettlementSnapshotForWipe(store, wipe, wechatAdminActor(req));
          appendLog(store, req, 'wechat_admin_kda_sync', `微信管理同步 KDA ${wipe.name}`, {
            targetId: wipe.id,
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req),
            metadata: counts
          });
        }, 'wechat_admin_kda_sync_local_demo');
      } else if (activeParticipants.length && kdaCapability.kdaSyncAvailable) {
        const payloadRows = await queueBackgroundTask(
          `wechat-admin-kda-sync:${targetWipe.id}`,
          () => syncVitalKdaForWipe(targetWipe, activeParticipants, membersById),
          VITAL_KDA_SYNC_DELAY_MS,
          { force: true }
        );
        await updateKdaWriteStore((store) => {
          const wipe = store.wipes.find((item) => item.id === targetWipe.id);
          assertKdaVitalWipeTarget(wipe, targetWipe.vitalWipeId);
          const requestedMemberIds = new Set(activeParticipants.map((participant) => participant.memberId));
          const nextCounts = upsertVitalKdaRows(store, wipe, payloadRows, requestedMemberIds);
          counts = { ...counts, ...nextCounts, requested, completed: requested, failed: 0, source: 'vital' };
          refreshSettlementSnapshotForWipe(store, wipe, wechatAdminActor(req));
          appendLog(store, req, 'wechat_admin_kda_sync', `微信管理同步 KDA ${wipe.name}`, {
            targetId: wipe.id,
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req),
            metadata: counts
          });
        }, 'wechat_admin_kda_sync_vital');
      } else if (activeParticipants.length) {
        counts = { ...counts, ...kdaSyncUnavailableCounts(targetWipe, requested, 'manual'), estimatedSeconds };
        await updateKdaWriteStore((store) => {
          const wipe = store.wipes.find((item) => item.id === targetWipe.id);
          refreshSettlementSnapshotForWipe(store, wipe, wechatAdminActor(req));
          appendLog(store, req, 'wechat_admin_kda_sync', `微信管理跳过 KDA 自动同步 ${wipe.name}`, {
            targetId: wipe.id,
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req),
            metadata: counts
          });
        }, 'wechat_admin_kda_sync_unavailable');
      } else {
        await updateKdaWriteStore((store) => {
          const wipe = store.wipes.find((item) => item.id === targetWipe.id);
          appendLog(store, req, 'wechat_admin_kda_sync', `微信管理同步 KDA ${wipe.name}`, {
            targetId: wipe.id,
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req),
            metadata: counts
          });
        }, 'wechat_admin_kda_sync_empty');
      }

      const finalCompleted = Math.max(0, Number(counts.completed ?? requested));
      const finalFailed = Math.max(0, Number(counts.failed || 0));
      await writeSyncState('kda', {
        status: 'complete',
        source: counts.source || 'manual',
        ...counts,
        completed: finalCompleted,
        failed: finalFailed,
        percent: 100,
        etaSeconds: 0,
        wipeId: targetWipe.id,
        wipeStatus: effectiveWipeStatus(targetWipe),
        ...publicWipeKdaCapability(targetWipe),
        syncedAt: nowIso(),
        error: '',
        syncJobId: syncJob.id,
        syncJobType: 'kda',
        syncJobSource: 'manual',
        syncJobScope: 'kda'
      });
      queueMemberRankingCardRefresh('wechat-admin-kda-sync');

      const store = await readKdaRuntimeStore({
        wipeIds: [targetWipe.id],
        syncJobIds: [syncJob.id],
        scopeMembersToRows: true
      });
      const wipe = store.wipes.find((item) => item.id === targetWipe.id);
      const payload = wechatWipeParticipantsPayload(store, wipe, '');
      send(res, {
        ...counts,
        job: publicSyncJob((store.syncJobs || []).find((job) => job.id === syncJob.id) || syncJob),
        syncState: publicSyncState(store.syncState?.kda || {}),
        wipe: publicWechatWipe(wipe, store),
        ...payload
      });
    } catch (error) {
      await failKdaSyncStateFromJob(syncJob, error, 'manual').catch(() => {});
      next(error);
    }
  });

  router.post('/wechat/admin/wipes/:id/sync-playtime', requireWechatOrWebAdmin, rateLimit({ name: 'wechat_admin_playtime_sync', windowMs: 180_000, max: 1 }), async (req, res, next) => {
    let syncJob = null;
    try {
      const requestedWipeId = normalizeText(req.params.id, 120);
      const snapshot = await readBattlemetricsSyncRequestStore({
        battlemetricsWipePlaytimeOnly: true,
        requestedWipeId
      });
      if (!battlemetricsApiKey(snapshot)) {
        fail(res, 400, 'BattleMetrics API Key 尚未配置');
        return;
      }
      const targetWipe = resolveWechatAdminSyncWipe(snapshot, requestedWipeId);
      assertWechatAdminSyncWipe(targetWipe);
      const requestedMemberIds = activeWipeParticipantMemberIds(snapshot, targetWipe);
      const { wipe, targets } = battlemetricsTargetsForWipe(snapshot, targetWipe, requestedMemberIds, Date.now(), { force: true });
      const serverId = battlemetricsServerIdForWipe(wipe);
      if (!wipe || !serverId) {
        fail(res, 400, '当前服务器缺少 BattleMetrics Server ID');
        return;
      }
      const activeSyncJobInput = {
        type: 'battlemetrics_playtime',
        scope: 'battlemetrics',
        targetWipeId: wipe.id,
        targetServerId: serverId
      };
      const activeJob = findActiveSyncJob(snapshot, activeSyncJobInput);
      if (activeJob) {
        const store = await readKdaRuntimeStore({
          wipeIds: [wipe.id],
          syncJobIds: [activeJob.id],
          scopeMembersToRows: true
        });
        const currentWipe = store.wipes.find((item) => item.id === wipe.id);
        const payload = wechatWipeParticipantsPayload(store, currentWipe, '');
        send(res, {
          requested: targets.length,
          updated: 0,
          failed: 0,
          completed: 0,
          job: publicSyncJob((store.syncJobs || []).find((job) => job.id === activeJob.id) || activeJob),
          syncState: publicSyncState(store.syncState?.battlemetrics || store.syncState?.battlemetricsPlaytime || {}),
          battlemetricsQueue: battlemetricsQueueSnapshot(),
          wipe: publicWechatWipe(currentWipe, store),
          reused: true,
          ...payload
        });
        return;
      }
      const estimatedSeconds = estimateBattlemetricsSyncSeconds(targets);
      const backgroundRequested = ['1', 'true', 'yes', 'queue', 'queued'].includes(
        normalizeText(req.query?.background || req.query?.async || req.query?.queued, 20).toLowerCase()
      );
      if (backgroundRequested) {
        const finishedAt = targets.length ? '' : nowIso();
        const actor = wechatAdminActor(req);
        const syncJobResult = await createSyncJobUnlessActive({
          type: 'battlemetrics_playtime',
          source: 'manual',
          scope: 'battlemetrics',
          status: targets.length ? 'queued' : 'completed',
          targetWipeId: wipe.id,
          targetServerId: serverId,
          targetServerName: expandVitalRustName(wipe.serverName || wipe.name || ''),
          totalCount: targets.length,
          percent: targets.length ? 0 : 100,
          etaSeconds: targets.length ? estimatedSeconds : 0,
          finishedAt,
          createdBy: reviewActorId(req),
          metadata: {
            runner: SYNC_JOB_RUNNER_METADATA_KEY,
            requestedMemberIds: targets.map((member) => member.id),
            requestedWipeId: wipe.id,
            statusKey: 'battlemetrics',
            createdByUsername: actor.username || ''
          }
        }, activeSyncJobInput);
        syncJob = syncJobResult.job;
        if (syncJobResult.reused) {
          const store = await readKdaRuntimeStore({
            wipeIds: [wipe.id],
            syncJobIds: [syncJob.id],
            scopeMembersToRows: true
          });
          const currentWipe = store.wipes.find((item) => item.id === wipe.id);
          const payload = wechatWipeParticipantsPayload(store, currentWipe, '');
          send(res, {
            requested: targets.length,
            updated: 0,
            failed: 0,
            completed: 0,
            job: publicSyncJob((store.syncJobs || []).find((job) => job.id === syncJob.id) || syncJob),
            syncState: publicSyncState(store.syncState?.battlemetrics || store.syncState?.battlemetricsPlaytime || {}),
            battlemetricsQueue: battlemetricsQueueSnapshot(),
            wipe: publicWechatWipe(currentWipe, store),
            reused: true,
            ...payload
          });
          return;
        }
        await writeSyncState('battlemetrics', {
          status: targets.length ? 'queued' : 'complete',
          source: 'manual',
          requested: targets.length,
          updated: 0,
          failed: 0,
          completed: 0,
          percent: targets.length ? 0 : 100,
          estimatedSeconds,
          etaSeconds: targets.length ? estimatedSeconds : 0,
          ...battlemetricsWipeSyncInfo(wipe, serverId),
          startedAt: '',
          syncedAt: targets.length ? '' : finishedAt,
          error: '',
          syncJobId: syncJob.id,
          syncJobType: 'battlemetrics_playtime',
          syncJobSource: 'manual',
          syncJobScope: 'battlemetrics'
        });
        await appendLogDirect(req, 'wechat_admin_playtime_sync', `微信管理排队同步在线时长 ${targets.length} 人`, {
          targetId: wipe.id,
          actorUserId: actor.id,
          actorUsername: actor.username,
          metadata: { requested: targets.length, queued: Boolean(targets.length), syncJobId: syncJob.id }
        });
        if (targets.length) scheduleSyncJobRunner();
        const store = await readKdaRuntimeStore({
          wipeIds: [wipe.id],
          syncJobIds: [syncJob.id],
          scopeMembersToRows: true
        });
        const currentWipe = store.wipes.find((item) => item.id === wipe.id);
        const payload = wechatWipeParticipantsPayload(store, currentWipe, '');
        send(res, {
          requested: targets.length,
          updated: 0,
          failed: 0,
          completed: 0,
          estimatedSeconds,
          queued: Boolean(targets.length),
          job: publicSyncJob((store.syncJobs || []).find((job) => job.id === syncJob.id) || syncJob),
          syncState: publicSyncState(store.syncState?.battlemetrics || store.syncState?.battlemetricsPlaytime || {}),
          battlemetricsQueue: battlemetricsQueueSnapshot(),
          wipe: publicWechatWipe(currentWipe, store),
          ...payload
        });
        return;
      }
      const syncJobResult = await createSyncJobUnlessActive({
        type: 'battlemetrics_playtime',
        source: 'manual',
        scope: 'battlemetrics',
        status: targets.length ? 'running' : 'completed',
        targetWipeId: wipe.id,
        targetServerId: serverId,
        targetServerName: expandVitalRustName(wipe.serverName || wipe.name || ''),
        totalCount: targets.length,
        percent: targets.length ? 0 : 100,
        etaSeconds: targets.length ? estimatedSeconds : 0,
        startedAt: nowIso(),
        finishedAt: targets.length ? '' : nowIso(),
        createdBy: reviewActorId(req)
      }, activeSyncJobInput);
      syncJob = syncJobResult.job;
      if (syncJobResult.reused) {
        const store = await readKdaRuntimeStore({ reference: 'wechatRanking' });
        const currentWipe = store.wipes.find((item) => item.id === wipe.id);
        const payload = wechatWipeParticipantsPayload(store, currentWipe, '');
        send(res, {
          requested: targets.length,
          updated: 0,
          failed: 0,
          completed: 0,
          job: publicSyncJob(syncJob),
          battlemetricsQueue: battlemetricsQueueSnapshot(),
          wipe: publicWechatWipe(currentWipe, store),
          reused: true,
          ...payload
        });
        return;
      }
      const counts = await syncBattlemetricsPlaytimeTargets({
        requestedMemberIds,
        manual: true,
        wipeId: wipe.id,
        syncJobId: syncJob.id,
        source: 'manual'
      });
      await appendLogDirect(req, 'wechat_admin_playtime_sync', `微信管理同步在线时长 ${counts.updated}/${counts.requested}`, {
        targetId: wipe.id,
        actorUserId: reviewActorId(req),
        actorUsername: requestActorUsername(req),
        metadata: counts
      });
      const store = await readKdaRuntimeStore({
        wipeIds: [wipe.id],
        syncJobIds: [syncJob.id],
        scopeMembersToRows: true
      });
      const freshWipe = store.wipes.find((item) => item.id === wipe.id);
      const payload = wechatWipeParticipantsPayload(store, freshWipe, '');
      send(res, {
        ...counts,
        job: publicSyncJob((store.syncJobs || []).find((job) => job.id === syncJob.id) || syncJob),
        syncState: publicSyncState(store.syncState?.battlemetrics || store.syncState?.battlemetricsPlaytime || {}),
        battlemetricsQueue: battlemetricsQueueSnapshot(),
        wipe: publicWechatWipe(freshWipe, store),
        ...payload
      });
    } catch (error) {
      await failKdaSyncStateFromJob(syncJob, error, 'manual').catch(() => {});
      next(error);
    }
  });

