  router.delete('/wechat/admin/wipes/:id/participants/:memberId', requireWechatOrWebManager, async (req, res, next) => {
    try {
      const requestedWipeId = normalizeText(req.params.id, 120);
      const requestedMemberId = normalizeText(req.params.memberId, 120);
      let updatedWipeId = '';
      const directResult = await writeWechatAdminWipeParticipantsDirect(req, 'remove', {
        requestedWipeId,
        memberId: requestedMemberId
      });
      if (directResult) {
        updatedWipeId = directResult.updatedWipeId;
      } else {
        await updateStore((store) => {
          const viewer = wechatManagementActor(store, req);
          const wipe = requestedWipeId === 'current'
            ? currentWipe(store)
            : store.wipes.find((item) => item.id === requestedWipeId);
          assertWipeMutable(wipe);
          const participant = store.wipeParticipants.find((item) => item.wipeId === wipe.id && item.memberId === requestedMemberId);
          if (!participant) throw Object.assign(new Error('报名记录不存在'), { status: 404 });
          const member = store.members.find((item) => item.id === requestedMemberId);
          if (member) {
            const squadsByMember = memberSquadMap(store);
            const memberSquad = participant.squadId ? { squadId: participant.squadId } : (squadsByMember.get(member.id) || null);
            const captainSquads = leaderSquads(store, viewer);
            const leaderSquad = memberSquad
              ? captainSquads.find((squad) => squad.id === memberSquad.squadId) || null
              : captainSquads[0] || null;
            if (!canManageWipeParticipant(viewer, member, memberSquad, leaderSquad)) {
              throw Object.assign(new Error('无权移除该报名'), { status: 403 });
            }
          }
          updatedWipeId = wipe.id;
          store.wipeParticipants = store.wipeParticipants.filter((item) => !(item.wipeId === wipe.id && item.memberId === requestedMemberId));
          if (isWipeStartedServer(wipe)) syncKdaRows(store, wipe);
          appendLog(store, req, 'wechat_admin_wipe_signup_remove', `微信管理移除报名 ${member ? memberDisplayName(member) : requestedMemberId}`, {
            targetId: wipe.id,
            steamId: member?.steamId || '',
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req),
            metadata: { memberId: requestedMemberId }
          });
        });
      }
      queueDiscordWipeAttendanceCardRefresh(updatedWipeId, 'wechat_admin_signup_remove');
      const store = sqlitePrimaryMode()
        ? await readWechatWipeRuntimeStore(updatedWipeId, {
            currentMemberId: req.wechatMember?.id,
            includePermissionRoles: true
          })
        : await readWipeRuntimeStore({ includeUploads: true, includeWechatUsers: true, includePermissionRoles: true });
      const viewer = wechatManagementActor(store, req);
      const wipe = store.wipes.find((item) => item.id === updatedWipeId);
      const payload = wechatWipeParticipantsPayload(store, wipe, '', viewer, {
        attendanceModel: wechatAttendanceModelFromRequest(req)
      });
      send(res, {
        wipe: publicWechatWipe(wipe, store),
        ...payload
      });
    } catch (error) {
      next(error);
    }
  });

