  router.post('/wechat/admin/squads', requireWechatOrWebAdmin, defaultJsonParser, async (req, res, next) => {
    try {
      const name = normalizeText(req.body?.name, 80);
      const leaderUserIds = requestedSquadLeaderIds(req.body);
      if (!name) {
        fail(res, 400, '队伍名称必填');
        return;
      }
      if (!leaderUserIds.length) {
        fail(res, 400, '请选择有效队长');
        return;
      }
      let createdSquadId = '';
      const directWrite = await writeWechatAdminSquadDirect(req, 'create', { name, leaderUserIds, body: req.body || {} });
      if (directWrite) {
        createdSquadId = directWrite.squadId;
      } else {
        await updateStore((store) => {
          const leaders = leaderUserIds.map((userId) => (store.users || []).find((user) => user.id === userId));
          if (leaders.some((leader) => !leader)) throw Object.assign(new Error('请选择有效队长'), { status: 400 });
          const createdAt = nowIso();
          const squad = {
            id: createId('squad'),
            name,
            leaderUserId: leaderUserIds[0],
            leaderUserIds,
            color: normalizeText(req.body?.color, 40),
            iconUrl: normalizeText(req.body?.iconUrl || req.body?.icon, 500),
            notes: normalizeText(req.body?.notes, 500),
            createdBy: reviewActorId(req),
            createdAt,
            updatedAt: createdAt,
            archivedAt: ''
          };
          store.squads.unshift(squad);
          leaders.forEach((leader) => ensureAccountMember(store, leader, { ensureSquad: false }));
          createdSquadId = squad.id;
          appendLog(store, req, 'wechat_admin_squad_add', `微信管理创建队伍 ${name}`, {
            targetId: squad.id,
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req, 'wechat_admin'),
            metadata: { leaderUserIds }
          });
        });
      }
      const store = await readWechatAdminSquadRuntimeStore(() => readWipeRuntimeStore({ includeWechatUsers: true, includePermissionRoles: true }));
      const squads = activeSquads(store)
        .map((squad) => publicWechatAdminSquad(store, squad))
        .sort((left, right) => left.name.localeCompare(right.name));
      send(res, {
        squad: publicWechatAdminSquad(store, activeSquadById(store, createdSquadId)),
        squads,
        leaderOptions: (store.users || []).map(publicWechatAdminSquadLeader).filter(Boolean),
        total: squads.length
      });
    } catch (error) {
      next(error);
    }
  });

