  router.delete('/wechat/admin/members/:id', requireWechatOrWebAdmin, async (req, res, next) => {
    try {
      const memberId = normalizeText(req.params.id, 120);
      let deletedMember = null;
      let affectedWechatUsers = [];
      const directDelete = await deleteWechatAdminMemberDirect(req, memberId);
      if (directDelete) {
        deletedMember = directDelete.deletedMember;
        affectedWechatUsers = directDelete.affectedWechatUsers;
      } else {
        await updateStore((store) => {
          const member = store.members.find((item) => item.id === memberId);
          if (!member) throw Object.assign(new Error('成员不存在'), { status: 404 });
          deletedMember = { ...member };
          const linkedWechatUsers = (store.wechatUsers || []).filter((item) => (
            item.memberId === member.id ||
            item.id === member.wechatUserId ||
            (isWechatSystemId(member.wechatId) && item.id === member.wechatId)
          ));
          const updatedAt = nowIso();
          for (const wechatUser of linkedWechatUsers) {
            wechatUser.memberId = '';
            if (wechatUser.status !== 'blocked') wechatUser.status = 'guest';
            wechatUser.updatedAt = updatedAt;
          }
          affectedWechatUsers = linkedWechatUsers.map((item) => ({ ...item }));
          store.members = store.members.filter((item) => item.id !== member.id);
          removeMemberRuntimeRecords(store, [member]);
          appendLog(store, req, 'wechat_admin_member_delete', `微信管理删除成员 ${memberDisplayName(member)}`, {
            steamId: member.steamId,
            targetId: member.id,
            actorUserId: reviewActorId(req),
            actorUsername: requestActorUsername(req, 'wechat_admin')
          });
        });
      }
      const store = await readWechatAdminMembersStore();
      send(res, {
        deleted: true,
        memberId,
        steamId: deletedMember?.steamId || '',
        wechatUsers: affectedWechatUsers.map(publicWechatUser),
        members: store.members.map((member) => publicWechatAdminMember(store, member)).filter(Boolean),
        total: store.members.length
      });
    } catch (error) {
      next(error);
    }
  });

  router.get('/wechat/admin/members', requireWechatOrWebManager, ...WECHAT_ADMIN_READ_RATE_LIMITERS, async (req, res, next) => {
    try {
      const store = await readWechatAdminMembersStore();
      const viewer = wechatManagementActor(store, req);
      const q = normalizeText(req.query?.q, 120).toLowerCase();
      const requestedLimit = Number(req.query?.limit || 50);
      const requestedOffset = Number(req.query?.offset || 0);
      const limit = Number.isFinite(requestedLimit) ? Math.min(200, Math.max(1, requestedLimit)) : 50;
      const offset = Number.isFinite(requestedOffset) ? Math.max(0, Math.floor(requestedOffset)) : 0;
      const bindingFilter = normalizeText(req.query?.binding, 20).toLowerCase();
      const wechatUsersById = new Map((store.wechatUsers || []).map((item) => [item.id, item]));
      const wechatUsersByMemberId = new Map();
      for (const wechatUser of store.wechatUsers || []) {
        if (wechatUser.memberId) wechatUsersByMemberId.set(wechatUser.memberId, wechatUser);
      }
      const members = store.members
        .filter((member) => canViewAllData(viewer) || canManageMemberInStore(store, viewer, member))
        .filter((member) => {
          const wechatUser = wechatUsersByMemberId.get(member.id) || wechatUsersById.get(member.wechatUserId) || null;
          const wechatBound = Boolean(wechatUser || member.wechatUserId || isWechatSystemId(member.wechatId));
          const discordBound = Boolean(member.discordId || member.discordName);
          if (bindingFilter === 'any' && !wechatBound && !discordBound) return false;
          if (bindingFilter === 'wechat' && !wechatBound) return false;
          if (bindingFilter === 'discord' && !discordBound) return false;
          if (bindingFilter === 'both' && (!wechatBound || !discordBound)) return false;
          if (!q) return true;
          return [
            member.steamId,
            member.customName,
            member.steamNickname,
            member.discordId,
            member.discordName,
            member.wechatId,
            wechatUser?.id,
            wechatUser?.nickname,
            wechatUser?.wechatId,
            memberWechatContactId(member, wechatUser)
          ].some((value) => String(value || '').toLowerCase().includes(q));
        })
        .sort((left, right) => memberDisplayName(left).localeCompare(memberDisplayName(right)));
      const pageMembers = members.slice(offset, offset + limit);
      await hydrateMemberScopedRuntimeStore(store, pageMembers.map((member) => member.id));
      send(res, {
        members: pageMembers.map((member) => publicWechatAdminMember(store, member)),
        total: members.length,
        offset,
        limit,
        hasMore: offset + pageMembers.length < members.length,
        binding: ['any', 'wechat', 'discord', 'both'].includes(bindingFilter) ? bindingFilter : ''
      });
    } catch (error) {
      next(error);
    }
  });

