  router.post('/wechat/profile/refresh', requireApprovedWechatMember, ...WECHAT_PROFILE_REFRESH_RATE_LIMITERS, async (req, res, next) => {
    try {
      const snapshot = await readWechatAccessStatusStore(req.wechatUser.id);
      const wechatUser = (snapshot.wechatUsers || []).find((item) => item.id === req.wechatUser.id) || req.wechatUser;
      const member = wechatUser.memberId ? snapshot.members.find((item) => item.id === wechatUser.memberId) : null;
      if (!member) {
        fail(res, 404, '成员不存在');
        return;
      }

      const memberKey = member.id;
      const alreadyRunning = pendingWechatProfileRefreshMembers.has(memberKey);
      let identityRefresh = {
        ok: false,
        updated: false,
        skipped: alreadyRunning,
        error: alreadyRunning ? '资料刷新已在后台进行中' : '',
        steamNickname: '',
        avatar: '',
        fetchedAt: ''
      };
      if (!alreadyRunning) {
        pendingWechatProfileRefreshMembers.add(memberKey);
        const requestContext = {
          ...req,
          headers: { ...(req.headers || {}) },
          ip: req.ip || '',
          socket: { remoteAddress: req.socket?.remoteAddress || '' },
          wechatUser: { ...req.wechatUser },
          user: req.user ? { ...req.user } : null
        };
        let steamProfileOverride;
        let auditLogInBackground = true;
        try {
          const result = await refreshWechatMemberSteamIdentity(member, requestContext);
          steamProfileOverride = result.steamProfile || undefined;
          auditLogInBackground = !result.ok;
          identityRefresh = {
            ok: result.ok,
            updated: result.updated,
            skipped: false,
            error: result.error || '',
            steamNickname: result.steamNickname || '',
            avatar: result.avatar || '',
            fetchedAt: result.fetchedAt || ''
          };
        } catch (error) {
          identityRefresh = {
            ok: false,
            updated: false,
            skipped: false,
            error: normalizeText(error?.message || 'Steam 资料刷新失败', 240),
            steamNickname: '',
            avatar: '',
            fetchedAt: ''
          };
        }
        queueMemberProfileTask(`wechat-profile-refresh:${memberKey}`, async () => {
          try {
            await refreshWechatMemberProfileData({ ...member }, requestContext, {
              forceExternal: true,
              auditLog: auditLogInBackground,
              ...(steamProfileOverride ? { steamProfileOverride } : {})
            });
          } finally {
            pendingWechatProfileRefreshMembers.delete(memberKey);
          }
        }, 0, { force: true }).catch((error) => {
          pendingWechatProfileRefreshMembers.delete(memberKey);
          console.warn('[nb-clan] wechat profile background refresh failed:', error?.message || error);
        });
      }
      const responseStore = alreadyRunning ? snapshot : await readWechatAccessStatusStore(req.wechatUser.id);
      const responseWechatUser = (responseStore.wechatUsers || []).find((item) => item.id === req.wechatUser.id) || wechatUser;
      const responseMember = responseWechatUser.memberId
        ? responseStore.members.find((item) => item.id === responseWechatUser.memberId)
        : null;
      const profile = responseMember
        ? publicWechatMemberProfile(responseStore, responseMember, responseWechatUser, { detailed: true })
        : null;
      send(res, {
        profile,
        member: profile,
        refresh: {
          queued: !alreadyRunning,
          alreadyRunning,
          background: true,
          identity: identityRefresh,
          message: alreadyRunning
            ? '资料刷新已在后台进行中，请稍后查看'
            : (identityRefresh.ok ? 'Steam 资料已更新，其余资料正在后台刷新' : '资料刷新已提交后台，请稍后查看')
        },
        wechatUser: publicWechatUser(responseWechatUser),
        accessStatus: wechatAccessStatusPayload(responseStore, responseWechatUser)
      });
    } catch (error) {
      next(error);
    }
  });

  router.get('/wechat/query', requireApprovedWechatMember, ...WECHAT_QUERY_RATE_LIMITERS, async (req, res, next) => {
    try {
      const rawQuery = normalizeText(req.query?.q || req.query?.steamInput, 500);
      if (!rawQuery) {
        fail(res, 400, '请输入查询内容');
        return;
      }
      const latestRequested = ['1', 'true', 'yes'].includes(String(req.query?.latest || '').toLowerCase());
      const resolved = await resolveSteamInput(rawQuery).catch(() => ({ ok: false, rawInput: rawQuery }));
      let payload = null;
      let queryStore = await readMemberRankingRuntimeStore({ reference: 'wechatRanking' });
      let latestRefresh = null;
      const requesterSteamId = normalizeText(req.wechatMember?.steamId, 80);
      if (latestRequested && resolved.ok && requesterSteamId && requesterSteamId === resolved.steamId && req.wechatMember?.id) {
        const requester = queryStore.members.find((item) => item.id === req.wechatMember.id || item.steamId === requesterSteamId) || req.wechatMember;
        const timings = [];
        try {
          latestRefresh = {
            ok: true,
            ...(await refreshWechatMemberLatestQueryData(requester, {
              timings,
              directKda: true
            }))
          };
          queryStore = await readMemberRankingRuntimeStore({ reference: 'wechatRanking' });
        } catch (error) {
          latestRefresh = {
            ok: false,
            error: normalizeText(error?.message || error || 'latest query refresh failed', 240),
            timings
          };
          if (envFlagEnabled(process.env.NB_DEBUG_WECHAT_QUERY_LATEST)) {
            console.warn('[nb-clan] wechat latest query refresh failed:', error?.message || error);
          }
        }
      }
      let members = [];
      if (resolved.ok) {
        const member = queryStore.members.find((item) => item.steamId === resolved.steamId);
        if (member) members = [member];
      }
      if (!members.length) {
        members = findWechatQueryMembers(queryStore, rawQuery);
      }
      const queryPayloadOptions = {
        ...(latestRequested ? { profileKdaFallback: false } : {}),
        currentVitalKdaCache: new Map()
      };
      const publicMembers = await Promise.all(
        members.map((member) => publicWechatQueryMemberPayload(queryStore, member, req.wechatUser, queryPayloadOptions))
      );
      await appendLogDirect(req, 'wechat_query', `微信查询 ${rawQuery}`, {
        steamId: resolved.ok ? resolved.steamId : '',
        actorUserId: `wechat:${req.wechatUser.id}`,
        actorUsername: requestActorUsername(req),
        metadata: {
          rawInput: rawQuery,
          kind: resolved.kind || 'text',
          resultCount: publicMembers.length,
          wechatUserId: req.wechatUser.id,
          latestRequested,
          latestRefresh: latestRefresh ? {
            ok: latestRefresh.ok,
            error: latestRefresh.error || '',
            timings: latestRefresh.timings || []
          } : null
        }
      });
      payload = {
        query: {
          rawInput: rawQuery,
          steamId: resolved.ok ? resolved.steamId : '',
          kind: resolved.ok ? (resolved.kind || 'steam') : 'text'
        },
        membership: {
          isClanMember: publicMembers.length > 0,
          label: publicMembers.length > 0 ? '战队成员' : '非战队成员',
          description: publicMembers.length > 0
            ? deploymentText("该 SteamID 已在 Clan Portal 成员库中。")
            : deploymentText("该 SteamID 未在 Clan Portal 成员库中；下方仅展示公开 Steam 账号和官服数据。")
        },
        isMember: publicMembers.length > 0,
        member: publicMembers[0] || null,
        members: publicMembers,
        currentWipe: publicMembers[0]?.currentWipe || null
      };
      const missingProfileSteamIds = [];
      for (const member of payload?.members || []) {
        if (member.steamId && !member.avatar) missingProfileSteamIds.push(member.steamId);
        const responseSquads = [member.squad, member.currentWipe?.squad, member.currentWipe?.kda?.squad].filter(Boolean);
        for (const squad of responseSquads) {
          const leaders = squad?.leaders || [squad?.leader].filter(Boolean);
          for (const leader of leaders) {
            if (leader?.steamId && !leader.avatar) missingProfileSteamIds.push(leader.steamId);
          }
        }
      }
      if (!latestRequested && missingProfileSteamIds.length) {
        await backfillMissingMemberProfilesDirect([...new Set(missingProfileSteamIds)]);
        const refreshedStore = await readMemberRankingRuntimeStore({ reference: 'wechatRanking' });
        const refreshedMembers = (payload?.members || [])
          .map((item) => refreshedStore.members.find((member) => member.steamId === item.steamId))
          .filter(Boolean);
        const members = await Promise.all(
          refreshedMembers.map((member) => publicWechatQueryMemberPayload(refreshedStore, member, req.wechatUser, queryPayloadOptions))
        );
        payload = {
          ...payload,
          membership: {
            isClanMember: members.length > 0,
            label: members.length > 0 ? '战队成员' : '非战队成员',
            description: members.length > 0
              ? deploymentText("该 SteamID 已在 Clan Portal 成员库中。")
              : deploymentText("该 SteamID 未在 Clan Portal 成员库中；下方仅展示公开 Steam 账号和官服数据。")
          },
          isMember: members.length > 0,
          member: members[0] || null,
          members,
          currentWipe: members[0]?.currentWipe || null
        };
      }
      if (!payload?.member && resolved.ok && !latestRequested) {
        const store = await readMemberRankingRuntimeStore({ reference: 'wechatRanking' });
        const externalMember = await publicWechatExternalQueryPayload(store, resolved.steamId, queryPayloadOptions);
        payload = {
          ...payload,
          membership: {
            isClanMember: false,
            label: '非战队成员',
            description: deploymentText("该 SteamID 未在 Clan Portal 成员库中；下方仅展示公开 Steam 账号和官服数据。")
          },
          isMember: false,
          member: externalMember,
          members: externalMember ? [externalMember] : [],
          currentWipe: externalMember?.currentWipe || null
        };
      }
      if (latestRefresh) {
        payload.latestRefresh = {
          ok: latestRefresh.ok,
          error: latestRefresh.error || '',
          steamProfile: latestRefresh.steamProfile || null,
          realtime: latestRefresh.realtime || null,
          timings: latestRefresh.timings || []
        };
      }
      send(res, payload);
    } catch (error) {
      next(error);
    }
  });

  router.get('/wechat/rankings', requireApprovedWechatMember, ...WECHAT_READ_RATE_LIMITERS, async (req, res, next) => {
    try {
      const metric = normalizeWechatRankingMetric(req.query?.metric);
      if (!WECHAT_RANKING_METRICS.has(metric)) {
        fail(res, 400, '排行指标不支持');
        return;
      }
      const requestedWipeId = normalizeText(req.query?.wipeId, 120);
      const requestedLimit = Number(req.query?.limit || 50);
      const limit = Number.isFinite(requestedLimit) ? Math.min(100, Math.max(1, requestedLimit)) : 50;
      const store = sqlitePrimaryMode()
        ? await readMemberRankingRuntimeStore({
            requestedWipeId,
            reference: requestedWipeId && requestedWipeId !== 'current' ? '' : 'wechatRanking',
            scopeMembersToRows: true
          })
        : await readStore();
      const wipe = requestedWipeId && requestedWipeId !== 'current'
        ? store.wipes.find((item) => item.id === requestedWipeId)
        : wechatRankingWipe(store);
      if (!wipe) {
        send(res, {
          metric,
          wipe: null,
          rows: [],
          myRow: null,
          dataFreshness: kdaDataFreshness([]),
          emptyState: wechatRankingEmptyState(null, [])
        });
        return;
      }
      const rankingViewer = { id: 'wechat_rankings', username: 'wechat_rankings', role: 'admin' };
      const sortedRows = kdaRowsForWipe(store, wipe, rankingViewer, { scope: 'all', sort: 'kda', order: 'desc' })
        .map((row) => {
          const member = row.member || store.members.find((item) => item.id === row.memberId || item.steamId === row.steamId) || null;
          return member ? { ...row, member, avatar: row.avatar || member.avatar || '' } : row;
        })
        .sort((left, right) => {
          const diff = wechatRankingMetricValue(right, metric) - wechatRankingMetricValue(left, metric);
          if (diff !== 0) return diff;
          return String(left.displayName || left.steamId).localeCompare(String(right.displayName || right.steamId));
        });
      const rankingMemberContext = {
        membersById: new Map((store.members || []).map((member) => [member.id, member]).filter(([id]) => id)),
        membersBySteamId: new Map((store.members || []).map((member) => [member.steamId, member]).filter(([steamId]) => steamId)),
        viewer: req.wechatUser
      };
      const rows = sortedRows
        .slice(0, limit)
        .map((row, index) => {
          const publicRow = publicWechatRankingRow(row, index, metric, store, wipe, rankingMemberContext);
          return {
            ...publicRow,
            isSelf: Boolean(
              (req.wechatMember?.id && publicRow.memberId === req.wechatMember.id) ||
              (req.wechatMember?.steamId && publicRow.steamId === req.wechatMember.steamId)
            )
          };
        });
      const myIndex = sortedRows.findIndex((row) => (
        (req.wechatMember?.id && row.memberId === req.wechatMember.id) ||
        (req.wechatMember?.steamId && row.steamId === req.wechatMember.steamId)
      ));
      const myRow = myIndex >= 0 ? {
        ...publicWechatRankingRow(sortedRows[myIndex], myIndex, metric, store, wipe, rankingMemberContext),
        metricRanks: wechatRankingMetricRanks(sortedRows, sortedRows[myIndex])
      } : null;
      const visibleIds = new Set(rows.map((row) => row.id));
      const freshness = {
        ...kdaDataFreshness(sortedRows),
        ...publicWipeKdaCapability(wipe)
      };
      send(res, {
        metric,
        wipe: publicWechatWipe(wipe, store),
        dataFreshness: freshness,
        emptyState: wechatRankingEmptyState(wipe, sortedRows),
        myRow: myRow ? { ...myRow, isSelf: true, inRows: visibleIds.has(myRow.id) } : null,
        rows
      });
    } catch (error) {
      next(error);
    }
  });

