  router.post('/wechat/wipes/:id/signup', requireApprovedWechatMember, defaultJsonParser, ...WECHAT_WIPE_SIGNUP_RATE_LIMITERS, async (req, res, next) => {
    let addedMemberId = '';
    let updatedWipeId = '';
    let notificationMessages = [];
    try {
      const rawStatus = normalizeText(req.body?.status, 40).toLowerCase();
      const cancelRequested = rawStatus === 'cancel' || rawStatus === 'cancelled';
      const requestedStatus = cancelRequested ? 'cancel' : normalizeWechatWipeSignupStatus(req.body?.status);
      if (!cancelRequested && !requestedStatus) {
        fail(res, 400, '报名状态无效');
        return;
      }
      const requestedWipeId = normalizeText(req.params.id, 120);
      const directResult = await writeWechatWipeSignupDirect(req, {
        requestedWipeId,
        cancelRequested,
        status: requestedStatus,
        note: req.body?.note
      });
      if (directResult) {
        addedMemberId = directResult.addedMemberId || '';
        updatedWipeId = directResult.updatedWipeId || '';
        notificationMessages = directResult.notificationMessages || [];
      } else {
        await updateStore((store) => {
          const wechatUser = (store.wechatUsers || []).find((item) => item.id === req.wechatUser.id);
          const member = wechatUser?.memberId ? store.members.find((item) => item.id === wechatUser.memberId) : null;
          if (!wechatUser) throw Object.assign(new Error('微信用户不存在'), { status: 404 });
          if (!member) throw Object.assign(new Error('微信账号未绑定有效成员'), { status: 403 });
          const wipe = requestedWipeId === 'current'
            ? currentWipe(store)
            : store.wipes.find((item) => item.id === requestedWipeId);
          assertWechatWipeSignupOpen(wipe);
          if (cancelRequested) {
            const result = cancelWechatWipeParticipant(store, { wipe, member, wechatUser });
            updatedWipeId = wipe.id;
            if (result.removed && isWipeStartedServer(wipe)) syncKdaRows(store, wipe);
            appendLog(store, req, 'wechat_wipe_signup_cancel', `微信取消报名 ${memberDisplayName(member)}`, {
              targetId: wipe.id,
              steamId: member.steamId,
              actorUserId: `wechat:${wechatUser.id}`,
              actorUsername: wechatUser.nickname || wechatUser.id,
              metadata: {
                wechatUserId: wechatUser.id,
                memberId: member.id,
                status: 'cancel',
                source: 'wechat',
                removed: result.removed
              }
            });
            return;
          }
          const result = upsertWechatWipeParticipant(store, {
            wipe,
            member,
            wechatUser,
            status: requestedStatus,
            note: req.body?.note
          });
          updatedWipeId = wipe.id;
          if (result.added) addedMemberId = member.id;
          notificationMessages = collectWechatWipeSignupStatusNotification(store, {
            wipe,
            wechatUser,
            status: requestedStatus
          });
          if (isWipeStartedServer(wipe)) syncKdaRows(store, wipe);
          const statusText = attendanceStatusText(requestedStatus, { language: 'zh', context: 'wechat' });
          appendLog(store, req, 'wechat_wipe_signup', `微信报名 ${memberDisplayName(member)} ${statusText}`, {
            targetId: wipe.id,
            steamId: member.steamId,
            actorUserId: `wechat:${wechatUser.id}`,
            actorUsername: wechatUser.nickname || wechatUser.id,
            metadata: {
              wechatUserId: wechatUser.id,
              memberId: member.id,
              status: requestedStatus,
              source: 'wechat'
            }
          });
        });
      }
      const syncResult = addedMemberId
        ? await triggerNewMemberDataSyncSafe([addedMemberId], { source: 'wechat_wipe_signup' })
        : { queued: false, requested: 0 };
      queueDiscordWipeAttendanceCardRefresh(updatedWipeId, 'wechat_self_signup');
      const store = sqlitePrimaryMode()
        ? await readWechatWipeRuntimeStore(updatedWipeId, { currentMemberId: req.wechatMember.id })
        : await readWipeRuntimeStore({ includeUploads: true, includeWechatUsers: true });
      const wipe = store.wipes.find((item) => item.id === updatedWipeId) || null;
      const payload = wechatWipeParticipantsPayload(store, wipe, req.wechatMember.id, null, {
        attendanceModel: wechatAttendanceModelFromRequest(req),
        memberViewer: req.wechatManagementUser || req.wechatUser
      });
      send(res, {
        wipe: publicWechatWipe(wipe, store),
        participant: payload.mySignup,
        ...payload,
        syncQueued: syncResult.queued ? syncResult.requested : 0
      });
      void queueWechatSubscribeMessages('wipe-signup-status', notificationMessages);
    } catch (error) {
      next(error);
    }
  });

