  router.post('/integrations/public-query', rateLimit({ name: 'public_api_query', windowMs: 1_000, max: 10 }), defaultJsonParser, trackManagementRequest(async (req, res, next) => {
    try {
      res.set('Cache-Control', 'no-store');
      const publicApiSource = sqlitePrimaryMode()
        ? ((await getSqliteScalar('settings')) || {})
        : ((await readStore()).settings || {});
      const assertPublicToken = management
        ? await management.authorizePublicToken(readPublicApiToken(req))
        : (await validatePublicApiToken(req, publicApiSource), () => {});

      const resolved = await resolveSteamInput(req.body?.steamInput);
      if (!resolved.ok) {
        queueBackgroundTask(`public-api-query-failed:${Date.now()}`, () => (
          appendLogDirect(req, 'query_failed', resolved.message, { metadata: { rawInput: resolved.rawInput, api: 'public' } })
        ), 0).catch(() => {});
        fail(res, 400, resolved.message);
        return;
      }

      const store = await readMemberQueryRuntimeStore(resolved.steamId);
      assertPublicToken();
      const member = store.members.find((item) => item.steamId === resolved.steamId);
      const data = publicIntegrationQueryPayload(store, resolved, member);
      queueBackgroundTask(`public-api-query-log:${resolved.steamId}:${Date.now()}`, () => (
        appendLogDirect(req, 'public_api_query', `公开 API 查询 SteamID ${resolved.steamId}`, {
          steamId: resolved.steamId,
          metadata: { rawInput: resolved.rawInput, kind: resolved.kind, isMember: Boolean(member) }
        })
      ), 0).catch(() => {});

      const missingProfileSteamIds = [];
      if (data?.member && !data.member.avatar) missingProfileSteamIds.push(resolved.steamId);
      const responseSquads = [data?.member?.squad, data?.currentWipe?.squad].filter(Boolean);
      const leaders = responseSquads.flatMap((squad) => squad?.leaders || [squad?.leader].filter(Boolean));
      for (const leader of leaders) {
        if (leader?.steamId && !leader.avatar) missingProfileSteamIds.push(leader.steamId);
      }
      if (!management && missingProfileSteamIds.length) {
        queueMemberProfileTask(`public-api-profile-backfill:${resolved.steamId}`, () => (
          backfillMissingMemberProfilesDirect([...new Set(missingProfileSteamIds)])
        ), 0).catch(() => {});
      }

      assertPublicToken();
      send(res, { data });
    } catch (error) {
      next(error);
    }
  }));

  router.post('/integrations/rustplus/relay', rateLimit({ name: 'rustplus_relay', windowMs: 1_000, max: 30 }), defaultJsonParser, async (req, res, next) => {
    let tokenValidated = false;
    try {
      const assertRelayCredentialsCurrent = await rustplusRelayAuthCache.authenticate(req);
      assertRelayCredentialsCurrent();
      tokenValidated = true;
      if (relayIngest) {
        const payload = await relayIngest(req.body || {}, { transport: 'http', assertCredentialsCurrent: assertRelayCredentialsCurrent });
        send(res, rustplusRelayIngestAckPayload(payload));
        return;
      }
      let payload;
      try {
        payload = await ingestRustplusRelayPayload(req.body || {});
        await createIntegrationEvent(rustplusIntegrationEventInput(req.body || {}, payload, null, {
          transport: 'http'
        }), { dedupe: true }).catch(() => null);
      } catch (error) {
        await createIntegrationEvent(rustplusIntegrationEventInput(req.body || {}, {}, error, {
          transport: 'http'
        }), { dedupe: true }).catch(() => null);
        throw error;
      }
      if (payload.event?.type === 'clan_chat_message' && !payload.event?.skipped) {
        forwardRustplusRelayChatToDiscord(req, payload).catch(() => {});
      }
      send(res, rustplusRelayIngestAckPayload(payload));
    } catch (error) {
      if (tokenValidated && !relayIngest) {
        await recordRustplusRelayError(error.message || 'Rust+ relay failed').catch(() => {});
      }
      next(error);
    }
  });

