  router.post('/integrations/discord/interactions', express.raw({ type: 'application/json', limit: '1mb' }), async (req, res, next) => {
    try {
      const store = await readSettingsRuntimeStore();
      const globalSettings = discordSettings(store);
      const verified = await verifyDiscordInteractionSignature(req, globalSettings.publicKey);
      if (!verified) {
        fail(res, 401, 'Discord signature verification failed.');
        return;
      }
      const payload = JSON.parse(req.body.toString('utf8') || '{}');
      const memberRegisterCustomId = normalizeText(payload?.data?.custom_id, 120);
      // Discord still delivers both legacy cards and v2 notification cards to
      // this configured endpoint. Preserve the signed bytes for the v2 owner.
      if (managedDiscordInteraction(payload) || notifications?.ownsDiscordInteraction?.(payload)) {
        if (typeof notifications?.handleCallback !== 'function') {
          fail(res, 503, 'Discord signup callback is unavailable.');
          return;
        }
        await notifications.handleCallback('discord', {
          rawBody: req.body, headers: req.headers, receivedAt: nowIso()
        }, { ack: reply => { if (!res.writableEnded) res.status(200).json(reply); } });
        return;
      }
      const settings = discordSettingsForInteraction(store, payload);
      const language = discordInteractionLanguage(payload);
      const integrationEvent = await createIntegrationEvent(discordIntegrationEventInput(payload, req), { dedupe: true }).catch(() => null);
      const recordInteractionFailure = async (error, stage) => {
        if (!integrationEvent?.event?.id || integrationEvent.event.status === 'duplicate') return;
        integrationEvent.responseFailure = {
          errorSummary: normalizeText(error?.message || error || 'Discord interaction failed', 240),
          stage: normalizeText(stage, 80)
        };
        await updateIntegrationEvent(integrationEvent.event.id, {
          status: 'failed',
          processedAt: nowIso(),
          errorSummary: integrationEvent.responseFailure.errorSummary,
          metadata: { stage: integrationEvent.responseFailure.stage }
        }).catch(() => null);
      };
      attachIntegrationEventResponseRecorder(res, integrationEvent, {
        targetId: settings.targetId || '',
        targetName: settings.targetName || ''
      });
      if (payload.type === 1) {
        res.json({ type: 1 });
        return;
      }
      if (legacyRegistrationInteraction(memberRegisterCustomId)) {
        const notice = legacyRegistrationNotice(payload.locale || 'en');
        res.json(discordInteractionMessage(`${notice.message}\n${notice.loginUrl}`));
        return;
      }
      if (payload.type === 5 && memberRegisterCustomId === discordMemberRegisterCustomId('remove_submit')) {
        try {
          const message = await applyDiscordMemberRemove(req, payload);
          res.json(discordInteractionMessage(message));
        } catch (error) {
          await recordInteractionFailure(error, 'member_remove');
          res.json(discordInteractionMessage(error.message || discordText(language, 'memberRemoveFailed')));
        }
        return;
      }
      if (payload.type === 5 && memberRegisterCustomId.startsWith(`${DISCORD_VITAL_VIP_PREFIX}:submit`)) {
        try {
          res.json(await applyDiscordVitalVipUpdate(req, payload));
        } catch (error) {
          await recordInteractionFailure(error, 'vip_update');
          res.json(discordInteractionMessage(error.message || discordVitalVipText(language, 'updateFailed')));
        }
        return;
      }
      if (payload.type === 5 && memberRegisterCustomId.startsWith(`${DISCORD_MEMBER_REGISTER_PREFIX}:submit`)) {
        try {
          const message = await applyDiscordMemberRegister(req, payload);
          res.json(discordInteractionMessage(message));
        } catch (error) {
          await recordInteractionFailure(error, 'member_register');
          res.json(discordInteractionMessage(error.message || discordText(language, 'memberRegisterFailed')));
        }
        return;
      }
      if (payload.type === 2) {
        try {
          res.json(await applyDiscordWipeAttendanceCommand(req, payload, settings));
        } catch (error) {
          await recordInteractionFailure(error, 'wipe_attendance_command');
          res.json(discordInteractionMessage(error.message || discordText(language, 'attendanceFailed')));
        }
        return;
      }
      if (payload.type !== 3) {
        res.json(discordInteractionMessage(discordText(language, 'thisActionUnsupported')));
        return;
      }
      try {
        if (memberRegisterCustomId.startsWith(`${DISCORD_MEMBER_REVIEW_PREFIX}:`)) {
          const result = await applyDiscordMemberReview(req, payload, settings);
          if (result?.type === 'update') {
            res.json(discordInteractionUpdateMessage(result.message));
            if (result.followup) {
              sendDiscordInteractionFollowup(payload, result.followup).catch(() => {});
            }
            return;
          }
          res.json(discordInteractionMessage(result?.content || discordText(language, 'memberReviewUpdated')));
          return;
        }
        if (memberRegisterCustomId === `${DISCORD_MEMBER_REGISTER_PREFIX}:open`) {
          if (!effectiveDiscordMemberRegisterRoleSquadRules(settings).length) {
            res.json(discordInteractionMessage(discordText(language, 'notConfiguredDiscordRole')));
            return;
          }
          if (!canUseDiscordMemberRegister(payload, settings)) {
            res.json(discordInteractionMessage(discordText(language, 'registerMemberDenied')));
            return;
          }
          res.json(discordMemberRegisterSpecialtyMessage(payload));
          return;
        }
        if (memberRegisterCustomId === `${DISCORD_VITAL_VIP_PREFIX}:open`) {
          const discordUserId = discordUserIdFromInteraction(payload);
          const member = await readDiscordMemberForUserId(discordUserId);
          if (!member) {
            res.json(discordInteractionMessage(discordVitalVipText(language, 'needRegistration')));
            return;
          }
          res.json(discordVitalVipTypeMessage(member, payload));
          return;
        }
        if (memberRegisterCustomId === `${DISCORD_VITAL_VIP_PREFIX}:provider`) {
          res.json(await applyDiscordVipProviderSelection(req, payload));
          return;
        }
        if (memberRegisterCustomId === `${DISCORD_VITAL_VIP_PREFIX}:type` || memberRegisterCustomId.startsWith(`${DISCORD_VITAL_VIP_PREFIX}:type:`)) {
          res.json(await applyDiscordVitalVipTypeSelection(req, payload));
          return;
        }
        if (memberRegisterCustomId.startsWith(`${DISCORD_MEMBER_RANKING_PREFIX}:metric:`)) {
          const metric = memberRegisterCustomId.split(':')[2] || DISCORD_MEMBER_RANKING_DEFAULT_METRIC;
          const rankingStore = sqlitePrimaryMode()
            ? await readMemberRankingRuntimeStore({ reference: 'wechatRanking', scopeMembersToRows: true })
            : await readStore();
          res.json(await buildDiscordMemberRankingMetricInteraction(rankingStore, metric, settings));
          return;
        }
        if (memberRegisterCustomId === `${DISCORD_MEMBER_RANKING_PREFIX}:mine`) {
          const discordUserId = discordUserIdFromInteraction(payload);
          const rankingStore = sqlitePrimaryMode()
            ? await readMemberRankingRuntimeStore({ reference: 'wechatRanking' })
            : await readStore();
          const member = discordMemberForUserId(rankingStore, discordUserId);
          if (!member) {
            res.json(discordInteractionMessage(discordText(language, 'noBoundDiscordMember')));
            return;
          }
          queueDiscordOriginalInteractionDelete(payload, DISCORD_MEMBER_RANKING_DELETE_DELAY_MS, 'member_ranking_mine');
          res.json(buildDiscordMemberRankingMineMessage(rankingStore, member, language));
          return;
        }
        if (memberRegisterCustomId === discordMemberRegisterCustomId('remove_open')) {
          if (!canUseDiscordMemberManage(payload, settings)) {
            res.json(discordInteractionMessage(settings.memberManageRoleId
              ? discordText(language, 'removeManageDenied')
              : discordText(language, 'removeNeedAdmin')));
            return;
          }
          res.json(discordMemberRemoveModal(payload));
          return;
        }
        if (memberRegisterCustomId === discordMemberRegisterCustomId('specialty')) {
          if (!effectiveDiscordMemberRegisterRoleSquadRules(settings).length) {
            res.json(discordInteractionMessage(discordText(language, 'notConfiguredDiscordRole')));
            return;
          }
          if (!canUseDiscordMemberRegister(payload, settings)) {
            res.json(discordInteractionMessage(discordText(language, 'registerMemberDenied')));
            return;
          }
          const specialty = discordMemberRegisterSpecialtyFromPayload(payload);
          res.json(discordMemberRegisterVipTypeMessage(specialty, payload));
          return;
        }
        if (memberRegisterCustomId.startsWith(`${DISCORD_MEMBER_REGISTER_PREFIX}:vip_type:`)) {
          if (!effectiveDiscordMemberRegisterRoleSquadRules(settings).length) {
            res.json(discordInteractionMessage(discordText(language, 'notConfiguredDiscordRole')));
            return;
          }
          if (!canUseDiscordMemberRegister(payload, settings)) {
            res.json(discordInteractionMessage(discordText(language, 'registerMemberDenied')));
            return;
          }
          const specialty = discordMemberRegisterSpecialtyFromPayload(payload);
          const vipType = discordMemberRegisterVipTypeFromPayload(payload);
          res.json(discordMemberRegisterModal(specialty, payload, vipType));
          return;
        }
        const schedulingNotice = legacySignupInteractionNotice(memberRegisterCustomId);
        if (schedulingNotice) { res.json(schedulingNotice); return; }
	        if (memberRegisterCustomId.startsWith(`${DISCORD_CUSTOM_ID_PREFIX}:`)) {
	          const integrationEventId = integrationEvent?.event?.status === 'duplicate' ? '' : integrationEvent?.event?.id;
	          res.once('finish', () => {
	            queueDiscordSignupInteraction(req, payload, language, { integrationEventId });
	          });
	          res.json(discordInteractionDeferredUpdateMessage());
	          return;
	        }
        const result = await applyDiscordSignup(req, payload);
        if (typeof result === 'object' && result?.type === 'update') {
          res.json(discordInteractionUpdateMessage(result.message));
          if (result.followup) {
            sendDiscordInteractionFollowup(payload, result.followup).catch(() => {});
          }
          return;
        }
        if (typeof result === 'object' && result?.type) {
          res.json(result);
          return;
        }
        const message = typeof result === 'object' ? result?.content : result;
        res.json(discordInteractionMessage(message));
      } catch (error) {
        await recordInteractionFailure(error, memberRegisterCustomId.startsWith(`${DISCORD_MEMBER_REVIEW_PREFIX}:`)
          ? 'member_review'
          : 'component');
        res.json(discordInteractionMessage(memberRegisterCustomId.startsWith(`${DISCORD_MEMBER_REVIEW_PREFIX}:`)
          ? discordMemberReviewErrorMessage(error, language)
          : (error.message || discordText(language, 'attendanceFailed'))));
      }
    } catch (error) {
      next(error);
    }
  });

  router.post('/integrations/kook/events', express.raw({ type: '*/*', limit: '1mb' }), async (req, res, next) => {
    try {
      const store = await readSettingsRuntimeStore();
      const settings = kookSettings(store);
      const payload = parseKookWebhookPayload(req.body, settings);
      const data = kookEventData(payload);
      const verifyToken = kookEventVerifyToken(payload);
      const buttonBody = kookButtonEventBody(payload);
      const configuredVerifyToken = kookVerifyToken(settings);
      if (!configuredVerifyToken) {
        fail(res, 503, 'KOOK verify token is not configured.');
        return;
      }
      if (!timingSafeEqualText(verifyToken, configuredVerifyToken)) {
        fail(res, 401, 'KOOK verify token mismatch.');
        return;
      }
      if (data.channel_type === 'WEBHOOK_CHALLENGE') {
        await createIntegrationEvent(kookIntegrationEventInput(payload, buttonBody), { dedupe: true }).catch(() => null);
        sendKookChallengeResponse(res, data.challenge);
        return;
      }
      const buttonValue = buttonBody && kookButtonEventValue(buttonBody);
      if (buttonValue && !buttonValue.startsWith(KOOK_MEMBER_RANKING_PREFIX) &&
        (/^[A-Za-z0-9_-]{43}$/.test(buttonValue) || /^nb(?:confirm|late):/.test(buttonValue))) {
        if (typeof notifications?.handleCallback !== 'function') {
          fail(res, 503, 'KOOK signup callback is unavailable.');
          return;
        }
        res.set('Cache-Control', 'no-store');
        await notifications.handleCallback('kook', {
          rawBody: req.body, headers: req.headers, receivedAt: nowIso()
        }, { ack: reply => { if (!res.writableEnded) res.status(200).json(reply); } });
        return;
      }
      if (buttonBody) {
        const claim = claimKookWebhookEvent(payload, buttonBody);
        const integrationEvent = await createIntegrationEvent(kookIntegrationEventInput(payload, buttonBody, claim), { dedupe: true }).catch(() => null);
        const activeIntegrationEventId = integrationEvent?.event?.status === 'duplicate' ? '' : integrationEvent?.event?.id;
        const queued = queueKookWebhookButtonEvent(payload, claim, { integrationEventId: activeIntegrationEventId });
        if (integrationEvent?.event?.id) {
          const duplicate = integrationEvent.event.status === 'duplicate' || !queued.queued;
          await updateIntegrationEvent(integrationEvent.event.id, {
            status: duplicate ? 'duplicate' : 'queued',
            processedAt: duplicate ? nowIso() : '',
            metadata: {
              queued: Boolean(queued.queued),
              reason: queued.reason || '',
              memoryDedupeKey: queued.key || claim.key || ''
            }
          }).catch(() => null);
        }
        res.json({ ok: true, queued: Boolean(queued.queued) });
        return;
      }
      await createIntegrationEvent(kookIntegrationEventInput(payload, buttonBody), { dedupe: true }).catch(() => null);
      res.json({ ok: true });
    } catch (error) {
      next(error);
    }
  });

