  router.post('/settings/proxy/test', requireModuleEdit('system'), async (req, res, next) => {
    try {
      if (!rootOnly(req, res)) return;
      const service = normalizeText(req.body?.service, 40);
      if (!['battlemetrics', 'kda'].includes(service)) {
        fail(res, 400, '代理测试服务无效');
        return;
      }
      const targetUrl = service === 'battlemetrics'
        ? battlemetricsUrl('/servers', { 'page[size]': 1 })
        : '';
      const operationRun = await createOperationRun({
        type: 'config_test',
        platform: 'system',
        source: 'manual',
        status: 'running',
        targetType: 'config_service',
        targetId: service,
        dedupeKey: `config-test:${service}:${Date.now()}`,
        createdBy: requestActorUserId(req),
        metadata: { service }
      }).catch(() => null);
      requireOperationRun(operationRun);
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), 10_000);
      const startedMs = Date.now();
      try {
        if (service === 'kda') {
          await fetchVitalServerWipes('19');
          await finishOperationRun(operationRun, {
            status: 'succeeded',
            metadata: { service, status: 200, durationMs: Date.now() - startedMs }
          });
          send(res, {
            service,
            success: true,
            status: 200,
            durationMs: Date.now() - startedMs
          });
          return;
        }
        const response = await serviceFetch(service, targetUrl, {
          method: 'GET',
          headers: { accept: 'application/json' },
          signal: controller.signal
        });
        const success = response.status < 500;
        await finishOperationRun(operationRun, {
          status: success ? 'succeeded' : 'failed',
          errorSummary: success ? '' : `HTTP ${response.status}`,
          retryable: !success,
          metadata: { service, status: response.status, durationMs: Date.now() - startedMs }
        });
        send(res, {
          service,
          success,
          status: response.status,
          durationMs: Date.now() - startedMs
        });
      } catch (error) {
        await finishOperationRun(operationRun, {
          status: 'failed',
          errorSummary: normalizeText(error.message || '代理测试失败', 240),
          retryable: true,
          metadata: { service, durationMs: Date.now() - startedMs }
        });
        fail(res, 502, normalizeText(error.message || '代理测试失败', 240));
      } finally {
        clearTimeout(timer);
      }
    } catch (error) {
      next(error);
    }
  });

