  router.post('/settings/battlemetrics/sync-playtime', requireModuleEdit('api'), rateLimit({ name: 'battlemetrics_playtime_sync', windowMs: 180_000, max: 1 }), async (req, res, next) => {
    let syncJob = null;
    try {
      if (!rootOnly(req, res)) return;
      const requestedMemberIds = Array.isArray(req.body?.memberIds)
        ? req.body.memberIds.map((id) => normalizeText(id, 80)).filter(Boolean)
        : null;
      const immediateRequest = Boolean(
        process.env.NB_DISABLE_BACKGROUND_JOBS === '1' ||
        (requestedMemberIds && requestedMemberIds.length === 1)
      );
      const requestedWipeId = normalizeText(req.body?.wipeId, 120);
      const snapshot = await readBattlemetricsSyncRequestStore(requestedMemberIds ? {
        memberIds: requestedMemberIds,
        includeWipeParticipants: false,
        requestedWipeId
      } : {});
      const targetWipe = battlemetricsTargetWipe(snapshot, requestedWipeId);
      const { wipe, targets } = battlemetricsTargetsForWipe(snapshot, targetWipe, requestedMemberIds, Date.now(), {
        force: true,
        includeAllMembers: !requestedMemberIds
      });
      const estimatedSeconds = estimateBattlemetricsSyncSeconds(targets);
      const serverId = battlemetricsServerIdForWipe(wipe);
      if (!wipe || !serverId) {
        fail(res, 400, '当前服务器缺少 BattleMetrics Server ID');
        return;
      }
      const activeSyncJobInput = {
        type: 'battlemetrics_playtime',
        scope: 'battlemetrics',
        targetWipeId: wipe?.id || '',
        targetServerId: serverId
      };
      const activeJob = findActiveSyncJob(snapshot, activeSyncJobInput);
      if (activeJob) {
        send(res, {
          job: publicSyncJob(activeJob),
          battlemetrics: battlemetricsSettingsPayload(snapshot),
          battlemetricsQueue: battlemetricsQueueSnapshot(),
          syncState: publicSyncState(snapshot.syncState?.battlemetrics || {}),
          reused: true
        });
        return;
      }
      const syncJobResult = await createSyncJobUnlessActive({
        type: 'battlemetrics_playtime',
        source: 'manual',
        scope: 'battlemetrics',
        status: immediateRequest ? 'running' : (targets.length ? 'queued' : 'completed'),
        targetWipeId: wipe?.id || '',
        targetServerId: serverId,
        targetServerName: expandVitalRustName(wipe?.serverName || wipe?.name || ''),
        totalCount: targets.length,
        percent: targets.length ? 0 : 100,
        etaSeconds: targets.length ? estimatedSeconds : 0,
        finishedAt: targets.length ? '' : nowIso(),
        createdBy: req.user.id,
        metadata: immediateRequest ? {} : {
          runner: SYNC_JOB_RUNNER_METADATA_KEY,
          requestedMemberIds: targets.map((member) => member.id),
          requestedWipeId: requestedWipeId || 'current',
          statusKey: 'battlemetrics',
          createdByUsername: req.user.username || ''
        }
      }, activeSyncJobInput);
      syncJob = syncJobResult.job;
      if (syncJobResult.reused) {
        const store = await readBattlemetricsSyncRequestStore({
          battlemetricsStatusOnly: true,
          syncJobIds: [syncJob.id]
        });
        send(res, {
          job: publicSyncJob((store.syncJobs || []).find((job) => job.id === syncJob.id) || syncJob),
          battlemetrics: battlemetricsSettingsPayload(store),
          battlemetricsQueue: battlemetricsQueueSnapshot(),
          syncState: publicSyncState(store.syncState?.battlemetrics || snapshot.syncState?.battlemetrics || {}),
          reused: true
        });
        return;
      }
      if (!immediateRequest) {
        await writeSyncState('battlemetrics', {
          status: targets.length ? 'queued' : 'complete',
          source: 'manual',
          requested: targets.length,
          updated: 0,
          failed: 0,
          completed: 0,
          percent: targets.length ? 0 : 100,
          estimatedSeconds,
          etaSeconds: targets.length ? estimatedSeconds : 0,
          ...(wipe && serverId ? battlemetricsWipeSyncInfo(wipe, serverId) : {}),
          startedAt: '',
          syncedAt: targets.length ? '' : nowIso(),
          error: '',
          syncJobId: syncJob.id,
          syncJobType: 'battlemetrics_playtime',
          syncJobSource: 'manual',
          syncJobScope: 'battlemetrics'
        });
        await appendLogDirect(req, 'battlemetrics_playtime_sync', `排队同步 BattleMetrics 在线时间 ${targets.length} 人`, {
          metadata: { requested: targets.length }
        });
        if (targets.length) scheduleSyncJobRunner({ force: true });
        const store = await readBattlemetricsSyncRequestStore({
          battlemetricsStatusOnly: true,
          syncJobIds: [syncJob.id]
        });
        send(res, {
          queued: Boolean(targets.length),
          job: publicSyncJob((store.syncJobs || []).find((job) => job.id === syncJob.id) || syncJob),
          syncState: publicSyncState(store.syncState?.battlemetrics || {}),
          battlemetrics: battlemetricsSettingsPayload(store),
          battlemetricsQueue: battlemetricsQueueSnapshot()
        });
        return;
      }
      const counts = await syncBattlemetricsPlaytimeTargets({
        requestedMemberIds,
        manual: true,
        wipeId: requestedWipeId,
        syncJobId: syncJob.id,
        source: 'manual'
      });
      await appendLogDirect(req, 'battlemetrics_playtime_sync', `同步 BattleMetrics 在线时间 ${counts.updated}/${counts.requested}`, { metadata: counts });
      const store = await readBattlemetricsSyncRequestStore({
        battlemetricsStatusOnly: true,
        syncJobIds: [syncJob.id]
      });
      send(res, {
        ...counts,
        job: publicSyncJob((store.syncJobs || []).find((job) => job.id === syncJob.id) || syncJob),
        battlemetrics: battlemetricsSettingsPayload(store),
        battlemetricsQueue: battlemetricsQueueSnapshot(),
        syncState: publicSyncState(store.syncState?.battlemetrics || {})
      });
    } catch (error) {
      await failSyncJob(syncJob?.id, error).catch(() => {});
      next(error);
    }
  });

