  router.post('/members', requireMemberCollectionManagement, async (req, res, next) => {
    try {
      if (blockMemberRoleManagement(req, res)) return;
      const resolved = await resolveSteamInput(req.body?.steamInput);
      if (!resolved.ok) {
        fail(res, 400, resolved.message);
        return;
      }

      const customName = normalizeText(req.body?.customName, 80);
      assertWebMemberVipPurchaseDate(req.body || {});
      const profile = await nicknameForSteamId(resolved.steamId);
      const member = {
        id: createId('member'),
        steamId: resolved.steamId,
        rawInput: resolved.rawInput,
        customName,
        steamNickname: profile.nickname,
        avatar: profile.avatar,
        discordId: normalizeText(req.body?.discordId, 80),
        discordName: normalizeText(req.body?.discordName, 120),
        wechatId: normalizeText(req.body?.wechatId, 80),
        wechatUserId: '',
        phone: normalizeText(req.body?.phone, 80),
        notes: normalizeText(req.body?.notes, 240),
        specialty: normalizeMemberSpecialties(req.body?.specialty),
        ...normalizeMemberVipInput(req.body || {}),
        battlemetricsId: normalizeText(req.body?.battlemetricsId, 80),
        invitedByUserId: req.user.id,
        createdAt: nowIso(),
        updatedAt: nowIso()
      };

      const directWrite = await writeWebMemberCreateDirect(req, member);
      if (!directWrite) {
        await updateStore((store) => {
          if (store.members.some((item) => item.steamId === member.steamId)) {
            throw Object.assign(new Error('该 SteamID 已经是成员'), { status: 409 });
          }
          store.members.unshift(member);
          if (Object.hasOwn(req.body || {}, 'squadId') && normalizeText(req.body.squadId, 80)) {
            setMemberSquad(store, member, req.body.squadId, req.user);
          }
          appendLog(store, req, 'member_add', `添加成员 ${memberDisplayName(member)}`, {
            steamId: member.steamId,
            targetId: member.id,
            metadata: { rawInput: member.rawInput }
          });
        });
      }
      const syncResult = await triggerNewMemberDataSyncSafe([member.id], { source: 'member_add' });
      if (normalizeText(req.query?.response, 40) === 'minimal') {
        send(res, {
          member: {
            id: member.id,
            steamId: member.steamId,
            customName: member.customName,
            steamNickname: member.steamNickname,
            avatar: member.avatar,
            squadId: normalizeText(req.body?.squadId, 80),
            createdAt: member.createdAt
          },
          syncQueued: syncResult.queued ? syncResult.requested : 0
        });
        return;
      }
      const payload = await memberListPayloadForViewer(req.user, req.query || {});
      send(res, {
        members: payload.members,
        total: payload.total,
        offset: payload.offset,
        limit: payload.limit,
        hasMore: payload.hasMore,
        syncQueued: syncResult.queued ? syncResult.requested : 0
      });
    } catch (error) {
      next(error);
    }
  });

  router.post('/members/bulk', requireMemberCollectionManagement, async (req, res, next) => {
    try {
      if (blockMemberRoleManagement(req, res)) return;
      const lines = String(req.body?.text || '')
        .split(/\r?\n/)
        .map((line) => line.trim())
        .filter(Boolean)
        .slice(0, MAX_BULK_MEMBER_LINES);

      if (!lines.length) {
        fail(res, 400, 'Steam ID 必填');
        return;
      }

      const specialty = normalizeMemberSpecialties(req.body?.specialty);
      const squadId = Object.hasOwn(req.body || {}, 'squadId') ? normalizeText(req.body.squadId, 80) : '';
      assertWebMemberVipPurchaseDate(req.body || {});
      const seenSteamIds = new Set();
      const failedResults = [];
      const candidates = [];

      for (const input of lines) {
        const resolved = await resolveSteamInput(input);
        if (!resolved.ok) {
          failedResults.push({ input, steamId: '', status: 'failed', message: resolved.message });
          continue;
        }
        if (seenSteamIds.has(resolved.steamId)) {
          failedResults.push({ input, steamId: resolved.steamId, status: 'skipped', message: '重复 Steam ID' });
          continue;
        }
        seenSteamIds.add(resolved.steamId);
        candidates.push({ input, resolved });
      }

      const preparedMembers = [];
      for (const candidate of candidates) {
        const profile = await nicknameForSteamId(candidate.resolved.steamId);
        const createdAt = nowIso();
        preparedMembers.push({
          input: candidate.input,
          member: {
            id: createId('member'),
            steamId: candidate.resolved.steamId,
            rawInput: candidate.resolved.rawInput,
            customName: '',
            steamNickname: profile.nickname,
            avatar: profile.avatar,
            discordId: '',
            wechatId: '',
            wechatUserId: '',
            phone: '',
            notes: '',
            specialty,
            ...normalizeMemberVipInput(req.body || {}),
            battlemetricsId: '',
            invitedByUserId: req.user.id,
            createdAt,
            updatedAt: createdAt
          }
        });
      }

      const results = [...failedResults];
      const importedMemberIds = [];
      let imported = 0;
      let skipped = failedResults.filter((item) => item.status === 'skipped').length;
      let failed = failedResults.filter((item) => item.status === 'failed').length;

      const directWrite = await writeWebMemberBulkCreateDirect(req, preparedMembers, { results, skipped, failed, squadId });
      if (directWrite) {
        imported = directWrite.imported;
        skipped = directWrite.skipped;
        failed = directWrite.failed;
        results.length = 0;
        results.push(...directWrite.results);
        importedMemberIds.push(...directWrite.importedMemberIds);
      } else {
        await updateStore((store) => {
          const existingSteamIds = new Set(store.members.map((member) => member.steamId));
          for (const item of preparedMembers) {
            if (existingSteamIds.has(item.member.steamId)) {
              skipped += 1;
              results.push({ input: item.input, steamId: item.member.steamId, status: 'skipped', message: '该 SteamID 已经是成员' });
              continue;
            }
            store.members.unshift(item.member);
            existingSteamIds.add(item.member.steamId);
            if (squadId) {
              setMemberSquad(store, item.member, squadId, req.user);
            }
            imported += 1;
            importedMemberIds.push(item.member.id);
            results.push({ input: item.input, steamId: item.member.steamId, status: 'imported', message: memberDisplayName(item.member) });
          }

          if (imported > 0) {
            appendLog(store, req, 'member_bulk_add', `批量导入成员 ${imported} 人`, {
              metadata: { imported, skipped, failed, squadId }
            });
          }
        });
	      }

	      const syncResult = await triggerNewMemberDataSyncSafe(importedMemberIds, { source: 'member_bulk_add' });
	      if (normalizeText(req.query?.response, 40) === 'minimal') {
	        send(res, { imported, skipped, failed, results, syncQueued: syncResult.queued ? syncResult.requested : 0 });
	        return;
	      }
	      const payload = await memberListPayloadForViewer(req.user, req.query || {});
	      send(res, { members: payload.members, imported, skipped, failed, results, syncQueued: syncResult.queued ? syncResult.requested : 0 });
    } catch (error) {
      next(error);
    }
  });

