  router.post('/members/:id/battlemetrics-id/refresh', requireAuth, rateLimit({ name: 'battlemetrics_id_refresh', windowMs: 60_000, max: 6 }), async (req, res, next) => {
    try {
      if (blockMemberRoleManagement(req, res)) return;
      const snapshot = await readBattlemetricsIdRefreshRequestStore({
        memberId: req.params.id,
        wipeId: req.body?.wipeId
      });
      const current = snapshot.members.find((item) => item.id === req.params.id);
      if (!current) {
        fail(res, 404, '成员不存在');
        return;
      }
      if (!canManageMemberInStore(snapshot, req.user, current)) {
        fail(res, 403, '无权管理该成员');
        return;
      }
      const apiKey = battlemetricsApiKey(snapshot);
      if (!apiKey) {
        fail(res, 400, 'BattleMetrics API Key 尚未配置');
        return;
      }

      const operationStore = await readActiveOperationRunsByTargetStore({
        type: 'battlemetrics_id_refresh',
        platform: 'battlemetrics',
        targetId: current.id
      });
      const activeRun = ensureOperationRuns(operationStore).find((run) => (
        run.type === 'battlemetrics_id_refresh' &&
        operationRunIsActive(run.status) &&
        run.targetId === current.id &&
        Date.now() - timestampForSort(run.updatedAt || run.startedAt || run.createdAt) <= OPERATION_RUN_STALE_MS
      ));
      const member = await memberProfileDetailPayloadForViewer(current.id, req.user);
      if (activeRun) {
        send(res, {
          member,
          battlemetricsId: member?.battlemetricsId || current.battlemetricsId || '',
          queued: true,
          reused: true,
          operationRun: publicOperationRun(activeRun)
        });
        return;
      }

      const operationRun = await createOperationRun({
        type: 'battlemetrics_id_refresh',
        platform: 'battlemetrics',
        source: 'manual',
        status: 'queued',
        targetType: 'member',
        targetId: current.id,
        createdBy: req.user?.id || '',
        metadata: {
          steamId: current.steamId || '',
          wipeId: normalizeText(req.body?.wipeId, 120)
        }
      });
      requireOperationRun(operationRun);
      queueBackgroundTask(`battlemetrics-id-refresh:${current.id}`, () => refreshBattlemetricsIdForMember(current.id, req, operationRun.id), 0, { force: true });
      send(res, {
        member,
        battlemetricsId: member?.battlemetricsId || current.battlemetricsId || '',
        queued: true,
        operationRun: publicOperationRun(operationRun)
      });
    } catch (error) {
      next(error);
    }
  });

