  router.put('/members/:id', requireAuth, async (req, res, next) => {
    try {
      const store = sqlitePrimaryMode() ? await readMemberRefreshRequestStore(req.params.id) : await readStore();
      const current = store.members.find((member) => member.id === req.params.id);
      if (!current) {
        fail(res, 404, '成员不存在');
        return;
      }
      if (!canManageMemberInStore(store, req.user, current)) {
        fail(res, 403, '无权管理该成员');
        return;
      }
      const memberSelfEdit = isMember(req.user);
      const editBody = memberSelfEdit ? {
        ...req.body,
        steamInput: current.steamId,
        squadId: undefined,
        battlemetricsId: undefined
      } : (req.body || {});
      assertWebMemberVipPurchaseDate(editBody || {}, current);

      const resolved = await resolveMemberEditSteamInput(editBody?.steamInput, current);
      if (!resolved.ok) {
        fail(res, 400, resolved.message);
        return;
      }

      const nextProfile = resolved.steamId === current.steamId
        ? { nickname: current.steamNickname, avatar: current.avatar || '' }
        : await nicknameForSteamId(resolved.steamId);
      const responseMemberOnly = req.query?.response === 'member';
	      const result = await updateMemberDirect(req, { editBody, memberSelfEdit, resolved, nextProfile });
	      if (responseMemberOnly) {
	        const nextStore = sqlitePrimaryMode()
	          ? await readMemberDetailRuntimeStore(result.updatedMemberId)
	          : await readMemberRuntimeBaseStore();
	        if (!sqlitePrimaryMode()) await hydrateMemberScopedRuntimeStore(nextStore, [result.updatedMemberId]);
	        const nextMember = nextStore.members.find((member) => member.id === result.updatedMemberId);
	        send(res, { member: nextMember ? enrichMember(nextStore, nextMember, req.user) : null });
	        return;
      }
      if (result.members) {
        send(res, { members: result.members });
        return;
      }
      const payload = await memberListPayloadForViewer(req.user, req.query || {});
      send(res, { members: payload.members });
    } catch (error) {
      next(error);
    }
  });

  router.delete('/members', requireMemberCollectionManagement, async (req, res, next) => {
    try {
      if (blockMemberRoleManagement(req, res)) return;
      const memberIds = [...new Set((Array.isArray(req.body?.memberIds) ? req.body.memberIds : [])
        .map((id) => normalizeText(id, 80))
        .filter(Boolean))];
      if (!memberIds.length) {
        fail(res, 400, '未选择成员');
        return;
      }
      let deleted = 0;
      const directDelete = await deleteWebMembersDirect(req, memberIds, { bulk: true });
      if (directDelete) {
        deleted = directDelete.deleted;
      } else {
        await updateStore((store) => {
          const membersById = new Map(store.members.map((member) => [member.id, member]));
          const missingId = memberIds.find((id) => !membersById.has(id));
          if (missingId) throw Object.assign(new Error('成员不存在'), { status: 404 });
          const targetMembers = memberIds.map((id) => membersById.get(id));
          const blockedMember = targetMembers.find((member) => !canManageMemberInStore(store, req.user, member));
          if (blockedMember) {
            throw Object.assign(new Error('无权管理该成员'), { status: 403 });
          }
          const deleteIds = new Set(targetMembers.map((member) => member.id));
          deleted = deleteIds.size;
          store.members = store.members.filter((item) => !deleteIds.has(item.id));
          removeMemberRuntimeRecords(store, targetMembers);
          appendLog(store, req, 'member_bulk_delete', `批量删除成员 ${deleted} 人`, {
            metadata: {
              deleted,
              memberIds: [...deleteIds],
              names: targetMembers.map((member) => memberDisplayName(member))
            }
          });
        });
      }
      if (normalizeText(req.query?.response, 40) === 'minimal') {
        send(res, { deleted, deletedMemberIds: memberIds });
        return;
      }
      const payload = await memberListPayloadForViewer(req.user, req.query || {});
      send(res, { members: payload.members, deleted });
    } catch (error) {
      next(error);
    }
  });

