  router.post('/squads', requireModuleEdit('squads'), async (req, res, next) => {
    try {
      const name = normalizeText(req.body?.name, 80);
      const leaderUserIds = requestedSquadLeaderIds(req.body);
      if (!name) {
        fail(res, 400, '队伍名称必填');
        return;
      }
      if (!leaderUserIds.length) {
        fail(res, 400, '请选择有效队长');
        return;
      }
      const directWrite = await writeWebSquadDirect(req, 'create', { name, leaderUserIds, body: req.body || {} });
      if (!directWrite) {
        await updateStore((store) => {
          const leaders = leaderUserIds.map((userId) => store.users.find((user) => user.id === userId));
          if (leaders.some((leader) => !leader)) {
            throw Object.assign(new Error('请选择有效队长'), { status: 400 });
          }
          const createdAt = nowIso();
          const squad = {
            id: createId('squad'),
            name,
            leaderUserId: leaderUserIds[0],
            leaderUserIds,
            notes: normalizeText(req.body?.notes, 500),
            createdBy: req.user.id,
            createdAt,
            updatedAt: createdAt,
            archivedAt: ''
          };
          store.squads.unshift(squad);
          leaders.forEach((leader) => ensureAccountMember(store, leader, { ensureSquad: false }));
          appendLog(store, req, 'squad_add', `创建队伍 ${name}`, { targetId: squad.id });
        });
      }
      const payload = await squadListPayloadForViewer(req.user);
      send(res, { squads: payload.squads });
    } catch (error) {
      next(error);
    }
  });

  router.put('/squads/:id', requireAuth, async (req, res, next) => {
    try {
      const directWrite = await writeWebSquadDirect(req, 'edit', { squadId: req.params.id, body: req.body || {} });
      if (!directWrite) {
        await updateStore((store) => {
          const index = store.squads.findIndex((squad) => squad.id === req.params.id && !squad.archivedAt);
          if (index === -1) throw Object.assign(new Error('队伍不存在'), { status: 404 });
          const current = store.squads[index];
          if (!canManageSquadInStore(store, req.user, current)) throw Object.assign(new Error('无权管理该队伍'), { status: 403 });
          const nextFields = {
            name: normalizeText(req.body?.name, 80) || current.name,
            notes: normalizeText(req.body?.notes, 500),
            updatedAt: nowIso()
          };
          let assignedLeaders = [];
          if (canEditModuleInStore(store, req.user, 'squads') && (Object.hasOwn(req.body || {}, 'leaderUserIds') || Object.hasOwn(req.body || {}, 'leaderUserId'))) {
            const leaderUserIds = requestedSquadLeaderIds(req.body);
            if (!leaderUserIds.length) throw Object.assign(new Error('请选择有效队长'), { status: 400 });
            assignedLeaders = leaderUserIds.map((userId) => store.users.find((user) => user.id === userId));
            if (assignedLeaders.some((leader) => !leader)) throw Object.assign(new Error('请选择有效队长'), { status: 400 });
            nextFields.leaderUserId = leaderUserIds[0];
            nextFields.leaderUserIds = leaderUserIds;
          }
          store.squads[index] = { ...current, ...nextFields };
          assignedLeaders.forEach((leader) => ensureAccountMember(store, leader, { ensureSquad: false }));
          appendLog(store, req, 'squad_edit', `编辑队伍 ${store.squads[index].name}`, { targetId: current.id });
        });
      }
      const payload = await squadListPayloadForViewer(req.user);
      send(res, { squads: payload.squads });
    } catch (error) {
      next(error);
    }
  });

