  router.post('/squads/:id/members', requireAuth, async (req, res, next) => {
    try {
      const memberIds = Array.isArray(req.body?.memberIds) ? req.body.memberIds.map((id) => normalizeText(id, 80)).filter(Boolean) : [];
      const directWrite = await writeSquadMembersDirect(req, req.params.id, { action: 'add', memberIds });
      if (!directWrite) {
        await updateStore((store) => {
          const squad = store.squads.find((item) => item.id === req.params.id && !item.archivedAt);
          if (!squad) throw Object.assign(new Error('队伍不存在'), { status: 404 });
          if (!canManageSquadInStore(store, req.user, squad)) throw Object.assign(new Error('无权管理该队伍'), { status: 403 });
          const candidates = new Set(candidateMembersForSquad(store, req.user, squad).map((member) => member.id));
          for (const memberId of memberIds) {
            if (!candidates.has(memberId)) throw Object.assign(new Error('存在无权添加的成员'), { status: 403 });
            store.squadMembers = store.squadMembers.filter((item) => item.memberId !== memberId);
            store.squadMembers.push({
              id: createId('squad_member'),
              squadId: squad.id,
              memberId,
              addedByUserId: req.user.id,
              createdAt: nowIso()
            });
            syncLiveMemberWipeSquadRecords(store, [memberId], squad.id);
          }
          appendLog(store, req, 'squad_member_add', `队伍 ${squad.name} 添加成员 ${memberIds.length} 人`, { targetId: squad.id });
        });
      }
      const payload = await squadMemberPayloadForViewer(req.params.id, req.user, req.body || {});
      if (payload.status !== 200) {
        fail(res, payload.status || 500, payload.error || '队伍成员读取失败');
        return;
      }
      send(res, { squad: payload.squadPayload, members: payload.members });
    } catch (error) {
      next(error);
    }
  });

  router.delete('/squads/:id/members/:memberId', requireAuth, async (req, res, next) => {
    try {
      const directWrite = await writeSquadMembersDirect(req, req.params.id, {
        action: 'remove',
        memberId: req.params.memberId
      });
      if (!directWrite) {
        await updateStore((store) => {
          const squad = store.squads.find((item) => item.id === req.params.id && !item.archivedAt);
          if (!squad) throw Object.assign(new Error('队伍不存在'), { status: 404 });
          if (!canManageSquadInStore(store, req.user, squad)) throw Object.assign(new Error('无权管理该队伍'), { status: 403 });
          const member = (store.members || []).find((item) => item.id === req.params.memberId) || { id: req.params.memberId };
          store.squadMembers = store.squadMembers.filter((item) => !(item.squadId === squad.id && item.memberId === req.params.memberId));
          removeLiveMemberWipeRecords(store, [member]);
          appendLog(store, req, 'squad_member_remove', `队伍 ${squad.name} 移除成员`, { targetId: squad.id });
        });
      }
      const payload = await squadMemberPayloadForViewer(req.params.id, req.user, req.body || {});
      if (payload.status !== 200) {
        fail(res, payload.status || 500, payload.error || '队伍成员读取失败');
        return;
      }
      send(res, { squad: payload.squadPayload, members: payload.members });
    } catch (error) {
      next(error);
    }
  });

